	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_WND_SHOWN )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_WND_HIDED )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_EXIT_UI_FULL_SCREEN )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_SET_RESOLUTION )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_LOADING_SCREEN )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_START_LEVEL )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_END_LEVEL )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_PLAYER_DISCONNECTED )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_MASTER_SERVER_DISCONNECTED_SYNC )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_MASTER_SERVER_CONNECTED )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_RELOAD_RESOURCES )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_HUD_MODE_CHANGED )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_HANGAR_TAB_CHANGED )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_TUTORIAL_STOP )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_OCULUS_ENABLE )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_MSGBOX_RET )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_KB_KEY_DOWN )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_KB_KEY_UP )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_JOY_KEY_DOWN )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_JOY_KEY_UP )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_MOUSE_BUTTON_DOWN )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_MOUSE_BUTTON_UP )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_MOUSE_MOVE )
	self.base:SubscribeUiObjOnEvent( self.OBJ_ID_ROOT_WND, self.EV_MOUSE_WHEEL )

	self:SendUiEvent( UI.EV_GAME_START, UI.INVALID_UI_HANDLE, UI.INVALID_UI_HANDLE, UI.DELIVER_NEXT_FRAME, 0, 0, 0, 0 )

	self:SetDefaultCursor( "cursor_def" )

	self:UpdateDecimalDotString()

end


--
function UI:Shutdown()

	UI.SaleAdvert:OnShutdown()

	if UI.HudEditor then
		UI.HudEditor:Shutdown()
	end

end


--
function UI:Update( dSysTime, dGameTime )

	self.TimersManager:Update( dSysTime, dGameTime )

	if self.frames_afterLoading ~= -1 then
		self.frames_afterLoading = self.frames_afterLoading + 1
		if self.frames_afterLoading == 2 then
			self.frames_afterLoading = -1
		end
	end

	self:UpdateTooltip( dSysTime )

	self:UpdateWaitingRequestsTimer()

	if UI.Tutorial then
		UI.Tutorial:Update( dSysTime, dGameTime )
	end

	self:UpdateAutoHelpTimer( dSysTime )

	self:UpdateFps()

	self.bMouseMove = false

	if UI.SquadFinder then
		UI.SquadFinder:OnNewFrame( dSysTime, dGameTime )
	end

	if UI.RewardSchedule then
		UI.RewardSchedule:OnNewFrame( dSysTime, dGameTime )
	end

	self:CheckUpdateShipsDisabledByTime()

	self:CheckLogoutOnInactivity()

end

--
function UI:UpdateFps()

	local frameTime = _G.TimerGetSysFameTime()
	local curFps = 1 / ( frameTime + 1e-9 )

	self.fps = 9 * self.fps / 10 + curFps / 10

end


--
function UI:GetFps()

	return self.fps

end


--
function UI:UpdateAutoHelpTimer( dt )

	if self.autoHelpTimer == -1 then
		return
	end

	self.autoHelpTimer = self.autoHelpTimer - dt

	if self.autoHelpTimer <= 0 then

		self.autoHelpTimer = -1
		self:CheckAutoShowContextHelp( true )

	end

end


--
function UI:OnMouseMove( mouseX, mouseY, wndIdThatReceivedInput )

	self.tooltipWaitTime = 0
	self.bMouseMove = true

end


--
function UI:OnResetDevice()

	self:RecalcRelAbsCoeffs()

end


--
function UI:OnBeforeReloadResources( resourceTypes, srcGroup, dstGroup )

	self:ResetTooltip()

	if UI.HudEditor then
		UI.HudEditor:OnBeforeReloadResources( resourceTypes, srcGroup, dstGroup )
	end

end


--
function UI:OnAfterReloadResources( resourceTypes, srcGroup, dstGroup )

	if bit.band( resourceTypes, UI.RES_STRING ) == UI.RES_STRING then

		self:UpdateDecimalDotString()

    	for idx, shipItem in pairs( self.serverData.allShips ) do
    		shipItem.localizedName			= UI:GetEntityLocalizedNameByDef( shipItem.defName )
    		shipItem.localizedName_lower	= _G.Utf8CaseFold_Transform( shipItem.localizedName )
    	end

	end

	if UI.HudEditor then
		UI.HudEditor:OnAfterReloadResources( resourceTypes, srcGroup, dstGroup )
	end

end


--
function UI:RecalcRelAbsCoeffs()

	self.screenWidth	= cvars.r_width
	self.screenHeight	= cvars.r_height

    self.abs2Rel_x	= 1024 / self.screenWidth
    self.abs2Rel_y	= 768 / self.screenHeight
    self.rel2Abs_x	= self.screenWidth / 1024
    self.rel2Abs_y	= self.screenHeight / 768

end


-- сохранение игрового состояния
function UI:SaveUiStates()

	self.bSavingGameState = true

	self.base:SaveUiStates()

	self.store.global = {}

	self.store.global.timerId_beforeDeadScreen = self.timerId_beforeDeadScreen
	self.store.global.timerId_afterLoading = self.timerId_afterLoading

	for i = 1, #l_gameObjects do
		local t = self[ l_gameObjects[ i ] ]
		if t then
			t:SaveUiState()
		end
	end

	self.store.global.children = {}
	local child = UI:GetUiObjByHandle( UI.OBJ_ID_ROOT_WND ):GetFirstChild()
	while child do
		table.insert( self.store.global.children, child:GetScriptTableName() )
		child = child:GetNextSibling()
	end

end


-- восстановление игрового состояния
function UI:RestoreUiStates()

	for i = 1, #l_gameObjects do
		local t = self[ l_gameObjects[ i ] ]
		if t then
			t:RestoreUiState()
		end
	end

	self.base:RestoreUiStates()

	if self.store.global then

		self.timerId_beforeDeadScreen = self.store.global.timerId_beforeDeadScreen
		self.timerId_afterLoading = self.store.global.timerId_afterLoading

		for i = 1, #self.store.global.children do
			local w = self:GetTableByName( self.store.global.children[ i ] )
			if w then
				self:ShowWindow( w:GetUiHandle() )
			end
		end
		self.store.global = nil
	end

	self.bSavingGameState = false

	self:UpdateChatVisibility()
	self:UpdateMusicForFullScreenUI()

end


-- Подписка на события engine
function UI:SubscribeOnEngineEvents()

	for eveneName, eventId in pairs( self.engineEvents ) do
		UI.base:SubscribeOnEngineEvent( eventId )
	end

end


-- требуются ли UI события ввода
function UI:NeedInput()

	local hFocus = UI:GetKeyboardFocus()
	return not ( hFocus == UI.INVALID_UI_HANDLE or hFocus == 0 )

end



