end


--
function UI:GetCurLevelName()

	if cvars then
		return UI:GetLevelNameFromPath( cvars.cl_levelName )
	else
		return ""
	end

end


--
function UI:GetLevelNameFromPath( levelPath )

	local rpath = string.reverse( string.lower( levelPath ) )
	local rname = string.match( rpath, "[%w_]*" )
	return rname and string.reverse( rname ) or ""

end



--
function UI:GetLevelRect( levelName )

	if cvars ~= nil then
		return UI:Quat( cvars.ed_levelX0, cvars.ed_levelZ0, cvars.ed_levelSX, cvars.ed_levelSZ )
	else
		return UI:ZeroQuat()
	end

end


--
function UI:PauseGame( bPause )

	if bPause then
		cvars.timer_uiPause = true
	else
		cvars.timer_uiPause = false
	end

end


--
function UI:IsFullScreenWindow( wnd )

	return wnd and wnd.IS_FULL_SCREEN

end


--
function UI:IsFullScreenWindowEx( wnd )

	return wnd and ( wnd.IS_FULL_SCREEN or wnd:GetClassName() == "MsgBoxWnd" )

end


--
function UI:IsInFullScreen()

	return UI.hWndFullScreen ~= UI.INVALID_UI_HANDLE

end


--
function UI:UpdateFullScreenUI()

	local fullScreenWnd = nil

    local child = UI.Root:GetFirstChild()
	while child do

    	if UI:IsFullScreenWindow( child ) or ( UI:IsFullScreenWindowEx( child ) and not UI:IsFullScreenWindow( fullScreenWnd )  ) then
			fullScreenWnd = child
		end

    	child = child:GetNextSibling()

	end

	if fullScreenWnd then
    	UI:EnterFullScreenUI( fullScreenWnd:GetUiHandle() )
	else
    	UI:ExitFullScreenUI()
	end

end


--
function UI:EnterFullScreenUI( hWnd )

	if hWnd == UI.INVALID_UI_HANDLE then
		sys.log( "UI:EnterFullScreenUI()[ERROR]: invalid hWnd" )
		return
	end

	if UI.hWndFullScreen == hWnd then
		return
	end

	self.hWndDelayedExitFullScreen = UI.INVALID_UI_HANDLE

	local bWasInFullScreen = UI.hWndFullScreen ~= UI.INVALID_UI_HANDLE
	UI.hWndFullScreen = hWnd

	-- звуки
	if not bWasInFullScreen and not self.bSavingGameState then
		self.fxVolume		= _G.GetSoundGroupVolume( 0 )
		self.voceiverVolume	= _G.GetSoundGroupVolume( 3 )
	end

    self:UpdateFullScreenUIParams()

end


--
function UI:UpdateFullScreenUIParams()

	if UI.hWndFullScreen == UI.INVALID_UI_HANDLE then
		sys.log( "UI:UpdateFullScreenUIParams()[ERROR]: not in fullscreen mode" )
		return
	end

    self:UpdateMusicForFullScreenUI()
	self:UpdateSoundVolumeForFullScreenUI()
	self:UpdateSpecSoundsForFullScreenUI()
	self:UpdatePauseForFullScreenUI()

end


-- асинхронный вызов
function UI:ExitFullScreenUI()

	if UI.hWndFullScreen == UI.INVALID_UI_HANDLE then
		return
	end

	if self:IsInShutdown() or UI:IsInRemovingAllWindows() then
		return
	end

	-- не скрываю сразу, т.к. я не знаю, последует ли непосредственно за скрытием данного полноэкранного окна
	-- показ другого; поэтому откладываю действие на следующий кадр

	self.hWndDelayedExitFullScreen = self.hWndFullScreen
	self:SendUiEvent( UI.EV_EXIT_UI_FULL_SCREEN, UI.INVALID_UI_HANDLE, self.Root:GetUiHandle(), UI.DELIVER_NEXT_FRAME, 0, 0, 0, 0 )

end


-- собственно действие
function UI:ExitFullScreenUI_2()

	-- скрытие интерфейса может быть отменено другим вызовом показа еще в предыдущем кадре,
	-- поэтому пришедшее сообщение может оказаться неактуальным

	if self.hWndDelayedExitFullScreen == UI.INVALID_UI_HANDLE then
		return
	end

	-- музыка
	sys.concmd( "s_musicPause 0" )
	self.musicTheme = ""

	-- звуки
	sys.concmd( string.format( "s_setGroupVolume 0 %f", self.fxVolume ) )
	sys.concmd( string.format( "s_setGroupVolume 3 %f", self.voceiverVolume ) )

	-- пауза
	UI:PauseGame( false )

	self.hWndDelayedExitFullScreen = UI.INVALID_UI_HANDLE
	UI.hWndFullScreen = UI.INVALID_UI_HANDLE

end


--
function UI:UpdateMusicForFullScreenUI()

	if self.bSavingGameState then
		return
	end

	local musicType, theme = self:GetMusicForWnd( UI.hWndFullScreen )

	if musicType == UI.wndMusicTypes.PLAY then

		if type( theme ) == "string" then

        	if theme ~= self.musicTheme then
            	self.musicTheme = theme
            	sys.concmd( string.format( "s_musicPlay '%s'", theme ) )
    		end

		else
			sys.log( "UI:UpdateMusicForFullScreenUI()[ERROR]: invalid music theme: %s", tostring( theme ) )
		end

	elseif musicType == UI.wndMusicTypes.NONE then
		sys.concmd( "s_musicStop" )
		self.musicTheme = ""

	elseif musicType == UI.wndMusicTypes.DONT_CARE then
		-- nothing

	elseif musicType == UI.wndMusicTypes.PAUSE then
		sys.concmd( "s_musicPause 1" )

	elseif musicType == UI.wndMusicTypes.UNPAUSE then
		sys.concmd( "s_musicPause 0" )

	elseif musicType == UI.wndMusicTypes.PAUSE_GAME then
		sys.concmd( "s_musicPause 1" )
		self.musicTheme = ""

	elseif musicType == UI.wndMusicTypes.UNPAUSE_GAME then
		sys.concmd( "s_musicPause 0" )
		self.musicTheme = ""

	elseif musicType == UI.wndMusicTypes.GAME then
		self.musicTheme = ""

	else
		sys.log( "UI:UpdateMusicForFullScreenUI()[ERROR]: invalid music type: %s", tostring( musicType ) )
	end

-- sys.log( "^5type %s  theme %s", UI:Val2Key( UI.wndMusicTypes, musicType ), tostring( theme ) )

end


--
function UI:GetMusicForWnd( hWnd )

	if UI.LoginWnd and UI.LoginWnd:IsOnScreen() then
		return UI.wndMusicTypes.PLAY, "MainTheme"

	elseif _G.GetCurrentGameMode and _G.GetCurrentGameMode() ~= 0 then

		if UI:IsMenuWindowsOnScreen() then
			return UI.wndMusicTypes.PAUSE_GAME
		else
			return UI.wndMusicTypes.UNPAUSE_GAME
		end

	elseif ( UI.DebriefingWnd and UI.DebriefingWnd:IsOnScreen() ) or ( UI.HangarWnd and UI.HangarWnd:IsOnScreen() and UI.HangarWnd:NeedShowDebriefing() ) then
		return UI.wndMusicTypes.GAME

	elseif UI:IsValidMainMenuLevelName( UI:GetCurLevelName() ) then

		local hangarRace = UI:GetCurSpaceStationRace()

		local theme = UI.defaultMusicTheme

		if hangarRace == ai.Race.EMPIRE then
			theme = "EmpHangar"
		elseif hangarRace == ai.Race.FEDERATION then
			theme = "FedHangar"
		elseif hangarRace == ai.Race.JERICHO then
			theme = "JerHangar"
		elseif hangarRace == ai.Race.CRYSTAL then
			theme = "ElHangar"
		else
			sys.log( "UI:GetMusicForWnd()[ERROR]: unhandled race %d", hangarRace )
		end

		return UI.wndMusicTypes.PLAY, theme

	else
		return UI.wndMusicTypes.DONT_CARE
	end

end


--
function UI:UpdateSoundVolumeForFullScreenUI()

	if self.bSavingGameState then
		return
	end

	local needFxVolume, needVoiceoverVolume = self:GetSoundVolumeForWnd( UI.hWndFullScreen )

	if needFxVolume == -1 then
		needFxVolume = self.fxVolume
	end

	if needVoiceoverVolume == -1 then
		needVoiceoverVolume = self.voceiverVolume
	end

	sys.concmd( string.format( "s_setGroupVolume 0 %f", needFxVolume ) )
	sys.concmd( string.format( "s_setGroupVolume 3 %f", needVoiceoverVolume ) )

end


--
function UI:GetSoundVolumeForWnd( hWnd )

	if _G.GetCurrentGameMode and _G.GetCurrentGameMode() ~= 0 then

		if UI:IsMenuWindowsOnScreen() then
			return 0, 0

		elseif UI.HudWnd and UI.HudWnd:IsOnScreen() and UI.HudWnd:NeedMuteFxSounds() then
			return 0, -1

		elseif UI.HelpWnd and UI.HelpWnd:IsOnScreen() then
			return 0, -1

		else
			return -1, -1
		end

	elseif UI.LoginWnd and UI.LoginWnd:IsOnScreen() then
		return 0, 0

	elseif UI:IsLoadingWndOnScreen() then
		return 0, 0

	elseif UI.DebriefingWnd:IsOnScreen() then
		return 0, 0

	else
		return -1, -1
	end

end


--
function UI:UpdateSpecSoundsForFullScreenUI()

	if self:NeedPlayTacticalViewSound() then
		UI:PlayGlobalSound( self.tacticalViewSoundName, true, false )
	else
		UI:StopGlobalSound( self.tacticalViewSoundName )
	end

end


--
function UI:NeedPlayTacticalViewSound()

	if not UI.HudWnd or not UI.HudWnd:IsOnScreen() then
		return false
	end

	if UI:IsMenuWindowsOnScreen() then
		return false
	end

	-- #45759
	if UI.GameplayPveMapHudContainerWnd and UI.GameplayPveMapHudContainerWnd:IsOnScreen() then
		return false
	end

	if UI.HelpWnd and UI.HelpWnd:IsOnScreen() then
		return false
	end

	local hudMode = UI.HudWnd:GetMode()
	return UI.HudWnd:IsWorldLookMode( hudMode )

end


--
function UI:UpdatePauseForFullScreenUI()

	local bNeedPause = self:GetPauseForWnd( UI.hWndFullScreen )
	UI:PauseGame( bNeedPause )

end


--
function UI:GetPauseForWnd( hWnd )

	if UI.Tutorial and UI.Tutorial:IsActive() then
		if _G.GetCurrentGameMode and _G.GetCurrentGameMode() ~= 0 then
			if UI:IsMenuWindowsOnScreen() or ( UI.HelpWnd and UI.HelpWnd:IsOnScreen() ) or ( UI.QuestInfoWnd and UI.QuestInfoWnd:IsOnScreen() ) then
				return true
			end
		end
	end

	return false

end


--
function UI:IsMenuWindowsOnScreen()

	if UI.MenuWnd and UI.MenuWnd:IsOnScreen() then
		return true
	end

	if UI.OptionsWnd and UI.OptionsWnd:IsOnScreen() then
		return true
	end

	return false

end


--
function UI:HideAllWindows()

	self:ResetTooltip()

	if self.hErrorMsg == self.INVALID_UI_HANDLE then
		self.base:HideAllWindows()
	else
		local w = self.Root:GetFirstChild()
		while w do
			local next_w = w:GetNextSibling()
			if w:GetUiHandle() ~= self.hErrorMsg then
				w:UnlinkFromParent()
			end
			w = next_w
		end
	end

end


--
function UI:SetKeyboardFocus( hWnd )

	if self.hErrorMsg ~= self.INVALID_UI_HANDLE and hWnd ~= self.hErrorMsg then
		return
	end

	self.base:SetKeyboardFocus( hWnd )

end



