--
function UI:OnDlcLoad( resourcListPath, dlcLoadGroupName )

	if type( resourcListPath ) ~= "string" then
		sys.log( "UI:OnDlcLoad()[ERROR]: invalid type of the 1-st parameter (resourcListPath); \"string\" expected, got \"%s\"", type( resourcListPath ) )
		return
	end

	if type( dlcLoadGroupName ) ~= "string" then
		sys.log( "UI:OnDlcLoad()[ERROR]: invalid type of the 1-st parameter (dlcLoadGroupName); \"string\" expected, got \"%s\"", type( dlcLoadGroupName ) )
		return
	end

	self:LoadResourceList( resourcListPath )

	self:LoadResourcesByGroup( dlcLoadGroupName )

	local curLanguage = self:GetLanguage()
	self:ReloadResources( UI.RES_STRING + UI.RES_TEXTURE, curLanguage, curLanguage )

end


-- инициализирует и показывет окно меню
function UI:ShowMenuInternal( level, stack, selItem, bPlayStartAnim )

	local wnd = self:GetMenuWndForStack( level, stack )

	if level ~= nil or stack ~= nil then
		wnd:SetLevel( level, stack )
	end

	wnd:Show( bPlayStartAnim )

	if selItem ~= nil then
		wnd:SelectItem( selItem )
	end

end


-- в данном проекте - заглушка, т.к. окно меню только одно
function UI:GetMenuWndForStack( level, stack )

	return UI.MenuWnd

end


--
function UI:ShowMainMenuForce()

	self:HideAllWindows()
	UI:ShowMenuInternal( "main", {}, nil, false )

end


-- инициализирует и показывает не только собственно окно меню, но любое полноэкранное (по преимуществу) окно,
-- которое указано в структуре menuState

function UI:ShowMenuEx( menuState )

	if not menuState then
		sys.log( "UI:ShowMenuEx()[ERROR]: nil parameter" )
		return
	end

	if menuState.bMenu then

		if not menuState.level then
			menuState.level = "main"
			menuState.stack = {}
		end

		local menuWnd = self:GetMenuWndForStack( menuState.level, menuState.stack )

    	menuWnd:SetLevel( menuState.level, menuState.stack )
       	menuWnd:Show( true )

    	if menuState.selItem then
    	   	menuWnd:SelectItem( menuState.selItem )
    	end

	else

		sys.log( "UI:ShowMenuEx()[ERROR]: invalid structure menuState" )

		local level = "main"
		local stack = {}

		local menuWnd = self:GetMenuWndForStack( level, stack )

    	menuWnd:SetLevel( level, stack )
       	menuWnd:Show( true )

	end

end


-- собирает информацию о текущей игре, чтобы после загрузки уровня mainmenu был показан правильный интерфейс

function UI:PrepareUIForMainMenuLevel()

	self.suspendedMenuState = {}
	local state = self.suspendedMenuState
	self:ResetMenuStateStruct( state )


	-- TODO: восстановить функционал

end


-- вызывается при загрузке уровня mainmenu; показывает подходящий случаю интерфейс
function UI:ShowUIForMainMenuLevel()

	if _G.MasterServer_IsConnected() then

		if not UI.AntechamberWnd:IsOnScreen() then
    		self:HideAllWindows()
    		UI.AntechamberWnd:Show()
		end

	else

		if not UI.LoginWnd:IsOnScreen() then
			self:HideAllWindows()
			UI.LoginWnd:Show()
		end

	end

	-- показ отложенных месседжбоксов о дисконнекте

	if self.playerDisconnectReason ~= -1 then

		if self.playerDisconnectReason ~= _G.network.DisconnectReason.CLIENT_QUIT and self.playerDisconnectReason ~= _G.network.DisconnectReason.CLIENT_GAME_FINISHED then
			self:ShowMsgOnMpConnectionLost( self.playerDisconnectReason, false )
		end

		self.playerDisconnectReason = -1

	end

	if self.masterServerDisconnectReason ~= -1 then
		self:ShowMsgOnMasterServerConnectionLost( self.masterServerDisconnectReason, false )
		self.masterServerDisconnectReason = -1
	end


--[[ из других проектов
	if not self.suspendedMenuState then
		self.suspendedMenuState = {}
		self:ResetMenuStateStruct( self.suspendedMenuState )

		self.suspendedMenuState.bMenu	= true
		self.suspendedMenuState.level	= "main"
		self.suspendedMenuState.stack	= {}
	end

	self:ShowMenuEx( self.suspendedMenuState )
]]

	self.suspendedMenuState = nil

end


