-- загружает уровень mainmenu;
-- перед этим собирает информацию о текущей игре, чтобы после загрузки уровня mainmenu был показан правильный интерфейс;
-- если уровень mainmenu уже был загружен, то показывает интерфейс для него

local l_bInLoadMainMenuLevel = false

function UI:LoadMainMenuLevel( bNotPrepareUi, quitResult )

	if bNotPrepareUi == nil then
		bNotPrepareUi = false
	end

	if bReconnectEnable == nil then
		bReconnectEnable = false
	end

	if l_bInLoadMainMenuLevel then
		return
	end

	l_bInLoadMainMenuLevel = true

	if not bNotPrepareUi then
		self:PrepareUIForMainMenuLevel()
	end

	if network.isMultiplayer then

		if network.isServer then
			_G.MpServerClose()

		elseif network.isClient then

			-- если передать nil в качестве параметра, то будет скриптовая ошибка...
			if quitResult then
				_G.MpClientDisconnect( quitResult )
			else
				_G.MpClientDisconnect()
			end

		end

	end

	local rightMainMenuLevelName = UI:GetRightMainMenuLevelName()
	if UI:GetCurLevelName() ~= rightMainMenuLevelName then
		sys.concmd( "map " .. rightMainMenuLevelName )
	else
		UI:ShowUIForMainMenuLevel()
	end

	l_bInLoadMainMenuLevel = false

end


