--
function UI:ShowMsgOnMpConnectionLost( reason, bPause )

	if bPause == nil then
		bPause = true
	end

	local reasonName = UI:Val2Key( network.DisconnectReason, reason )

	if reasonName == "" then
		sys.log( "ShowMsgOnMpConnectionLost()[ERROR]: unknown reason for mp connection lost: \"%s\"", tostring( reason ) )
	end

	local msg = UI:GetStringByName( "msg_connectLost" )
	local reasonStr = UI:GetStringByName( string.format( "connectLostReason_%s", reasonName ) )
	msg = string.format( msg, reasonStr )

	if bPause then
		self:PauseGame( true )
	end

	return self:MessageBox( "", msg, UI.MBS_OK )

end


--
function UI:ShowMsgOnMasterServerConnectionLost( reason, bPause )

	if bPause == nil then
		bPause = true
	end

	local reasonName = UI:Val2Key( _G.network.MasterServerDisconnectReason, reason )

	if reasonName == "" then
		sys.log( "ShowMsgOnMasterServerConnectionLost()[ERROR]: unknown reason for mp connection lost: \"%s\"", tostring( reason ) )
	end

	local captionStr = ""
	local msgStr = UI:GetStringByName( "msg_masterServerDisconnect" )

	local bShowMsg = true

	if reason == _G.network.MasterServerDisconnectReason.DR_BANNED then

		local banReason = _G.MasterServer_GetBanCategory()
		local banReasonName = UI:Val2Key( _G.MasterServer.AbuseCategory, banReason )

		local reasonStr = UI:GetStringByName( string.format( "disconnectReason_%s_%s", reasonName, banReasonName ) )
		msgStr = string.format( msgStr, reasonStr )

		local time = _G.MasterServer_GetBanTimeLeft()

		local strTime = UI:Time2Str41( time )
		local strBanTimeLeft = UI:GetStringByName( "banTimeLeft" )
		strBanTimeLeft = string.format( strBanTimeLeft, strTime )

		local strLink = UI:GetStringByName( "msgBanLink" )

		msgStr = string.format( "%s|%s|%s", msgStr, strBanTimeLeft, strLink )

		captionStr = UI:GetStringByName( "msgCapt_masterServerConnectionLost" )

	elseif reason == _G.network.MasterServerDisconnectReason.DR_INVALID_LOGIN then

		local reasonStr = UI:GetStringByName( string.format( "disconnectReason_%s", reasonName ) )
		msgStr = string.format( msgStr, reasonStr )

		captionStr = UI:GetStringByName( "msgCapt_masterServerConnectionLost_DR_INVALID_LOGIN" )

	elseif reason == _G.network.MasterServerDisconnectReason.DR_CLIENT_QUIT then

		if self.bNeedShowMsgOnInactivity then

    		local reasonStr = UI:GetStringByName( "disconnectReason_logoutOnInactivity" )
    		msgStr = string.format( msgStr, reasonStr )

    		captionStr = UI:GetStringByName( "msgCapt_masterServerConnectionLost" )

		else
			bShowMsg = false
		end

	else

		local reasonStr = UI:GetStringByName( string.format( "disconnectReason_%s", reasonName ) )
		msgStr = string.format( msgStr, reasonStr )

		captionStr = UI:GetStringByName( "msgCapt_masterServerConnectionLost" )

	end

	self.bNeedShowMsgOnInactivity = false

	if bShowMsg then

    	if bPause then
    		self:PauseGame( true )
    	end

    	return self:MessageBox( captionStr, msgStr, UI.MBS_OK )

	else
		return UI.INVALID_UI_HANDLE
	end

end


--
function UI:IsEntityOfClass( ent, className )

	if not ent or not className then
		return false
	end

	local defName = ent:GetDefName()
	return _G.IsKindOf( defName, className )

end


--
function UI:IsEntityOfClassById( entId, className )

	if not entId or not className then
		return false
	end

	local ent = _G.Entities[ entId ]
	return UI:IsEntityOfClass( ent, className )

end


--
function UI:GetEntityLocalizedName( ent, bWithColor, bShowTier )

	if not ent then
		sys.log( "UI:GetEntityLocalizedName()[ERROR]: nil ent" )
		return "unknown"
	end

	local defName = ent:GetDefName()
	return self:GetEntityLocalizedNameByDef( defName, bWithColor, false, bShowTier )

end


--
function UI:GetEntityLocalizedNameByDef( defName, bWithColor, bSelColor, bShowRank, bShowObsolete, bAltColor, autogenUpgradeLevel )

	if bWithColor == nil then
		bWithColor = false
	end

	-- #0059898, комм.(0242519) - вернули отображение ранга там, где раньше был тир
	if bShowRank == nil then
		bShowRank = true
	end

	if bShowObsolete == nil then
		bShowObsolete = true
	end

	if autogenUpgradeLevel == nil then
		autogenUpgradeLevel = -1
	end

	if UI:IsStrEmpty( defName ) then
		sys.log( "UI:GetEntityLocalizedNameByDef()[ERROR]: empty defName" )
		return "unknown"
	end

	local str = defName

	if not UI.showDefNames then

    	local def = UI:GetDef( defName, true, autogenUpgradeLevel )
    	if def then

        	-- имена кораблей НЕ формируются, а берутся как есть

        	if UI:IsDefShip( defName ) then

    			if def.ship_name then

    				local strId = string.format( "%s_name", def.ship_name )
    				str = UI:GetStringByName( strId )

    			else
    				sys.log( "UI:GetEntityLocalizedNameByDef()[ERROR]: cannot find _G.Def[%s].ship_name", defName )
    			end

    		-- #0027175
        	elseif UI:IsDefJunk( defName ) then

    			local strId = string.format( "%s_name", defName )
    			str = UI:GetStringByName( strId )

        	elseif UI:IsDefTokenItem( defName ) then

    			str = UI:TokenItem2Str( defName )

    		elseif UI:IsDefModule( defName ) or UI:IsDefAmmo( defName ) then

				if UI:IsDefAutogen( defName ) then

					local autogenItem = UI:GetAutogenItem( defName )
					if autogenItem then
						str = UI:Autogen2StrInternal( defName, def, autogenItem.rollData )
					else
						sys.log( "UI:GetEntityLocalizedNameByDef()[ERROR]: cannot find autogenItem for %s", defName )
					end

				else
					str = UI:Module2StrInternal( defName, def )
				end

				if bShowRank then
					str = UI:AddRankToItemName( str, defName, def )
				end

				if bShowObsolete then
					str = UI:AddObsoleteToItemName( str, defName, def )
				end

    		elseif UI:IsDefAvatar( defName ) then

    			str = UI:GetAvatarName( defName )

    		-- no name for motto
    		elseif UI:IsDefMotto( defName ) then

    			str = ""

			elseif UI:IsDefResource( defName ) then

				-- #0036680, комм.(0133824)
				if not UI:IsStrEmpty( def.uiName ) then
					str = UI:GetStringByName( def.uiName )
				else
					sys.log( "UI:GetEntityLocalizedNameByDef()[ERROR]: cannot find _G.Def[%s].uiName", defName )
				end

			elseif UI:IsDefBlueprint( defName ) then

				local craftResultDefName = UI:GetResourceCraftResult( defName )

				local craftResultLocalizedName = UI:GetEntityLocalizedNameByDef( craftResultDefName, bWithColor, bSelColor, bShowRank, bShowObsolete, bAltColor )

				if bWithColor then
					local mainColor = UI:GetItemColor( defName, bSelColor, bAltColor )
					craftResultLocalizedName = string.format( "%s%s", craftResultLocalizedName, UI:Color2Str( mainColor ) )
				end

				str = UI:GetStringByName( "blueprintNamePattern" )

				local numSubst = 0
				str, numSubst = string.gsub( str, "%$craft_result_name%$", craftResultLocalizedName )

				if numSubst == 0 then
					sys.log( "UI:GetEntityLocalizedNameByDef()[ERROR]: cannot find placeholder \"$craft_result_name$\" in string \"blueprintNamePattern\"" )
					str = string.format( "[INVALID STRING] Blueprint for %s", craftResultLocalizedName )
				end

    		else

            	-- имя

            	local strName = defName

            	if def.uiName then
            		strName = UI:GetStringByName( def.uiName )
            	else
            		sys.log( "UI:GetEntityLocalizedNameByDef()[ERROR]: cannot find _G.Def[%s].uiName", defName )
            	end

            	-- тир или ранг (может не быть)

            	local strRank = ""

    			if bShowRank then
					strRank = UI:AddRankToItemName( strRank, defName, def )
    			end

            	local bRank = strRank ~= ""


            	-- марк (только суффикс, т.к. префикс входит в имя) (может не быть)

            	local strMark = ""

    			-- #0033904: Mk1 сейчас не пишется
            	if def.mark and def.mark ~= 1 then

            		local bMarkPrefixed = _G.ItemMarks and _G.ItemMarks[ def.mark ] and _G.ItemMarks[ def.mark ].prefix == true
            		if not bMarkPrefixed then

                		strMark = self.strItemMarks[ def.mark ]
                		if not strMark then
                			strMark = UI:GetStringByName( string.format( "mark_%s", def.mark ) )
                			self.strItemMarks[ def.mark ] = strMark		-- кешируется, в целях оптимизации
                		end

            		end

            	end

            	local bMark  = strMark ~= ""

            	str = string.format( "%s%s%s%s%s",
            		strName,
            		bRank and " " or "",
            		bRank and strRank or "",
            		bMark and " " or "",
            		bMark and strMark or "" )
    		end

    	else
    		sys.log( "UI:GetEntityLocalizedNameByDef()[ERROR]: cannot find def \"%s\"", defName )
    		str = defName
    	end

	end

	if bWithColor then
		local color = UI:GetItemColor( defName, bSelColor, bAltColor )
		local strColor = UI:Color2Str( color )
		str = string.format( "%s%s", strColor, str )
	end

	return str

end


--
function UI:GetEntityDescByDef( defName )

	if UI:IsStrEmpty( defName ) then
		sys.log( "UI:GetEntityDescByDef()[ERROR]: empty def" )
		return ""
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetEntityDescByDef()[ERROR]: cannot find def %s", defName )
		return defName
	end

	-- #0027175
	if UI:IsDefJunk( defName ) then
		local strId = string.format( "%s_desc", defName )
		return UI:GetStringByName( strId )

	elseif UI:IsDefTokenItem( defName ) then

		return UI:GetTokenItemDesc( defName )

	elseif UI:IsDefAmmo( defName ) or UI:IsDefModule( defName ) then

		if not UI:IsStrEmpty( def.uiDesc ) then
			return UI:GetStringByName( def.uiDesc )

		else
    		local subType = UI:GetItemSubType( defName )
    		if subType ~= -1 then
    			local itemSubTypeName = UI:Val2Key( _G.ItemSubtype, subType )
    			local strId = string.format( "itemSubType_%s_desc", itemSubTypeName )
    			return UI:GetStringByName( strId )
    		else
    			sys.log( "UI:GetEntityDescByDef()[ERROR]: cannot find item sub type for \"%s\"", defName )
    			return ""
    		end
		end

	elseif UI:IsDefBundle( defName ) then

		return UI:GetBundleDesc( defName )

	elseif def.uiDesc then

		return UI:GetStringByName( def.uiDesc )

	else

		sys.log( "UI:GetEntityDescByDef()[ERROR]: cannot find _G.Def[%s].uiDesc", defName )
		return ""

	end

end


--
function UI:GetItemDescEx( srcInfo, compareInfo, substColor, baseColor, bAutogenAffixIcons )

	local desc = ""

	if type( srcInfo ) ~= "table" then
		sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of the 1-st parameter (\"srcInfo\"); \"table\" expected, got \"%s\"", type( srcInfo ) )
		return desc
	end

	if type( srcInfo.defName ) ~= "string" then
		sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of the srcInfo.defName; \"string\" expected, got \"%s\"", type( srcInfo.defName ) )
		return desc
	end

	if substColor ~= nil then
    	if type( substColor ) ~= "number" then
			sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of the 3-rd parameter (\"substColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( substColor ) )
			substColor = nil
    	end
	end

	if substColor == nil then
		baseColor = UI.TEXT_SEL_COLOR
	end

	if baseColor ~= nil then
    	if type( baseColor ) ~= "number" then
			sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of the 4-th parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
    	end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if bAutogenAffixIcons ~= nil then
		if type( bAutogenAffixIcons ) ~= "boolean" then
			sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of the 5-th parameter (\"bAutogenAffixIcons\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bAutogenAffixIcons ) )
			bAutogenAffixIcons = nil
		end
	end

	if bAutogenAffixIcons == nil then
		bAutogenAffixIcons = false
	end

	srcInfo.dataType = UI.paramSrcTypes.MODULE

	if compareInfo then
		compareInfo.dataType = UI.paramSrcTypes.MODULE
	end

	if UI:IsDefAutogen( srcInfo.defName ) then

		local rollData = nil
		local upgradeLevel = -1

		if srcInfo.data and srcInfo.data.autogen and srcInfo.data.autogen.upgradeLevel and srcInfo.data.autogen.upgradeLevel ~= -1 then

			rollData = srcInfo.data.autogen.rollData
			upgradeLevel = srcInfo.data.autogen.upgradeLevel

		else

			local autogenItem = UI:GetAutogenItem( srcInfo.defName )
			if not autogenItem or not next( autogenItem ) then
				sys.log( "UI:GetItemDescEx()[ERROR]: fail to get autogenItem for '%s'", srcInfo.defName )
				return desc
			end

			rollData = autogenItem.rollData
			upgradeLevel = autogenItem.upgradeLevel
		end

		local decomposition = _G.DecompositeAutogenRollData( rollData )
		if not decomposition or not next( decomposition ) then
			sys.log( "UI:GetItemDescEx()[ERROR]: fail to decomposite rollData for '%s'", srcInfo.defName )
			return desc
		end

		if not srcInfo.data then
			srcInfo.data = {}
		end
		if not srcInfo.data.autogen then
			srcInfo.data.autogen = {}
		end

		srcInfo.data.autogen.affixesGeneratedData = _G.GameStore_GetAutogenGeneratedValsByAffix( rollData, upgradeLevel )
		srcInfo.data.autogen.decomposition = decomposition

		if decomposition.affixes then

			for affixIdx, affixData in ipairs( decomposition.affixes ) do

				local affixName, affixGroupId = UI:GetAutogenAffixNameAndGroup( affixData.affixId )
				local affixGroupName = UI:Val2Key( _G.AutogenAffixGroup, affixGroupId )

				local affixDescStrId = string.format( "autogen_%s_%s_desc", affixGroupName, affixName )
				local affixDesc = UI:GetStringByName( affixDescStrId )

				local affixDescriptionParams = UI:GetAutogenAffixDescParams( affixData.affixId )
				affixDesc = UI:FillDescWithParams( srcInfo, nil--[[не сравнивается]], affixDesc, affixDescriptionParams, substColor, baseColor, true, nil, nil, affixIdx )

				if bAutogenAffixIcons then
					local texName = string.format( "autogenAffix_%s", affixGroupName )
					local icoMetaString = string.format( "$texture [texName %s][ignoreFontSize true]$", texName )
					affixDesc = " "..icoMetaString.." "..affixDesc
				end

				if affixDesc ~= "" then
					desc = string.format( "%s%s%s", desc, desc ~= "" and "|" or "", affixDesc )
				end

			end

		end

	else

		desc = UI:GetEntityDescByDef( srcInfo.defName )
		if desc == "" then
			return desc
		end

		local descriptionParams = UI:GetItemDescParams( srcInfo.defName )
		desc = UI:FillDescWithParams( srcInfo, compareInfo, desc, descriptionParams, substColor, baseColor, true )

	end

	if srcInfo.data ~= nil then
		if type( srcInfo.data ) == "table" then

			if srcInfo.data.params ~= nil then
				if type( srcInfo.data.params ) == "table" then

					-- если установлено несколько пассивных модулей одного субтайпа, то у них снижаются характеристики;
					-- в этом случае пишется предупреждение

					if srcInfo.data.params.diminishingIdx ~= nil then
						if type( srcInfo.data.params.diminishingIdx ) == "number" then

							if srcInfo.data.params.diminishingIdx > 1 then

								local bCanShowDiminishingString = true

								local def = UI:GetDef( srcInfo.defName )
								if def then

									if def.hide_diminishing_string ~= nil then

										if type( def.hide_diminishing_string ) == "boolean" then

											if def.hide_diminishing_string then
												bCanShowDiminishingString = false
											end

										else
											sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of _G.Def[\"%s\"].hide_diminishing_string; \"boolean\" or \"nil\" expected, got \"%s\"", srcInfo.defName, type( def.hide_diminishing_string ) )
										end

									end

								else
									sys.log( "UI:GetItemDescEx()[ERROR]: cannot find def for %s", srcInfo.defName )
								end

								if bCanShowDiminishingString then

    								local diminishingCf = nil

    								if type( _G.PassiveModuleDiminishing ) == "table" then

    									diminishingCf = _G.PassiveModuleDiminishing[ srcInfo.data.params.diminishingIdx ]

    									if type( diminishingCf ) ~= "number" then
    										sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of _G.PassiveModuleDiminishing[%d]; \"number\" expected, got \"%s\"", srcInfo.data.params.diminishingIdx, type( diminishingCf ) )
    										diminishingCf = nil
    									end

    								else
    									sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of _G.PassiveModuleDiminishing; \"table\" expected, got \"%s\"", type( _G.PassiveModuleDiminishing ) )
    								end

    								local strBaseColor			= UI:Color2Str( baseColor )
    								local strSelColor			= UI:Color2Str( substColor )
									local strDiminishingColor	= UI:Color2Str( UI.PARAM_DELTA_MINUS_COLOR )

    								local strNumModules = tostring( srcInfo.data.params.diminishingIdx )
    								strNumModules = string.format( "%s%s%s", strSelColor, strNumModules, strDiminishingColor )

    								local strDiminishingVal = "unknown"

    								if diminishingCf then
    									local diminishingVal = math.floor( diminishingCf * 100 )
    									strDiminishingVal = string.format( "%d%%", diminishingVal )
    								end

    								strDiminishingVal = string.format( "%s%s%s", strSelColor, strDiminishingVal, strDiminishingColor )

    								local strDiminishingLabel = UI:GetStringByName( "passiveModuleDiminishing" )

    								local tSubst =
    								{
    									num_modules	= strNumModules,
    									val			= strDiminishingVal,
    								}

    								local numSubst = 0
    								strDiminishingLabel, numSubst = string.gsub( strDiminishingLabel, "%$(.-)%$", tSubst )

    								if numSubst < 2 then
    									sys.log( "UI:GetItemDescEx()[ERROR]: invalid placeholders in string \"passiveModuleDiminishing\"; expected \"$num_modules$\" and \"$val$\"" )
    									strDiminishingLabel = string.format( "[INVALID_STRING] Num identical modules is %s; efficiency is %s", strNumModules, strDiminishingVal )
    								end

									strDiminishingLabel = string.format( "%s%s%s", strDiminishingColor, strDiminishingLabel, strBaseColor )

    								desc = string.format( "%s||%s", desc, strDiminishingLabel )

								end

							end

						else
							sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of srcInfo.data.params.diminishingIdx; \"number\" or \"nil\" expected, got \"%s\"", type( srcInfo.data.params.diminishingIdx ) )
						end
					end

					-- если установлен несовместимый модуль, то он отключается;
					-- в этом случае пишется предупреждение

					if srcInfo.data.params.weapon_compatibility ~= nil then
						if type( srcInfo.data.params.weapon_compatibility ) == "boolean" then

							if not srcInfo.data.params.weapon_compatibility then

								local bCanShowIncompatibilityString = true

								local def = UI:GetDef( srcInfo.defName )
								if def then

									if def.hide_incompatibility_string ~= nil then

										if type( def.hide_incompatibility_string ) == "boolean" then

											if def.hide_incompatibility_string then
												bCanShowIncompatibilityString = false
											end

										else
											sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of _G.Def[\"%s\"].hide_incompatibility_string; \"boolean\" or \"nil\" expected, got \"%s\"", srcInfo.defName, type( def.hide_incompatibility_string ) )
										end

									end

								else
									sys.log( "UI:GetItemDescEx()[ERROR]: cannot find def for %s", srcInfo.defName )
								end

								if bCanShowIncompatibilityString then

    								local strBaseColor				= UI:Color2Str( baseColor )
									local strIncompatibilityColor	= UI:Color2Str( UI.PARAM_DELTA_MINUS_COLOR )

    								local strIncompatibilityLabel	= UI:GetStringByName( "moduleIncompatibility" )

									strIncompatibilityLabel			= string.format( "%s%s%s", strIncompatibilityColor, strIncompatibilityLabel, strBaseColor )

    								desc = string.format( "%s||%s", desc, strIncompatibilityLabel )

								end

							end

						else
							sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of srcInfo.data.params.weapon_compatibility; \"number\" or \"nil\" expected, got \"%s\"", type( srcInfo.data.params.weapon_compatibility ) )
						end
					end

				else
					sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of srcInfo.data.params; \"table\" or \"nil\" expected, got \"%s\"", type( srcInfo.data.params ) )
				end
			end

		else
			sys.log( "UI:GetItemDescEx()[ERROR]: invalid type of srcInfo.data; \"table\" or \"nil\" expected, got \"%s\"", type( srcInfo.data ) )
		end
	end

	return desc

end


--
function UI:GetShipDescSimple( defName )

	if UI:IsStrEmpty( defName ) then
		sys.log( "UI:GetShipDescSimple2()[ERROR]: empty def" )
		return ""
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetShipDescSimple2()[ERROR]: cannot find def %s", defName )
		return ""
	end

	if not def.ship_name then
		sys.log( "UI:GetShipDescSimple2()[ERROR]: cannot find _G.Def[%s].ship_name", defName )
		return ""
	end

	local strId = string.format( "%s_desc_lore", def.ship_name )
--[[ #0031105 cosmosim
	-- если строки нет, то это считается нормальным, в лог ругаться не нужно
	local strHandle = UI:GetResourceHandleByName( strId, UI.RES_STRING, true )
	if strHandle == UI.INVALID_RESOURCE_HANDLE then
		return ""
	end

	local strRc = UI:GetResourceByHandle( strHandle )
	return strRc:GetStr()
]]
	-- #0031105 cosmosim
	do
		return UI:GetStringByName( strId, false ) or ""
	end

end


--
function UI:GetShipDescEx( srcInfo, substColor, baseColor, craftedBonuses )

	srcInfo.dataType = UI.paramSrcTypes.SHIP

	local defName = srcInfo and srcInfo.defName or ""
	local shipSynergyLevel = srcInfo.synergyLevel or 0

	local shipAdditionalDesc = UI:GetShipAdditionalDesc( defName )

	local desc = shipAdditionalDesc

	local paramsData = UI:GetShipDescParamsEx( srcInfo, craftedBonuses )
	for paramIdx, paramData in ipairs( paramsData ) do

		local partDesc = UI:ShipDescParam2Str( paramData, baseColor, substColor, defName, shipSynergyLevel, true )
		desc = string.format( "%s%s%s", desc, desc ~= "" and "|" or "", partDesc )

	end

	return desc

end


--
function UI:ShipDescParam2Str( paramData, baseColor, substColor, defName, shipSynergyLevel, bShowLockState )

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if substColor == nil then
		substColor = UI.TEXT_SEL_COLOR
	end

	local strSubstColor		= UI:Color2Str( substColor )
	local strBaseColor		= UI:Color2Str( baseColor )
	local strLockColor		= UI:Color2Str( UI.LOCK_COLOR )
	local strPartDescColor	= strBaseColor

	local fnItemGroupSubst = function( capture )

		local strSubst = nil

		local itemGroupName = string.match( capture, "^itemGroup_(.-)$" )
		if itemGroupName then

			local itemGroup = ai.ItemGroup[ itemGroupName ]
			if itemGroup then
				strSubst = UI:ItemGroup2Str( itemGroup )
			else
				sys.log( "UI:ShipDescParam2Str()[ERROR]: invalid item group: \"%s\" for ship %s", itemGroupName, defName )
			end

		end

		if strSubst then
			strSubst = string.format( "%s%s%s", strSubstColor, strSubst, strPartDescColor )
		end

		return strSubst

	end

	local synergyLevel		= paramData.synergyLevel or -1

	local bMinus = false

	if not paramData.bUndefined then

    	local numVals = #paramData.vals
    	if numVals == 1 then

    		local val = paramData.vals[ 1 ]
    		if val < 0 then

    			bMinus = true

    			-- т.к. GetParamVals() вызывалась с bForceAbs=false, а рисовать надо положительное число
    			paramData.vals[ 1 ] = -val

    		end

    	elseif numVals == 0 then
    		sys.log( "UI:ShipDescParam2Str()[ERROR]: no vals for param \"%s\" ship \"%s\"", paramData.paramInfo.name, defName )

    	else
    		sys.log( "UI:ShipDescParam2Str()[ERROR]: multiple vals for param \"%s\" ship \"%s\"", paramData.paramInfo.name, defName )
    	end

	end

	local partDesc = ""

	if paramData.bUndefined then
		partDesc = UI:GetStringByName( "shipBonusUndefined" )

	else

		local partDescId = bMinus and string.format( "ship_desc_negative_%s", paramData.paramInfo.name ) or string.format( "ship_desc_bonus_%s", paramData.paramInfo.name )
		partDesc = UI:GetStringByName( partDescId )

    	strPartDescColor = ( bShowLockState and synergyLevel > shipSynergyLevel ) and strLockColor or strBaseColor
    	partDesc = string.gsub( partDesc, "%$(.-)%$", fnItemGroupSubst )

    	local strParam = UI:ParamVals2Str( paramData.paramInfo, paramData.vals, nil, false, substColor, nil, false, false )
    	strParam = string.format( "%s%s", strParam, strPartDescColor )

    	local strPattern = "%$"..paramData.paramInfo.name.."%$"
		local numSubst = 0
    	partDesc, numSubst = string.gsub( partDesc, strPattern, strParam )

		if numSubst == 0 then
			sys.log( "UI:ShipDescParam2Str()[ERROR]: cannot find placeholder \"%s\" in string \"%s\"", "$"..paramData.paramInfo.name.."$", partDescId )
			partDesc = string.format( "[INVALID STRING] Param \"%s\" is %s", paramData.paramInfo.name, strParam )
		end

		partDesc = string.format( "%s%s%s", strPartDescColor, partDesc, strBaseColor )

	end

	-- залоченный по синергии параметр
	if bShowLockState and synergyLevel > shipSynergyLevel then

		local strLock = UI:GetStringByName( "paramLockedBySynergy" )
		local strSynergyLevel = string.format( "%s%s%s", strSubstColor, tostring( synergyLevel ), strLockColor )
		strLock = string.gsub( strLock, "%$level%$", strSynergyLevel )

		partDesc = string.format( "%s %s", strLock, partDesc )
		partDesc = string.format( "%s%s", strLockColor, partDesc )

	end

	return partDesc

end


-- все параметры для описания корабля - включая и те, которые непосредственно в дефе, и зависимые по синергии;
-- одинаковые параметры стакаются

function UI:GetShipDescParamsEx( srcInfo, craftedBonuses )

	local defName = srcInfo and srcInfo.defName or ""
	local shipSynergyLevel = srcInfo.synergyLevel or 0

	srcInfo.dataType = UI.paramSrcTypes.SHIP

	local regularParamsData = self:GetShipRegularDescParams( srcInfo )
	local leveledParamsData	= self:GetShipSynergyDependDescParams( srcInfo, craftedBonuses )

	local paramsDataBySource =
	{
		regularParamsData,
		leveledParamsData,
	}

	local allParamsData = {}

	for paramsSource, paramsData in ipairs( paramsDataBySource ) do

    	for paramIdx, paramData in ipairs( paramsData ) do

			local bHasNonZeroVals = false
			for valIdx, val in pairs( paramData.vals ) do
				if val ~= nil and val ~= 0 then
					bHasNonZeroVals = true
					break
				end
			end

			if bHasNonZeroVals then							-- #0070023,комм.(0291078) - не показываются параметры со значением 0
    			table.insert( allParamsData, paramData )
			end

    	end

	end


	-- #0034719 - одинаковые параметры стакаются ("схлопываются") - суммируются постоянно присутствующее значение (если есть) и значения для всех достигнутых уровней синергии

	local numParams = #allParamsData
	for paramIdx = 1, numParams do

		local baseParamData = allParamsData[ paramIdx ]
		if not baseParamData.bIgnore and not baseParamData.bUndefined then

        	local numBaseVals		= #baseParamData.vals
    		local baseSynergyLevel	= baseParamData.synergyLevel or -1

    		for tailParamIdx = paramIdx + 1, numParams do

    			local tailParamData = allParamsData[ tailParamIdx ]
    			if not tailParamData.bUndefined and tailParamData.paramInfo.name == baseParamData.paramInfo.name then

    				local tailSynergyLevel = tailParamData.synergyLevel or -1

    				if ( baseSynergyLevel == -1 or baseSynergyLevel <= shipSynergyLevel ) and ( tailSynergyLevel == -1 or tailSynergyLevel <= shipSynergyLevel ) then

        				local numTailVals = #tailParamData.vals
        				if numBaseVals == numTailVals then

            				for valIdx = 1, numBaseVals do

        						local val = baseParamData.vals[ valIdx ]
            					local tailVal = tailParamData.vals[ valIdx ]

        						val = val + tailVal
        						baseParamData.vals[ valIdx ] = val

            				end

    						tailParamData.bIgnore = true

        				else
        					sys.log( "UI:GetShipDescParams()[ERROR]: num vals mismatched for param %s and ship %s", baseParamData.paramInfo.name, defName )
        				end

    				end

    			end

    		end

		end

	end

	-- #0034751, комм.(0121258) - если значения "плохие", то они не отображаются
	for idx, paramData in pairs( allParamsData ) do
		if not paramData.bIgnore and not paramData.bUndefined then

			local vals = paramData.vals
			if #vals == 1 then
				local val = paramData.vals[ 1 ]

				local bNegative = ( paramData.paramInfo.negative == true and val > 0 ) or ( paramData.paramInfo.negative ~= true and val < 0 )
				if bNegative then
					paramData.bIgnore = true
				end
			end

		end
	end


	-- окончательный список, без тех параметров, которые были ассимилированы в результате "схлопывания"
	local finalParamsData = {}

	for idx = 1, #allParamsData do

		local paramData = allParamsData[ idx ]
		if not paramData.bIgnore then
			table.insert( finalParamsData, paramData )
		end

	end

	return finalParamsData

end


-- параметры, которые прописаны непосредственнго в дефе корабля
function UI:GetShipRegularDescParams( srcInfo )

	local paramsData = {}

	local descriptionParams = UI:GetShipDescParams( srcInfo.defName )
	for paramIdx = 1, #descriptionParams do

		local paramInfo = descriptionParams[ paramIdx ]

		local vals = self:GetParamVals( srcInfo.defName, paramInfo, srcInfo.dataType, srcInfo.data, false, -1 )
		if next( vals ) ~= nil then

			local bFound = false
			for existIdx, existParamData in pairs( paramsData ) do
				if existParamData.paramInfo.name == paramInfo.name then
					bFound = true
					break
				end
			end

			if not bFound then

    			local paramData =
    			{
    				paramInfo		= paramInfo,
    				vals			= vals,
					synergyLevel	= -1,
    			}
    			table.insert( paramsData, paramData )

			else
				sys.log( "UI:GetShipRegularDescParams()[ERROR]: duplicate param %s", paramInfo.name )
			end

		end

	end

	return paramsData

end


-- параметры, зависимые по синергии; на каждый параметр каждого уровня синергии возвращается по записи
function UI:GetShipSynergyDependDescParams( srcInfo, craftedBonuses )

	local paramsData = {}

	local def = UI:GetDef( srcInfo.defName )
	if not def then
		sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: cannot find def %s", srcInfo.defName )
		return paramsData
	end

	if craftedBonuses ~= nil then
    	if type( craftedBonuses ) ~= "table" then
    		sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: invalid type of the 2-nd parameter (\"craftedBonuses\"); \"table\" or \"nil\" expected, got \"%s\"", type( craftedBonuses ) )
    		return paramsData
    	end
	end


	local shipDefName = srcInfo.defName

	local descriptionParams = UI:GetShipDescParams( shipDefName )


	local function fnSortByName( paramInfo1, paramInfo2 )
		return paramInfo1.name < paramInfo2.name
	end

	local function fnSortBySynergy( levelParamsInfo1, levelParamsInfo2 )
		return levelParamsInfo1.synLevel < levelParamsInfo2.synLevel
	end


	if def.special_grades ~= nil then

		if type( def.special_grades ) == "table" then

			local synParams = {}

			for synLevel, levelData in pairs( def.special_grades ) do

				local levelParamsInfos =
				{
					synLevel		= synLevel,
					params			= {},
					selBonusName	= "",
				}

				if type( levelData ) ~= "table" then
					sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: invalid type of \"_G.Def[\"%s\"].special_grades[%d]\"; \"table\" expected, got \"%s\"", shipDefName, synLevel, type( levelData ) )
					levelData = nil
				end

				local levelParams = levelData

				if levelData then

    				if UI:IsShipCraftable( shipDefName ) then

    					-- формат поля данных для уровня синергии может быть разный;
    					-- там могут быть как собственно моодификаторы в формате {имя_модификатора=значение},
    					-- так и список имен бонусов, из которых игрок при крафте корабля выбирает один,
    					-- а модификаторы хранятся уже в данных того бонуса;
    					-- отличается один формат от другого хаком -
    					-- если есть целочисленные ключи в таблице, значит это массив, и значит это список имен бонусов

    					local bIsBonusNamesArr = false

    					for key, val in pairs( levelData ) do
    						if type( key ) == "number" then
    							bIsBonusNamesArr = true
    							break
    						end
    					end

    					if bIsBonusNamesArr then

    						levelParams = {}

    						local bonusName = ""

    						if craftedBonuses then

    							bonusName = craftedBonuses[ synLevel ]

    							if bonusName ~= nil then
    								if type( bonusName ) ~= "string" then
    									sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: invalid type of craftedBonuses[\"%s\"]; \"string\" or \"nil\" expected, got \"%s\"", type( bonusName ) )
    									bonusName = ""
    								end
    							end

    						else

    							local shipItem = self:GetShipItemByDef( shipDefName, false )
    							if shipItem then
									bonusName = UI:GetShipCraftedBonus( shipItem, synLevel )
								else
									bonusName = "undefined"	-- специальное имя для отображения бонуса, пока корабль еще не скрафчен, вне окна крафта
    							end

    						end

    						if bonusName ~= nil and bonusName ~= "" then

								levelParamsInfos.selBonusName = bonusName

								if bonusName ~= "undefined" then

        							if type( _G.ShipSpecBonus ) == "table" then

        								levelParams = _G.ShipSpecBonus[ bonusName ]

        								if type( levelParams ) ~= "table" then
        									sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: invalid type of \"_G.ShipSpecBonus[\"%s\"]\"; \"table\" expected, got \"%s\"", bonusName, type( levelParams ) )
        									levelParams = nil
        								end

        							else
        								sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: invalid type of \"_G.ShipSpecBonus\"; \"table\" expected, got \"%s\"", type( _G.ShipSpecBonus ) )
        							end

								end

    						else
    							sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: selected bonus for customizable level is not specified for ship \"%s\" level %d", shipDefName, synLevel )
    						end

    					end

    				end

				end

				if levelParams then

    				for paramName, paramVal in pairs( levelParams ) do

						if type( paramName ) == "string" and type( paramVal ) == "number" then

        					local paramInfo =
        					{
        						name	= paramName,
        						val		= paramVal,
        					}
        					table.insert( levelParamsInfos.params, paramInfo )

						else
							sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: invalid format of bonuses for ship \"%s\" level %d; \"string\"=\"number\" expected, got \"%s\"=\"%s\"", shipDefName, synLevel, type( paramName ), type( paramVal ) )
						end

    				end

    				table.sort( levelParamsInfos.params, fnSortByName )

				end

    			table.insert( synParams, levelParamsInfos )

			end

			table.sort( synParams, fnSortBySynergy )

			for synLevelIdx = 1, #synParams do

				local levelParams = synParams[ synLevelIdx ]
				local synergyLevel = levelParams.synLevel

				if levelParams.selBonusName == "undefined" then

					local paramData =
					{
						paramInfo		= nil,
						vals			= {},
						synergyLevel	= synergyLevel,
						bUndefined		= true,
					}
					table.insert( paramsData, paramData )

				else

    				for synParamIdx = 1, #levelParams.params do

    					local synParamInfo = levelParams.params[ synParamIdx ]

    					local descParamInfo = nil
    					for descParamIdx, descInfo in pairs( descriptionParams ) do
    						if type( descInfo.valField ) == "string" and descInfo.valField == synParamInfo.name then
    							descParamInfo = descInfo
    							break
    						end
    					end

    					if descParamInfo then

                    		local vals = self:GetParamVals( srcInfo.defName, descParamInfo, srcInfo.dataType, srcInfo.data, false, synergyLevel, levelParams.selBonusName )

                    		if next( vals ) ~= nil then

    							local paramData =
    							{
    								paramInfo		= descParamInfo,
    								vals			= vals,
    								synergyLevel	= synergyLevel,
    							}
    							table.insert( paramsData, paramData )

                    		end

    					end

    				end

				end

			end

		else
			sys.log( "UI:GetShipSynergyDependDescParams()[ERROR]: invalid type of _G.Def[%s].special_grades; \"table\" expected, got \"%s\"", defName, type( def.special_grades ) )
		end

	end

	return paramsData

end


--
function UI:FillDescWithParams( srcInfo, compareInfo, desc, descriptionParams, substColor, baseColor, bForceAbs, synergyLevel, selBonusName, affixIdx )

	if type( srcInfo ) ~= "table" then
		sys.log( "UI:FillDescWithParams()[ERROR]: invalid type of the 1-st param (\"srcInfo\"); \"table\" expected, got \"%s\"", type( srcInfo ) )
		return ""
	end

	if type( srcInfo.defName ) ~= "string" then
		sys.log( "UI:FillDescWithParams()[ERROR]: invalid type of (\"srcInfo.defName\"); \"string\" expected, got \"%s\"", type( srcInfo.defName ) )
		return ""
	end

	if compareInfo ~= nil and type( compareInfo ) ~= "table" then
		sys.log( "UI:FillDescWithParams()[ERROR]: invalid type of the 2-nd param (\"srcInfo\"); \"table\" or \"nil\" expected, got \"%s\"", type( compareInfo ) )
		return ""
	end

	if compareInfo then
    	if type( compareInfo.defName ) ~= "string" then
    		sys.log( "UI:FillDescWithParams()[ERROR]: invalid type of (\"compareInfo.defName\"); \"string\" expected, got \"%s\"", type( compareInfo.defName ) )
    		return ""
    	end
	end

	if type( desc ) ~= "string" then
		sys.log( "UI:FillDescWithParams()[ERROR]: invalid type of the 3-rd param (\"desc\"); \"string\" expected, got \"%s\"", type( desc ) )
		return ""
	end

	if descriptionParams ~= nil then
    	if type( descriptionParams ) ~= "table" then
    		sys.log( "UI:FillDescWithParams()[ERROR]: invalid type of the 4-th param (\"descriptionParams\"); \"table\" or \"nil\" expected, got \"%s\"", type( descriptionParams ) )
			return ""
    	end
	end

	if substColor ~= nil then
    	if type( substColor ) ~= "number" then
    		sys.log( "UI:FillDescWithParams()[ERROR]: invalid type of the 5-th param (\"substColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( substColor ) )
			return ""
    	end
	end

	if baseColor ~= nil then
    	if type( baseColor ) ~= "number" then
    		sys.log( "UI:FillDescWithParams()[ERROR]: invalid type of the 6-th param (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			return ""
    	end
	end

	if substColor ~= nil and baseColor == nil then
		sys.log( "UI:FillDescWithParams()[ERROR]: substColor is not nil but baseColor is nil; default color will be used as baseColor" )
		baseColor = UI.TEXT_BASE_COLOR
	end

	local strBaseColor = baseColor and UI:Color2Str( baseColor ) or ""

	if descriptionParams and next( descriptionParams ) then

		local fnSubst = function( capture )

			for paramIdx, paramInfo in pairs( descriptionParams ) do

				if paramInfo.name == capture then

					local strParam = UI:GetParamValAsStr( paramInfo, srcInfo, compareInfo, false, substColor, nil, bForceAbs, descriptionParams, nil, nil, synergyLevel, selBonusName, affixIdx )

					if not UI:IsStrEmpty( strParam ) then
						strParam = string.format( "%s%s", strParam, strBaseColor )
					else
						sys.log( "UI:FillDescWithParams()[ERROR]: cannot convert parameter \"%s\" for \"%s\" into string; it has no corresponding values", paramInfo.name, srcInfo.defName )
						strParam = nil
					end

					return strParam
				end

			end

			return nil

		end

		desc = string.gsub( desc, "%$(.-)%$", fnSubst )

	end

	if strBaseColor ~= "" and desc ~= "" then
		desc = string.format( "%s%s", strBaseColor, desc )
	end

	return desc

end


--
l_arabic2Latin =
{
	[ 1 ]	= "I",
	[ 2 ]	= "II",
	[ 3 ]	= "III",
	[ 4 ]	= "IV",
	[ 5 ]	= "V",
	[ 6 ]	= "VI",
	[ 7 ]	= "VII",
	[ 8 ]	= "VIII",
	[ 9 ]	= "IX",
	[ 10 ]	= "X",
}

--
function UI:Arabic2LatinNumerals( num )

	return l_arabic2Latin[ num ] or ""

end


--
function UI:HasReactinWindowsOnEvent( eventId )

	local bHasReactingWindows = false

	-- проверяются только окна, прилинкованные к руту
	local wnd =	UI.Root:GetFirstChild()
	while wnd do
		if self:IsUiObjSubscribedOnEvent( wnd:GetUiHandle(), eventId ) then
			bHasReactingWindows = true
			break
		end
		wnd = wnd:GetNextSibling()
	end

	return bHasReactingWindows

end


--
local l_spellIcoLayer2SpriteName =
{
    activation		= "action_type",
    target			= "action_area",
    target_system	= "action_object",
    influence		= "modification",
}

local l_defaultSpellIcoSpriteName = "action_type"

--
function UI:UpdateSpellIco( icoInfo, wnd, layer )

	local icoEffect = UI:GetEffectFromLayer( wnd, layer )
	if not icoEffect then
		return
	end

	for layerName, spriteName in pairs( l_spellIcoLayer2SpriteName ) do
		icoEffect:SetSpriteTexture( spriteName, UI.INVALID_RESOURCE_HANDLE )
	end

	if not icoInfo or type( icoInfo ) ~= "table" then
		return
	end

	for layerName, layerInfo in pairs( icoInfo ) do

		local spriteName = l_spellIcoLayer2SpriteName[ layerName ]
		if spriteName then

			local texName = layerInfo.tex
			if type( texName ) == "string" then

				local hTex = UI:GetResourceHandleByName( texName, UI.RES_TEXTURE )
        		if hTex == UI.INVALID_RESOURCE_HANDLE then
        			hTex = UI:GetResourceHandleByName( "NoData", UI.RES_TEXTURE )
        		end

				icoEffect:SetSpriteTexture( spriteName, hTex )
				UI:ReleaseResourceHandle( hTex )

			else
				sys.log( "UI:UpdateSpellIco()[ERROR]: cannot find \"_G.Def.%s.ui_ico.%s.tex\"", defName, layerName )
			end
		else
			sys.log( "UI:UpdateSpellIco()[ERROR]: cannot find sprite for layer \"%s\"", tostring( layerName ) )
		end

	end

end


--
function UI:UpdateItemIco( defName, wnd, layer, bMono, phase )

	if type( defName ) ~= "string" then
		sys.log( "UI:UpdateItemIco()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return
	end

	if type( wnd ) ~= "table" then
		sys.log( "UI:UpdateItemIco()[ERROR]: invalid type of the 2-nd parameter (\"wnd\"); \"table\" expected, got \"%s\"", type( wnd ) )
		return
	end

	if not wnd.w then
		sys.log( "UI:UpdateItemIco()[ERROR]: invalid the 2-nd parameter (\"wnd\"); Wnd expected" )
		return
	end

	if type( layer ) ~= "number" then
		sys.log( "UI:UpdateItemIco()[ERROR]: invalid type of the 3-rd parameter (\"layer\"); \"number\" expected, got \"%s\"", type( layer ) )
		return
	end

	if bMono ~= nil then
    	if type( bMono ) ~= "boolean" then
    		sys.log( "UI:UpdateItemIco()[ERROR]: invalid type of the 4-th parameter (\"bMono\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bMono ) )
			bMono = false
    	end
	else
		bMono = false
	end

	if phase == nil then
		phase = -1
	else
		if type( phase ) ~= "number" then
			sys.log( "UI:UpdateItemIco()[ERROR]: invalid type of the 5-th parameter (\"phase\"); \"number\" expected, got \"%s\"", type( phase ) )
			return
		end
	end

	local icoEffect = UI:GetEffectFromLayer( wnd, layer )
	if not icoEffect then
		sys.log( "UI:UpdateItemIco()[ERROR]: effect not found" )
		return

	end

	-- reset

	UI:ResetItemIco( wnd, layer )


    local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:UpdateItemIco()[ERROR]: cannot find def \"%s\"", defName )
		return
	end


	-- try set spell ico

	local varName = "ui_ico"
	if phase ~= -1 then
		varName = string.format( "%s_%d", varName, phase )
	end

	local icoInfo = def[ varName ]
	if icoInfo then

		if type( icoInfo ) ~= "table" then
			sys.log( "UI:UpdateItemIco()[ERROR]: invalid type of _G.Def[%s].%s; \"table\" or \"nil\" expected, got \"%s\"", defName, varName, type( icoInfo ) )
			return
		end

    	for layerName, layerInfo in pairs( icoInfo ) do

    		local spriteName = l_spellIcoLayer2SpriteName[ layerName ]
    		if spriteName then

    			local texName = layerInfo.tex
    			if type( texName ) == "string" then

    				if bMono then
    					texName = string.format( "%s_mono", texName )
    				end

    				local hTex = UI:GetTex( texName )
    				icoEffect:SetSpriteTexture( spriteName, hTex )

    			else
    				sys.log( "UI:UpdateItemIco()[ERROR]: cannot find \"_G.Def.%s.%s.%s.tex\"", defName, varName, layerName )
    			end

    		else
    			sys.log( "UI:UpdateItemIco()[ERROR]: cannot find sprite for layer \"%s\"", tostring( layerName ) )
    		end

    	end

	-- set non-spell ico

	else

		local hTex = UI:GetShopIco( defName )
    	icoEffect:SetSpriteTexture( l_defaultSpellIcoSpriteName, hTex )

	end

end


--
function UI:SetItemIcoDirect( hTex, wnd, layer )

	if type( hTex ) ~= "number" then
		sys.log( "UI:SetItemIcoDirect()[ERROR]: invalid type of the 1-st parameter (\"hTex\"); \"number\" expected, got \"%s\"", type( hTex ) )
		return
	end

	if type( wnd ) ~= "table" then
		sys.log( "UI:SetItemIcoDirect()[ERROR]: invalid type of the 2-nd parameter (\"wnd\"); \"table\" expected, got \"%s\"", type( wnd ) )
		return
	end

	if not wnd.w then
		sys.log( "UI:SetItemIcoDirect()[ERROR]: invalid the 2-nd parameter (\"wnd\"); Wnd expected" )
		return
	end

	if type( layer ) ~= "number" then
		sys.log( "UI:SetItemIcoDirect()[ERROR]: invalid type of the 3-rd parameter (\"layer\"); \"number\" expected, got \"%s\"", type( layer ) )
		return
	end

	local icoEffect = UI:GetEffectFromLayer( wnd, layer )
	if not icoEffect then
		sys.log( "UI:SetItemIcoDirect()[ERROR]: effect not found" )
		return
	end

	UI:ResetItemIco( wnd, layer )

	icoEffect:SetSpriteTexture( l_defaultSpellIcoSpriteName, hTex )

end


--
function UI:ResetItemIco( wnd, layer )

	local icoEffect = UI:GetEffectFromLayer( wnd, layer )
	if not icoEffect then
		return
	end

	for layerName, spriteName in pairs( l_spellIcoLayer2SpriteName ) do
		icoEffect:SetSpriteTexture( spriteName, UI.INVALID_RESOURCE_HANDLE )
	end

end


--
function UI:GetItemRace( defName )

	if UI:IsDefShip( defName ) then

		return UI:GetShipRace( defName )

	else

		local def = UI:GetDef( defName )
    	local raceMask = def and def.required_race

    	if raceMask == nil or raceMask == 0 then
    		return -1
    	end

    	local race = UI:RaceMask2OneRace( raceMask )

    	if race == -1 then
    		sys.log( "UI:GetItemRace()[ERROR]: more than one race in mask %d for def %s", raceMask, defName )
    	end

    	return race

	end

end


--
function UI:GetShipRace( defName )

	local race = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipRace()[ERROR]: invalid type of the 1-st parameterr (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return race
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetShipRace()[ERROR]: cannot find _G.Def[%s]", defName )
		return race
	end

	if type( def.race ) ~= "number" then
		sys.log( "UI:GetShipRace()[ERROR]: invalid type of the _G.Def[%s].race; \"number\" expected, got \"%s\"", defName, type( def.race ) )
		return race
	end

	if UI:Val2Key( ai.Race, def.race ) == "" then
		sys.log( "UI:GetShipRace()[ERROR]: invalid value in _G.Def[%s].race; one of the \"ai.Race\" values expected, got %d", defName, def.race )
		return race
	end

	if def.race == ai.Race.NUM then
		sys.log( "UI:GetShipRace()[ERROR]: invalid race in _G.Def[%s].race", defName )
		return race
	end

	race = def.race
	return race

end


--
function UI:RaceMask2OneRace( raceMask )

	if not raceMask or raceMask == 0 then
		return -1
	end

	local race = -1

	local singleRaceName = UI:Val2Key( ai.RaceMask, raceMask )
	if singleRaceName ~= "" then
		race = ai.Race[ singleRaceName ]
	end

	return race or -1

end


--
function UI:GetItemRaceMask( defName )

	local mask = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemRaceMask()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expectef, got \"%s\"", type( defName ) )
		return mask
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemRaceMask()[ERROR]: cannot find Def[\"%s\"]", defName )
