--
function UI:GetItemUpgradeCreditsPrice( defName )

	local price		= 0
	local basePrice	= 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemUpgradeCreditsPrice()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return price, basePrice
	end

	if UI:IsDefAutogen( defName ) then
		sys.log( "UI:GetItemUpgradeCreditsPrice()[ERROR]: not supported for autogen" )
		return price, basePrice
	end

	local nextDefName = UI:GetItemUpgradeNextDef( defName )
	if nextDefName == "" then
		sys.log( "UI:GetItemUpgradeCreditsPrice()[ERROR]: cannot find next upgrade def for \"%s\"", defName )
		return price, basePrice
	end

	local creditsPrice		= UI:GetShopAllBuyPricesByDef( nextDefName, false, false )
	local baseCreditsPrice	= UI:GetShopAllBaseBuyPricesByDef( nextDefName, false )

	price		= creditsPrice
	basePrice	= baseCreditsPrice

	return price, basePrice

end


--
function UI:GetItemPopUpMenuDataForUpgrade( iid )

	local upgradeData = nil

	if type( iid ) ~= "userdata" then
		sys.log( "UI:GetItemPopUpMenuDataForUpgrade()[ERROR]: invalid type of the 1-st parameter (\"iid\"); \"userdata\" expected, got \"%s\"", type( iid ) )
		return upgradeData
	end

	if iid == UI.INVALID_U64_ID then
		sys.log( "UI:GetItemPopUpMenuDataForUpgrade()[ERROR]: invalid iid" )
		return upgradeData
	end

	local defName = UI:Iid2DefName( iid )
	if defName == "" then
		sys.log( "UI:GetItemPopUpMenuDataForUpgrade()[ERROR]: cannot find defName" )
		return upgradeData
	end

	if not UI:CanItemUpgradeFurther( defName ) then
		return upgradeData
	end

	if UI:CanUpgradeItemThroughCraftOnly( defName ) then
		return upgradeData
	end

	upgradeData = {}

	upgradeData.slotType	= UI.popUpMenuSlotTypes.UPGRADE_ITEM
	upgradeData.text		= UI:GetStringByName( "popUpMenu_upgradeItem" )
	upgradeData.iid			= iid

	return upgradeData

end


--
function UI:GetItemRequiredAccountRank( defName )

	local requiredRank = 1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemRequiredAccountRank()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return requiredRank
	end

	if UI:IsDefShip( defName ) then

		if not UI:IsShipPremium( defName ) and not UI:IsShipDlc( defName ) then

			local shipRace = UI:GetShipRace( defName )
			local shipRank = UI:GetShipRank( defName )

			if shipRace ~= -1 and shipRank ~= -1 then
				requiredRank = UI:GetShipsRequiredRank( shipRace, shipRank )
			else
				sys.log( "UI:GetItemRequiredAccountRank()[ERROR]: invalid race or rank for ship %s", defName )
			end

		end

	else

		local def = UI:GetDef( defName )
		if def then

			if def.required_rank ~= nil then
				if type( def.required_rank ) == "number" then
					requiredRank = def.required_rank
				else
					sys.log( "UI:GetItemRequiredAccountRank()[ERROR]: invalid type of _G.Def[%s].required_rank; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.required_rank ) )
				end
			end

		else
			sys.log( "UI:GetItemRequiredAccountRank()[ERROR]: cannot find _G.Def[%s]", defName )
		end

	end

	return requiredRank

end


--
function UI:GetShipsRequiredRank( shipRace, shipRank )

	local requiredRank = 1

	if type( shipRace ) ~= "number" then
		sys.log( "UI:GetShipsRequiredRank()[ERROR]: invalid type of the 1-st parameter (\"shipRace\"); \"number\" expected, got \"%s\"", type( shipRace ) )
		return requiredRank
	end

	if type( shipRank ) ~= "number" then
		sys.log( "UI:GetShipsRequiredRank()[ERROR]: invalid type of the 2-nd parameter (\"shipRank\"); \"number\" expected, got \"%s\"", type( shipRank ) )
		return requiredRank
	end

	if type( _G.LockRank ) == "table" then

		local raceInfo = _G.LockRank[ shipRace ]
		if type( raceInfo ) == "table" then

			if type( raceInfo[ shipRank ] ) == "number" then
				requiredRank = raceInfo[ shipRank ]
			else
				sys.log( "UI:GetShipsRequiredRank()[ERROR]: invalid type of \"_G.LockRank[%d][%d]\"; \"table\" expected, got \"%s\"", shipRace, shipRank, type( raceInfo[ shipRank ] ) )
			end

		else
			sys.log( "UI:GetShipsRequiredRank()[ERROR]: invalid type of \"_G.LockRank[%d]\"; \"table\" expected, got \"%s\"", shipRace, type( raceInfo ) )
		end

	else
		sys.log( "UI:GetShipsRequiredRank()[ERROR]: invalid type of \"_G.LockRank\"; \"table\" expected, got \"%s\"", type( _G.LockRank ) )
	end

	return requiredRank

end


--
function UI:IsEnoughAccountRankForItem( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:IsEnoughAccountRankForItem()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return true
	end

	local requiredRank	= self:GetItemRequiredAccountRank( defName )
	local playerRank	= self:GetPlayerAccountRank()

	return requiredRank <= playerRank

end


--
function UI:GetItemTooltipParams( defName )

	if not ( ( UI:IsDefAmmo( defName ) or UI:IsDefModule( defName ) ) and not UI:IsDefTokenItem( defName ) and not UI:IsDefAutogen( defName ) ) then
		return {}
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemTooltipParams()[ERROR]: cannot find _G.Def[%s]", tostring( defName ) )
		return {}
	end

	if not def.item_subtype then
		sys.log( "UI:GetItemTooltipParams()[ERROR]: cannot find _G.Def[%s].item_subtype", defName )
		return {}
	end

	local allParams = _G.ItemTooltips and _G.ItemTooltips[ def.item_subtype ] and _G.ItemTooltips[ def.item_subtype ].tooltipParams or {}
	local params = {}

	for paramIdx = 1, #allParams do

		local paramInfo = allParams[ paramIdx ]

		if paramInfo.invisible ~= true then
			table.insert( params, paramInfo )
		end

	end

	return params

end


