--
function UI:FixParamVals( vals, paramInfo, bForceAbs, isValsFromAffix )

	-- значения прогоняются через указанную функциию (функции) (если есть);
	-- при этом количество исходных значений и количество формул может не совпадать;
	-- показывается в результате столько значений, сколько формул, в каждую формулу при этом передаются все значения

	if paramInfo.formula and next( vals ) then

		-- есть ли хотя бы одно значение из аффикса
		local isAValFromAffix = false
		if isValsFromAffix then
			for idx, bFromAffix in pairs( isValsFromAffix ) do
				if bFromAffix then
					isAValFromAffix = true
					break
				end
			end
		end

		local newVals = {}
		local newIsValsFromAffix = {}

		local formulaFieldType = type( paramInfo.formula )

		if formulaFieldType == "function" then

			local fn = paramInfo.formula
			local val = fn( unpack( vals ) )

			if val == nil then
				-- #0027758
--				sys.log( "UI:FixParamVals()[ERROR]: nil val after return from \"formula\" for param \"%s\"", tostring( paramInfo.name ) )
--				val = 0
			end

			if val ~= nil then
				table.insert( newVals, val )
				table.insert( newIsValsFromAffix, isAValFromAffix )	-- если хотя бы одно из начальных полей было из аффикса, то считаем, что результат тоже из аффикса
			end

		elseif formulaFieldType == "table" then

        	for idx = 1, #paramInfo.formula do

    			local fn = paramInfo.formula[ idx ]
    			if type( fn ) == "function" then

    				local val = fn( unpack( vals ) )

        			if val == nil then
						-- #0027758
--        				sys.log( "UI:FixParamVals()[ERROR]: nil val after return from \"formula[%d]\" for param \"%s\"", idx, tostring( paramInfo.name ) )
--        				val = 0
        			end

					if val ~= nil then
						table.insert( newVals, val )
						table.insert( newIsValsFromAffix, isAValFromAffix )	-- если хотя бы одно из начальных полей было из аффикса, то считаем, что результат тоже из аффикса
					end

    			else
    				sys.log( "UI:FixParamVals()[ERROR]: invalid type of formula[%d] for param \"%s\"; \"function\" expected, got \"%s\"", idx, tostring( paramInfo.name ), type( fn ) )
    			end

        	end

		else
			sys.log( "UI:FixParamVals()[ERROR]: invalid type of \"formula\" for param \"%s\"; \"function\" or \"table\" expected, got \"%s\"", tostring( paramInfo.name ), formulaFieldType )
		end

		vals = newVals
		isValsFromAffix = newIsValsFromAffix

	end

	-- значения модифицируются сообразно полю units

    for idx, val in pairs( vals ) do
		vals[ idx ] = UI:FixParamVal( paramInfo, val, bForceAbs )
	end

	return vals, isValsFromAffix

end


-- возврвщает значения в виде таблицы, даже если параметр один
function UI:GetParamVals( defName, paramInfo, paramSrcType, paramSrcData, bForceAbs, synergyLevel, selBonusName, bNodeBonus, affixIdx )

	-- получаются "сырые" значения по ссылкам

	local vals = {}
	local isValsFromAffix = {}

	if type( defName ) ~= "string"  then
		sys.log( "UI:GetParamVals()[ERROR]: invalid type of then 1-st parameter (\"defName\" ); \"string\" expected, got \"%s\"", type( defName ) )
		return vals
	end

	if type( paramInfo ) ~= "table"  then
		sys.log( "UI:GetParamVals()[ERROR]: invalid type of then 2-nd parameter (\"paramInfo\" ); \"table\" expected, got \"%s\"", type( paramInfo ) )
		return vals
	end

	local valFieldType = type( paramInfo.valField )
	if valFieldType == "string" then

		local val, bFromAffix = UI:GetParamValByField( defName, paramInfo, paramInfo.valField, 1, paramSrcType, paramSrcData, synergyLevel, selBonusName, bNodeBonus, affixIdx )
		if val ~= nil then
			table.insert( vals, val )
			table.insert( isValsFromAffix, bFromAffix or false )
		end

	elseif valFieldType == "table" then

		local numValFields = #paramInfo.valField
		for fieldIdx = 1, numValFields do

			local fieldName = paramInfo.valField[ fieldIdx ]

			if type( fieldName ) == "string" then

				local val, bFromAffix = UI:GetParamValByField( defName, paramInfo, fieldName, fieldIdx, paramSrcType, paramSrcData, synergyLevel, selBonusName, bNodeBonus, affixIdx )
				if val ~= nil then
					table.insert( vals, val )
					table.insert( isValsFromAffix, bFromAffix or false )
				end

			else
				sys.log( "UI:GetParamVals()[ERROR]: invalid \"valField\" format for param \"%s\"", tostring( paramInfo.name ) )
			end

		end

		local numVals = #vals
		if numVals > 0 and numVals ~= numValFields then
			-- #0027984
--			sys.log( "UI:GetParamVals()[ERROR]: some values (but not all) are nill in param \"%s\" for defName \"%s\"", tostring( paramInfo.name ), tostring( defName ) )
			vals = {}
		end

	else
		sys.log( "UI:GetParamVals()[ERROR]: invalid type of \"valField\" for param \"%s\" defName \"%s\"; \"string\" or \"table\" expected, got \"%s\"", tostring( paramInfo.name ), tostring( defName ), valFieldType )
		return vals
	end

	return UI:FixParamVals( vals, paramInfo, bForceAbs, isValsFromAffix )

end


--
function UI:GetParamValByField( srcDefName, paramInfo, refFieldName, refFieldIdx, paramSrcType, paramSrcData, synergyLevel, selBonusName, bNodeBonus, affixIdx )

	local bAllowNilParams = true

	local val = nil
	if not bAllowNilParams then
		val = 0
	end

	if type( srcDefName ) ~= "string" then
		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of then 1-st parameter (\"srcDefName\" ); \"string\" expected, got \"%s\"", type( srcDefName ) )
		return val
	end

	if type( paramInfo ) ~= "table"  then
		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of then 2-nd parameter (\"paramInfo\" ); \"table\" expected, got \"%s\"", type( paramInfo ) )
		return val
	end

	if type( refFieldName ) ~= "string" then
		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 3-rd parameter (\"refFieldName\"); \"string\" expected, got \"%s\"", type( refFieldName ) )
		return val
	end

	if type( refFieldIdx ) ~= "number" then
		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 4-th parameter (\"refFieldIdx\"); \"number\" expected, got \"%s\"", type( refFieldIdx ) )
		return val
	end

	if UI:Val2Key( UI.paramSrcTypes, paramSrcType ) == "" then
		sys.log( "UI:GetParamValByField()[ERROR]: invalid 5-th parameter (\"paramSrcType\"); one of the \"UI.paramSrcTypes\" values expected, got \"%s\"", tostring( paramSrcType ) )
		return val
	end

	if synergyLevel ~= nil then
		if type( synergyLevel ) ~= "number" then
			sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 7-th parameter (\"synergyLevel\"); \"number\" or \"nil\" expected, got \"%s\"", type( synergyLevel ) )
			synergyLevel = nil
		end
	end

	if synergyLevel == nil then
		synergyLevel = -1
	end

	if selBonusName ~= nil then
		if type( selBonusName ) ~= "string" then
			sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 8-th parameter (\"selBonusName\"); \"string\" or \"nil\" expected, got \"%s\"", type( selBonusName ) )
			selBonusName = nil
		end
	end

	if selBonusName == nil then
		selBonusName = ""
	end

	if bNodeBonus ~= nil then
		if type( bNodeBonus ) ~= "boolean" then
			sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 9-th parameter (\"bNodeBonus\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bNodeBonus ) )
			bNodeBonus = nil
		end
	end

	if bNodeBonus == nil then
		bNodeBonus = false
	end

	if paramSrcType == UI.paramSrcTypes.SPELL then

		if paramSrcData ~= nil then

        	if type( paramSrcData ) ~= "table" then
        		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 6-th parameter (\"paramSrcData\"); \"table\" or nil expected, got \"%s\"", type( paramSrcData ) )
        		return val
        	end

    		if paramSrcData.auraEnt ~= nil then
            	if type( paramSrcData.auraEnt ) ~= "userdata" then
            		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the paramSrcData.auraEnt; \"userdata\" or nil expected, got \"%s\"", type( paramSrcData.auraEnt ) )
            		return val
            	end
    		end

    		if paramSrcData.auraIdx ~= nil then
            	if type( paramSrcData.auraIdx ) ~= "number" then
            		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the paramSrcData.auraIdx; \"number\" or nil expected, got \"%s\"", type( paramSrcData.auraIdx ) )
            		return val
            	end
    		end

		end

	elseif paramSrcType == UI.paramSrcTypes.SHIP or paramSrcType == UI.paramSrcTypes.MODULE then

		if paramSrcData ~= nil then

        	if type( paramSrcData ) ~= "table" then
        		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 6-th parameter (\"paramSrcData\"); \"table\" or nil expected, got \"%s\"", type( paramSrcData ) )
        		return val
        	end

    		if paramSrcData.params ~= nil then
            	if type( paramSrcData.params ) ~= "table" then
            		sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the paramSrcData.params; \"table\" or nil expected, got \"%s\"", type( paramSrcData.params ) )
            		return val
            	end
    		end

		end

	end

	if paramSrcType == UI.paramSrcTypes.MODULE and UI:IsDefAutogen( srcDefName ) then

		if affixIdx ~= nil then
			if type( affixIdx ) ~= "number" then
				sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 9-th parameter (\"affixIdx\"); \"number\" or \"nil\" expected, got \"%s\"", type( affixIdx ) )
				return val
			end
		end

		if affixIdx and affixIdx ~= -1 then

			if type( paramSrcData ) ~= "table" then
				sys.log( "UI:GetParamValByField()[ERROR]: invalid type of the 6-th parameter (\"paramSrcData\"); \"table\" or nil expected, got \"%s\"", type( paramSrcData ) )
				return val
			end

			if type( paramSrcData.autogen ) ~= "table" then
				sys.log( "UI:GetParamValByField()[ERROR]: invalid type of paramSrcData.autogen; \"table\" expected, got \"%s\"", type( paramSrcData.autogen ) )
				return val
			end

			if type( paramSrcData.autogen.affixesGeneratedData ) ~= "table" then
				sys.log( "UI:GetParamValByField()[ERROR]: invalid type of paramSrcData.autogen.affixesGeneratedData; \"table\" expected, got \"%s\"", type( paramSrcData.autogen.affixesGeneratedData ) )
				return val
			end

			if type( paramSrcData.autogen.decomposition ) ~= "table" then
				sys.log( "UI:GetParamValByField()[ERROR]: invalid type of paramSrcData.autogen.decomposition; \"table\" expected, got \"%s\"", type( paramSrcData.autogen.decomposition ) )
				return val
			end

		end

	end

	-- автоген-аффикс
	if paramSrcType == UI.paramSrcTypes.MODULE and UI:IsDefAutogen( srcDefName ) and affixIdx and affixIdx ~= -1 then

		local bFromAffix = false

		local affixData = paramSrcData.autogen.affixesGeneratedData[ affixIdx ]
		if not affixData then
			sys.log(  "UI:GetParamValByField()[ERROR]: no generated data for affix for module %s affixIdx %d", srcDefName, affixIdx )
			return val
		end

		-- спелл
		if paramInfo.spellPrototype ~= nil then

			if type( paramInfo.spellPrototype ) ~= "string" then
				sys.log( "UI:GetParamValByField()[ERROR]: invalid type of 'spellPrototype' in param '%s' for module %s affixIdx %d ; 'string' or 'nil' expected, got '%s'", paramInfo.name, srcDefName, affixIdx, type( paramInfo.spellPrototype ) )
				return val
			end

			local spellActionData = affixData[ paramInfo.spellPrototype ]
			if not spellActionData then
				sys.log( "UI:GetParamValByField()[ERROR]: cannot find spellActionData for module %s affixIdx %d spellAction %s", srcDefName, affixIdx, paramInfo.spellPrototype )
				return val
			end

			local spellIdx = 1
			if paramInfo.spellId ~= nil then
				if type( paramInfo.spellId ) == "number" then
					spellIdx = paramInfo.spellId
				else
					sys.log( "UI:GetParamValByField()[ERROR]: invalid type of 'spellId' in param '%s' for module %s affixIdx %d ; 'number' or 'nil' expected, got '%s'", paramInfo.name, srcDefName, affixIdx, type( paramInfo.spellId ) )
					return val
				end
			end

			local spellData = spellActionData[ spellIdx ]
			if not spellData then
				sys.log( "UI:GetParamValByField()[ERROR]: cannot find spellData for module %s affixIdx %d spellAction %s spellIdx %d", srcDefName, affixIdx, paramInfo.spellPrototype, spellIdx )
				return val
			end

			local _val = spellData[ refFieldName ]

			if _val then
				bFromAffix = true

			-- если значения нет в аффиксе, значит берем из базового дефа спелла
			else

				local affixRollData = paramSrcData.autogen.decomposition.affixes and paramSrcData.autogen.decomposition.affixes[ affixIdx ]
				if not affixRollData then
					sys.log( "UI:GetParamValByField()[ERROR]: cannot find rollData for module %s affixIdx %d", baseSpellDefName, affixIdx )
					return val
				end

				local baseSpellDefName = UI:GetAutogenSpellBaseDefName( affixRollData.affixId, affixRollData.level, paramInfo.spellPrototype, spellIdx )
				if baseSpellDefName == "" then
					sys.log( "UI:GetParamValByField()[ERROR]: cannot find baseSpellDefName for module %s affixIdx %d spellAction %s spellIdx %d", srcDefName, affixIdx, paramInfo.spellPrototype, spellIdx )
					return val
				end

				local baseSpellDef = UI:GetSpellDef( baseSpellDefName )
				if not baseSpellDef then
					sys.log( "UI:GetParamValByField()[ERROR]: cannot find spell %s for module %s affixIdx %d spellAction %s spellIdx %d", baseSpellDefName, srcDefName, affixIdx, paramInfo.spellPrototype, spellIdx )
					return val
				end

				_val = baseSpellDef[ refFieldName ]

			end

			if not _val then
				sys.log( "UI:GetParamValByField()[ERROR]: cannot find val for module %s affixIdx %d spellAction %s spellIdx %d valName %s", srcDefName, affixIdx, paramInfo.spellPrototype, spellIdx, refFieldName )
				return val
			end

			val = _val

		-- модификатор
		else

			local _val = affixData[ refFieldName ]

			if _val then
				bFromAffix = true

			-- если значения нет в аффиксе, значит берем из базового дефа модуля
			else

				local moduleBaseDefName = UI:GetAutogenItemBaseDefName( paramSrcData.autogen.decomposition )

				local moduleBaseDef = UI:GetDef( moduleBaseDefName )
				if not moduleBaseDef then
					sys.log( "UI:GetParamValByField()[ERROR]: canot find def 'moduleBaseDefName'" )
					return val
				end

				_val = moduleBaseDef[ refFieldName ]

			end

			if not _val then
				sys.log( "UI:GetParamValByField()[ERROR]: cannot find val for module %s affixIdx %d valName %s", srcDefName, affixIdx, refFieldName )
				return val
			end

			val = _val

		end

		return val, bFromAffix

	end


	local refDefTypes =
	{
		SRC		= 1,
		SPELL	= 3,
	}

	local refDefType		= -1
	local refDefVarName		= ""

	local subDefVarName		= ""
	local spellVarName		= ""

	local subDefType		= type( paramInfo.subPrototype )
	local spellType			= type( paramInfo.spellPrototype )

	if subDefType == "string" then
		subDefVarName = paramInfo.subPrototype

	elseif subDefType == "table" then
		subDefVarName = paramInfo.subPrototype[ refFieldIdx ]

	elseif subDefType ~= "nil" then
		sys.log( "UI:GetParamValByField()[ERROR]: invalid subPrototypeType type in param \"%s\" for item \"%s\"", tostring( paramInfo.name ), srcDefName )
		return val
	end

	if spellType == "string" then
		spellVarName = paramInfo.spellPrototype

	elseif spellType == "table" then
		spellVarName = paramInfo.spellPrototype[ refFieldIdx ]

	elseif spellType ~= "nil" then
		sys.log( "UI:GetParamValByField()[ERROR]: invalid spellPrototype type in param \"%s\" for item \"%s\"", tostring( paramInfo.name ), srcDefName )
		return val
	end

	if not UI:IsStrEmpty( spellVarName ) then

		refDefType		= refDefTypes.SPELL
		refDefVarName	= spellVarName

	else

		refDefType = refDefTypes.SRC

		if not UI:IsStrEmpty( subDefVarName ) then
			refDefVarName = subDefVarName
		end

	end


	local srcDef = nil

	if paramSrcType == UI.paramSrcTypes.SPELL then

		srcDef = UI:GetSpellDef( srcDefName )
    	if not srcDef then
    		sys.log( "UI:GetParamValByField()[ERROR]: cannot find _G.Spell[%s]", srcDefName )
    		return val
    	end

	elseif paramSrcType == UI.paramSrcTypes.SHIP_NODE then

		srcDef = _G.VesselProgress[ srcDefName ]
    	if not srcDef then
    		sys.log( "UI:GetParamValByField()[ERROR]: cannot find _G.VesselProgress[%s]", srcDefName )
    		return val
    	end

	else

		if UI:IsDefAutogen( srcDefName ) and paramSrcData and paramSrcData.autogen and paramSrcData.autogen.autogenDef then
			srcDef = paramSrcData.autogen.autogenDef
		else
			srcDef = UI:GetDef( srcDefName )
		end

    	if not srcDef then
    		sys.log( "UI:GetParamValByField()[ERROR]: cannot find _G.Def[%s]", srcDefName )
    		return val
    	end

	end

	local subDef = nil
	local subDefName = ""

	if not UI:IsStrEmpty( subDefVarName ) then

		subDefName = srcDef[ subDefVarName ]
		if type( subDefName ) ~= "string" then
			sys.log( "UI:GetParamValByField()[ERROR]: cannot find _G.Def[%s].%s referenced in param \"%s\" for item \"%s\"", srcDefName, subDefVarName, tostring( paramInfo.name ), srcDefName )
    		return val
		end

		subDef = UI:GetDef( subDefName )
		if not subDef then
			sys.log( "UI:GetParamValByField()[ERROR]: cannot find _G.Def[%s] referenced in param \"%s\" for item \"%s\"", subDefName, tostring( paramInfo.name ), srcDefName )
    		return val
		end

	end

	local refDefName = ""
	local refDef = nil
	local refDefPath = ""

	local spellIdx	= -1
	local numSpells	= 0

	if refDefType == refDefTypes.SRC then

		if subDef then
			refDef = subDef
			refDefName = subDefName
		else
			refDef = srcDef
			refDefName = srcDefName
		end

    	if paramSrcType == UI.paramSrcTypes.SPELL then

			local auraIdx = paramSrcData.auraIdx or 0

			if auraIdx == 0 then
				--refDefPath = string.format( "_G.Spell.%s", refDefName )
				refDefPath = "refDef"
			else
				-- refDefPath = string.format( "_G.Spell.%s.additional_auras[%d]", refDefName, auraIdx )
				refDefPath = string.format( "refDef.additional_auras[%d]", auraIdx )
			end

    	elseif paramSrcType == UI.paramSrcTypes.SHIP_NODE then

			if bNodeBonus then
				--refDefPath = string.format( "_G.VesselProgress.%s.special_grade", refDefName )
				refDefPath = "refDef.special_grade"
			else
    			--refDefPath = string.format( "_G.VesselProgress.%s", refDefName )
				refDefPath = "refDef"
			end

    	else
			--refDefPath = string.format( "_G.Def.%s", refDefName )
			refDefPath = "refDef"
		end

	elseif refDefType == refDefTypes.SPELL then

		local spellInfo = nil

		if subDef then
			spellInfo = subDef[ refDefVarName ]
		else
			spellInfo = srcDef[ refDefVarName ]
		end

		if type( spellInfo ) == "string" then

			refDefName	= spellInfo
			spellIdx	= 1
			numSpells	= 1

		elseif type( spellInfo ) == "table" then

			numSpells = #spellInfo

			if type( paramInfo.spellId ) == "number" then
				spellIdx = paramInfo.spellId

			elseif type( paramInfo.spellId ) == "table" then

				spellIdx = paramInfo.spellId[ refFieldIdx ]

				if type( spellIdx ) ~= "number" then
					sys.log( "UI:GetParamValByField()[ERROR]: invalid type of \"spellId[%d]\" in param \"%s\" for item \"%s\"; \"number\" expected, got \"%s\"", refFieldIdx, tostring( paramInfo.name ), srcDefName, type( spellIdx ) )
					spellIdx = -1
				end

			else
				sys.log( "UI:GetParamValByField()[ERROR]: invalid type of \"spellId\" in param \"%s\" for item \"%s\"; \"number\" or \"table\" expected, got \"%s\"", tostring( paramInfo.name ), srcDefName, type( paramInfo.spellId ) )
			end

			if spellIdx ~= -1 then

				refDefName = spellInfo[ spellIdx ]

				if type( refDefName ) ~= "string" then
					sys.log( "UI:GetParamValByField()[ERROR]: invalid type of \"_G.Def[%s].%s[%d]\" referenced in param \"%s\" for item \"%s\"; \"string\" expected, got \"%s\"", srcDefName, refDefVarName, spellIdx, tostring( paramInfo.name ), srcDefName, type( refDefName ) )
					refDefName	= ""
					spellIdx	= -1
				end

			end

		else
			sys.log( "UI:GetParamValByField()[ERROR]: invalid type of \"_G.Def[%s].%s\" referenced in param \"%s\" for item \"%s\"; \"string\" or \"table\" expected, got \"%s\"", srcDefName, refDefVarName, tostring( paramInfo.name ), srcDefName, type( spellInfo ) )
		end

		if refDefName ~= "" then

			refDef = UI:GetSpellDef( refDefName )
			if not refDef then
				sys.log( "UI:GetParamValByField()[ERROR]: cannot find spell def \"_G.Spell[%s]\" referenced in param \"%s\" for item \"%s\"", refDefName, tostring( paramInfo.name ), srcDefName )
			end

			--refDefPath = string.format( "_G.Spell.%s", refDefName )
			refDefPath = "refDef"

		else
			spellIdx = -1
		end

	else
		sys.log( "UI:GetParamValByField()[ERROR]: unhandled ref def type: %s", tostring( refDefType ) )
    	return val
	end


	if refDef then

		-- #0057824 - можно в качестве имени поля прописать путь, например: valField = "additional_auras[1].aura_param"
		-- но это не будет работать если valField будет использоваться для получения значения из других мест кроме дефа

		local strValGetFromPath = string.format( "local params = {...}; local refDef = params[1]; return %s.%s", refDefPath, refFieldName )
		val = assert( loadstring( strValGetFromPath ) )( refDef )	-- внутри refDef не виден, поэтому передается параметром

		-- у аур параметр модифицируется (скиллами, модулями и т.п.), поэтому берется не из дефинишена, а из энтити ауры;
		-- однако если в дефинишене он nil, то параметр вообще не показывается

		if paramSrcType == UI.paramSrcTypes.SPELL then

    		if paramInfo.name == "aura_param" and paramSrcData and paramSrcData.auraEnt and val ~= nil then
        		val = paramSrcData.auraEnt:GetAuraParam()
    		end

    	-- у кораблей параметр модифицируется (скиллами, модулями и т.п.), поэтому берется не из дефинишена, а из предоставленных данных
		-- однако если в дефинишене он nil, то параметр вообще не покаывается

    	elseif paramSrcType == UI.paramSrcTypes.SHIP or paramSrcType == UI.paramSrcTypes.MODULE then

			if paramSrcType == UI.paramSrcTypes.SHIP then

				local shipDefName = refDefName

				if synergyLevel ~= -1 then
					if refDef.special_grades ~= nil then
    					if type( refDef.special_grades ) == "table" then

							local synergyData = refDef.special_grades[ synergyLevel ]

							if synergyData ~= nil then
    							if type( synergyData ) ~= "table" then
    								sys.log( "UI:GetParamValByField()[ERROR]: invalid type of _G.Def[%s].special_grades[%d]; \"table\" or \"nil\" expected, got \"%s\"", shipDefName, synergyLevel, type( synergyData ) )
    								synergyData = nil
    							end
							end

							local synergyParams = synergyData

							if synergyData ~= nil then

                   				if UI:IsShipCraftable( shipDefName ) then

                   					-- формат поля данных для уровня синергии может быть разный;
                   					-- там могут быть как собственно моодификаторы в формате {имя_модификатора=значение},
                   					-- так и список имен бонусов, из которых игрок при крафте корабля выбирает один,
                   					-- а модификаторы хранятся уже в данных того бонуса;
                   					-- отлиается один формат от другого хаком -
                   					-- если есть целочисленные ключи в таблице, значит это массив, и значит это список имен бонусов

                   					local bIsBonusNamesArr = false

                   					for key, val in pairs( synergyData ) do
                   						if type( key ) == "number" then
                   							bIsBonusNamesArr = true
                   							break
                   						end
                   					end

                					if bIsBonusNamesArr then

                						synergyParams = {}

                						if selBonusName ~= "" then

                							if type( _G.ShipSpecBonus ) == "table" then

                								synergyParams = _G.ShipSpecBonus[ selBonusName ]

                								if type( synergyParams ) ~= "table" then
                									sys.log( "UI:GetParamValByField()[ERROR]: invalid type of \"_G.ShipSpecBonus[\"%s\"]\"; \"table\" expected, got \"%s\"", selBonusName, type( synergyParams ) )
                									synergyParams = nil
                								end

                							else
                								sys.log( "UI:GetParamValByField()[ERROR]: invalid type of \"_G.ShipSpecBonus\"; \"table\" expected, got \"%s\"", type( _G.ShipSpecBonus ) )
                							end

                						else
                							sys.log( "UI:GetParamValByField()[ERROR]: selected bonus for customizable level is not specified for ship \"%s\" level %d", shipDefName, synergyLevel )
                						end

									end

    							end

							end

							if synergyParams then
								val = synergyParams[ refFieldName ]
							end

    					else
    						sys.log( "UI:GetParamValByField()[ERROR]: invalid type of _G.Def[%s].special_grades; \"table\" or \"nil\" expected, got \"%s\"", shipDefName, type( refDef.special_grades ) )
						end
					end
				end

			end

			if paramSrcData and paramSrcData.params --[[and val ~= nil]] and synergyLevel == -1 then	-- #0069319,комм.(0290723) - наличие параметра в дефе необязательно

				local realVal = nil

				if refDefType == refDefTypes.SRC then

					if refDefVarName ~= "" then

						local realValFieldName = string.format( "%s.%s", refDefVarName, refFieldName )
						realVal = paramSrcData.params[ realValFieldName ]

					else
						realVal = paramSrcData.params[ refFieldName ]
					end

				elseif refDefType == refDefTypes.SPELL then

					if numSpells > 1 then

						if spellIdx ~= -1 and paramSrcData.params[ refDefVarName ] and paramSrcData.params[ refDefVarName ][ spellIdx ] then
    						realVal = paramSrcData.params[ refDefVarName ][ spellIdx ][ refFieldName ]
						end

					else

						if paramSrcData.params[ refDefVarName ] then
							realVal = paramSrcData.params[ refDefVarName ][ refFieldName ]
						end

					end

				else
					sys.log( "UI:GetParamValByField()[ERROR]: unhandled refDefType: %s", tostring( refDefType ) )
				end

				if realVal ~= nil then
					val = realVal
				end

			end

    	end

		if val == nil and not bAllowNilParams then
			val = 0
			sys.log( "UI:GetParamValByField()[ERROR]: cannot find field \"%s\" in \"%s\" referenced in param \"%s\" for item \"%s\"", refFieldName, refDefName, tostring( paramInfo.name ), srcDefName )
		end

	end

	return val

end


--
function UI:FixParamVal( paramInfo, val, bForceAbs )

	if type( paramInfo ) ~= "table" then
		sys.log( "UI:FixParamVal()[ERROR]: invalid type of the 1-st param (\"paramInfo\" ); \"table\" expected, fot \"%s\"", type( paramInfo ) )
		return 0
	end

	if val == nil then
		sys.log( "UI:FixParamVal()[ERROR]: nil 2-nd param (\"val\")" )
		return 0
	end

	if bForceAbs ~= nil then
		if type( bForceAbs ) ~= "boolean" then
			sys.log( "UI:FixParamVal()[ERROR]: invalid type of the 3-rd param; \"nil\" or \"boolean\" expected, got \"%s\"", type( bForceAbs ) )
			bForceAbs = false
		end
	else
		bForceAbs = false
	end

	if paramInfo.units == "metre" or paramInfo.units == "metre_per_second" or paramInfo.units == "metre_per_second_2" then
		val = val * 10

	elseif paramInfo.units == "percent" or paramInfo.units == "percent_per_second" then

		if val > 0 then
			val = val * 100

		elseif val < 0 then
			val = 100 / ( 1 - val ) - 100		-- #0018742
		end

	elseif paramInfo.units == "percent_minus" then

		if val < 0 then
			sys.log( "UI:FixParamVal()[ERROR]: negative val for percent_minus in \"%s\"", paramInfo.name )
		end

		val = 100 / ( 1 + val ) - 100

	end

	if val < 0 and ( bForceAbs or paramInfo.absValue == true ) then
		val = -val	-- #0024213 и  #0026878
	end

	-- #0029198 и #0033290
	if math.abs( val ) > 50 then
		val = UI:Round( val )
	end

	return val

end


--
function UI:ParamVal2Str( paramInfo, val )

	local strVal = ""

	if paramInfo.format then
		strVal = string.format( paramInfo.format, val )

	else
		local valRound = UI:Round( val * 10 ) / 10
		strVal = UI:FNum2StrSeparatedBy3( valRound )
	end

	return strVal

end


--
function UI:GetItemParamValAsStr( paramInfo, srcInfo, compareInfo, bUnits, valColor, baseColor, bForceAbs, paramsTable, bWithDeltaOnly, bShowOnlyDelta )

	srcInfo.dataType = UI.paramSrcTypes.MODULE

	if compareInfo then
		compareInfo.dataType = UI.paramSrcTypes.MODULE
	end

	return self:GetParamValAsStr( paramInfo, srcInfo, compareInfo, bUnits, valColor, baseColor, bForceAbs, paramsTable, bWithDeltaOnly, bShowOnlyDelta )

end


--
function UI:GetShipParamValAsStr( paramInfo, srcInfo, compareInfo, bUnits, valColor, baseColor, bForceAbs, paramsTable )

	srcInfo.dataType = UI.paramSrcTypes.SHIP

	if compareInfo then
		compareInfo.dataType = UI.paramSrcTypes.SHIP
	end

	return self:GetParamValAsStr( paramInfo, srcInfo, compareInfo, bUnits, valColor, baseColor, bForceAbs, paramsTable )

end


--
function UI:GetParamValAsStr( paramInfo, srcInfo, compareInfo, bUnits, valColor, baseColor, bForceAbs, paramsTable, bWithDeltaOnly, bShowOnlyDelta, synergyLevel, selBonusName, affixIdx )

	local vals, isValsFromAffix = self:GetParamVals( srcInfo.defName, paramInfo, srcInfo.dataType, srcInfo.data, false, synergyLevel, selBonusName, nil, affixIdx )
	local valsCompare	= UI:GetParamCompareVals( paramInfo, compareInfo, false, synergyLevel, selBonusName, #vals, srcInfo.defName )

	return UI:ParamVals2Str( paramInfo, vals, valsCompare, bUnits, valColor, baseColor, bWithDeltaOnly, bShowOnlyDelta, isValsFromAffix, bForceAbs )

end


--
function UI:GetParamCompareVals( paramInfo, compareInfo, bForceAbs, synergyLevel, selBonusName, numSrcVals, srcDefName )

	local valsCompare = nil

	if numSrcVals > 0 and compareInfo then

    	valsCompare = UI:GetParamVals( compareInfo.defName, paramInfo, compareInfo.dataType, compareInfo.data, bForceAbs, synergyLevel, selBonusName, nil )
		local numValsCompare = #valsCompare

		if numValsCompare > 0 then

			if numValsCompare ~= numSrcVals then
				valsCompare = nil
				numValsCompare = 0
	    		sys.log( "UI:GetParamCompareVals()[ERROR]: different number of params in main and in compare object; cannot perform comparing param \"%s\" in \"%s\" and \"%s\"", paramInfo.name, srcDefName, compareInfo.defName )
			end

		else
			valsCompare = nil
			numValsCompare = 0

			if paramsTable then

				local equalParamInfo = nil
				local equialParamNames = nil

				if compareInfo.dataType == UI.paramSrcTypes.MODULE then
					equialParamNames = _G.ItemTooltipsCompareEqualParams and _G.ItemTooltipsCompareEqualParams[ paramInfo.name ]
				end

				if equialParamNames then

    				for equalParamIdx, equalParamName in pairs( equialParamNames ) do

    					for idx, info in pairs( paramsTable ) do
    						if info.name == equalParamName then
    							equalParamInfo = info
    							break
    						end
    					end

        				if equalParamInfo then

                        	valsCompare = UI:GetParamVals( compareInfo.defName, equalParamInfo, compareInfo.dataType, compareInfo.data, bForceAbs, synergyLevel, selBonusName, nil )
                    		numValsCompare = #valsCompare

                    		if numValsCompare > 0 then

                    			if numValsCompare ~= numSrcVals then
                    				valsCompare = nil
                    				numValsCompare = 0
                    	    		sys.log( "UI:GetParamCompareVals()[ERROR]: different number of params in main and in compare object; cannot perform comparing param \"%s\" in \"%s\" and param \"%s\" in \"%s\"", paramInfo.name, srcDefName, equalParamInfo.name, compareInfo.defName )
                    			end

								break

							else
                                valsCompare = nil
        					end

        				end

					end
				end
			end
		end
	end

	return valsCompare

end


--
function UI:ParamVals2Str( paramInfo, vals, valsCompare, bUnits, valColor, baseColor, bWithDeltaOnly, bShowOnlyDelta, isValsFromAffix, bForceAbs )

	if bUnits == nil then
		bUnits = false
	end

	if bWithDeltaOnly == nil then
		bWithDeltaOnly = false
	end

	if bShowOnlyDelta == nil then
		bShowOnlyDelta = false
	end

	if isValsFromAffix == nil then
		isValsFromAffix = {}
	end

	local str = ""

	local numVals = #vals

	if valsCompare then
    	if #valsCompare ~= numVals then
    		sys.log( "UI:ParamVals2Str()[ERROR]: mismatch number of base vals and vals for comparing" )
    		valsCompare = nil
    	end
	end

	if valColor == nil then
		valColor = UI.TEXT_SEL_COLOR
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	local tStr = {}
	local strValColor = UI:Color2Str( valColor )
	local strBaseColor = UI:Color2Str( baseColor )
	local bHasDelta = false

	for valIdx = 1, numVals do

		local val		= vals[ valIdx ]
		local valDelta	= nil

		if valsCompare then

			local valCompare = valsCompare[ valIdx ]

        	if math.abs( val - valCompare ) >= 1e-2 then
				valDelta = val - valCompare
        	end

		end

		if valDelta then
			bHasDelta = true
		end

		local strVal = ""

		if not bWithDeltaOnly or valDelta then

    		if not bShowOnlyDelta then

    			strVal = UI:ParamVal2Str( paramInfo, bForceAbs and math.abs( val ) or val )

				local bFromAffix = isValsFromAffix[ valIdx ] or false
				local strColor = bFromAffix and UI:Color2Str( UI.AUTOGEN_AFFIX_COLOR ) or strValColor	-- для значений, кторые берутся мз аффиксов - отдельный цвет

            	strVal = string.format( "%s%s%s", strColor, strVal, strBaseColor )

    		end

    		if valDelta then

    			local bIsNegativeParam = false

    			if paramInfo.negative ~= nil then

					if type( paramInfo.negative ) == "boolean" then
						bIsNegativeParam = paramInfo.negative

					elseif type( paramInfo.negative ) == "table" then

						if type( paramInfo.negative[ valIdx ] ) == "boolean" then
							bIsNegativeParam = paramInfo.negative[ valIdx ]
						else
							sys.log( "UI:ParamVals2Str()[ERROR]: invalid type of \"negative[%d]\" for param \"%s\"; \"boolean\" expected, got \"%s\"", valIdx, paramInfo.name, type( paramInfo.negative[ valIdx ] ) )
						end

					else
						sys.log( "UI:ParamVals2Str()[ERROR]: invalid type of \"negative\" for param \"%s\"; \"boolean\" or \"table\" expected, got \"%s\"", paramInfo.name, type( paramInfo.negative ) )
					end

				end


    			local bIsBetter = ( bIsNegativeParam and valDelta < 0 ) or ( not bIsNegativeParam and valDelta > 0 )

    			local strValDelta = UI:ParamVal2Str( paramInfo, math.abs( valDelta ) )
    			strValDelta = string.format( "%s%s%s%s", bShowOnlyDelta and "" or "(", valDelta > 0 and "+" or "-", strValDelta, bShowOnlyDelta and "" or ")" )

    			if valColor then
    				local deltaColor = bIsBetter and UI.PARAM_DELTA_PLUS_COLOR or UI.PARAM_DELTA_MINUS_COLOR
    				strValDelta = string.format( "%s%s%s", UI:Color2Str( deltaColor ), strValDelta, strBaseColor )
    			end

    			strVal = string.format( "%s%s", strVal, strValDelta )

    		end

		end

		-- индивидуальные единицы измерения для каждого значения (могут быть общие, тогда они обрабтаются после всех значений)

		if strVal ~= "" and bUnits then

    		local strValUnits = UI:ParamUnits2Str( paramInfo, valIdx )
			if strValUnits ~= "" then
    			strVal = string.format( "%s %s", strVal, strValUnits )
			end

		end

		tStr[ valIdx ] = strVal

	end


	-- fix delta

	if bWithDeltaOnly and not bHasDelta then
		return str
	end

	if bShowOnlyDelta then

		local bHasNotEmptyDelta = false

		for strIdx, _str in pairs( tStr ) do
			if not UI:IsStrEmpty( _str ) then
				bHasNotEmptyDelta = true
				break
			end
		end

		if bHasNotEmptyDelta then
			for strIdx = 1, #tStr do
				if UI:IsStrEmpty( tStr[ strIdx ] ) then
					tStr[ strIdx ] = string.format( "%s0%s", strValColor, strBaseColor )
				end
			end
		else
			tStr = {}
		end

	end

	local numStr = #tStr
	if numStr > 1 then

		if type( paramInfo.concat ) == "string" then
			str = string.format( paramInfo.concat, unpack( tStr ) )
		else
			sys.log( "UI:ParamVals2Str()[ERROR]: cannot find \"concat\" in param \"%s\" or it is of invalid type", tostring( paramInfo.name ) )
			str = table.concat( tStr, ", " )
		end

	elseif numStr == 1 then
		str = tStr[ 1 ]
	end

	-- общие единицы измерения для всех значений (могут быть индивидуальные для каждого значения, тогда они уже добавились при обработке этого значения)

	if str ~= "" and bUnits then

		local strUnits = UI:ParamUnits2Str( paramInfo, -1 )
		if strUnits ~= "" then
			str = string.format( "%s %s", str, strUnits )
		end

	end

	if str ~= "" then
		str = string.format( "%s%s", strBaseColor, str )
	end

	return str

end


-- если valIdx=nil или valIdx=-1, то возвращаются единицы измерения, если в таблице они описаны в виде строки (то есть являются общими для всех параметров);
-- при других значениях valIdx - если единицы измерения описаны в виде таблицы

function UI:ParamUnits2Str( paramInfo, valIdx )

	local str = ""

	if type( paramInfo ) ~= "table" then
		sys.log( "UI:ParamUnits2Str()[ERROR]: invalid type of the 1-st parameter (\"paramInfo\"); \"table\" expected, got \"%s\"", type( paramInfo ) )
		return str
	end

	if valIdx ~= nil then
    	if type( valIdx) ~= "number" then
    		sys.log( "UI:ParamUnits2Str()[ERROR]: invalid type of the 2-nd parameter (\"valIdx\"); \"number\" or \"nil\" expected, got \"%s\"", type( valIdx ) )
			valIdx = nil
    	end
	end

	if valIdx == nil then
		valIdx = -1
	end

	local unitsName = ""

	if paramInfo.units ~= nil then

    	if type( paramInfo.units ) == "string" then

			if valIdx == -1 then
				unitsName = paramInfo.units
			end

    	elseif type( paramInfo.units ) == "table" then

			if valIdx ~= -1 then

				local paramUnitsName = paramInfo.units[ valIdx ]
				if paramUnitsName ~= nil then

					if type( paramUnitsName ) == "string" then
						unitsName = paramUnitsName
					else
						sys.log( "UI:ParamUnits2Str()[ERROR]: invalid type of the \"units[%d]\" in param \"%s\"; \"string\" expected, got \"%s\"", valIdx, tostring( paramInfo.name ), type( paramUnitsName ) )
					end

				end

			end

    	else
    		sys.log( "UI:ParamUnits2Str()[ERROR]: invalid \"units\" type in param \"%s\"; \"string\", \"table\" or \"nil\" expected, got \"%s\"", tostring( paramInfo.name ), type( paramInfo.units ) )
    	end

	end

	if unitsName ~= "" then
		str = UI:GetStringByName( string.format( "units_%s", unitsName ) )
	end

    return str

end


