--
function UI:GetTier( defName )

	local tier = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetTier()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return tier
	end

	if defName == "" then
		sys.log( "UI:GetTier()[ERROR]: empty defName" )
		return tier
	end

	if UI:IsDefTokenItem( defName ) then

    	local dstDefName = UI:GetTokenItemDstDefName( defName )
    	if dstDefName ~= "" then
			return UI:GetTier( dstDefName )
		else
    		sys.log( "UI:GetTier()[ERROR]: cannot find dst def for token-item \"%s\"", defName )
    		return tier
    	end
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetTier()[ERROR]: cannot find \"_G.Def[%s]\"", defName )
		return tier
	end

	local isShip = _G.IsClassKindOf( def.class, "SpaceShip" )

	if isShip then
		tier = def.ship_tier
	else
		tier = def.tier
	end

	if tier == nil or tier == 0 then
		tier = -1
	end

	return tier

end


