--
function UI:CalcMaxReputation( reps )

	local repMax = 0

	if type( reps ) ~= "table" then
		sys.log( "UI:CalcMaxReputation()[ERROR]: invalid type of the 1-st parameter (\"reps\"); \"table\" expected, got \"%s\"", type( reps ) )
		return repMax
	end

	for key, rep in pairs( reps ) do
		if rep > repMax then
			repMax = rep
		end
	end

	return repMax

end


