end


-- returns title, curVal, nextVal, rank
function UI:Reputation2TitleAndProgress( reputation )

	if not reputation then
		sys.log( "UI:Reputation2TitleAndProgress()[ERROR]: nil param" )
		return "", 0, 0, -1
	end

	if not ai.Reputation or not next( ai.Reputation ) then
		return "", 0, 0, -1
	end

	local rank = -1
	for idx = #ai.ReputationByRank, 1, -1 do

		local val = ai.ReputationByRank[ idx ]

		if reputation >= val then
			rank = idx
			break
		end

	end

	if rank == -1 then
		sys.log( "UI:Reputation2TitleAndProgress()[ERROR]: cannot find rank for reputation %d", reputation )
		return "", reputation, 0, -1
	end

	local curRep	= ai.ReputationByRank[ rank ]
	local nextRep	= ai.ReputationByRank[ rank + 1 ]
	local title		= UI:Val2Key( ai.Reputation, curRep )

	return title, reputation - curRep, nextRep and nextRep - curRep or 0, rank

end


