--
function UI:GetLockedBattleSlotTooltipData( slotIdx )

	local tipText		= ""
	local tipCaption	= UI:GetStringByName( "lockedBattleSlotTip_caption" )

	if slotIdx > self.serverData.battleSlotsCount then

		tipText = UI:GetStringByName( "lockedBattleSlotTip_outOfOrder" )

	else

		local rank = self.serverData.battleSlotsRankReq[ slotIdx ] or 1
		local strRank = string.format( "%s[%d]%s", UI:Color2Str( UI.TEXT_SEL_COLOR ), rank, UI:Color2Str( UI.TEXT_BASE_COLOR ) )

		tipText = UI:GetStringByName( "shipsTree_accountRankRequired" )
		tipText = string.gsub( tipText, "%$rank%$", strRank )

	end

	return { tooltipType = UI.tooltipTypes.TEXT_LARGE, text = tipText, caption = tipCaption }

end


--
function UI:UpdateTooltip( dt )

	local bCursorHidden = _G.IsCursorHidden()

	if not bCursorHidden then

		if self.tooltipWaitTime ~= -1 then
			self.tooltipWaitTime = self.tooltipWaitTime + dt
		end

	else
		self.tooltipWaitTime = 0
	end

	if _G.TextPicker_IsActive() then
		return
	end

	local mouseX = UI:GetMouseX()
	local mouseY = UI:GetMouseY()

	local targetWnd = nil

	if not bCursorHidden then

    	if UI:NeedInput() or ( UI.HudWnd and UI.HudWnd:IsOnScreen() and UI:IsChatInput() ) then
    		targetWnd = UI:FindWindowUnderMouse( UI.Root, mouseX, mouseY, true )
    	end

	end

	local hTargetWnd = targetWnd and targetWnd:GetUiHandle() or UI.INVALID_UI_HANDLE

	if hTargetWnd ~= self.tooltipInfo.hTargetWnd then

    	if self.tooltipInfo.hTargetWnd ~= UI.INVALID_UI_HANDLE then
        	self:ResetTooltip()
		end

    	if not targetWnd or not targetWnd.GetTooltipData then
    		return
    	end

		local tooltipData = targetWnd:GetTooltipData()
		if not tooltipData then
			return
		end

		local delay = tooltipData.tooltipDelay or self.TOOLTIP_DELAY

		if self.tooltipWaitTime >= delay then

			local hTooltipWnd	= UI.INVALID_UI_HANDLE
			local bHandled		= false

			local handlerWnd = self:GetTooltipHandlerWnd( targetWnd )
			while handlerWnd do

       			bHandled, hTTWnd = handlerWnd:HandleTooltip( targetWnd, tooltipData )
				if bHandled then
					hTooltipWnd = hTTWnd
					break
				end

				handlerWnd = self:GetTooltipHandlerWnd( handlerWnd:GetParent() )

			end

			if bHandled then

    			if hTooltipWnd == UI.INVALID_UI_HANDLE then
    				return
    			end

			-- handle by self
			else

				hTooltipWnd	= self:GetDefaultTooltipWnd( tooltipData.tooltipType )

				if hTooltipWnd ~= UI.INVALID_UI_HANDLE then
    				local tooltipWnd = UI:GetUiObjByHandleT( hTooltipWnd )
    				tooltipWnd:Setup( tooltipData )
				else
					return
				end

			end

           	self.tooltipInfo.hTargetWnd		= hTargetWnd
   			self.tooltipInfo.hTooltipWnd	= hTooltipWnd
       		self.tooltipInfo.mousePos_abs.x	= UI:XToAbs( mouseX )
       		self.tooltipInfo.mousePos_abs.y	= UI:YToAbs( mouseY )

			local tooltipWnd = UI:GetCurTooltip()

   			self:ShowWindow( hTooltipWnd )
			self:PlaceTooltipOnScreen( tooltipWnd, tooltipData )

			if tooltipWnd then

				local tooltipRect = tooltipWnd:GetRect()

				if UI:IsPtInRect( tooltipRect, mouseX, mouseY ) then
					self.tooltipInfo.bMouseOverTooltip = true
				end

			end

		end

	else

		--#0034328

		-- мышь над тем же окном

		if self.tooltipInfo.hTargetWnd ~= UI.INVALID_UI_HANDLE then

			-- тултип еще не был показан -> при движении мыши ожидание прерываем
			if self.tooltipInfo.hTooltipWnd == UI.INVALID_UI_HANDLE then

            	local mouseX_abs	= UI:XToAbs( mouseX )
            	local mouseY_abs 	= UI:YToAbs( mouseY )

            	local dir = UI:Vec2( mouseX_abs - self.tooltipInfo.mousePos_abs.x, mouseY_abs - self.tooltipInfo.mousePos_abs.y )
            	local distSq_abs = UI:V2LengthSq( dir )

    			local mouseThreshold_abs = UI:XToAbs( UI:XTo1024x768( UI.TOOLTIP_MOUSE_THRESHOLD, { x = 1280, y = 720 } ) )
            	if distSq_abs > mouseThreshold_abs * mouseThreshold_abs then
            		self:ResetTooltip()
            	end

			-- тултип уже показывается -> если мышь не выходит за пределы исходного окна и не заходит на тултип, он не скрывается;
			-- если мышь зашла на тултип (или сдвинулась, если она на нем изначально была), то тултип скрывается
			else

				if self.bMouseMove then

        			local tooltipWnd = UI:GetCurTooltip()
        			if tooltipWnd then

        				local tooltipRect = tooltipWnd:GetRect()
        				if UI:IsPtInRect( tooltipRect, mouseX, mouseY ) then

        					if self.tooltipInfo.bMouseOverTooltip then

                            	local mouseX_abs	= UI:XToAbs( mouseX )
                            	local mouseY_abs 	= UI:YToAbs( mouseY )

                            	local dir = UI:Vec2( mouseX_abs - self.tooltipInfo.mousePos_abs.x, mouseY_abs - self.tooltipInfo.mousePos_abs.y )
                            	local distSq_abs = UI:V2LengthSq( dir )

                    			local mouseThreshold_abs = UI:XToAbs( UI:XTo1024x768( UI.TOOLTIP_MOUSE_THRESHOLD, { x = 1280, y = 720 } ) )
                            	if distSq_abs > mouseThreshold_abs * mouseThreshold_abs then
                            		self:ResetTooltip()
                            	end

    						else
    			            	self:ResetTooltip()
    						end

        				end

        			end

				end

			end

		end

	end

end


--
function UI:GetCurTooltipTarget()

	if self.tooltipInfo.hTargetWnd ~= UI.INVALID_UI_HANDLE then
		return UI:GetUiObjByHandleT( self.tooltipInfo.hTargetWnd )
	else
		return nil
	end

end


--
function UI:GetCurTooltipTargetHandle()

	return self.tooltipInfo.hTargetWnd

end


--
function UI:GetCurTooltip()

	if self.tooltipInfo.hTooltipWnd ~= UI.INVALID_UI_HANDLE then
		return UI:GetUiObjByHandleT( self.tooltipInfo.hTooltipWnd )
	else
		return nil
	end

end


--
function UI:GetCurTooltipHandle()

	return self.tooltipInfo.hTooltipWnd

end


--
function UI:ResetTooltip()

	if self.tooltipInfo.hTooltipWnd ~= UI.INVALID_UI_HANDLE then
		self:HideWindow( self.tooltipInfo.hTooltipWnd )
	end

	self.tooltipInfo.hTargetWnd			= UI.INVALID_UI_HANDLE
	self.tooltipInfo.hTooltipWnd		= UI.INVALID_UI_HANDLE
	self.tooltipInfo.mousePos_abs.x		= 0
	self.tooltipInfo.mousePos_abs.y 	= 0
	self.tooltipInfo.bMouseOverTooltip	= false

end


--
function UI:GetTooltipHandlerWnd( startWnd )

	if not startWnd then
		return nil
	end

	local tipHandlerWnd = nil

	local wnd = startWnd
	while wnd do

		if wnd.HandleTooltip then
			tipHandlerWnd = wnd
			break
		end

		wnd = wnd:GetParent()
	end

	return tipHandlerWnd

end


--
function UI:GetDefaultTooltipWnd( tooltipType )

	local hDefaultTooltipWnd = UI.INVALID_UI_HANDLE

	local defaultTooltipName = self.defaultTooltipNames[ tooltipType ]
	if not defaultTooltipName then
		sys.log( "UI:GetDefaultTooltipWnd()[ERROR]: cannot find tooltip for type: %s", tostring( tooltipType ) )
		return hDefaultTooltipWnd
	end

	local tooltipWnd = UI[ defaultTooltipName ]
	if tooltipWnd then
		hDefaultTooltipWnd = tooltipWnd:GetUiHandle()
	else
		sys.log( "UI:Init()[ERROR]: cannot find tooltip wnd \"%s\"", defaultTooltipName )
	end

	return hDefaultTooltipWnd

end


--
function UI:PlaceTooltipOnScreen( tooltipWnd, tooltipData )

	if not tooltipWnd then
		sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: no tooltipWnd"  )
		return
	end

	local placementRule = UI.tooltipPlacementRules.DEFAULT

	-- тултип корабля - это сложное образование из нескольких тултипов (сравнение кораблей, тултипы спецмодулей и их сравнение);
	-- он сам размещает себя на экране; не поддерживается его размещение кем-либо еще
	if tooltipData.tooltipType == UI.tooltipTypes.SHIP then
		placementRule = UI.tooltipPlacementRules.DONT_TOUCH
	end

	local anchorPos = nil
	local hAlignment = nil
	local vAlignment = nil

	-- в tooltipData.tooltipPlacement хранятся данные о способах размещения, назначенные туда окном, на котором показывается тултип

	local tooltipPlacement = tooltipData and tooltipData.tooltipPlacement
	if tooltipPlacement ~= nil then

		if type( tooltipPlacement ) == "table" then

			if type( tooltipPlacement.placementRule ) == "number" and UI:Val2Key( UI.tooltipPlacementRules, tooltipPlacement.placementRule ) ~= "" then

				placementRule = tooltipPlacement.placementRule

				-- в tooltipPlacement хранится точка привязки, и как относительно нее размещать
				if tooltipPlacement.placementRule == UI.tooltipPlacementRules.ALIGNMENT_DATA then

					anchorPos = tooltipPlacement.anchorPos
					hAlignment = tooltipPlacement.hAlignment
					vAlignment = tooltipPlacement.vAlignment

				-- в tooltipPlacement хранится функция, которая вернет точку привязки, и как относительно нее размещать
				elseif tooltipPlacement.placementRule == UI.tooltipPlacementRules.ALIGNMENT_FUNCTION then

					if type( tooltipPlacement.fnGetAlignment ) == "function" then
						anchorPos, hAlignment, vAlignment = tooltipPlacement.fnGetAlignment( tooltipWnd, tooltipData )
					else
						sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: invalid type of 'tooltipPlacement.fnGetAlignment'; 'function' expectd, got '%s'", type( tooltipPlacement.fnGetAlignment ) )
					end

				end

			else
				sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: invalid 'tooltipPlacement.placementRule' (%s)", tostring( tooltipPlacement.placementRule ) )
			end

		else
			sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: invalid type of 'tooltipPlacement'; 'table' or 'nil' expectd, got '%s'", type( tooltipPlacement ) )
		end

	end

	if tooltipData.tooltipType == UI.tooltipTypes.SHIP then
		if placementRule ~= UI.tooltipPlacementRules.DONT_TOUCH then
			sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: not support placement rule othe than DONT_TOUCH for ship tooltips" )
			placementRule = UI.tooltipPlacementRules.DONT_TOUCH
		end
	end

	-- вообще никак не влиять на позицию тутипа, тулипт сам себя будет размещать или кто-либо еще
	if placementRule == UI.tooltipPlacementRules.DONT_TOUCH then
		return
	end

	local pos = Vec2( 0, 0 )

	local tooltipWidth = tooltipWnd:GetWidth()
	local tooltipHeight = tooltipWnd:GetHeight()

	local mouseX = UI:GetMouseX()
	local mouseY = UI:GetMouseY()

	-- по умолчанию
	if placementRule == UI.tooltipPlacementRules.DEFAULT then

		pos = Vec2( UI:GetTooltipDefaultPos( tooltipWidth, tooltipHeight ) )

	else

		-- есть точка привязки и как относительно нее размещать - слева справа/по центру и сверху/снизу/по центру

		local bValid = true

		if type( anchorPos ) ~= "userdata" or type( anchorPos.x ) ~= "number" or type( anchorPos.y ) ~= "number" then
			sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: invalid type of 'anchorPos'; 'userdata' (Vec2) expectd, got '%s'", type( anchorPos ) )
			bValid = false
		end

		if type( hAlignment ) ~= "number" or UI:Val2Key( UI.hAlignments, hAlignment ) == "" then
			sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: invalid 'hAlignment' (%s)", tostring( hAlignment ) )
			bValid = false
		end

		if type( vAlignment ) ~= "number" or UI:Val2Key( UI.vAlignments, vAlignment ) == "" then
			sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: invalid 'vAlignment' (%s)", tostring( vAlignment ) )
			bValid = false
		end

		if bValid then

			if hAlignment == UI.hAlignments.LEFT then
				pos.x = anchorPos.x - tooltipWidth

			elseif hAlignment == UI.hAlignments.RIGHT then
				pos.x = anchorPos.x

			elseif hAlignment == UI.hAlignments.CENTER then
				pos.x = anchorPos.x - tooltipWidth / 2
			end


			if vAlignment == UI.vAlignments.TOP then
				pos.y = anchorPos.y - tooltipHeight

			elseif vAlignment == UI.vAlignments.BOTTOM then
				pos.y = anchorPos.y

			elseif vAlignment == UI.vAlignments.CENTER then
				pos.y = anchorPos.y - tooltipHeight / 2
			end

		else

			pos = Vec2( UI:GetTooltipDefaultPos( tooltipWidth, tooltipHeight ) )

		end

	end

	-- справшиваем у самого тултипа, как он сам может повлиять на свое размещение
	-- (некоторые тутипы имеют вторичные тултипы, и, соответственно, при их показе корректируют свою позицию)

	local finalPos = pos

	if tooltipWnd.OnPlaceTooltipOnScreen then

		finalPos = tooltipWnd:OnPlaceTooltipOnScreen( Vec2( pos ), tooltipData )

		if type( finalPos ) ~= "userdata" then
			sys.log( "UI:PlaceTooltipOnScreen()[ERROR]: invalid return type from OnPlaceTooltipOnScreen() for tooltip '%s'; 'userdata' expected, got '%s'", tooltipWnd:GetName(), type( finalPos ) )
			finalPos = pos
		end

	end

	tooltipWnd:SetPos( finalPos.x, finalPos.y )

end


--
function UI:GetTooltipDefaultPos( tooltipWidth, tooltipHeight )

	local mouseX	= UI:GetMouseX()
	local mouseY	= UI:GetMouseY()

	local resolution = { x = 1280, y = 720 }
	local spaceX = UI:YTo1024x768( self.TOOLTIP_SPACE_X, resolution )
	local spaceY = UI:YTo1024x768( self.TOOLTIP_SPACE_Y, resolution )

	local x = mouseX + spaceX
	local y = mouseY - tooltipHeight - spaceY

	local maxRect = UI:Quat( 0, 0, 1024, 768 )

	if x < maxRect.x then
		x = maxRect.x
	end

	if x + tooltipWidth > maxRect.x + maxRect.z then
		x = ( maxRect.x + maxRect.z ) - tooltipWidth
	end

	if y < maxRect.y then
		y = mouseY + self:GetCursorHeight() + spaceY
	end

	if y + tooltipHeight > maxRect.y + maxRect.w then
		y = ( maxRect.y + maxRect.w ) - tooltipHeight
	end

	return UI:Vec2( x, y )

end


--
function UI:TryHideTooltipOnRMouse()

	if self.tooltipInfo.hTooltipWnd ~= UI.INVALID_UI_HANDLE or self.tooltipWaitTime ~= -1 then
		UI:ResetTooltip()
		self.tooltipWaitTime = -1
	end

end


--
function UI:GetCursorHeight()

	local hCusor = UI:GetCurrentCursor()

	if hCusor ~= UI.INVALID_RESOURCE_HANDLE then
		local cursor = UI:GetCursorByHandle( hCusor )
		if cursor then
			return cursor:GetHeight()
		end
	end

	return 0

end


--
function UI:ServerDataUpdate_OnLoadingComplete( storeSize )

	self.serverData.shop						= {}
    self.serverData.shopByDef					= {}
	self.serverData.craftResult2Blueprints		= {}
	self.serverData.accountAura2UnlockedItems	= {}
	self.serverData.item2Bundles				= {}

	self.serverData.currencyRate = _G.GameStore_GetGoldExchangeRate()
	self.serverData.yupExchangeCfs = _G.GameStore_GetYupConversionCf()

    self.serverData.shop = _G.GameStore_GetStore()

	for idx, item in pairs( self.serverData.shop ) do

		if self.serverData.shopByDef[ item.defName ] then
			sys.log( "UI:ServerDataUpdate_OnLoadingComplete()[ERROR]: items with duplicate defName - \"%s\"", item.defName )
		else
			self.serverData.shopByDef[ item.defName ] = item
		end

		-- tODO: почему это здесь?? Это зависит не от сервера и магазина, а от дефов

		if item.type == _G.GameStore.ItemType.IT_BLUEPRINT then

			local craftResultDefName, craftResultCount = UI:GetResourceCraftResult( item.defName )
			if craftResultDefName ~= "" then

				-- один предмет может крафтиться несколькими чертежами #0111179(0521078)
				if self.serverData.craftResult2Blueprints[ craftResultDefName ] == nil then
					self.serverData.craftResult2Blueprints[ craftResultDefName ] = {}
				end
				table.insert( self.serverData.craftResult2Blueprints[ craftResultDefName ], item.defName )

			else
				sys.log( "UI:ServerDataUpdate_OnLoadingComplete( storeSize )[ERROR]: cannot find craft result for blueprint \"%s\"", item.defName )
			end

		end

		local unlockingAccountAura = UI:GetAccountAuraToUnlockItem( item.defName )
		if unlockingAccountAura ~= "" then

			local unlockedItems = self.serverData.accountAura2UnlockedItems[ unlockingAccountAura ]
			if not unlockedItems then
				unlockedItems = {}
				self.serverData.accountAura2UnlockedItems[ unlockingAccountAura ] = unlockedItems
			end

			table.insert( unlockedItems, item.defName )

		end

		if item.type == _G.GameStore.ItemType.IT_BUNDLE then

			local bundleContent = UI:GetBundleUiContent( item.defName, false )
			for blockIdx, blockInfo in pairs( bundleContent ) do

				for bundleItemIdx, bundleItemInfo in pairs( blockInfo ) do

					if	bundleItemInfo.type == ai.BundleContent.ITEM
						or bundleItemInfo.type == ai.BundleContent.VESSEL
						or bundleItemInfo.type == ai.BundleContent.CRAFT_RESOURCE
						or bundleItemInfo.type == ai.BundleContent.BLUEPRINT then

							if not self.serverData.item2Bundles[ bundleItemInfo.defName ] then
								self.serverData.item2Bundles[ bundleItemInfo.defName ] = {}
							end

							table.insert( self.serverData.item2Bundles[ bundleItemInfo.defName ], item.defName )
					end

				end

			end

		end

	end

	self:UpdateGoldPacksInfo()

	self.serverData.creditsInfo = _G.GameStore_GetCreditPacksInfo() or {}
	for idx, info in pairs( self.serverData.creditsInfo ) do
		info.id = idx - 1
	end

	self.serverData.inventoryLevelsInfo = _G.GameStore_GetInventoryExtensionsInfo()
	self.serverData.autogenInventoryLevelsInfo = _G.GameStore_GetAutogenInventoryExtensionsInfo()

	-- запрос цен на юплей покупки (премиум-лицензии в том числе)
	UI:RequestYupPurchasesPrices( true )

	UI:UpdateShipsNextDisableTimes()

end


--
function UI:UpdateGoldPacksInfo()

	self.serverData.goldPacksInfo = _G.GameStore_GetGoldPacksInfo() or {}

	for idx, goldPackInfo in pairs( self.serverData.goldPacksInfo ) do
		goldPackInfo.id = idx - 1
	end

end


--
function UI:CompareDefs( defName1, defName2, bDesc, bIgnoreCategories )

	local def1 = UI:GetDef( defName1 )
	local def2 = UI:GetDef( defName2 )

	if not def1 then
		return false
	end

	if not def2 then
		return true
	end

	-- 1. по категории магазина

	if not bIgnoreCategories then

		local mainCategoryIdxInfo1 = def1.shopCategory and StoreInfo.categoryName2Idx[ def1.shopCategory ]
		local mainCategoryIdxInfo2 = def2.shopCategory and StoreInfo.categoryName2Idx[ def2.shopCategory ]

		local mainCategoryIdx1 = mainCategoryIdxInfo1 and mainCategoryIdxInfo1.idx or -1
		local mainCategoryIdx2 = mainCategoryIdxInfo2 and mainCategoryIdxInfo2.idx or -1

		if mainCategoryIdx1 ~= mainCategoryIdx2 then
			return mainCategoryIdx1 < mainCategoryIdx2
		end

		local subCategoryIdx1 = def1.shopSubCategory and mainCategoryIdxInfo1 and mainCategoryIdxInfo1.sub[ def1.shopSubCategory ] or -1
		local subCategoryIdx2 = def2.shopSubCategory and mainCategoryIdxInfo2 and mainCategoryIdxInfo2.sub[ def2.shopSubCategory ] or -1

		if subCategoryIdx1 ~= subCategoryIdx2 then
			return subCategoryIdx1 < subCategoryIdx2
		end

	end

	-- 2. по полю item_subtype (если есть)

	local subType1 = def1.item_subtype or 0
	local subType2 = def2.item_subtype or 0

	if subType1 ~= subType2 then
		return subType1 < subType2
	end

	-- 3. по рангу (если есть)

	local rank1 = def1.rank
	local rank2 = def2.rank

	if rank1 == nil or rank1 == 0 then
		rank1 = -1
	end

	if rank2 == nil or rank2 == 0 then
		rank2 = -1
	end

	if rank1 ~= rank2 then
		if bDesc then
			return rank1 > rank2
		else
			return rank1 < rank2
		end
	end

	-- 4. по item_lvl (если есть)

	local itemLevel1 = def1 and def1.item_lvl or 0
	local itemLevel2 = def2 and def2.item_lvl or 0

	if itemLevel1 ~= itemLevel2 then
		if bDesc then
			return itemLevel1 > itemLevel2
		else
			return itemLevel1 < itemLevel2
		end
	end

	-- 5. по цене (сначала по серебру, потом по золоту)

	local price1, isPremium1 = UI:GetShopBaseBuyPriceByDef( defName1, true, false )
	local price2, isPremium2 = UI:GetShopBaseBuyPriceByDef( defName2, true, false )

	if isPremium1 ~= isPremium2 then

		if not isPremium1 and isPremium2 then
			return ( not bDesc )
		end

		if isPremium1 and not isPremium2 then
			return bDesc
		end

	end

	if price1 ~= price2 then

		if bDesc then
			return price1 > price2
		else
			return price1 < price2
		end

	end

	-- 6. по defName

	return defName1 < defName2

end


--
UI.ShopSortObjPred = {}
function UI.ShopSortObjPred:GetCompareFn( bDesc, bIgnoreCategories )

	local fnCompare = function( item1, item2 )
		return UI:CompareDefs( item1.defName, item2.defName, bDesc, bIgnoreCategories )
	end

	return fnCompare

end


--
UI.DefsSortObjPred = {}
function UI.DefsSortObjPred:GetCompareFn( bDesc, bIgnoreCategories )

	local fnCompare = function( defName1, defName2 )
		return UI:CompareDefs( defName1, defName2, bDesc, bIgnoreCategories )
	end

	return fnCompare

end


--
function UI:SortShop( shopItems, bDesc, bIgnoreCategories, sortObjPred )

	if bIgnoreCategories == nil then
		bIgnoreCategories = false
	end

	if not sortObjPred then
		sortObjPred = UI.ShopSortObjPred
	end

	local fnCompare = sortObjPred:GetCompareFn( bDesc, bIgnoreCategories )
	table.sort( shopItems, fnCompare )

	return shopItems

end


--
function UI:SortDefs( defNames, bDesc, bIgnoreCategories, sortObjPred )

	if bIgnoreCategories == nil then
		bIgnoreCategories = false
	end

	if not sortObjPred then
		sortObjPred = UI.DefsSortObjPred
	end

	local fnCompare = sortObjPred:GetCompareFn( bDesc, bIgnoreCategories )
	table.sort( defNames, fnCompare )

	return defNames

end


--
function UI:UpdateServerData_OnInventory( result, requestId, param1, param2 )

	if result == 0 then
		self:OnInventoryChanged()
	end

	requestId = self.INVENTORY_REQUEST_ID
	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


