--
function UI:UpdateServerData_OnUpgradeAutogenItem( result, requestId, params )

	if result == 0 then
		self:OnAutogenInventoryChanged()
	end

	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:UpdateServerData_OnSellVessel( result, requestId, param1, param2 )

	if result == 0 then

    	local vid = u64( param1, param2 )

    	local shipItemIdx	= -1
		local shipItem		= nil

    	for idx, item in pairs( self.serverData.allShips ) do
    		if item.vid == vid then
				shipItemIdx	= idx
				shipItem	= item
				break
    		end
    	end

		if shipItem then

    		if UI:IsShipCraftable( shipItem.defName ) then

            	shipItem.equipModules	= {}
        	    shipItem.equipAmmo		= {}

				table.remove( self.serverData.allShips, shipItemIdx )

    		else

        		shipItem.conserved		= true
            	shipItem.equipModules	= _G.GameStore_GetEquipmentIids( shipItem.vid )
        	    shipItem.equipAmmo		= _G.GameStore_GetMunition( shipItem.vid )

    		end

        	self:UpdateIid2Ship( shipItem )

		else
			sys.log( "UI:UpdateServerData_OnSellVessel()[ERROR]: cannot find ship item" )
		end

    	for idx, item in pairs( self.serverData.ships ) do
    		if item.vid == vid then
				table.remove( self.serverData.ships, idx )
    			break
    		end
    	end

		for battleSlotIdx, battleSlotVid in pairs( self.serverData.battleSlots ) do
			if battleSlotVid == vid then
				self.serverData.battleSlots[ battleSlotIdx ] = UI.INVALID_U64_ID
				break
			end
		end

    	self.serverData.bInvItemsDirty = true

	end


	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:UpdateServerData_OnVesselEquipment( result, requestId, param1, param2 )

	if result == 0 then

    	local shipId = u64( param1, param2 )

    	for idx, shipItem in pairs( self.serverData.allShips ) do

    		if shipItem.vid == shipId then

    			shipItem.equipModules	= _G.GameStore_GetEquipmentIids( shipItem.vid )
	    		shipItem.equipAmmo		= _G.GameStore_GetMunition( shipItem.vid )

    			self:UpdateIid2Ship( shipItem )

    			break

    		end

    	end

		self.serverData.bInvItemsDirty = true

	end


	requestId = UI.VESSEL_EQUIPMENT_REQUEST_ID
	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


-- ВНИМАНИЕ! индексы в vids с 0
function UI:UpdateServerData_OnVesselsEquipment( vids )

	for idx, vid in pairs( vids ) do

    	for idx, shipItem in pairs( self.serverData.allShips ) do

    		if shipItem.vid == vid then

    			shipItem.equipModules	= _G.GameStore_GetEquipmentIids( shipItem.vid )
        		shipItem.equipAmmo		= _G.GameStore_GetMunition( shipItem.vid )

    			self:UpdateIid2Ship( shipItem )

    			break

    		end

    	end

	end

	self.serverData.bInvItemsDirty = true


	requestId = UI.VESSELS_EQUIPMENT_REQUEST_ID

	if self:IsWaitingRequest( requestId ) then
		self:RemoveWaitingRequest( requestId )
	else
		self:UpdateInvItems()
	end

end


--
function UI:OnInventoryChanged()

	self.serverData.inventory		= {}
	self.serverData.inventoryByDef	= {}
	self.serverData.inventoryByIid	= {}

	local inventory = _G.GameStore_GetInventory()

	for idx, item in pairs( inventory ) do

		local byDef = self.serverData.inventoryByDef[ item.defName ]

		if not byDef then
			byDef = {}
			self.serverData.inventoryByDef[ item.defName ] = byDef
		end
		table.insert( byDef, item )

		if not self.serverData.inventoryByIid[ item.iid.h ] then
			self.serverData.inventoryByIid[ item.iid.h ] = {}
		end
		self.serverData.inventoryByIid[ item.iid.h ][ item.iid.l ] = item

	end

	self.serverData.inventory = inventory
	self.serverData.bInvItemsDirty = true

end


--
function UI:OnAutogenInventoryChanged()

	self.serverData.autogenInventory		= {}
	self.serverData.autogenInventoryByDef	= {}
	self.serverData.autogenInventoryByIid	= {}

	local autogenInventory = _G.GameStore_GetAutogenInventory()

	for idx, autogenItem in pairs( autogenInventory ) do

		if autogenItem.defName ~= "" then	-- во время геймплея дефов у автогена из инвентаря нет
			autogenItem.def = _G.GetAutogenDef( autogenItem.defName )
			self.serverData.autogenInventoryByDef[ autogenItem.defName ] = autogenItem
		end

		if not self.serverData.autogenInventoryByIid[ autogenItem.iid.h ] then
			self.serverData.autogenInventoryByIid[ autogenItem.iid.h ] = {}
		end
		self.serverData.autogenInventoryByIid[ autogenItem.iid.h ][ autogenItem.iid.l ] = autogenItem

	end

	self.serverData.autogenInventory = autogenInventory
	self.serverData.bInvItemsDirty = true

end


--
function UI:UpdateServerData_OnOwnedVessels( result, requestId, param1, param2 )

	if result == 0 then

    	self.serverData.ships = {}
    	self.serverData.allShips = _G.GameStore_GetOwnedVessels() or {}

    	for idx, shipItem in pairs( self.serverData.allShips ) do

			UI:ValidateShipItem( shipItem )

			if not shipItem.conserved then
				table.insert( self.serverData.ships, shipItem )
			end

    		self:UpdateIid2Ship( shipItem )

    	end

    	self.serverData.bInvItemsDirty = true

	end

	requestId = self.OWNED_VESSELS_REQUEST_ID
	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:UpdateServerData_OnRecraftVessel( result, requestId, param1, param2, u64Param )

	if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
		return
	end

	self:UpdateServerData_OnFullUpdateShip( u64Param )

end


--
function UI:UpdateServerData_OnFullUpdateShip( vid )

    local newShipItem = _G.GameStore_GetOwnedVessel( vid )
	UI:ValidateShipItem( newShipItem )

    for idx, shipItem in pairs( self.serverData.allShips ) do
		if shipItem.vid == vid then
    		self.serverData.allShips[ idx ] = newShipItem
    		break
		end
	end


	local bWasConserved = true

    for idx, shipItem in pairs( self.serverData.ships ) do

		if shipItem.vid == vid then

			bWasConserved = false

			if newShipItem.conserved then
				table.remove( self.serverData.ships, idx )
			else
				self.serverData.ships[ idx ] = newShipItem
			end

			break

		end

	end

	if bWasConserved and not newShipItem.conserved then
		table.insert( self.serverData.ships, newShipItem )
	end


    self:UpdateIid2Ship( newShipItem )

    self.serverData.bInvItemsDirty = true
	self:UpdateInvItems()

end


--
function UI:ValidateShipItem( shipItem )

	shipItem.equipModules			= _G.GameStore_GetEquipmentIids( shipItem.vid )
	shipItem.equipAmmo				= _G.GameStore_GetMunition( shipItem.vid )
	shipItem.localizedName			= UI:GetEntityLocalizedNameByDef( shipItem.defName )
	shipItem.localizedName_lower	= _G.Utf8CaseFold_Transform( shipItem.localizedName )
	shipItem.exp					= _G.GameStore_GetVesselExp( shipItem.vid )
	shipItem.level					= _G.GameStore_GetVesselLevel( shipItem.vid )
	shipItem.specModuleParts		= _G.GameStore_GetBudgetCount( shipItem.vid ) or 0
	shipItem.evolutionPoints		= _G.GameStore_GetVesselEvolutionPoints( shipItem.vid ) or 0

	shipItem.specModuleLevel = _G.GameStore_GetBudgetLevel( shipItem.vid ) or -1
	if shipItem.specModuleLevel ~= -1 then
		shipItem.specModuleLevel = shipItem.specModuleLevel + 1
	end

end


--
function UI:UpdateServerData_OnVesselLevelUp( result, requestId, param1, param2 )

	if result ~= 0 then
		return
	end

	local vid = u64( param1, param2 )
	local shipItem = self:GetShipItem( vid, true )

	if shipItem then
		shipItem.exp = _G.GameStore_GetVesselExp( vid )
		shipItem.level = _G.GameStore_GetVesselLevel( vid )
	end

end


