--
function UI:UpdateServerData_OnTransferMunition( result, requestId, param1, param2, u64Param )

	if result == _G.GameStore.MunitionResult.MR_OK then

    	local srcVid = u64( param1, param2 )
    	local dstVid = u64Param

    	for idx, shipItem in pairs( self.serverData.allShips ) do

    		if shipItem.vid == srcVid or shipItem.vid == dstVid then
    			shipItem.equipAmmo = _G.GameStore_GetMunition( shipItem.vid )
    		end

    	end

    	self.serverData.bInvItemsDirty = true

	end

	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.MunitionResult.MR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:UpdateIid2Ship( shipItem )

	for h, ll in pairs( self.serverData.iid2Ship ) do
		for l, item in pairs( ll ) do
			if item.vid == shipItem.vid then
				ll[ l ] = nil
			end
		end
	end

	for slotIdx, iid in pairs( shipItem.equipModules ) do

		if iid ~= UI.INVALID_U64_ID then

    		if not self.serverData.iid2Ship[ iid.h ] then
    			self.serverData.iid2Ship[ iid.h ] = {}
    		end
    		self.serverData.iid2Ship[ iid.h ][ iid.l ] = shipItem

		end

	end

end


--
function UI:UpdateServerData_OnPlayerCredits( result, requestId, param1, param2 )

	if result ~= 0 then
		sys.log( "UI:UpdateServerData_OnPlayerCredits(): res ~= 0" )
		return
	end

	local oldRaceReps 		= self.serverData.playerCredits and self.serverData.playerCredits.raceRep or {}

	self.serverData.playerCredits = _G.MasterServer_GetPlayerCredits()

	self.serverData.playerCredits.credits			= tonumber( self.serverData.playerCredits.credits_str )
	self.serverData.playerCredits.goldCredits		= tonumber( self.serverData.playerCredits.goldCredits_str )
	self.serverData.playerCredits.goldBuyingPoints	= tonumber( _G.U64ToStr( self.serverData.playerCredits.goldBuyingPoints ) )

	self.serverData.playerCredits.raceRep_prev		= oldRaceReps
	self.serverData.playerCredits.raceRepChanged	= false

	for race, rep in pairs( self.serverData.playerCredits.raceRep ) do

		local oldRep = oldRaceReps[ race ]

		if oldRep and rep ~= oldRep then
			self.serverData.playerCredits.raceRepChanged = true
			break
		end

	end

end


--
function UI:UpdateServerData_OnNotification( notification, params )

	if UI.Notifications then
		UI.Notifications:MasterServer_OnNotification( notification, params )
	end

	if notification == _G.MasterServer.ServerNotification.SN_QUEST_PROGRESS then

--		sys.log("^5SN_QUEST_PROGRESS")

		if type( params.questId ) == "number" then

			local info = self.serverData.activeQuestsById[ params.questId ]
			if info then

				if type( params.progress ) == "number" then
					info.progress = params.progress
				else
					sys.log( "UI:UpdateServerData_OnNotification()[ERROR]: invalid type of \"params.progress\" in notification \"SN_QUEST_PROGRESS\"; \"number\" expected, got \"%s\"", type( params.progress ) )
				end

				if type( params.stage ) == "number" then
					info.stage = params.stage
				else
					sys.log( "UI:UpdateServerData_OnNotification()[ERROR]: invalid type of \"params.stage\" in notification \"SN_QUEST_PROGRESS\"; \"number\" expected, got \"%s\"", type( params.stage ) )
				end

			else
				sys.log( "UI:UpdateServerData_OnNotification()[ERROR]: cannot find info for quest %d", params.questId )
			end

		else
			sys.log( "UI:UpdateServerData_OnNotification()[ERROR]: invalid type of \"params.questId\" in notification \"SN_QUEST_PROGRESS\"; \"number\" expected, got \"%s\"", type( params.questId ) )
		end


	elseif notification == _G.MasterServer.ServerNotification.SN_NEW_LETTER then

		-- #0029816: возможна ситуация, когда может прийти нотификация для письма, которое уже занесено в кэш;
		-- это может происходить для писем, которые отправляются сразу после логина и
		-- зависит от взаимной очередности прихода нотификации о письме и коллбэка на запрос MasterServer_MailRequest()

		local bFound = false
		for letterIdx, letter in pairs( UI.serverData.mail ) do
			if letter.mailId == params.mailId then
				bFound = true
				break
			end
		end

		if not bFound then
			self:AddLetterInternal( params )
		end


	elseif notification == _G.MasterServer.ServerNotification.SN_VESSEL_CUSTOM_ELEMENTS_NEW_FREE then

		UI:UpdateFreeShipCustomizations()

	elseif notification == _G.MasterServer.ServerNotification.SN_GAME_REWARDED then

		UI:CheckModidyGameRewardNotification()

	end

end


