--
function UI:ResetInvItems()

	self.serverData.invItems = {}
	self.serverData.bInvItemsDirty = true

end


--
function UI:UpdateInvItems()

	if not self.serverData.bInvItemsDirty then
		return
	end

	if not UI.HangarWnd:IsOnScreen() then
		return
	end

	self:ResetInvItems()

	local defShip2InvItem_notEnchanted = {}
	local defShip2InvItem_enchanted = {}

	for inventoryIdx, inventoryItem in pairs( self.serverData.inventory ) do

		local bIgnore = false

    	local def = UI:GetDef( inventoryItem.defName )
		if not def then
			sys.log( "UI:UpdateInvItems()[ERROR]: cannot find def for defName \"%s\"", inventoryItem.defName )
			bIgnore = true
		end

		-- аммуниция может лежать в инвентаре с количеством 0; не показываeтся в списке
		if not bIgnore then
			bIgnore = inventoryItem.amount <= 0
		end

		-- #0098460 - предметы, которые выставлены на продажу между игроками, не должны показываться больше нигде
		if not bIgnore then
			local bAdverted = UI:IsItemAdverted( inventoryItem.iid )
			if bAdverted then
				bIgnore = true
			end
		end

		if not bIgnore then

    		local isAmmo = UI:IsDefAmmo( inventoryItem.defName )

    		local equipShipItem = self:GetEquippedShipItem( inventoryItem.iid )
    		local equipShipId = equipShipItem and equipShipItem.vid or UI.INVALID_U64_ID

			local bEnchanted = false
			if not isAmmo then
				bEnchanted = UI:IsInventoryItemEnchanted( inventoryItem )
			end

			local defShip2InvItem = bEnchanted and defShip2InvItem_enchanted or defShip2InvItem_notEnchanted

			local invItemsByDef = defShip2InvItem[ inventoryItem.defName ]

			local existInvItem = nil

			if not UI:IsDefModule( inventoryItem.defName ) then
				existInvItem = invItemsByDef and invItemsByDef[ equipShipId.h ] and invItemsByDef[ equipShipId.h ][ equipShipId.l ]
			end

    		if existInvItem then
    			existInvItem.count = existInvItem.count + inventoryItem.amount
	    		table.insert( existInvItem.iids, inventoryItem.iid )
    		else
				local invItem = self:CreateInvItem( isAmmo and UI.invItemTypes.AMMO or UI.invItemTypes.MODULE, inventoryItem.defName, equipShipItem, inventoryItem.amount, inventoryItem.iid, defShip2InvItem, nil )
		        invItem.bEnchanted = bEnchanted
    			table.insert( self.serverData.invItems, invItem )
    		end

		end

	end

	-- корабли и экипированная аммуниция
	-- (экипированная аммуниция не лежит в инвентаре, поэтому ее нужно собирать отдельно, по всем кораблям)

	for shipIdx, shipItem in pairs( self.serverData.ships ) do

--[[ корабли сейчас нельзя продавать из окна склада

		-- корабль (корабли не стэкаются)

		local shipInvItem = self:CreateInvItem( UI.invItemTypes.SHIP, shipItem.defName, nil, 1, nil, nil, shipItem )
    	table.insert( self.serverData.invItems, shipInvItem )
]]

		-- аммуниция
		for slotId, ammo in pairs( shipItem.equipAmmo ) do

    		if ammo.def ~= "" and ammo.amount > 0 then

				local defShip2InvItem = defShip2InvItem_notEnchanted
    			local invItemsByDef = defShip2InvItem[ ammo.def ]
				local existInvItem = invItemsByDef and invItemsByDef[ shipItem.vid.h ] and invItemsByDef[ shipItem.vid.h ][ shipItem.vid.l ]

        		if existInvItem then
        			existInvItem.count = existInvItem.count + ammo.amount
				else
					local ammoInvItem = self:CreateInvItem( UI.invItemTypes.AMMO, ammo.def, shipItem, ammo.amount, nil, defShip2InvItem, nil )
			        ammoInvItem.bEnchanted = false
    				table.insert( self.serverData.invItems, ammoInvItem )
				end
    		end
		end
	end

	-- ресурсы и чертежи

	for rcDefName, rcCount in pairs( UI.serverData.resources ) do

		local availableCount = rcCount

		-- #0098460 - предметы, которые выставлены на продажу между игроками, не должны показываться больше нигде
		local advertedCount = UI:GetResourceAdvertedCount( rcDefName )
		availableCount = math.max( availableCount - advertedCount, 0 )

		if availableCount > 0 then
			local rcInvItem = self:CreateInvItem( UI:IsDefBlueprint( rcDefName ) and UI.invItemTypes.BLUEPRINT or UI.invItemTypes.RESOURCE, rcDefName, nil, availableCount, nil, nil, nil )
    		table.insert( self.serverData.invItems, rcInvItem )
		end

	end

	-- автоген

	for autogenItemIdx, autogenItem in pairs( self.serverData.autogenInventory ) do

		if autogenItem.def then

    		local equipShipItem = self:GetEquippedShipItem( autogenItem.iid )
			local invItem = self:CreateInvItem( UI.invItemTypes.MODULE, autogenItem.defName, equipShipItem, 1, autogenItem.iid, nil, nil )

    		table.insert( self.serverData.invItems, invItem )

		end

	end

	self.serverData.bInvItemsDirty = false

	self:SendUiEvent( UI.EV_INV_ITEMS_CHANGED, UI.INVALID_UI_HANDLE, UI.INVALID_UI_HANDLE, UI.DELIVER_IMMEDIATE, 0, 0, 0, 0 )

end


--
function UI:CreateInvItem( invItemType, defName, equipShipItem, count, iid, defShip2InvItem, shipItem )

	local invItem = {}

	invItem.itemType		= invItemType
	invItem.defName			= defName
	invItem.count			= count
	invItem.equipShipItem	= equipShipItem
	invItem.shipItem		= shipItem
	invItem.bEnchanted		= false

	invItem.iids = {}
	if iid then
		table.insert( invItem.iids, iid )
	end

	if defShip2InvItem then

		local byDef = defShip2InvItem[ defName ]
		if not byDef then
			byDef = {}
			defShip2InvItem[ defName ] = byDef
		end

		local shipId = equipShipItem and equipShipItem.vid or UI.INVALID_U64_ID
		if not byDef[ shipId.h ] then
			byDef[ shipId.h ] = {}
		end
		byDef[ shipId.h ][ shipId.l ] = invItem

	end

	return invItem

end


--
function UI:SortInvItems( invItems, bDesc )

	local currencyRate = self:GetCurrencyRate()

	local fSort = function( item1, item2 )

		-- 1. если вещь одинакового дефа то
		-- а) bEnchanted или нет
		-- б) по имени корабля, на который установлена
		-- в) по iid

		if item1.defName == item2.defName then

			if item1.bEnchanted and not item2.bEnchanted then
				return bDesc

			elseif not item1.bEnchanted and item2.bEnchanted then
				return not bDesc

			else

        		if not item1.equipShipItem and item2.equipShipItem then
        			return true

        		elseif item1.equipShipItem and not item2.equipShipItem then
        			return false

				else

        			if item1.equipShipItem == item2.equipShipItem then

						if UI:IsDefModule( item1.defName ) then

							local iid1 = item1.iids[ 1 ]
							local iid2 = item2.iids[ 1 ]

							return iid1 < iid2

						end

					else

         				if item1.equipShipItem.localizedName < item2.equipShipItem.localizedName then
         					return true

         				elseif item1.equipShipItem.localizedName > item2.equipShipItem.localizedName then
         					return false
         				end

					end

				end

			end

			return false

		end

		local def1 = UI:GetDef( item1.defName )
		local def2 = UI:GetDef( item2.defName )

		if not def1 then
			return false
		end

		if not def2 then
			return true
		end

        -- 2. по категории магазина

		local mainCategoryIdxInfo1 = def1.shopCategory and StoreInfo.categoryName2Idx[ def1.shopCategory ]
		local mainCategoryIdxInfo2 = def2.shopCategory and StoreInfo.categoryName2Idx[ def2.shopCategory ]

		local mainCategoryIdx1 = mainCategoryIdxInfo1 and mainCategoryIdxInfo1.idx or -1
		local mainCategoryIdx2 = mainCategoryIdxInfo2 and mainCategoryIdxInfo2.idx or -1

		if mainCategoryIdx1 ~= mainCategoryIdx2 then
			return mainCategoryIdx1 < mainCategoryIdx2
		end

		local subCategoryIdx1 = def1.shopSubCategory and mainCategoryIdxInfo1 and mainCategoryIdxInfo1.sub[ def1.shopSubCategory ] or -1
		local subCategoryIdx2 = def2.shopSubCategory and mainCategoryIdxInfo2 and mainCategoryIdxInfo2.sub[ def2.shopSubCategory ] or -1

		if subCategoryIdx1 ~= subCategoryIdx2 then
			return subCategoryIdx1 < subCategoryIdx2
		end

        -- 3. по полю item_subtype (если есть)

		local subType1 = def1.item_subtype or 0
		local subType2 = def2.item_subtype or 0

		if subType1 ~= subType2 then
			return subType1 < subType2
		end

		-- 4. по рангу (если есть)

		local rank1 = def1.rank
		local rank2 = def2.rank

		if rank1 == nil or rank1 == 0 then
			rank1 = -1
		end

		if rank2 == nil or rank2 == 0 then
			rank2 = -1
		end

		if rank1 ~= rank2 then
			if bDesc then
				return rank1 > rank2
			else
				return rank1 < rank2
			end
		end

        -- 5. по item_lvl (если есть)

		local itemLevel1 = def1 and def1.item_lvl or 0
		local itemLevel2 = def2 and def2.item_lvl or 0

		if itemLevel1 ~= itemLevel2 then
			if bDesc then
				return itemLevel1 > itemLevel2
			else
				return itemLevel1 < itemLevel2
			end
		end

        -- 6. по цене (сначала по серебру, потом по золоту)

		local price1, isPremium1 = self:GetShopBaseBuyPriceByDef( item1.defName, true, false )	-- #0036543, комм.(0132906) - "Цены для сортировки используются так: если есть серебряная, то используется она. Если серебряной нет, то золотая"
		local price2, isPremium2 = self:GetShopBaseBuyPriceByDef( item2.defName, true, false )

		if not isPremium1 and isPremium2 then
			return ( not bDesc )
		end

		if isPremium1 and not isPremium2 then
			return bDesc
		end

		if bDesc then
			return price1 > price2
		else
			return price1 < price2
		end

	end

	table.sort( invItems, fSort )
	return invItems

end


--
function UI:UpdateServerData_OnBattleSlots( result, requestId, param1, param2 )

	if result ~= 0 then
		return
	end

	self.serverData.battleSlots					= _G.GameStore_GetBattleSlots()
	self.serverData.battleSlotsRankReq			= _G.GameStore_GetBattleSlotRepReqs()
	self.serverData.battleSlotsCount			= _G.GameStore_GetBattleSlotsCount()
	self.serverData.battleSlotsMax				= _G.GameStore_GetBattleSlotsMax()
	self.serverData.battleSlotTypes				= _G.GameStore_GetBattleSlotTypes()
	self.serverData.battleSlotsChangeReputations = _G.GameStore_GetBattleSlotConversionRepReq()

	requestId = self.BATTLE_SLOTS_REQUEST_ID
	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


