--
function UI:UpdateServerData_OnRefillMunition( result, requestId, param1, param2 )

	if result == _G.GameStore.MunitionResult.MR_OK then

    	self:OnInventoryChanged()

    	local shipId = u64( param1, param2 )
    	for idx, shipItem in pairs( self.serverData.allShips ) do
    		if shipItem.vid == shipId then
    			shipItem.equipAmmo = _G.GameStore_GetMunition( shipItem.vid )
    			break
	   		end
    	end

    	self.serverData.bInvItemsDirty = true

	end

	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.MunitionResult.MR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:UpdateServerData_OnRefillBattleVessels( result, requestId, param1, param2 )

	if result == _G.GameStore.MunitionResult.MR_OK then

    	self:OnInventoryChanged()

    	for idx, shipItem in pairs( self.serverData.allShips ) do
    		shipItem.equipAmmo = _G.GameStore_GetMunition( shipItem.vid )
    	end

    	self.serverData.bInvItemsDirty = true

	end

	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.MunitionResult.MR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:StartWaitingRequests()

	if UI:IsWaitingRequests() then
		return
	end

    self.waitingStartTime = _G.TimerGetRealTime()

	self:SendUiEvent( UI.EV_START_WAITING_REQUESTS, UI.INVALID_UI_HANDLE, UI.INVALID_UI_HANDLE, UI.DELIVER_IMMEDIATE, 0, 0, 0, 0 )

end


--
function UI:StopWaitingRequests()

	if not UI:IsWaitingRequests() then
		return
	end

	self.waitingRequests = {}
	self.waitingStartTime = -1

	self:SendUiEvent( UI.EV_STOP_WAITING_REQUESTS, UI.INVALID_UI_HANDLE, UI.INVALID_UI_HANDLE, UI.DELIVER_IMMEDIATE, 0, 0, 0, 0 )

	self:UpdateInvItems()

end


--
function UI:IsWaitingRequests()

	return self.waitingStartTime ~= -1

end

--
function UI:IsWaitingRequest( requestId )

	return self.waitingRequests[ requestId ] ~= nil

end


--
function UI:AddWaitingRequest( requestId )

	if requestId == 0 then
		return
	end

	local wasWaiting = self:IsWaitingRequests()

	if requestId < 0 then

		if not self.waitingRequests[ requestId ] then
			self.waitingRequests[ requestId ] = 1
		else
			self.waitingRequests[ requestId ] = self.waitingRequests[ requestId ] + 1
		end

	else
		self.waitingRequests[ requestId ] = true
	end

	if not wasWaiting then
		self:StartWaitingRequests()
	end

end


--
function UI:RemoveWaitingRequest( requestId )

	if requestId == 0 then
		return
	end

	if requestId < 0 then

		if self.waitingRequests[ requestId ] then
			self.waitingRequests[ requestId ] = self.waitingRequests[ requestId ] - 1
			if self.waitingRequests[ requestId ] <= 0 then
				self.waitingRequests[ requestId ] = nil
			end
		end

	else
		self.waitingRequests[ requestId ] = nil
	end

	if not next( self.waitingRequests ) then
		self:StopWaitingRequests()
	end

end


--
function UI:UpdateWaitingRequestsTimer()

	if not self:IsWaitingRequests() then
		return
	end

	local curTime = _G.TimerGetRealTime()

	if curTime - self.waitingStartTime >= self.MAX_WAITING_REQUEST_TIME_OUT then
		sys.log( "UI:UpdateWaitingRequestsTimer()[WARNING]: time out" )
		self:StopWaitingRequests()
	end

end


