--
function UI:GetShopBuyPrice( item, bAllowMultiple, bConsiderConserved, bWithAuraSale, bCanUseEventCredits )

	if not item then
		return 0, false, false
	end

	if bConsiderConserved == nil then
		bConsiderConserved = true
	end

	if bWithAuraSale == nil then
		bWithAuraSale = true
	end

	if bCanUseEventCredits == nil then
		bCanUseEventCredits = false
	end

	if bConsiderConserved then

    	local bConserved = false

    	if UI:IsDefShip( item.defName ) then
    		local shipItem = self:GetShipItemByDef( item.defName, true )
    		if shipItem and shipItem.conserved then
    			bConserved = true
    		end
    	end

		if bConserved then
			local price, bGold = UI:GetShopConservedBuyPrice( item )
			return price, bGold, false
		end

	end

	-- актуальная цена 0 в той или иной валюте не означает, что за эту валюту нельзя купить, 0 может образоваться в результате скидки,
	-- поэтому можно или нет купить за данную валюту, проверяется через базовую цену - там 0 означает невозможность купить за данную валюту

	local basePrice, bGold, bEventCredits = UI:GetShopBaseBuyPrice( item, bAllowMultiple, bConsiderConserved, bCanUseEventCredits )

	local val = 0

	if bGold then
		val = item.premiumPrice or 0
	elseif bEventCredits then
		val = item.eventPrice or 0
	else
		val = item.price or 0
	end

	if bWithAuraSale and val > 0 then

		local bIsAura, modifier_credits, modifier_gold = UI:GetItemAuraSaleInfo( item.defName )

		if bIsAura then

    		modifier = bGold and modifier_gold or modifier_credits

    		val = val + val * modifier
    		val = math.max( val, 0 )

		end

	end

	return val, bGold, bEventCredits

end


