--
function UI:GetShopBaseBuyPrice( item, bAllowMultiple, bConsiderConserved, bCanUseEventCredits )

	if not item then
		return 0, false, false
	end

	if bConsiderConserved == nil then
		bConsiderConserved = true
	end

	if bCanUseEventCredits == nil then
		bCanUseEventCredits = false
	end

	if bConsiderConserved then

    	local bConserved = false

    	if UI:IsDefShip( item.defName ) then
    		local shipItem = self:GetShipItemByDef( item.defName, true )
    		if shipItem and shipItem.conserved then
    			bConserved = true
    		end
    	end

		if bConserved then
			local price, bGold = UI:GetShopConservedBaseBuyPrice( item )
			return price, bGold, false
		end

	end

	return UI:UnifyPrice( item.basePrice, item.basePremiumPrice, bAllowMultiple, bCanUseEventCredits, item.baseEventPrice )


end


