--
function UI:GetShopAllBuyPrices( item, bConsiderConserved, bWithAuraSale )

	local creditsPrice		= 0
	local goldPrice			= 0
	local eventCreditsPrice	= 0
	local tokensPrice		= 0

	if not item then
		return creditsPrice, goldPrice, eventCreditsPrice, tokensPrice
	end

	if bConsiderConserved == nil then
		bConsiderConserved = true
	end

	if bWithAuraSale == nil then
		bWithAuraSale = true
	end

    local bConserved = false

	if bConsiderConserved then

    	if UI:IsDefShip( item.defName ) then
    		local shipItem = self:GetShipItemByDef( item.defName, true )
    		if shipItem and shipItem.conserved then
    			bConserved = true
    		end
    	end

		if bConserved then

			local conservedPrice, bGold = UI:GetShopConservedBuyPrice( item )

			creditsPrice	= bGold and 0 or conservedPrice
			goldPrice		= bGold and conservedPrice or 0

		end

	end

	if not bConserved then

		creditsPrice		= item.price or 0
		goldPrice			= item.premiumPrice or 0
		eventCreditsPrice	= item.eventPrice or 0
		tokensPrice			= item.tokenPrice or 0

    	if bWithAuraSale then

    		local bIsAura, modifier_credits, modifier_gold = UI:GetItemAuraSaleInfo( item.defName )

			if bIsAura then

    			if goldPrice > 0 then
    				goldPrice = goldPrice + goldPrice * modifier_gold
    				goldPrice = math.max( goldPrice, 0 )
				end

    			if creditsPrice > 0 then
    				creditsPrice = creditsPrice + creditsPrice * modifier_credits
    				creditsPrice = math.max( creditsPrice, 0 )
				end

			end

    	end

	end

	return creditsPrice, goldPrice, eventCreditsPrice, tokensPrice

end


