function UI:GetShopAllBuyPricesByDef( defName, bConsiderConserved, bWithAuraSale )

	local shopItem = UI.serverData.shopByDef[ defName ]
	if shopItem then
		return UI:GetShopAllBuyPrices( shopItem, bConsiderConserved, bWithAuraSale )
	else
		return 0, 0, 0, 0
	end

end


