function UI:GetShopAllBaseBuyPrices( item, bConsiderConserved )

	local creditsPrice		= 0
	local goldPrice			= 0
	local eventCreditsPrice	= 0
	local tokenPrice		= 0

	if not item then
		return creditsPrice, goldPrice, eventCreditsPrice
	end

	if bConsiderConserved == nil then
		bConsiderConserved = true
	end

    local bConserved = false

	if bConsiderConserved then

    	if UI:IsDefShip( item.defName ) then
    		local shipItem = self:GetShipItemByDef( item.defName, true )
    		if shipItem and shipItem.conserved then
    			bConserved = true
    		end
    	end

		if bConserved then

			local conservedPrice, bGold = UI:GetShopConservedBaseBuyPrice( item )

			creditsPrice	= bGold and 0 or conservedPrice
			goldPrice		= bGold and conservedPrice or 0

		end

	end

	if not bConserved then
		creditsPrice		= item.basePrice or 0
		goldPrice			= item.basePremiumPrice or 0
		eventCreditsPrice	= item.baseEventPrice or 0
		tokenPrice			= item.baseTokenPrice or 0
	end

	return creditsPrice, goldPrice, eventCreditsPrice, tokenPrice

end


