-- возвращает цену в серебре (либо иной валюте), если оно прописано и хватает денег;
-- иначе в золоте если оно прописано
function UI:GetShopSmartBuyPriceOne( item, bWithAuraSale )

	local priceType, price, basePrice, altPriceType, altPrice, altBasePrice = UI:GetShopSmartBuyPriceAlt( item, bWithAuraSale )

	if altPriceType then
		priceType	= altPriceType
		price		= altPrice
		basePrice	= altBasePrice
	end

	return priceType, price, basePrice

end


-- возвращает цену в серебре (либо иной валюте), если оно прописано и хватает денег;
-- иначе в золоте если оно прописано
function UI:GetShopSmartBuyPriceOneByDef( defName, bWithAuraSale )

	local shopItem = UI.serverData.shopByDef[ defName ]
	if shopItem then
		return UI:GetShopSmartBuyPriceOne( shopItem, bWithAuraSale )
	else
		return -1, 0, 0
	end

end


-- возвращает цену в серебре (либо иной валюте);
-- если не хватает денег, то еще и цену в золоте (если она прописана)
function UI:GetShopSmartBuyPriceAlt( item, bWithAuraSale )

	local bCanUseEventCredits = UI:IsDefModule( item.defName ) -- #0084864,комм.(0376483) - ивентовая валюта - только для модулей

	local priceType		= -1
	local price			= 0
	local basePrice		= 0

	local priceCredits,		priceGold,		priceEventCredits,		priceTokens		= UI:GetShopAllBuyPrices( item, nil, bWithAuraSale )
	local basePriceCredits,	basePriceGold,	basePriceEventCredits,	basePriceTokens	= UI:GetShopAllBaseBuyPrices( item )

	if basePriceEventCredits ~= 0 and bCanUseEventCredits then

		priceType		= _G.GameStore.CreditsType.CT_EVENT
		price			= priceEventCredits
		basePrice		= basePriceEventCredits

	elseif basePriceTokens ~= 0 then

		priceType		= _G.GameStore.CreditsType.CT_TOKENS
		price			= priceTokens
		basePrice		= basePriceTokens

	elseif basePriceCredits ~= 0 then

		priceType		= _G.GameStore.CreditsType.CT_CREDITS
		price			= priceCredits
		basePrice		= basePriceCredits

	elseif basePriceGold ~= 0 then

		priceType		= _G.GameStore.CreditsType.CT_GOLD
		price			= priceGold
		basePrice		= basePriceGold

	end

	local altPriceType	= nil
	local altPrice		= nil
	local altBasePrice	= nil

	if priceType ~= -1 and priceType ~= _G.GameStore.CreditsType.CT_GOLD and not UI:GetPlayerFunds( priceType ) and basePriceGold ~= 0 then
		altPriceType	= _G.GameStore.CreditsType.CT_GOLD
		altPrice		= priceGold
		altBasePrice	= basePriceGold
	end

	return priceType, price, basePrice, altPriceType, altPrice, altBasePrice

end


-- возвращает цену в серебре (либо иной валюте);
-- если не хватает денег, то еще и цену в золоте (если она прописана)
function UI:GetShopSmartBuyPriceAltByDef( defName, bWithAuraSale )

	local shopItem = UI.serverData.shopByDef[ defName ]
	if shopItem then
		return UI:GetShopSmartBuyPriceAlt( shopItem, bWithAuraSale )
	else
		return -1, 0, 0, nil, nil, nil
	end

end


--
function UI:GetShopConservedBuyPrice( item )

	if type( item ) ~= "table" then
		sys.log( "UI:GetShopConservedBuyPrice()[ERROR]: invalid type of the 1-st parameter (\"item\"); \"table\" expected, got \"%s\"", type( item ) )
		return 0, false
	end

	local price = item.price or 0
	price = math.max( math.floor( price * _G.GameStore_GetDeconserveCostModifier() ), 1 )

	return price, false

end


--
function UI:GetShopConservedBuyPriceByDef( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShopConservedBuyPriceByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return 0, false
	end

	local shopItem = UI.serverData.shopByDef[ defName ]
	if not shopItem then
		sys.log( "UI:GetShopConservedBuyPriceByDef()[ERROR]: cannot find shop item with def \"%s\"", defName )
		return 0, false
	end

	return UI:GetShopConservedBuyPrice( shopItem )

end


--
function UI:GetShopConservedBaseBuyPrice( item )

	if type( item ) ~= "table" then
		sys.log( "UI:GetShopConservedBaseBuyPrice()[ERROR]: invalid type of the 1-st parameter (\"item\"); \"table\" expected, got \"%s\"", type( item ) )
		return 0, false
	end

	local price = item.basePrice or 0
	price = math.max( math.floor( price * _G.GameStore_GetDeconserveCostModifier() ), 1 )

	return price, false

end


--
function UI:GetShopConservedBaseBuyPriceByDef( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShopConservedBaseBuyPriceByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return 0, false
	end

	local shopItem = UI.serverData.shopByDef[ defName ]
	if not shopItem then
		sys.log( "UI:GetShopConservedBaseBuyPriceByDef()[ERROR]: cannot find shop item with def \"%s\"", defName )
		return 0, false
	end

	return UI:GetShopConservedBaseBuyPrice( shopItem )

end


