--
function UI:IsItemFitForShip( itemDefName, shipItem )

	if not UI:IsItemFitForShipByRequiredShip( itemDefName, shipItem.defName ) then
		return false
	end

	if not self:IsItemFitForShipByClass( itemDefName, shipItem.defName ) then
		return false
	end

	if not self:IsItemFitForShipByRace( itemDefName, shipItem.defName ) then
		return false
	end

	if not self:IsItemFitForShipByTierAndRank( itemDefName, shipItem.defName ) then
		return false
	end

	if not self:IsItemFitForShipBySlot( itemDefName, shipItem ) then
		return false
	end

	if not self:IsItemFitForShipByRole( itemDefName, shipItem.defName ) then
		return false
	end

	return true

end


--
function UI:IsItemFitForShipByClass( itemDefName, shipDefName )

	local bFit = false

	if type( itemDefName ) ~= "string" then
		sys.log( "UI:IsItemFitForShipByClass()[ERROR]: invalid type of the 1-st parameter (\"itemDefName\"); \"string\" expected, got \"%s\"", type( itemDefName ) )
		return bFit
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:IsItemFitForShipByClass()[ERROR]: invalid type of the 2-nd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return bFit
	end

	bFit = UI:IsItemFitForShipClass( itemDefName, UI:GetShipClass( shipDefName ) )

	return bFit

end


--
function UI:IsItemFitForShipClass( itemDefName, shipClass )

	local bFit = false

	if type( itemDefName ) ~= "string" then
		sys.log( "UI:IsItemFitForShipClass()[ERROR]: invalid type of the 1-st parameter (\"itemDefName\"); \"string\" expected, got \"%s\"", type( itemDefName ) )
		return bFit
	end

	if type( shipClass ) ~= "number" then
		sys.log( "UI:IsItemFitForShipClass()[ERROR]: invalid type of the 1-st parameter (\"shipClass\"); \"number\" expected, got \"%s\"", type( shipClass ) )
		return bFit
	end

	local itemClassMask = UI:GetItemShipClassMask( itemDefName )
	if itemClassMask ~= nil then

		if shipClass ~= -1 then
			bFit = bit.band( itemClassMask, shipClass ) ~= 0
		else
			sys.log( "UI:IsItemFitForShipClass()[ERROR]: invalid ship class" )
		end

	else
		bFit = true
	end

	return bFit

end


--
function UI:GetShipClass( defName )

	local shipClass = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipClass()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return shipClass
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetShipClass()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return shipClass
	end

	if type( def.ship_class ) == "number" then
		shipClass = def.ship_class
	else
		sys.log( "UI:GetShipClass()[ERROR]: invalid type of _G.Def[\"%s\"].ship_class; \"number\" expected, got \"%s\"", defName, type( def.ship_class ) )
	end

	return shipClass

end


--
function UI:GetItemShipClassMask( defName )

	local mask = nil

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemShipClassMask()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return mask
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemShipClassMask()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return mask
	end

	if def.class_mask ~= nil then
		if type( def.class_mask ) == "number" then
			mask = def.class_mask
		else
			sys.log( "UI:GetShipClass()[ERROR]: invalid type of _G.Def[\"%s\"].class_mask; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.class_mask ) )
		end
	end

	return mask

end


--
function UI:GetShipClassByRole( role )

	local shipClass = -1

	if type( role ) ~= "number" then
		sys.log( "UI:GetShipClassByRole()[ERROR]: invalid type of the 1-st param ('role'); 'number' expected, got '%s'", type( role ) )
		return shipClass
	end

	if type( _G.ShipClassToRoles ) ~= "table" then	 -- ShipClassToRoles определена в ui_properties.lua
		sys.log( "UI:GetShipClassByRole()[ERROR]: invalid type of _G.ShipClassToRoles; 'table' expected, got '%s'", type( _G.ShipClassToRoles ) )
		return shipClass
	end

	for _shipClass, roles in pairs( _G.ShipClassToRoles ) do

		if type( _shipClass ) == "number" and type( roles ) == "table" then

			for roleIdx, _role in pairs( roles ) do

				if type( roleIdx ) == "number" and type( _role ) == "number" then

					if _role == role then
						shipClass = _shipClass
						break
					end

				else
					sys.log( "UI:GetShipClassByRole()[ERROR]: invalid format of _G.ShipClassToRoles[%d] table; {<number>=<number> expected}", _shipClass )
				end

			end

		else
			sys.log( "UI:GetShipClassByRole()[ERROR]: invalid format of _G.ShipClassToRoles table; {<number>=<table>} expected" )
		end

	end

	if shipClass == -1 then
		sys.log( "UI:GetShipClassByRole()[ERROR]: cannot find ship class for role %d", role )
	end

	return shipClass

end


--
function UI:IsItemFitForShipByTierAndRank( itemDefName, shipDefName )

	local itemMinRank = UI:GetItemEquipMinRank( itemDefName )
	local itemMaxRank = UI:GetItemEquipMaxRank( itemDefName )
	local shipRank = UI:GetShipRank( shipDefName )

	-- #0055484,комм.(0227827) - если у вещи не прописан ранг, то она считается подходяшей под корабль любого ранга
	-- Однако см. в #0082990,комм.(0377570) - переделали, что ранг всегда должен быть, так что ситуация невалидного ранга просто не должна возникнуть никогда

	if itemMinRank == -1 or itemMaxRank == -1 then
		return true
	else
		return shipRank ~= -1 and shipRank >= itemMinRank and shipRank <= itemMaxRank
	end

end


--
function UI:IsItemFitForShipByRace( itemDefName, shipDefName )

	local itemDef = UI:GetDef( itemDefName )

	if not itemDef then
		return false
	end

	if itemDef.race_mask then

		local shipRace = UI:GetShipRace( shipDefName )

		if shipRace ~= -1 then

			local shipRaceMaskId = UI:Bit( shipRace )

			if bit.band( itemDef.race_mask, shipRaceMaskId ) == 0 then
				return false
			end

		else
			sys.log( "UI:IsItemFitForShipByRace()[ERROR]: cannot find race for ship %s", shipDefName )
			return false
		end

	end

	return true

end


--
function UI:IsItemFitForShipBySlot( itemDefName, shipItem )

	local itemDef = UI:GetDef( itemDefName )
	local shipDef = shipItem and UI:GetDef( shipItem.defName )

	if not itemDef or not shipDef then
		return false
	end

	local itemType = _G.GetStoreItemTypeByDef( itemDefName )

	if itemType == _G.GameStore.ItemType.IT_MODULE then

		local moduleType = itemDef.module_type
		if not moduleType then
			return false
		end

		local bHasFitSlot = false

		local slotsMask = UI:GetShipSlotsMask( shipItem )
		if slotsMask ~= u64( 0 ) then

			for slotType = 0, ai.SpaceShipModuleSlot.NUM - 1 do

				if UI:BitTstU64( slotsMask, slotType ) then

        			if ai.ModuleTypeOf[ slotType ] == moduleType then
        				bHasFitSlot = true
        				break
        			end

				end

			end

		end

		if not bHasFitSlot then
			return false
		end


	elseif itemType == _G.GameStore.ItemType.IT_ROCKET then
		return true

	else
		return false
	end


	return true

end


--
function UI:GetShipSlotsMask( shipItem )

	local mask = u64( 0 )

	if type( shipItem ) ~= "table" then
		sys.log( "UI:GetShipSlotsMask()[ERROR]: invalid type of the 1-st parameter (\"shipItem\"), \"table\" expected, got \"%s\"", type( shipItem ) )
		return mask
	end

	if UI:IsShipCraftable( shipItem.defName ) then
		mask = shipItem.enabledModuleSlots or u64( 0 )

	elseif UI:IsShipEvolving( shipItem.defName ) then
		mask = UI:GetEvolvingShipSlotsMask( shipItem )

	else
		mask = UI:GetShipAllPossibleSlotsMask( shipItem.defName )
	end

	return mask

end


--
function UI:GetShipAllPossibleSlotsMask( defName )

	local mask = u64( 0 )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipAllPossibleSlotsMask()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return mask
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetShipAllPossibleSlotsMask()[ERROR]: cannot find \"_G.Def[\"%s\"]\"", defName )
		return mask
	end

	if def.slot_bones == nil then
		return mask
	end

	if type( def.slot_bones ) == "table" then

		for slotType, slotInfo in pairs( def.slot_bones ) do
			mask = UI:BitSetU64( mask, slotType )
		end

	else
		sys.log( "UI:GetShipAllPossibleSlotsMask()[ERROR]: invalid type of _G.Def[\"%s\"].slot_bones; \"table\" or \"nil\" expected, got \"%s\"", defName, type( def.slot_bones ) )
	end

	return mask

end


--
function UI:GetCraftableShipDefaultSlotsMask( defName )

	local mask = u64( 0 )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetCraftableShipDefaultSlotsMask()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return mask
	end

	mask = UI:GetShipAllPossibleSlotsMask( defName )

	for slotType = ai.SpaceShipModuleSlot.ENGINE_MOD_01, ai.SpaceShipModuleSlot.CPU_MOD_03 do
		mask = UI:BitRstU64( mask, slotType )
	end

	return mask

end


--
function UI:IsItemFitForShipByRole( itemDefName, shipDefName )

	local shipRole = self:GetItemRole( shipDefName )
	local itemRole = self:GetItemRole( itemDefName )

	return shipRole == -1 or itemRole == -1 or shipRole == itemRole

end


--
function UI:IsItemFitForShipByRequiredShip( itemDefName, shipDefName )

	local requiredShipDefNames = UI:GetItemRequiredShips( itemDefName )
	if not next( requiredShipDefNames ) then
		return true
	end

	if UI:IsShipEvolving( shipDefName ) then
		shipDefName = UI:GetEvolvingShipBaseDef( shipDefName )
	end

	for idx, requiredShipDefName in pairs( requiredShipDefNames ) do

    	if UI:IsShipEvolving( requiredShipDefName ) then
    		requiredShipDefName = UI:GetEvolvingShipBaseDef( requiredShipDefName )
    	end

		if requiredShipDefName == shipDefName then
			return true
		end

	end

	return false

end


--
function UI:CheckShowChat()

	if self:CanShowChat() then
		self:ForceShowChat()
	end

end


--
function UI:UpdateChatVisibility()

	if self:CanShowChat() then
		self:ForceShowChat()
	else
		self:HideChat()
	end

end


