function UI:ChatCheckSetDefaultChannel()

	if not _G.GameChat_IsConnected() then
		return
	end

--[[
	if not UI.HangarWnd or not UI.HangarWnd.w or not UI.HangarWnd:IsOnScreen() then
		return
	end
]]
	--[[local channelName = "general"

	_G.GameChat_Join( channelName )
	_G.GameChat_SetChannel( channelName )]]
	UI.Chat:Connect()

end


--
function UI:ForceShowChat()

	if self.bSavingGameState then
		return
	end

	if cvars.cl_debugChat ~= 0 then

    	if not self:IsChatVisible() then
    		_G.GameChat_ShowUp( true )
    	end

	else

		if UI.Chat then
			UI.Chat:Show()
		end

	end

end


--
function UI:HideChat()

	if cvars.cl_debugChat ~= 0 then

		_G.GameChat_ShowUp( false )
		UI:StopChatInput()

	else

		if UI.Chat then
			UI.Chat:Hide()
		end

	end

end



--
function UI:CanShowChat()

	for idx, wndName in pairs( self.chatIncompatibleWnds ) do
		local wnd = UI[ wndName ]
		if wnd and wnd:IsOnScreen() then
			return false
		end
	end

	if UI.HangarWnd and UI.HangarWnd:IsOnScreen() and UI.HangarWnd:CanShowChat() then
		return true
	end

	if UI.HudWnd and UI.HudWnd:IsOnScreen() and UI.HudWnd:CanShowChat() then
		return true
	end

	return false

end


--
function UI:IsChatVisible()

	if cvars.cl_debugChat ~= 0 then
		return _G.GameChat_IsActive()
	else
		if UI.Chat then
			return UI.Chat:IsVisible()
		else
			return false
		end
	end

end


--
function UI:CheckStartChatInput()

	if self:CanChatInput() then
		self:ForceStartChatInput()
	end

end


--
function UI:ForceStartChatInput( bSound )

	if cvars.cl_debugChat ~= 0 then

		_G.GameChat_ActivateInputMode( true )
		_G.CL_LocalPlayerControllerSetIgnoreMouse( true )

	else

		if UI.Chat then
			UI.Chat:StartInput( bSound )
		end

	end

end


--
function UI:StopChatInput()

	if cvars.cl_debugChat ~= 0 then

		_G.GameChat_ActivateInputMode( false )
		_G.CL_LocalPlayerControllerSetIgnoreMouse( false )

	else

		if UI.Chat then
			UI.Chat:StopInput()
		end

	end

end


--
function UI:CanChatInput()

	if UI:IsChatVisible() then
		local hWnd = UI:GetKeyboardFocus()
		local wnd = UI:GetUiObjByHandleT( hWnd )
		if wnd and wnd.GetClassName then
			if wnd:GetClassName() == "EditWnd" then
				return false
			end
		end
		if UI.ChatWnd:IsChildOf( UI.HangarWnd ) then
			if not UI.HangarWnd:CanChatStartInput() then
				return false
			end
		end
		return true
	end
	return false

end


--
function UI:IsChatInput()

	if cvars.cl_debugChat ~= 0 then
		return _G.GameChat_IsInputMode()
	else
		if UI.Chat then
			return UI.Chat:IsInInputMode()
		else
			return false
		end
	end

end


--
function UI:GetFirstMsgBox()

	local child = UI.Root:GetFirstChild()
	while child do

		if child:GetClassName() == "MsgBoxWnd" then
			return child
		end

		child = child:GetNextSibling()

	end

	return nil

end


--
function UI:GetLastMsgBox()

	local child = UI.Root:GetLastChild()
	while child do

		if child:GetClassName() == "MsgBoxWnd" then
			return child
		end

		child = child:GetPrevSibling()

	end

	return nil

end


--
function UI:IsMsgBoxOnScreen()

	return self:GetLastMsgBox() ~= nil

end


