--
function UI:GetAmmoType( defName )

	local ammoType = -1

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetAmmoType()[ERROR]: cannot find def \"%s\"", tostring( defName ) )
		return -1
	end

	if type( def.MunitionBayType ) ~= "number" then
		sys.log( "UI:GetAmmoType()[ERROR]: invalid type of _G.Def[%s].MunitionBayType; \"number\" expected, got \"%s\"", defName, type( def.MunitionBayType ) )
		return -1
	end

	return def.MunitionBayType

end


--
function UI:GetShipRefillInfo( shipItem )

	local refillInfo =
	{
		bHasAvailable	= false,
		bFullAmmo		= true,
		bNoAmmo			= true,
		credits			= 0,
		gold			= 0,
	}

	if not shipItem then
		sys.log( "UI:GetShipRefillInfo()[ERROR]: nil param" )
		return refillInfo
	end

	local shipDef = UI:GetDef( shipItem.defName )
	if not shipDef then
		sys.log( "UI:GetShipRefillInfo()[ERROR]: cannot find def for %s", shipItem.defName )
		return refillInfo
	end

	for ammoName, slotIdx in pairs( ai.MunitionBayType ) do
		if slotIdx ~= ai.MunitionBayType.MBT_NUM then

        	local ammoInfo = shipItem.equipAmmo[ slotIdx  ]

    		if ammoInfo and ammoInfo.def ~= "" then

    			local invCount = 0

    			local invItemsByDef = self.serverData.inventoryByDef[ ammoInfo.def ]
    			if invItemsByDef then
    				for invItemIdx, invItem in pairs( invItemsByDef ) do
    					invCount = invCount + invItem.amount
    				end
    			end

				local bCanBeBought = not UI:CantItemBeBoughtByDef( ammoInfo.def )

    			local bAvailable = bCanBeBought or invCount > 0
    			if bAvailable then

    				refillInfo.bHasAvailable = true

            		local count = ammoInfo.amount
    				if count > 0 then
    					refillInfo.bNoAmmo = false
    				end

            		local maxCount	= 1
            		local needCount	= maxCount - count

            		if needCount > 0 then

    					refillInfo.bFullAmmo = false

            			-- если есть в инвентаре, аммуниция будет взята оттуда (и на цену это, соответственно, не повлияет);
	        			-- если в инвентаре нет, то она будет куплена

						local buyCount = 0
						if bCanBeBought then
                			buyCount = math.max( needCount - invCount, 0 )
						end

            			if buyCount > 0 then

            				local price, bGold = UI:GetShopBuyPriceByDef( ammoInfo.def, false, nil, false )	-- -- #0036543, комм.(0132906) - утверждается, что на расходники должна быть одна цена
            				local totalPrice = price * buyCount

            				if bGold then
            					refillInfo.gold = refillInfo.gold + totalPrice
            				else
            					refillInfo.credits = refillInfo.credits + totalPrice
            				end

            			end

            		end
    			end
    		end
		end
	end

	return refillInfo

end



--
function UI:GetAllShipsRefillInfo()

	local refillInfo =
	{
		bHasAvailable	= false,
		bFullAmmo		= true,
		bNoAmmo			= true,
		credits			= 0,
		gold			= 0,
	}

	for slotIdx, vid in pairs( UI.serverData.battleSlots ) do

		if vid ~= UI.INVALID_U64_ID then

    		local shipItem = UI:GetShipItem( vid, true )
    		if shipItem then

    			local shipRefillInfo = UI:GetShipRefillInfo( shipItem )

    			if shipRefillInfo.bHasAvailable then
    				refillInfo.bHasAvailable = true
    			end

    			if not shipRefillInfo.bFullAmmo then
    				refillInfo.bFullAmmo = false
    			end

    			if not shipRefillInfo.bNoAmmo then
    				refillInfo.bNoAmmo = false
    			end

    			refillInfo.credits	= refillInfo.credits + shipRefillInfo.credits
    			refillInfo.gold		= refillInfo.gold + shipRefillInfo.gold

    		end

		end

	end

	return refillInfo

end


--
function UI:GetShipRepairInfo( vid, bZeroDurOnly )

	local repairInfo =
	{
		credits		= 0,
		gold		= 0,
		bZeroDur	= false,
		bFullDur	= true,
	}

	local shipDur = _G.GameStore_GetVesselHullCondition( vid )

	repairInfo.bZeroDur = shipDur == 0
	repairInfo.bFullDur = shipDur == 1

	if repairInfo.bZeroDur or not bZeroDurOnly then
		repairInfo.credits = _G.GameStore_GetRepairCost( vid )
	end

	return repairInfo

end


--
function UI:GetAllShipsRepairInfo( bZeroDurOnly )

	local vids = {}

	for slotIdx, vid in pairs( UI.serverData.battleSlots ) do

		if vid ~= UI.INVALID_U64_ID then
			table.insert( vids, vid )
		end

	end

	return UI:GetShipsRepairInfo( vids, bZeroDurOnly )

end


--
function UI:GetShipsRepairInfo( vids, bZeroDurOnly )

	local repairInfo =
	{
		credits		= 0,
		gold		= 0,
		bZeroDur	= false,
		bFullDur	= true,
	}

	for idx, vid in pairs( vids ) do

		local shipRepairInfo = self:GetShipRepairInfo( vid, bZeroDurOnly )

		repairInfo.credits	= repairInfo.credits + shipRepairInfo.credits
		repairInfo.gold		= repairInfo.gold + shipRepairInfo.gold

		if shipRepairInfo.bZeroDur then
			repairInfo.bZeroDur = true
		end

		if not shipRepairInfo.bFullDur then
			repairInfo.bFullDur = false
		end

	end

	return repairInfo

end


--
function UI:GetShipFullRepairPrice( defName )

	local price = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipFullRepairPrice()[ERROR]: invalid type of the 1-st param ('defName'); 'string' expected, got '%s'", type( defName ) )
		return price
	end

	local maxRankDefName = defName

	if UI:IsShipEvolving( defName ) then
		local maxRank = UI:GetEvolvingShipMaxRank( defName )
		maxRankDefName = UI:GetEvolvingShipDefForRank( defName, maxRank )
	end

	local def = UI:GetDef( maxRankDefName )
	if not def then
		sys.log( "UI:GetShipFullRepairPrice()[ERROR]: cannot find def for ship '%s'", maxRankDefName )
		return price
	end

	local DEFAULT_REPAIR_COST = 10000	-- такая цифра в коде cpp забита, и если не прописано явно, то используется она
	price = DEFAULT_REPAIR_COST

	if def.repair_cost ~= nil then

		if type( def.repair_cost ) == "number" then
			price = def.repair_cost
		else
			sys.log( "UI:GetShipFullRepairPrice()[ERROR]: invalid type of Def['%s'].repair_cost; 'number' or 'nil' expected, got '%s'", type( def.repair_cost ) )
		end

	end

	return price

end


--
function UI:IsEnoughReputationToChangeBattleSlot( slotIdx )

	local requiredReputation = self.serverData.battleSlotsChangeReputations[ slotIdx ] or 0
	return self:IsEnoughReputationWithAnyRace( requiredReputation )

end


--
function UI:IsEnoughReputationWithAnyRace( requiredReputation )

	if requiredReputation == 0 then
		return true
	end

	for race, reputation in pairs( self.serverData.playerCredits.raceRep ) do
		if reputation >= requiredReputation then
			return true
		end
	end

	return false

end


-- макс. уровень синергии
-- для "зеленых" кораблей возвращается уровень именно для этого дефа (для каждого ранга - свой макс. уровень синергии)
function UI:GetShipMaxLevel( defName )

	local maxLevel = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipMaxLevel()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return maxLevel
	end

    local rank = UI:GetShipRank( defName )

	maxLevel = UI:GetShipMaxSynergyLevelForRank( rank )

	if maxLevel == -1 then
		sys.log( "UI:GetShipMaxLevel()[ERROR]: cannot find max synergy level for %s", defName )
	end

	return maxLevel

end


