-- с каким уровнем синергии корабль окажется после покупки
-- для зеленых кораблей может быть любой деф из цепочки развития
function UI:GetShipDefaultLevel( defName )

	local level = 1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipDefaultLevel()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return level
	end

	if UI:IsShipPremium( defName ) then
		level = UI:GetShipMaxLevel( defName )

	elseif UI:IsShipEvolving( defName ) then
		local minRank = UI:GetEvolvingShipMinRank( defName )
		level = UI:GetShipMaxSynergyLevelForRank( minRank )
	end

	return level

end


--
function UI:GetShipMaxSynergyLevelForRank( rank )

	local synergyLevel = -1

	if type( rank ) ~= "number" then
		sys.log( "UI:GetShipMaxSynergyLevelForRank()[ERROR]: invalid type of the 1-st parameter (\"rank\"); \"number\" expected, got \"%s\"", type( rank ) )
		return synergyLevel
	end

	if type( _G.VesselMaxLevel ) ~= "table" then
		sys.log( "UI:GetShipMaxSynergyLevelForRank()[ERROR]: invalid type of _G.VesselMaxLevel; \"table\" expected, got \"%s\"", type( _G.VesselMaxLevel ) )
		return synergyLevel
	end

	if type( _G.VesselMaxLevel[ rank ] ) == "number" then
		synergyLevel = _G.VesselMaxLevel[ rank ]
	else
        sys.log( "UI:GetShipMaxSynergyLevelForRank()[ERROR]: invalid type of _G.VesselMaxLevel[%d]; \"number\" expected, got \"%s\"", rank, type( _G.VesselMaxLevel[ rank ] ) )
	end


	return synergyLevel

end


--
function UI:CanExtractShipSynergy( shipItem )

	if type( shipItem ) ~= "table" then
		sys.log( "UI:CanExtractShipSynergy()[ERROR]: invalid type of the 1-st parameter (\"shipItem\"); \"table\" expected, got \"%s\"", type( shipItem ) )
		return false
	end

	if UI:GetShipLevel( shipItem ) < UI:GetShipMaxLevel( shipItem.defName ) then
		return false
	end

	if UI:GetShipExp( shipItem ) <= 0 then
		return false
	end

	if UI:IsShipInBattle( shipItem ) then
		return false
	end

	return true

end


--
function UI:HasShipModuleSlot( shipItem, slotType )

	if type( shipItem ) ~= "table" then
		sys.log( "UI:HasShipModuleSlot()[ERROR]: invalid type of the 1-st parameter (\"shipItem\"), \"table\" expected, got \"%s\"", type( shipItem ) )
		return false
	end

	if type( slotType ) ~= "number" then
		sys.log( "UI:HasShipModuleSlot()[ERROR]: invalid type of the 2-nd parameter (\"slotType\"), \"number\" expected, got \"%s\"", type( slotType ) )
		return false
	end

	local slotsMask = UI:GetShipSlotsMask( shipItem )

	return UI:BitTstU64( slotsMask, slotType )

end


-- shipInfo возвращается _G.CL_GetAvailableShips()
function UI:HasShipModuleSlotByShipInfo( shipInfo, slotType )

	if type( shipInfo ) ~= "table" then
		sys.log( "UI:HasShipModuleSlotByShipInfo()[ERROR]: invalid type of the 1-st parameter (\"shipInfo\"), \"table\" expected, got \"%s\"", type( shipInfo ) )
		return false
	end

	if type( slotType ) ~= "number" then
		sys.log( "UI:HasShipModuleSlotByShipInfo()[ERROR]: invalid type of the 2-nd parameter (\"slotType\"), \"number\" expected, got \"%s\"", type( slotType ) )
		return false
	end

	local slotsMask = u64( 0 )

	if UI:IsShipCraftable( shipInfo.baseDef ) then
		
		if shipInfo.enabledSlots == u64( 0 ) then -- для тестдрайва
			slotsMask = UI:GetShipAllPossibleSlotsMask( shipInfo.baseDef ) or u64( 0 )
		else -- для кораблей которые у игрока уже есть
			slotsMask = shipInfo.enabledSlots or u64( 0 )
		end

	elseif UI:IsShipEvolving( shipInfo.baseDef ) then

		local defaultMask	= self:GetEvolvingShipDefaultSlotsMask( shipInfo.baseDef )
		local evolvedMask	= shipInfo.enabledSlots or u64( 0 )

		slotsMask = UI:BitBorU64( defaultMask, evolvedMask )

	else
		slotsMask = UI:GetShipAllPossibleSlotsMask( shipInfo.baseDef )
	end

	return UI:BitTstU64( slotsMask, slotType )

end


--
function UI:HasShipModuleSlotByEnt( ent, slotType )

	return ent:HasModuleSlot( slotType )

end


