--
function UI:GetWinLoseStrings( winnerTeam, winReason, localPlayerTeam, params )

	if not localPlayerTeam then

		local localPlayerId = _G.Game_LocalClientNum()

		localPlayerTeam = _G.CL_GetPlayerTeam( localPlayerId )
		if localPlayerTeam == 0 then
			localPlayerTeam = 1
		end

	end

	-- место - для GT_BATTLE_ROYALE и GT_HUNGER_GAMES
	local place			= params and params.place or -1
	local numPlayers	= params and params.numPlayers or -1

	-- количество пройденных волн - для волновой пве
	local numWaves		= params and params.numWaves or -1

	if place ~= -1 and numWaves ~= -1 then
		sys.log( "UI:GetWinLoseStrings()[ERROR]: invalid params: both 'place' and 'numWaves'" )
		numWaves = -1
	end

	local statusName = ""

	if winnerTeam == 0 then
		statusName = "draw"
	elseif winnerTeam == localPlayerTeam then
		statusName = "win"
	else
		statusName = "lose"
	end


	local strReason = ""
	local strStatus = ""

	if winnerTeam == 0 then

		local strIdRerason = string.format( "gameEndReason_%s", statusName )
		strReason = UI:GetStringByName( strIdRerason )

		local strIdStatus = string.format( "gameEndStatus_%s", statusName )
		strStatus = UI:GetStringByName( strIdStatus )

	else

		local reasonName = UI:Val2Key( ai.WinReason, winReason )

		local strIdRerason = string.format( "gameEndReason_%s_%s", statusName, reasonName )
		strReason = UI:GetStringByName( strIdRerason )

		local strIdStatus = string.format( "gameEndStatus_%s_%s", statusName, reasonName )
		strStatus = UI:GetStringByName( strIdStatus )

		if place ~= -1 then

			if winnerTeam ~= localPlayerTeam then

				local strPlace = string.format( "%d/%d", place, numPlayers )

				local numSubst = 0
				strStatus, numSubst = string.gsub( strStatus, "%$place%$", strPlace )

				if numSubst == 0 then
					sys.log( "UI:GetWinLoseStrings()[ERROR]: cannot find placeholder '$place$' in string '%s'", strIdStatus )
					strStatus = string.format( "%s [INVALID STRING]Place: %s", strStatus, strPlace )
				end
			end

		elseif numWaves ~= -1 then

			local numSubst = 0
			strStatus, numSubst = string.gsub( strStatus, "%$waves%$", tostring( numWaves ) )

			if numSubst == 0 then
				sys.log( "UI:GetWinLoseStrings()[ERROR]: cannot find placeholder '$waves$' in string '%s'", strIdStatus )
				strStatus = string.format( "%s [INVALID STRING]Num waves: %s", strStatus, tostring( numWaves ) )
			end

		end

	end

	return strStatus, strReason

end


--
function UI:Race2Str( race, bUpperCase )

	if bUpperCase == nil then
		bUpperCase = false
	end

	local raceName = UI:Val2Key( ai.Race, race )
