		str = UI:GetStringByName( string.format( "race_upper_%s", raceName ) )
	else
		str = UI:GetStringByName( string.format( "race_%s", raceName ) )
	end

	return str

end


--
function UI:GetRaces()

	local races = {}

	for raceName, raceId in pairs( ai.Race ) do
		if raceId ~= ai.Race.NUM then
			table.insert( races, raceId )
		end
	end

	table.sort( races )

