--
function UI:HideHelp( bSound )

	if not UI.HelpWnd then
		return
	end

	if not UI.HelpWnd:IsOnScreen() then
		return
	end

	UI.HelpWnd:Close( bSound )

end


--
function UI:ShowHelp( theme, mode, page )

	if not UI.HelpWnd then
		sys.log( "UI:ShowHelp()[ERROR]: cannot find table \"UI.HelpWnd\"" )
		return
	end

	UI.HelpWnd:Setup( theme, mode, page )
	UI.HelpWnd:Show()

end


--
function UI:TryUserToggleContextHelp()

	if not UI.HelpWnd then
		return
	end

	if UI.HelpWnd:IsOnScreen() then

		if UI:GetKeyboardFocus() == UI.HelpWnd:GetUiHandle() then
			self:HideHelp( true )
		end

	else

		self:TryUserShowContextHelp()

	end

end


--
function UI:TryUserShowContextHelp( bNotActuallyShow )

	if not UI.HelpWnd then
		return false
	end

	if UI.HelpWnd:IsOnScreen() then
		return false
	end

	if not self:CanShowHelpNow() then
		return false
	end

	if UI.Tutorial and UI.Tutorial:IsActive() then
		return false
	end

	if self:IsMsgBoxOnScreen() then
		return false
	end

	local theme = self:DetectContextHelpTheme()
	if theme == "" then
		return false
	end

	if not bNotActuallyShow then
		self:ShowHelp( theme, UI.HelpWnd.modes.USER )
	end

	return true

end


--
function UI:CheckAutoShowContextHelp( bImmediate )

	-- #0029692
	if true then
		return
	end

	-- т.к. данные о том, показывалась помощь или нет, хранятся на сервере
	if not _G.MasterServer_IsConnected() then
		return
	end

	if self:NeedSkipAutoHelp() then
		return
	end

	if not UI.HelpWnd then
		return
	end

	if UI.HelpWnd:IsOnScreen() then
		return
	end

	if not self:CanShowHelpNow() then
		return
	end

	if UI.Tutorial and UI.Tutorial:IsActive() then
		return
	end

	-- #0028277
	if _G.GetCurrentGameMode() ~= ai.Gameplay.NONE then
		return
	end

	local theme = self:DetectContextHelpTheme()
	if theme == "" then
		return
	end

	local shownState = UI.serverData.userData.helpShown and UI.serverData.userData.helpShown[ theme ]
	if shownState ~= nil and shownState ~= false and shownState ~= 0 then
		return
	end

	if bImmediate then
		self:ShowHelp( theme, UI.HelpWnd.modes.AUTO )
	else
		self.autoHelpTimer = self.AUTO_HELP_DELAY
	end

end


--
function UI:CanShowHelpNow()

	if not UI.HelpWnd then
		return false
	end

	for idx, wndName in pairs( self.helpIncompatibleWnds ) do
		local wnd = UI[ wndName ]
		if wnd and wnd:IsOnScreen() then
			return false
		end
	end

	return true

end


--
function UI:CheckHideHelp()

	if not UI.HelpWnd then
		return
	end

	if not UI.HelpWnd:IsOnScreen() then
		return
	end

	if not UI:CanShowHelpNow() then
		self:HideHelp( false )
	end

end


--
function UI:DetectContextHelpTheme()

	local theme = ""

	if UI.EquipmentWnd and UI.EquipmentWnd:IsOnScreen() then
		theme = "equipment"

	elseif UI.ShopWnd and UI.ShopWnd:IsOnScreen() then
		theme = "shop"

	elseif UI.TalentsWnd and UI.TalentsWnd:IsOnScreen() then
		theme = "skills"

	elseif UI.HangarWnd and UI.HangarWnd:IsOnScreen() and UI.HangarWnd:GetCurTab() == UI.HangarWnd.menuTabs.MAIN then
		theme = "hangar"

	elseif UI.ShipSelectionWnd and UI.ShipSelectionWnd:IsOnScreen() then
		theme = "shipSelection"

	elseif UI.HudWnd and UI.HudWnd:IsOnScreen() then
		theme = "hud"
	end

	if theme ~= "" and not self:IsHelpThemeValid( theme ) then
    	sys.log( "UI:DetectContextHelpTheme(): invalid data for theme \"%s\"", theme )
    	theme = ""
	end

	return theme

end


--
function UI:IsHelpThemeValid( theme )

	if type( theme ) ~= "string" then
		sys.log( "UI:IsHelpThemeValid()[ERROR]: invalid type of the 1-st parameter (\"theme\"); \"string\" expected, got \"%s\"", type( theme ) )
		return false
	end

	local themeInfo = UI.Help and UI.Help.themesByName and UI.Help.themesByName[ theme ]
	local textures = themeInfo and themeInfo.textures

	return textures ~= nil and next( textures ) ~= nil

end


--
function UI:NeedSkipAutoHelp()

	if not _G.MasterServer_IsConnected() then
		return false
	end

	local needSkip = UI.serverData.userData.skipAutoHelp
	return needSkip ~= nil and needSkip ~= false and needSkip ~= 0

end


