--
function UI:GetInventoryMaxLevel()

	return #self.serverData.inventoryLevelsInfo

end


--
function UI:GetAutogenInventoryMaxLevel()

	return #self.serverData.autogenInventoryLevelsInfo

end


--
function UI:GetInventoryNextLevel()

	local curLevel = self:GetInventoryCurLevel()
	local maxLevel = self:GetInventoryMaxLevel()

	if curLevel < maxLevel then
		return curLevel + 1
	else
		return -1
	end

end


--
function UI:GetAutogenInventoryNextLevel()

	local curLevel = self:GetAutogenInventoryCurLevel()
	local maxLevel = self:GetAutogenInventoryMaxLevel()

	if curLevel < maxLevel then
		return curLevel + 1
	else
		return -1
	end

end


--
function UI:GetInventoryCurSize()

	return _G.GameStore_GetInventorySize()

end


--
function UI:GetAutogenInventoryCurSize()

	return _G.GameStore_GetAutogenInventorySize()

end


--
function UI:GetInventoryMaxSizeForCurLevel()

	return _G.GameStore_GetInventoryMaxSize()

end


--
function UI:GetAutogenInventoryMaxSizeForCurLevel()

	return _G.GameStore_GetAutogenInventoryMaxSize()

end


--
function UI:GetInventoryMaxSizeForLevel( level )

	-- текущий уровень может быть 0, при этом в inventoryLevelsInfo на него информации нет
	if level == UI:GetInventoryCurLevel() then
		return UI:GetInventoryMaxSizeForCurLevel()
	end

	local info = self.serverData.inventoryLevelsInfo[ level ]

	if not info then
		sys.log( "UI:GetInventoryMaxSizeForLevel()[ERROR]: cannot find info for level %s", tostring( level ) )
		return 0
	end

	return info.size

end


--
function UI:GetAutogenInventoryMaxSizeForLevel( level )

	-- текущий уровень может быть 0, при этом в autogenInventoryLevelsInfo на него информации нет
	if level == UI:GetAutogenInventoryCurLevel() then
		return UI:GetAutogenInventoryMaxSizeForCurLevel()
	end

	local info = self.serverData.autogenInventoryLevelsInfo[ level ]

	if not info then
		sys.log( "UI:GetAutogenInventoryMaxSizeForLevel()[ERROR]: cannot find info for level %s", tostring( level ) )
		return 0
	end

	return info.size

end


--
function UI:GetInventoryDeltaSizeToBuy()

	local curLevelCount = self:GetInventoryMaxSizeForCurLevel()

	local nextLevel = self:GetInventoryNextLevel()
	if nextLevel == -1 then
		return 0
	end

	local nextLevelCount = self:GetInventoryMaxSizeForLevel( nextLevel )

	local deltaCount = nextLevelCount - curLevelCount
	if deltaCount <= 0 then
		sys.log( "UI:GetInventoryDeltaSizeToBuy()[ERROR]: inventory next level has less or equal slots count than current level" )
		return 0
	end

	return deltaCount

end


--
function UI:GetAutogenInventoryDeltaSizeToBuy()

	local curLevelCount = self:GetAutogenInventoryMaxSizeForCurLevel()

	local nextLevel = self:GetAutogenInventoryNextLevel()
	if nextLevel == -1 then
		return 0
	end

	local nextLevelCount = self:GetAutogenInventoryMaxSizeForLevel( nextLevel )

	local deltaCount = nextLevelCount - curLevelCount
	if deltaCount <= 0 then
		sys.log( "UI:GetAutogenInventoryDeltaSizeToBuy()[ERROR]: inventory next level has less or equal slots count than current level" )
		return 0
	end

	return deltaCount

end


--
function UI:GetInventoryPriceForLevel( level )

	local info = self.serverData.inventoryLevelsInfo[ level ]

	if not info then
		sys.log( "UI:GetInventoryPriceForLevel()[ERROR]: cannot find info for level %s", tostring( level ) )
		return 0, false
	end

	return UI:UnifyPrice( info.price, info.goldPrice )

end


--
function UI:GetAutogenInventoryPriceForLevel( level )

	local info = self.serverData.autogenInventoryLevelsInfo[ level ]

	if not info then
		sys.log( "UI:GetAutogenInventoryPriceForLevel()[ERROR]: cannot find info for level %s", tostring( level ) )
		return 0, false
	end

	return UI:UnifyPrice( info.price, info.goldPrice )

end


--
function UI:GetInventoryPriceToBuy()

	local nextLevel = self:GetInventoryNextLevel()

	if nextLevel == -1 then
		sys.log( "UI:GetInventoryPriceToBuy()[ERROR]: inventory is already at the max level" )
		return 0, false
	end

	return self:GetInventoryPriceForLevel( nextLevel )

end


--
function UI:IsEnoughPlaceInInventoryForItem( defName )

	local needSize = UI:GetNeedInventorySizeForItem( defName )

	if needSize == 0 then
		return true
	end

	local usedSize	= UI:GetInventoryCurSize()
	local capacity	= UI:GetInventoryMaxSizeForCurLevel()

	return ( usedSize + needSize ) <= capacity

end


--
function UI:IsEnoughPlaceInAutogenInventoryForItem( defName )

	local needCommonSize, needAutogenSize = UI:GetNeedInventorySizeForItem( defName )

	if needAutogenSize == 0 then
		return true
	end

	local usedSize	= UI:GetAutogenInventoryCurSize()
	local capacity	= UI:GetAutogenInventoryMaxSizeForCurLevel()

	return ( usedSize + needAutogenSize ) <= capacity

end


--
function UI:GetNeedInventorySizeForItem( defName, count )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetNeedInventorySizeForItem()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return 0, 0
	end

	if count ~= nil then
    	if type( count ) ~= "number" then
    		sys.log( "UI:GetNeedInventorySizeForItem()[ERROR]: invalid type of the 2-nd parameter (\"count\"); \"number\" or \"nil\" expected, got \"%s\"", type( count ) )
			return 0, 0
    	end
	end

	if count == nil then
		count = 1
	end

	local needSize = 1
	local needAutogenSize = 0

	if UI:IsDefModule( defName ) then

		if UI:IsDefAutogen( defName ) then
			needAutogenSize = count
		else
			needSize = count
		end

	elseif UI:IsDefAmmo( defName ) then

		local itemsByDef = self.serverData.inventoryByDef[ defName ]
		if itemsByDef and next( itemsByDef ) then
			needSize = 0
		end

	elseif UI:IsDefShip( defName ) then

		if count ~= 1 then
			sys.log( "UI:GetNeedInventorySizeForItem()[ERROR]: invalid count for ship" )
		end

		-- #0034678

		needSize = 0

		local def = UI:GetDef( defName )
		if def then

			if type( def.base_preset ) == "string" then

				local preset = _G.ModulePresets and _G.ModulePresets[ def.base_preset ]
				if type( preset ) == "table" then

					if preset.modules ~= nil then

						if type( preset.modules ) == "table" then

							local numModules = 0

							for slotId, moduleDefName in pairs( preset.modules ) do
								if moduleDefName ~= "" then
									numModules = numModules + 1
								end
							end

							needSize = numModules

						else
							sys.log( "UI:GetNeedInventorySizeForItem()[ERROR]: invalid type of the \"_G.ModulePresets[%s].modules\"; \"table\" or \"nil\" expected, got \"%s\"", def.base_preset, type( preset.modules ) )
						end

					end

				else
					sys.log( "UI:GetNeedInventorySizeForItem()[ERROR]: invalid type of the \"_G.ModulePresets[%s]\"; \"table\" expected, got \"%s\"", def.base_preset, type( preset ) )
				end

			else
				sys.log( "UI:GetNeedInventorySizeForItem()[ERROR]: invalid type of the \"_G.Def[%s].base_preset\"; \"string\" expected, got \"%s\"", defName, type( def.base_preset ) )
			end

		else
			sys.log( "UI:GetNeedInventorySizeForItem()[ERROR]: cannot find \"_G.Def[%s]\"", defName )
		end

	elseif UI:IsDefBundle( defName ) then

		local needSizeOne, needAutogenSizeOne = _G.GameStore_GetBundleStorageSpace( defName )

		needSize = needSizeOne * count
		needAutogenSize = needAutogenSizeOne * count

	elseif UI:IsDefResource( defName ) or UI:IsDefBlueprint( defName ) then

		needSize = 0

	else

		sys.log( "UI:GetNeedInventorySizeForItem()[ERROR]: unhandled item type for \"%s\"", defName )
		needSize = 0

	end

	return needSize, needAutogenSize

end


--
function UI:CanIncreaseInventory()

	return self:GetInventoryDeltaSizeToBuy() > 0

end


--
function UI:CanIncreaseAutogenInventory()

	return self:GetAutogenInventoryDeltaSizeToBuy() > 0

end


