--
function UI:MakePlayerNameById( playerId, bWithClan, bWithTitle, bForceRequestTitle, playerInfo )

	local nickName = "unknown"

	if type( playerId ) ~= "number" then
		sys.log( "UI:MakePlayerNameById()[ERROR]: invalid type of the 1-st parameter (\"playerId\"); \"number\" expected, got \"%s\"", type( playerId ) )
		return nickName
	end

	if type( bWithClan ) ~= "boolean" then
		sys.log( "UI:MakePlayerNameById()[ERROR]: invalid type of the 2-nd parameter (\"bWithClan\"); \"boolean\" expected, got \"%s\"", type( bWithClan ) )
		bWithClan = false
	end

	if type( bWithTitle ) ~= "boolean" then
		sys.log( "UI:MakePlayerNameById()[ERROR]: invalid type of the 3-rd parameter (\"bWithTitle\"); \"boolean\" expected, got \"%s\"", type( bWithTitle ) )
		bWithTitle = false
	end

	if bWithTitle then
    	if type( bForceRequestTitle ) ~= "boolean" then
    		sys.log( "UI:MakePlayerNameById()[ERROR]: invalid type of the 4-th parameter (\"bForceRequestTitle\"); \"boolean\" expected, got \"%s\"", type( bForceRequestTitle ) )
    		bForceRequestTitle = true
    	end
	end

	if playerInfo ~= nil then
    	if type( playerInfo ) ~= "table" then
    		sys.log( "UI:MakePlayerNameById()[ERROR]: invalid type of the 5-th parameter (\"playerInfo\"); \"number\" or \"nil\" expected, got \"%s\"", type( playerInfo ) )
    		return nickName
    	end
	end

	if not playerInfo then

    	playerInfo = _G.GetPlayerInfo( playerId )

    	if not playerInfo then
    		sys.log( "UI:MakePlayerNameById()[ERROR]: cannot find playerInfo for player %d", playerId )
    		return nickName
    	end

	end

	if type( playerInfo.nickName ) == "string" then
		nickName = playerInfo.nickName
	else
		sys.log( "UI:MakePlayerNameById()[ERROR]: invalid type of field \"nickName\" in player info for player %d; \"string\" expected, got \"%s\"", playerId, type( playerInfo.nickName ) )
	end

	local clanTag = ""
	local title = -1

	if bWithClan then

		local cid = UI:GetPlayerClanById( playerId )
		if cid ~= UI.INVALID_U64_ID then
			clanTag = UI:GetClanTag( cid )
		end

	end

	if bWithTitle then
		title = playerInfo.title or -1
	end

	return UI:MakePlayerNameInternal( nickName, clanTag, title )

end


--
function UI:MakePlayerNameByUid( uid, bWithClan, bWithTitle, bForceRequestTitle )

	local nickName = "unknown"

	if type( uid ) ~= "userdata" then
		sys.log( "UI:MakePlayerNameByUid()[ERROR]: invalid type of the 1-st parameter (\"uid\"); \"userdata\" expected, got \"%s\"", type( uid ) )
		return nickName
	end

	if uid == UI.INVALID_U64_ID then
		sys.log( "UI:MakePlayerNameByUid()[ERROR]: invalid uid" )
		return nickName
	end

	if type( bWithClan ) ~= "boolean" then
		sys.log( "UI:MakePlayerNameByUid()[ERROR]: invalid type of the 2-nd parameter (\"bWithClan\"); \"boolean\" expected, got \"%s\"", type( bWithClan ) )
		bWithClan = false
	end

	if type( bWithTitle ) ~= "boolean" then
		sys.log( "UI:MakePlayerNameByUid()[ERROR]: invalid type of the 3-rd parameter (\"bWithTitle\"); \"boolean\" expected, got \"%s\"", type( bWithTitle ) )
		bWithTitle = false
	end

	if bWithTitle then
    	if type( bForceRequestTitle ) ~= "boolean" then
    		sys.log( "UI:MakePlayerNameByUid()[ERROR]: invalid type of the 4-th parameter (\"bForceRequestTitle\"); \"boolean\" expected, got \"%s\"", type( bForceRequestTitle ) )
    		bForceRequestTitle = true
    	end
	end

	nickName = UI:GetPlayerNicknameByUid( uid )

	local clanTag = ""
	local title = -1

	if bWithClan then

		local cid = UI:GetPlayerClanByUid( uid )

		if cid ~= UI.INVALID_U64_ID then
			clanTag = UI:GetClanTag( cid )
		end

	end

	if bWithTitle then
		title = UI:GetPlayerTitleByUid( uid, bForceRequestTitle )
	end

	return UI:MakePlayerNameInternal( nickName, clanTag, title )

end


--
function UI:MakePlayerNameInternal( nickName, clanTag, title )

	if type( nickName ) ~= "string" then
		sys.log( "UI:MakePlayerNameInternal()[ERROR]: invalid type of the 1-st parameter (\"nickName\"); \"string\" expected, got \"%s\"", type( nickName ) )
		nickName = "unknown"
	end

	if type( clanTag ) ~= "string" then
		sys.log( "UI:MakePlayerNameInternal()[ERROR]: invalid type of the 2-nd parameter (\"clanTag\"); \"string\" expected, got \"%s\"", type( clanTag ) )
		clanTag = ""
	end

	if type( title ) ~= "number" then
		sys.log( "UI:MakePlayerNameInternal()[ERROR]: invalid type of the 3-rd parameter (\"title\"); \"number\" expected, got \"%s\"", type( title ) )
		title = -1
	end

	nickName = UI:ShieldSpecSymbols( nickName )

	if clanTag ~= "" then

		local tSubst =
		{
			name		= nickName,
			clan_name	= clanTag,
		}

		local strTemplate = UI:GetStringByName( "name_with_clan_postfix" )
		nickName = string.gsub( strTemplate, "%$(.-)%$", tSubst )

	end


	if title ~= -1 and title ~= _G.PlayerTitleId.NO_TITLE then

		local strTitle = UI:Val2Key( _G.PlayerTitleId, title )
		local strIdTemplate = string.format( "title_%s_format", strTitle )
		local strTemplate = UI:GetStringByName( strIdTemplate )

		nickName = string.gsub( strTemplate, "%$name%$", nickName )

	end

	return nickName

end


--
function UI:GetPlayerTitleByUid( uid, bForceRequest )

	local title = -1

	if type( uid ) ~= "userdata" then
		sys.log( "UI:GetPlayerTitleByUid()[ERROR]: invalid type of the 1-st parameter (\"uid\"); \"userdata\" expected, got \"%s\"", type( uid ) )
		return title
	end

	if type( bForceRequest ) ~= "boolean" then
		sys.log( "UI:GetPlayerTitleByUid()[ERROR]: invalid type of the 2-nd parameter (\"bForceRequest\"); \"boolean\" expected, got \"%s\"", type( bForceRequest ) )
		bForceRequest = true
	end

	local profile = _G.MasterServer_UserProfileGet( uid )
	if type( profile ) ~= "table" then
		sys.log( "UI:GetPlayerTitleByUid()[ERROR]: invalid type value returned from MasterServer_UserProfileGet(); \"table\" expected, got \"%s\"", type( profile ) )
		return title
	end

	if profile.titles == nil or bForceRequest then

		local requestId = _G.MasterServer_UserProfileRequestField( uid, _G.MasterServer.UserProfileField.UPF_TITLES )
		if requestId == 0 then
			sys.log( "UI:GetPlayerTitle()[ERROR]: invalid request id" )
		end

	end

	if profile.titles then

    	if type( profile.titles ) == "table" then

    		if type( profile.titles.title ) == "number" then
    			title = profile.titles.title
    		else
    			sys.log( "UI:GetPlayerTitleByUid()[ERROR]: invalid type of field \"titles.title\" in profile; \"number\" expected, got \"%s\"", profile.titles.title )
    		end

    	else
    		sys.log( "UI:GetPlayerTitleByUid()[ERROR]: invalid type of field \"titles\" in profile; \"table\" expected, got \"%s\"", profile.titles )
    	end

	end

	return title

end


--
function UI:GetPlayerClanByUid( uid )

	local cid = UI.INVALID_U64_ID

	if type( uid ) ~= "userdata" then
		sys.log( "UI:GetPlayerClanByUid()[ERROR]: invalid type of the 1-st parameter (\"uid\"); \"userdata\" expected, got \"%s\"", type( uid ) )
		return cid
	end

	local profile = _G.MasterServer_UserProfileGet( uid )
	if type( profile ) ~= "table" then
		sys.log( "UI:GetPlayerClanByUid()[ERROR]: invalid type value returned from MasterServer_UserProfileGet(); \"table\" expected, got \"%s\"", type( profile ) )
		return cid
	end

	if profile.clanId == nil then

		local requestId = _G.MasterServer_UserProfileRequestField( uid, _G.MasterServer.UserProfileField.UPF_CLAN_ID )
		if requestId == 0 then
			sys.log( "UI:GetPlayerClanByUid()[ERROR]: invalid request id" )
		end

	elseif type( profile.clanId ) == "userdata" then
		cid = profile.clanId

	else
		sys.log( "UI:GetPlayerClanByUid()[ERROR]: invalid type of field \"clanId\" in profile; \"userdata\" expected, got \"%s\"", profile.clanId )
	end

	return cid

end



function UI:MakePlayerNameWithTitle( uid, titleName )
	local titleId = UI.Profile:GetCurrentTitle( uid )
	local titleName = titleName or UI:Val2Key( PlayerTitleId, titleId )
	local str = UI:GetStringByName( "title_"..titleName.."_format" )
	local nickName, bCached, requestId = _G.MasterServer_GetNickName( uid )
	local cid = UI.Profile:RequestClanId( uid )
	local clanTag, bCached, requestId
	clanTag = ""
	if cid == nil then
		if UI.Profile:GetClanId( uid ) ~= UI.INVALID_U64_ID then
			clanName, bCached, requestId, clanTag = _G.MasterServer_GetClanName( UI.Profile:GetClanId( uid ) )
		end
	end
	local nameStr = ""
	if clanTag == "" then
		nameStr = nickName
	else
		nameStr = UI:GetStringByName( "name_with_clan_postfix" )
		nameStr = string.gsub( nameStr, "%$clan_name%$", clanTag )
		nameStr = string.gsub( nameStr, "%$name%$", nickName )
	end
	str = string.gsub( str, "%$name%$", nameStr )
	return str
end


--
function UI:GetBotName( entId )

	if type( entId ) ~= "number" then
		sys.log( "UI:GetBotName()[ERROR]: invalid type of the 1-st parameter (\"entId\"); \"number\" expected, got \"%s\"", type( entId ) )
		return ""
	end

	local ent = _G.Entities[ entId ]
	if not ent then
		sys.log( "UI:GetBotName()[ERROR]: cannot find ent with id %d", entId )
		return ""
	end

	local defName = ent:GetDefName()

	local name = self:GetBotNameByDef( defName )

	if UI:IsStrEmpty( name ) then
		name = ent:GetName()
	end

	return name

end


--
function UI:GetBotNameByDef( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBotNameByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return ""
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetBotNameByDef()[ERROR]: cannot find def \"%s\"", defName )
		return ""
	end

	if type( def.uiName ) ~= "string" then
		sys.log( "UI:GetBotNameByDef()[ERROR]: cannot find of Def[%s].uiName or it is not of \"string\" type", defName )
		return ""
	end

	return UI:GetStringByName( def.uiName )

end


--
function UI:GetGurrency()

	local language = UI:GetLanguage()
	local langDesc = _G.locale and _G.locale.languages and _G.locale.languages[ language ]

	local currency = ""
	if langDesc and langDesc.currency then
		currency = string.lower( langDesc.currency )
	end

	if UI:IsStrEmpty( currency ) then
		sys.log( "UI:GetGurrency()[ERROR]: cannot find currency for language %s; \"usd\" will be used", language )
		currency = "usd"
	end

	return currency

end


--
function UI:GetGoldPackYupPrice( goldPackInfo )

	local price = 0

	local currency = UI:GetGurrency()

	if currency == "rub" then
		price = goldPackInfo.yupRUB

	elseif currency == "usd" then
		price = goldPackInfo.yupUSD

	elseif currency == "eur" then
		price = goldPackInfo.yupEUR

	else
		sys.log( "UI.GetGoldPackYupPrice:GetGoldPackYupPrice()[ERROR]: unsupported currency \"%s\"; \"usd\" will be used", currency )
		price = goldPackInfo.yupUSD
	end

	if not price then
		sys.log( "UI:GetGoldPackYupPrice()[ERROR]: cannot find yup price for currency \"%s\" in pack %d", currency, goldPackInfo.id )
		price = 0
	end

	return price

end


--
function UI:Currency2Str( currency )

	local strId = string.format( "currency_%s", currency )
	return UI:GetStringByName( strId )

end


--
function UI:GetModuleKey( moduleSlotId )

	local bindName = ""
	
	local curInputType = UI:GetCurInputType()
	
	local bIsGamepadInput = false
	
	if not (curInputType == UI.inputTypes.KB) then
		bIsGamepadInput = true
	end
	
	if bIsGamepadInput and moduleSlotId == ai.SpaceShipModuleSlot.PRIMARY_WEAPON_01 then
		bindName = "primaryFire"
	
	elseif bIsGamepadInput and moduleSlotId == ai.SpaceShipModuleSlot.SECONDARY_WEAPON then
		bindName = "secondaryFire"

	elseif moduleSlotId >= ai.SpaceShipModuleSlot.WEAPON_MOD_01 and moduleSlotId <= ai.SpaceShipModuleSlot.WEAPON_MOD_03 then
		bindName = string.format( "weaponMod%d", moduleSlotId - ai.SpaceShipModuleSlot.WEAPON_MOD_01 )

	elseif moduleSlotId >= ai.SpaceShipModuleSlot.ACTIVE_01 and moduleSlotId <= ai.SpaceShipModuleSlot.ACTIVE_04 then
		bindName = string.format( "module%d", moduleSlotId - ai.SpaceShipModuleSlot.ACTIVE_01 )

	elseif moduleSlotId == ai.SpaceShipModuleSlot.SPECIAL then
		bindName = "activateSpecial"
	end

	if bindName == "" then
		return ""
	end

	return self:GetBindKeysStr( bindName, true )

end


--
function UI:GetAmmoKey( ammoSlotId )

	local bindName = string.format( "selectRocket%d", ammoSlotId )
	return self:GetBindKeysStr( bindName, true )

end

--
function UI:GetBoostKey()

	local bindName = string.format( "boost", ammoSlotId )
	return self:GetBindKeysStr( bindName, true )

end


-- возвращает таблицу в формате: { {"alt", "space"}, {"f2"} }
function UI:GetBindKeys( bindName, bFitInputTypeOnly )

	local keySets = {}

	if type( bindName ) ~= "string" then
		sys.log( "UI:GetBindKeys()[ERROR]: invalid type of the 1-st parameter (\"bindName\"); \"string\" expected, got \"%s\"", type( bindName ) )
		return keySets
	end

	if bFitInputTypeOnly ~= nil then
    	if type( bFitInputTypeOnly ) ~= "boolean" then
    		sys.log( "UI:GetBindKeys()[ERROR]: invalid type of the 2-nd parameter (\"bFitInputTypeOnly\"); \"boolean\" expected, got \"%s\"", type( bFitInputTypeOnly ) )
			bFitInputTypeOnly = nil
    	end
	end

	if bFitInputTypeOnly == nil then
		bFitInputTypeOnly = true
	end

	local cmd = ""
	local controlMode = -1

	if _G.UserBindings then
		for bondIdx, bindInfo in pairs(  _G.UserBindings ) do
			if bindInfo.name == bindName then
				if bindInfo.cmd then
					cmd = bindInfo.cmd
					controlMode = bindInfo.controlMode
				end
				break
			end
		end
	end

	if cmd == "" then
		return keySets
	end

	keySets = _G.GetKeysByCommand( cmd, controlMode ) or {}

	if bFitInputTypeOnly then

		local curInputType = UI:GetCurInputType()

		local fitKeySets = {}

    	for keySetIdx = 1, #keySets do

    		local keySet = keySets[ keySetIdx ]
			local bFit = true

        	for keyIdx = 1, #keySet do

    			local keyName = keySet[ keyIdx ]
    			local key = _G.StringToKey( keyName )

				local keyInputType = UI:GetInputTypeByKey( key )
				if keyInputType ~= curInputType then
					bFit = false
					break
				end

        	end

			if bFit then
				table.insert( fitKeySets, keySet )
			end

    	end

		keySets = fitKeySets

	end

	return keySets

end


-- возвращает строку в формате: "Alt+Пробел, F2"
function UI:GetBindKeysStr( bindName, bShort, bFitInputTypeOnly, bAllowDefaultString )

	if type( bindName ) ~= "string" then
		sys.log( "UI:GetBindKeysStr()[ERROR]: invalid type of the 1-st parameter (\"bindName\"), \"string\" expected, got %s", type( bindName ) )
		return ""
	end

	if bShort ~= nil then
		if type( bShort ) ~= "boolean" then
			sys.log( "UI:GetBindKeysStr()[ERROR]: invalid type of the 2-nd parameter (\"bShort\"), \"boolean\" or \"nil\" expected, got %s", type( bShort ) )
			bShort = nil
		end
	end

	if bShort == nil then
		bShort = false
	end

	if bAllowDefaultString ~= nil then
		if type( bAllowDefaultString ) ~= "boolean" then
			sys.log( "UI:GetBindKeysStr()[ERROR]: invalid type of the 4-th parameter (\"bAllowDefaultString\"), \"boolean\" or \"nil\" expected, got %s", type( bAllowDefaultString ) )
			bAllowDefaultString = nil
		end
	end

	if bAllowDefaultString == nil then
		bAllowDefaultString = false
	end

	local strKeys = ""

	local keySets = UI:GetBindKeys( bindName, bFitInputTypeOnly )
	if keySets and next( keySets ) then

		for keySetIdx, keySet in ipairs( keySets ) do

			local strKeySet = ""

			for keyIdx, keyName in ipairs( keySet ) do

				local strKey = self:KeyName2Str( keyName, bShort )
				strKeySet = string.format( "%s%s%s", strKeySet, keyIdx ~= 1 and "+" or "", strKey )

			end

			strKeys	= string.format( "%s%s%s", strKeys, strKeys ~= "" and ", " or "", strKeySet )

		end

	end

	if strKeys == "" and bAllowDefaultString then
		strKeys = UI:GetStringByName( "keyNotSet" )
	end

	return strKeys

end


-- key - число, значение из таблицы UI.Keys
function UI:Key2Str( key, bShort )

	local keyName = _G.KeyToString( key )
	if keyName == "" then
		sys.log( "UI:Key2Str()[ERROR]: cannot find name for key %s", tostring( key ) )
		return ""
	end

	return UI:KeyName2Str( keyName, bShort )

end



-- strKey - строка, название клавиши как оно прописывается в биндах,
-- (в cpp есть структура g_KeyNames для перевода между именами и значениями клавиш)

function UI:KeyName2Str( keyName, bShort )

	local strId = string.format( "KEY_%s", string.upper( keyName ) )

	if bShort then

		local strIdShort = string.format( "%s_short", strId )

		-- сокращенного названия может не быть
		local strShort = UI:GetStringByName( strIdShort, false )
		if strShort then
			return strShort
		end

	end

	local str = UI:GetStringByName( strId, false )

	-- #0051377,комм.(0224989) - если нет локализации, то возвращать техническое название
	if not str then
		str = keyName
	end

	return str

end


