--
function UI:GetCurInputType()

	local inputType = UI.inputTypes.KB

	if UI:IsTrueEx( cvars.ship_joyEnable ) then

		if cvars.ship_joyDinputDevice == 0 then
			inputType = UI.inputTypes.XINPUT
		else
			inputType = UI.inputTypes.JOY
		end

	end

	return inputType

end


-- Модуль, в комплекте с которым корабль покупается;
-- не путать с модулем, который автоматически установится в бою, если на корабле ничего в этом слоте не было установлено ( можно получить функцией GetShipDefaultModule() );
-- slotId - из ai.SpaceShipModuleSlot

function UI:GetShipInitialModule( shipDefName, slotId )

	local moduleDefName = ""

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipInitialModule()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return moduleDefName
	end

	if type( slotId ) ~= "number" then
		sys.log( "UI:GetShipInitialModule()[ERROR]: invalid type of the 2-nd parameter (\"slotId\"); \"number\" expected, got \"%s\"", type( slotId ) )
		return moduleDefName
	end

	local shipDef = UI:GetDef( shipDefName )
	if not shipDef then
		sys.log( "UI:GetShipInitialModule()[ERROR]: cannot find _G.Def[%s]", shipDefName )
		return moduleDefName
	end

	if type( shipDef.base_preset ) ~= "string" then
		sys.log( "UI:GetShipInitialModule()[ERROR]: invalid 0type of the \"_G.Def[%s].base_preset\"; \"string\" expected, got \"%s\"", shipDefName, type( shipDef.base_preset ) )
		return moduleDefName
	end

	-- для тест-драйва будет брать testdrive_preset, если он прописан, иначе base_preset
	local presetName = shipDef.testdrive_preset or shipDef.base_preset
	if presetName == "" then
		sys.log( "UI:GetShipInitialModule()[ERROR]: empty \"_G.Def[%s].base_preset\"", shipDefName )
		return moduleDefName
	end

	local preset = _G.ModulePresets and _G.ModulePresets[ presetName ]
	if type( preset ) ~= "table" then
		sys.log( "UI:GetShipInitialModule()[ERROR]: invalid type of the \"_G.ModulePresets[%s]\"; \"table\" expected, got \"%s\"", presetName, type( preset ) )
		return moduleDefName
	end

	if preset.modules ~= nil then

		if type( preset.modules ) == "table" then

			if preset.modules[ slotId ] ~= nil then

				if type( preset.modules[ slotId ] ) == "string" then
					moduleDefName = preset.modules[ slotId ]
				else
					sys.log( "UI:GetShipInitialModule()[ERROR]: invalid type of the \"_G.ModulePresets[%s].modules[%d]\"; \"string\" or \"nil\" expected, got \"%s\"", presetName, slotId, type( preset.modules[ slotId ] ) )
				end

			end

		else
			sys.log( "UI:GetShipInitialModule()[ERROR]: invalid type of the \"_G.ModulePresets[%s].modules\"; \"table\" or \"nil\" expected, got \"%s\"", presetName, type( preset.modules ) )
		end

	end

	return moduleDefName

end


