function UI:GetShipSpecModule( shipItem )

	local specModuleDefName = ""

	if type( shipItem ) ~= "table" then
		sys.log( "UI:GetShipSpecModule()[ERROR]: invalid type of the 1-st parameter (\"shipItem\"); \"table\" expected, got \"%s\"", type( shipItem ) )
		return specModuleDefName
	end

	if shipItem.specialModuleDef ~= nil then

		if type( shipItem.specialModuleDef ) == "string" then

			if shipItem.specialModuleDef ~= "" then
				specModuleDefName = shipItem.specialModuleDef
			end

		else
			sys.log( "UI:GetShipSpecModule()[ERROR]: invalid type of shipItem.specialModuleDef; \"string\" or \"nil\" expected, got \"%s\"", type( shipItem.specialModuleDef ) )
		end

	end

	if specModuleDefName == "" then
		specModuleDefName = UI:GetShipDefaultSpecModule( shipItem.defName )
	end

	return specModuleDefName

end


--
function UI:GetShipItem( vid, bIncludeConserved )

	if type( vid ) ~= "userdata" then
		sys.log( "UI:GetShipItem()[ERROR]: invalid type of the 1-st parameter (\"vid\"); \"userdata\" expected, got \"%s\"", type( vid ) )
		return nil
	end

	if vid == UI.INVALID_U64_ID then
		sys.log( "UI:GetShipItem()[ERROR]: invalid vid" )
		return nil
	end

	if bIncludeConserved ~= nil then
		if type( bIncludeConserved ) ~= "boolean" then
			sys.log( "UI:GetShipItem()[ERROR]: invalid type of the 2-nd parameter (\"bIncludeConserved\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIncludeConserved ) )
			bIncludeConserved = nil
		end
	end

	if bIncludeConserved == nil then
		bIncludeConserved = false
	end

	for idx, shipItem in pairs( self.serverData.allShips ) do
		if shipItem.vid == vid then

			if not shipItem.conserved or bIncludeConserved then
				return shipItem
			else
				return nil
			end

		end
	end

	return nil

end


-- имеет смысл только если работает условие, что корабль из одного протототипа может быть у игрока только в одном экземпляре
function UI:GetShipItemByDef( defName, bIncludeConserved )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipItemByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return nil
	end

	if defName == "" then
		sys.log( "UI:GetShipItemByDef()[ERROR]: empty defName" )
		return nil
	end

	if bIncludeConserved ~= nil then
		if type( bIncludeConserved ) ~= "boolean" then
			sys.log( "UI:GetShipItemByDef()[ERROR]: invalid type of the 2-nd parameter (\"bIncludeConserved\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIncludeConserved ) )
			bIncludeConserved = nil
		end
	end

	if bIncludeConserved == nil then
		bIncludeConserved = false
	end

	for idx, shipItem in pairs( self.serverData.allShips ) do
		if shipItem.defName == defName then

			if not shipItem.conserved or bIncludeConserved then
				return shipItem
			else
				return nil
			end

		end
	end

	return nil

end


--
function UI:GetInventoryItem( iid )

	if type( iid ) ~= "userdata" then
		sys.log( "UI:GetInventoryItem()[ERROR]: invalid type of the 1-st parameter (\"iid\"); \"userdata\" expected, got \"%s\"", type( iid ) )
		return nil
	end

	if iid == UI.INVALID_U64_ID then
		sys.log( "UI:GetInventoryItem()[ERROR]: invalid iid" )
