	end

	return self.serverData.inventoryByIid[ iid.h ] and self.serverData.inventoryByIid[ iid.h ][ iid.l ]

end


--
function UI:GetAutogenInventoryItem( iid )

	if type( iid ) ~= "userdata" then
		sys.log( "UI:GetAutogenInventoryItem()[ERROR]: invalid type of the 1-st parameter (\"iid\"); \"userdata\" expected, got \"%s\"", type( iid ) )
		return nil
	end

	if iid == UI.INVALID_U64_ID then
		sys.log( "UI:GetAutogenInventoryItem()[ERROR]: invalid iid" )
