--
function UI:GetAutogenInventoryItemByDef( defName )

	if _G.GetCurrentGameMode() ~= ai.Gameplay.NONE then
		sys.log( "UI:GetAutogenInventoryItemByDef()[ERROR]: no autogen defs in inventory during gameplay" )
		return nil
	end

	if type( defName ) ~= "string" then
		sys.log( "UI:GetAutogenInventoryItemByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return nil
	end

	if defName == "" then
		sys.log( "UI:GetAutogenInventoryItemByDef()[ERROR]: invalid defName" )
		return nil
	end

	return self.serverData.autogenInventoryByDef[ defName ]

end


-- возвращает как обычный итем, так и автоген (второе возвращаемое значение - true если автоген, и false если обычный)
function UI:GetInventoryItemEx( iid )

	if type( iid ) ~= "userdata" then
		sys.log( "UI:GetInventoryItemEx()[ERROR]: invalid type of the 1-st parameter (\"iid\"); \"userdata\" expected, got \"%s\"", type( iid ) )
		return nil, false
	end

	if iid == UI.INVALID_U64_ID then
		sys.log( "UI:GetInventoryItemEx()[ERROR]: invalid iid" )
		return nil, false
	end

	local item = UI:GetInventoryItem( iid )
	if item then
		return item, false
	end

	local autogenItem = UI:GetAutogenInventoryItem( iid )
	if autogenItem then
		return autogenItem, true
	end

	return nil, false

end


--
function UI:GetInventoryItemsByDef( defName, bIncludeAdverted )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetInventoryItemsByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return {}
	end

	if defName == "" then
		sys.log( "UI:GetInventoryItemsByDef()[ERROR]: empty def name" )
		return {}
	end

	if bIncludeAdverted ~= nil then
		if type( bIncludeAdverted ) ~= "boolean" then
			sys.log( "UI:GetInventoryItemsByDef()[ERROR]: invalid type of the 2-nd parameter (\"bIncludeAdverted\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIncludeAdverted ) )
			bIncludeAdverted = nil
		end
	end

	if bIncludeAdverted == nil then
		bIncludeAdverted = false
	end

	local items = {}

	if bIncludeAdverted then
		items = self.serverData.inventoryByDef[ defName ] or {}
	else

		local allItems = self.serverData.inventoryByDef[ defName ]
		if allItems then

			for itemIdx, item in pairs( allItems ) do

				-- #0098460 - предметы, которые выставлены на продажу между игроками, не должны показываться больше нигде
				local bAdverted = UI:IsItemAdverted( item.iid )
				if not bAdverted then
					table.insert( items, item )
				end

			end

		end

	end

	return items

end


--
function UI:Iid2DefName( iid )

	local item = UI:GetInventoryItemEx( iid )
	return item and item.defName or ""

end


--
function UI:GetEquippedShipItem( iid )

	return self.serverData.iid2Ship[ iid.h ] and self.serverData.iid2Ship[ iid.h ][ iid.l ]

end


--
function UI:GetEquippedSlot( iid )

	local shipItem = UI:GetEquippedShipItem( iid )
	if not shipItem then
		return -1
	end

	for slotId, equipIid in pairs( shipItem.equipModules ) do
		if equipIid == iid then
			return slotId
		end
	end

	return -1

end


--
function UI:GetEquippedShipItemAndSlot( iid )

	local shipItem = UI:GetEquippedShipItem( iid )
	if not shipItem then
		return nil, -1
	end

	for slotId, equipIid in pairs( shipItem.equipModules ) do
		if equipIid == iid then
			return shipItem, slotId
		end
	end

	return nil, -1

end


-- TODO: убрать, заменить анлоки на аккаунт-ранг
function UI:GetUnlocksForNewRaceRank( race, newReputation, oldReputations )

	local unlockItems = {}

--[[ tODO: заменить анлоки на аккаунт-ранг

	local newReputations = {}

	for r, rep in pairs( oldReputations ) do
		if r == race then
			rep = newReputation
		end
		newReputations[ r ] = rep
	end

	local newPlayerRank = UI:Reputation2Rank( UI:CalcMaxReputation( newReputations ) )
	local oldPlayerRank = UI:Reputation2Rank( UI:CalcMaxReputation( oldReputations ) )

	local baseName2Item = {}

	for defName, shopItem in pairs( UI.serverData.shopByDef ) do

		if not UI:CantItemBeBought( shopItem ) then

			local bShowItem = false

			-- у кораблей прямо прописана раса и требования к ней
			if shopItem.type == _G.GameStore.ItemType.IT_VESSEL then

	    		local bWasLocked	= not self:IsEnoughRaceReputationForItem2( shopItem.defName, oldReputations )
    			local bIsLocked		= not self:IsEnoughRaceReputationForItem2( shopItem.defName, newReputations )

				bShowItem = bWasLocked and not bIsLocked

			-- у остальных предметов не прописана раса и требования к ней, но дизайнерм хочется, чтобы чисто визуально,
			-- в списке новых анлоченнх модулей, модули показывались с учетом привязки их тира к рангу расы ( #0027373, комм.(0086223) )

			elseif shopItem.type == _G.GameStore.ItemType.IT_MODULE or shopItem.type == _G.GameStore.ItemType.IT_ROCKET then

				-- показываются только модули самого первого тира и марка из имеющихся для данного итем-субтайпа
				-- ( #0027373, комм.(0086223) )

				local baseName = string.match( shopItem.defName, "^([%w_]+)_%w+_%w+$" )
				local minItem = baseName2Item[ baseName ]

				if not minItem then
					minItem = UI:GetMinShopItem( shopItem, baseName )
					baseName2Item[ baseName ] = minItem
				end

				shopItem = minItem

				if shopItem then

					local bFound = false

					for idx, item in pairs( unlockItems ) do
						if item == shopItem then
							bFound = true
							break
						end
					end

					if not bFound then

						local itemNeedRank = UI:GetItemBuyRank( shopItem.defName )
						if itemNeedRank ~= -1 then

                    		local bWasLocked = itemNeedRank > oldPlayerRank
    						local bIsLocked = itemNeedRank > newPlayerRank

    						bShowItem = bWasLocked and not bIsLocked

						end

					end

				end

			end

    		if bShowItem then
				table.insert( unlockItems, shopItem )
    		end

		end

	end
]]

	UI:SortShop( unlockItems, false, false )


	local unlockDefNames = {}

	for idx = 1, #unlockItems do

		local shopItem = unlockItems[ idx ]

		local defNamesByType = unlockDefNames[ shopItem.type ]
		if not defNamesByType then
			defNamesByType = {}
			unlockDefNames[ shopItem.type ] = defNamesByType
		end

		table.insert( defNamesByType, shopItem.defName )

	end

	return unlockDefNames

end


-- ищется вещь в магазине, аналогичнвя данной по итем-субтайпу, но минимального тира и марка;
-- захачено - ищется не по честному, а по составным частям имени

function UI:GetMinShopItem( shopItem, baseName )

	if not shopItem then
		sys.log( "UI:GetMinShopItem()[ERROR]: nil param" )
		return nil
	end

	local def = UI:GetDef( shopItem.defName )
	if not def then
		sys.log( "UI:GetMinShopItem()[ERROR]: cannot find _G.Def[%s]", defName )
		return shopItem
	end

	local itemTier = def.tier or 1
	local itemMark = def.mark or 1

	if itemTier == 1 and itemMark == 1 then
		return shopItem
	end

	local NUM_TIERS = 5
	local NUM_MARKS = #_G.ItemMarks

	for tier = 1, NUM_TIERS do
		for mark = 1, NUM_MARKS do

			local markName = _G.ItemMarks[ mark ] and _G.ItemMarks[ mark ].name or ""
			if not UI:IsStrEmpty( markName ) then

    			local minName = string.format( "%s_T%d_%s", baseName, tier, markName )
    			local minShopItem = UI.serverData.shopByDef[ minName ]

    			if minShopItem and not UI:CantItemBeBought( minShopItem ) then
    				return minShopItem
    			end

			else
				sys.log( "UI:GetMinShopItem()[ERROR]: cannot find name for mark %d" )
			end

		end
	end

	return shopItem

end


--
function UI:GetNickNamePlaceHolder( uid )

	return string.format( "Player%s", _G.U64ToStr( uid ) )

end


--
function UI:GetPlayerNicknameByUid( uid )

	local nickName = UI:GetNickNamePlaceHolder( uid )

	local foundNickName, bCached, requestId = _G.MasterServer_GetNickName( uid )

	if bCached then
		nickName = foundNickName
	else
		-- нет имени и не предвидится, показывается дефолтное
		if requestId == 0 then
			sys.log( "UI:GetPlayerNicknameByUid()[ERROR]: cannot get nickname for uid %s", _G.U64ToStr( uid ) )
		end
	end

	return nickName

end


--
function UI:UpdateZOrder( child )

	if child:GetClassName() ~= "MsgBoxWnd" then

		local firstMsgBox = UI:GetFirstMsgBox()
		if firstMsgBox then
			UI.Root:MoveChildBefore( child, firstMsgBox )
		end

	end

	if UI.AntechamberWnd and UI.AntechamberWnd:IsOnScreen() then
		UI.Root:MoveChildToFirstPosition( UI.AntechamberWnd )
	end

	if UI.HudWnd and UI.HudWnd:IsOnScreen() then
		UI.Root:MoveChildToFirstPosition( UI.HudWnd )
	end

	if UI.HangarWnd and UI.HangarWnd:IsOnScreen() then
		UI.Root:MoveChildToFirstPosition( UI.HangarWnd )
	end

	local firstOverlayWnd = self:GetFirstOverlayWnd()

	if UI.DebriefingWnd and UI.DebriefingWnd:IsOnScreen() then
		if firstOverlayWnd then
			UI.Root:MoveChildBefore( UI.DebriefingWnd, firstOverlayWnd )
		else
			UI.Root:MoveChildToLastPosition( UI.DebriefingWnd )
		end
	end

	if UI.DebriefingOWWnd and UI.DebriefingOWWnd:IsOnScreen() then
		if firstOverlayWnd then
			UI.Root:MoveChildBefore( UI.DebriefingOWWnd, firstOverlayWnd )
		else
			UI.Root:MoveChildToLastPosition( UI.DebriefingOWWnd )
		end
	end

	if UI.Profile_Wnd and UI.Profile_Wnd:IsChildOf( UI.Root ) then		-- NB: не заменять на IsOnScreen(), т.к. профиль может быть чайлдом ангара
		if firstOverlayWnd then
			UI.Root:MoveChildBefore( UI.Profile_Wnd, firstOverlayWnd )
		else
			UI.Root:MoveChildToLastPosition( UI.Profile_Wnd )
		end
	end

	if UI.ProfileWnd_new and UI.ProfileWnd_new:IsChildOf( UI.Root ) then		-- NB: не заменять на IsOnScreen(), т.к. профиль может быть чайлдом ангара
		if firstOverlayWnd then
			UI.Root:MoveChildBefore( UI.ProfileWnd_new, firstOverlayWnd )
		else
			UI.Root:MoveChildToLastPosition( UI.ProfileWnd_new )
		end
	end

	if UI.LeaderboardWnd and UI.LeaderboardWnd:IsChildOf( UI.Root ) then		-- NB: не заменять на IsOnScreen(), т.к. окно лидербордов может быть чайлдом ангара
		if firstOverlayWnd then
			UI.Root:MoveChildBefore( UI.LeaderboardWnd, firstOverlayWnd )
		else
			UI.Root:MoveChildToLastPosition( UI.LeaderboardWnd )
		end
	end

	if UI.ChatWnd and UI.ChatWnd:GetParent() == UI.Root then
		if firstOverlayWnd then
			UI.Root:MoveChildBefore( UI.ChatWnd, firstOverlayWnd )
		else
			UI.Root:MoveChildToLastPosition( UI.ChatWnd )
		end
	end

	if UI.HudEditorWnd and UI.HudEditorWnd:IsOnScreen() then
		if firstOverlayWnd then
			UI.Root:MoveChildBefore( UI.HudEditorWnd, firstOverlayWnd )
		else
			UI.Root:MoveChildToLastPosition( UI.HudEditorWnd )
		end
	end

	if UI.DailyRewardWnd and UI.DailyRewardWnd:IsOnScreen() then
		if firstOverlayWnd then
			UI.Root:MoveChildBefore( UI.DailyRewardWnd, firstOverlayWnd )
		else
			UI.Root:MoveChildToLastPosition( UI.DailyRewardWnd )
		end
	end

	if UI.AchievementWnd and UI.AchievementWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.AchievementWnd )
	end

	if UI.ExpUpWnd and UI.ExpUpWnd.w and UI.ExpUpWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.ExpUpWnd )
	end

	if UI.PveMissionLevelWowWnd and UI.PveMissionLevelWowWnd.w and UI.PveMissionLevelWowWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.PveMissionLevelWowWnd )
	end

	if UI.NotificationsPopUpsWnd and UI.NotificationsPopUpsWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.NotificationsPopUpsWnd )
	end

	if UI.BundleWowWnd and UI.BundleWowWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.BundleWowWnd )
	end

	if UI.TourNotificationWnd and UI.TourNotificationWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.TourNotificationWnd )
	end

	if UI.ContextMenu and UI.ContextMenu:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.ContextMenu )
	end

	if UI.PopUpMenuWnd and UI.PopUpMenuWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.PopUpMenuWnd )
	end

	local tooltip = UI:GetCurTooltip()
	if tooltip then
		UI.Root:MoveChildToLastPosition( tooltip )
	end

	local facebookWaitingWnd = nil

	local wnd = UI.Root:GetLastChild()
	while wnd do

		if UI:IsWndKindOf( wnd, "SocialNetWaitingWnd" ) then
			facebookWaitingWnd = wnd
			break
		end

		wnd = wnd:GetPrevSibling()

	end

	if facebookWaitingWnd then
		UI.Root:MoveChildToLastPosition( facebookWaitingWnd )
	end

	if UI.NY2018PromoWnd and UI.NY2018PromoWnd.w and UI.NY2018PromoWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.NY2018PromoWnd )
	end

	if UI.EffectTreePreviewWnd and UI.EffectTreePreviewWnd:IsOnScreen() then
		UI.Root:MoveChildToLastPosition( UI.EffectTreePreviewWnd )
	end

	if UI.WarThunderPromoWnd and UI.WarThunderPromoWnd:IsOnScreen() then

		if UI.QuestInfoWnd and UI.QuestInfoWnd:IsOnScreen() then
			UI.Root:MoveChildBefore( UI.QuestInfoWnd, UI.WarThunderPromoWnd )
		end

	end

	if ( UI.TourWnd and UI.TourWnd:IsOnScreen() ) and ( UI.DebriefingWnd and UI.DebriefingWnd:IsOnScreen() ) then
		UI.Root:MoveChildBefore( UI.TourWnd, UI.DebriefingWnd )
	end

	-- окно повышения ранга не может показываться выше меню
	if UI.RankUpWnd and UI.RankUpWnd.w and UI.RankUpWnd:IsOnScreen() then

		if UI.MenuWnd and UI.MenuWnd.w and UI.MenuWnd:IsOnScreen() then
			UI.Root:MoveChildBefore( UI.RankUpWnd, UI.MenuWnd )
		end

		if UI.OptionsWnd and UI.OptionsWnd.w and UI.OptionsWnd:IsOnScreen() then
			UI.Root:MoveChildBefore( UI.RankUpWnd, UI.OptionsWnd )
		end

	end

	-- окно торговли показывается непосредственно выше своего главного окна
	if UI.TradingWnd and UI.TradingWnd.w and UI.TradingWnd:IsOnScreen() then

		local mainWndName = UI.TradingWnd:GetMainWndName()
		if mainWndName ~= "" then
			local mainWnd = UI[ mainWndName ]
			if mainWnd and mainWnd.w and mainWnd:IsOnScreen() then
				UI.Root:MoveChildAfter( UI.TradingWnd, mainWnd )
			end
		end

	end

	-- окно объявлений торговли показывается непосредственно выше своего главного окна
	if UI.Trading_AdvertsWnd and UI.Trading_AdvertsWnd.w and UI.Trading_AdvertsWnd:IsOnScreen() then

		local mainWndName = UI.Trading_AdvertsWnd:GetMainWndName()
		if mainWndName ~= "" then
			local mainWnd = UI[ mainWndName ]
			if mainWnd and mainWnd.w and mainWnd:IsOnScreen() then
				UI.Root:MoveChildAfter( UI.Trading_AdvertsWnd, mainWnd )
			end
		end

	end

	-- окно подтверждения апгрейда баффа показывается выше окна пве
	if UI.Pve_UpgradeBuffsWnd and UI.Pve_UpgradeBuffsWnd.w and UI.Pve_UpgradeBuffsWnd:IsOnScreen() and UI.PveWnd and UI.PveWnd.w and UI.PveWnd:IsOnScreen() then
		UI.Root:MoveChildAfter( UI.Pve_UpgradeBuffsWnd, UI.PveWnd )
	end

	-- фикс очередности ComboBox_ListWnd (раскрывающийся список комбобокса);
	-- они прилинковываются к UI.Root, и из-за предыдущих манипуляций с порядком окон они могли оказаться на неправильном месте

	local comboBoxLists = nil

	local child = UI.Root:GetFirstChild()
	while child do

		if UI:IsWndKindOf( child, "ComboBox_ListWnd" ) then

			if not comboBoxLists then
				comboBoxLists = {}
			end

			table.insert( comboBoxLists, child )

		end

		child = child:GetNextSibling()

	end

	if comboBoxLists then

		for idx, list in pairs( comboBoxLists ) do

			local comboBox = list:GetComboBox()

			local comboBoxAncestor = nil
			local parent = comboBox:GetParent()
			if parent ~= UI.Root then
    			while parent do
    				if parent:GetParent() == UI.Root then
						comboBoxAncestor = parent
						break
    				end
    				parent = parent:GetParent()
    			end
			end

			if comboBoxAncestor then
				UI.Root:MoveChildAfter( list, comboBoxAncestor )
			end

		end

	end

end


--
function UI:GetFirstOverlayWnd()

	local child = UI.Root:GetFirstChild()
	while child do

		if UI:IsOverlayWnd( child ) then
			return child
		end

		child = child:GetNextSibling()
	end

	return nil

end


--
function UI:IsOverlayWnd( wnd )

	if not wnd then
		return false
	end

	if wnd:GetClassName() == "MsgBoxWnd" then
		return true
	end

	for idx, wndName in pairs( UI.overlayWnds ) do
		local overlayWnd = UI:GetValByName( wndName )
		if overlayWnd and ( overlayWnd == wnd or UI:IsWndKindOf( wnd, overlayWnd:GetName() ) ) then
			return true
		end
	end

	return false

end


--
function UI:AddOverlayWnd( wnd )

	table.insert( UI.overlayWnds, wnd )

end


