--
function UI:GetAchievementAward( achvId, rank )

	local gold = 0

	if type( achvId ) ~= "number" then
    	sys.log( "UI:GetAchievementAward()[ERROR]: invalid type the 1-st parameter (\"achvId\"); \"number\" expected, got \"%s\"", type( achvId ) )
		return gold
	end

	if type( rank ) ~= "number" then
    	sys.log( "UI:GetAchievementAward()[ERROR]: invalid type the 2-nd parameter (\"rank\"); \"number\" expected, got \"%s\"", type( rank ) )
		return gold
	end

	local achvInfo = _G.Achievements and _G.Achievements[ achvId ]
	if not achvInfo then
		sys.log( "UI:GetAchievementAward()[ERROR]: cannot find _G.Achievements[%d]", achvId )
		return gold
	end

	if type( achvInfo.ranks ) ~= "table" then
    	sys.log( "UI:GetAchievementAward()[ERROR]: invalid type of \"_G.Achievements[%d].ranks\"; \"table\" expected, got \"%s\"", achvId, type( achvInfo.ranks ) )
		return gold
	end

	local rankInfo = achvInfo.ranks[ rank ]
	if type( rankInfo ) ~= "table" then
    	sys.log( "UI:GetAchievementAward()[ERROR]: invalid type of \"_G.Achievements[%d].ranks[%d]\"; \"table\" expected, got \"%s\"", achvId, rank, type( rankInfo ) )
		return gold
	end

	if rankInfo.gold ~= nil then

    	if type( rankInfo.gold ) == "number" then
    		gold = rankInfo.gold
    	else
    		sys.log( "UI:GetAchievementAward()[ERROR]: invalid type of \"_G.Achievements[%d].ranks[%d].gold\"; \"number\" or \"nil\" expected, got \"%s\"", achvId, rank, type( rankInfo.gold ) )
    	end

	end

	return gold

end


