--
function UI:GetMedalDesc( medalId, level )

	local medalName = UI:Val2Key( ai.MedalType, medalId )
	if medalName == "" then
		sys.log( "UI:GetMedalDesc()[ERROR]: invalid medalId: %s", tostring( medalId ) )
		return ""
	end

	local strId = string.format( "medal_desc_%s_%d", medalName, level )
	local str = UI:GetStringByName( strId )

	local desc = _G.Medals and _G.Medals[ medalId ]
	if not desc then
		sys.log( "UI:GetMedalDesc()[ERROR]: cannot find _G.Medals[ai.MedalType.%s]", medalName )
		return str
	end

	local fnSubst = function( capture )

		if capture == "AP" then

			if type( desc.additional_params ) == "number" then

				val = desc.additional_params

				if desc.isDistance then
					val = val * 10
				end

				if desc.isPercent then
					return string.format( "%s%%", UI:Num2StrSeparatedBy3( UI:Round( val * 100 ) ) )
				else
					return UI:FNum2StrSeparatedBy3( val )
				end

			else
				sys.log( "UI:GetMedalDesc()[ERROR]: cannot find _G.Medals[ai.MedalType.%s].additional_params or it is not of \"number\" type", medalName )
			end

		elseif capture == "LP" then

			local infoIdx = level + 1
			local levelInfo = desc.levels and desc.levels[ infoIdx ]

			if type( levelInfo ) == "table" then

				local val = levelInfo[ 1 ]
				if val ~= nil then

					if desc.lpIsPercent then
						return string.format( "%s%%", UI:Num2StrSeparatedBy3( UI:Round( val * 100 ) ) )

					elseif type( val ) == "number" then
						return UI:FNum2StrSeparatedBy3( val )

					else
						return tostring( val )
					end

				else
					sys.log( "UI:GetMedalDesc()[ERROR]: cannot find _G.Medals[ai.MedalType.%s].levels[%d][1]", medalName, infoIdx )
				end

			else
				sys.log( "UI:GetMedalDesc()[ERROR]: cannot find _G.Medals[ai.MedalType.%s].levels[%d] or it is not of \"table\" type", medalName, infoIdx )
			end

		else
			sys.log( "UI:GetMedalDesc()[ERROR]: unhandled capture \"%s\" in medal desc string for medal %s", capture, medalName )
		end

		return nil

	end

	str = string.gsub( str, "%$(.-)%$", fnSubst )

	return str

end


