-- описание с подстановкой параметров и описанием с условием
function UI:GetSpellDescEx( srcInfo, substColor, baseColor )

	local spellDefName = srcInfo.defName or ""

	local auraIdx	= 0
	local bHold		= false

	if srcInfo and srcInfo.data then
		auraIdx	= srcInfo.data.auraIdx or 0
		bHold	= srcInfo.data.bHold or false
	end

	local auraId = UI:GetSpellAura( spellDefName, auraIdx )

	local desc = UI:GetSpellAuraDesc( auraId, bHold )
	if desc == "" then
		return ""
	end

	srcInfo.dataType = UI.paramSrcTypes.SPELL

	local descriptionParams = UI:GetAuraDescParams( auraId )

	local fnSubst = function( condParam, condDesc )

		for paramIdx, paramInfo in pairs( descriptionParams ) do
			if paramInfo.name == condParam then

				local vals = self:GetParamVals( spellDefName, paramInfo, srcInfo.dataType, srcInfo.data, true )

				if next( vals ) == nil then
					return ""
				else
					return condDesc
				end

				break
			end
		end

		return ""

	end

	desc = string.gsub( desc, "{%s-if_([%w_]+)%s(.-)}", fnSubst )

	return UI:FillDescWithParams( srcInfo, nil, desc, descriptionParams, substColor, baseColor, true )

end


--
function UI:GetSpellAura( spellName, auraIdx )

	local auraId = -1

	if type( spellName ) ~= "string" then
		sys.log( "UI:GetSpellAura()[ERROR]: invalid type of the 1-st parameter (\"spellName\"); \"string\" expected, got \"%s\"", type( spellName ) )
		return auraId
	end

	if auraIdx ~= nil then
    	if type( auraIdx ) ~= "number" then
    		sys.log( "UI:GetSpellAura()[ERROR]: invalid type of the 2-nd parameter (\"auraIdx\"); \"number\" or \"nil\" expected, got \"%s\"", type( auraIdx ) )
    		return auraId
    	end
	end

	if auraIdx == nil then
		auraIdx = 0
	end

	local spellDef = UI:GetSpellDef( spellName )
	if not spellDef then
		sys.log( "UI:GetSpellAura()[ERROR]: cannot find _G.Spell[%s]", tostring( spellName ) )
		return auraId
	end

	if auraIdx == 0 then

		if type( spellDef.aura ) == "number" then
			auraId = spellDef.aura
		else
			sys.log( "UI:GetSpellAura()[ERROR]: invalid type of _G.Spell[\"%s\"].aura; \"number\" expected, got \"%s\"", spellName, type( spellDef.aura ) )
		end

	else

		if type( spellDef.additional_auras ) == "table" then

			local additionAuraInfo = spellDef.additional_auras[ auraIdx ]
			if type( additionAuraInfo ) == "table" then

				if type( additionAuraInfo.aura ) == "number" then
					auraId = additionAuraInfo.aura
				else
					sys.log( "UI:GetSpellAura()[ERROR]: invalid type of _G.Spell[\"%s\"].additional_auras[%d].aura; \"number\" expected, got \"%s\"", spellName, auraIdx, type( additionAuraInfo.aura ) )
				end

			else
				sys.log( "UI:GetSpellAura()[ERROR]: invalid type of _G.Spell[\"%s\"].additional_auras[%d]; \"table\" expected, got \"%s\"", spellName, auraIdx, type( additionAuraInfo ) )
			end

		else
			sys.log( "UI:GetSpellAura()[ERROR]: invalid type of _G.Spell[\"%s\"].additional_auras; \"table\" expected, got \"%s\"", spellName, type( spellDef.additional_auras ) )
		end


	end

	return auraId

end


