--
function UI:OnAccountAurasChanged()

	local oldAccountAurasMap = {}
	for idx, auraInfo in pairs( self.serverData.accountAuras ) do
		oldAccountAurasMap[ auraInfo.defName ] = true
	end

	self.serverData.accountAuras = _G.MasterServer_GetAccountAuras()

	local newAccountAurasMap = {}
	for idx, auraInfo in pairs( self.serverData.accountAuras ) do
		newAccountAurasMap[ auraInfo.defName ] = true
	end

	self.serverData.unlockingAccountAurasChanged = false

	for defName in pairs( oldAccountAurasMap ) do
		if not newAccountAurasMap[ defName ] then
			self.serverData.unlockingAccountAurasChanged = true
			break
		end
	end

	if not self.serverData.unlockingAccountAurasChanged then
    	for defName in pairs( newAccountAurasMap ) do
    		if not oldAccountAurasMap[ defName ] then
    			self.serverData.unlockingAccountAurasChanged = true
    			break
    		end
    	end
	end

end


--
function UI:CheckRemovePremiumExpiredMsgFlag()

	if UI:IsTrueEx( UI.serverData.userData.premiumExpiredMsgShown ) then

		if not _G.MasterServer_IsPremiumTimeExpired() then
			UI.serverData.userData.premiumExpiredMsgShown = false
	        UI:SaveServerUserData()
		end

	end

end


