--
function UI:GetItemColor( defName, bSel, bAlt )

	local color = UI.WHITE_COLOR

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemColor()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return color
	end

	if bSel ~= nil then
    	if type( bSel ) ~= "boolean" then
    		sys.log( "UI:GetItemColor()[ERROR]: invalid type of the 2-nd parameter (\"bSel\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bSel ) )
			bSel = nil
    	end
	end

	if bSel == nil then
		bSel = false
	end

	if bAlt ~= nil then
    	if type( bAlt ) ~= "boolean" then
    		sys.log( "UI:GetItemColor()[ERROR]: invalid type of the 3-rd parameter (\"bAlt\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bAlt ) )
			bAlt = nil
    	end
	end

	if bAlt == nil then
		bAlt = false
	end

	if UI:IsDefTokenItem( defName ) then

    	local dstDefName = UI:GetTokenItemDstDefName( defName )
    	if dstDefName ~= "" then
			return UI:GetItemColor( dstDefName, bSel, bAlt )
		else
    		sys.log( "UI:GetItemColor()[ERROR]: cannot find dst def for token-item \"%s\"", defName )
    		return color
    	end
	end

	local quality = UI:GetItemQuality( defName )

	local colorId = nil

	if quality ~= -1 then
		colorId = quality

	else
		if UI:IsDefShip( defName ) then

			if UI:GetShipRace( defName ) == ai.Race.CRYSTAL then
				colorId = UI.ALIEN_SHIP_COLOR_ID

			elseif UI:IsShipPremium( defName ) then
				colorId = UI.PREMIUM_QUALITY

			elseif UI:IsShipCraftable( defName ) then
				colorId = UI.CRAFT_SHIP_COLOR_ID

			else
				colorId = UI.SHIP_COLOR_ID
			end

		elseif UI:IsDefResource( defName ) then

			local shipDefName = UI:GetShipBuiltFromResource( defName )
			if shipDefName ~= "" then
			    colorId = UI:IsShipPremium( shipDefName ) and UI.PREMIUM_QUALITY or UI.RESOURCE_COLOR_ID
			else
				if UI:IsResourceRare( defName ) then
					colorId = UI.RESOURCE_SPECIAL_COLOR_ID
				else
					colorId = UI.RESOURCE_COLOR_ID
				end
			end

		elseif UI:IsDefBlueprint( defName ) then
			colorId = UI.RESOURCE_COLOR_ID

		else
			-- #0022915 - если марк в дефинишене не прописан, то считается, то mk1
			colorId = UI.MK1_QUALITY
		end
	end

	if colorId then
		color = UI:GetItemQualityColor( colorId, bSel, bAlt )
	end

	return color or UI.WHITE_COLOR

end


--
function UI:GetItemQualityColor( quality, bSel, bAlt )

	if bSel == nil then
		bSel = false
	end

	if bAlt == nil then
		bAlt = false
	end

	local color = nil

	if quality ~= -1 then

    	local colorId = quality

    	local itemColors = UI.itemsColors[ colorId ]
    	if itemColors then

			if bAlt then
				color = bSel and itemColors.selAlt or itemColors.alt
			end

			if color == nil then
				color = bSel and itemColors.sel or itemColors.base
			end

    	else
    		sys.log( "UI:GetItemQualityColor()[ERROR]: cannot find color for quality %s", tostring( quality ) )
    	end

	end

	return color or UI.WHITE_COLOR

end


--
function UI:GetPremiumItemColor( bSel )

	if bSel == nil then
		bSel = false
	end

	local color = UI.WHITE_COLOR
	local PREMIUM_MARK = 4

	local itemColors = UI.itemsColors[ PREMIUM_MARK ]
	if itemColors then
		color = bSel and itemColors.sel or itemColors.base
	else
		sys.log( "UI:GetPremiumItemColor()[ERROR]: cannot find color for colorId %d", colorId )
	end

	return color or UI.WHITE_COLOR

end


