--
function UI:UpdatePlayerCredentials()

	local steamID_old		= self.serverData.playerCredentials.steamID
	local localSteamID_old	= self.serverData.playerCredentials.localSteamID

	self.serverData.playerCredentials = _G.MasterServer_GetPlayerCredentials()

	if UI:IsLinkedSteam() and ( steamID_old ~= self.serverData.playerCredentials.steamID or localSteamID_old ~= self.serverData.playerCredentials.localSteamID ) then
		_G.MasterServer_RequestSteamUserInfo()
	end

end


