--
function UI:UnifyPrice( priceCredits, priceGold, bAllowMultiple, bCanUseEventCredits, priceEventCredits )

	if priceCredits == nil then
		sys.log( "UI:UnifyPrice()[ERROR]: nil priceCredits param")
		priceCredits = 0
	end

	if priceGold == nil then
		sys.log( "UI:UnifyPrice()[ERROR]: nil priceGold param")
		priceGold = 0
	end

	if bAllowMultiple == nil then
		bAllowMultiple = false
	end

	if bCanUseEventCredits == nil then
		bCanUseEventCredits = false
	end

	if priceEventCredits == nil then
		if bCanUseEventCredits then
			sys.log( "UI:UnifyPrice()[ERROR]: nil priceEventCredits param")
		end
		priceEventCredits = 0
	end

	local price			= priceCredits
	local bGold			= false
	local bEventCredits	= false

	local bValid = true

	if not bAllowMultiple then

		local numPrices = 0

		if priceCredits ~= 0 then
			numPrices = numPrices + 1
		end

		if priceGold ~= 0 then
			numPrices = numPrices + 1
		end

		if bCanUseEventCredits and priceEventCredits ~= 0 then
			numPrices = numPrices + 1
		end

		if numPrices > 1 then
			sys.log( "UI:UnifyPrice()[ERROR]: multiple prices" )
			bValid = false
		end

	end

	if bValid then

		if bCanUseEventCredits and priceEventCredits ~= 0 then
			price = priceEventCredits
			bEventCredits = true

		elseif priceCredits ~= 0 then
			price = priceCredits

		elseif priceGold ~= 0 then
			price = priceGold
			bGold = true
		end

	end

	return price, bGold, bEventCredits

end


