end


--
function UI:GetShipCustomizationPrice( customizationName, shipDefName, duration )

	if type( customizationName ) ~= "string" then
		sys.log( "UI:GetShipCustomizationPrice()[ERROR]: invalid type of the 1-st parameter (\"customizationName\"); \"string\" expected, got \"%s\"", type( customizationName ) )
		return 0, false
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipCustomizationPrice()[ERROR]: invalid type of the 2-nd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return 0, false
	end

	if duration ~= nil then
    	if type( duration ) ~= "number" then
    		sys.log( "UI:GetShipCustomizationPrice()[ERROR]: invalid type of the 3-rd parameter (\"duration\" ); \"number\" or \"nil\" expected, got \"%s\"", type( duration ) )
    		return 0, false
    	end
	else
		duration = -1
	end

	local def = _G.VesselCustomElements and _G.VesselCustomElements[ customizationName ]
	if not def then
		sys.log( "UI:GetShipCustomizationPrice()[ERROR]: cannot find _G.VesselCustomElements[%s]", tostring( customizationName ) )
		return 0, false
	end

	if type( def.prices ) ~= "table" then
		sys.log( "UI:GetShipCustomizationPrice()[ERROR]: invalid type of _G.VesselCustomElements[%s].prices; \"table\" expected, got \"%s\"", customizationName, type( def.prices ) )
		return 0, false
	end

	local shipRank = UI:GetShipRank( shipDefName )
	if shipRank == -1 then
		sys.log( "UI:GetShipCustomizationPrice()[ERROR]: cannot find rank for ship %s \"%s\"", shipDefName )
		return 0, false
	end

	local prices = def.prices[ shipRank ]
	if type( prices ) ~= "table" then
		sys.log( "UI:GetShipCustomizationPrice()[ERROR]: cannot find prices for ship rank; invalid type of _G.VesselCustomElements[%s].prices[%d]; \"table\" expected, got \"%s\"", customizationName, shipRank )
		return 0, false
	end

	for idx, info in pairs( prices ) do

		if info.duration == duration then

			if info.cost ~= nil then
				if type( info.cost ) ~= "number" then
					sys.log( "UI:GetShipCustomizationPrice()[ERROR]: invalid type of _G.VesselCustomElements[%s].prices[%d].cost; \"number\" or \"nil\" expected, got \"%s\"", customizationName, shipRank, type( info.cost ) )
					return 0, false
				end
			end

			if info.goldCost ~= nil then
				if type( info.goldCost ) ~= "number" then
					sys.log( "UI:GetShipCustomizationPrice()[ERROR]: invalid type of _G.VesselCustomElements[%s].prices[%d].goldCost; \"number\" or \"nil\" expected, got \"%s\"", customizationName, shipRank, type( info.goldCost ) )
					return 0, false
				end
			end

			local credits	= info.cost or 0
			local gold		= info.goldCost or 0

			if info.cost == nil and info.goldCost == nil then
				sys.log( "UI:GetShipCustomizationPrice()[ERROR]: neither \"cost\" nor \"goldCost\" are specified in _G.VesselCustomElements[%s].prices[%d]", customizationName, shipRank )

			elseif credits == 0 and gold == 0 then
				sys.log( "UI:GetShipCustomizationPrice()[ERROR]: both \"cost\" and \"goldCost\" are zero in _G.VesselCustomElements[%s].prices[%d]", customizationName, shipRank )

			elseif credits ~= 0 and gold ~= 0 then
				sys.log( "UI:GetShipCustomizationPrice()[ERROR]: both \"cost\" and \"goldCost\" are non zero in _G.VesselCustomElements[%s].prices[%d]", customizationName, shipRank )
			end

			return UI:UnifyPrice( credits, gold )

		end

	end

	sys.log( "UI:GetShipCustomizationPrice()[ERROR]: cannot find price for customization %s, duration %s, ship %s", customizationName, tostring( duration ), shipDefName )
	return 0, false

end


--
function UI:GetShipRank( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipRank()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return -1
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetShipRank()[ERROR]: cannot find _G.Def[%s]", defName )
		return -1
	end

	if type( def.rank ) ~= "number" then
		sys.log( "UI:GetShipRank()[ERROR]: invalid type of _G.Def[%s].rank; \"number\" expected, got \"%s\"", defName, type( def.rank ) )
		return -1
	end

	return def.rank

end


