--
function UI:GetStickerDecalPath( stickerName )

	local def = _G.VesselCustomElements and _G.VesselCustomElements[ stickerName ]
	if not def then
		sys.log( "UI:GetStickerDecalFileName()[ERROR]: cannot find _G.VesselCustomElements[%s]", tostring( stickerName ) )
		return ""
	end

	if def.decal then

		local decalInfo = _G.ShipDecals and _G.ShipDecals.Token and _G.ShipDecals.Token[ def.decal ]
		if decalInfo then

			if decalInfo.ui then
				return decalInfo.ui
			end

			if decalInfo.albedo then
				return decalInfo.albedo
			else
				sys.log( "UI:GetStickerDecalFileName()[ERROR]: cannot find _G.ShipDecals.Token[%s].albedo", def.decal )
			end

		else
			sys.log( "UI:GetStickerDecalFileName()[ERROR]: cannot find _G.ShipDecals.Token[%s]", def.decal )
		end

	else
		sys.log( "UI:GetStickerDecalFileName()[ERROR]: cannot find _G.VesselCustomElements[%s].deval", stickerName )
	end

	return ""

end


