--
function UI:GetHudMarkSpecIcoAnimName( colorScheme, bInRange )

	if bInRange == nil then
		bInRange = false
	end

	local animName = ""

	if colorScheme == UI.gameObjColorSchemes.FRIEND then
		animName = bInRange and "friend_shot" or "friend"

	elseif colorScheme == UI.gameObjColorSchemes.ENEMY then
		animName = bInRange and "enemy_shot" or "enemy"

	elseif colorScheme == UI.gameObjColorSchemes.NEUTRAL then
		animName = bInRange and "neutral_shot" or "neutral"

	elseif colorScheme == UI.gameObjColorSchemes.SQUAD then
		animName = "squad"

	elseif colorScheme == UI.gameObjColorSchemes.ME then
		animName = bInRange and "me_shot" or "me"

	elseif colorScheme == UI.gameObjColorSchemes.AGGRESSIVE then
		animName = bInRange and "agressiv_shot" or "agressiv"

	elseif colorScheme == UI.gameObjColorSchemes.ALIEN then
		animName = bInRange and "nlo_shot" or "nlo"
	end

	if animName == "" then
		sys.log( "UI:GetHudMarkSpecIcoAnimName()[ERROR]: cannot find animation for color scheme %s", tostring( colorScheme ) )
	end

	return animName

end


--
function UI:ConvertServerString( msg )

	msg = UI:ShieldSpecSymbolsEx( msg )
	return UI:SubstituteLinks( msg )

end


--
function UI:SubstituteLinks( msg )

	local fnLinkSubst = function( tagName, params )

		if tagName == "link" then

			if params then

				local href		= string.match( params, "href%s*=%s*\"(.-)\"" )
				local text		= string.match( params, "text%s*=%s*\"(.-)\"" )
				local strSteam	= string.match( params, "steam%s*=%s*\"(.-)\"" )

				if href and text then

					local bSteam = false
					if strSteam then
						bSteam = strSteam == "true" or strSteam == "1"
					end

					return string.format( "$link [type HTTP][params {href=\"%s\", text=\"%s\", bSteam=%s }]$", href, text, tostring( bSteam ) )

				end

			end

			sys.log( "UI:SubstituteLinks()[ERROR]: invalid format of \"link\" tag; usage: [link href=\"url\" text=\"text\"]" )


		elseif tagName == "item" then

			if params then

				local defName		= string.match( params, "name%s*=%s*\"(.-)\"" )
				local strOpenShop	= string.match( params, "shop%s*=%s*\"(.-)\"" )
				local text			= string.match( params, "text%s*=%s*\"(.-)\"" ) or ""

				if defName then

					local bOpenShop = false
					if strOpenShop then
						bOpenShop = strOpenShop == "true" or strOpenShop == "1"
					end

					local itemType = _G.GetStoreItemTypeByDef( defName )

					if itemType == _G.GameStore.ItemType.IT_VESSEL then
						return string.format( "$link [type SHIP][params {defName=\"%s\", bOpenShop=%s, text=\"%s\"}]$", defName, tostring( bOpenShop ), text )

					elseif itemType == _G.GameStore.ItemType.IT_MODULE or itemType == _G.GameStore.ItemType.IT_ROCKET then
						return string.format( "$link [type ITEM][params {defName=\"%s\", bOpenShop=%s, text=\"%s\"}]$", defName, tostring( bOpenShop ), text )

					else
						sys.log( "UI.NewsWnd:SubstituteLinks()[ERROR]: cannot show link for itemType %s", UI:Val2Key( _G.GameStore.ItemType, itemType ) )
					end

				end

			end

			sys.log( "UI:SubstituteLinks()[ERROR]: invalid format of \"item\" tag; usage: [item name=\"defName\" shop=\"true\" text=\"text\"] (shop and text are optional)" )

		else
--			sys.log( "UI:SubstituteLinks()[ERROR]: unhandled tag: \"%s\"", tagName )
		end

		return nil

	end

	return string.gsub( msg, "%[([%w_]+)%s*(.-)%]", fnLinkSubst )

end


