--
function UI:GetShipBattleSlotByVid( vid )

	if type( vid ) ~= "userdata" then
		sys.log( "UI:GetShipBattleSlotByVid()[ERROR]: invalid type of the 1-st parameter (\"vid\"); \"userdata\" expected, got \"%s\"", type( vid ) )
		return -1
	end

    if vid == UI.INVALID_U64_ID then
		return -1
	end

	for battleSlotIdx, battleVid in pairs( self.serverData.battleSlots ) do
		if battleVid == vid then
			return battleSlotIdx
		end
	end

	return -1

end


--
function UI:CantItemBeBought( shopItem, bIgnoreAccountAuras )

	if bIgnoreAccountAuras == nil then
		bIgnoreAccountAuras = true
	end

	if not shopItem then
		return true
	end

	if UI:IsTrueEx( shopItem.cantBeBought ) then
		return true
	end

	if not bIgnoreAccountAuras then
    	if UI:IsItemLockedByAccountAura( shopItem.defName ) then
    		return true
    	end
	end

	return false

end


