--
function UI:CantItemBeEquippedByDef( defName )

	local def = UI:GetDef( defName )
	if not def then
		return true
	end

	local bCantBeEquipped = def.cant_be_equipped
	if bCantBeEquipped == nil then
		bCantBeEquipped = false
	end

	return bCantBeEquipped

end


--
function UI:GetAccountAuraDuration( defName )

	local time		= nil
	local battles	= nil

	if type( defName ) ~= "string" then
		sys.log( "UI:GetAccountAuraDuration()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return time, battles
	end

	local def = _G.AccountAura and _G.AccountAura[ defName ]
	if not def then
		sys.log( "UI:GetAccountAuraDuration()[ERROR]: cannot find _G.AccountAura[%s]", tostring( defName ) )
		return time, battles
	end

	if def.duration_in_hours ~= nil then
		if type( def.duration_in_hours ) == "number" then
			time = def.duration_in_hours
		else
			sys.log( "UI:GetAccountAuraDuration()[ERROR]: invalid type of _G.AccountAura[%s].duration_in_hours; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.duration_in_hours ) )
		end
	end

	if def.duration_in_counters ~= nil then
		if type( def.duration_in_counters ) == "number" then
			battles = def.duration_in_counters
		else
			sys.log( "UI:GetAccountAuraDuration()[ERROR]: invalid type of _G.AccountAura[%s].duration_in_counters; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.duration_in_counters ) )
		end
	end

	return time, battles

end



--
function UI:IsAccountAuraOnlyForBattlePass( defName )

	local onlyBP = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsAccountAuraOnlyForBattlePass()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return onlyBP
	end

	local def = _G.AccountAura and _G.AccountAura[ defName ]
	if not def then
		sys.log( "UI:IsAccountAuraOnlyForBattlePass()[ERROR]: cannot find _G.AccountAura[%s]", tostring( defName ) )
		return onlyBP
	end

	if def.only_for_battle_pass ~= nil then
		if type( def.only_for_battle_pass ) == "boolean" then
			onlyBP = def.only_for_battle_pass
		else
			sys.log( "UI:IsAccountAuraOnlyForBattlePass()[ERROR]: invalid type of _G.AccountAura[%s].only_for_battle_pass; \"boolean\" or \"nil\" expected, got \"%s\"", defName, type( def.only_for_battle_pass ) )
		end
	end

	return onlyBP

end


--
function UI:GetLeftTimeFor( endTime )

	if type( endTime ) ~= "userdata" then
		sys.log( "UI:GetLeftTimeFor()[ERROR]: invalid type of \"endTime\"; \"userdata\" expected, got \"%s\"", type( endTime ) )
		return 0
	end

	local curTime = _G.MasterServer_GetServerTime()
	local leftTime = _G.GetPlatformTimeDiffSec( endTime, curTime )

	return math.max( leftTime, 0 )

end


-- основывается на предположении, что может быть только одна аура одинакового дефа
function UI:GetAccountAuraLeftTime( accountAuraDefName, bLogErrors )

	if bLogErrors == nil then
		bLogErrors = false
	end

	local timeLeft		= nil
	local battlesLeft	= nil

	if type( accountAuraDefName ) ~= "string" then
		if bLogErrors then
			sys.log( "UI:GetAccountAuraLeftTime()[ERROR]: invalid type of the 1-st parameter (\"accountAuraDefName\"); \"string\" expected, got \"%s\"", type( accountAuraDefName ) )
		end
		return timeLeft, battlesLeft
	end

	local accountAuras	= _G.MasterServer_GetAccountAuras()
	local bFound		= false

	for idx, info in pairs( accountAuras ) do

		if info.defName == accountAuraDefName then

			if not bFound then

    			local timeDur, battlesDur = UI:GetAccountAuraDuration( accountAuraDefName )

    			if battlesDur then
    				if info.counterLeft then
    					battlesLeft = info.counterLeft
    				else
						if bLogErrors then
    						sys.log( "UI:GetAccountAuraLeftTime()[ERROR]: cannot find \"counterLeft\" dor aura \"%s\"", accountAuraDefName )
						end
    				end
				end
				
    			if timeDur then
					if info.timeLeft then
						timeLeft = info.timeLeft
					else
						if bLogErrors then
    						sys.log( "UI:GetAccountAuraLeftTime()[ERROR]: cannot find \"timeLeft\" dor aura \"%s\"", accountAuraDefName )
						end
					end
				end

				bFound = true

			else
				if bLogErrors then
					sys.log( "UI:GetAccountAuraLeftTime()[ERROR]: more than one aura of the same def (\"%s\")", accountAuraDefName )
				end
				break
			end

		end

	end

	if not bFound then
		if bLogErrors then
			sys.log( "UI:GetAccountAuraLeftTime()[ERROR]: cannot find account aura \"%s\" among applied auras", accountAuraDefName )
		end
	end

	return timeLeft, battlesLeft

end


--
function UI:GetPlayerClanById( playerId )

	local cid = UI.INVALID_U64_ID

	if type( playerId ) ~= "number" then
		sys.log( "UI:GetPlayerClanById()[ERROR]: invalid type of the 1-st param (\"playerId\"); \"number\" expected, got \"%s\"", type( playerId ) )
		return cid
	end

	local playerInfo = _G.GetPlayerInfo( playerId )
	if not playerInfo then
		sys.log( "UI:GetPlayerClanById()[ERROR]: cannot find player info for player %d", playerId )
		return cid
	end

	if playerInfo.isBot then

		if playerInfo.botUid then
			if playerInfo.botUid ~= UI.INVALID_U64_ID then
				cid = UI:GetPlayerClanByUid( playerInfo.botUid )
			end
		else
			sys.log( "UI:GetPlayerClanById()[ERROR]: cannot find \"botUid\" in playerInfo for player %d", playerId )
		end

	else

		if playerInfo.cid then
			cid = playerInfo.cid
		else
			sys.log( "UI:GetPlayerClanById()[ERROR]: cannot find \"cid\" in playerInfo for player %d", playerId )
		end

	end

	return cid

end


