--
function UI:GetClanIco( cid )

	local hTex = UI:GetTex( "clan_icon_default" )

	if type( cid ) ~= "userdata" then
		sys.log( "UI:GetClanIco()[ERROR]: invalid type of the 1-st param (\"cid\"); \"userdata\" expected, got \"%s\"", type( cid ) )
		return hTex
	end

	local emblemName = UI:GetClanEmblemName( cid )

	if emblemName == "" then
		return hTex
	end

	if type( _G.ClanEmblems ) ~= "table" then
		sys.log( "UI:GetClanIco()[ERROR]: invalid type of \"_G.ClanEmblems\"; \"table\" expected, got \"%s\"", type( _G.ClanEmblems ) )
		return hTex
	end

	local emplemData = _G.ClanEmblems[ emblemName ]
	if type( emplemData ) ~= "table" then
		sys.log( "UI:GetClanIco()[ERROR]: invalid type of \"_G.ClanEmblems[\"%s\"]\"; \"table\" expected, got \"%s\"", emblemName, type( emplemData ) )
		return hTex
	end

	local texName = emplemData.decal
	if type( texName ) ~= "string" then
		sys.log( "UI:GetClanIco()[ERROR]: invalid type of \"_G.ClanEmblems[\"%s\"].texName\"; \"string\" expected, got \"%s\"", emblemName, type( texName ) )
		return hTex
	end

	hTex = UI:GetTex( texName )

	return hTex

end


--
function UI:HasClanPrivilege( privilegeId )

	local bIsPrivilege = false

	if type( privilegeId ) ~= "number" then
		sys.log( "UI:HasClanPrivilege()[ERROR]: invalid type of the 1-st param (\"privilegeId\"); \"number\" expected, got \"%s\"", type( privilegeId ) )
		return bIsPrivilege
	end

	if not UI.Clan:IsInClan() then
		sys.log( "UI:HasClanPrivilege()[ERROR]: not in clan" )
		return bIsPrivilege
	end

	local privilegesData = _G.MasterServer_ClanGetActionPrivileges( _G.MasterServer_GetLocalUserId() )
	if type( privilegesData ) ~= "table" then
		sys.log( "UI:HasClanPrivilege()[ERROR]: invalid type of return value #1 from _G.MasterServer_ClanGetActionPrivileges(); \"table\" expected, got \"%s\"", type( privilegesData ) )
		return bIsPrivilege
	end

	for idx, id in pairs( privilegesData ) do
		if id == privilegeId then
			bIsPrivilege = true
			break
		end
	end

	return bIsPrivilege

end


