function UI:GetTalentRank( talent )

	if type( _G.TalentGroups ) ~= "table" then
		sys.log( "UI:GetTalentRank()[ERROR]: cannot find _G.TalentGroups or it is not of \"table\" type" )
		return -1
	end

	for rank, talentsByRank in pairs( _G.TalentGroups ) do
		for idx, t in pairs( talentsByRank ) do
			if t == talent then
				return rank
			end
		end
	end

	sys.log( "UI:GetTalentRank()[ERROR]: cannot find rank for talent \"%s\"", talent )
	return -1

end


