--
function UI:IsTalentAvailable( talent, talentSetId )

	if UI:IsTalentActive( talent, talentSetId ) then
		return true
	end

	local talentRank = UI:GetTalentRank( talent )

	local playerRep = UI:GetPlayerMaxReputationForRace()
	local playerRank = UI:Reputation2Rank( playerRep )

	return talentRank <= playerRank

end


--
function UI:IsTalentActive( talent, talentSetId )

	local talentsMap = UI.serverData.talentsMap[ talentSetId ]
	return talentsMap ~= nil and talentsMap[ talent ] == true

end


--
function UI:GetActiveTalentForRank( rank, talentSetId )

	local talentsByRank = _G.TalentGroups and _G.TalentGroups[ rank ]
	if not talentsByRank then
		sys.log( "UI:GetActiveTalentForRank()[ERROR]: cannot find _G.TalentGroups[%s].rank", tostring( rank ) )
		return ""
	end

	for idx, talent in pairs( talentsByRank ) do
		if UI:IsTalentActive( talent, talentSetId ) then
			return talent
		end
	end

	return ""

end


--
function UI:GetTalentSetPrices( talentSetId, bIsBuyPrice )

	local priceInfos = {}

	if type( talentSetId ) ~= "number" then
		sys.log( "UI:GetTalentSetPrices()[ERROR]: invalid type of the 1-st parameter (\"talentSetId\"); \"number\" expected, got \"%s\"", type( talentSetId ) )
		return priceInfos
	end

	if bIsBuyPrice ~= nil then
    	if type( bIsBuyPrice ) ~= "boolean" then
    		sys.log( "UI:GetTalentSetPrices()[ERROR]: invalid type of the 2-nd parameter (\"bIsBuyPrice\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIsBuyPrice ) )
			bIsBuyPrice = nil
    	end
	end

	if bIsBuyPrice == nil then
		bIsBuyPrice = true
	end

	if type( _G.TalentSetCosts ) ~= "table" then
		sys.log( "UI:GetTalentSetPrices()[ERROR]: invalid type of \"_G.TalentSetCosts\"; \"table\" expected, got \"%s\"", type( _G.TalentSetCosts ) )
		return priceInfos
	end

	local talentSetInfo = _G.TalentSetCosts[ talentSetId + 1 ]
	if type( talentSetInfo ) ~= "table" then
		sys.log( "UI:GetTalentSetPrices()[ERROR]: invalid type of \"_G.TalentSetCosts[%d]\"; \"table\" expected, got \"%s\"", talentSetId + 1, type( talentSetInfo ) )
		return priceInfos
	end


	-- кредиты

	local credits = talentSetInfo.credits
	if credits ~= nil then
		if type( credits ) ~= "number" then
			sys.log( "UI:GetTalentSetPrices()[ERROR]: invalid type of \"_G.TalentSetCosts[%d].credits\"; \"number\" or \"nil\" expected, got \"%s\"", talentSetId + 1, type( credits ) )
			credits = nil
		end
	end

	if credits == nil then
		credits = 0
	end

	if credits ~= 0 then

    	local creditsPriceInfo =
    	{
    		priceType	= _G.GameStore.CreditsType.CT_CREDITS,
    		bIsBuyPrice	= bIsBuyPrice,
			val			= credits,
    		basePrice	= credits,
    	}

		table.insert( priceInfos, creditsPriceInfo )

	end


	-- золото

	local gold = talentSetInfo.gold_credits
	if gold ~= nil then
		if type( gold ) ~= "number" then
			sys.log( "UI:GetTalentSetPrices()[ERROR]: invalid type of \"_G.TalentSetCosts[%d].gold_credits\"; \"number\" or \"nil\" expected, got \"%s\"", talentSetId + 1, type( gold ) )
			gold = nil
		end
	end

	if gold == nil then
		gold = 0
	end

	if gold ~= 0 then

    	local goldPriceInfo =
    	{
    		priceType	= _G.GameStore.CreditsType.CT_GOLD,
    		bIsBuyPrice	= bIsBuyPrice,
			val			= gold,
    		basePrice	= gold,
    	}

		table.insert( priceInfos, goldPriceInfo )

	end


	-- токены

	local tokens = talentSetInfo.tokens
	if tokens ~= nil then
		if type( tokens ) ~= "number" then
			sys.log( "UI:GetTalentSetPrices()[ERROR]: invalid type of \"_G.TalentSetCosts[%d].tokens\"; \"number\" or \"nil\" expected, got \"%s\"", talentSetId + 1, type( tokens ) )
			tokens = nil
		end
	end

	if tokens == nil then
		tokens = 0
	end

	if tokens ~= 0 then

    	local tokensPriceInfo =
    	{
    		priceType	= _G.GameStore.CreditsType.CT_TOKENS,
    		bIsBuyPrice	= bIsBuyPrice,
			val			= tokens,
    		basePrice	= tokens,
    	}

		table.insert( priceInfos, tokensPriceInfo )

	end

	return priceInfos

end


--
function UI:GetTalentSetRank( talentSetId )

	local rank = -1

	if type( talentSetId ) ~= "number" then
		sys.log( "UI:GetTalentSetRank()[ERROR]: invalid type of the 1-st parameter (\"talentSetId\"); \"number\" expected, got \"%s\"", type( talentSetId ) )
		return rank
	end

	if type( _G.TalentSetCosts ) ~= "table" then
		sys.log( "UI:GetTalentSetRank()[ERROR]: invalid type of \"_G.TalentSetCosts\"; \"table\" expected, got \"%s\"", type( _G.TalentSetCosts ) )
		return rank
	end

	local talentSetInfo = _G.TalentSetCosts[ talentSetId + 1 ]
	if type( talentSetInfo ) ~= "table" then
		sys.log( "UI:GetTalentSetRank()[ERROR]: invalid type of \"_G.TalentSetCosts[%d]\"; \"table\" expected, got \"%s\"", talentSetId + 1, type( talentSetInfo ) )
		return rank
	end

	if talentSetInfo.rank ~= nil then

		if type( talentSetInfo.rank ) == "number" then
			rank = talentSetInfo.rank
		else
			sys.log( "UI:GetTalentSetRank()[ERROR]: invalid type of \"_G.TalentSetCosts[%d].rank\"; \"number\" or \"nil\" expected, got \"%s\"", talentSetId + 1, type( talentSetInfo.rank ) )
		end

	end

	return rank

end


