--
function UI:UpdateServerData_OnTalentsUpdate( result, requestId )

	if result ~= _G.SkillManager.TalentResult.TR_OK then
		return
	end

	self:UpdateTalents()

	UI.serverData.talentSetBinds = _G.SkillManager_GetTalentBindings()

end


--
function UI:UpdateServerData_OnSetTalentBindings( result, requestId, param1, param2 )

	UI.serverData.talentSetBinds = _G.SkillManager_GetTalentBindings()

end


--
function UI:UpdateServerData_OnTalentsAcquisition( result, requestId, talentNames, talentSetId )

	if result ~= _G.SkillManager.TalentResult.TR_OK then
		return
	end

	self:UpdateTalentsForSet( talentSetId )

end


--
function UI:UpdateServerData_OnTalentsReset( result, requestId, talentSetId )

	if result ~= _G.SkillManager.TalentResult.TR_OK then
		return
	end

	self:UpdateTalentsForSet( talentSetId )

end


--
function UI:UpdateTalents()

	for talentSetId = 0, UI.MAX_TALENT_SETS - 1 do
		UI:UpdateTalentsForSet( talentSetId )
	end

end


--
function UI:UpdateTalentsForSet( talentSetId )

	self.serverData.talents[ talentSetId ] = _G.SkillManager_GetTalents( talentSetId ) or {}

	self.serverData.talentsMap[ talentSetId ] = {}

	for idx, talent in pairs( self.serverData.talents[ talentSetId ] ) do
		self.serverData.talentsMap[ talentSetId ][ talent ] = true
	end

end


--
function UI:Talent2Str( talent )

	if type( talent ) ~= "string" then
		sys.log( "UI:Talent2Str()[ERROR]: invalid type od the 1-st parameter (\"talent\"); \"string\" expected, got \"%s\"", type( talent ) )
		return ""
	end

	local strId = string.format( "talent_%s_name", talent )
	return UI:GetStringByName( strId )

end


--
function UI:GetTalentDesc( talent, substColor, baseColor )

	if type( talent ) ~= "string" then
		sys.log( "UI:GetTalentDesc()[ERROR]: invalid type od the 1-st parameter (\"talent\"); \"string\" expected, got \"%s\"", type( talent ) )
		return ""
	end

	if type( substColor ) ~= "number" then
		sys.log( "UI:GetTalentDesc()[ERROR]: invalid type od the 2-nd parameter (\"substColor\"); \"number\" expected, got \"%s\"", type( substColor ) )
		substColor = UI.TEXT_SEL_COLOR
	end

	if type( baseColor ) ~= "number" then
		sys.log( "UI:GetTalentDesc()[ERROR]: invalid type od the 3-rd parameter (\"baseColor\"); \"number\" expected, got \"%s\"", type( baseColor ) )
		baseColor = UI.TEXT_BASE_COLOR
	end

	local strSubstColor = UI:Color2Str( substColor )
	local strBaseColor = UI:Color2Str( baseColor )

	local strId = string.format( "talent_%s_desc", talent )
	local str = UI:GetStringByName( strId )

	local fnSubst = function( capture )

		local strSubst = nil

		local itemGroupName = string.match( capture, "^itemGroup_(.-)$" )
		if itemGroupName then

			local itemGroup = ai.ItemGroup[ itemGroupName ]
			if itemGroup then
				strSubst = UI:ItemGroup2Str( itemGroup )
			else
				sys.log( "UI:GetTalentDesc()[ERROR]: invalid item group: \"%s\" for talent %s", itemGroupName, talent )
			end

		else

			local def = _G.Talent[ talent ]
			if def then

				local val = def[ capture ]
				if val ~= nil then

					if type( val ) == "number" then

						local strPercFieldName = string.format( "%s_percent", capture )
						local bPerc = def[ strPercFieldName ]

						if bPerc ~= nil then

							if type( bPerc ) == "boolean" then

        						if bPerc then

        							if val < 0 then
        								val = UI:Round( 100 - 100 / ( 1 - val ) )
        							else
        								val = UI:Round( val * 100 )
        							end

        						end

							else
								sys.log( "UI:GetTalentDesc()[ERROR]: invalid type of _G.Talent[%s].%s; \"boolean\" expected, got \"%s\"", talent, strPercFieldName, type( bPerc ) )
								val = nil
							end

						end

					else
						sys.log( "UI:GetTalentDesc()[ERROR]: invalid type of _G.Talent[%s].%s; \"number\" expected, got \"%s\"", talent, capture, type( val ) )
						val = nil
					end

				else
					sys.log( "UI:GetTalentDesc()[ERROR]: cannot find _G.Talent[%s].%s", talent, capture )
				end

				if val ~= nil then
					strSubst = UI:FNum2StrSeparatedBy3( val )
				end

			else
				sys.log( "UI:GetTalentDesc()[ERROR]: cannot find _G.Talent[%s]", talent )
			end

		end

		if strSubst then
			strSubst = string.format( "%s%s%s", strSubstColor, strSubst, strBaseColor )
		end

		return strSubst

	end

	str = string.gsub( str, "%$(.-)%$", fnSubst )
	str = string.format( "%s%s", strBaseColor, str )

	return str

end


