--
function UI:IsShipLockedByDependancy( defName )

	if UI:IsShipEvolving( defName ) then
		return false
	end

	-- уже был куплен

	if self:GetShipItemByDef( defName, true ) ~= nil then
		return false
	end

	-- хотя бы один из кораблей, от которых зависит данный, должен был быть куплен и прокачан до определенного уровня

	local treeDef = _G.VesselTree and _G.VesselTree[ defName ]
	if not treeDef then
		return false
	end

	if not treeDef.depends_on or not next( treeDef.depends_on ) then
		return false
	end

	for dependShipIdx, dependShipDefName in pairs( treeDef.depends_on ) do

		local dependShipItem = UI:GetShipItemByDef( dependShipDefName, true )
		if dependShipItem then

			local dependLevel = UI:GetShipDependLevel( defName, dependShipDefName )
			if dependLevel ~= -1 then

				if UI:GetShipLevel( dependShipItem ) >= dependLevel then
					return false
				end

			else
				return false
			end

		end

	end

	return true

end


-- если предположить, что парент с указанным именем куплен и имеет указанный уровень
function UI:IsShipLockedByDependancyConditional( defName, parentShipDefName, parentShipLevel )

	if type( defName ) ~= "string" then
		sys.log( "UI:IsShipLockedByDependancyConditional()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	if type( parentShipDefName ) ~= "string" then
		sys.log( "UI:IsShipLockedByDependancyConditional()[ERROR]: invalid type of the 2-nd parameter (\"parentShipDefName\"); \"string\" expected, got \"%s\"", type( parentShipDefName ) )
		return false
	end

	if type( parentShipLevel ) ~= "number" then
		sys.log( "UI:IsShipLockedByDependancyConditional()[ERROR]: invalid type of the 3-rd parameter (\"parentShipLevel\"); \"number\" expected, got \"%s\"", type( parentShipLevel ) )
		return false
	end

	-- уже был куплен

	if self:GetShipItemByDef( defName, true ) ~= nil then
		return false
	end

	-- хотя бы один из кораблей, от которых зависит данный, должен был быть куплен и прокачан до определенного уровня

	local treeDef = _G.VesselTree and _G.VesselTree[ defName ]
	if not treeDef then
		return false
	end

	if not treeDef.depends_on or not next( treeDef.depends_on ) then
		return false
	end

	for dependShipIdx, dependShipDefName in pairs( treeDef.depends_on ) do

    	local dependLevel = UI:GetShipDependLevel( defName, dependShipDefName )
		if dependLevel ~= -1 then

			if dependShipDefName == parentShipDefName then

				if parentShipLevel >= dependLevel then
    				return false
				end

			else

        		local dependShipItem = UI:GetShipItemByDef( dependShipDefName, true )
        		if dependShipItem then

    				if UI:GetShipLevel( dependShipItem ) >= dependLevel then
    					return false
    				end
    			end

			end

		else
			-- ошибка в формате данных?
			return false
		end
	end

	return true

end


--
function UI:GetShipDependLevel( defName, defNameDependOn )

	local dependLevel = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipDependLevel()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return dependLevel
	end

	if type( defNameDependOn ) ~= "string" then
		sys.log( "UI:GetShipDependLevel()[ERROR]: invalid type of the 2-nd parameter (\"defNameDependOn\"); \"string\" expected, got \"%s\"", type( defNameDependOn ) )
		return dependLevel
	end

	local treeDef = _G.VesselTree and _G.VesselTree[ defName ]
	if treeDef == nil then
		return dependLevel
	end

	if type( treeDef ) ~= "table" then
		sys.log( "UI:GetShipDependLevel()[ERROR]: invalid type of \"_G.VesselTree[%s]\"; \"table\" or \"nil\" expected, got \"%s\"", defName, type( treeDef ) )
		return dependLevel
	end

	if treeDef.depends_on == nil then
		return dependLevel
	end

	if type( treeDef.depends_on ) ~= "table" then
		sys.log( "UI:GetShipDependLevel()[ERROR]: invalid type of \"_G.VesselTree[%s].depends_on\"; \"table\" or \"nil\" expected, got \"%s\"", defName, type( treeDef.depends_on ) )
		return dependLevel
	end

	local linkIdx = -1

	for idx, dfName in pairs( treeDef.depends_on ) do
		if dfName == defNameDependOn then
			linkIdx = idx
			break
		end
	end

	if linkIdx == -1 then
		return dependLevel
	end

	if type( treeDef.depends_on_lvl ) ~= "table" then
		sys.log( "UI:GetShipDependLevel()[ERROR]: invalid type of \"_G.VesselTree[%s].depends_on_lvl\"; \"table\" expected, got \"%s\"", defName, type( treeDef.depends_on_lvl ) )
		return dependLevel
	end

	local level = treeDef.depends_on_lvl[ linkIdx ]
	if type( level ) ~= "number" then
		sys.log( "UI:GetShipDependLevel()[ERROR]: invalid type of \"_G.VesselTree[%s].depends_on_lvl[%d]\"; \"number\" expected, got \"%s\"", defName, linkIdx, type( level ) )
		return dependLevel
	end

	dependLevel = level
	return dependLevel

end


--
function UI:IsShipDependFromShip( childShipDefName, parentShipDefName )

	return UI:GetShipDependLevel( childShipDefName, parentShipDefName ) ~= -1

end


-- возвращает список кораблей, от которых зависит данный
function UI:GetShipsTheShipDependOn( childShipDefName )

	local parentShips = {}

	if type( childShipDefName ) ~= "string" then
		sys.log( "UI:GetShipsTheShipDependOn()[ERROR]: invalid type of the 1-st parameter (\"childShipDefName\"); \"string\" expected, got \"%s\"", type( childShipDefName ) )
		return parentShips
	end

	if type( _G.VesselTree ) ~= "table" then
		sys.log( "UI:GetShipsTheShipDependOn()[ERROR]: invalid type of \"_G.VesselTree\"; \"table\" expected, got \"%s\"", type( _G.VesselTree ) )
		return parentShips
	end

	local childShipTreeInfo = _G.VesselTree[ childShipDefName ]

	if type( childShipTreeInfo ) ~= "table" then
		sys.log( "UI:GetShipsTheShipDependOn()[ERROR]: invalid type of \"_G.VesselTree[\"%s\"]\"; \"table\" expected, got \"%s\"", childShipDefName, type( childShipTreeInfo ) )
		return parentShips
	end

	if childShipTreeInfo.depends_on == nil then
		return parentShips
	end

	if type( childShipTreeInfo.depends_on ) ~= "table" then
		sys.log( "UI:GetShipsTheShipDependOn()[ERROR]: invalid type of \"_G.VesselTree[\"%s\"].depends_on\"; \"table\" or \"nil\" expected, got \"%s\"", childShipDefName, type( childShipTreeInfo.depends_on ) )
		return parentShips
	end

	for parentShipIdx, parentShipDefName in pairs( childShipTreeInfo.depends_on ) do

		if type( parentShipDefName ) ~= "string" then
			sys.log( "UI:GetShipsTheShipDependOn()[ERROR]: invalid type of \"_G.VesselTree[\"%s\"].depends_on[%s]\"; \"string\" expected, got \"%s\"", childShipDefName, tostring( parentShipIdx ), type( parentShipDefName ) )
			return parentShips
		end

	end

	parentShips = childShipTreeInfo.depends_on

	return parentShips

end


-- апгрейд на момент вызова функции может быть как уже свершившимся, так и нет

function UI:GetUnlockedShipsOnShipLevelUp( shipDefName, shipLevel )

	local unlockedShips = {}

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetUnlockedShipsOnShipLevelUp()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return unlockedShips
	end

	if type( shipLevel ) ~= "number" then
		sys.log( "UI:GetUnlockedShipsOnShipLevelUp()[ERROR]: invalid type of the 2-nd parameter (\"shipLevel\"); \"number\" expected, got \"%s\"", type( shipLevel ) )
		return unlockedShips
	end

	if not _G.VesselTree then
		return unlockedShips
	end

	for treeShipDefName, treeInfo in pairs( _G.VesselTree ) do

		local dependLevel = UI:GetShipDependLevel( treeShipDefName, shipDefName )
		if dependLevel ~= -1 then

			local bWasLocked	= UI:IsShipLockedByDependancyConditional( treeShipDefName, shipDefName, shipLevel - 1 )
			local bIsLocked		= UI:IsShipLockedByDependancyConditional( treeShipDefName, shipDefName, shipLevel )

			if bWasLocked and not bIsLocked then
				table.insert( unlockedShips, treeShipDefName )
			end

		end

	end

	return unlockedShips

end


--
function UI:IsUpgradeUnlockNextShip( shipDefName, curLevel ) -- return {shipDef, shipDef, shipDef}

	local unlockTable = {}

	for k, v in pairs( _G.VesselTree ) do
		if UI:IsShipLockedByDependancy( k ) then
			if v.depends_on_lvl then
				if v.depends_on then
					for i = 1, #v.depends_on do
						if v.depends_on[ i ] == shipDefName then
							if v.depends_on_lvl[ i ] and v.depends_on_lvl[ i ] == curLevel + 1 then
								table.insert( unlockTable, k )
							end
						end
					end
				end
			end
		end
	end

	return unlockTable

end


