function UI:OnItemRankModeOptionChanged()

	local function l_fnRecurse( wnd )

		if UI:IsWndKindOf( wnd, "ItemIcoWnd" ) then
			wnd:OnItemRankModeOptionChanged()
		end

    	local child = wnd:GetFirstChild()
    	while child do

			l_fnRecurse( child )

    		child = child:GetNextSibling()

    	end

	end

	l_fnRecurse( UI.Root )

end


