--
function UI:GetShipSpawnData( vid, bWithBuffs, activeNodesMask, bWithTalents, bWithAutogens )

	-- для автогена из инвентаря имена дефов есть только в ангаре, во время геймплея дефы автогена есть только для модулей, которые стоят на кораблях игроков,
	-- поэтому эту функцию нельзя вызывать во время геймплея
	if _G.GetCurrentGameMode() ~= ai.Gameplay.NONE then
		sys.log( "UI:GetShipSpawnData()[ERROR]: call in gameplay; autogen will not handle correctly" )
	end

	if bWithBuffs == nil then
		bWithBuffs = true
	end

	if bWithTalents == nil then
		bWithTalents = false
	end

	if bWithAutogens == nil then
		bWithAutogens = true
	end

	local spawnData = {}

	if type( vid ) ~= "userdata" or vid.l == nil or vid.h == nil then
		sys.log( "UI:GetShipSpawnData()[ERROR]: invalid type of the 1-st param (\"vid\"); \"u64\" expected; got \"%s\"", type( vid ) )
		return spawnData
	end

	local shipItem = UI:GetShipItem( vid, true )
	if not shipItem then
		sys.log( "UI:GetShipSpawnData()[ERROR]: cannot find ship item with vid %s", _G.U64ToStr( vid ) )
		return spawnData
	end

	-- деф

	local defName = shipItem.defName

	-- если выбраны ноды, то коррекция дефа, иначе параметры потом будут получены неправильне
	if UI:IsShipEvolving( shipItem.defName ) and activeNodesMask then
		defName = UI:CalcEvolvingShipDefNameFromNodesMask( shipItem.defName, activeNodesMask )
	end

	spawnData.baseDef = defName


	-- слоты

	spawnData.enabledSlots = nil

	if UI:IsShipCraftable( shipItem.defName ) then
		spawnData.enabledSlots = shipItem.enabledModuleSlots

	elseif UI:IsShipEvolving( shipItem.defName ) then
		spawnData.enabledSlots = shipItem.evolvedModuleSlots
	end

	if bWithBuffs then

		-- модули

		local equipmentDefs = {}
		for slotId, iid in pairs( shipItem.equipModules ) do

			if iid ~= UI.INVALID_U64_ID then

				local bFound = false

				local item = UI:GetInventoryItem( iid )
				if item then

					bFound = true
					equipmentDefs[ slotId ] = item.defName

				else

					local autogenItem = UI:GetAutogenInventoryItem( iid )
					if autogenItem then

						bFound = true

						if bWithAutogens then

							-- в cpp при обоработке spawnData не обрабатывается отдельно автоген; если у автогена есть defТame, то он обработается как и обычные модули
							if autogenItem.defName and defName ~= "" then
								equipmentDefs[ slotId ] = autogenItem.defName
							else
								-- для автогена из инвентаря имена дефов есть только в ангаре, во время геймплея дефы автогена есть только для модулей, которые стоят на кораблях игроков,
								-- поэтому эту функцию нельзя вызывать во время геймплея
								sys.log( "UI:GetShipSpawnData()[ERROR]: no def for autogen item %s", _G.U64ToStr( iid ) )
							end

						end

					end

				end

				if not bFound then
					sys.log( "UI:GetShipSpawnData()[ERROR]: cannot find item for iid %s", _G.U64ToStr( iid ) )
				end

			end

		end

		for slotId = 0, ai.SpaceShipModuleSlot.NUM - 1 do
			spawnData[ "module"..slotId ] = equipmentDefs[ slotId ]
		end

		-- аммуниция

		for ammoName, ammoSlotId in pairs( ai.MunitionBayType ) do
			if ammoSlotId ~= ai.MunitionBayType.MBT_NUM then

			local ammoInfo = shipItem.equipAmmo[ ammoSlotId ]
				if ammoInfo and ammoInfo.def ~= "" and ammoInfo.amount > 0 then
					spawnData[ "munition"..ammoSlotId ] = ammoInfo.def
				end

			end
		end

		-- аккаунт-ауры

		spawnData.accountAuras = UI.serverData.accountAuras


		-- #0074768
		-- таланты

		if bWithTalents then

			local talents = {}

			local battleSlotIdx = UI:GetShipBattleSlot( shipItem )
			if battleSlotIdx ~= -1 then

				local talentSetId = UI.serverData.talentSetBinds[ battleSlotIdx ] or -1

				if talentSetId ~= -1 then
					talents = UI.serverData.talents[ talentSetId ] or {}
				end

			end

			spawnData.talents = talents

		end

	end

	-- опыт
	spawnData.level = shipItem.level or 1

	-- если выбраны ноды, то коррекция дефа, иначе параметры потом будут получены неправильне
	if UI:IsShipEvolving( defName ) and activeNodesMask then
		local rank = UI:GetShipRank( defName )
		spawnData.level = UI:GetShipMaxSynergyLevelForRank( rank )
	end

	-- украшения
	local customizations = _G.GameStore_GetVesselCustomElements( shipItem.vid )
	for customIdx, customData in pairs( customizations ) do

		local customFieldName = string.format( "customElementName%d", customData.slot )
		spawnData[ customFieldName ] = customData.defName

	end

	-- скрафченные бонусы для уровней синергии (только для крафтовых кораблей)

	if UI:IsShipCraftable( shipItem.defName ) then

		local bonuses = {}

		local maxLevel = UI:GetShipMaxLevel( shipItem.defName )
		for level = 1, maxLevel do

			local bonusName = UI:GetShipCraftedBonus( shipItem, level )
			table.insert( bonuses, bonusName )

		end

		spawnData.specialGrades = bonuses

	end

	-- для "зеленых" кораблей - базовый деф и активированные ноды

	if UI:IsShipEvolving( shipItem.defName ) then

		spawnData.sourceDef = UI:GetEvolvingShipBaseDef( shipItem.defName )

		if activeNodesMask then
			spawnData.activeMask = activeNodesMask
		else
			spawnData.activeMask = UI:GetEvolvingShipActiveNodesMask( vid )
		end

	end


	return spawnData

end


--
function UI:GetShipDefaultSpawnData( defName, bPremiumShipMaxed, bWithBuffs )

	local spawnData	= {}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipDefaultSpawnData()[ERROR]: invalid type of the 1-st param (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return spawnData
	end

	if not UI:GetDef( defName ) then
		sys.log( "UI:GetShipDefaultSpawnData()[ERROR]: wrong defName \"%s\"", defName )
		return spawnData
	end

	if bPremiumShipMaxed ~= nil then
		if type( bPremiumShipMaxed ) ~= "boolean" then
			sys.log( "UI:GetShipDefaultSpawnData()[ERROR]: invalid type of the 2-nd param (\"bPremiumShipMaxed\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bPremiumShipMaxed ) )
			bPremiumShipMaxed = nil
		end
	end

	if bPremiumShipMaxed == nil then
		bPremiumShipMaxed = true
	end

	if bWithBuffs ~= nil then
		if type( bWithBuffs ) ~= "boolean" then
			sys.log( "UI:GetShipDefaultSpawnData()[ERROR]: invalid type of the 3-кd param (\"bWithBuffs\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bWithBuffs ) )
			bWithBuffs = nil
		end
	end

	if bWithBuffs == nil then
		bWithBuffs = true
	end

	-- деф

	spawnData.baseDef = defName

	-- опыт

	spawnData.level = UI:GetShipDefaultLevel( defName )

	if UI:IsShipPremium( defName ) and not bPremiumShipMaxed then
		spawnData.level = 1
	end


	if bWithBuffs then

		-- модули (с которыми корабль идет в комплекте при покупке)

		local slotsMask = u64( 0 )

		if UI:IsShipCraftable( defName ) then
			slotsMask = UI:GetCraftableShipDefaultSlotsMask( defName )

		elseif UI:IsShipEvolving( defName ) then
			slotsMask = UI:GetEvolvingShipDefaultSlotsMask( defName )

		else
			slotsMask = UI:GetShipAllPossibleSlotsMask( defName )
		end

		for slotName, slotId in pairs( ai.SpaceShipModuleSlot ) do

			if slotId ~= ai.SpaceShipModuleSlot.NUM then

				local moduleDefName = ""

				if UI:BitTstU64( slotsMask, slotId ) then
					moduleDefName = UI:GetShipInitialModule( defName, slotId )
				end

				if moduleDefName ~= "" then
					spawnData[ "module"..slotId ] = moduleDefName
				end

			end

		end

		-- аммуниция (с которой корабль идет в комплекте при покупке)

		for slotName, slotId in pairs( ai.MunitionBayType ) do

			if slotId ~= ai.MunitionBayType.MBT_NUM then

				local ammoDefName = UI:GetShipInitialAmmo( defName, slotId )

				if ammoDefName ~= "" then
					spawnData[ "munition"..slotId ] = ammoDefName
				end

			end

		end

		-- аккаунт-ауры

		spawnData.accountAuras = UI.serverData.accountAuras

	end

	-- для "зеленых" кораблей - базовый деф и активированные ноды

	if UI:IsShipEvolving( defName ) then
		spawnData.sourceDef		= UI:GetEvolvingShipBaseDef( defName )
		spawnData.activeMask	= u64( 0 )
	end

	return spawnData

end


-- для игры некупленным кораблем; кораблю даются максимальная синергия и модули
function UI:GetShipTestDriveSpawnData( defName )

	local spawnData	= {}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipTestDriveSpawnData()[ERROR]: invalid type of the 1-st param (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return spawnData
	end

	if not UI:GetDef( defName ) then
		sys.log( "UI:GetShipTestDriveSpawnData()[ERROR]: wrong defName \"%s\"", defName )
		return spawnData
	end

	if UI:IsShipCraftable( defName ) and not UI:IsShipHasTestdrivePreset( defName ) then
		sys.log( "UI:GetShipTestDriveSpawnData()[ERROR]: craftable ships not supported with testdrive_preset" )
		return spawnData
	end

	if UI:IsShipEvolving( defName ) and not UI:IsShipHasTestdrivePreset( defName ) then
		sys.log( "UI:GetShipTestDriveSpawnData()[ERROR]: evolving ships not supported with testdrive_preset" )
		return spawnData
	end

	spawnData = UI:GetShipDefaultSpawnData( defName, true, true )
	if not next( spawnData ) then
		sys.log( "UI:GetShipTestDriveSpawnData()[ERROR]: cannot make ship spawn data" )
		return spawnData
	end


	-- опыт (синергия) - максимальный

	spawnData.level = UI:GetShipMaxLevel( defName )

	-- модули - максимально прокачанные версии тех, которые идут дефолтом при покупке

	local slotsMask = UI:GetShipAllPossibleSlotsMask( defName )
	for slotName, slotId in pairs( ai.SpaceShipModuleSlot ) do

		if slotId ~= ai.SpaceShipModuleSlot.NUM and UI:BitTstU64( slotsMask, slotId ) then

			local moduleDefName = spawnData[ "module"..slotId ] or ""
			if moduleDefName ~= "" then

				local moduleMaxLevel = UI:GetItemUpgradeMaxLevel( moduleDefName )
				if moduleMaxLevel ~= -1 then

					local moduleMaxDefName = UI:GetItemUpgradeDefForLevel( moduleDefName, moduleMaxLevel )
					if moduleMaxDefName ~= "" then
						spawnData[ "module"..slotId ] = moduleMaxDefName
					end

				end

			end

		end

	end

	return spawnData

end


