--
function UI:GetItemRole( defName )

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemRole()[ERROR]: cannot dinf _G.Def[%s]", tostring( defName ) )
		return -1
	end

	local role = -1

	if _G.IsClassKindOf( def.class, "SpaceShip" ) then
		role = def.role
		if not role then
			sys.log( "UI:GetItemRole()[ERROR]: cannot find _G.Def[%s].role", defName )
		end
	else
		role = def.required_role
	end

	return role or -1

end


