--
function UI:GetAllEquippedShips()
	local ships = {}
	local battleSlots = UI.serverData.battleSlots
	for i = 1, #battleSlots do
		if battleSlots[ i ] ~= UI.INVALID_U64_ID then
			for j = 1, #UI.serverData.ships do
				if battleSlots[ i ] == UI.serverData.ships[ j ].vid then
					table.insert( ships, UI.serverData.ships[ j ] )
				end
			end
		end
	end
	return ships
end


--
function UI:ShowPopUpMenuForShip( defName, hOwnerWnd )

	if type( defName ) ~= "string" then
		sys.log( "UI:ShowPopUpMenuForShip()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	if type( hOwnerWnd ) ~= "number" then
		sys.log( "UI:ShowPopUpMenuForShip()[ERROR]: invalid type of the 2-nd parameter (\"hOwnerWnd\"); \"number\" expected, got \"%s\"", type( hOwnerWnd ) )
		return false
	end

	local wasBaughtShipItem = UI:GetShipItemByDef( defName, true )	-- корабль, который может быть или сейчас куплен, или ранее когда-либо покупался, а потом был продан

	local shipItem = wasBaughtShipItem	-- корабль, который куплен прямо сейчас
	if shipItem and shipItem.conserved then
		shipItem = nil
	end


	local questId			= -1
	local bLockedOnQuest	= false

	local bInMatchmaking = shipItem ~= nil and UI:IsShipInMatchmaking( shipItem )
	local bAdvert, bAdvertByFlag = UI:IsShipAdvert( defName )
	local bDisabledByTime = UI:IsShipDisabledByTime( defName )	-- SC-111975 некоторые корабли доступны только в определенные дни года

	if shipItem then

		questId = UI:GetShipQuestForShip( shipItem )

		if questId ~= -1 then
			bLockedOnQuest = true

		else

			if UI.ShipsTreeWnd:IsOnScreen() then

				local editedQuestId = UI.ShipsTreeWnd:GetShipQuest()
				if editedQuestId ~= -1 and not UI:IsShipQuestTaken( editedQuestId ) then

					if UI.ShipsTreeWnd:HasQuestShip( shipItem.vid ) then
						questId = editedQuestId
					end

				end

			end

		end

	end


	local datas = {}

	-- апгрейдить

	if shipItem and UI:CanShipLevelUp( shipItem.vid ) then

		if not UI:IsShipOnShipQuest( shipItem ) and not UI:IsShipInBattle( shipItem ) then

        	local upgradeData =
        	{
        		slotType	= UI.popUpMenuSlotTypes.SHIP_UPGRADE,
        		vid			= shipItem.vid,
        		text		= UI:GetStringByName( "popUpMenu_upgradeShip" ),
        	}

    		table.insert( datas, upgradeData )

		end

	end


	-- боевые слоты (для купленного корабля)

	if shipItem and questId == -1 and UI.HangarWnd:GetPrepareState() == UI.HangarWnd.prepareStates.NONE then

    	local battleSlotsInfo = UI:GetBattleSlotInfoForShip( defName )
    	if next( battleSlotsInfo ) then

        	for idx = 1, #battleSlotsInfo do

        		local slotInfo = battleSlotsInfo[ idx ]

        		if slotInfo.bEquipped then

					local data = {}
					data.slotType	= UI.popUpMenuSlotTypes.BATTLE_SLOT
					data.slotIdx	= slotInfo.slotIdx
        			data.text		= UI:GetStringByName( "ships_removeFromBattleSlot_popUpMenu" )
        			data.vid		= UI.INVALID_U64_ID

					table.insert( datas, data )

        		else

					if not bDisabledByTime then

						local data = {}
						data.slotType	= UI.popUpMenuSlotTypes.BATTLE_SLOT
						data.slotIdx	= slotInfo.slotIdx
						data.text		= string.format( UI:GetStringByName( "ships_setToBattleSlot_popUpMenu" ), slotInfo.slotIdx )
						data.vid		= shipItem.vid

						table.insert( datas, data )

					end

        		end

        	end

    	end

	end


	-- убрать из квестового слота

	if shipItem and questId ~= -1 and not bLockedOnQuest then

    	local removeFromQuestSlotData =
    	{
    		slotType	= UI.popUpMenuSlotTypes.SHIP_REMOVE_FROM_QUEST_SLOT,
    		vid			= shipItem.vid,
    		text		= UI:GetStringByName( "popUpMenu_removeShipFromQuestSlot" ),
    	}

		table.insert( datas, removeFromQuestSlotData )

	end


	-- перейти к квесту

	if bLockedOnQuest then

    	local goToQuestData =
    	{
    		slotType	= UI.popUpMenuSlotTypes.GO_TO_SHIP_QUEST,
    		questId		= questId,
    		text		= UI:GetStringByName( "popUpMenu_goToShipQuest" ),
    	}

		table.insert( datas, goToQuestData )

	end


	-- преввью

	if wasBaughtShipItem or not bAdvert or bAdvertByFlag then

    	local previewData =
    	{
    		slotType	= UI.popUpMenuSlotTypes.SHIP_PREVIEW,
    		defName		= defName,
    		text		= UI:GetStringByName( "popUpMenu_previewShip" ),
    	}

    	table.insert( datas, previewData )

	end


	-- снять всё установленное оборудование (для купленного корабля)

	if shipItem and not bLockedOnQuest and not UI:IsShipInBattle( shipItem ) then

		local bHasEquipment = false

		for slotId, iid in pairs( shipItem.equipModules ) do
			if iid ~= UI.INVALID_U64_ID then
				bHasEquipment = true
				break
			end
		end

		if not bHasEquipment then
    		for slotId, ammoInfo in pairs( shipItem.equipAmmo ) do
        		if ammoInfo.def ~= "" then
					bHasEquipment = true
					break
				end
    		end
		end

		if bHasEquipment then

        	local stripData =
        	{
        		slotType	= UI.popUpMenuSlotTypes.SHIP_STRIP_EQUIPMENT,
        		text		= UI:GetStringByName( "popUpMenu_stripShipEquipment" ),
        		vid			= shipItem.vid,
        	}

        	table.insert( datas, stripData )

		end

	end


	-- апгрейдить модули

	if shipItem and not bLockedOnQuest and not UI:IsShipInBattle( shipItem ) then

		local itemsForUpgrade, totalPrice, bGivingExp = UI:GetModulesForUpgrade( shipItem )

		if next( itemsForUpgrade ) then

			local strIco = string.format( "$texture [texName %s]$", bGivingExp and "questIco_w_1"--[[желтая]] or "questIco_auto_w_1"--[[синяя]] )

			local upgradeData =
			{
				slotType		= UI.popUpMenuSlotTypes.SHIP_UPGRADE_ITEMS,
				text			= strIco .. UI:GetStringByName( "popUpMenu_shipUpgradeItems" ),

				vid				= shipItem.vid,
				itemsForUpgrade	= itemsForUpgrade,
				totalPrice		= totalPrice,
				bGivingExp		= bGivingExp,
			}

			table.insert( datas, upgradeData )

		end

	end


	-- пересоздать крафтовый корабль

	if shipItem and UI:IsShipCraftable( defName ) and not bLockedOnQuest and not bDisabledByTime then

    	local recraftData =
    	{
    		slotType	= UI.popUpMenuSlotTypes.SHIP_RECRAFT,
    		vid			= shipItem.vid,
    		text		= UI:GetStringByName( "popUpMenu_recraftShip" ),
    	}

    	table.insert( datas, recraftData )

	end


	-- продать

	if shipItem and not bLockedOnQuest and not bInMatchmaking and self:CanSellShip( defName ) then

    	local sellData =
    	{
    		slotType	= UI.popUpMenuSlotTypes.SHIP_SELL,
    		vid			= shipItem.vid,
    		text		= --[[UI:IsShipCraftable( defName ) and UI:GetStringByName( "popUpMenu_sellCraftedShip" ) or]] UI:GetStringByName( "popUpMenu_sellShip" ),	-- #0060122: убрали пункт "Разобрать" для карфтовых кораблей
    	}

    	table.insert( datas, sellData )

	end


	-- открыть экипировку

	if shipItem then

		local menuData =
		{
    		slotType	= UI.popUpMenuSlotTypes.SHOW_SHIP_EQUIPMENT,
    		vid			= shipItem.vid,
    		text		= UI:GetStringByName( "popUpMenu_showEquipment" ),
		}

    	table.insert( datas, menuData )

	end


	-- тест-драйв

	if not shipItem and not bAdvert and ( UI:IsShipHasTestdrivePreset( defName ) or ( not UI:IsShipEvolving( defName ) and not UI:IsShipCraftable( defName ) ) ) then

		local previewData =
		{
			slotType	= UI.popUpMenuSlotTypes.SHIP_TEST_DRIVE,
			defName		= defName,
			text		= UI:GetStringByName( "popUpMenu_testDrive" ),
		}

		table.insert( datas, previewData )

	end



	if next( datas ) then

		UI.PopUpMenuWnd:Setup( hOwnerWnd, UI.popUpMenuTypes.SHIP, UI:GetEntityLocalizedNameByDef( defName, true, false ) )

		for idx = 1, #datas do
        	UI.PopUpMenuWnd:AddRecord( datas[ idx ] )
		end

		return true

	end

	return false

end


--
function UI:ShowPopUpMenuForShipInBundle( defName, hOwnerWnd )

	if type( defName ) ~= "string" then
		sys.log( "UI:ShowPopUpMenuForShipInBundle()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
