end



--
function UI:GetBattleSlotInfoForShip( defName )

	local slotsInfo = {}

	local shipItem = UI:GetShipItemByDef( defName, false )
	local vid = shipItem and shipItem.vid or UI.INVALID_U64_ID

	for slotIdx = 1, UI.serverData.battleSlotsCount do

		local slotMask = UI.serverData.battleSlotTypes[ slotIdx - 1 ] or 0
		local shipType = UI:GetItemShipType( defName )

		if shipType and bit.band( slotMask, shipType ) ~= 0 then
			local slotInfo = { slotIdx = slotIdx, bEquipped = vid ~= UI.INVALID_U64_ID and UI.serverData.battleSlots[ slotIdx ] == vid }
			table.insert( slotsInfo, slotInfo )
		end

	end

	return slotsInfo

end


--
function UI:UpdateServerData_OnMailGet( result, requestId )

	if result ~= _G.MasterServer.MailOpResult.MOR_OK then
		return
	end

	self.serverData.mail = {}

	local data = _G.MasterServer_MailGet()

	if data.letters then
		for idx, letter in pairs( data.letters ) do
        	-- торговые письма в cpp хранятся также и у отправителя, но в ui они не показываются
        	if letter.sender ~= UI:GetLocalPlayerUid() then
        		table.insert( self.serverData.mail, letter )
        	end
		end
	end

	local function fnSort( letter1, letter2 )

		local time1 = letter1.sentAt or UI.INVALID_U64_ID
		local time2 = letter2.sentAt or UI.INVALID_U64_ID

		return UI:IsU64Greater( time1, time2 )

	end

	table.sort( self.serverData.mail, fnSort )

end


--
function UI:UpdateServerData_OnMailDeliver( result, requestId, param1, param2, u64Param )

	if result ~= _G.MasterServer.MailOpResult.MOR_OK then
		return
	end

	self:DeleteLetterInternal( u64Param )

end


--
function UI:UpdateServerData_OnMailRemove( result, requestId, unused, unused, mailId )

	if result ~= _G.MasterServer.MailOpResult.MOR_OK then
		return
	end

	self:DeleteLetterInternal( mailId )

end


--
function UI:UpdateServerData_OnMailExpired( result, requestId, unused, unused, mailId )

	if result ~= _G.MasterServer.MailOpResult.MOR_OK then
		return
	end

	self:DeleteLetterInternal( mailId )

end


--
function UI:DeleteLetterInternal( mailId )

	for letterIdx, letter in pairs( self.serverData.mail ) do
		if letter.mailId == mailId then
			table.remove( self.serverData.mail, letterIdx )
			break
		end
	end

end


--
function UI:AddLetterInternal( letter )

	if type( letter ) ~= "table" then
		sys.log( "UI:AddLetterInternal()[ERROR]: invalid type of the 1-st param (\"letter\"); \"table\" expected, got \"%s\"", type( letter ) )
		return
	end

	-- торговые письма в cpp хранятся также и у отправителя, но в ui они не показываются
	if letter.sender == UI:GetLocalPlayerUid() then
		return
	end

	local letterTime = letter.sentAt or UI.INVALID_U64_ID

	for idx = 1, #self.serverData.mail do

		local time = self.serverData.mail[ idx ].sentAt or UI.INVALID_U64_ID
		if UI:IsU64Greater( letterTime, time ) then
			table.insert( self.serverData.mail, idx, letter )
			return
		end

	end

	table.insert( self.serverData.mail, letter )

end


--
function UI:RewardReason2Str( rewardReason, bUpperCase )

	if bUpperCase == nil then
		bUpperCase = false
	end

	local strRewardReason = UI:Val2Key( ai.RewardReason, rewardReason )

	local strId = ""
	if bUpperCase then
		strId = string.format( "reward_%s", strRewardReason )
	else
		strId = string.format( "reward_%s_low", strRewardReason )
	end

	return UI:GetStringByName( strId )

end


