--
function UI:IsItemSale( item )

	local priceType, price, basePrice, altPriceType, altPrice, altBasePrice = UI:GetShopSmartBuyPriceAlt( item )

	local bSale = price < basePrice

	if altPriceType then
		if altPrice < altBasePrice then
			bSale = true
		end
	end

	return bSale

end


--
function UI:IsItemNew( item )

	if type( item ) ~= "table" then
		sys.log( "UI:IsItemNew()[ERROR]: invalid type of the 1-st parameter (\"item\"); \"table\" expected, got \"%s\"", type( item ) )
		return false
	end

	if type( item.flags ) ~= "number" then
		sys.log( "UI:IsItemNew()[ERROR]: invalid type of the field \"flags\"; \"number\" expected, got \"%s\"", type( item.flags ) )
		return false
	end

	return bit.band( item.flags, _G.GameStore.ItemFlags.IF_NEW ) == _G.GameStore.ItemFlags.IF_NEW

end


--
function UI:IsItemHot( item )

	if type( item ) ~= "table" then
		sys.log( "UI:IsItemHot()[ERROR]: invalid type of the 1-st parameter (\"item\"); \"table\" expected, got \"%s\"", type( item ) )
		return false
	end

	if type( item.flags ) ~= "number" then
		sys.log( "UI:IsItemHot()[ERROR]: invalid type of the field \"flags\"; \"number\" expected, got \"%s\"", type( item.flags ) )
		return false
	end

	return bit.band( item.flags, _G.GameStore.ItemFlags.IF_HOT ) == _G.GameStore.ItemFlags.IF_HOT

end


--
function UI:IsItemHiddenInShop( item )

	local bHidden = true

	if type( item ) ~= "table" then
		sys.log( "UI:IsItemHiddenInShop()[ERROR]: invalid type of the 1-st parameter (\"item\"); \"table\" expected, got \"%s\"", type( item ) )
		return bHidden
	end

	local def = UI:GetDef( item.defName )
	if not def then
		sys.log( "UI:IsItemHiddenInShop()[ERROR]: cannot find def \"%s\"", item.defName )
		return bHidden
	end

	if def.hiddenInShop ~= nil then
		if type( def.hiddenInShop ) == "boolean" then
			bHidden = def.hiddenInShop
		else
			sys.log( "UI:IsItemHiddenInShop()[ERROR]: invalid type of _G.Def[\"%s\"]; \"boolean\" or \"nil\" expected, got \"%s\"", item.defName, type( def.hiddenInShop ) )
		end

	else
		bHidden = false
	end

	if bHidden then

    	-- #0062440,комм.(0255236) - для бандлов дополнительно испльзуется флаг IS_SHOW
    	if UI:IsDefBundle( item.defName ) then

        	if type( item.flags ) == "number" then
        		if bit.band( item.flags, _G.GameStore.ItemFlags.IS_SHOW ) == _G.GameStore.ItemFlags.IS_SHOW then
					bHidden = false
				end
			else
        		sys.log( "UI:IsItemHiddenInShop()[ERROR]: invalid type of the field \"flags\"; \"number\" expected, got \"%s\"", type( item.flags ) )
        	end

    	end

	end

	return bHidden

end


--
function UI:IsItemAdvert( item )

	if type( item ) ~= "table" then
		sys.log( "UI:IsItemAdvert()[ERROR]: invalid type of the 1-st parameter (\"item\"); \"table\" expected, got \"%s\"", type( item ) )
		return false
	end

	if type( item.flags ) ~= "number" then
		sys.log( "UI:IsItemAdvert()[ERROR]: invalid type of the field \"flags\"; \"number\" expected, got \"%s\"", type( item.flags ) )
		return false
	end

	return bit.band( item.flags, _G.GameStore.ItemFlags.IS_ADVERT ) == _G.GameStore.ItemFlags.IS_ADVERT

end


