--
function UI:GetQuestCharacterRace( character )

	local race = -1

	if type( character ) ~= "string" then
		sys.log( "UI:GetQuestCharacterRace()[ERROR]: invalid type of the 1-st parameter (\"character\"); \"string\" expected, got \"%s\"", type( character ) )
		return race
	end

	if type( _G.quest_characters ) ~= "table" then
		sys.log( "UI:GetQuestCharacterRace()[ERROR]: invalid type of \"_G.quest_characters\"; \"table\" expected, got \"%s\"", type( _G.quest_characters ) )
		return race
	end

	local characterInfo = nil

	for idx, info in pairs( _G.quest_characters ) do

		if type( info ) == "table" then

			if info.name == character then
				characterInfo = info
				break
			end

		else
    		sys.log( "UI:GetQuestCharacterRace()[ERROR]: invalid type of \"_G.quest_characters[%d]\"; \"table\" expected, got \"%s\"", idx, type( info ) )
		end

	end

	if not characterInfo then
		sys.log( "UI:GetQuestCharacterRace()[ERROR]: cannot find info for character \"%s\"", character )
		return race
	end

	if characterInfo.race ~= nil then
    	if type( characterInfo.race ) == "number" then
    		race = characterInfo.race
    	else
    		sys.log( "UI:GetQuestCharacterRace()[ERROR]: invalid type of \"race\" field in \"_G.quest_characters\" for character \"%s\"; \"number\" or \"nil\" expected, got \"%s\"", character, type( characterInfo.race ) )
    	end
	end

	return race

end


