--
function UI:GetAllQuestCharacters()

	local characters = {}

	if type( _G.quest_characters ) ~= "table" then
		sys.log( "UI:GetAllQuestCharacters()[ERROR]: invalid type of \"_G.quest_characters\"; \"table\" expected, got \"%s\"", type( _G.quest_characters ) )
