    		end

		else
    		sys.log( "UI:GetAllQuestCharacters()[ERROR]: invalid type of \"_G.quest_characters[%d]\"; \"table\" expected, got \"%s\"", idx, type( info ) )
		end

	end

	return characters

end


--
function UI:GetQuestDifficulty( questId )

	local difficulty = nil

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestDifficulty()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return difficulty
	end

	local questInfo = self:GetQuestInfo( questId )

	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestCharacter()[ERROR]: cannot find questInfo for quest %s", tostring( questId ) )
		return difficulty
	end

	if questInfo.difficulty == nil then
		return difficulty
	end

	if type( questInfo.difficulty ) == "string" then

		difficulty = questInfo.difficulty

		if difficulty == "" then
			difficulty = nil
		end

	else
		sys.log( "UI:GetQuestDifficulty()[ERROR]: invalid type of the \"_G.Quests[%d].difficulty\"; \"string\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.difficulty ) )
	end

	return difficulty

end


