--
function UI:Quest2Str( questId, bWithDifficulty, bCanAbsent )

	local name = ""

	if type( questId ) ~= "number" then
		sys.log( "UI:Quest2Str()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return name
	end

	if bWithDifficulty ~= nil then
    	if type( bWithDifficulty ) ~= "boolean" then
    		sys.log( "UI:Quest2Str()[ERROR]: invalid type of the 2-nd parameter (\"bWithDifficulty\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bWithDifficulty ) )
			bWithDifficulty = nil
    	end
	end

	if bWithDifficulty == nil then
		bWithDifficulty = false
	end

	if bCanAbsent ~= nil then
    	if type( bCanAbsent ) ~= "boolean" then
    		sys.log( "UI:Quest2Str()[ERROR]: invalid type of the 3-st parameter (\"bCanAbsent\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bCanAbsent ) )
			bCanAbsent = nil
    	end
	end

	if bCanAbsent == nil then
		bCanAbsent = false
	end

	local questName = UI:Val2Key( _G.QuestId, questId )
	if questName == "" then
		sys.log( "UI:Quest2Str()[ERROR]: invalid qusetId: %d", questId )
		return name
	end

	if UI.showDefNames then
		return questName
	end

	local strId = string.format( "quest_%s_name", questName )
	name = UI:GetStringByName( strId, not bCanAbsent ) or ""

	if bWithDifficulty and name ~= "" then

		local difficulty = UI:GetQuestDifficulty( questId )
		if difficulty ~= nil then

			local strDifficulty = UI:QuestDifficulty2Str( difficulty )
			name = string.format( "%s %s", name, strDifficulty )

		end

	end

	return name

end


