function UI:GetQuestLoreDesc( questId, bCompleted, baseColor, bCanAbsent )

	local desc = ""

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestLoreDesc()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return desc
	end

	if type( bCompleted ) ~= "boolean" then
		sys.log( "UI:GetQuestLoreDesc()[ERROR]: invalid type of the 1-st parameter (\"bCompleted\"); \"boolean\" expected, got \"%s\"", type( bCompleted ) )
		return desc
	end

	if type( baseColor ) ~= "number" then
		sys.log( "UI:GetQuestLoreDesc()[ERROR]: invalid type of the 3-rd parameter (\"baseColor\"); \"number\" expected, got \"%s\"", type( baseColor ) )
		baseColor = UI.TEXT_BASE_COLOR
	end

	if bCanAbsent ~= nil then
		if type( bCanAbsent ) ~= "boolean" then
			sys.log( "UI:GetQuestLoreDesc()[ERROR]: invalid type of the 4-th parameter (\"bCanAbsent\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bCanAbsent ) )
			bCanAbsent = bCanAbsent
		end
	end

	if bCanAbsent == nil then
		bCanAbsent = false
	end

	local questName = UI:Val2Key( _G.QuestId, questId )
	if questName == "" then
		sys.log( "UI:GetQuestLoreDesc()[ERROR]: invalid qusetId: %d", questId )
		return desc
	end

	local strId = bCompleted and string.format( "quest_%s_text_complete", questName ) or string.format( "quest_%s_text_new", questName )
	desc = UI:GetStringByName( strId, not bCanAbsent )	or ""

	if desc ~= "" then
		desc = UI:SubstituteBaseColorPlaceholders( desc, baseColor )
	end

	return desc

end


--
function UI:GetQuestTaskDesc( questId, stage, bAllowLinks, baseColor )

	local desc = ""

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestTaskDesc()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return desc
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetQuestTaskDesc()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return desc
	end

	if type( baseColor ) ~= "number" then

		if baseColor ~= nil then
			sys.log( "UI:GetQuestTaskDesc()[ERROR]: invalid type of the 4-th parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
		end

		baseColor = UI.TEXT_BASE_COLOR

	end

	local questName = UI:Val2Key( _G.QuestId, questId )
	if questName == "" then
		sys.log( "UI:GetQuestTaskDesc()[ERROR]: invalid qusetId: %d", questId )
		return desc
	end

	local strBaseColor = UI:Color2Str( baseColor )
	local strSelColor = UI:Color2Str( UI.TEXT_SEL_COLOR )

	local numStages = UI:GetQuestNumStages( questId )

	local strPostfix = numStages > 1 and string.format( "_%d", stage ) or ""
	local strId = string.format( "quest_%s_task%s", questName, strPostfix )

	desc = UI:GetStringByName( strId )
	desc = UI:SubstituteLinks( desc )
	desc = UI:FillQuestDescWithParams( questId, stage, desc, bAllowLinks, baseColor )
	desc = string.format( "%s%s", strBaseColor, desc )

	return desc

end


--
function UI:GetQuestTaskDesc2( questId, baseColor, selColor, stage, bAllowLinks )

	local desc = ""

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestTaskDesc2()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return desc
	end

	local questName = UI:Val2Key( _G.QuestId, questId )
	if questName == "" then
		sys.log( "UI:GetQuestTaskDesc2()[ERROR]: invalid qusetId: %d", questId )
		return desc
	end

	if type( baseColor ) ~= "number" then

		if baseColor ~= nil then
			sys.log( "UI:GetQuestTaskDesc2()[ERROR]: invalid type of the 2-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
		end

		baseColor = UI.TEXT_BASE_COLOR

	end

	if type( selColor ) ~= "number" then

		if selColor ~= nil then
			sys.log( "UI:GetQuestTaskDesc2()[ERROR]: invalid type of the 3-rd parameter (\"selColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( selColor ) )
		end

		selColor = UI.TEXT_SEL_COLOR

	end

	if stage ~= nil then
    	if type( stage ) ~= "number" then
    		sys.log( "UI:GetQuestTaskDesc2()[ERROR]: invalid type of the 4-th parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
    		return desc
    	end
	else
		stage = -1
	end

	if stage == -1 then
		stage = UI:GetQuestStage( questId )
	end

	local strBaseColor	= UI:Color2Str( baseColor )
	local strSelColor	= UI:Color2Str( selColor )

	local strId = stage == 1 and string.format( "quest_%s_task_short", questName ) or string.format( "quest_%s_%d_task_short", questName, stage )
	desc = UI:GetStringByName( strId )

	local curVal = 0
	local maxVal = 0

	local event = UI:GetQuestEventForStage( questId, stage )

	if event == ai.GameEvent.REPEL_INVASION then

		if _G.CL_IsInvasionActive() then
			maxVal, curVal = _G.CL_GetInvasionInfo()
		else
			sys.log( "UI:GetQuestTaskDesc2()[ERROR]: invasion is not active; cannot show valid task for quest %d, stage %d", questId, stage )
		end

	else

		maxVal = self:GetQuestTaskMaxVal( questId, stage ) or 0

    	local bCompleted = false

    	if UI:IsQuestCompleted( questId ) then
    		bCompleted = true
    	else
    		if UI:IsQuestRecurrent( questId ) then
    			if not UI:IsQuestTaken( questId ) then
    				bCompleted = true
    			end
    		end
    	end

		if bCompleted and stage == UI:GetQuestNumStages( questId ) then
			curVal = maxVal
		else
			curVal = self:GetQuestTaskCurVal( questId ) or 0
		end

	end

	local strCurVal = string.format( "%s%s%s", strSelColor, UI:Num2StrSeparatedBy3( curVal ), strBaseColor )
	local strMaxVal = string.format( "%s%s%s", strSelColor, UI:Num2StrSeparatedBy3( maxVal ), strBaseColor )

	local tSubst =
	{
		current	= strCurVal,
		target	= strMaxVal,
	}

	desc = string.gsub( desc, "%$(.-)%$", tSubst )
	desc = UI:FillQuestDescWithParams( questId, stage, desc, bAllowLinks, baseColor )
	desc = string.format( "%s%s", strBaseColor, desc )

	return desc

end


-- поддерживает плейсхолдеры:
-- $need$ - подставляется "required_value";
-- $param_%d_%d$ - подставляется из "restrictions"; первое %d - индекс параметра в таблице "params", второе %d - индекс значения в таблице num_value или str_value
-- $battlePoint$ - подставляется из поля battlePoint
-- $shipRankMin$
-- $shipRankMax$

function UI:FillQuestDescWithParams( questId, stage, text, bAllowLinks, baseColor )

	local textWithParams = ""

	if type( questId ) ~= "number" then
		sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return textWithParams
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return textWithParams
	end

	if type( text ) ~= "string" then
		sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of the 3-rd parameter (\"text\"); \"string\" expected, got \"%s\"", type( text ) )
		return textWithParams
	end

	if type( bAllowLinks ) ~= "boolean" then
		sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of the 4-th parameter (\"bAllowLinks\"); \"boolean\" expected, got \"%s\"", type( bAllowLinks ) )
		bAllowLinks = false
	end

	if type( baseColor ) ~= "number" then

		if baseColor ~= nil then
			sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of the 5-th parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
		end

		baseColor = UI.TEXT_BASE_COLOR

	end

	textWithParams = text

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:FillQuestDescWithParams()[ERROR]: cannot find questInfo for quest %s", tostring( questId ) )
		return textWithParams
	end

	local params = nil

	local stageInfo = UI:GetQuestStageInfo( questId, stage )
	if stageInfo then

    	if stageInfo.restrictions ~= nil then

			if type( stageInfo.restrictions ) == "table" then
				params = stageInfo.restrictions
			else
        		sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of the \"_G.Quests[%d].stages[%d].restrictions\"; \"table\" or \"nil\" expected, got \"%s\"", questId, stage, type( stageInfo.restrictions ) )
			end

    	end

	else
		sys.log( "UI:FillQuestDescWithParams()[ERROR]: cannot find stage info for quest %d stage %d", questId, stage )
	end

	local strBaseColor = UI:Color2Str( baseColor )
	local strSelColor = UI:Color2Str( UI.TEXT_SEL_COLOR )


	local function fnSubst( capture )

		local strSubst = nil

		if capture == "need" then

			local maxVal = nil

    		local event = UI:GetQuestEventForStage( questId, stage )

    		if event == ai.GameEvent.REPEL_INVASION then

    			if _G.CL_IsInvasionActive() then
					local curVal = 0
    				maxVal, curVal = _G.CL_GetInvasionInfo()
    			else
    				sys.log( "UI:FillQuestDescWithParams()[ERROR]: invasion is not active; cannot show valid task for quest %d, stage %d", questId, stage )
    			end

			else
				maxVal = self:GetQuestTaskMaxVal( questId, stage )
			end

			if maxVal then
				strSubst = string.format( "%s%d%s", strSelColor, maxVal, strBaseColor )
			end

		elseif capture == "shipRankMin" then

			local minRank = -1

			if type( questInfo.shipRankMin ) == "number" then
				minRank = questInfo.shipRankMin
			else
				sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].shipRankMin\"; \"number\" expected, got \"%s\"", questId, type( questInfo.shipRankMin ) )
			end

			if minRank ~= -1 then
				strSubst = tostring( minRank )
			else
				strSubst = "unknown rank"
			end

		elseif capture == "shipRankMax" then

			local maxRank = -1

			if type( questInfo.shipRankMax ) == "number" then
				maxRank = questInfo.shipRankMax
			else
				sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].shipRankMax\"; \"number\" expected, got \"%s\"", questId, type( questInfo.shipRankMax ) )
			end

			if maxRank ~= -1 then
				strSubst = tostring( maxRank )
			else
				strSubst = "unknown rank"
			end

		elseif capture == "battlePoint" then

			local battleType = UI:GetQuestBattleType( questId )

			if battleType ==  ai.QuestBattleType.OW then

				local zoneName = UI:GetQuestBattlePoint( questId )
				if zoneName ~= "" then
					strSubst = UI:Zone2Str( zoneName )
				else
					sys.log( "UI:FillQuestDescWithParams()[ERROR]: cannot find zone for quest %d", questId )
				end

			elseif battleType ==  ai.QuestBattleType.PVE then

				local missionName = UI:GetQuestPveMission( questId )

				if missionName ~= "" then
					strSubst = UI:PveMission2Str( missionName )
				else

					local levelName = UI:GetQuestPveLevel( questId )
					if levelName ~= "" then
						strSubst = UI:GetLevelLocalizedName( levelName, false )
					else
						sys.log( "UI:FillQuestDescWithParams()[ERROR]: cannot find neither pve mission nor pve map for quest %d", questId )
					end

				end

			else
				sys.log( "UI:FillQuestDescWithParams()[ERROR]: unhandled battle type %d(%s) for quest %d", battleType, UI:Val2Key( ai.QuestBattleType, battleType ), questId )
			end

			if strSubst == nil then
				strSubst = "unknown level"
			end

		elseif capture == "unlimPveMissionLevel" then

			strSubst = "unknown"

			if params then

				for restrictionIdx, restriction in pairs( params ) do

					if restriction.param == ai.GameEventParam.UNLIM_PVE_MISSION_LEVEL then

						if type( restriction.min_value ) == "number" then

							local missionLevel = restriction.min_value
							strSubst = tostring( missionLevel )
							strSubst = string.format( "%s%s%s", strSelColor, strSubst, strBaseColor )

						else
							sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d].min_value\"; \"number\" expected, got \"%s\"", questId, restrictionIdx, type( restriction.min_value ) )
						end

						break

					end

				end

			end

		else

			local bOpenShop = false
			local strParamIdx = nil
			local strValIdx = nil

			local isLink = string.match( capture, "^link%s.*" ) ~= nil

			if not isLink then
				local strParamIdx, strValIdx = string.match( capture, "^param_(%d+)_(%d+)_shop$" )
				if strParamIdx and strValIdx then
					bOpenShop = true
				else
					strParamIdx, strValIdx = string.match( capture, "^param_(%d+)_(%d+)$" )
				end
			end

			if isLink then
				-- just ignore this
			elseif strParamIdx and strValIdx then

				if params then

            		local paramIdx = tonumber( strParamIdx )
            		local valIdx = tonumber( strValIdx )

            		local paramInfo = params[ paramIdx ]
            		if type( paramInfo ) == "table" then

                		local paramType = paramInfo.param
                		if type( paramType ) == "number" then

        					-- корабль
                    		if paramType == ai.GameEventParam.SHIP_NAME then

                    			local shipDefsNames = paramInfo.str_value
                    			if type( shipDefsNames ) == "table" then

                        			local shipDefName = shipDefsNames[ valIdx ]
                        			if type( shipDefName ) == "string" then

										if bOpenShop then
											sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid use of placeholder with \"_shop\" postfix for parameter of type %s in quest %d", UI:Val2Key( ai.GameEventParam, paramType ), questId )
										end

        								-- ок
        								strSubst = UI:GetEntityLocalizedNameByDef( shipDefName, false )
        								strSubst = string.format( "%s%s%s", strSelColor, strSubst, strBaseColor )

        							else
                        				sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d].str_value[%d]\"; \"string\" expected, got \"%s\"", questId, paramIdx, valIdx, type( shipDefName ) )
                        			end

        						else
                    				sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d].str_value\"; \"table\" expected, got \"%s\"", questId, paramIdx, type( shipDefsNames ) )
                    			end


        					-- тип предмета
                    		elseif paramType == ai.GameEventParam.ITEM_SUBTYPE then

                    			local itemSubTypes = paramInfo.num_value
                    			if type( itemSubTypes ) == "table" then

                        			local itemSubType = itemSubTypes[ valIdx ]
                        			if type( itemSubType ) == "number" then

        								if UI:Val2Key( _G.ItemSubtype, itemSubType ) ~= "" then

        									-- ок
        									if bAllowLinks then
        	                        			strSubst = string.format( "$link [type ITEM_SUBTYPE][params {itemSubType=%d, bOpenShop=%s}]$", itemSubType, tostring( bOpenShop ) )
        									else
        										strSubst = UI:ItemSubType2Str2( itemSubType )
        										strSubst = string.format( "%s%s%s", strSelColor, strSubst, strBaseColor )
        									end

        								else
        									sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid item subtype in \"_G.Quests[%d].restrictions[%d].num_value[%d]\"; on of the \"_G.ItemSubtype\" members expected, got \"%d\"", questId, paramIdx, valIdx. itemSubType )
        								end
        							else
                        				sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d].num_value[%d]\"; \"number\" expected, got \"%s\"", questId, paramIdx, valIdx, type( itemSubType ) )
                        			end
        						else
                    				sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d].num_value\"; \"table\" expected, got \"%s\"", questId, paramIdx, type( itemSubTypes ) )
                    			end


        					-- тип параметра, который не обрабатывается ui (задание было только на корабли и итем-сабтайп - #0030646)
                    		else
                    			sys.log( "UI:FillQuestDescWithParams()[ERROR]: unhandled type of parameter: %d (%s) referenced in placeholder \"%s\" in description for quest %d", paramType, UI:Val2Key( ai.GameEventParam, paramType ), "$"..capture.."$", questId )
                    		end

        				else
                			sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d].param\"; \"number\" expected, got \"%s\"", questId, paramIdx, type( paramType ) )
                		end
        			else
            			sys.log( "UI:FillQuestDescWithParams()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d]\"; \"table\" expected, got \"%s\"", questId, paramIdx, type( paramInfo ) )
            		end
				else
					sys.log( "UI:FillQuestDescWithParams()[ERROR]: cannot find _G.Quests[%d].restrictions to substitute placeholder \"%s\"", questId, "$"..capture.."$" )
				end
    		else
    			sys.log( "UI:FillQuestDescWithParams()[ERROR]: unhandled placeholder \"%s\" in description for quest %d", "$"..capture.."$", questId )
    		end
		end

		return strSubst

	end

	textWithParams = UI:SubstituteBaseColorPlaceholders( textWithParams, baseColor )
	textWithParams = string.gsub( textWithParams, "%$(.-)%$", fnSubst )

	return textWithParams

end


--
function UI:GetQuestInfo( questId )

	local questInfo = nil

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestInfo()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return questInfo
	end

	questInfo = _G.Quests and _G.Quests[ questId ]

	if questInfo ~= nil then
    	if type( questInfo ) ~= "table" then
    		sys.log( "UI:GetQuestInfo()[ERROR]: invalid type of _G.Quests[%d]; \"table\" expected, got \"%s\"", questId, type( questInfo ) )
    		questInfo = nil
    	end
	else
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestInfo()[ERROR]: cannot find _G.Quests[%d]", questId )
	end

	return questInfo

end


--
function UI:GetQuestTaskMaxVal( questId, stage )

	local val = nil

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestTaskMaxVal()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return val
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetQuestTaskMaxVal()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return val
	end

	local stageInfo = UI:GetQuestStageInfo( questId, stage )
	if not stageInfo then
		sys.log( "UI:GetQuestTaskMaxVal()[ERROR]: cannot find stage info for quest %d stage %d", questId, stage )
		return val
	end

	if stageInfo.required_value == nil then
		sys.log( "UI:GetQuestTaskMaxVal()[ERROR]: cannot find \"_G.Quests[%d].stages[%d].required_value\"", questId, stage )
		return val
	end

	if type( stageInfo.required_value ) ~= "number" then
		sys.log( "UI:GetQuestTaskMaxVal()[ERROR]: invalid type of the \"_G.Quests[%d].stages[%d].required_value\"; \"number\" expected, gpt \"%s\"", questId, stage, type( stageInfo.required_value ) )
		return val
	end

	val = stageInfo.required_value

	local event = UI:GetQuestEventForStage( questId, stage )
	if event == ai.GameEvent.ONLINE then
		val = val * 0.001	-- хранится в миллисекундах, возвращаю в секундах
	end

	return val

end


--
function UI:GetQuestTaskCurVal( questId )

	local val = nil

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestTaskCurVal()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return val
	end


	local activeData = UI.serverData.activeQuestsById[ questId ]
	if activeData then

		local stage = UI:GetQuestStage( questId )
		local event = UI:GetQuestEventForStage( questId, stage )

		if event == ai.GameEvent.ONLINE then

			if type( activeData.endsAt ) == "userdata" then

				if _G.MasterServer_IsConnected() then

					local curTime = _G.MasterServer_GetServerTime()

					local timeLeft = 0
					if activeData.endsAt > curTime then
						timeLeft = ( activeData.endsAt - curTime ).l * 0.001
					end

					local timeMax = UI:GetQuestTaskMaxVal( questId, stage )

					val = timeMax - timeLeft

				else
					sys.log( "UI:GetQuestTaskCurVal()[ERROR]: server is not connected" )
				end
			else
				sys.log( "UI:GetQuestTaskCurVal()[ERROR]: invalid type for \"endsAt\" for quest %d; \"userdata\" expected, got \"%s\"", questId, type( activeData.endsAt ) )
			end

		else

			if type( activeData.progress ) == "number" then
				val = activeData.progress
			else
				sys.log( "UI:GetQuestTaskCurVal()[ERROR]: invalid type for \"progress\" for quest %d; \"number\" expected, got \"%s\"", questId, type( activeData.progress ) )
			end

		end

	else

		if self:IsQuestCompleted( questId ) then
			val = self:GetQuestTaskMaxVal( questId, UI:GetQuestNumStages( questId ) )
		else
			val = 0
		end

	end

	return val

end


--
function UI:IsQuestCompleted( questId )

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestCompleted()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return false
	end

	return UI.serverData.completedQuestsById[ questId ] ~= nil

end


--
function UI:IsQuestTaken( questId )

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestTaken()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return false
	end

	return UI.serverData.activeQuestsById[ questId ] ~= nil

end


--
function UI:CanQuestBeCompleted( questId )

	if UI:IsQuestCompleted( questId ) then
		sys.log( "UI:CanQuestBeCompleted()[ERROR]: quest %d is already completed", questId )
		return false
	end

	if not UI:IsQuestTaken( questId ) then
		sys.log( "UI:CanQuestBeCompleted()[ERROR]: quest %d is not taken", questId )
		return false
	end

	local stage = UI:GetQuestStage( questId )
	local numStages = UI:GetQuestNumStages( questId )

	if stage < numStages then
		return false
	end

	local taskCurVal = UI:GetQuestTaskCurVal( questId )
	local taskMaxVal = UI:GetQuestTaskMaxVal( questId, numStages )

	local event = UI:GetQuestEventForStage( questId, stage )
	if event == ai.GameEvent.ONLINE then
		return taskCurVal ~= nil and ( taskCurVal - taskMaxVal ) > -1e-03
	else
		return taskCurVal ~= nil and taskCurVal >= taskMaxVal
	end

end


--
function UI:IsTutotialQuestPrevCompleted( questId )

	local questInfo = self:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:IsTutotialQuestPrevCompleted()[ERROR]: cannot find quest info for quest %s", tostring( questId ) )
		return true
	end

	local bUnlockNextDay = false

	if questInfo.unlocks_on_next_day ~= nil then

		if type( questInfo.unlocks_on_next_day ) == "boolean" then
			bUnlockNextDay = questInfo.unlocks_on_next_day
		else
			sys.log( "UI:IsTutotialQuestPrevCompleted()[ERROR]: invalid type of \"_G.Quests[%d].unlocks_on_next_day\"; \"boolean\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.unlocks_on_next_day ) )
		end

	end

	if questInfo.unlocks_after_all ~= nil then

		if type( questInfo.unlocks_after_all ) == "table" then

			if next( questInfo.unlocks_after_all ) then

				for idx, prevQuestId in pairs( questInfo.unlocks_after_all ) do
					if not self:IsQuestCompleted( prevQuestId ) or bUnlockNextDay and _G.MasterServer_IsQuestCompletedToday( prevQuestId ) then
						return false
					end
				end

			end

		else
			sys.log( "UI:IsTutotialQuestPrevCompleted()[ERROR]: invalid type of \"_G.Quests[%d].unlocks_after_all\"; \"table\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.unlocks_after_all ) )
		end

	end

	if questInfo.unlocks_after_any ~= nil then

		if type( questInfo.unlocks_after_any ) == "table" then

			if next( questInfo.unlocks_after_any ) then

				local bHasCompleted = false

				for idx, prevQuestId in pairs( questInfo.unlocks_after_any ) do
					if self:IsQuestCompleted( prevQuestId ) and ( not bUnlockNextDay or not _G.MasterServer_IsQuestCompletedToday( prevQuestId ) ) then
						bHasCompleted = true
						break
					end
				end

				if not bHasCompleted then
					return false
				end

			end

		else
			sys.log( "UI:IsTutotialQuestPrevCompleted()[ERROR]: invalid type of \"_G.Quests[%d].unlocks_after_any\"; \"table\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.unlocks_after_any ) )
		end

	end

	return true

end


-- возвращает непосредственных предшественников;
-- формат выозвращаемых данных: { <questId> = true, ... }
function UI:GetQuestParentQuests( questId )

	local parentQuests = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestParentQuests()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return parentQuests
	end

	local questInfo = self:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestParentQuests()[ERROR]: cannot find quest info for quest %s", tostring( questId ) )
		return parentQuests
	end

	if questInfo.unlocks_after_all ~= nil then

		if type( questInfo.unlocks_after_all ) == "table" then

			for idx, parentQuestId in pairs( questInfo.unlocks_after_all ) do
				if type( parentQuestId ) == "number" then
					parentQuests[ parentQuestId ] = true
				else
					sys.log( "UI:GetQuestParentQuests()[ERROR]: invalid type of \"_G.Quests[%d].unlocks_after_all[%s]\"; \"number\" expected, got \"%s\"", questId, tostring( idx ), type( questInfo.unlocks_after_all ) )
				end
			end

		else
			sys.log( "UI:GetQuestParentQuests()[ERROR]: invalid type of \"_G.Quests[%d].unlocks_after_all\"; \"table\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.unlocks_after_all ) )
		end

	end

	if questInfo.unlocks_after_any ~= nil then

		if type( questInfo.unlocks_after_any ) == "table" then

			for idx, parentQuestId in pairs( questInfo.unlocks_after_any ) do
				if type( parentQuestId ) == "number" then
					parentQuests[ parentQuestId ] = true
				else
					sys.log( "UI:GetQuestParentQuests()[ERROR]: invalid type of \"_G.Quests[%d].unlocks_after_any[%s]\"; \"number\" expected, got \"%s\"", questId, tostring( idx ), type( questInfo.unlocks_after_any ) )
				end
			end

		else
			sys.log( "UI:GetQuestParentQuests()[ERROR]: invalid type of \"_G.Quests[%d].unlocks_after_any\"; \"table\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.unlocks_after_any ) )
		end

	end

	return parentQuests

end


-- возвращает всех предшественников вглубь по иерархии;
-- формат возвращаемых данных: { <questId> = true, ... }
function UI:GetQuestAncestorQuests( questId )

	local ancestorQuests = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestAncestorQuests()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return ancestorQuests
	end

	local function fnRecurse( childQuestId )

		local parentQuests = UI:GetQuestParentQuests( childQuestId )

    	for parentQuestId, val in pairs( parentQuests ) do

    		ancestorQuests[ parentQuestId ] = true
			fnRecurse( parentQuestId )

		end

	end

	fnRecurse( questId )

	return ancestorQuests

end


--
function UI:GetQuestHangarRace( questId )

	local race = -1

	local questInfo = self:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestHangarRace()[ERROR]: cannot find quest info for quest %s", tostring( questId ) )
		return race
	end

	local group = UI:GetQuestGroup( questId )

	if group ~= -1 then

    	local groupInfo = _G.QuestGroups and _G.QuestGroups[ group ]
    	if type( groupInfo ) ~= "table" then
    		sys.log( "UI:GetQuestHangarRace()[ERROR]: invalid type of _G.QuestGroups[%d]; \"table\" expected, got \"%s\"", group, type( groupInfo ) )
    		return race
    	end

		if groupInfo.space_station_race ~= nil then

           	if type( groupInfo.space_station_race ) ~= "number" then
           		sys.log( "UI:GetQuestHangarRace()[ERROR]: invalid type of \"_G.QuestGroups[%d].space_station_race\"; \"number\" or \"nil\" expected, got \"%s\"", group, type( groupInfo.space_station_race ) )
        		return race
        	end

           	race = groupInfo.space_station_race

        	if UI:Val2Key( ai.Race, race ) == "" then
        		sys.log( "UI:GetQuestHangarRace()[ERROR]: invalid race in %d in \"_G.QuestGroups[%d].space_station_race\"", race, group )
        		race = -1
        	end

		end

	else

		if questInfo.space_station_race ~= nil then

            if type( questInfo.space_station_race ) ~= "number" then
            	sys.log( "UI:GetQuestHangarRace()[ERROR]: invalid type of \"_G.Quests[%d].space_station_race\"; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.space_station_race ) )
         		return race
         	end

           	race = questInfo.space_station_race

        	if UI:Val2Key( ai.Race, race ) == "" then
        		sys.log( "UI:GetQuestHangarRace()[ERROR]: invalid race in %d in \"_G.Quests[%d].space_station_race\"", race, questId )
        		race = -1
        	end

		end

	end

	if race == ai.Race.NUM then
		race = -1
	end

	return race

end


--
function UI:IsQuestDisabled( questId )

	local bDisabled = true

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestDisabled()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bDisabled
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:IsQuestDisabled()[ERROR]:cannot find quest info for quest %d", questId )
		return bDisabled
	end

	bDisabled = false

	if questInfo.disabled ~= nil then

		if type( questInfo.disabled ) == "boolean" then
			bDisabled = questInfo.disabled
		else
			sys.log( "UI:IsQuestDisabled()[ERROR]: invalid type of _G.Quests[%d].disabled; \"boolean\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.disabled ) )
		end

	end

	return bDisabled

end


--
function UI:IsQuestUnavailable( questId )

	local bUnavailable = true

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestUnavailable()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bUnavailable
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		return bUnavailable
	end

	bUnavailable = false

	if questInfo.acceptable_during ~= nil then

		if type( questInfo.acceptable_during ) == "number" then

			if not UI:IsQuestTaken( questInfo.acceptable_during ) then
				bUnavailable = true
			end
			
		else
			sys.log( "UI:IsQuestUnavailable()[ERROR]: invalid type of _G.Quests[%d].acceptable_during; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.acceptable_during ) )
		end

	end

	return bUnavailable

end


--
function UI:GetQuestDialogsForEvent( questId, stage, eventIdx )

	local dialogs = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestDialogsForEvent()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return dialogs
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetQuestDialogsForEvent()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return dialogs
	end

	if type( eventIdx ) ~= "number" then
		sys.log( "UI:GetQuestDialogsForEvent()[ERROR]: invalid type of the 3-rd parameter (\"eventIdx\"); \"number\" expected, got \"%s\"", type( eventIdx ) )
		return dialogs
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestDialogsForEvent()[ERROR]:cannot find quest info for quest %d", questId )
		return dialogs
	end

	if type( questInfo.stages ) ~= "table" then
		sys.log( "UI:GetQuestDialogsForEvent()[ERROR]: invalid type of _G.Quests[%d].stages; \"table\" expected, got \"%s\"", questId, type( questInfo.stages ) )
		return dialogs
	end

	local stageInfo = questInfo.stages[ stage ]
	if type( stageInfo ) ~= "table" then
		sys.log( "UI:GetQuestDialogsForEvent()[ERROR]: invalid type of _G.Quests[%d].stages[%d]; \"table\" expected, got \"%s\"", questId, stage, type( stageInfo ) )
		return dialogs
	end

	if type( stageInfo.info_events ) ~= "table" then
		sys.log( "UI:GetQuestDialogsForEvent()[ERROR]: invalid type of _G.Quests[%d].stages[%d].info_events; \"table\" expected, got \"%s\"", questId, stage, type( stageInfo.info_events ) )
		return dialogs
	end

	local eventInfo = stageInfo.info_events[ eventIdx ]
	if type( eventInfo ) ~= "table" then
		sys.log( "UI:GetQuestDialogsForEvent()[ERROR]: invalid type of _G.Quests[%d].stages[%d].info_events[%d]; \"table\" expected, got \"%s\"", questId, stage, eventIdx, type( eventInfo ) )
		return dialogs
	end

	if type( eventInfo.dialogs ) ~= "table" then
		sys.log( "UI:GetQuestDialogsForEvent()[ERROR]: invalid type of _G.Quests[%d].stages[%d].info_events[%d].dialogs; \"table\" expected, got \"%s\"", questId, stage, eventIdx, type( eventInfo.dialogs ) )
		return dialogs
	end

	dialogs = eventInfo.dialogs
	return dialogs

end


--
function UI:GetQuestNumDialogsForEvent( questId, stage, eventIdx )

	local dialogs = UI:GetQuestDialogsForEvent( questId, stage, eventIdx )
	return #dialogs

end


--
function UI:GetQuestDialogInfo( questId, stage, eventIdx, dialogIdx )

	local dialogInfo = nil

	if type( dialogIdx ) ~= "number" then
		sys.log( "UI:GetQuestDialogInfo()[ERROR]: invalid type of the 3-rd parameter (\"dialogIdx\"); \"number\" expected, got \"%s\"", type( dialogIdx ) )
		return dialogInfo
	end

	local dialogs = UI:GetQuestDialogsForEvent( questId, stage, eventIdx )

	local dlgInfo = dialogs[ dialogIdx ]
	if type( dlgInfo ) ~= "table" then
		sys.log( "UI:GetQuestDialogInfo()[ERROR]: invalid type of _G.Quests[%d].stages[%d].info_events[%d].dialogs[%d]; \"table\" expected, got \"%s\"", questId, stage, eventIdx, dialogIdx, type( dlgInfo ) )
		return dialogInfo
	end

	dialogInfo = dlgInfo
	return dialogInfo

end


-- SC-115197: преобразование таблицы с наградой из нотификации SV_FreeSpace_GiveReward в таблицу с наградой за обычные квесты
function UI:ScriptRewardToQuestRewards( reward )

	local questReward = {}
	
	if reward.credits ~= nil then
		local tt =
		{
			rewardType	= UI.questRewardTypes.CREDITS,
			val			= reward.credits,
		}
		table.insert( questReward, tt )
	end
	
	if reward.gold ~= nil then
		local tt =
		{
			rewardType	= UI.questRewardTypes.GOLD,
			val			= reward.gold,
		}
		table.insert( questReward, tt )
	end
	
	if reward.event_credits ~= nil then
		local tt =
		{
			rewardType	= UI.questRewardTypes.EVENT_CREDITS,
			val			= reward.event_credits,
		}
		table.insert( questReward, tt )
	end
	
	if reward.tokens ~= nil then
		local tt =
		{
			rewardType	= UI.questRewardTypes.TOKENS,
			val			= reward.tokens,
		}
		table.insert( questReward, tt )
	end
	
	if reward.vessel_xp ~= nil then
		local tt =
		{
			rewardType	= UI.questRewardTypes.SYNERGY,
			val			= reward.vessel_xp,
			-- TODO vid
		}
		table.insert( questReward, tt )
	end
	
	if reward.free_xp ~= nil then
		local tt =
		{
			rewardType	= UI.questRewardTypes.FREE_SYNERGY,
			val			= reward.free_xp,
		}
		table.insert( questReward, tt )
	end
	
	if reward.account_aura ~= nil then
		local tt =
		{
			rewardType		= UI.questRewardTypes.ACCOUNT_AURA,
			defName			= reward.account_aura,
		}
		table.insert( questReward, tt )
	end
	
	if reward.items ~= nil then
		for itemIdx, itemInfo in ipairs( reward.items ) do
			if type( itemInfo ) == "table" then
				itemInfo.rewardType = UI.questRewardTypes.ITEM
				table.insert( questReward, itemInfo )
			end
		end
	end
	
	return questReward
	
end


-- используются либо bPremiumOnlyModifiers/bEmulatePremium, либо completionData
function UI:GetQuestRewards( questId, bSeparateReward, bPremiumOnlyModifiers, bEmulatePremium, completionData, bSort )

	local rewards = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return rewards
	end

	if bSeparateReward ~= nil then
		if type( bSeparateReward ) ~= "boolean" then
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of the 2-nd parameter (\"bSeparateReward\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bSeparateReward ) )
			bSeparateReward = nil
		end
	end

	if bSeparateReward == nil then
		bSeparateReward = false
	end

	if bPremiumOnlyModifiers ~= nil then
		if type( bPremiumOnlyModifiers ) ~= "boolean" then
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of the 3-rd parameter (\"bPremiumOnlyModifiers\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bPremiumOnlyModifiers ) )
			bPremiumOnlyModifiers = nil
		end
	end

	if bPremiumOnlyModifiers == nil then
		bPremiumOnlyModifiers = false
	end

	if bEmulatePremium ~= nil then
		if type( bEmulatePremium ) ~= "boolean" then
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of the 4-th parameter (\"bEmulatePremium\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bEmulatePremium ) )
			bEmulatePremium = nil
		end
	end

	if bEmulatePremium == nil then
		bEmulatePremium = false
	end

	if completionData ~= nil then
		if type( completionData ) ~= "table" then
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of the 5-rd parameter (\"completionData\"); \"table\" or \"nil\" expected, got \"%s\"", type( completionData ) )
			completionData = nil
		end
	end

	if bSort ~= nil then
		if type( bSort ) ~= "boolean" then
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of the 6-th parameter (\"bSort\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bSort ) )
			bSort = nil
		end
	end

	if bSort == nil then
		bSort = true
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
	    -- sys.log( "UI:GetQuestRewards()[ERROR]: cannot find questInfo for quest id %d", questId )
		return rewards
	end

	local creditsModifier		= 1
	local resourceModifier		= 1
	local synergyModifier		= 1

	if completionData then

		if completionData.creditsCoef ~= nil then

			if type( completionData.creditsCoef ) == "number" then
				creditsModifier = completionData.creditsCoef
			else
				sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of field \"creditsCoef\" in \"completionData\"; \"number\" or \"nil\" expected, got \"%s\"", type( completionData.creditsCoef ) )
			end

		end

		if completionData.resourceCoef ~= nil then

			if type( completionData.resourceCoef ) == "number" then
				resourceModifier = completionData.resourceCoef
			else
				sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of field \"resourceCoef\" in \"completionData\"; \"number\" or \"nil\" expected, got \"%s\"", type( completionData.resourceCoef ) )
			end

		end

		if completionData.expCoef ~= nil then

			if type( completionData.expCoef ) == "number" then
				synergyModifier = completionData.expCoef
			else
				sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of field \"expCoef\" in \"completionData\"; \"number\" or \"nil\" expected, got \"%s\"", type( completionData.expCoef ) )
			end

		end

	else

		local modifiers = _G.MasterServer_GetQuestRewardModifiers( questId, bPremiumOnlyModifiers, bEmulatePremium )

		if type( modifiers.creditsCoef ) == "number" then
			creditsModifier = modifiers.creditsCoef
		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of \"creditsCoef\" after _G.MasterServer_GetQuestRewardModifiers(); \"number\" expected, got \"%s\"", type( modifiers.creditsCoef ) )
		end

		if type( modifiers.resourceCoef ) == "number" then
			resourceModifier = modifiers.resourceCoef
		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of \"resourceCoef\" after _G.MasterServer_GetQuestRewardModifiers(); \"number\" expected, got \"%s\"", type( modifiers.resourceCoef ) )
		end

		if type( modifiers.expCoef ) == "number" then
			synergyModifier = modifiers.expCoef
		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of \"expCoef\" after _G.MasterServer_GetQuestRewardModifiers(); \"number\" expected, got \"%s\"", type( modifiers.expCoef ) )
		end

	end


	-- 1. золото

	if questInfo.reward_gold_credits ~= nil then

		if type( questInfo.reward_gold_credits ) == "number" then

			local goldReward =
			{
				rewardType	= UI.questRewardTypes.GOLD,
				val			= questInfo.reward_gold_credits,
			}
			table.insert( rewards, goldReward )

		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_gold_credits; \"number\" expected, got \"%s\"", questId, type( questInfo.reward_gold_credits ) )
		end

	end


	-- 2. кредиты

	if questInfo.reward_credits ~= nil then

		if type( questInfo.reward_credits ) == "number" then

			local valBase		= questInfo.reward_credits
			local valModified	= UI:Round( valBase * creditsModifier )

			if bSeparateReward then

    			local creditsRewardBase =
    			{
    				rewardType	= UI.questRewardTypes.CREDITS,
    				val			= valBase,
    			}
    			table.insert( rewards, creditsRewardBase )

				if valModified > valBase then

        			local creditsRewardBonus =
        			{
        				rewardType	= UI.questRewardTypes.CREDITS,
        				val			= valModified - valBase,
						bBonus		= true,
        			}
        			table.insert( rewards, creditsRewardBonus )

				end

			else

    			local creditsRewardModified =
    			{
    				rewardType		= UI.questRewardTypes.CREDITS,
    				val				= valModified,
					bBonusIncluded	= valModified ~= valBase,
    			}
    			table.insert( rewards, creditsRewardModified )

			end

		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_credits; \"number\" expected, got \"%s\"", questId, type( questInfo.reward_credits ) )
		end

	end


	-- 3. токены (иридиум для игрока)

	if questInfo.reward_tokens ~= nil then

		if type( questInfo.reward_tokens ) == "number" then

			local tokensReward =
			{
				rewardType	= UI.questRewardTypes.TOKENS,
				val			= questInfo.reward_tokens,
			}
			table.insert( rewards, tokensReward )

		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_tokens; \"number\" expected, got \"%s\"", questId, type( questInfo.reward_tokens ) )
		end

	end


	-- 4. клановый иридиум

	if questInfo.reward_iridium ~= nil then

		if type( questInfo.reward_iridium ) == "number" then

			local iridiumReward =
			{
				rewardType	= UI.questRewardTypes.CLAN_IRIDIUM,
				val			= questInfo.reward_iridium,
			}
			table.insert( rewards, iridiumReward )

		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_iridium; \"number\" expected, got \"%s\"", questId, type( questInfo.reward_iridium ) )
		end

	end


	-- 5. синергия

	if questInfo.reward_vessel_exp ~= nil then

		if type( questInfo.reward_vessel_exp ) == "number" then

			local valBase		= questInfo.reward_vessel_exp
			local valModified	= UI:Round( valBase * synergyModifier )

			local vid = UI.INVALID_U64_ID

			if completionData then

				if type( completionData.usedVid ) == "userdata" then
					vid = completionData.usedVid
				else
        			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of field \"usedVid\" in \"completionData\"; \"userdata\" expected, got \"%s\"", type( completionData.usedVid ) )
				end

			end

			if bSeparateReward then

    			local synergyRewardBase =
    			{
    				rewardType	= UI.questRewardTypes.SYNERGY,
    				val			= valBase,
					vid			= vid,
    			}
    			table.insert( rewards, synergyRewardBase )

				if valModified > valBase then

        			local synergyRewardBonus =
        			{
        				rewardType	= UI.questRewardTypes.SYNERGY,
        				val			= valModified - valBase,
						vid			= vid,
						bBonus		= true,
        			}
        			table.insert( rewards, synergyRewardBonus )

				end

			else

    			local synergyRewardModified =
    			{
    				rewardType		= UI.questRewardTypes.SYNERGY,
    				val				= valModified,
					vid				= vid,
					bBonusIncluded	= valModified ~= valBase,
    			}
    			table.insert( rewards, synergyRewardModified )

			end

		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_vessel_exp; \"number\" expected, got \"%s\"", questId, type( questInfo.reward_vessel_exp ) )
		end

	end


	-- 6. предметы; среди предметов - сортировка по имени дефинишена

	if questInfo.reward_items ~= nil then

		if type( questInfo.reward_items ) == "table" then

			local itemsRewards = {}

			for itemIdx, itemInfo in ipairs( questInfo.reward_items ) do

				if type( itemInfo ) == "table" then

					local itemDefName = itemInfo[ 1 ]
					if type( itemDefName ) == "string" then

						local countBase = itemInfo[ 2 ]
						if countBase == nil then
							countBase = 1
						else
							if type( countBase ) ~= "number" then
								sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_items[%d][2]; \"number\" or \"nil\" expected, got \"%s\"", questId, itemIdx, type( countBase ) )
								countBase = 1
							end
						end

						local countModified = countBase

						if UI:IsDefResource( itemDefName ) or UI:IsDefBlueprint( itemDefName ) then
							countModified = UI:Round( countBase * resourceModifier )
						end

						if bSeparateReward then

                			local itemRewardBase =
                			{
                				rewardType	= UI.questRewardTypes.ITEM,
                				defName		= itemDefName,
    							count		= countBase,
                			}
    						table.insert( itemsRewards, itemRewardBase )

							if countModified > countBase then

                    			local itemRewardBonus =
                    			{
                    				rewardType	= UI.questRewardTypes.ITEM,
                    				defName		= itemDefName,
        							count		= countModified - countBase,
									bBonus		= true,
                    			}
        						table.insert( itemsRewards, itemRewardBonus )

							end

						else

                			local itemRewardModified =
                			{
                				rewardType		= UI.questRewardTypes.ITEM,
                				defName			= itemDefName,
    							count			= countModified,
								bBonusIncluded	= countModified ~= countBase,
                			}
    						table.insert( itemsRewards, itemRewardModified )

						end

					else
						sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_items[%d][1]; \"string\" expected, got \"%s\"", questId, itemIdx, type( itemDefName ) )
					end

				else
					sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_items[%d]; \"table\" expected, got \"%s\"", questId, itemIdx, type( itemInfo ) )
				end

			end

			if bSort then

    			local function fnSortItems( itemReward1, itemReward2 )

    				if itemReward1.defName == itemReward2.defName then

    					local bBonus1 = itemReward1.bBonus == true
    					local bBonus2 = itemReward2.bBonus == true

    					return not bBonus1 and bBonus2

    				else
    					return itemReward1.defName < itemReward2.defName
    				end

    			end

    			table.sort( itemsRewards, fnSortItems )

			end

			for itemIdx, itemReward in ipairs( itemsRewards ) do
				table.insert( rewards, itemReward )
			end

		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_items; \"table\" expected, got \"%s\"", questId, type( questInfo.reward_items ) )
		end

	end


	-- 7. аккаунт-аура

	if questInfo.reward_account_aura ~= nil then

		if type( questInfo.reward_account_aura ) == "string" then

			local auraReward =
			{
				rewardType	= UI.questRewardTypes.ACCOUNT_AURA,
				defName		= questInfo.reward_account_aura,
			}
			table.insert( rewards, auraReward )

		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_account_aura; \"string\" expected, got \"%s\"", questId, type( questInfo.reward_account_aura ) )
		end

	end


	-- 8. ивентовые кредиты

	if questInfo.reward_event_credits ~= nil then

		if type( questInfo.reward_event_credits ) == "number" then

			local eventCreditsReward =
			{
				rewardType	= UI.questRewardTypes.EVENT_CREDITS,
				val			= questInfo.reward_event_credits ,
			}
			table.insert( rewards, eventCreditsReward )

		else
			sys.log( "UI:GetQuestRewards()[ERROR]: invalid type of _G.Quests[%d].reward_event_credits; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.reward_event_credits ) )
		end

	end


	return rewards

end


-- вырожденный случай UI:GetQuestRewards() - возвращается только одна награда (которая указана поле ui_reward)
-- используются либо bPremiumOnlyModifiers/bEmulatePremium, либо completionData
function UI:GetQuestSingleReward( questId, bSeparateReward, bPremiumOnlyModifiers, bEmulatePremium, completionData )

	local singleReward = nil

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestSingleReward()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return singleReward
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
	    -- sys.log( "UI:GetQuestSingleReward()[ERROR]: cannot find questInfo for quest id %d", questId )
		return singleReward
	end

	if type( questInfo.ui_reward ) ~= "string" then
		sys.log( "UI:GetQuestSingleReward()[ERROR]: invalid type of _G.Quests[%d].ui_reward; \"string\" expected, got \"%s\"", questId, type( questInfo.ui_reward ) )
		return singleReward
	end

    local fieldName2RewardType =
    {
    	reward_gold_credits 	= UI.questRewardTypes.GOLD,
    	reward_credits      	= UI.questRewardTypes.CREDITS,
    	reward_items        	= UI.questRewardTypes.ITEM,
    	reward_tokens       	= UI.questRewardTypes.TOKENS,
    	reward_vessel_exp   	= UI.questRewardTypes.SYNERGY,
    	reward_iridium      	= UI.questRewardTypes.CLAN_IRIDIUM,
    	reward_account_aura 	= UI.questRewardTypes.ACCOUNT_AURA,
    	reward_event_credits	= UI.questRewardTypes.EVENT_CREDITS,
    }

	local singleRewardType = fieldName2RewardType[ questInfo.ui_reward ]
	if singleRewardType == nil then
		sys.log( "UI:GetQuestSingleReward()[ERROR]: unhandled reward \"%s\" for quest %d", questInfo.ui_reward, questId )
		return singleReward
	end

	local allRewards = UI:GetQuestRewards( questId, bSeparateReward, bPremiumOnlyModifiers, bEmulatePremium, completionData, false )

	for rewardIdx, reward in ipairs( allRewards ) do
		if reward.rewardType == singleRewardType then
			singleReward = reward
			break
		end
	end

	if singleReward == nil then
		sys.log( "UI:GetQuestSingleReward()[ERROR]: cannot find single reward for quest %d", questId )
	end

	return singleReward

end


