--
function UI:GetQuestStage( questId )

	local stage = -1

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestStage()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return stage
	end

	if self:IsQuestCompleted( questId ) then
		return UI:GetQuestNumStages( questId )
	end

	local activeData = UI.serverData.activeQuestsById[ questId ]
	if activeData then

    	if type( activeData.stage ) == "number" then
			stage = activeData.stage
		else
    		sys.log( "UI:GetQuestStage()[ERROR]: invalid type of \"stage\" field after _G.MasterServer_GetActiveQuests() for quest %d; \"number\" expected, got \"%s\"", questId, type( activeData.stage ) )
    	end

	else
		stage = 1
	end

	return stage

end


--
function UI:GetQuestStageInfo( questId, stage )

	local stageInfo = nil

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestStageInfo()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return stageInfo
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetQuestStageInfo()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return stageInfo
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestStageInfo()[ERROR]:cannot find quest info for quest %d", questId )
		return stageInfo
	end

	if type( questInfo.stages ) ~= "table" then
		sys.log( "UI:GetQuestStageInfo()[ERROR]: invalid type of _G.Quests[%d].stages; \"table\" expected, got \"%s\"", questId, type( questInfo.stages ) )
		return stageInfo
	end

	stageInfo = questInfo.stages[ stage ]

	if type( stageInfo ) ~= "table" then
		sys.log( "UI:GetQuestStageInfo()[ERROR]: invalid type of _G.Quests[%d].stages[%d]; \"table\" expected, got \"%s\"", questId, stage, type( stageInfo ) )
		stageInfo = nil
	end

	return stageInfo

end


