--
function UI:GetQuestZonesForStage( questId, stage )

	local zones = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestZonesForStage()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return zones
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetQuestZonesForStage()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return zones
	end

	local stageInfo = UI:GetQuestStageInfo( questId, stage )
	if not stageInfo then
		sys.log( "UI:GetQuestZonesForStage()[ERROR]: cannot find stage info for quest %d stage %d", questId, stage )
		return zones
	end

	if stageInfo.marked_zone_id == nil then
		return zones
	end

	if type( stageInfo.marked_zone_id ) == "number" then

		if stageInfo.marked_zone_id ~= 0 then
			table.insert( zones, stageInfo.marked_zone_id )
		end

	elseif type( stageInfo.marked_zone_id ) == "table" then

		local bValid = true

		for zoneIdx, zoneId in pairs( stageInfo.marked_zone_id ) do
			if type( zoneIdx ) ~= "number" or type( zoneId ) ~= "number" then
				sys.log( "UI:GetQuestZonesForStage()[ERROR]: invalid format of table field \"marked_zone_id\" for quest %d stage %d; <number>=<number> expected, got <%s>=<%s>", questId, stage, type( zoneIdx ), type( zoneId ) )
				bValid = false
				break
			end
		end

		if bValid then
			zones = stageInfo.marked_zone_id
		end

	else
		sys.log( "UI:GetQuestZonesForStage()[ERROR]: invalid type of \"marked_zone_id\" for quest %d stage %d; \"number\", \"table\" or \"nil\" expected, got \"%s\"", questId, stage, type( stageInfo.marked_zone_id ) )
	end

	return zones

end


