--
function UI:IsZoneAlwaysAccessible( zoneId )

	if type( zoneId ) ~= "number" then
		sys.log( "UI:IsZoneAlwaysAccessible()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return false
	end

	if type( _G.START_ZONE_ID ) ~= "number" then
		sys.log( "UI:IsZoneAlwaysAccessible()[ERROR]: invalid type of _G.START_ZONE_ID; \"number\" expected, got \"%s\"", type( _G.START_ZONE_ID ) )
		return false
	end

	return zoneId == _G.START_ZONE_ID

end


--
function UI:GetQuestZoneToTransfer( questId )

	local transferZoneId = -1

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestZoneToTransfer()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return transferZoneId
	end

	local stage 			= UI:GetQuestStage( questId )
	local allZones 			= UI:GetQuestZonesForStage( questId, stage )
	local accessibleZones	= UI:GetQuestAccessibleZonesForStage( questId, stage )
	local currentZoneId		= ( _G.GetCurrentGameMode() == ai.Gameplay.NONE ) and _G.MasterServer_GetSpaceStationZoneId() or _G.CL_GetCurrentSpaceZoneId()

	for idx, zoneId in ipairs( allZones ) do

		local bFit = true

		if zoneId ~= currentZoneId and not UI:IsZoneAlwaysAccessible( zoneId ) then

			-- флаг 'allowed_jump' в дефе
			if not UI:IsZoneAllowedForTransfer( zoneId ) then
				bFit = false
			end

			-- аккаунт ранг
			if bFit then

				local bNeedCheckRank = true

				local bAccessibleByQuest = false
				for accessibleIdx, accessibleZoneId in pairs( accessibleZones ) do
					if accessibleZoneId == zoneId then
						bAccessibleByQuest = true
						break
					end
				end

				if bAccessibleByQuest then
					bNeedCheckRank = false
				end

				if bNeedCheckRank then
					if UI:GetZoneUnlockRank( zoneId ) > UI:GetPlayerAccountRank() then
						bFit = false
					end
				end

			end

		end

		if bFit then
			transferZoneId = zoneId
			break
		end

	end

	return transferZoneId

end


