--
function UI:IsQuestUnlockedByRank( questId )

	local bUnlocked = true

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestUnlockedByRank()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bUnlocked
	end

	local questMinRank	= UI:GetQuestMinAccountRank( questId )
	local questMaxRank	= UI:GetQuestMaxAccountRank( questId )
	local playerRank	= UI:GetPlayerAccountRank()

	bUnlocked = ( questMinRank == -1 or playerRank >= questMinRank ) and ( questMaxRank == -1 or playerRank <= questMaxRank )

	return bUnlocked

end


