--
function UI:GetQuestMaxAccountRank( questId )

	local rank = -1

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestMaxAccountRank()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
