			end

		else
			sys.log( "UI:GetQuestMaxAccountRank()[ERROR]: invalid type of the _G.Quests[%d].locks_on_account_rank; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.locks_on_account_rank ) )
		end

	end

	return rank

