--
function UI:GetQuestMarkDefsForStage( questId, stage )

	local markDefs = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestMarkDefsForStage()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return markDefs
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetQuestMarkDefsForStage()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return markDefs
	end

	local stageInfo = UI:GetQuestStageInfo( questId, stage )
	if not stageInfo then
		sys.log( "UI:GetQuestMarkDefsForStage()[ERROR]: cannot find stage info for quest %d stage %d", questId, stage )
		return markDefs
	end

	if stageInfo.hud_marker_defs == nil then
		return markDefs
	end

	if type( stageInfo.hud_marker_defs ) ~= "table" then
		sys.log( "UI:GetQuestMarkDefsForStage()[ERROR]: invalid type of the _G.Quests[%d].stages[%d].hud_marker_defs; \"table\" or \"nil\" expected, got \"%s\"", questId, stage, type( stageInfo.hud_marker_defs ) )
		return markDefs
	end

	for idx, defName in pairs( stageInfo.hud_marker_defs ) do
		if type( defName ) == "string" then
			markDefs[ defName ] = true
		else
			sys.log( "UI:GetQuestMarkDefsForStage()[ERROR]: invalid type of the _G.Quests[%d].stages[%d].hud_marker_defs[%d]; \"string\" or \"nil\" expected, got \"%s\"", questId, stage, idx, type( defName ) )
		end
	end

	return markDefs

end


--
function UI:GetQuestTag( questId )

	local tag = -1

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestTag()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return tag
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestTag()[ERROR]: cannot find quest info for quest %s", tostring( questId ) )
		return tag
	end

	if questInfo.tag ~= nil then
		if type( questInfo.tag ) == "number" then
			tag = questInfo.tag
		else
			sys.log( "UI:GetQuestTag()[ERROR]: invalid type of the _G.Quests[%d].tag; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.tag ) )
		end
	end

	return tag

end


--
function UI:IsCustomEventQuestAvailableByDay( questId )

	if type( questId ) ~= "number" then
		sys.log( "UI:IsCustomEventQuestAvailableByDay()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return false
	end

	if UI:GetQuestTag( questId ) ~= ai.QuestTag.CUSTOM_EVENT then
		sys.log( "UI:IsCustomEventQuestAvailableByDay()[ERROR]: quest %d is not with CUSTOM_EVENT tag", questId )
		return false
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:IsCustomEventQuestAvailableByDay()[ERROR]: cannot find quest info for quest %s", tostring( questId ) )
		return false
	end

	if questInfo.event_day == nil and questInfo.event_day_min == nil and questInfo.event_day_max == nil then
		return true
	end

	if questInfo.event_day ~= nil then

		if type( questInfo.event_day ) == "number" then
			return _G.MasterServer_IsCurrentCustomEventDay( questInfo.event_day )
		else
			sys.log( "UI:IsCustomEventQuestAvailableByDay()[ERROR]: invalid type of _G.Quests[%d].event_day; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.event_day ) )
			return false
		end

	end

	if questInfo.event_day_min ~= nil then
		if type( questInfo.event_day_min ) ~= "number" then
			sys.log( "UI:IsCustomEventQuestAvailableByDay()[ERROR]: invalid type of _G.Quests[%d].event_day_min; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.event_day_min ) )
			return false
		end
	end

	if questInfo.event_day_max ~= nil then
		if type( questInfo.event_day_max ) ~= "number" then
			sys.log( "UI:IsCustomEventQuestAvailableByDay()[ERROR]: invalid type of _G.Quests[%d].event_day_max; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.event_day_max ) )
			return false
		end
	end

	if questInfo.event_day_min and questInfo.event_day_max then
		return _G.MasterServer_IsCurrentCustomEventDay( questInfo.event_day_min, questInfo.event_day_max )

	elseif questInfo.event_day_min then
		return _G.MasterServer_IsCurrentCustomEventDay( questInfo.event_day_min )

	elseif questInfo.event_day_max then
		return _G.MasterServer_IsCurrentCustomEventDay( 1, questInfo.event_day_max )
	end

	sys.log( "UI:IsCustomEventQuestAvailableByDay()[ERROR]: cannot be here" )
	return false

end


