function UI:IsQuestTheOnlyInGroup( questId )

	local bTheOnly = true

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestTheOnlyInGroup()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bTheOnly
	end

	local questGroup = UI:GetQuestGroup( questId )
	if questGroup == -1 then
		sys.log( "UI:IsQuestTheOnlyInGroup()[ERROR]: cannot find group for quest %d", questId )
		return bTheOnly
	end

	if type( _G.QuestId ) ~= "table" then
		sys.log( "UI:IsQuestTheOnlyInGroup()[ERROR]: invalid type of _G.QuestId; \"table\" expected, got \"%s\"", type( _G.QuestId ) )
		return bTheOnly
	end

	for name, id in pairs( _G.QuestId ) do

		if id ~= questId then

			local group = UI:GetQuestGroup( id )
			if group == questGroup then

				bTheOnly = false
				break

			end

		end

	end

	return bTheOnly

end


