--
function UI:IsQuestOffered( questId )

	local bOffered = false

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestOffered()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bOffered
	end

	if not UI:IsQuestRecurrent( questId ) then
		sys.log( "UI:IsQuestOffered()[ERROR]: quest %d is not recurrent", questId )
		return bOffered
	end

	if UI:IsQuestManuallyOfferable( questId ) then

		-- предполагается, что проверки на другие условия (соотвествие рангу, ивенту и т.п.) будут произведены за пределами этой функции

		local groupId = UI:GetQuestGroup( questId )

		bOffered =
			not UI:IsQuestTaken( questId )
			and UI:GetQuestGroupCooldown( groupId ) <= 0
			and not UI:HasGroupActiveQuest( groupId )

	else
		bOffered = UI.serverData.offeredQuestsById[ questId ] ~= nil
	end

	return bOffered

end


--
function UI:IsQuestManuallyOfferable( questId )

	local bManually = false

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestManuallyOfferable()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bManually
	end

	local group = UI:GetQuestGroup( questId )

	if group == -1 then
		sys.log( "UI:IsQuestManuallyOfferable()[ERROR]: no group for quest %d", questId )
		return bManually
	end

	bManually = UI:IsQuestGroupManuallyOfferable( group )

	return bManually

end


--
function UI:IsQuestGroupManuallyOfferable( group )

	local bManually = false

	if type( group ) ~= "number" then
		sys.log( "UI:IsQuestGroupManuallyOfferable()[ERROR]: invalid type of the 1-st parameter (\"group\"); \"number\" expected, got \"%s\"", type( group ) )
		return bManually
	end

	local groupInfo = _G.QuestGroups and _G.QuestGroups[ group ]

	if type( groupInfo ) ~= "table" then
		sys.log( "UI:IsQuestGroupManuallyOfferable()[ERROR]: invalid type of _G.QuestGroups[%d]; \"table\" expected, got \"%s\"", group, type( groupInfo ) )
		return bManually
	end

	if groupInfo.manual_offer == nil then
		return bManually
	end

	if type( groupInfo.manual_offer ) == "boolean" then
		bManually = groupInfo.manual_offer
	else
		sys.log( "UI:IsQuestGroupManuallyOfferable()[ERROR]: invalid type of the _G.QuestGroups[%d].manual_offer; \"number\" or \"nil\" expected, got \"%s\"", group, type( groupInfo.manual_offer ) )
	end

	return bManually

end


