local l_GetQuestState_guard = false
--
function UI:GetQuestState( questId, additionalData )

	-- если bVisible == false, то всем остальным полям не присваиваются валидные значения

	local state =
	{
		bVisible	= false,
		bTaken		= false,
		bCompleted	= false,
		bCanBeTaken	= false,
	}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestState()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return state
	end

	if additionalData ~= nil then
    	if type( additionalData ) ~= "table" then
    		sys.log( "UI:GetQuestState()[ERROR]: invalid type of the 2-nd parameter (\"additionalData\"); \"table\" or \"nil\" expected, got \"%s\"", type( additionalData ) )
    		return state
    	end
	end

	local fitCharacters				= {}
	local questsByGroup				= {}
	local bCustomEvent				= false
	local bWasInMajorTeam			= false

	if additionalData then

		fitCharacters				= additionalData.fitCharacters
    	questsByGroup				= additionalData.questsByGroup
    	bCustomEvent				= additionalData.bCustomEvent
		bWasInMajorTeam				= additionalData.bWasInMajorTeam

	else

    	local hangarRace = UI:GetCurSpaceStationRace()
    	local allCharacters = UI:GetAllQuestCharacters()

    	for idx, character in pairs( allCharacters ) do

    		local characterRace = UI:GetQuestCharacterRace( character )

    		if characterRace == -1 or characterRace == hangarRace then
    			fitCharacters[ character ] = true
    		end

    	end

        for _questId, questInfo in pairs( _G.Quests ) do

    		local group = UI:GetQuestGroup( _questId )
    		if group ~= -1 then

    			if not questsByGroup[ group ] then
    				questsByGroup[ group ] = {}
    			end

    			table.insert( questsByGroup[ group ], _questId )

    		end

    	end

    	bCustomEvent			= _G.MasterServer_IsEventCustomEvent()
		bWasInMajorTeam			= _G.MasterServer_IsInMajorLeague()	-- достигал ли игрок когда-либо "первой лиги", это не равнозначно MasterServer_GetLeagueTeam().major, в котором текущее состояние

	end

	local character		= UI:GetQuestCharacter( questId )
	local bRecurrent	= UI:IsQuestRecurrent( questId )
	local bInterval		= UI:IsQuestInterval( questId )
	local bTaken		= UI:IsQuestTaken( questId )

	local bCompleted = false
	if bRecurrent or bInterval then
		bCompleted = not bTaken and UI:GetQuestNumCompletions( questId ) >= UI:GetQuestMaxCompletions( questId )
	else
		bCompleted = UI:IsQuestCompleted( questId )
	end

	local bCanBeTaken = false

	if not bTaken then

    	if bRecurrent then

    		if UI:IsQuestManuallyOfferable( questId ) then
				local groupId = UI:GetQuestGroup( questId )
    			bCanBeTaken = UI:GetQuestGroupCooldown( groupId ) <= 0 and not UI:HasGroupActiveQuest( groupId )
    		else
    			bCanBeTaken = UI.serverData.offeredQuestsById[ questId ] ~= nil
    		end

    	else
    		bCanBeTaken = not bCompleted
    	end

	end

	-- #0075194 - если в группе нет ни одного взятого или готового к взятию квеста,
	-- то показывается на кулдауне последний завершенный квест из этой группы

	if not l_GetQuestState_guard then

    	if bRecurrent and not UI:IsQuestManuallyOfferable( questId ) then

    		if not bTaken and not bCanBeTaken then

        		local group = UI:GetQuestGroup( questId )
    			if group ~= -1 then

    				if _G.MasterServer_GetLastCompletedQuestInGroup( group ) == questId then

    					local bIsActiveQuestInGroup = false

    					if questsByGroup[ group ] then

    						for idx, groupQuestId in pairs( questsByGroup[ group ] ) do

								l_GetQuestState_guard = true
    							local groupQuestState = UI:GetQuestState( groupQuestId, additionalData )
								l_GetQuestState_guard = false

    							if groupQuestState.bVisible then
									bIsActiveQuestInGroup = true
									break
								end

    						end

    					end

						if not bIsActiveQuestInGroup then
							bCompleted = true
						end

    				end

    			end

    		end

    	end

	end

	local bFit = true


	-- прописан персонаж?

	if character == "" then
		-- #0069217,комм.(0286529) - утверждается, что отсутствие прописанного персонажа - это законная ситуация
--		sys.log( "UI:GetQuestState()[ERROR]: cannot find character for quest %d", questId )
		bFit = false
	end


 	-- подходит раса персонажа?

 	if bFit then
		if not fitCharacters[ character ] then
			bFit = false
		end
 	end


	-- "автоматические" квесты не показываются

	if bFit then
		if UI:IsQuestAuto( questId ) then
			bFit = false
		end
	end


	-- не показываются невзятые и незавершенные одноразовые квесты, для которых не выполнены предшествующие в цепочке квесты

	if bFit then

		if not bRecurrent then
			if not bTaken and not bCompleted and not UI:IsTutotialQuestPrevCompleted( questId ) then
				bFit = false
			end
		end

	end


	-- является ли квест специфическим для какого-то ивента?

	if bFit then

		local questTag = UI:GetQuestTag( questId )

		if questTag == ai.QuestTag.CUSTOM_EVENT then

			if bCustomEvent then
				if not bTaken and not bCompleted and not UI:IsCustomEventQuestAvailableByDay( questId ) then
					bFit = false
				end
			else
				bFit = false
			end

		end

	end


	-- подходит ранг?

	if bFit then
		if not bTaken and not bCompleted and not UI:IsQuestUnlockedByRank( questId ) then
			bFit = false
		end
	end


	-- у игрока есть корабль, наличие которого делает квест недоступным для взятия

	if bFit then

		local shipDefName = UI:GetQuestLockingShip( questId )

		if shipDefName ~= "" then
			if not bTaken and not bCompleted and UI:GetShipItemByDef( shipDefName, true ) ~= nil then
				bFit = false
			end
		end

	end


	-- дополнительные правила для многоразовых квестов

	if bFit then

		if bRecurrent then

			-- если квесты из группы выбираются вручную, то они показываются все - #0061638,комм.(0251997);
			-- ( #0062077, комм.(0253016) меняли эту логику, но в #0074032 снова вернули)
			if not UI:IsQuestManuallyOfferable( questId ) then

				if not bTaken and not bCanBeTaken then

					-- #0075194 - если в группе нет ни одного взятого или готового к взятию квеста,
					-- то показывается на кулдауне последний завершенный квест из этой группы

					if not bCompleted then
						bFit = false
					end

				end

			end

		end

	end


	-- дополнительные правила для опенворлдовских квестов

	if bFit then

		if UI:IsQuestOpenWorld( questId ) then

			-- есть доступ в опенворлд?
			if not _G.MasterServer_HasFreeSpaceAccess() then
				bFit = false
			end

		end

	end


	-- квест задисэйблен дизайнерами?

	if bFit then
		if UI:IsQuestDisabled( questId ) then
			bFit = false
		end
	end


	-- взять квест для "первой лиги" можно только если игрок когда-либо достигал ее (#0060294,комм.(0262106))

	if bFit then

		if	UI:IsQuestForMajorTeamOnly( questId )
			and not bWasInMajorTeam
			and not bTaken
			and not bCompleted then
				bFit = false
		end

	end

	-- для интервальных квестов - неподходящее время (не показываются даже взятые квесты - #0087726)

	if bFit then
		if bInterval and UI.serverData.intervalQuestsById[ questId ] == nil then
			bFit = false
		end
	end

	-- для квеста требуется, чтобы была активна в расписании определенная пве-карта

	if bFit then

		local requiredLevelName = UI:GetQuestRequiredPveScheduledLevel( questId )
		if requiredLevelName ~= "" then

			local bIsInSchedule = false

			local scheduledLevelNames = _G.MasterServer_GetPveScheduledLevels()
			for levelIdx, levelName in pairs( scheduledLevelNames ) do
				if levelName == requiredLevelName then
					bIsInSchedule = true
					break
				end
			end

			if not bIsInSchedule then
				bFit = false
			end

		end

	end

	-- ок, квест можно показать

	if bFit then

		state.bVisible		= true
		state.bTaken		= bTaken
		state.bCompleted	= bCompleted
		state.bCanBeTaken	= bCanBeTaken

	end

	return state

end


--
function UI:IsQuestForMajorTeamOnly( questId )

	local bForMajor = false

	if type( questId ) ~= "number" then
		sys.log( "UI:IsQuestForMajorTeamOnly()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bForMajor
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:IsQuestForMajorTeamOnly()[ERROR]: cannot find quest info for quest %d", questId )
		return bForMajor
	end

	if questInfo.for_major_league ~= nil then

		if type( questInfo.for_major_league ) == "boolean" then
			bForMajor = questInfo.for_major_league
		else
			sys.log( "UI:IsQuestForMajorTeamOnly()[ERROR]: invalid type of the _G.Quests[%d].for_major_league; \"boolean\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.for_major_league ) )
		end

	end

	return bForMajor

end


--
function UI:GetQuestCategory( questId )

	local category = -1

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestCategory()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return category
	end

	local questInfo = UI:GetQuestInfo( questId )
	if not questInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestCategory()[ERROR]: cannot find quest info for quest %d", questId )
		return category
	end

	if questInfo.category ~= nil then
    	if type( questInfo.category ) == "number" then
    		category = questInfo.category
    	else
    		sys.log( "UI:GetQuestCategory()[ERROR]: invalid type of the _G.Quests[%d].category; \"number\" or \"nil\" expected, got \"%s\"", questId, type( questInfo.category ) )
    	end
	end

	return category

end


--
function UI:QuestCategory2Str( category )

	local str = "unknown"

	if type( category ) ~= "number" then
		sys.log( "UI:QuestCategory2Str()[ERROR]: invalid type of the 1-st parameter (\"category\"); \"number\" expected, got \"%s\"", type( category ) )
		return str
	end

	local categoryName = UI:Val2Key( _G.QuestCategory, category )

	if category == _G.QuestCategory.ADVENTURE then
		str = UI:GetStringByName( "adventure_name" )
	else
		str = UI:GetStringByName( string.format( "questCategory_name_%s", categoryName ) )
	end

	return str

end



--
function UI:GetIntervalQuestDisableTime( questId )

	local disableTime = UI.INVALID_U64_ID

	if type( questId ) ~= "number" then
		sys.log( "UI:GetIntervalQuestDisableTime()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return disableTime
	end

	if not UI:IsQuestInterval( questId ) then
		sys.log( "UI:GetIntervalQuestDisableTime()[ERROR]: quest %d is not interval", questId )
		return disableTime
	end

	if UI.serverData.intervalQuestsById[ questId ] then
		if type( UI.serverData.intervalQuestsById[ questId ].timeDisable ) == "userdata" then
			disableTime = UI.serverData.intervalQuestsById[ questId ].timeDisable
		else
			sys.log( "UI:GetIntervalQuestDisableTime()[ERROR]: invalid type of field \"timeDisable\"; \"userdata\" expected, got \"%s\"", type( UI.serverData.intervalQuestsById[ questId ].timeDisable ) )
		end
	else
		sys.log( "UI:GetIntervalQuestDisableTime()[ERROR]: quest %d is not enabled", questId )
	end

	return disableTime

end


