--
function UI:GetQuestUnlimPveMinMissionLevel( questId )

	local minLevel = -1

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestUnlimPveMinMissionLevel()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return minLevel
	end

	local stage = UI:GetQuestStage( questId )

	local stageInfo = UI:GetQuestStageInfo( questId, stage )
	if not stageInfo then
		sys.log( "UI:GetQuestUnlimPveMinMissionLevel()[ERROR]: cannot find stage info for quest %d stage %d", questId, stage )
		return minLevel
	end

	if stageInfo.restrictions == nil then
		return minLevel
	end

	if type( stageInfo.restrictions ) ~= "table" then
		sys.log( "UI:GetQuestUnlimPveMinMissionLevel()[ERROR]: invalid type of the \"_G.Quests[%d].stages[%d].restrictions\"; \"table\" or \"nil\" expected, got \"%s\"", questId, stage, type( stageInfo.restrictions ) )
		return minLevel
	end

	for restrictionIdx, restriction in pairs( stageInfo.restrictions ) do

		if restriction.param == ai.GameEventParam.UNLIM_PVE_MISSION_LEVEL then

			if type( restriction.min_value ) == "number" then
				minLevel = restriction.min_value
			else
				sys.log( "UI:GetQuestUnlimPveMinMissionLevel()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d].min_value\"; \"number\" expected, got \"%s\"", questId, restrictionIdx, type( restriction.min_value ) )
			end

			break

		end

	end

	return minLevel

end


