--
function UI:GetCurSpaceStationRace()

	local race = -1

	local zoneId = _G.MasterServer_GetSpaceStationZoneId()
	if zoneId == 0 then
		return race
	end

	local zoneDesc = _G.SpaceZoneById and _G.SpaceZoneById[ zoneId ]

	if zoneDesc ~= nil then
		if type( zoneDesc ) ~= "table" then
			sys.log( "UI:GetCurSpaceStationRace()[ERROR]: invalid type of the _G.SpaceZoneById[%d]; \"table\" expected, got \"%s\"", zoneId, type( zoneDesc ) )
			zoneDesc = nil
		end
	else
		sys.log( "UI:GetCurSpaceStationRace()[ERROR]: cannot find _G.SpaceZoneById[%d]", zoneId )
	end

	if not zoneDesc then
		return race
	end

	local bHasZoneSpaceStation = false

	if zoneDesc.space_station ~= nil then
		if type( zoneDesc.space_station ) == "boolean" then
			bHasZoneSpaceStation = zoneDesc.space_station
		else
			sys.log( "UI:GetCurSpaceStationRace()[ERROR]: invalid type of the _G.SpaceZoneById[%d].space_station; \"boolean\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneDesc.space_station ) )
		end
	end

	if not bHasZoneSpaceStation then
		sys.log( "UI:GetCurSpaceStationRace()[ERROR]: current zone %d don't have a space station", zoneId )
		return race
	end

	if type( zoneDesc.station_race ) == "number" then

		if UI:Val2Key( ai.Race, zoneDesc.station_race ) ~= "" then

			if zoneDesc.station_race ~= ai.Race.NUM then
				race = zoneDesc.station_race
			else
				sys.log( "UI:GetCurSpaceStationRace()[ERROR]: ai.Race.NUM in _G.SpaceZoneById[%d].station_race", zoneId )
			end

		else
			sys.log( "UI:GetCurSpaceStationRace()[ERROR]: invalid race %d in _G.SpaceZoneById[%d].station_race", zoneDesc.station_race, zoneId )
		end

	else
		sys.log( "UI:GetCurSpaceStationRace()[ERROR]: invalid type of the _G.SpaceZoneById[%d].station_race; \"number\" expected, got \"%s\"", zoneId, type( zoneDesc.station_race ) )
	end

	return race

end


--
function UI:IsZoneSpaceStation( zoneId )

	local bSpaceStation = false

	if type( zoneId ) ~= "number" then
		sys.log( "UI:IsZoneSpaceStation()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
