--
function UI:GetSpaceStationForRace( race )

	local zoneId = -1

	if type( race ) ~= "number" then
		sys.log( "UI:GetSpaceStationForRace()[ERROR]: invalid type of the 1-st parameter (\"%s\"); \"number\" expected, got \"%s\"", type( race ) )
		return zoneId
	end

	if UI:Val2Key( ai.Race, race ) == "" or race == ai.Race.NUM then
		sys.log( "UI:GetSpaceStationForRace()[ERROR]: invalid race %d", race )
		return zoneId
	end

	if not _G.SpaceZone then
		return zoneId
	end

	for zoneName, zoneDesc in pairs( _G.SpaceZone ) do

    	local bHasZoneSpaceStation = false

    	if zoneDesc.space_station ~= nil then
    		if type( zoneDesc.space_station ) == "boolean" then
    			bHasZoneSpaceStation = zoneDesc.space_station
    		else
    			sys.log( "UI:GetSpaceStationForRace()[ERROR]: invalid type of the _G.SpaceZoneById[%d].space_station; \"boolean\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneDesc.space_station ) )
    		end
    	end

    	if bHasZoneSpaceStation then

        	if type( zoneDesc.station_race ) == "number" then

				if zoneDesc.station_race == race then

					if type( zoneDesc.zone_id ) == "number" then
						zoneId = zoneDesc.zone_id
					else
		        		sys.log( "UI:GetSpaceStationForRace()[ERROR]: invalid type of the _G.SpaceZoneById[%d].zone_id; \"number\" expected, got \"%s\"", zoneId, type( zoneDesc.zone_id ) )
					end

					break

				end

        	else
        		sys.log( "UI:GetSpaceStationForRace()[ERROR]: invalid type of the _G.SpaceZoneById[%d].station_race; \"number\" expected, got \"%s\"", zoneId, type( zoneDesc.station_race ) )
        	end

    	end

	end

	return zoneId

end


