--
function UI:UpdateServerData_OnChangeIntervalQuests()

	UI:UpdateQuestsData()

end


--
function UI:UpdateQuestsData()

	if not UI.serverData.bQuestsInited then
		sys.log( "UI:UpdateQuestsData()[ERROR]: quests are not inited" )
		UI.serverData.bQuestsInited = true
	end

	self.serverData.activeQuests	= _G.MasterServer_GetActiveQuests()
	self.serverData.completedQuests	= _G.MasterServer_GetCompletedQuests()
	self.serverData.offeredQuests	= _G.MasterServer_GetOfferedQuests()
	self.serverData.intervalQuests	= _G.MasterServer_GetIntervalQuests()

	self.serverData.activeQuestsById	= {}
	self.serverData.completedQuestsById	= {}
	self.serverData.offeredQuestsById	= {}
	self.serverData.intervalQuestsById	= {}

	for idx, info in pairs( self.serverData.activeQuests ) do
		self.serverData.activeQuestsById[ info.id ] = info
	end

	for idx, questId in pairs( self.serverData.completedQuests ) do
		self.serverData.completedQuestsById[ questId ] = true
	end

	for idx, questInfo in pairs( self.serverData.offeredQuests ) do
		self.serverData.offeredQuestsById[ questInfo.id ] = questInfo
	end

	for idx, questInfo in pairs( self.serverData.intervalQuests ) do
		self.serverData.intervalQuestsById[ questInfo.questId ] = questInfo
	end

end


--
function UI:UpdateAdventuresData()

	if not UI.serverData.bAdventuresInited then
		sys.log( "UI:UpdateAdventuresData()[ERROR]: adventures are not inited" )
		UI.serverData.bAdventuresInited = true
	end

	self.serverData.activeAdventures = _G.MasterServer_GetActiveAdventures()

	self.serverData.activeAdventuresByAiid = {}

	for idx, info in pairs( self.serverData.activeAdventures ) do

		if not self.serverData.activeAdventuresByAiid[ info.aiid.h ] then
			self.serverData.activeAdventuresByAiid[ info.aiid.h ] = {}
		end

		self.serverData.activeAdventuresByAiid[ info.aiid.h ][ info.aiid.l ] = info

	end

end

