function UI:IsSteam()

	return UI.serverData.playerCredentials.localSteamID ~= nil and UI.serverData.playerCredentials.localSteamID ~= UI.INVALID_U64_ID

end


--
function UI:GetLetterAttachments( letter )

	local attachments = {}

	if type( letter ) ~= "table" then
		sys.log( "UI:GetLetterAttachments()[ERROR]: invalid type of the first param (\"letter\" ); \"table\" expected, got \"%s\"", type( letter ) )
		return attachments
	end

	if type( letter.attachments ) ~= "table" then
		sys.log( "UI:GetLetterAttachments()[ERROR]: invalid type of \"attachments\"; \"table\" expected, got \"%s\"", type( letter.attachments ) )
		return attachments
	end

	for key, attachment in pairs( letter.attachments ) do

		local attachmentTpye = UI:GetMailAttachmentType( attachment )
		if attachmentTpye ~= -1 then
			table.insert( attachments, attachment )
		end

	end

	UI:SortMailAttachments( attachments )

	return attachments

end


--
function UI:GetMailAttachmentType( attachment )

	local mailType = -1

	if type( attachment ) ~= "table" then
		sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of the 1-st parameter (\"attachment\"); \"table\" expected, got \"%s\"", type( attachment ) )
		return mailType
	end

	if type( attachment.type ) ~= "number" then
		sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of (\"attachment.type\"); \"number\" expected, got \"%s\"", type( attachment.type ) )
		return mailType
	end


	if attachment.type == _G.MasterServer.AttachmentType.LAT_INVALID then
		-- invalid type


	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_GAME_MESSAGE then
		-- invalid type


	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_MESSAGE then
		-- invalid type


	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_CREDITS then

		if type( attachment.content ) == "table" then

        	local credits		= attachment.content.credits
        	local gold			= attachment.content.goldCredits
			local tokens		= attachment.content.tokenCredits	-- #0036033 - токены могут лежать здесь, а могут и в аттачменте типа LAT_TOKENS
			local eventCredits	= attachment.content.eventCredits

    		if credits ~= nil then
				if type( credits ) ~= "number" then
					sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of \"attachment.content.credits\"; \"number\" or \"nil\" expected, got \"%s\"", type( credits ) )
					credits = nil
				end
			end

			if credits == nil then
				credits = 0
			end

    		if gold ~= nil then
				if type( gold ) ~= "number" then
					sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of \"attachment.content.goldCredits\"; \"number\" or \"nil\" expected, got \"%s\"", type( gold ) )
					gold = nil
				end
			end

			if gold == nil then
				gold = 0
			end

    		if tokens ~= nil then
				if type( tokens ) ~= "number" then
					sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of \"attachment.content.tokenCredits\"; \"number\" \"nil\" expected, got \"%s\"", type( tokens ) )
					tokens = nil
				end
			end

			if tokens == nil then
				tokens = 0
			end

    		if eventCredits ~= nil then
				if type( eventCredits ) ~= "number" then
					sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of \"attachment.content.eventCredits\"; \"number\" \"nil\" expected, got \"%s\"", type( eventCredits ) )
					eventCredits = nil
				end
			end

			if eventCredits == nil then
				eventCredits = 0
			end


			local numVals = 0

			if credits ~= 0 then
				numVals = numVals + 1
			end

			if gold ~= 0 then
				numVals = numVals + 1
			end

			if tokens ~= 0 then
				numVals = numVals + 1
			end

			if eventCredits ~= 0 then
				numVals = numVals + 1
			end

			if numVals > 1 then
    			sys.log( "UI:GetMailAttachmentType()[ERROR]: more than one currency in attachment of type LAT_CREDITS" )

			elseif numVals == 0 then
    			sys.log( "UI:GetMailAttachmentType()[ERROR]: no currency in attachment of type LAT_CREDITS" )

			else
        		if credits ~= 0 then
    				mailType = UI.mailAttachmentTypes.CREDITS

        		elseif gold ~= 0 then
    				mailType = UI.mailAttachmentTypes.GOLD

        		elseif tokens ~= 0 then
    				mailType = UI.mailAttachmentTypes.TOKENS

        		elseif eventCredits ~= 0 then
    				mailType = UI.mailAttachmentTypes.EVENT_CREDITS
        		end
			end

		else
			sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of \"attachment.content\"; \"table\" expected, got \"%s\"", type( attachment.content ) )
		end


	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_LOYALTY_LEGACY then

		if type( attachment.content ) == "table" then

			-- сейчас репутация с расой не передается в этом типе аттачменте, и самого этого аттачмента уже нет
			-- Но могли, теоретически, сохраниться старые письма, поэтому не убирается

    		local race = attachment.content.race
    		if race ~= nil then

				if type( race ) == "number" then
					mailType = UI.mailAttachmentTypes.RACE_REP
				else
					sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of \"attachment.content.race\"; \"number\" expected, got \"%s\"", type( race ) )
				end

    		else
				mailType = UI.mailAttachmentTypes.LOYALTY_LEGACY
    		end

		else
			sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of \"attachment.content\"; \"table\" expected, got \"%s\"", type( attachment.content ) )
		end


	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_ITEM then
		mailType = UI.mailAttachmentTypes.ITEM

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_TOKENS then
		mailType = UI.mailAttachmentTypes.TOKENS	-- #0036033 - токены могут лежать здесь, а могут и в аттачменте типа LAT_CREDITS

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_VESSEL_EXP_POOL then
		mailType = UI.mailAttachmentTypes.SYNERGY_FREE

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_VESSEL_EXP then
		mailType = UI.mailAttachmentTypes.SYNERGY_SHIP

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_PREMIUM then
		mailType = UI.mailAttachmentTypes.PREMIUM

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_TITLE then
		mailType = UI.mailAttachmentTypes.TITLE

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_TALENT_SET then
		mailType = UI.mailAttachmentTypes.TALENT_SET

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_ACCOUNT_AURA then
		mailType = UI.mailAttachmentTypes.ACCOUNT_AURA

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_CUSTOM_ELEMENT then
		mailType = UI.mailAttachmentTypes.CUSTOM_ELEMENT

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_AVATAR then
		mailType = UI.mailAttachmentTypes.AVATAR

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_MOTTO then
		mailType = UI.mailAttachmentTypes.MOTTO

	elseif attachment.type == _G.MasterServer.AttachmentType.LAT_AUTOGEN then
		mailType = UI.mailAttachmentTypes.AUTOGEN

	else
		sys.log( "UI:GetMailAttachmentType()[ERROR]: unhandled attachment type: %d", attachment.type )
	end

	return mailType

end


--
function UI:SortMailAttachments( attachments )

	if type( attachments ) ~= "table" then
		sys.log( "UI:GetMailAttachmentType()[ERROR]: invalid type of the 1-st parameter (\"attachments\"); \"table\" expected, got \"%s\"", type( attachments ) )
		return
	end

	local function fnSort( attach1, attach2 )

		local type1 = UI:GetMailAttachmentType( attach1 )
		local type2 = UI:GetMailAttachmentType( attach2 )

		-- 1. премиум

		if type1 == UI.mailAttachmentTypes.PREMIUM and type2 ~= UI.mailAttachmentTypes.PREMIUM then
			return true

		elseif type2 == UI.mailAttachmentTypes.PREMIUM and type1 ~= UI.mailAttachmentTypes.PREMIUM then
			return false

		elseif type1 == UI.mailAttachmentTypes.PREMIUM and type2 == UI.mailAttachmentTypes.PREMIUM then

			-- 1.1. среди премиума - сортировка по времени

			local time1 = UI:GetMailAttachmentPremiumTime( attach1 )
			local time2 = UI:GetMailAttachmentPremiumTime( attach2 )

			return time1 > time2

		end

		-- 2. репутация c расой

		if type1 == UI.mailAttachmentTypes.RACE_REP and type2 ~= UI.mailAttachmentTypes.RACE_REP then
			return true

		elseif type2 == UI.mailAttachmentTypes.RACE_REP and type1 ~= UI.mailAttachmentTypes.RACE_REP then
			return false

		elseif type1 == UI.mailAttachmentTypes.RACE_REP and type2 == UI.mailAttachmentTypes.RACE_REP then

			-- 2.1. среди репутации - сортировка по расе

			local race1 = UI:GetMailAttachmentRace( attach1 )
			local race2 = UI:GetMailAttachmentRace( attach2 )

			if race1 ~= race2 then
				return race1 < race2

			else
				-- 2.2. среди репутации с одной расой - сортировка по количеству репутации

				local raceRep1 = UI:GetMailAttachmentRaceRep( attach1 )
				local raceRep2 = UI:GetMailAttachmentRaceRep( attach2 )

				return raceRep1 > raceRep2
			end

		end


		-- 3. лояльность

		if type1 == UI.mailAttachmentTypes.LOYALTY_LEGACY and type2 ~= UI.mailAttachmentTypes.LOYALTY_LEGACY then
			return true

		elseif type2 == UI.mailAttachmentTypes.LOYALTY_LEGACY and type1 ~= UI.mailAttachmentTypes.LOYALTY_LEGACY then
			return false

		elseif type1 == UI.mailAttachmentTypes.LOYALTY_LEGACY and type2 == UI.mailAttachmentTypes.LOYALTY_LEGACY then

			-- 3.1. среди лояльности - сортировка по количеству

			local loyalty1 = UI:GetMailAttachmentLoyalty( attach1 )
			local loyalty2 = UI:GetMailAttachmentLoyalty( attach2 )

			return loyalty1 > loyalty2

		end


		-- 4. золото

		if type1 == UI.mailAttachmentTypes.GOLD and type2 ~= UI.mailAttachmentTypes.GOLD then
			return true

		elseif type2 == UI.mailAttachmentTypes.GOLD and type1 ~= UI.mailAttachmentTypes.GOLD then
			return false

		elseif type1 == UI.mailAttachmentTypes.GOLD and type2 == UI.mailAttachmentTypes.GOLD then

			-- 4.1. среди золота - сортировка по количеству

			local gold1 = UI:GetMailAttachmentGold( attach1 )
			local gold2 = UI:GetMailAttachmentGold( attach2 )

			return gold1 > gold2

		end


		-- 5. кредиты

		if type1 == UI.mailAttachmentTypes.CREDITS and type2 ~= UI.mailAttachmentTypes.CREDITS then
			return true

		elseif type2 == UI.mailAttachmentTypes.CREDITS and type1 ~= UI.mailAttachmentTypes.CREDITS then
			return false

		elseif type1 == UI.mailAttachmentTypes.CREDITS and type2 == UI.mailAttachmentTypes.CREDITS then

			-- 5.1. среди кредитов - сортировка по количеству

			local credits1 = UI:GetMailAttachmentCredits( attach1 )
			local credits2 = UI:GetMailAttachmentCredits( attach2 )

			return credits1 > credits2

		end


		-- 6. токены

		if type1 == UI.mailAttachmentTypes.TOKENS and type2 ~= UI.mailAttachmentTypes.TOKENS then
			return true

		elseif type2 == UI.mailAttachmentTypes.TOKENS and type1 ~= UI.mailAttachmentTypes.TOKENS then
			return false

		elseif type1 == UI.mailAttachmentTypes.TOKENS and type2 == UI.mailAttachmentTypes.TOKENS then

			-- 6.1. среди токенов - сортировка по количеству

			local tokens1 = UI:GetMailAttachmentTokens( attach1 )
			local tokens2 = UI:GetMailAttachmentTokens( attach2 )

			return tokens1 > tokens2

		end


		--7. свободная синергия

		if type1 == UI.mailAttachmentTypes.SYNERGY_FREE and type2 ~= UI.mailAttachmentTypes.SYNERGY_FREE then
			return true

		elseif type2 == UI.mailAttachmentTypes.SYNERGY_FREE and type1 ~= UI.mailAttachmentTypes.SYNERGY_FREE then
			return false

		elseif type1 == UI.mailAttachmentTypes.SYNERGY_FREE and type2 == UI.mailAttachmentTypes.SYNERGY_FREE then

			-- 7.1. среди синергии - сортировка по времени

			local val1 = UI:GetMailAttachmentSynergyFree( attach1 )
			local val2 = UI:GetMailAttachmentSynergyFree( attach2 )

			return val1 > val2

		end


		-- 8. синергия на корабль

		if type1 == UI.mailAttachmentTypes.SYNERGY_SHIP and type2 ~= UI.mailAttachmentTypes.SYNERGY_SHIP then
			return true

		elseif type2 == UI.mailAttachmentTypes.SYNERGY_SHIP and type1 ~= UI.mailAttachmentTypes.SYNERGY_SHIP then
			return false

		elseif type1 == UI.mailAttachmentTypes.SYNERGY_SHIP and type2 == UI.mailAttachmentTypes.SYNERGY_SHIP then

			-- 8.1. среди синергии - сортировка по времени

			local val1 = UI:GetMailAttachmentSynergyShip( attach1 )
			local val2 = UI:GetMailAttachmentSynergyShip( attach2 )

			return val1 > val2

		end


		-- 9. предметы

		if type1 == UI.mailAttachmentTypes.ITEM and type2 ~= UI.mailAttachmentTypes.ITEM then
			return true

		elseif type2 == UI.mailAttachmentTypes.ITEM and type1 ~= UI.mailAttachmentTypes.ITEM then
			return false

		elseif type2 == UI.mailAttachmentTypes.ITEM and type1 == UI.mailAttachmentTypes.ITEM then

			-- 9.1. среди предметов - сортировка по алфавиту

			local defName1 = UI:GetMailAttachmentItemDefName( attach1 )
			local defName2 = UI:GetMailAttachmentItemDefName( attach2 )

			local localizedName1 = UI:GetEntityLocalizedNameByDef( defName1, false, nil, false )
			local localizedName2 = UI:GetEntityLocalizedNameByDef( defName2, false, nil, false )

			if localizedName1 ~= localizedName2 then
				return localizedName1 < localizedName2

			else

				-- 9.2. среди предметов c одним дефинишеном - сортировка по количеству

				local count1 = UI:GetMailAttachmentItemCount( attach1 )
				local count2 = UI:GetMailAttachmentItemCount( attach2 )

				return count1 > count2

			end

		end


		-- 10. звания

		if type1 == UI.mailAttachmentTypes.TITLE and type2 ~= UI.mailAttachmentTypes.TITLE then
			return true

		elseif type2 == UI.mailAttachmentTypes.TITLE and type1 ~= UI.mailAttachmentTypes.TITLE then
			return false

		elseif type1 == UI.mailAttachmentTypes.TITLE and type2 == UI.mailAttachmentTypes.TITLE then

			-- 10.1. среди званий - сортировка по id

			local title1 = UI:GetMailAttachmentTitle( attach1 )
			local title2 = UI:GetMailAttachmentTitle( attach2 )

			return title1 < title2

		end


		-- 11. сеты талантов

		if type1 == UI.mailAttachmentTypes.TALENT_SET and type2 ~= UI.mailAttachmentTypes.TALENT_SET then
			return true

		elseif type2 == UI.mailAttachmentTypes.TALENT_SET and type1 ~= UI.mailAttachmentTypes.TALENT_SET then
			return false

		elseif type1 == UI.mailAttachmentTypes.TALENT_SET and type2 == UI.mailAttachmentTypes.TALENT_SET then

			-- 11.1. среди сетов - сортировка по id

			local talentSetId1 = UI:GetMailAttachmentTalentSet( attach1 )
			local talentSetId2 = UI:GetMailAttachmentTalentSet( attach2 )

			return talentSetId1 < talentSetId2

		end


		-- 12. аккаунт-ауры

		if type1 == UI.mailAttachmentTypes.ACCOUNT_AURA and type2 ~= UI.mailAttachmentTypes.ACCOUNT_AURA then
			return true

		elseif type2 == UI.mailAttachmentTypes.ACCOUNT_AURA and type1 ~= UI.mailAttachmentTypes.ACCOUNT_AURA then
			return false

		elseif type1 == UI.mailAttachmentTypes.ACCOUNT_AURA and type2 == UI.mailAttachmentTypes.ACCOUNT_AURA then

			-- 12.1. среди аур - сортировка по дефу

			local defName1 = UI:GetMailAttachmentAccountAura( attach1 )
			local defName2 = UI:GetMailAttachmentAccountAura( attach2 )

			return defName1 < defName2

		end


		-- 13. ивентовые кредиты

		if type1 == UI.mailAttachmentTypes.EVENT_CREDITS and type2 ~= UI.mailAttachmentTypes.EVENT_CREDITS then
			return true

		elseif type2 == UI.mailAttachmentTypes.EVENT_CREDITS and type1 ~= UI.mailAttachmentTypes.EVENT_CREDITS then
			return false

		elseif type1 == UI.mailAttachmentTypes.EVENT_CREDITS and type2 == UI.mailAttachmentTypes.EVENT_CREDITS then

			-- 13.1. среди ивентовых кредитов - сортировка по количеству

			local eventCredits1	= UI:GetMailAttachmentEventCredits( attach1 )
			local eventCredits2	= UI:GetMailAttachmentEventCredits( attach2 )

			return eventCredits1 > eventCredits2

		end


		-- 14. кастомизация корабля

		if type1 == UI.mailAttachmentTypes.CUSTOM_ELEMENT and type2 ~= UI.mailAttachmentTypes.CUSTOM_ELEMENT then
			return true

		elseif type2 == UI.mailAttachmentTypes.CUSTOM_ELEMENT and type1 ~= UI.mailAttachmentTypes.CUSTOM_ELEMENT then
			return false

		elseif type1 == UI.mailAttachmentTypes.CUSTOM_ELEMENT and type2 == UI.mailAttachmentTypes.CUSTOM_ELEMENT then

			-- 14.1. среди кастомизации корабля - сортировка по имени

			local customElement1	= UI:GetMailAttachmentCustomElement( attach1 )
			local customElement2	= UI:GetMailAttachmentCustomElement( attach2 )

			return customElement1 < customElement2

		end


		-- 15. аватар

		if type1 == UI.mailAttachmentTypes.AVATAR and type2 ~= UI.mailAttachmentTypes.AVATAR then
			return true

		elseif type2 == UI.mailAttachmentTypes.AVATAR and type1 ~= UI.mailAttachmentTypes.AVATAR then
			return false

		elseif type1 == UI.mailAttachmentTypes.AVATAR and type2 == UI.mailAttachmentTypes.AVATAR then

			-- 15.1. среди аватаров - сортировка по имени

			local avatar1	= UI:GetMailAttachmentAvatar( attach1 )
			local avatar2	= UI:GetMailAttachmentAvatar( attach2 )

			return avatar1 < avatar1

		end


		-- 15. девиз

		if type1 == UI.mailAttachmentTypes.MOTTO and type2 ~= UI.mailAttachmentTypes.MOTTO then
			return true

		elseif type2 == UI.mailAttachmentTypes.MOTTO and type1 ~= UI.mailAttachmentTypes.MOTTO then
			return false

		elseif type1 == UI.mailAttachmentTypes.MOTTO and type2 == UI.mailAttachmentTypes.MOTTO then

			-- 16.1. среди аватаров - сортировка по имени

			local motto1	= UI:GetMailAttachmentMotto( attach1 )
			local motto2	= UI:GetMailAttachmentMotto( attach2 )

			return motto1 < motto2

		end


		-- 16. автогены

		if type1 == UI.mailAttachmentTypes.AUTOGEN and type2 ~= UI.mailAttachmentTypes.AUTOGEN then
			return true

		elseif type2 == UI.mailAttachmentTypes.AUTOGEN and type1 ~= UI.mailAttachmentTypes.AUTOGEN then
			return false

		elseif type2 == UI.mailAttachmentTypes.AUTOGEN and type1 == UI.mailAttachmentTypes.AUTOGEN then

			-- 16.1. среди предметов - сортировка по iid

			local autogenItem1 = UI:GetMailAttachmentAutogenItem( attach1 )
			local autogenItem2 = UI:GetMailAttachmentAutogenItem( attach2 )

			local iid1 = autogenItem1.iid or UI.INVALID_U64_ID
			local iid2 = autogenItem2.iid or UI.INVALID_U64_ID

			if iid1 ~= iid2 then
				return iid1 < iid2
			end

		end


		return false

	end

	table.sort( attachments, fnSort )

end


--
function UI:GetMailAttachmentRace( attachment )

	local race = -1

	local attachmentType = UI:GetMailAttachmentType( attachment )

	if attachmentType ~= UI.mailAttachmentTypes.RACE_REP then
		sys.log( "UI:GetMailAttachmentRace()[ERROR]: attachment is not of RACE_REP type" )
		return race
	end

	race = attachment.content.race

	return race

end


--
function UI:GetMailAttachmentRaceRep( attachment )

	local rep = 0

	local attachmentType = UI:GetMailAttachmentType( attachment )

	if attachmentType ~= UI.mailAttachmentTypes.RACE_REP then
		sys.log( "UI:GetMailAttachmentRaceRep()[ERROR]: attachment is not of RACE_REP type" )
		return rep
	end

	if type( attachment.content.reputation ) == "number" then
		rep = attachment.content.reputation
	else
		sys.log( "UI:GetMailAttachmentRaceRep()[ERROR]: invalid type of \"attachment.content.reputation\"; \"number\" expected, got \"%s\"", type( attachment.content.reputation ) )
	end

	return rep

end


