	if attachmentType ~= UI.mailAttachmentTypes.LOYALTY_LEGACY then
		sys.log( "UI:GetMailAttachmentLoyalty()[ERROR]: attachment is not of LOYALTY type" )
		return rep
	end

	if type( attachment.content.loyalty ) == "number" then
		rep = attachment.content.loyalty
	else
		sys.log( "UI:GetMailAttachmentLoyalty()[ERROR]: invalid type of \"attachment.content.loyalty\"; \"number\" expected, got \"%s\"", type( attachment.content.loyalty ) )
	end

	return rep

