--
function UI:GetMailAttachmentGold( attachment )

	local gold = 0

	local attachmentType = UI:GetMailAttachmentType( attachment )

	if attachmentType ~= UI.mailAttachmentTypes.GOLD then
		sys.log( "UI:GetMailAttachmentGold()[ERROR]: attachment is not of GOLD type" )
		return gold
	end

	gold = attachment.content.goldCredits

	return gold

end


--
function UI:GetMailAttachmentCredits( attachment )

	local credits = 0

	local attachmentType = UI:GetMailAttachmentType( attachment )

	if attachmentType ~= UI.mailAttachmentTypes.CREDITS then
		sys.log( "UI:GetMailAttachmentCredits()[ERROR]: attachment is not of CREDITS type" )
		return credits
	end

	credits = attachment.content.credits
	if credits < 0 then	-- передается 32-битное целое знаковое, если значение не влазит, то приходит с минусом; поэтому перевод его в положительное число
		credits = 4294967295 + credits + 1
	end

	return credits

end


