function UI:GetMailAttachmentItemEnchantedStatus( attachment )

	local bEnchanted = false

	local attachmentType = UI:GetMailAttachmentType( attachment )

	if attachmentType ~= UI.mailAttachmentTypes.ITEM then
		sys.log( "UI:GetMailAttachmentItemEnchantedStatus()[ERROR]: attachment is not of ITEM type" )
		return bEnchanted
	end

	if attachment.content.enchantments ~= nil then

    	if type( attachment.content.enchantments ) == "number" then
    		bEnchanted = attachment.content.enchantments > 0
    	else
    		sys.log( "UI:GetMailAttachmentItemEnchantedStatus()[ERROR]: invalid type of \"attachment.content.enchantments\"; \"number\" or \"nil\" expected, got \"%s\"", type( attachment.content.enchantments ) )
    	end

	end

	return bEnchanted

end


