function UI:GetMailAttachmentTitle( attachment )

	local titleId = -1

	local attachmentType = UI:GetMailAttachmentType( attachment )

	if attachmentType ~= UI.mailAttachmentTypes.TITLE then
		sys.log( "UI:GetMailAttachmentTitle()[ERROR]: attachment is not of TITLE type" )
		return titleId
	end

	if type( attachment.content.tid ) == "number" then

		titleId = attachment.content.tid

		if titleId <= 0 then
			sys.log( "UI:GetMailAttachmentTitle()[ERROR]: invalid title id %d", titleId )
			titleId = -1
		end

	else
		sys.log( "UI:GetMailAttachmentTitle()[ERROR]: invalid type of \"attachment.content.tid\"; \"number\" expected, got \"%s\"", type( attachment.content.tid ) )
	end

	return titleId

end


