--
function UI:MailAttachment2Str( attachment )

	local str = "error"

	local attachmentType = UI:GetMailAttachmentType( attachment )

	if attachmentType == UI.mailAttachmentTypes.ITEM then

		local defName = UI:GetMailAttachmentItemDefName( attachment )
		local count = UI:GetMailAttachmentItemCount( attachment )
		str = UI:MailAttachmentItem2Str( defName, count )

	elseif attachmentType == UI.mailAttachmentTypes.CREDITS then

		local credits = UI:GetMailAttachmentCredits( attachment )
		str = UI:MailAttachmentCredits2Str( credits )

	elseif attachmentType == UI.mailAttachmentTypes.GOLD then

		local gold = UI:GetMailAttachmentGold( attachment )
		str = UI:MailAttachmentGold2Str( gold )

	elseif attachmentType == UI.mailAttachmentTypes.LOYALTY_LEGACY then

		local rep = UI:GetMailAttachmentLoyalty( attachment )
		str = UI:MailAttachmentLoyalty2Str( rep )

	elseif attachmentType == UI.mailAttachmentTypes.RACE_REP then

		local race = UI:GetMailAttachmentRace( attachment )
		local rep = UI:GetMailAttachmentRaceRep( attachment )
		str = UI:MailAttachmentRaceRep2Str( race, rep )

	elseif attachmentType == UI.mailAttachmentTypes.TOKENS then

		local tokens = UI:GetMailAttachmentTokens( attachment )
		str = UI:MailAttachmentTokens2Str( tokens )

	elseif attachmentType == UI.mailAttachmentTypes.SYNERGY_FREE then

		local synergy = UI:GetMailAttachmentSynergyFree( attachment )
		str = UI:MailAttachmentSynergyFree2Str( synergy )

	elseif attachmentType == UI.mailAttachmentTypes.SYNERGY_SHIP then

		local synergy = UI:GetMailAttachmentSynergyShip( attachment )
		str = UI:MailAttachmentSynergyShip2Str( synergy )

	elseif attachmentType == UI.mailAttachmentTypes.PREMIUM then

		local time = UI:GetMailAttachmentPremiumTime( attachment )
		str = UI:MailAttachmentPremiumTime2Str( time )

	elseif attachmentType == UI.mailAttachmentTypes.TITLE then

		local titleId = UI:GetMailAttachmentTitle( attachment )
		str = UI:MailAttachmentTitle2Str( titleId )

	elseif attachmentType == UI.mailAttachmentTypes.TALENT_SET then

		local talentSetId = UI:GetMailAttachmentTalentSet( attachment )
		str = UI:MailAttachmentTalentSet2Str( talentSetId )

	elseif attachmentType == UI.mailAttachmentTypes.ACCOUNT_AURA then

		local defName = UI:GetMailAttachmentAccountAura( attachment )
		str = UI:MailAttachmentAccountAura2Str( defName )

	elseif attachmentType == UI.mailAttachmentTypes.EVENT_CREDITS then

		local eventCredits = UI:GetMailAttachmentEventCredits( attachment )
		str = UI:MailAttachmentEventCredits2Str( eventCredits )

	elseif attachmentType == UI.mailAttachmentTypes.CUSTOM_ELEMENT then

		local customElement = UI:GetMailAttachmentCustomElement( attachment )
		str = UI:MailAttachmentCustomElement2Str( customElement )

	elseif attachmentType == UI.mailAttachmentTypes.AVATAR then

		local avatar = UI:GetMailAttachmentAvatar( attachment )
		str = UI:MailAttachmentAvatar2Str( avatar )

	elseif attachmentType == UI.mailAttachmentTypes.MOTTO then

		local motto = UI:GetMailAttachmentMotto( attachment )
		str = UI:MailAttachmentMotto2Str( motto )

	elseif attachmentType == UI.mailAttachmentTypes.AUTOGEN then

 		local autogenItem = UI:GetMailAttachmentAutogenItem( attachment )
		str = UI:MailAttachmentAutogenItem2Str( autogenItem )

	else
		sys.log( "UI:MailAttachment2Str()[ERROR]: unhandled attachment type: %s", tostring( attachmentType ) )
	end

	return str

end


