--
function UI:GetLetterTheme( letter )

	local strTheme = "Unknown Theme"

	if type( letter ) ~= "table" then
		sys.log( "UI:GetLetterTheme()[ERROR]: invalid type of the first param (\"letter\" ); \"table\" expected, got \"%s\"", type( letter ) )
		return strTheme
	end

	local bThemeFound = false

	if type( letter.attachments ) == "table" then

    	for attachmentIdx, attachment in pairs( letter.attachments ) do

    		if attachment.type == _G.MasterServer.AttachmentType.LAT_GAME_MESSAGE then

            	if type( attachment.content ) == "table" then

    	        	if type( attachment.content.stringId ) == "string" then
    					local strId = string.format( "%s_theme", attachment.content.stringId )
    					strTheme = UI:GetStringByName( strId )
    					bThemeFound = true
    				else
    	        		sys.log( "UI:GetLetterTheme()[ERROR]: invalid type of \"attachments[%d].content.stringId\" in letter letter %s; \"string\" expected, got \"%s\"", attachmentIdx, _G.U64ToStr( letter.mailId ), type( attachment.content.stringId ) )
    				end

    			else
            		sys.log( "UI:GetLetterTheme()[ERROR]: invalid type of \"attachments[%d].content\" in letter %s; \"table\" expected, got \"%s\"", attachmentIdx, _G.U64ToStr( letter.mailId ), type( attachment.content ) )
            	end

    			break

    		elseif attachment.type == _G.MasterServer.AttachmentType.LAT_MESSAGE then

            	if type( attachment.content ) == "table" then

    	        	if type( attachment.content.subject ) == "string" then
    					strTheme = UI:Ut8ValidateLastSymbol( attachment.content.subject )
						strTheme = UI:ShieldSpecSymbolsForMetatext( strTheme )
    					bThemeFound = true
    				else
    	        		sys.log( "UI:GetLetterTheme()[ERROR]: invalid type of \"attachments[%d].content.subject\" in letter %s; \"string\" expected, got \"%s\"", attachmentIdx, _G.U64ToStr( letter.mailId ), type( attachment.content.subject ) )
    				end

    			else
            		sys.log( "UI:GetLetterTheme()[ERROR]: invalid type of \"attachments[%d].content\" in letter %s; \"table\" expected, got \"%s\"", attachmentIdx, _G.U64ToStr( letter.mailId ), type( attachment.content ) )
            	end

    			break

    		end

    	end

	else
		sys.log( "UI:GetLetterTheme()[ERROR]: invalid type of \"attachments\" in letter %s; \"table\" expected, got \"%s\"", _G.U64ToStr( letter.mailId ), type( letter.attachments ) )
	end

	if not bThemeFound then
		sys.log( "UI:GetLetterTheme()[ERROR]: cannot find theme in letter %s", _G.U64ToStr( letter.mailId ) )
	end

	return strTheme

end


--
function UI:GetNeedInventorySizeForMailAttachments( attachments )

	local needSizeTotal = 0
	local needAutogenSizeTotal = 0

	if type( attachments ) ~= "table" then
		sys.log( "UI:GetNeedInventorySizeForMailAttachments()[ERROR]: invalid type of the 1-st parameter (\"attachments\"); \"table\" expected, got \"%s\"", type( attachments ) )
		return needSizeTotal, needAutogenSizeTotal
	end

	for key, attachment in pairs( attachments ) do

		local needSizeAttachment, needAutogenSizeAttachment = UI:GetNeedInventorySizeForMailAttachment( attachment )

		needSizeTotal			= needSizeTotal + needSizeAttachment
		needAutogenSizeTotal	= needAutogenSizeTotal + needAutogenSizeAttachment

	end

	return needSizeTotal, needAutogenSizeTotal

end


--
function UI:GetNeedInventorySizeForMailAttachment( attachment )

	local needSize = 0
	local needAutogenSize = 0

	local attachmentType = UI:GetMailAttachmentType( attachment )

	if attachmentType == UI.mailAttachmentTypes.ITEM then

		local itemDefName = UI:GetMailAttachmentItemDefName( attachment )
		if itemDefName ~= "" then
			needSize, needAutogenSize = UI:GetNeedInventorySizeForItem( itemDefName )
		end

	elseif attachmentType == UI.mailAttachmentTypes.AUTOGEN then
		needAutogenSize = 1
	end

	return needSize, needAutogenSize

end


--
function UI:GetLetterById( letterId )

	if type( letterId ) ~= "userdata" then
		sys.log( "UI:GetLetterById()[ERROR]: invalid type of the 1-st parameter (\"letterId\"); \"userdata\" expected, got \"%s\"", type( letterId ) )
		return nil
	end

	for idx, letter in pairs( UI.serverData.mail ) do
		if letter.mailId == letterId then
			return letter
		end
	end

	return nil

end


--
function UI:IsLetterImportant( letter )

	local bImportant = false

	if type( letter ) ~= "table" then
		sys.log( "UI:IsLetterImportant()[ERROR]: invalid type of the first param (\"letter\" ); \"table\" expected, got \"%s\"", type( letter ) )
		return bImportant
	end

	if type( letter.important ) == "number" then
		bImportant = letter.important ~= 0
	else
		sys.log( "UI:IsLetterImportant()[ERROR]: invalid type of field \"important\" in letter letter %s; \"number\" expected, got \"%s\"", _G.U64ToStr( letter.mailId ), type( letter.important ) )
	end

	return bImportant

end


--
function UI:IsLetterTrading( letter )

	local bTrading = false

	if type( letter ) ~= "table" then
		sys.log( "UI:IsLetterTrading()[ERROR]: invalid type of the first param (\"letter\" ); \"table\" expected, got \"%s\"", type( letter ) )
		return bTrading
	end

	if letter.goldCost ~= nil then

    	if type( letter.goldCost ) == "number" then
    		bTrading = letter.goldCost > 0
    	else
    		sys.log( "UI:IsLetterTrading()[ERROR]: invalid type of field \"goldCost\" in letter letter %s; \"number\" or \"nil\" expected, got \"%s\"", _G.U64ToStr( letter.mailId ), type( letter.goldCost ) )
    	end

	end

	return bTrading

end


--
function UI:Price2Str( val )

	local shortVal = val
	local strFactor = ""

	if val >= 1000000 then
		shortVal = val / 1000000
		strFactor = "kk"

	elseif val >= 1000 then
		shortVal = val / 1000
		strFactor = "k"
	end

	local strVal = UI:FNum2StrSeparatedBy3( shortVal )

	if strFactor ~= "" then
		strVal = string.format( "%s%s", strVal, strFactor )
	end

	return strVal

end


--
function UI:Price2Str2( val )

	local strVal = ""

	if val >= 100000 then
		val = math.floor( val / 1000 )
		strVal = string.format( "%sk", UI:Num2StrSeparatedBy3( val ) )
	else
		strVal = UI:Num2StrSeparatedBy3( val )
	end

	return strVal

end


--
function UI:HasSaleItemsInShop()

	for defName, shopItem in pairs( UI.serverData.shopByDef ) do

		if UI:IsItemVisibleInShop( shopItem ) and UI:IsItemSale( shopItem ) then
			return true
		end

	end

	return false

end


-- нужно ли показывать в окне магазина
function UI:IsItemVisibleInShop( item )

	local def = UI:GetDef( item.defName )

	if not def then
		sys.log( "UI:IsItemVisibleInShop()[ERROR]: cannot find def \"%s\"", item.defName )
		return false
	end

	if not UI:IsItemVisibleForBuy( item, false ) then
		return false
	end

	-- аммуниция может быть куплена только в экране эквипмента, а собственно в магазине - не может
	if item.type == _G.GameStore.ItemType.IT_ROCKET then
		return false
	end

	-- чертежи могут быть куплены только в экране крафта предметов, а собственно в магазине - не могут
	if item.type == _G.GameStore.ItemType.IT_BLUEPRINT then
		return false
	end

	-- бандлы могут быть куплены только в специальном окне
	if item.type == _G.GameStore.ItemType.IT_BUNDLE then
		return false
	end

	-- категория
	-- (показываются только товары валидных категорий (для которых есть информация в _G.StoreInfo ))

	local mainCategoryIdxInfo = def.shopCategory and _G.StoreInfo.categoryName2Idx[ def.shopCategory ]
	if not mainCategoryIdxInfo then
		return false
	end

	local subCategoryIdx = def.shopSubCategory and mainCategoryIdxInfo.sub[ def.shopSubCategory ]

	-- не показываются те товары, для категории которых указан специальный флаг, запрещающий показ в магазине

	local mainCategoryInfo = _G.StoreInfo.categories[ mainCategoryIdxInfo.idx ]
	if mainCategoryInfo.shop == false then
		return false
	end

	if subCategoryIdx then
    	if mainCategoryInfo.subCategories[ subCategoryIdx ].shop == false then
    		return false
    	end
	end

	-- ок, в магазине покажется
	return true

end


-- можно ли показывать для продажи (в любом окне)
function UI:IsItemVisibleForBuy( item, bIgnoreAccountAuras )

	if bIgnoreAccountAuras == nil then
		bIgnoreAccountAuras = false
	end

	local def = UI:GetDef( item.defName )

	if not def then
		sys.log( "UI:IsItemVisibleForBuy()[ERROR]: cannot find def \"%s\"", item.defName )
		return false
	end

	-- может быть куплен?

	if UI:CantItemBeBought( item, bIgnoreAccountAuras ) then
		return false
	end

	-- подходит ранг? (только для бандлов)
	if UI:IsDefBundle( item.defName ) then

		local playerRank = UI:GetPlayerAccountRank()
		local bundleRank = UI:GetItemRequiredAccountRank( item.defName )

		if bundleRank ~= -1 and playerRank < bundleRank then
			return false
		end

	end

	-- SC-111305 есть на счету не менее некой суммы в золоте (только для бандлов)
	if UI:IsDefBundle( item.defName ) then

		if def.min_gold_for_auction ~= nil then

			if type( def.min_gold_for_auction ) == "number" then
				if UI:GetPlayerMoney( true ) < def.min_gold_for_auction then
					return false
				end
			else
				sys.log( "UI:IsItemVisibleForBuy()[ERROR]: invalid type of _G.Def[\"%s\"].min_gold_for_auction; \"number\" or \"nil\" expected, got \"%s\"", item.defName, type( def.min_gold_for_auction ) )
			end

		end

	end


	-- видим в окне, если справедливо хотя бы одно из условий: 1) нет флага hiddenInShop в дефе; 2) есть флаг IS_SHOW в магазине (только для бандлов); 3) бесплатно (только для бандлов)
	local bVisible = false

	if not bVisible then

    	if def.hiddenInShop ~= nil then
    		if type( def.hiddenInShop ) == "boolean" then
				if not def.hiddenInShop then
    				bVisible = true
				end
    		else
    			sys.log( "UI:IsItemVisibleForBuy()[ERROR]: invalid type of _G.Def[\"%s\"].hiddenInShop; \"boolean\" or \"nil\" expected, got \"%s\"", item.defName, type( def.hiddenInShop ) )
    		end
    	else
    		bVisible = true
    	end

	end

	if not bVisible then

    	-- #0062440,комм.(0255236) - для бандлов дополнительно используется флаг IS_SHOW
    	if UI:IsDefBundle( item.defName ) then

        	if type( item.flags ) == "number" then
        		if bit.band( item.flags, _G.GameStore.ItemFlags.IS_SHOW ) == _G.GameStore.ItemFlags.IS_SHOW then
					bVisible = true
				end
			else
        		sys.log( "UI:IsItemVisibleForBuy()[ERROR]: invalid type of the field \"flags\"; \"number\" expected, got \"%s\"", type( item.flags ) )
        	end

    	end

	end

	if not bVisible then

    	if UI:IsDefBundle( item.defName ) then
    		if not UI:IsBundleContentFullyCollected( item.defName ) then
        		local price = UI:GetBundleRealBuyPriceByDef( item.defName, not bIgnoreAccountAuras )
        		if price == 0 then
        			bVisible = true
        		end
    		end
    	end

	end

	return bVisible

end


-- можно ли показывать для продажи (в любом окне)
function UI:IsItemVisibleForBuyByDef( defName, bIgnoreAccountAuras )

	if type( defName ) ~= "string" then
		sys.log( "UI:IsItemVisibleForBuyByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	local item = UI:GetShopItemByDef( defName )
	if not item then
		sys.log( "UI:IsItemVisibleForBuyByDef()[ERROR]: cannot find shop item for \"%s\"", defName )
		return false
	end

	return UI:IsItemVisibleForBuy( item, bIgnoreAccountAuras )

end


