function UI:HasSaleShips()

	for defName, shopItem in pairs( UI.serverData.shopByDef ) do

		if shopItem.type == _G.GameStore.ItemType.IT_VESSEL and UI:IsShipVisibleInShipsTree( shopItem.defName ) and UI:IsItemSale( shopItem ) then
			return true
		end

	end

	return false

