--
function UI:IsShipVisibleInShipsTree( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:IsShipVisibleInShipsTree()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	if not UI:IsDefShip( defName ) then
		sys.log( "UI:IsShipVisibleInShipsTree()[ERROR]: \"%s\" is not ship", defName )
		return false
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsShipVisibleInShipsTree()[ERROR]: cannot find def \"%s\"", defName )
		return false
	end

	local race = UI:GetItemRace( defName )
	if race == -1 then
		sys.log( "UI:IsShipVisibleInShipsTree()[ERROR]: cannot find race for ship \"%s\"", defName )
		return false
	end

	if type( _G.VesselTree ) ~= "table" then
		sys.log( "UI:IsShipVisibleInShipsTree()[ERROR]: invalid type of _G.VesselTree; \"table\" expected, got \"%s\"", type( _G.VesselTree ) )
		return false
	end

	if _G.VesselTree[ defName ] == nil then
		return false
	end

	local bShow = false

	local marketPlaceType = UI:GetShipMarketPlaceType( defName )
	local bIsBought = UI:GetShipItemByDef( defName, false ) ~= nil

	local bCantBeBought = false
	--if not UI:IsShipEvolving( defName ) then	-- #0068954,комм.(0287900) - для "зеленых" кораблей cant_be_bought игнорируется
		bCantBeBought = UI:CantItemBeBoughtByDef( defName )
	--end

	if marketPlaceType == _G.MarketPlaceTypes.NATIVE then
		bShow = bIsBought or not bCantBeBought

	elseif marketPlaceType == _G.MarketPlaceTypes.STEAM_BUNDLE then

		if bIsBought then

			bShow = true

		elseif not bCantBeBought then

			local link = ""

			local dlcName = UI:GetShipDlcName( defName )
			if dlcName ~= "" then
				link = UI:GetDlcLink( dlcName )
			end

			bShow = not UI:IsStrEmpty( link )

		end

	else
		sys.log( "UI:IsShipVisibleInShipsTree()[ERROR]: unhandled marketplace type: %s", tostring( marketPlaceType ) )
	end

	return bShow

end


