--
function UI:ShipCustomization2Str( name )

	local str = "unknown"

	if type( name ) ~= "string" then
		sys.log( "UI:ShipCustomization2Str()[ERROR]: invalid type of the 1-st param ('name'); 'string' expected, got '%s'", type( name ) )
		return str
	end

	local def = _G.VesselCustomElements[ name ]
	if not def then
		sys.log( "UI:ShipCustomization2Str()[ERROR]: cannot find _G.VesselCustomElements[%s]", tostring( name ) )
		return str
	end

	if def.type == ai.VesselCustomElementType.STICKER then
		str = UI:Sticker2Str( name )

	elseif def.type == ai.VesselCustomElementType.MATERIAL then
		str = UI:ShipCustomColor2Str( name )

	elseif def.type == ai.VesselCustomElementType.MPRESET then
		str = UI:ShipCustomPreset2Str( name )

	elseif def.type == ai.VesselCustomElementType.CHILD then
		str = UI:ShipCustomChild2Str( name )

	else
		sys.log( "UI:ShipCustomization2Str()[ERROR]: unhandled customization type: %s in customiztion \"%s\"", tostring( def.type ), name )
	end

	return str

end


--
function UI:GetDyeColor( dyeName )

	local color = UI.WHITE_COLOR

	if type( dyeName ) ~= "string" then
		sys.log( "UI:GetDyeColor()[ERROR]: invaliod type of the 1-st parameter (\"dyeName\"); \"string\" expected, got \"%s\"", type( dyeName ) )
		return color
	end

	local dyeInfo = _G.ShipDyes and _G.ShipDyes[ dyeName ]
	if type( dyeInfo ) ~= "table" then
		sys.log( "UI:GetDyeColor()[ERROR]: invalid type of \"_G.ShipDyes[%s]\"; \"table\" expected, got \"%s\"", dyeName, tostring( dyeInfo ) )
		return color
	end

	if type( dyeInfo.albedo ) ~= "string" then
		sys.log( "UI:GetDyeColor()[ERROR]: invalid type of \"_G.ShipDyes[%s].albedo\"; \"string\" expected, got \"%s\"", dyeName, type( dyeInfo.albedo ) )
		return color
	end

	local strR, strG, strB = string.match( dyeInfo.albedo, "^%s*(%d+)%s+(%d+)%s+(%d+)%s*$" )

	if not strR or not strG or not strB then
		sys.log( "UI:GetDyeColor()[ERROR]: cannot parse \"_G.ShipDyes[%s].albedo\"", dyeName )
		return color
	end

	local R = tonumber( strR )
	local G = tonumber( strG )
	local B = tonumber( strB )
	local A = 255

	color = UI:MakeArgb( A, R, G, B )

	return color

end


