	if type( name ) ~= "string" then
		sys.log( "UI:GetShipCustomColorVal()[ERROR]: invalid type of the 1-st parameter (\"name\"); \"string\" expected, got \"%s\"", type( name ) )
		return color
	end

	local customizationInfo = _G.VesselCustomElements and _G.VesselCustomElements[ name ]
	if type( customizationInfo ) ~= "table" then
		sys.log( "UI:GetShipCustomColorVal()[ERROR]: invalid type of \"_G.VesselCustomElements[%s]\"; \"table\" expected, got \"%s\"", name, type( customizationInfo ) )
		return color
	end

	if type( customizationInfo.dye ) ~= "string" then
		sys.log( "UI:GetShipCustomColorVal()[ERROR]: invalid type of \"_G.VesselCustomElements[%s].dye\"; \"string\" expected, got \"%s\"", name, type( customizationInfo.dye ) )
		return color
	end

	color = UI:GetDyeColor( customizationInfo.dye )
	return color

end

function UI:GetShipCustomColorIco( presetName )

	local hTex = UI.INVALID_RESOURCE_HANDLE
	
	if type( presetName ) ~= "string" then
		sys.log( "UI:GetShipCustomColorIco()[ERROR]: invalid type of the 1-st param ('presetName'); 'string' expected, got '%s'", type( presetName ) )
		return hTex
	end
	
	local customizationType = UI:GetCustomizationTypeByName( presetName )
	if customizationType ~= ai.VesselCustomElementType.MATERIAL then
		sys.log( "UI:GetShipCustomColorIco()[ERROR]: %s is not MATERIAL", presetName )
		return hTex
	end
	
	local customizationInfo = _G.VesselCustomElements and _G.VesselCustomElements[ presetName ]
	if type( customizationInfo ) ~= "table" then
		sys.log( "UI:GetShipCustomColorIco()[ERROR]: invalid type of \"_G.VesselCustomElements[%s]\"; \"table\" expected, got \"%s\"", presetName, type( customizationInfo ) )
		return hTex
	end
	
	-- если иконка не прописана - это нормальная ситуация, тогда пресет будет отображаться в виде трех цветов
	if customizationInfo.uiIco == nil then
		return hTex
	end
	
	if type( customizationInfo.uiIco ) == "string" then
		hTex = UI:GetTex( customizationInfo.uiIco )
	else
		sys.log( "UI:GetShipCustomPresetIco()[ERROR]: invalid type of \"_G.VesselCustomElements[%s].uiIco\"; \"string\" or \"nil\" expected, got \"%s\"", presetName, type( customizationInfo.uiIco) )
	end
	
	return hTex
end


--
function UI:GetShipCustomPresetColor( presetName, colorSlotId )

	local color = UI.WHITE_COLOR

	if type( presetName ) ~= "string" then
		sys.log( "UI:GetShipCustomPresetColor()[ERROR]: invalid type of the 1-st parameter (\"presetName\"); \"string\" expected, got \"%s\"", type( presetName ) )
		return color
	end

	if type( colorSlotId ) ~= "number" then
		sys.log( "UI:GetShipCustomPresetColor()[ERROR]: invalid type of the 2-nd parameter (\"colorSlotId\"); \"number\" expected, got \"%s\"", type( colorSlotId ) )
		return color
	end

	if not( colorSlotId == ai.VesselCustomSlot.MATERIAL_0 or colorSlotId == ai.VesselCustomSlot.MATERIAL_1 or colorSlotId == ai.VesselCustomSlot.MATERIAL_2 ) then
		sys.log( "UI:GetShipCustomPresetColor()[ERROR]: invalid colorSlotId; %d is not color slot", colorSlotId )
		return color
	end

	local dyeName = UI:GetShipCustomizationInPreset( presetName, colorSlotId )

	if dyeName == "" then
		sys.log( "UI:GetShipCustomPresetColor()[ERROR]: no color in slot %d in preset %s", colorSlotId, presetName )
		return color
	end

	color = UI:GetDyeColor( dyeName )
	return color

end


--
function UI:GetShipCustomizationsInPreset( presetName )

	local customizations = {}

	if type( presetName ) ~= "string" then
		sys.log( "UI:GetShipCustomizationsInPreset()[ERROR]: invalid type of the 1-st param (\"presetName\"); \"string\" expected, got \"%s\"", type( presetName ) )
		return customizations
	end

	local presetInfo = _G.VesselCustomElements and _G.VesselCustomElements[ presetName ]
	if type( presetInfo ) ~= "table" then
		sys.log( "UI:GetShipCustomizationsInPreset()[ERROR]: invalid type of the _G.VesselCustomElements[%s]; \"table\" expected, got \"%s\"", presetName, type( presetInfo ) )
		return customizations
	end

	if type( presetInfo.type ) ~= "number" then
		sys.log( "UI:GetShipCustomizationsInPreset()[ERROR]: invalid type of the _G.VesselCustomElements[%s].type; \"number\" expected, got \"%s\"", presetName, type( presetInfo.type ) )
		return customizations
	end

	if presetInfo.type ~= ai.VesselCustomElementType.MPRESET then
		sys.log( "UI:GetShipCustomizationsInPreset()[ERROR]: \"%s\" is not of type ai.VesselCustomElementType.MPRESET", presetName )
		return customizations
	end

	if type( presetInfo.desc ) ~= "table" then
		sys.log( "UI:GetShipCustomizationsInPreset()[ERROR]: invalid type of the _G.VesselCustomElements[%s].desc; \"table\" expected, got \"%s\"", presetName, type( presetInfo.desc ) )
		return customizations
	end

	for slotId, customName in pairs( presetInfo.desc ) do

		if type( slotId ) == "number" and type( customName ) == "string" then
			customizations[ slotId ] = customName
		else
			sys.log( "UI:GetShipCustomizationsInPreset()[ERROR]: invalid format of table _G.VesselCustomElements[%s].desc; <number>=<string> expected, got <%s>=<%s>", presetName, type( slotId ), type( customName ) )
		end

	end

	return customizations

end


--
function UI:GetShipCustomizationInPreset( presetName, customSlotId )

	if type( presetName ) ~= "string" then
		sys.log( "UI:GetShipCustomizationInPreset()[ERROR]: invalid type of the 1-st param (\"presetName\"); \"string\" expected, got \"%s\"", type( presetName ) )
		return ""
	end

	if type( customSlotId ) ~= "number" then
		sys.log( "UI:GetShipCustomizationInPreset()[ERROR]: invalid type of the 2-nd param (\"customSlotId\"); \"number\" expected, got \"%s\"", type( customSlotId ) )
		return ""
	end

	local customizations = UI:GetShipCustomizationsInPreset( presetName )
	return customizations[ customSlotId ] or ""

end


--
function UI:IsShipCustomSlotInPreset( presetName, customSlotId )

	if type( presetName ) ~= "string" then
		sys.log( "UI:IsShipCustomSlotInPreset()[ERROR]: invalid type of the 1-st param (\"presetName\"); \"string\" expected, got \"%s\"", type( presetName ) )
		return false
	end

	if type( customSlotId ) ~= "number" then
		sys.log( "UI:IsShipCustomSlotInPreset()[ERROR]: invalid type of the 2-nd param (\"customSlotId\"); \"number\" expected, got \"%s\"", type( customSlotId ) )
		return false
	end

	return UI:GetShipCustomizationInPreset( presetName, customSlotId ) ~= ""

end


--
function UI:GetShipCustomPresetIco( presetName )

	local hTex = UI.INVALID_RESOURCE_HANDLE

	if type( presetName ) ~= "string" then
		sys.log( "UI:GetShipCustomPresetIco()[ERROR]: invalid type of the 1-st param ('presetName'); 'string' expected, got '%s'", type( presetName ) )
		return hTex
	end

	local customizationType = UI:GetCustomizationTypeByName( presetName )
	if customizationType ~= ai.VesselCustomElementType.MPRESET then
		sys.log( "UI:GetShipCustomPresetIco()[ERROR]: %s is not MPRESET", presetName )
		return hTex
	end

	local customizationInfo = _G.VesselCustomElements and _G.VesselCustomElements[ presetName ]
	if type( customizationInfo ) ~= "table" then
		sys.log( "UI:GetShipCustomPresetIco()[ERROR]: invalid type of \"_G.VesselCustomElements[%s]\"; \"table\" expected, got \"%s\"", presetName, type( customizationInfo ) )
		return hTex
	end

	-- если иконка не прописана - это нормальная ситуация, тогда пресет будет отображаться в виде трех цветов
	if customizationInfo.uiIco == nil then
		return hTex
	end

	if type( customizationInfo.uiIco ) == "string" then
		hTex = UI:GetTex( customizationInfo.uiIco )
	else
		sys.log( "UI:GetShipCustomPresetIco()[ERROR]: invalid type of \"_G.VesselCustomElements[%s].uiIco\"; \"string\" or \"nil\" expected, got \"%s\"", presetName, type( customizationInfo.uiIco) )
	end

	return hTex

end


--
function UI:GetShipMaterialIcoColor( colorName )

	local hTex = UI.INVALID_RESOURCE_HANDLE
	local color = UI.WHITE_COLOR

	if type( colorName ) ~= "string" then
		sys.log( "UI:GetShipMaterialIcoColor()[ERROR]: invalid type of the 1-st param ('colorName'); 'string' expected, got '%s'", type( colorName ) )
		return hTex
	end

	local customizationType = UI:GetCustomizationTypeByName( colorName )
	if customizationType ~= ai.VesselCustomElementType.MATERIAL then
		sys.log( "UI:GetShipMaterialIcoColor()[ERROR]: %s is not MATERIAL", colorName )
		return hTex
	end

	local customizationInfo = _G.VesselCustomElements and _G.VesselCustomElements[ colorName ]
	if type( customizationInfo ) ~= "table" then
		sys.log( "UI:GetShipMaterialIcoColor()[ERROR]: invalid type of \"_G.VesselCustomElements[%s]\"; \"table\" expected, got \"%s\"", colorName, type( customizationInfo ) )
		return hTex
	end

	-- если иконка не прописана - это нормальная ситуация, тогда цвет будет отображаться
	if customizationInfo.uiIco == nil then
		hTex = UI:GetTex( "white" )
		color = UI:GetShipCustomColorVal( colorName )
	elseif type( customizationInfo.uiIco ) == "string" then
		hTex = UI:GetTex( customizationInfo.uiIco )
	else
		sys.log( "UI:GetShipMaterialIcoColor()[ERROR]: invalid type of \"_G.VesselCustomElements[%s].uiIco\"; \"string\" or \"nil\" expected, got \"%s\"", colorName, type( customizationInfo.uiIco) )
	end

	return hTex, color

end


--
function UI:GetShipCustomizationRestrictGroup( customName )

	local restrictGroup = _G.VesselCustomElementsGroups.DEFAULT

	if type( customName ) ~= "string" then
		sys.log( "UI:GetShipCustomizationRestrictGroup()[ERROR]: invalid type of the 1-st param (\"customName\"); \"string\" expected, got \"%s\"", type( customName ) )
		return restrictGroup
	end

	local customDef = _G.VesselCustomElements[ customName ]
	if type( customDef ) ~= "table" then
		sys.log( "UI:GetShipCustomizationRestrictGroup()[ERROR]: invalid type of the \"_G.VesselCustomElements[%s]\"; \"table\" expected, got \"%s\"", customName, type( customDef ) )
		return restrictGroup
	end

	if customDef.group ~= nil then

		if type( customDef.group ) == "number" then
			restrictGroup = customDef.group
		else
			sys.log( "UI:GetShipCustomizationRestrictGroup[ERROR]: invalid type of _G.VesselCustomElements[%s].group; \"number\" or \"nil\" expected, got \"%s\"", customName, type( customDef.group ) )
		end

	end

	return restrictGroup

end


-- если вернет nil, то значит подходят любые группы; если пустую таблицу, то значит не подходит ни одна
function UI:GetShipCustomSlotRestrictGroups( shipDefName, customSlot )

	local restrictGroups = nil

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipCustomSlotRestrictGroups()[ERROR]: invalid type of the 1-st param (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return restrictGroups
	end

	if type( customSlot ) ~= "number" then
		sys.log( "UI:GetShipCustomSlotRestrictGroups()[ERROR]: invalid type of the 2-nd param (\"customSlot\"); \"number\" expected, got \"%s\"", type( customSlot ) )
		return restrictGroups
	end

	local shipDef = UI:GetDef( shipDefName )
	if not shipDef then
		sys.log( "UI:GetShipCustomSlotRestrictGroups()[ERROR]: cannot find _G.Def[%s]", shipDefName )
		return restrictGroups
	end

	local restrictInfo = shipDef.customization_groups
	if restrictInfo ~= nil then

		if type( restrictInfo ) == "table" then

			local groups = restrictInfo[ customSlot ]
			if groups ~= nil then

				restrictGroups = {}

				if type( groups ) == "table" then

					local bValid = true

					for groupIdx, group in pairs( groups ) do
						if type( groupIdx ) ~= "number" or type( group ) ~= "number" then
							sys.log( "UI:GetShipCustomSlotRestrictGroups()[ERROR]: invalid format of \"_G.Def[%s].customization_groups[%d]\" table; <number>=<number> expected, got <%s>=<%s>", shipDefName, customSlot, type( groupIdx ), type( group ) )
							bValid = false
							break
						end
					end

					if bValid then
						restrictGroups = groups
					end

				else
					sys.log( "UI:GetShipCustomSlotRestrictGroups()[ERROR]: invalid type of the \"_G.Def[%s].customization_groups[%d]\"; \"table\" or \"nil\" expected, got \"%s\"", shipDefName, customSlot, type( groups ) )
				end

			end

		else
			sys.log( "UI:GetShipCustomSlotRestrictGroups()[ERROR]: invalid type of the \"_G.Def[%s].customization_groups\"; \"table\" or \"nil\" expected, got \"%s\"", shipDefName, type( restrictInfo ) )
		end

	end

	return restrictGroups

end


--
function UI:IsShipCustomSlotDisabled( shipDefName, customSlot )

	local restrictGroups = UI:GetShipCustomSlotRestrictGroups( shipDefName, customSlot )
	return restrictGroups ~= nil and next( restrictGroups ) == nil	-- nil означает, что подходят любые группы; пустая таблица означает, что не подходит ни одна (т.е. слот задисэйблен)

end


--
function UI:GetCustomizationTypeByName( defName )

	local customType = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetCustomizationTypeByName()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return customType
	end

	local customDef = _G.VesselCustomElements and _G.VesselCustomElements[ defName ]
	if not customDef then
		sys.log( "UI:GetCustomizationTypeByName()[ERROR]: cannot find _G.VesselCustomElements[%s]", defName )
		return customType
	end

	if type( customDef.type ) ~= "number" then
		sys.log( "UI:GetCustomizationTypeByName()[ERROR]: invalid type of _G.VesselCustomElements[%s].type; \"number\" expected, got \"%s\"", defName, type( customDef.type ) )
		return customType
	end

	if UI:Val2Key( ai.VesselCustomElementType, customDef.type ) == "" then
		sys.log( "UI:GetCustomizationTypeByName()[ERROR]: invalid customization type of _G.VesselCustomElements[%s].type; one of the \"ai.VesselCustomElementType\" expected, got %d", defName, customDef.type )
		return customType
	end

	customType = customDef.type

	return customType

end


--
function UI:ShipCustomizationType2Str( customType )

	local str = "unknown"

	if type( customType ) ~= "number" then
		sys.log( "UI:ShipCustomizationType2Str()[ERROR]: invalid type of the 1-st parameter (\"customType\"); \"number\" expected, got \"%s\"", type( customType ) )
		return str
	end

	local customTypeName = UI:Val2Key( ai.VesselCustomElementType, customType )
	if customTypeName == "" then
		sys.log( "UI:ShipCustomizationType2Str()[ERROR]: invalid customType %d", customType )
		return str
	end

	local strId = string.format( "customizationType_%s", customTypeName )
	str = UI:GetStringByName( strId )

	return str

end


--
function UI:GetShipCustomizationGroup( defName )

	local groupId = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipCustomizationGroup()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return groupId
