--
function UI:GetShipDlcName( defName )

	local dlcName = ""

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetShipDlcName()[ERROR]: cannot find _G.Def[%s]", tostring( defName ) )
		return dlcName
	end

	local marketPlace = self:GetShipMarketPlaceType( defName )
	if marketPlace ~= _G.MarketPlaceTypes.STEAM_BUNDLE then
		sys.log( "UI:GetShipDlcName()[ERROR]: %s is not dlc", defName )
		return dlcName
	end

	if type( def.dlc_name ) == "string" then
		dlcName = def.dlc_name
	else
		sys.log( "UI:GetShipDlcName()[ERROR]: invalid type of _G.Def[%s].dlc_name; \"string\" expected, got \"%s\"", defName, type( def.dlc_name ) )
	end

	return dlcName

end


