--
function UI:GetArcDlcInfo( dlcName )

	if type( dlcName ) ~= "string" then
		sys.log( "UI:GetArcDlcInfo()[ERROR]: invalid type of the 1-st parameter (\"dlcName\"); \"string\" expected, got \"%s\"", type( dlcName ) )
		return nil
	end

	local dlcInfos = _G.GameStore_GetArcDLCInfo()

	for idx, info in pairs( dlcInfos ) do
		if info.name == dlcName then
			return info, idx - 1
		end
	end

	sys.log( "UI:GetArcDlcInfo()[ERROR]: cannot find arc info for dlc \"%s\"", dlcName )
	return nil

end


--
function UI:GetDlcLink( dlcName )

	local link = ""

	if type( dlcName ) ~= "string" then
		sys.log( "UI:GetDlcLink()[ERROR]: invalid type of the 1-st parameter (\"dlcName\"); \"string\" expected, got \"%s\"", type( dlcName ) )
		return link
	end

	if type( _G.DLCList ) ~= "table" then
		sys.log( "UI:GetDlcLink()[ERROR]: invalid type of _G.DLCList; \"table\" expected, got \"%s\"", type( _G.DLCList ) )
		return link
	end

	local dlcInfo = nil

	for idx, info in pairs( _G.DLCList ) do
		if type( info ) == "table" then

			if type( info.name ) == "string" then
				if info.name == dlcName then

					dlcInfo = info
					break

				end
			else
				sys.log( "UI:GetDlcLink()[ERROR]: invalid type of _G.DLCList[%s].name; \"string\" expected, got \"%s\"", tostring( idx ), type( info.name ) )
			end

		else
			sys.log( "UI:GetDlcLink()[ERROR]: invalid type of _G.DLCList[%s]; \"table\" expected, got \"%s\"", tostring( idx ), type( info ) )
		end
	end

	if not dlcInfo then
		sys.log( "UI:GetDlcLink()[ERROR]: cannot find dlc info for dlc \"%s\"", dlcName )
		return link
	end

	if dlcInfo.steam_force_yuplay ~= nil then
		if type( dlcInfo.steam_force_yuplay ) ~= "boolean" then
			sys.log( "UI:GetDlcLink()[ERROR]: invalid type of \"steam_force_yuplay\" in table \"_G.DLCList\" for dlc \"%s\"; \"boolean\" or \"nil\" expected, got \"%s\"", dlcName, type( dlcInfo.steam_force_yuplay ) )
			return
		end
	end

	if UI:IsSteam() and not dlcInfo.steam_force_yuplay then

		if type( dlcInfo.steam_url ) == "string" then
			link = dlcInfo.steam_url
		else
			sys.log( "UI:GetDlcLink()[ERROR]: invalid type of \"steam_url\" in table \"_G.DLCList\" for dlc \"%s\"; \"string\" expected, got \"%s\"", dlcName, type( dlcInfo.steam_url ) )
		end

	else

		local linkDefaultName = "yuplay_url"

		local language = UI:GetLanguage()
		local langDesc = _G.locale.languages and _G.locale.languages and _G.locale.languages[ language ]
		local langShortName = langDesc and langDesc.shortName or ""

		if not UI:IsStrEmpty( langShortName ) then

			local langLinkName = string.format( "%s_%s", linkDefaultName, langShortName )
			local langLink = dlcInfo[ langLinkName ]

			if langLink ~= nil then
				if type( langLink ) == "string" then
					link = langLink
				else
					sys.log( "UI:GetDlcLink()[ERROR]: invalid type of \"%s\" in table \"_G.DLCList\" for dlc \"%s\"; \"string\" expected, got \"%s\"", langLinkName, dlcName, type( langLink ) )
				end
			end

		else
			sys.log( "UI:GetDlcLink()[ERROR]: cannot find short name for language \"%s\"", language )
		end

		if UI:IsStrEmpty( link ) then

			local defaultLink = dlcInfo[ linkDefaultName ]

    		if type( defaultLink ) == "string" then
				link = defaultLink
    		else
				sys.log( "UI:GetDlcLink()[ERROR]: invalid type of \"%s\" in table \"_G.DLCList\" for dlc \"%s\"; \"string\" expected, got \"%s\"", linkDefaultName, dlcName, type( defaultLink ) )
    		end

		end

	end

	return link

end


--
function UI:GetDlcForceYuplay( dlcName )

	local bForceYuplay = false

	if type( dlcName ) ~= "string" then
		sys.log( "UI:GetDlcForceYuplay()[ERROR]: invalid type of the 1-st parameter (\"dlcName\"); \"string\" expected, got \"%s\"", type( dlcName ) )
		return bForceYuplay
	end

	local dlcInfo = nil

	for idx, info in pairs( _G.DLCList ) do
		if type( info ) == "table" then

			if type( info.name ) == "string" then
				if info.name == dlcName then

					dlcInfo = info
					break

				end
			else
				sys.log( "UI:GetDlcForceYuplay()[ERROR]: invalid type of _G.DLCList[%s].name; \"string\" expected, got \"%s\"", tostring( idx ), type( info.name ) )
			end

		else
			sys.log( "UI:GetDlcForceYuplay()[ERROR]: invalid type of _G.DLCList[%s]; \"table\" expected, got \"%s\"", tostring( idx ), type( info ) )
		end
	end

	if not dlcInfo then
		sys.log( "UI:GetDlcForceYuplay()[ERROR]: cannot find dlc info for dlc \"%s\"", dlcName )
		return bForceYuplay
	end

	if dlcInfo.steam_force_yuplay ~= nil then
		if type( dlcInfo.steam_force_yuplay ) == "boolean" then
			bForceYuplay = dlcInfo.steam_force_yuplay
		else
			sys.log( "UI:GetDlcForceYuplay()[ERROR]: invalid type of \"steam_force_yuplay\" in table \"_G.DLCList\" for dlc \"%s\"; \"boolean\" or \"nil\" expected, got \"%s\"", dlcName, type( dlcInfo.steam_force_yuplay ) )
			return bForceYuplay
		end
	end

	return bForceYuplay

end


--
function UI:GetDlcYupGuid( dlcName )

	local guid = ""

	if type( dlcName ) ~= "string" then
		sys.log( "UI:GetDlcYupGuid()[ERROR]: invalid type of the 1-st parameter (\"dlcName\"); \"string\" expected, got \"%s\"", type( dlcName ) )
		return guid
	end

	if type( _G.DLCList ) ~= "table" then
		sys.log( "UI:GetDlcYupGuid()[ERROR]: invalid type of _G.DLCList; \"table\" expected, got \"%s\"", type( _G.DLCList ) )
		return guid
	end

	local dlcInfo = nil

	for idx, info in pairs( _G.DLCList ) do
		if type( info ) == "table" then

			if type( info.name ) == "string" then
				if info.name == dlcName then

					dlcInfo = info
					break

				end
			else
				sys.log( "UI:GetDlcYupGuid()[ERROR]: invalid type of _G.DLCList[%s].name; \"string\" expected, got \"%s\"", tostring( idx ), type( info.name ) )
			end

		else
			sys.log( "UI:GetDlcYupGuid()[ERROR]: invalid type of _G.DLCList[%s]; \"table\" expected, got \"%s\"", tostring( idx ), type( info ) )
		end
	end

	if not dlcInfo then
		sys.log( "UI:GetDlcYupGuid()[ERROR]: cannot find dlc info for dlc \"%s\"", dlcName )
		return guid
	end


	local guidDefaultName = "yuplay_guid"

	local language = UI:GetLanguage()
	local langDesc = _G.locale.languages and _G.locale.languages and _G.locale.languages[ language ]
	local langShortName = langDesc and langDesc.shortName or ""

	if not UI:IsStrEmpty( langShortName ) then

		local langGuidName = string.format( "%s_%s", guidDefaultName, langShortName )
		local langGuid = dlcInfo[ langGuidName ]

		if langGuid ~= nil then
			if type( langGuid ) == "string" then
				guid = langGuid
			else
				sys.log( "UI:GetDlcYupGuid()[ERROR]: invalid type of \"%s\" in table \"_G.DLCList\" for dlc \"%s\"; \"string\" expected, got \"%s\"", langGuidName, dlcName, type( langGuid ) )
			end
		end

	else
		sys.log( "UI:GetDlcYupGuid()[ERROR]: cannot find short name for language \"%s\"", language )
	end

	if UI:IsStrEmpty( guid ) then

		local defaultGuid = dlcInfo[ guidDefaultName ]

		if type( defaultGuid ) == "string" then
			guid = defaultGuid
		else
			sys.log( "UI:GetDlcYupGuid()[ERROR]: invalid type of \"%s\" in table \"_G.DLCList\" for dlc \"%s\"; \"string\" expected, got \"%s\"", guidDefaultName, dlcName, type( defaultGuid ) )
		end

	end

	return guid

end


--
function UI:LaunchDlcLink( dlcName )

	if type( dlcName ) ~= "string" then
		sys.log( "UI:LaunchDlcLink()[ERROR]: invalid type of the 1-st parameter (\"dlcName\"); \"string\" expected, got \"%s\"", type( dlcName ) )
		return
	end

	local bForceYuplay = UI:GetDlcForceYuplay( dlcName )

	if UI:IsSteam() then

		-- SC-112141 открытие из интерфейса стима юплеевского магазина
		if bForceYuplay then

			local guid = UI:GetDlcYupGuid( dlcName )

			if guid ~= "" then
				_G.Steam_NavigateToURLGaijin( guid )
			else
				sys.log( "UI:LaunchDlcLink()[ERROR]: no guid found for dlc \"%s\"", dlcName )
			end

		else

			local link = UI:GetDlcLink( dlcName )
			if link == "" then
				sys.log( "UI:LaunchDlcLink()[ERROR]: no link found for dlc \"%s\"", dlcName )
				return
			end

			_G.Steam_NavigateToURL( link )

		end

	else

		local link = UI:GetDlcLink( dlcName )
		if link == "" then
			sys.log( "UI:LaunchDlcLink()[ERROR]: no link found for dlc \"%s\"", dlcName )
			return
		end

		_G.MasterServer_SignInAndRerirectGaijin( link )

	end

end


--
function UI:GetBoughtDlcs()

	local boughtDlcs = {}

	local data = _G.GameStore_GetOwnedDlc()
	if type( data ) ~= "table" then
		sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of return value from _G.GameStore_GetOwnedDlc(); \"table\" expected, got \"%s\"", type( data ) )
		return boughtDlcs
	end

	if type( _G.DLCList ) ~= "table" then
		sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of _G.DLCList; \"table\" expected, got \"%s\"", type( _G.DLCList ) )
		return boughtDlcs
	end

	local steamId2Name	= {}
	local yuplayId2Name	= {}

	for idx, info in pairs( _G.DLCList ) do

		if type( info ) == "table" then

			if type( info.name ) == "string" then

				local bSteamForceYuplay = false

				if info.steam_force_yuplay ~= nil then
					if type( info.steam_force_yuplay ) == "boolean" then
						bSteamForceYuplay = info.steam_force_yuplay
					else
						sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of _G.DLCList[%s].steam_force_yuplay; \"boolean\" or \"nil\" expected, got \"%s\"", tostring( idx ), type( info.steam_force_yuplay ) )
					end
				end

    			if type( info.steam_appId ) == "number" then
					steamId2Name[ info.steam_appId ] = info.name
    			elseif not bSteamForceYuplay then
    				sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of _G.DLCList[%s].steam_appId, dlc name \"%s\"; \"number\" expected, got \"%s\"", tostring( idx ), info.name, type( info.steam_appId ) )
    			end

    			if type( info.yuplay_guid_ru ) == "string" then
					yuplayId2Name[ info.yuplay_guid_ru ] = info.name
				else
    				sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of _G.DLCList[%s].yuplay_guid_ru; \"string\" expected, got \"%s\"", tostring( idx ), type( info.yuplay_guid_ru ) )
    			end

    			if type( info.yuplay_guid ) == "string" then
					yuplayId2Name[ info.yuplay_guid ] = info.name
				else
    				sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of _G.DLCList[%s].yuplay_guid; \"string\" expected, got \"%s\"", tostring( idx ), type( info.yuplay_guid ) )
    			end

			else
                sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of _G.DLCList[%s].name; \"string\" expected, got \"%s\"", tostring( idx ), type( info.name ) )
			end

		else
			sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of _G.DLCList[%s]; \"table\" expected, got \"%s\"", tostring( idx ), type( info ) )
		end

	end


	if data.steam ~= nil then

		if type( data.steam ) == "table" then

			for idx, id in pairs( data.steam ) do

				if type( id ) == "number" then

					local name = steamId2Name[ id ]
					if name then
						boughtDlcs[ name ] = true
					end

				else
					sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of field \"steam[%s]\"; \"number\" expected, got \"%s\"", tostring( idx ), type( id ) )
				end

			end

		else
			sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of field \"steam\"; \"table\" or \"nil\" expected, got \"%s\"", type( data.steam ) )
		end

	end

	if data.yuplay ~= nil then

		if type( data.yuplay ) == "table" then

			for idx, id in pairs( data.yuplay ) do

				if type( id ) == "string" then

					local name = yuplayId2Name[ id ]
					if name then
						boughtDlcs[ name ] = true
					end

				else
					sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of field \"yuplay[%s]\"; \"string\" expected, got \"%s\"", tostring( idx ), type( id ) )
				end

			end

		else
			sys.log( "UI:GetBoughtDlcs()[ERROR]: invalid type of field \"yuplay\"; \"table\" or \"nil\" expected, got \"%s\"", type( data.yuplay ) )
		end

	end

	return boughtDlcs

end


--
function UI:GetDlcArcBundle( dlcName )

	local bundleDefName = ""

	if type( dlcName ) ~= "string" then
		sys.log( "UI:GetDlcArcBundle()[ERROR]: invalid type of the 1-st parameter (\"dlcName\"); \"string\" expected, got \"%s\"", type( dlcName ) )
		return bundleDefName
	end

	if type( _G.DLCList ) ~= "table" then
		sys.log( "UI:GetDlcArcBundle()[ERROR]: invalid type of _G.DLCList; \"table\" expected, got \"%s\"", type( _G.DLCList ) )
		return bundleDefName
	end

	local dlcInfo = nil

	for idx, info in pairs( _G.DLCList ) do
		if type( info ) == "table" then

			if type( info.name ) == "string" then
				if info.name == dlcName then

					dlcInfo = info
					break

				end
			else
				sys.log( "UI:GetDlcArcBundle()[ERROR]: invalid type of _G.DLCList[%s].name; \"string\" expected, got \"%s\"", tostring( idx ), type( info.name ) )
			end

		else
			sys.log( "UI:GetDlcArcBundle()[ERROR]: invalid type of _G.DLCList[%s]; \"table\" expected, got \"%s\"", tostring( idx ), type( info ) )
		end
	end

	if not dlcInfo then
		sys.log( "UI:GetDlcArcBundle()[ERROR]: cannot find dlc info for dlc \"%s\"", dlcName )
		return bundleDefName
	end

	if type( dlcInfo.arc_bundle ) ~= "string" then
		sys.log( "UI:GetDlcArcBundle()[ERROR]: invalid type of \"arc_bundle\" in table \"_G.DLCList\" for dlc \"%s\"; \"string\" expected, got \"%s\"", dlcName, type( dlcInfo.arc_bundle ) )
		return bundleDefName
	end

	bundleDefName = dlcInfo.arc_bundle

	if not UI:IsDefBundle( bundleDefName ) then
		sys.log( "UI:GetDlcArcBundle()[ERROR]: \"%s\" is not bundle", bundleDefName )
		bundleDefName = ""
	end

	return bundleDefName

end


--
function UI:CanShipLevelUp( vid )

	if type( vid ) ~= "userdata" then
		sys.log( "UI:CanShipLevelUp()[ERROR]: invalid type of the 1-st parameter (\"vid\"); \"userdata\" expected, got \"%s\"", type( vid ) )
		return false
	end

	if vid == UI.INVALID_U64_ID then
		sys.log( "UI:CanShipLevelUp()[ERROR]: invalid vid" )
		return false
	end

	local shipItem = self:GetShipItem( vid, false )
	if not shipItem then
		sys.log( "UI:CanShipLevelUp()[ERROR]: cannot find ship item  for vid %s", _G.U64ToStr( vid ) )
		return false
	end

	local shipLevel = self:GetShipLevel( shipItem )
	local maxLevel = self:GetShipMaxLevel( shipItem.defName )

	if shipLevel >= maxLevel then
		return false
	end

	local shipRank = UI:GetShipRank( shipItem.defName )
	local needSynergy = _G.VesselExpPerLevel and _G.VesselExpPerLevel[ shipRank ] and _G.VesselExpPerLevel[ shipRank ][ shipLevel ]

	if type( needSynergy ) ~= "number" then
		sys.log( "UI:CanShipLevelUp()[ERROR]: invalid type of the _G.VesselExpPerLevel[%d][%d]; \"number\" expected, got \"%s\"", shipRank, shipLevel, type( needSynergy ) )
		needSynergy = 0
	end

	local shipSynergy = UI:GetShipExp( shipItem )
	local freeSynergy = self.serverData.playerCredits.vesselExpPool or 0

	return ( shipSynergy + freeSynergy ) >= needSynergy

end


--
function UI:GetLetterLifeTime( letter )

	if type( letter ) ~= "table" then
		sys.log( "UI:GetLetterLifeTime()[ERROR]: invalid type of the 1-st parameter (\"letter\"); \"table\" expected, got \"%s\"", type( letter ) )
		return 0
	end

	if type( letter.sentAt ) ~= "userdata" then
		sys.log( "UI:GetLetterLifeTime()[ERROR]: invalid type of \"letter.sentAt\"; \"userdata\" expected, got \"%s\"", type( letter.sentAt ) )
		return 0
	end

	if type( letter.expTime ) ~= "userdata" then
		sys.log( "UI:GetLetterLifeTime()[ERROR]: invalid type of \"letter.expTime\"; \"userdata\" expected, got \"%s\"", type( letter.expTime ) )
		return 0
	end

	return _G.GetPlatformTimeDiffSec( letter.expTime, letter.sentAt )

end


--
function UI:GetLetterLeftTime( letter )

	if type( letter ) ~= "table" then
		sys.log( "UI:GetLetterLeftTime()[ERROR]: invalid type of the 1-st parameter (\"letter\"); \"table\" expected, got \"%s\"", type( letter ) )
		return 0
	end

	if type( letter.expTime ) ~= "userdata" then
		sys.log( "UI:GetLetterLeftTime()[ERROR]: invalid type of \"letter.expTime\"; \"userdata\" expected, got \"%s\"", type( letter.expTime ) )
		return 0
	end

	local curTime = _G.MasterServer_GetServerTime()
	local leftTime = _G.GetPlatformTimeDiffSec( letter.expTime, curTime )

	return math.max( leftTime, 0 )

end


--
function UI:GetYupPurchasePrice( guid )

	local price = 0
	local currency = ""

	if type( guid ) ~= "string" then
		sys.log( "UI:GetYupPurchasePrice()[ERROR]: invalid type of the 1-st parameter (\"guid\"); \"string\" expected, got \"%s\"", type( guid ) )
		return price, currency
	end

	local info = UI.serverData.yupPurchasesPrices[ guid ]
	if type( info ) ~= "table" then
		sys.log( "UI:GetYupPurchasePrice()[ERROR]: cannot find price info for guid '%s'", guid )
		return price, currency
	end

	if type( info.shop_price ) == "number" then
		price = info.shop_price
	else
		sys.log( "UI:GetYupPurchasePrice()[ERROR]: invalid type of field 'shop_price' for guid '%s'; 'number' expected, got '%s'", guid, type( info.shop_price ) )
	end

	if type( info.shop_price_curr ) == "string" then
		currency = info.shop_price_curr
	else
		sys.log( "UI:GetYupPurchasePrice()[ERROR]: invalid type of field 'shop_price_curr' for guid '%s'; 'string' expected, got '%s'", guid, type( info.shop_price_curr ) )
	end

	return price, currency

end


--
function UI:GetItemAuraSaleInfo( itemDefName )

	local bIsAura			= false
	local modifier_credits	= 0
	local modifier_gold		= 0

	if type( itemDefName ) ~= "string" then
		sys.log( "UI:GetItemAuraSaleInfo()[ERROR]: invalid type of the 1-st parameter (\"itemDefName\"); \"string\" expected, got \"%s\"", type( itemDefName ) )
		return bIsAura, modifier_credits, modifier_gold
	end

	local shopItem = UI:GetShopItemByDef( itemDefName )
	if not shopItem then
		sys.log( "UI:GetItemAuraSaleInfo()[ERROR]: cannot find shop item for \"%s\"", itemDefName )
		return bIsAura, modifier_credits, modifier_gold
	end

	bIsAura, modifier_credits, modifier_gold = _G.GameStore_GetDiscountMod( shopItem.id )

	local bError = false

	if type( bIsAura ) ~= "boolean" then
		sys.log( "UI:GetItemAuraSaleInfo()[ERROR]: invalid type of 1-st return value from _G.GameStore_GetDiscountMod() for item \"%s\"; \"boolean\" expected, got \"%s\"", itemDefName, type( bIsAura ) )
		bError = true
	end

	if type( modifier_credits ) ~= "number" then
		sys.log( "UI:GetItemAuraSaleInfo()[ERROR]: invalid type of 2-nd return value from _G.GameStore_GetDiscountMod() for item \"%s\"; \"number\" expected, got \"%s\"", itemDefName, type( modifier_credits ) )
		bError = true
	end

	if type( modifier_gold ) ~= "number" then
		sys.log( "UI:GetItemAuraSaleInfo()[ERROR]: invalid type of 3-rd return value from _G.GameStore_GetDiscountMod() for item \"%s\"; \"number\" expected, got \"%s\"", itemDefName, type( modifier_gold ) )
		bError = true
	end

	if bError then
		bIsAura				= false
		modifier_credits	= 0
		modifier_gold		= 0
	end

	if not bIsAura then
		modifier_credits	= 0
		modifier_gold		= 0
	end

	return bIsAura, modifier_credits, modifier_gold

end


--
function UI:HasShipEquippedModuleOfSubType( vid, subType, slotIdToIgnore )

	if type( vid ) ~= "userdata" then
		sys.log( "UI:HasShipEquippedModuleOfSubType()[ERROR]: invalid type of the 1-st parameter (\"vid\"); \"userdata\" expected, got \"%s\"", type( vid ) )
		return false
	end

	if type( subType ) ~= "number" then
		sys.log( "UI:HasShipEquippedModuleOfSubType()[ERROR]: invalid type of the 2-nd parameter (\"subType\"); \"number\" expected, got \"%s\"", type( subType ) )
		return false
	end

	if type( slotIdToIgnore ) ~= "number" then
		sys.log( "UI:HasShipEquippedModuleOfSubType()[ERROR]: invalid type of the 3-rd parameter (\"slotIdToIgnore\"); \"number\" expected, got \"%s\"", type( slotIdToIgnore ) )
		return false
	end

	local shipItem = UI:GetShipItem( vid, true )
	if not shipItem then
		sys.log( "UI:HasShipEquippedModuleOfSubType()[ERROR]: cannot find ship item for vid %s", _G.U64ToStr( vid ) )
		return false
	end

	for slotId = ai.SpaceShipModuleSlot.ACTIVE_01, ai.SpaceShipModuleSlot.CPU_MOD_03 do

		if slotId ~= slotIdToIgnore then

    		local iid = shipItem.equipModules[ slotId ]
    		if iid and iid ~= UI.INVALID_U64_ID then

    			local inventoryItem = UI:GetInventoryItemEx( iid )
    			if inventoryItem and UI:GetItemSubType( inventoryItem.defName ) == subType then
					return true
    			end

    		end

		end

	end

	return false

end


--
function UI:IsItemUniqueEquip( defName )

	local bUnique = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsItemUniqueEquip()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bUnique
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsItemUniqueEquip()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return bUnique
	end

	if def.unique_equip == nil then
		return bUnique
	end

	if type( def.unique_equip ) == "boolean" then
		bUnique = def.unique_equip
	else
		sys.log( "UI:IsItemUniqueEquip()[ERROR]: invalid type of _G.Def[\"%s\"].unique_equip; \"boolean\" or \"nil\" expected, got \"%s\"", type( def.unique_equip ) )
	end

	return bUnique

end


--
function UI:IsItemLimitedEquip( defName )

	local bLimited = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsItemLimitedEquip()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bLimited
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsItemLimitedEquip()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return bLimited
	end

	if def.tags_mask ~= nil then
		if type( def.tags_mask ) == "number" then
			if bit.band( def.tags_mask, ai.ModuleTagsMask.UNIQUE ) == ai.ModuleTagsMask.UNIQUE then
				bLimited = true
			end
		else
			sys.log( "UI:IsItemLimitedEquip()[ERROR]: invalid type of _G.Def[\"%s\"].tags_mask; \"number\" or \"nil\"expected, got \"%s\"", type( def.tags_mask ) )
		end
	end

	return bLimited

end


--
function UI:GetKarmaMaxLevel()

	local maxLevel = 0

	if type( _G.KarmaValueToLevel ) == "table" then
		maxLevel = #_G.KarmaValueToLevel
	else
		sys.log( "UI:GetKarmaMaxLevel()[ERROR]: invalid type of \"_G.KarmaValueToLevel\"; \"table\" expected, got \"%s\"", type( _G.KarmaValueToLevel ) )
	end

	return maxLevel

end


--
function UI:Karma2Level( karma )

	local level = 0

	if type( karma ) ~= "number" then
		sys.log( "UI:Karma2KarmaRank()[ERROR]: invalid type of the 1-st parameter (\"karma\"); \"number\" expected, got \"%s\"", type( karma ) )
		return level
	end

	if type( _G.KarmaValueToLevel ) ~= "table" then
		sys.log( "UI:Karma2KarmaRank()[ERROR]: invalid type of \"_G.KarmaValueToLevel\"; \"table\" expected, got \"%s\"", type( _G.KarmaValueToLevel ) )
		return level
	end

	for lv = #_G.KarmaValueToLevel, 1, -1 do

		local val = _G.KarmaValueToLevel[ lv ]
		if math.abs( karma ) >= val then

			level = lv

			if karma < 0 then
				level = -level
			end

			break

		end

	end

	return level

end


--
function UI:FactionRep2Level( rep )

	local level = 0

	if type( rep ) ~= "number" then
		sys.log( "UI:FactionRep2Level()[ERROR]: invalid type of the 1-st parameter (\"rep\"); \"number\" expected, got \"%s\"", type( rep ) )
		return level
	end

	if type( _G.FactionRepToLevel ) ~= "table" then	
		sys.log( "UI:FactionRep2Level()[ERROR]: invalid type of \"_G.FactionRepToLevel\"; \"table\" expected, got \"%s\"", type( _G.FactionRepToLevel ) )
		return level
	end 

	for lv = #_G.FactionRepToLevel, 1, -1 do

		local val = _G.FactionRepToLevel[ lv ]
		if math.abs( rep ) >= val then

			level = lv

			if rep < 0 then
				level = -level
			end

			break

		end

	end

	return level

end


--
function UI:GetFactionRepLevelColor( repLevel )

	local baseColor = UI.WHITE_COLOR
	if math.abs( repLevel ) > _G.NeutralFactionRepLevelMax then
		if repLevel >= 0 then
			baseColor = UI.FRIEND_COLOR
		else
			baseColor = UI.ENEMY_COLOR
		end
	end

	return baseColor
end


--
function UI:FactionRep2ColoredStr( rep )

	local repLevel = UI:FactionRep2Level( rep )
	local levelColor = UI:GetFactionRepLevelColor( repLevel )

	local tSubst =
	{
		level	= string.format( "%s%d", UI:Color2Str( levelColor ), repLevel ),
		val		= UI:Num2StrSeparatedBy3( rep ),
	}
	local strVal = UI:GetStringByName( "hud_playerStatus_factionRep" )
	strVal = string.gsub( strVal, "%$(.-)%$", tSubst )
	
	return strVal

end


function UI:IsFactionRepVisible( faction, rep )
	return ( faction ~= ai.Faction.CYBER_2 or rep > _G.DefaultFactionRep[ faction ] ) and cvars.sv_factionRepEnabledTemp ~= 0
end


