--
function UI:GetZoneNameForStationByRace( race )

	local zoneName = ""

	if type( race ) ~= "number" then
		sys.log( "UI:ZoneStation2Str()[ERROR]: invalid type of the 1-st parameter (\"race\"); \"number\" expected, got \"%s\"", type( race ) )
		return zoneName
	end

	if _G.SpaceZone then
		for name, info in pairs( _G.SpaceZone ) do

			if info.space_station == true and info.station_race == race then
				zoneName = name
				break
			end

		end
	end

	return zoneName

end


--
function UI:GetZoneStationRace( zoneId )

	local race = -1

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetZoneStationRace()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return race
	end

	if type( _G.SpaceZoneById ) ~= "table" then
		sys.log( "UI:GetZoneStationRace()[ERROR]: invalid type of the \"_G.SpaceZoneById\"; \"table\" expected, got \"%s\"", type( _G.SpaceZoneById ) )
		return race
	end

	local zoneDesc = _G.SpaceZoneById[ zoneId ]
	if type( zoneDesc ) ~= "table" then
		sys.log( "UI:GetZoneStationRace()[ERROR]: invalid type of the \"_G.SpaceZoneById[%d]\"; \"table\" expected, got \"%s\"", zoneId, type( zoneDesc ) )
		return race
	end

	if zoneDesc.station_race ~= nil then
    	if type( zoneDesc.station_race ) == "number" then
			race = zoneDesc.station_race
		else
    		sys.log( "UI:GetZoneStationRace()[ERROR]: invalid type of the \"_G.SpaceZoneById[%d].station_race\"; \"number\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneDesc.station_race ) )
    	end
	end

	return race

end


