--
function UI:GetSubRegionForZone( zoneName )

	local subRegionName = ""

	if type( zoneName ) ~= "string" then
		sys.log( "UI:GetSubRegionForZone()[ERROR]: invalid type of the 1-st parameter (\"zoneName\"); \"string\" expected, got \"%s\"", type( zoneName ) )
		return subRegionName
	end

	if type( _G.FreeSpaceMap ) == "table" then

		if type( _G.FreeSpaceMap.SubRegions ) == "table" then

			for _subRegionName, subRegionInfo in pairs( _G.FreeSpaceMap.SubRegions ) do

				if type( _subRegionName ) == "string" and type( subRegionInfo ) == "table" then

					if type( subRegionInfo.zones ) == "table" then

						for zoneIdx, _zoneName in pairs( subRegionInfo.zones ) do

							if type( zoneIdx ) == "number" and type( _zoneName ) == "string" then

								if _zoneName == zoneName then
									subRegionName = _subRegionName
									break
								end

							else
								sys.log( "UI.GetSubRegionForZone()[ERROR]: invalid format of _G.FreeSpaceMap.SubRegions[\"%s\"].zones table; <number>=<string> expected, got <%s>=<%s>", _subRegionName, type( zoneIdx ), type( _zoneName ) )
							end

						end

					else
						sys.log( "UI.GetSubRegionForZone()[ERROR]: invalid type of _G.FreeSpaceMap.SubRegions[\"%s\"].zones; \"table\" expected, got \"%s\"", _subRegionName, type( subRegionInfo.zones ) )
					end

				else
					sys.log( "UI.GetSubRegionForZone()[ERROR]: invalid format of _G.FreeSpaceMap.SubRegions table; <string>=<table> expected, got <%s>=<%s>", type( _subRegionName ), type( subRegionInfo ) )
				end

			end

		else
			sys.log( "UI.GetSubRegionForZone()[ERROR]: invalid type of _G.FreeSpaceMap.SubRegions; \"table\" expected, got \"%s\"", type( _G.FreeSpaceMap.SubRegions ) )
		end

	else
		sys.log( "UI.GetSubRegionForZone()[ERROR]: invalid type of _G.FreeSpaceMap; \"table\" expected, got \"%s\"", type( _G.FreeSpaceMap ) )
	end

	return subRegionName

end


--
function UI:GetZoneForLevel( levelName )

	local zoneName = ""

	if type( levelName ) ~= "string" then
		sys.log( "UI:GetZoneForLevel()[ERROR]: invalid type of the 1-st parameter (\"levelName\"); \"string\" expected, got \"%s\"", type( levelName ) )
		return zoneName
	end

	if type( _G.SpaceZone ) ~= "table" then
		sys.log( "UI:GetZoneForLevel()[ERROR]: invalid type of _G.SpaceZone; \"table\" expected, got \"%s\"", type( _G.SpaceZone ) )
		return zoneName
	end

	for _zoneName, zoneDef in pairs( _G.SpaceZone ) do

		if type( zoneDef.level_name ) == "string" then
			if zoneDef.level_name == levelName then
				zoneName = _zoneName
				break
			end
		else
			sys.log( "UI:GetZoneDifficulty()[ERROR]: invalid type of _G.SpaceZone[\"%s\"].level_name; \"string\" expected, got \"%s\"", zoneName, type( zoneDef.level_name ) )
		end

	end

	return zoneName

end


--
function UI:SubRegion2Str( subRegionName, bUpper )

	local str = "unknown"

	if type( subRegionName ) ~= "string" then
		sys.log( "UI:SubRegion2Str()[ERROR]: invalid type of the 1-st parameter (\"subRegionName\"); \"string\" expected, got \"%s\"", type( subRegionName ) )
		return str
	end

	if bUpper ~= nil then
		if type( bUpper ) ~= "boolean" then
			sys.log( "UI:SubRegion2Str()[ERROR]: invalid type of the 2-nd parameter (\"bUpper\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bUpper ) )
			bUpper = nil
		end
	end

	if bUpper == nil then
		bUpper = false
	end

	local strId = string.format( "gameplay_subregion_%s_name", subRegionName )

	if bUpper then
		strId = string.format( "%s_upper", strId )
	end

	str = UI:GetStringByName( strId )

	return str

end


--
function UI:GetZoneDescShort( zoneName, baseColor, bShowCivilianChangeTime )

	local str = ""

	if type( zoneName ) ~= "string" then
		sys.log( "UI:GetZoneDescShort()[ERROR]: invalid type of the 1-st parameter (\"zoneName\"); \"string\" expected, got \"%s\"", type( zoneName ) )
		return str
	end

	if baseColor ~= nil then
		if type( baseColor ) ~= "number" then
			sys.log( "UI:GetZoneDescShort()[ERROR]: invalid type of the 2-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
		end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if bShowCivilianChangeTime ~= nil then
		if type( bShowCivilianChangeTime ) ~= "boolean" then
			sys.log( "UI:GetZoneDescShort()[ERROR]: invalid type of the 2-nd parameter (\"bShowCivilianChangeTime\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bShowCivilianChangeTime ) )
			baseColor = nil
		end
	end

	if bShowCivilianChangeTime == nil then
		bShowCivilianChangeTime = false
	end

	local zoneId = UI:ZoneName2Id( zoneName )
	local bAllowedForTransfer = UI:IsZoneAllowedForTransfer( zoneId )

	-- субрегион

	local subRegionName = UI:GetSubRegionForZone( zoneName )
	if subRegionName ~= "" then

		local strSubRegionLocalizedName = UI:SubRegion2Str( subRegionName )
		local strSubRegion = string.format( "%s: %s", UI:GetStringByName( "subRegion" ), strSubRegionLocalizedName )
		str = string.format( "%s%s%s", str, str ~= "" and "|" or "", strSubRegion )

	end

	-- сложность

	if bAllowedForTransfer then	-- #0109011(0511427)

		local strDifficultyVal = UI:ZoneDifficulty2Str( UI:GetZoneDifficulty( zoneName ) )
		strDifficulty = string.format( "%s: %s", UI:GetStringByName( "zoneDifficulty" ), strDifficultyVal )
		str = string.format( "%s%s%s", str, str ~= "" and "|" or "", strDifficulty )

	end

	-- защита станции

	if bAllowedForTransfer then	-- #0109011(0511427)

		local strCivilian = ""

		if UI:IsZoneCivilian( zoneName ) then
			strCivilian = UI:GetStringByName( "level_civilian" )
		else
			strCivilian = string.format( "%s%s%s", UI:Color2Str( UI.RED_COLOR ), UI:GetStringByName( "level_not_civilian" ), UI:Color2Str( baseColor ) )
		end

		if bShowCivilianChangeTime then

			local zoneUniverseData = UI.Universe:GetSectorById( zoneId, false )

			if zoneUniverseData and type( zoneUniverseData.civilianTime ) == "userdata" and zoneUniverseData.civilianTime ~= UI.INVALID_U64_ID then

				if _G.MasterServer_IsConnected() then

					local curTime = _G.MasterServer_GetServerTime()

					local timeLeft = 0
					if zoneUniverseData.civilianTime > curTime then
						timeLeft = ( zoneUniverseData.civilianTime - curTime ).l * 0.001
					end

					local strTime = UI:Time2Str45( timeLeft )

					local YELLOW_COLOR	= 0xffffff00
					strTime = string.format( "%s(%s)%s", UI:Color2Str( YELLOW_COLOR ), strTime, UI:Color2Str( baseColor ) )

					strCivilian = string.format( "%s %s", strCivilian, strTime )

				end

			end

		end

		str = string.format( "%s%s%s", str, str ~= "" and "|" or "", strCivilian )

	end

	return str

end


