	end

	local zoneDef = _G.SpaceZone[ zoneName ]
	if type( zoneDef ) ~= "table" then
		sys.log( "UI:GetZoneDifficulty()[ERROR]: invalid type of _G.SpaceZone[\"%s\"]; \"table\" expected, got \"%s\"", zoneName, type( zoneDef ) )
		return difficulty
	end

	if type( zoneDef.difficulty ) == "string" then
		difficulty = zoneDef.difficulty
