--
function UI:IsZoneCivilian( zoneName )

	local bCivilian = false

	if type( zoneName ) ~= "string" then
		sys.log( "UI:IsZoneCivilian()[ERROR]: invalid type of the 1-st parameter (\"zoneName\"); \"string\" expected, got \"%s\"", type( zoneName ) )
		return bCivilian
	end


	local zoneId = UI:ZoneName2Id( zoneName )
	local zoneUniverseData = UI.Universe:GetSectorById( zoneId, false )

	if zoneUniverseData then

		if type( zoneUniverseData.isCivilian ) == "boolean" then
			bCivilian = zoneUniverseData.isCivilian
		else
			sys.log( "UI:IsZoneCivilian()[ERROR]: invalid type \"isCivilian\" for zone %d(%s); \"boolean\" expected, got \"%s\"", zoneId, zoneName, type( zoneUniverseData.isCivilian ) )
		end

	else

		if type( _G.SpaceZone ) ~= "table" then
			sys.log( "UI:IsZoneCivilian()[ERROR]: invalid type of _G.SpaceZone; \"table\" expected, got \"%s\"", type( _G.SpaceZone ) )
			return bCivilian
		end

		local zoneDef = _G.SpaceZone[ zoneName ]
		if type( zoneDef ) ~= "table" then
			sys.log( "UI:IsZoneCivilian()[ERROR]: invalid type of _G.SpaceZone[\"%s\"]; \"table\" expected, got \"%s\"", zoneName, type( zoneDef ) )
			return bCivilian
		end

		if zoneDef.civilian_zone ~= nil then
			if type( zoneDef.civilian_zone ) == "boolean" then
				bCivilian = zoneDef.civilian_zone
			else
				sys.log( "UI:IsZoneCivilian()[ERROR]: invalid type of _G.SpaceZone[\"%s\"].civilian_zone; \"boolean\" expected, got \"%s\"", zoneName, type( zoneDef.civilian_zone ) )
			end
		end

	end

	return bCivilian

end


