function UI:GetZoneShipRanks( zoneId )

	local minRank = -1
	local maxRank = -1

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetZoneShipRanks()[ERROR]: invalid type of the 1-st param ('zoneId'); 'number' expected, got '%s'", type( zoneId ) )
		return minRank, maxRank
	end

	if type( _G.SpaceZoneById ) ~= "table" then
		sys.log( "UI:GetZoneShipRanks()[ERROR]: invalid type of the \"_G.SpaceZoneById\"; \"table\" expected, got \"%s\"", type( _G.SpaceZoneById ) )
		return minRank, maxRank
	end

	local zoneDesc = _G.SpaceZoneById[ zoneId ]
	if type( zoneDesc ) ~= "table" then
		sys.log( "UI:GetZoneShipRanks()[ERROR]: invalid type of the \"_G.SpaceZoneById[%d]\"; \"table\" expected, got \"%s\"", zoneId, type( zoneDesc ) )
		return minRank, maxRank
	end

	if zoneDesc.universeMinShipRank ~= nil then
    	if type( zoneDesc.universeMinShipRank ) == "number" then
			minRank = zoneDesc.universeMinShipRank
		else
    		sys.log( "UI:GetZoneShipRanks()[ERROR]: invalid type of the \"_G.SpaceZoneById[%d].universeMinShipRank\"; \"number\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneDesc.universeMinShipRank ) )
    	end
	end

	if zoneDesc.universeMaxShipRank ~= nil then
    	if type( zoneDesc.universeMaxShipRank ) == "number" then
			maxRank = zoneDesc.universeMaxShipRank
		else
    		sys.log( "UI:GetZoneShipRanks()[ERROR]: invalid type of the \"_G.SpaceZoneById[%d].universeMaxShipRank\"; \"number\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneDesc.universeMaxShipRank ) )
    	end
	end

	return minRank, maxRank

end


--
function UI:GetPlayerTooltip( uid )

	local tooltipData = nil

	if type( uid ) ~= "userdata" then
		sys.log( "UI:GetPlayerTooltip()[ERROR]: invalid type of the 1-st parameter (\"uid\"); \"userdata\" expected, got \"%s\"", type( uid ) )
		return tooltipData
	end

	if uid == UI.INVALID_U64_ID then
		sys.log( "UI:GetPlayerTooltip()[ERROR]: invalid uid" )
		return tooltipData
	end


	tooltipData = {}

	tooltipData.tooltipType = UI.tooltipTypes.TEXT_LARGE
	tooltipData.text = ""


	-- никнейм

	tooltipData.caption = UI:MakePlayerNameByUid( uid, false, false, false )


	-- клан

	local clanName = ""

	local cid = UI:GetPlayerClanByUid( uid )

	if cid ~= UI.INVALID_U64_ID then
		clanName = UI:GetClanName( cid )
	end

	if clanName ~= "" then

		local strClanNameLabel = UI:GetStringByName( "hud_playerTooltip_clanLabel" )
		local strClanNameVal = UI:ShieldSpecSymbols( clanName )
		local strClanName = string.format( "%s: %s", strClanNameLabel, strClanNameVal )

		tooltipData.text = string.format( "%s%s%s", tooltipData.text, tooltipData.text ~= "" and "|" or "", strClanName )

	end


	-- количество убийств

	_G.MasterServer_UserProfileRequestField( uid, _G.MasterServer.UserProfileField.UPF_GENERAL_STATS )

    local profile = _G.MasterServer_UserProfileGet( uid )
	local generalStats = profile and profile.generalStats
	local rating = generalStats and generalStats[ _G.MasterServer.UserProfileGeneralStat.UPGS_RATING ] or UI.INVALID_U64_ID

	local strRatingLabel = UI:GetStringByName( "hud_playerTooltip_killsLabel" )
	local strRatingVal = _G.I64ToStr( rating )
	local strRating = string.format( "%s: %s", strRatingLabel, strRatingVal )

	tooltipData.text = string.format( "%s%s%s", tooltipData.text, tooltipData.text ~= "" and "|" or "", strRating )

	return tooltipData

end


--
function UI:CanItemBeSalvaged( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:CanItemBeSalvaged()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	if UI:IsDefAutogen( defName ) then
		return false
	end

	if not UI:IsDefModule( defName ) then
		return false
	end

	local shopItem = self.serverData.shopByDef[ defName ]
	if not shopItem then
		sys.log( "UI:CanItemBeSalvaged()[ERROR]: cannot find shop item for \"%s\"", defName )
		return false
	end

	local refundForCredits	= shopItem.salvageTokenRefund or 0
	local refundForGold		= shopItem.salvagePremiumTokenRefund or 0

	return refundForCredits > 0 or refundForGold > 0

end


-- другой метод сальведжа (используются другие функции сервера для работы с ним)
function UI:CanItemBeSalvaged2( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:CanItemBeSalvaged2()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	if UI:IsDefAutogen( defName ) then
		return false
	end

	if not UI:IsDefModule( defName ) then
		return false
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:CanItemBeSalvaged2()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return false
	end

	if def.salvage == nil then
		return false
	end

	if type( def.salvage ) ~= "table" then
		sys.log( "UI:CanItemBeSalvaged2()[ERROR]: invalid type of _G.Def[\"%s\"].salvage; \"table\" or \"nil\" expected, got \"%s\"", defName, type( def.salvage ) )
		return false
	end

	return true

end


--
function UI:GetSalvageRefundItems( defName )

	local items = {}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetSalvageRefundItems()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return items
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetSalvageRefundItems()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return items
	end

	if def.salvage == nil then
		return items
	end

	if type( def.salvage ) ~= "table" then
		sys.log( "UI:GetSalvageRefundItems()[ERROR]: invalid type of _G.Def[\"%s\"].salvage; \"table\" or \"nil\" expected, got \"%s\"", defName, type( def.salvage ) )
		return items
	end

	for itemIdx, itemData in ipairs( def.salvage ) do

		if type( itemData ) == "table" then

			if type( itemData.def ) == "string" then

				local count = 1

				if itemData.count ~= nil then

					if type( itemData.count ) == "number" then
						count = itemData.count
					else
						sys.log( "UI:GetSalvageRefundItems()[ERROR]: invalid type of _G.Def[\"%s\"].salvage[%d].count; \"number\" or \"nil\" expected, got \"%s\"", defName, itemIdx, type( itemData.count ) )
					end

				end

				local item =
				{
					defName	= itemData.def,
					count	= count,
				}

				table.insert( items, item )


			else
				sys.log( "UI:GetSalvageRefundItems()[ERROR]: invalid type of _G.Def[\"%s\"].salvage[%d].def; \"string\" expected, got \"%s\"", defName, itemIdx, type( itemData.def ) )
			end

		else
			sys.log( "UI:GetSalvageRefundItems()[ERROR]: invalid type of _G.Def[\"%s\"].salvage[%d]; \"table\" expected, got \"%s\"", defName, itemIdx, type( itemData ) )
		end

	end

	return items

end


--
function UI:GetSalvageRefundIridium( defName, bForGold )

	local iridium = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetSalvageRefundIridium()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return iridium
	end

	if type( bForGold ) ~= "boolean" then
		sys.log( "UI:GetSalvageRefundIridium()[ERROR]: invalid type of the 2-nd parameter (\"bForGold\"); \"boolean\" expected, got \"%s\"", type( bForGold ) )
		return iridium
	end

	local shopItem = UI:GetShopItemByDef( defName )
	if not shopItem then
		sys.log( "UI:GetSalvageRefundIridium()[ERROR]: cannot find shop item for \"%s\"", defName )
		return iridium
	end

	if bForGold then
		iridium = shopItem.salvagePremiumTokenRefund or 0
	else
		iridium = shopItem.salvageTokenRefund or 0
	end

	return iridium

end


--
function UI:IsInventoryItemEnchanted( item )

	if type( item ) ~= "table" then
		sys.log( "UI:IsInventoryItemEnchanted()[ERROR]: invalid type of the 1-st parameter (\"item\"); \"table\" expected, got \"%s\"", type( item ) )
		return false
	end

	if type( item.defName ) == "string" and UI:IsDefAutogen( item.defName ) then
		return false
	end

	if type( item.enchantments ) ~= "number" then
		sys.log( "UI:IsInventoryItemEnchanted()[ERROR]: invalid type of the field \"enchantments\"; \"number\" expected, got \"%s\"", type( item.enchantments ) )
		return false
	end

	return item.enchantments ~= 0

end


--
function UI:IsInventoryItemEnchantedById( iid )

	local item, bAutogen = UI:GetInventoryItemEx( iid )

	if bAutogen then
		return false
	else
		return UI:IsInventoryItemEnchanted( item )
	end

end


--
function UI:GetEnchantedItemSynergyBonus( iid )

	local bonus = 0

	if type( iid ) ~= "userdata" then
		sys.log( "UI:GetEnchantedItemSynergyBonus()[ERROR]: invalid type of the 1-st parameter (\"iid\"); \"userdata\" expected, got \"%s\"", type( iid ) )
		return bonus
	end

	if iid == UI.INVALID_U64_ID then
		sys.log( "UI:GetEnchantedItemSynergyBonus()[ERROR]: invalid iid" )
		return bonus
	end

	local inventoryItem = UI:GetInventoryItem( iid )
	if not inventoryItem then
		sys.log( "UI:GetEnchantedItemSynergyBonus()[ERROR]: cannot find inventory item" )
		return bonus
	end

	if not UI:IsInventoryItemEnchanted( inventoryItem ) then
		sys.log( "UI:GetEnchantedItemSynergyBonus()[ERROR]: item is not enchanted" )
		return bonus
	end

	bonus = UI:GetEnchantedItemSynergyBonusByDefName( inventoryItem.defName )

	return bonus

end


