	local bonus = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEnchantedItemSynergyBonusByDefName()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bonus
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetEnchantedItemSynergyBonusByDefName()[ERROR]: cannot find _G.Def[%s]", defName )
		return bonus
	end

	if def.enchant_exp_mul ~= nil then
    	if type( def.enchant_exp_mul ) == "number" then
			bonus = def.enchant_exp_mul
		else
			sys.log( "UI:GetEnchantedItemSynergyBonusByDefName()[ERROR]: invalid type of _G.Def[%s].enchant_exp_mul; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.enchant_exp_mul ) )
    	end
	end

	return bonus

end


-- отсчет с 1
function UI:GetItemUpgradeLevel( defName )

	local level = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemUpgradeLevel()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return level
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemUpgradeLevel()[ERROR]: cannot find \"_G.Def[%s]\"", defName )
		return level
	end

	if UI:IsDefAutogen( defName ) then

		local itemQuality = def.mark or -1

		for upgradeLevel, quality in pairs( UI.autogenQualities ) do
			if quality == itemQuality then
				level = upgradeLevel
				break
			end
		end

	else

		if def.current_upgrade_level ~= nil then
			if type( def.current_upgrade_level ) == "number" then
				level = def.current_upgrade_level
			else
				sys.log( "UI:GetItemUpgradeLevel()[ERROR]: invalid type of the \"_G.Def[%s].current_upgrade_level\"; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.current_upgrade_level ) )
			end
		end

	end

	return level

end


-- отсчет с 1
function UI:GetItemUpgradeMinLevel( defName )

	local minLevel = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemUpgradeMinLevel()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return minLevel
	end

	if UI:IsDefAutogen( defName ) then
		return 1
	end

	local curLevel = UI:GetItemUpgradeLevel( defName )

	if curLevel == -1 then
		minLevel = -1

	else
		minLevel = curLevel

		local prevDefName = self:GetItemUpgradePrevDef( defName )
		if prevDefName ~= "" then

			while prevDefName ~= "" do

				local prevLevel = UI:GetItemUpgradeLevel( prevDefName )
				if prevLevel ~= -1 then
					minLevel = prevLevel
				else
					sys.log( "UI:GetItemUpgradeMinLevel()[ERROR]: one of next defs \"%s\" for original def \"%s\" don't have upgrade level", defName, prevDefName )
					break
				end

				prevDefName = self:GetItemUpgradePrevDef( prevDefName )

			end

		end

	end

	return minLevel

end


-- отсчет с 1
function UI:GetItemUpgradeMaxLevel( defName, bIncludeDeprecated )

	local maxLevel = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemUpgradeMaxLevel()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return maxLevel
	end

	if bIncludeDeprecated ~= nil then
		if type( bIncludeDeprecated ) ~= "boolean" then
			sys.log( "UI:GetItemUpgradeMaxLevel()[ERROR]: invalid type of the 2-nd parameter (\"bIncludeDeprecated\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIncludeDeprecated ) )
			bIncludeDeprecated = nil
		end
	end

	if bIncludeDeprecated == nil then
		bIncludeDeprecated = false
	end

	if UI:IsDefAutogen( defName ) then
		return UI.AUTOGEN_MAX_UPGRADE_LEVEL
	end

	local curLevel = UI:GetItemUpgradeLevel( defName )

	if curLevel == -1 then
		maxLevel = -1

	else
		maxLevel = curLevel

		local nextDefName = self:GetItemUpgradeNextDef( defName, bIncludeDeprecated )
		if nextDefName ~= "" then

			while nextDefName ~= "" do

				local nextLevel = UI:GetItemUpgradeLevel( nextDefName )
				if nextLevel ~= -1 then
					maxLevel = nextLevel
				else
					sys.log( "UI:GetItemUpgradeMaxLevel()[ERROR]: one of next defs \"%s\" for original def \"%s\" don't have upgrade level", defName, nextDefName )
					break
				end

				nextDefName = self:GetItemUpgradeNextDef( nextDefName, bIncludeDeprecated )

			end

		end

	end

	return maxLevel

end


--
function UI:GetItemUpgradeNextDef( defName, bIncludeDeprecated )

	local nextDefName = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemUpgradeNextDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return nextDefName
	end

	if UI:IsDefAutogen( defName ) then
		sys.log( "UI:GetItemUpgradeNextDef()[ERROR]: not supported for autogen" )
		return nextDefName
	end

	if bIncludeDeprecated ~= nil then
		if type( bIncludeDeprecated ) ~= "boolean" then
			sys.log( "UI:GetItemUpgradeNextDef()[ERROR]: invalid type of the 2-nd parameter (\"bIncludeDeprecated\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIncludeDeprecated ) )
			bIncludeDeprecated = nil
		end
	end

	if bIncludeDeprecated == nil then
		bIncludeDeprecated = false
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemUpgradeNextDef()[ERROR]: cannot find \"_G.Def[%s]\"", defName )
		return nextDefName
	end

	if def.next_upgrade ~= nil then
		if type( def.next_upgrade ) == "string" then
			nextDefName = def.next_upgrade
		else
			sys.log( "UI:GetItemUpgradeNextDef()[ERROR]: invalid type of the \"_G.Def[%s].next_upgrade\"; \"string\" or \"nil\" expected, got \"%s\"", defName, type( def.next_upgrade ) )
		end
	end

	if nextDefName ~= "" and not bIncludeDeprecated then

		if UI:IsItemUpgradeDefDeprecated( nextDefName ) then

			-- #0099535 - если есть чертеж, то этот уровень апгрейда учитываем
			local bHasBlueprint = false

			if UI:CanUpgradeItemThroughCraftOnly( defName ) then

				local blueprints = UI:GetAllBlueprintsForItemCraft( nextDefName )
				for blueprintIdx, blueprintDefName in pairs( blueprints ) do
					if UI:IsBluePrintLearned( blueprintDefName ) then
						bHasBlueprint = true
						break
					end
				end

			end

			if not bHasBlueprint then
				nextDefName = ""
			end

		end

	end

	return nextDefName

end


--
function UI:GetItemUpgradePrevDef( defName )

	local prevDefName = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemUpgradePrevDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return prevDefName
	end

	if UI:IsDefAutogen( defName ) then
		sys.log( "UI:GetItemUpgradePrevDef()[ERROR]: not supported for autogen" )
		return prevDefName
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemUpgradePrevDef()[ERROR]: cannot find \"_G.Def[%s]\"", defName )
		return prevDefName
	end

	if def.prev_upgrade ~= nil then
		if type( def.prev_upgrade ) == "string" then
			prevDefName = def.prev_upgrade
		else
			sys.log( "UI:GetItemUpgradePrevDef()[ERROR]: invalid type of the \"_G.Def[%s].prev_upgrade\"; \"string\" or \"nil\" expected, got \"%s\"", defName, type( def.prev_upgrade ) )
		end
	end

	if prevDefName ~= "" and UI:IsItemUpgradeDefDeprecated( prevDefName ) then
		sys.log( "UI:GetItemUpgradePrevDef()[ERROR]: deprecated module %s is not the last in upgrade chain; handling upgrade chain may be corrupted", prevDefName )
	end

	return prevDefName

end


-- curDefName - деф любого уровня в цепочке апгрейда
function UI:GetItemUpgradeDefForLevel( curDefName, level, bIncludeDeprecated )

	local defName = ""

	if type( curDefName ) ~= "string" then
		sys.log( "UI:GetItemUpgradeDefForLevel()[ERROR]: invalid type of the 1-st parameter (\"curDefName\"); \"string\" expected, got \"%s\"", type( curDefName ) )
		return defName
	end

	if UI:IsDefAutogen( curDefName ) then
		sys.log( "UI:GetItemUpgradeDefForLevel()[ERROR]: not supported for autogen" )
		return defName
	end

	if type( level ) ~= "number" then
		sys.log( "UI:GetItemUpgradeDefForLevel()[ERROR]: invalid type of the 2-nd parameter (\"level\"); \"number\" expected, got \"%s\"", type( level ) )
		return defName
	end

	if bIncludeDeprecated ~= nil then
		if type( bIncludeDeprecated ) ~= "boolean" then
			sys.log( "UI:GetItemUpgradeDefForLevel()[ERROR]: invalid type of the 3-rd parameter (\"bIncludeDeprecated\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIncludeDeprecated ) )
			bIncludeDeprecated = nil
		end
	end

	if bIncludeDeprecated == nil then
		bIncludeDeprecated = false
	end

	local curLevel = UI:GetItemUpgradeLevel( curDefName )

	if curLevel < level then

		local dn = UI:GetItemUpgradeNextDef( curDefName, bIncludeDeprecated )
		while dn ~= "" do

			local lv = UI:GetItemUpgradeLevel( dn )

			if lv == level then
				defName = dn
				break

			elseif lv > level then
				break
			end

			dn = UI:GetItemUpgradeNextDef( dn, bIncludeDeprecated )

		end

	elseif curLevel > level then

		local dn = UI:GetItemUpgradePrevDef( curDefName )
		while dn ~= "" do

			local lv = UI:GetItemUpgradeLevel( dn )

			if lv == level then
				defName = dn
				break

			elseif lv < level then
				break
			end

			dn = UI:GetItemUpgradePrevDef( dn )

		end

	else
		defName = curDefName
	end

	return defName

end


-- curDefName - деф любого уровня в цепочке апгрейда
function UI:GetItemUpgradeBaseDef( curDefName )

	if UI:IsDefAutogen( curDefName ) then
		return curDefName
	else
		return UI:GetItemUpgradeDefForLevel( curDefName, UI:GetItemUpgradeMinLevel( curDefName ) )
	end

end


-- #0097990 - если у дефа модуля, который стоит в цепочке апгрейда, прописан флаг HideFromPlayer=true, то до него нельзя улучшать (сейчас поддерживается только если такой модуль стоит в цепочке последним)
function UI:IsItemUpgradeDefDeprecated( defName )

	return UI:IsDefHidden( defName )

end


--
function UI:IsDefHidden( defName )

	local bHidden = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsDefHidden()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bHidden
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsDefHidden()[ERROR]: cannot find def %s", defName )
		return bHidden
	end

	if def.HideFromPlayer ~= nil then
		if type( def.HideFromPlayer ) == "boolean" then
			bHidden = def.HideFromPlayer
		else
			sys.log( "UI:IsDefHidden()[ERROR]: invalid type of _G.Def[\"%s\"].HideFromPlayer; \"boolean\" or \"nil\" expected, got \"%s\"", defName, type( def.HideFromPlayer ) )
		end
	end

	return bHidden

end


--
function UI:IsPriceInfoValid( priceInfo )

	if type( priceInfo ) ~= "table" then
		sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the 1-st parameter (\"priceInfo\"); \"table\" expected, got \"%s\"", type( priceInfo ) )
		return false
	end

	if type( priceInfo.priceType ) ~= "number" then
		sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"priceType\"; \"number\" expected, got \"%s\"", type( priceInfo.priceType ) )
		return false
	end

	if UI:Val2Key( _G.GameStore.CreditsType, priceInfo.priceType ) == "" and UI:Val2Key( UI.exPriceTypes, priceInfo.priceType ) == "" then
		sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid priceType; one of the \"_G.GameStore.CreditsType\" or \"UI.exPriceTypes\" values expected, get %d", priceInfo.priceType )
		return false
	end

	if type( priceInfo.val ) ~= "number" then
		sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"val\"; \"number\" expected, got \"%s\"", type( priceInfo.val ) )
		return false
	end

	if type( priceInfo.bIsBuyPrice ) ~= "boolean" then
		sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"bIsBuyPrice\"; \"boolean\" expected, got \"%s\"", type( priceInfo.bIsBuyPrice ) )
		return false
	end

	if priceInfo.bIsBuyPrice then

		if type( priceInfo.basePrice ) ~= "number" then
			sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"basePrice\"; \"number\" expected, got \"%s\"", type( priceInfo.basePrice ) )
			return false
		end

		if priceInfo.bDisableFree ~= nil then
			if type( priceInfo.bDisableFree ) ~= "boolean" then
				sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"bDisableFree\"; \"boolean\" or \"nil\" expected, got \"%s\"", type( priceInfo.bDisableFree ) )
				return false
			end
		end

	end

	if priceInfo.valAsString ~= nil then
		if type( priceInfo.valAsString ) ~= "string" then
			sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"valAsString\"; \"string\" or \"nil\" expected, got \"%s\"", type( priceInfo.valAsString ) )
			return false
		end
	end

	if priceInfo.bIcoFirst ~= nil then
		if type( priceInfo.bIcoFirst ) ~= "boolean" then
			sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"bIcoFirst\"; \"boolean\" or \"nil\" expected, got \"%s\"", type( priceInfo.bIcoFirst ) )
			return false
		end
	end

	if priceInfo.priceType == UI.exPriceTypes.SHIP_PARTS then

		if type( priceInfo.defName ) ~= "string" then
			sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"defName\"; \"string\" expected, got \"%s\"", type( priceInfo.defName ) )
			return false
		end

	elseif priceInfo.priceType == UI.exPriceTypes.SPEC_MODULE_PARTS then

		if type( priceInfo.shipDefName ) ~= "string" then
			sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"shipDefName\"; \"string\" expected, got \"%s\"", type( priceInfo.shipDefName ) )
			return false
		end

	elseif priceInfo.priceType == UI.exPriceTypes.SYNERGY then

		if priceInfo.vid ~= nil then
			if type( priceInfo.vid ) ~= "userdata" then
				sys.log( "UI:IsPriceInfoValid()[ERROR]: invalid type of the field \"vid\"; \"userdata\" or \"nil\" expected, got \"%s\"", type( priceInfo.vid ) )
				return false
			end
		end

	end

	return true

end


--[[
	priceInfos	- массив из таблиц priceInfo; формат priceinfo см. в комментарии к функции UI:PriceInfo2Str
    baseColor	- цвет текста - будет использован, если цена не красная (не хватает денег) и не зеленая (скидка)
    bShowSale	- показывать или нет скидку (зеленым цветом); нужно только в случае цены покупки
    bShowNotEnoughMoney	- отображение красным, если денег не хватает (только для цены покупки); если nil, то дефолтное поведение, которое не отображает красным цену для золота
    bLink		- каждая цена - это ссылка (при наведении мыши показывает тултип)

    playerMoney	-	количество ресурсов у игрока; регулярный массив, индексы соотствтуют индексам в таблице priceInfos;
					необходимо для тултипа, а также для определения цвета для цены покупки;
					если nil, то ресурсы берутся из стандартного места хранения;
					тип ресурса для каждого типа цены см. в комментарии к функции UI:PriceInfo2Str

	strConnect	- соединительная строка ("или" по умолчанию)
]]

function UI:PricesInfos2Str( priceInfos, baseColor, bShowSale, bShowNotEnoughMoney, bLink, playerMoney, strConnect )

	local str = ""

	if type( priceInfos ) ~= "table" then
		sys.log( "UI:PricesInfos2Str()[ERROR]: invalid type of the 1-st parameter (\"priceInfos\"); \"table\" expected, got \"%s\"", type( priceInfos ) )
		return str
	end

	if baseColor ~= nil then
    	if type( baseColor ) ~= "number" then
    		sys.log( "UI:PricesInfos2Str()[ERROR]: invalid type of the 2-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
    	end
	end

	if playerMoney ~= nil then
    	if type( playerMoney ) ~= "table" then
    		sys.log( "UI:PricesInfos2Str()[ERROR]: invalid type of the 6-th parameter (\"playerMoney\"); \"table\" or \"nil\" expected, got \"%s\"", type( playerMoney ) )
			playerMoney = nil
    	end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if strConnect ~= nil then
    	if type( strConnect ) ~= "string" then
    		sys.log( "UI:PricesInfos2Str()[ERROR]: invalid type of the 7-th parameter (\"strConnect\"); \"string\" or \"nil\" expected, got \"%s\"", type( strConnect ) )
			strConnect = nil
    	end
	end

	if strConnect == nil then
		strConnect = UI:GetStringByName( "or" )
	end


	for priceIdx = 1, #priceInfos do

		local priceInfo = priceInfos[ priceIdx ]

		local strPrice = ""

		if UI:IsPriceInfoValid( priceInfo ) then
    		strPrice = UI:PriceInfo2Str( priceInfo, baseColor, bShowSale, bShowNotEnoughMoney, bLink, playerMoney and playerMoney[ priceIdx ] )
		else
			sys.log( "UI:PricesInfos2Str()[ERROR]: invalid price format" )
		end

		if strPrice ~= "" then

    		if str == "" then
    			str = strPrice
    		else
    			str = string.format( "%s %s %s", str, strConnect, strPrice )
    		end

		end

	end

	if str ~= "" then
		str = string.format( "%s%s", UI:Color2Str( baseColor ), str )
	end

	return str

end


--[[
	-- priceInfo	-- таблица вида
	{
		priceType		= <_G.GameStore.CreditsType> или <UI.exPriceTypes>,
		val				= <number>,
		bIsBuyPrice		= <bool>,		-- является ли ценой покупки (могут быть цены продажи, награда, просто какое-то количесто чего-то)
		basePrice		= <number>,		-- при сравнении val и basePrice определяется наличие скидки; имеет смысл только для цены покупки
	}

	baseColor	- цвет текста - будет использован, если цена не красная (не хватает денег) и не зеленая (скидка)
	bShowSale	- показывать или нет скидку (зеленым цветом); нужно только в случае цены покупки
	bShowNotEnoughMoney	- отображение красным, если денег не хватает (только для цены покупки); если nil, то дефолтное поведение, которое не отображает красным цену для золота
	bLink		- каждая цена - это ссылка (при наведении мыши показывает тултип)

	playerMoney	-	количество данного ресурса у игрока; необходимо для тултипа, а также для определения цвета для цены покупки;
					если nil, то берется из стандартного места, где хранится данный ресурс;
					для золота, серебра, токенов должно быть целое число,
					для токен-итема не поддерживается
]]

--
function UI:PriceInfo2Str( priceInfo, baseColor, bShowSale, bShowNotEnoughMoney, bLink, playerMoney )

	local str = ""

	if not UI:IsPriceInfoValid( priceInfo ) then
		sys.log( "UI:PriceInfo2Str()[ERROR]: invalid price format" )
		return str
	end

	if baseColor ~= nil then
    	if type( baseColor ) ~= "number" then
    		sys.log( "UI:PriceInfo2Str()[ERROR]: invalid type of the 2-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
    	end
	end

	if bShowSale ~= nil then
		if type( bShowSale ) ~= "boolean" then
			sys.log( "UI:PriceInfo2Str()[ERROR]: invalid type of the 3-rd parameter (\"bShowSale\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bShowSale ) )
			bShowSale = nil
		end
	end

	if bShowNotEnoughMoney ~= nil then
    	if type( bShowNotEnoughMoney ) ~= "boolean" then
    		sys.log( "UI:PriceInfo2Str()[ERROR]: invalid type of the 4-th parameter (\"bShowNotEnoughMoney\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bShowNotEnoughMoney ) )
			bShowNotEnoughMoney = nil
    	end
	end

	if bLink ~= nil then
		if type( bLink ) ~= "boolean" then
			sys.log( "UI:PriceInfo2Str()[ERROR]: invalid type of the 5-th parameter (\"bLink\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bLink ) )
			bLink = nil
		end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if bShowSale == nil then
		bShowSale = false
	end

	if bShowNotEnoughMoney == nil then
		bShowNotEnoughMoney = priceInfo.priceType ~= _G.GameStore.CreditsType.CT_GOLD
	end

	if bLink == nil then
		bLink = false
	end

	if bLink then

		-- перевод таблицы priceInfo в строку для инициализации ссылки;
		-- вручную, т.к. sys.tostring() не используется, потому что она подставляет много всякой разной лишней фигни, которая сводит с ума метатекст

		local strType			= string.format( "priceType=%d", priceInfo.priceType )
		local strVal			= string.format( "val=%s", tostring( priceInfo.val ) )
		local strIsBuyPrice		= string.format( "bIsBuyPrice=%s", tostring( priceInfo.bIsBuyPrice ) )
		local strIcoFirst		= string.format( "bIcoFirst=%s", tostring( priceInfo.bIcoFirst ) )
		local strDisableFree	= string.format( "bDisableFree=%s", tostring( priceInfo.bDisableFree ) )

    	local strPriceInfo = string.format( "%s,%s,%s,%s,%s", strType, strVal, strIsBuyPrice, strIcoFirst, strDisableFree )

		if priceInfo.bIsBuyPrice then

	    	local strBasePrice	= string.format( "basePrice=%d", priceInfo.basePrice )
    		strPriceInfo = string.format( "%s,%s", strPriceInfo, strBasePrice )

		end

		if priceInfo.valAsString then

			local strValAsString = string.format( "valAsString=\"%s\"", priceInfo.valAsString )
			strPriceInfo = string.format( "%s,%s", strPriceInfo, strValAsString )

		end

		if priceInfo.priceType == UI.exPriceTypes.SHIP_PARTS then

			local strDefName = string.format( "defName=\"%s\"", priceInfo.defName )
			strPriceInfo = string.format( "%s,%s", strPriceInfo, strDefName )

		elseif priceInfo.priceType == UI.exPriceTypes.SPEC_MODULE_PARTS then

			local strDefName = string.format( "shipDefName=\"%s\"", priceInfo.shipDefName )
			strPriceInfo = string.format( "%s,%s", strPriceInfo, strDefName )

		elseif priceInfo.priceType == UI.exPriceTypes.SYNERGY then

			if priceInfo.vid ~= nil then
				local strVid = string.format( "vid=u64(%d,%d)", priceInfo.vid.h, priceInfo.vid.l )
				strPriceInfo = string.format( "%s,%s", strPriceInfo, strVid )
			end

		end

		strPriceInfo = string.format( "{%s}", strPriceInfo )


		-- перевод playerMoney в строку для инициализации ссылки

		local strPlayerMoney = "nil"

		if type( playerMoney ) == "number" then
			strPlayerMoney = string.format( "%d", playerMoney )

		elseif type( playerMoney ) == "table" then
			strPlayerMoney = string.format( "{%s}", table.concat( playerMoney, "," ) )

		elseif playerMoney ~= nil then
			sys.log( "UI:PriceInfo2Str()[ERROR]: unhandled type of playerMoney: %s", type( playerMoney ) )
		end

        str = string.format( "$link [type PRICE] [params {priceInfo=%s, bShowSale=%s, bShowNotEnoughMoney=%s, baseColor=%u, playerMoney=%s}]$", strPriceInfo, tostring( bShowSale ), tostring( bShowNotEnoughMoney ), baseColor, strPlayerMoney )

	else

    	local color = UI:GetPriceColor( priceInfo.priceType )

		if priceInfo.val == 0 and priceInfo.bIsBuyPrice and ( priceInfo.priceType == _G.GameStore.CreditsType.CT_CREDITS or priceInfo.priceType == _G.GameStore.CreditsType.CT_GOLD ) and not priceInfo.bDisableFree then

			str		= UI:GetStringByName( "priceFree" )
			color	= UI.FREE_COLOR

		else

			local strVal	= priceInfo.valAsString or UI:Num2StrSeparatedBy3( priceInfo.val )
			local strIco	= UI:GetPriceIcoMetaString( priceInfo )

			local bIcoFirst = priceInfo.bIcoFirst
			if bIcoFirst == nil then
				bIcoFirst = false
			end

			if bIcoFirst then
				str = string.format( "%s%s", strIco, strVal )
			else
				str = string.format( "%s%s", strVal, strIco )
			end

		end

    	local bEnoughMoney	= self:IsEnoughMoneyForPrice( priceInfo, false, playerMoney )
		local bSale			= priceInfo.bIsBuyPrice and priceInfo.val < priceInfo.basePrice

		if bSale and bShowSale then
			color = UI.PARAM_DELTA_PLUS_COLOR

		elseif not bEnoughMoney and bShowNotEnoughMoney then
			color = UI.PARAM_DELTA_MINUS_COLOR
		end

		local strColor		= UI:Color2Str( color )
		local strBaseColor	= UI:Color2Str( baseColor )

		str = string.format( "%s%s%s", strColor, str, strBaseColor )

	end

	return str

end


--
function UI:GetPriceIcoMetaString( priceInfo )

	local str = ""

	if priceInfo.priceType == _G.GameStore.CreditsType.CT_CREDITS then
		str = "$credits_big$"

	elseif priceInfo.priceType == _G.GameStore.CreditsType.CT_GOLD then
		str = "$gold_big$"

	elseif priceInfo.priceType == _G.GameStore.CreditsType.CT_TOKENS then
		str = "$tokens_big$"

	elseif priceInfo.priceType == UI.exPriceTypes.CLAN_IRIDIUM then
		str = "$clan_iridium$"

	elseif priceInfo.priceType == UI.exPriceTypes.SYNERGY then
		str = "$synergy_ship$"

	elseif priceInfo.priceType == UI.exPriceTypes.FREE_SYNERGY then
		str = "$synergy_free$"

	elseif priceInfo.priceType == UI.exPriceTypes.SHIP_PARTS then
		str = UI:GetShipPartsIcoMetaString( priceInfo.defName, false )

	elseif priceInfo.priceType == UI.exPriceTypes.SPEC_MODULE_PARTS then
		str = UI:GetSpecModulePartsIcoMetaString()

	elseif priceInfo.priceType == _G.GameStore.CreditsType.CT_EVENT then
		str = "$event_credits$"

	else
		sys.log( "UI:GetPriceIcoMetaString()[ERROR]: unhandled price type: %s", tostring( priceInfo.priceType ) )
	end

	return str

end


--
function UI:GetPriceColor( priceType )

	local color = UI.TEXT_BASE_COLOR

	if type( priceType ) ~= "number" then
		sys.log( "UI:GetPriceColor()[ERROR]: invalid type of the 1-st parameter (\"priceType\"); \"number\" expected, got \"%s\"", type( priceType ) )
		return color
	end

	local priceTypeName = ( priceType < 0 ) and UI:Val2Key( UI.exPriceTypes, priceType ) or UI:Val2Key( _G.GameStore.CreditsType, priceType )

	if UI.priceColors[ priceTypeName ] then
		color = UI.priceColors[ priceTypeName ]
	end

	return color

end


--
function UI:IsEnoughMoneyForPrice( priceInfo, bAllowRefill, playerMoney )

	if not UI:IsPriceInfoValid( priceInfo ) then
		sys.log( "UI:IsEnoughMoneyForPrice()[ERROR]: invalid format of priceInfo" )
		return false
	end

	if not priceInfo.bIsBuyPrice then
		return true
	end

	if bAllowRefill ~= nil then
		if type( bAllowRefill ) ~= "boolean" then
			sys.log( "UI:IsEnoughMoneyForPrice()[ERROR]: invalid type of the 2-nd parameter (\"bAllowRefill\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bAllowRefill ) )
			bAllowRefill = nil
		end
	end

	if bAllowRefill == nil then
		bAllowRefill = true
	end

	if bAllowRefill then
		if priceInfo.priceType ~= _G.GameStore.CreditsType.CT_CREDITS and priceInfo.priceType ~= _G.GameStore.CreditsType.CT_GOLD then
			bAllowRefill = false
		end
	end

	if bAllowRefill then
		return true
	end

	if playerMoney ~= nil then
		if type( playerMoney ) ~= "number" then
			sys.log( "UI:IsEnoughMoneyForPrice()[ERROR]: invalid type of the 3-rd parameter (\"playerMoney\"); \"number\" or \"nil\" expected, got \"%s\"", type( playerMoney ) )
			playerMoney = nil
		end
	end

	if playerMoney == nil then
		playerMoney = UI:GetPlayerFunds( priceInfo.priceType, priceInfo )
	end

	return playerMoney >= priceInfo.val

end


--
function UI:GetPlayerFunds( priceType, params )

	local funds = 0

	if type( priceType ) ~= "number" then
		sys.log( "UI:GetPlayerFunds()[ERROR]: invalid type of the 1-st parameter (\"priceType\"); \"number\" expected, got \"%s\"", type( priceType ) )
		return funds
	end

	if priceType == _G.GameStore.CreditsType.CT_CREDITS then
		funds = UI:GetPlayerMoney( false )

	elseif priceType == _G.GameStore.CreditsType.CT_GOLD then
		funds = UI:GetPlayerMoney( true )

	elseif priceType == _G.GameStore.CreditsType.CT_TOKENS then
		funds = UI:GetPlayerTokens()

	elseif priceType == UI.exPriceTypes.CLAN_IRIDIUM then
		funds = UI:GetIridium()

	elseif priceType == UI.exPriceTypes.FREE_SYNERGY then
		funds = UI:GetPlayerFreeSynergy()

	elseif priceType == UI.exPriceTypes.SHIP_PARTS then

		local defName = ""

		if type( params ) == "table" then
			if type( params.defName ) == "string" then
				defName = params.defName
			else
				sys.log( "UI:GetPlayerFunds()[ERROR]: invalid type of field params.defName; \"string\" expected, got \"%s\"", type( params.defName ) )
			end
		else
			sys.log( "UI:GetPlayerFunds()[ERROR]: invalid type of the 2-nd parameter (\"params\"); \"table\" expected, got \"%s\"", type( params ) )
		end

		if defName ~= "" then
			funds = UI:GetPlayerResourceCount( defName )
		end

	elseif priceType == UI.exPriceTypes.SPEC_MODULE_PARTS then

		local shipDefName = ""

		if type( params ) == "table" then
			if type( params.shipDefName ) == "string" then
				shipDefName = params.shipDefName
			else
				sys.log( "UI:GetPlayerFunds()[ERROR]: invalid type of field params.shipDefName; \"string\" expected, got \"%s\"", type( params.shipDefName ) )
			end
		else
			sys.log( "UI:GetPlayerFunds()[ERROR]: invalid type of the 2-nd parameter (\"params\"); \"table\" expected, got \"%s\"", type( params ) )
		end

		if shipDefName ~= "" then
			funds = UI:GetShipSpecModulePartsByDef( shipDefName )
		end

	elseif priceType == UI.exPriceTypes.SYNERGY then

		local vid = UI.INVALID_U64_ID

		if type( params ) == "table" then
			if type( params.vid ) == "userdata" then
				vid = params.vid
			else
				sys.log( "UI:GetPlayerFunds()[ERROR]: invalid type of field params.vid; \"userdata\" expected, got \"%s\"", type( params.vid ) )
			end
		else
			sys.log( "UI:GetPlayerFunds()[ERROR]: invalid type of the 2-nd parameter (\"params\"); \"table\" expected, got \"%s\"", type( params ) )
		end

		if vid ~= UI.INVALID_U64_ID then
			funds = UI:GetShipExpByVid( vid )
		end

	elseif priceType == _G.GameStore.CreditsType.CT_EVENT then
		funds = UI:GetPlayerEventCredits()

	else
		sys.log( "UI:GetPlayerFunds()[ERROR]: unhandled price type: %s", tostring( priceType ) )
	end

	return funds

end


--
function UI:CanItemUpgradeFurther( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:CanItemUpgradeFurther()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	local curLevel = UI:GetItemUpgradeLevel( defName )
	local maxLevel = UI:GetItemUpgradeMaxLevel( defName )

	return curLevel ~= -1 and maxLevel ~= -1 and curLevel < maxLevel

end


--
function UI:IsItemUpgradable( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:IsItemUpgradable()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	local maxLevel = UI:GetItemUpgradeMaxLevel( defName )

	return maxLevel > 1

end


--
function UI:CanUpgradeItemThroughCraftOnly( defName )

	local bThroughCraft = false

	if type( defName ) ~= "string" then
		sys.log( "UI:CanUpgradeItemThroughCraftOnly()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bThroughCraft
	end

	if UI:IsDefAutogen( defName ) then
		return bThroughCraft
	end

	local nextDefName = UI:GetItemUpgradeNextDef( defName, true )

	if nextDefName ~= "" then
		bThroughCraft = UI:CanUpgradeItemToDefThroughCraftOnly( nextDefName )
	else
		sys.log( "UI:CanUpgradeItemThroughCraftOnly()[ERROR]: cannot find def for next upgrade for \"%s\"", defName )
	end

	return bThroughCraft

end


--
function UI:CanUpgradeItemToDefThroughCraftOnly( dstDefName )

	local bThroughCraft = false

	if type( dstDefName ) ~= "string" then
		sys.log( "UI:CanUpgradeItemToDefThroughCraftOnly()[ERROR]: invalid type of the 1-st parameter (\"dstDefName\"); \"string\" expected, got \"%s\"", type( dstDefName ) )
		return bThroughCraft
	end

	local def = UI:GetDef( dstDefName )

	if def.upgrade_through_craft ~= nil then
		if type( def.upgrade_through_craft ) == "boolean" then
			bThroughCraft = def.upgrade_through_craft
		else
			sys.log( "UI:CanUpgradeItemToDefThroughCraftOnly()[ERROR]: invalid type of \"_G.Def.%s.upgrade_through_craft\"; \"boolean\" or \"nil\" expected, got \"%s\"", dstDefName, type( def.upgrade_through_craft ) )
		end
	end

	return bThroughCraft

end


--
function UI:GetTokenItemDstDefName( tokenDefName )

	if type( tokenDefName ) ~= "string" then
		sys.log( "UI:GetTokenItemDstDefName()[ERROR]: invalid type of the 1-st parameter (\"tokenDefName\"); \"string\" expected, got \"%s\"", type( tokenDefName ) )
		return ""
	end

	local def = UI:GetDef( tokenDefName )
	if not def then
		sys.log( "UI:GetTokenItemDstDefName()[ERROR]: cannot find \"_G.Def[%s]\"", tokenDefName )
		return ""
	end

	if type( def.upgrade_to_item ) ~= "string" then
		sys.log( "UI:GetTokenItemDstDefName()[ERROR]: invalid type of the \"_G.Def[%s].upgrade_to_item\"; \"string\" expected, got \"%s\"", tokenDefName, type( def.upgrade_to_item ) )
		return ""
	end

	return def.upgrade_to_item

end


--
function UI:GetTokenItemSrcDefName( tokenDefName )

	local dstDefName = UI:GetTokenItemDstDefName( tokenDefName )
	if dstDefName ~= "" then
		return UI:GetItemUpgradePrevDef( dstDefName )
	else
		return ""
	end

end


-- возвращает имена модулей, имеющихся у игрока, которые входят в upgrade chain, в котором участвцет указанный токен-итем;
-- если параметр bAllUpgradeChain=true, то возвращаются все модули из upgrade chain,
-- если bAllUpgradeChain=false - те, которые токен-итем непосредственно апгрейдит, и ниже

function UI:GetTokenItemAllSrcDefNames( tokenDefName, bAllUpgradeChain )

	local srcDefNames = {}

	if type( tokenDefName ) ~= "string" then
		sys.log( "UI:GetTokenItemAllSrcDefNames()[ERROR]: invalid type of the 1-st parameter (\"tokenDefName\"); \"string\" expected, got \"%s\"", type( tokenDefName ) )
		return srcDefNames
	end

	if type( bAllUpgradeChain ) ~= "boolean" then
		sys.log( "UI:GetTokenItemAllSrcDefNames()[ERROR]: invalid type of the 2-st parameter (\"bAllUpgradeChain\"); \"boolean\" expected, got \"%s\"", type( bAllUpgradeChain ) )
		bAllUpgradeChain = false
	end

	local dstDefName = UI:GetTokenItemDstDefName( tokenDefName )

	local highestDefName = ""

	if bAllUpgradeChain then

		if dstDefName ~= "" then

    		local maxLevel = UI:GetItemUpgradeMaxLevel( dstDefName )
    		if maxLevel ~= -1 then
				highestDefName = UI:GetItemUpgradeDefForLevel( dstDefName, maxLevel )
			end

		end

	else
		highestDefName = UI:GetItemUpgradePrevDef( dstDefName )
	end

	local defName = highestDefName
	while defName ~= "" do

		table.insert( srcDefNames, defName )
		defName = UI:GetItemUpgradePrevDef( defName )

	end

	return srcDefNames

end


-- возвращает информацию о модулях, имеющихся у игрока, которые входят в upgrade chain, в котором участвцет указанный токен-итем;
-- если параметр bAllUpgradeChain=true, то возвращаются все модули из upgrade chain,
-- если bAllUpgradeChain=false - те, которые токен-итем непосредственно апгрейдит, и ниже

function UI:GetTokenItemAllSrcInventoryInfo( tokenDefName, bAllUpgradeChain )

	local fitModulesInfos = {}

	if type( tokenDefName ) ~= "string" then
		sys.log( "UI:GetTokenItemAllSrcInventoryInfo()[ERROR]: invalid type of the 1-st parameter (\"tokenDefName\"); \"string\" expected, got \"%s\"", type( tokenDefName ) )
		return fitModulesInfos
	end

	local srcDefNames = UI:GetTokenItemAllSrcDefNames( tokenDefName, bAllUpgradeChain )
	for srcDefIdx, srcDefName in pairs( srcDefNames ) do

		local inventoryItems = UI:GetInventoryItemsByDef( srcDefName )
		if next( inventoryItems ) then

			local info =
			{
				defName			= srcDefName,
				numEquipped		= 0,
				numUnequipped	= 0,
			}

    		for itemIdx, item in pairs( inventoryItems ) do

    			local equipShipItem = UI:GetEquippedShipItem( item.iid )

    			if equipShipItem then
    				info.numEquipped = info.numEquipped + 1
    			else
    				info.numUnequipped = info.numUnequipped + 1
    			end

    		end

			table.insert( fitModulesInfos, info )

		end

	end

	return fitModulesInfos

end


--
function UI:TokenItemSrcInventoryInfo2Str( fitModulesInfos, baseColor, bAllowLinks, bLinksOpenStore, bMultyLine )

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if bAllowLinks == nil then
		bAllowLinks = false
	end

	if bLinksOpenStore == nil then
		bLinksOpenStore = false
	end

	if bMultyLine == nil then
		bMultyLine = true
	end

	local strBaseColor = UI:Color2Str( baseColor )

	local str = ""

	if next( fitModulesInfos ) then

    	local fnSort = function( info1, info2 )

			local upgradeLevel1 = UI:GetItemUpgradeLevel( info1.defName )
			local upgradeLevel2 = UI:GetItemUpgradeLevel( info2.defName )

			return upgradeLevel1 < upgradeLevel2

    	end

    	table.sort( fitModulesInfos, fnSort )

		local strSeparator = bMultyLine and "|" or ", "

    	for idx = 1, #fitModulesInfos do

    		local info = fitModulesInfos[ idx ]

			local strItemName = ""

			if bAllowLinks then
				local strOpenStore = bLinksOpenStore and ", bOpenStore=true" or ""
				strItemName = string.format( "$link [type ITEM][params {defName=\"%s\" %s}]$", info.defName, strOpenStore )
			else
				strItemName = UI:GetEntityLocalizedNameByDef( info.defName, true, false, true )
			end

			strItemName = string.format( "%s%s", strItemName, strBaseColor )

    		local strNum = ""

    		if info.numEquipped > 0 then

    			local strEquipped = UI:GetStringByName( "salvage_numFitModulesEquipped" )
    			local strNumEquipped = UI:Num2StrSeparatedBy3( info.numEquipped )
    			strEquipped = string.gsub( strEquipped, "%$num%$", strNumEquipped )

    			strNum = string.format( "%s%s%s", strNum, strNum ~= "" and "/" or "", strEquipped )

    		end

    		if info.numUnequipped > 0 then

    			local strUnequipped = UI:GetStringByName( "salvage_numFitModulesUnequipped" )
    			local strNumEquipped = UI:Num2StrSeparatedBy3( info.numUnequipped )
    			strUnequipped = string.gsub( strUnequipped, "%$num%$", strNumEquipped )

    			strNum = string.format( "%s%s%s", strNum, strNum ~= "" and " / " or "", strUnequipped )

    		end

    		local strByDef = string.format( "%s: %s", strItemName, strNum )
    		str = string.format( "%s%s%s", str, str ~= "" and strSeparator or "", strByDef )

    	end

	else

		local color = UI.PARAM_DELTA_MINUS_COLOR
		local strColor = UI:Color2Str( color )

        str = string.format( "%s%s", strColor, UI:GetStringByName( "tokenItem_desc_noSrcItem" ) )

	end

	return str

end


--
function UI:GetTokenItemIco( defName )

	local texId = UI:GetTex( "NoData" )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetTokenItemIco()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return texId
	end

	if defName == "" then
		sys.log( "UI:GetTokenItemIco()[ERROR]: empty defName" )
		return texId
	end

	local dstDefName = UI:GetTokenItemDstDefName( defName )

	if dstDefName == "" then
		sys.log( "UI:GetTokenItemIco()[ERROR]: cannot find dst def for token-item \"%s\"", defName )
		return texId
	end

	-- #0034867

	return UI:GetShopIco( dstDefName )

end


--
function UI:TokenItem2Str( defName )

	local str = "unknown"

	if type( defName ) ~= "string" then
		sys.log( "UI:TokenItem2Str()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return str
	end

	if defName == "" then
		sys.log( "UI:TokenItem2Str()[ERROR]: empty defName" )
		return str
	end

	str = defName

	local srcDefName = UI:GetTokenItemSrcDefName( defName )
	if srcDefName == "" then
		sys.log( "UI:TokenItem2Str()[ERROR]: cannot find src def for token-item \"%s\"", defName )
		return str
	end

	local srcName = UI:GetEntityLocalizedNameByDef( srcDefName, false, fale, true, false )
	local tSubst =
	{
		src_item	= srcName,
	}

	local str = UI:GetStringByName( "tokenItem_name" )
	str = string.gsub( str, "%$(.-)%$", tSubst )

	return str

end


--
function UI:GetTokenItemDesc( defName, bAllowLinks, baseColor )

	local str = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetTokenItemDesc()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return str
	end

	if defName == "" then
		sys.log( "UI:GetTokenItemDesc()[ERROR]: empty defName" )
		return str
	end

	if bAllowLinks ~= nil then
		if type( bAllowLinks ) ~= "boolean" then
			sys.log( "UI:GetTokenItemDesc()[ERROR]: invalid type of the 2-nd parameter (\"bAllowLinks\"); \"boolean\" expected, got \"%s\"", type( bAllowLinks ) )
			bAllowLinks = nil
		end
	end

	if bAllowLinks == nil then
		bAllowLinks = false
	end

	if baseColor ~= nil then
		if type( baseColor ) ~= "number" then
			sys.log( "UI:GetTokenItemDesc()[ERROR]: invalid type of the 3-rd parameter (\"baseColor\"); \"number\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
		end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	local strBaseColor = UI:Color2Str( baseColor )

	local srcDefName = UI:GetTokenItemSrcDefName( defName )
	local dstDefName = UI:GetTokenItemDstDefName( defName )

	local firstLevelDefName = UI:GetItemUpgradeDefForLevel( srcDefName, 1 )

	local strFirstLevelItamName = ""

	if bAllowLinks then
     	strFirstLevelItamName = string.format( "$link [type ITEM][params {defName=\"%s\"}]$", firstLevelDefName )
	else
		strFirstLevelItamName = UI:GetEntityLocalizedNameByDef( firstLevelDefName, true, false, true )
	end
	strFirstLevelItamName = string.format( "%s%s", strFirstLevelItamName, strBaseColor )

	local srcMark = UI:GetItemQuality( srcDefName )
	local dstMark = UI:GetItemQuality( dstDefName )

	local srcMarkColor = UI:GetItemQualityColor( srcMark, false )
	local dstMarkColor = UI:GetItemQualityColor( dstMark, false )

	local strSrcMark = UI:ItemQuality2Str( srcMark )
	local strDstMark = UI:ItemQuality2Str( dstMark )

	strSrcMark = string.format( "%s%s%s", UI:Color2Str( srcMarkColor ), strSrcMark, strBaseColor )
	strDstMark = string.format( "%s%s%s", UI:Color2Str( dstMarkColor ), strDstMark, strBaseColor )

	local tSubst =
	{
		item		= strFirstLevelItamName,
		src_mark	= strSrcMark,
		dst_mark	= strDstMark,
	}

	local str = UI:GetStringByName( "tokenItem_desc2" )
	str = string.gsub( str, "%$(.-)%$", tSubst )
	str = string.format( "%s%s", strBaseColor, str )

	return str

end


--
function UI:GetItemParamDeltas( defNameBase, defNameCompareTo, bShowDeltaOnly, vid, equipSlot, color )

	local deltaInfos = {}

	if type( defNameBase ) ~= "string" then
		sys.log( "UI:GetItemParamDeltas()[ERROR]: invalid type of the 1-st parameter (\"defNameBase\"); \"string\" expected, got \"%s\"", type( defNameBase ) )
		return deltaInfos
	end

	if type( defNameCompareTo ) ~= "string" then
		sys.log( "UI:GetItemParamDeltas()[ERROR]: invalid type of the 2-nd parameter (\"defNameCompareTo\"); \"string\" expected, got \"%s\"", type( defNameCompareTo ) )
		return deltaInfos
	end

	if type( bShowDeltaOnly ) ~= "boolean" then
		sys.log( "UI:GetItemParamDeltas()[ERROR]: invalid type of the 3-rd parameter (\"bShowDeltaOnly\"); \"boolean\" expected, got \"%s\"", type( bShowDeltaOnly ) )
		bShowDeltaOnly = false
	end

	if vid ~= nil then
    	if type( vid ) ~= "userdata" then
    		sys.log( "UI:GetItemParamDeltas()[ERROR]: invalid type of the 4-th parameter (\"vid\"); \"userdata\" or \"nil\" expected, got \"%s\"", type( vid ) )
			vid = nil
    	end
	end

    if vid == nil then
		vid = UI.INVALID_U64_ID
	end

	if equipSlot ~= nil then
    	if type( equipSlot ) ~= "number" then
    		sys.log( "UI:GetItemParamDeltas()[ERROR]: invalid type of the 5-th parameter (\"equipSlot\"); \"number\" or \"nil\" expected, got \"%s\"", type( equipSlot ) )
    		equipSlot = nil
    	end
	end

	if equipSlot == nil then
		equipSlot = -1
	end

	if vid ~= UI.INVALID_U64_ID and equipSlot == -1 then
		sys.log( "UI:GetItemParamDeltas()[ERROR]: vid is specified but equipSlot is not" )
		vid = UI.INVALID_U64_ID
	end

	if color ~= nil then
    	if type( color ) ~= "number" then
    		sys.log( "UI:GetItemParamDeltas()[ERROR]: invalid type of the 6-th parameter (\"color\"); \"number\" or \"nil\" expected, got \"%s\"", type( color ) )
			color = nil
    	end
	end

	if color == nil then
		color = UI.TEXT_BASE_COLOR
	end

	local paramsTables = {}
	table.insert( paramsTables, { table = UI:GetItemTooltipParams( defNameBase ), bForceAbs = false } )
	table.insert( paramsTables, { table = UI:GetItemDescParams( defNameBase ), bForceAbs = false } )

	local dstParamsData		= { defName = defNameBase, data = nil}
	local compareParamsData = { defName = defNameCompareTo, data = nil }

	if vid ~= UI.INVALID_U64_ID then

		if UI:IsDefAmmo( defNameBase ) then
			dstParamsData.data		= { params = _G.CL_GetMunitionParamsFromSpawnData( UI:GetShipSpawnData( vid, true, nil, nil, false--[[SC-112506 SC-112961 без автогенов]] ), defNameBase ) }
			compareParamsData.data	= { params = _G.CL_GetMunitionParamsFromSpawnData( UI:GetShipSpawnData( vid, true, nil, nil, false--[[SC-112506 SC-112961 без автогенов]] ), defNameCompareTo ) }
		else
			dstParamsData.data		= { params = _G.CL_GetModuleParamsFromSpawnData( UI:GetShipSpawnData( vid, true, nil, nil, false--[[SC-112506 SC-112961 без автогенов]] ), equipSlot, defNameBase ) }
			compareParamsData.data	= { params = _G.CL_GetModuleParamsFromSpawnData( UI:GetShipSpawnData( vid, true, nil, nil, false--[[SC-112506 SC-112961 без автогенов]] ), equipSlot, defNameCompareTo ) }
		end

	end

	for paramsTableIdx, paramsTable in ipairs( paramsTables ) do

		for paramIdx, paramInfo in ipairs( paramsTable.table ) do

			local strDelta = UI:GetItemParamValAsStr( paramInfo, dstParamsData, compareParamsData, true, color, color, paramsTable.bForceAbs, paramsTable.table, true, bShowDeltaOnly )

			if not UI:IsStrEmpty( strDelta ) then

				local deltaInfo =
				{
					paramInfo	= paramInfo,
					paramsTable	= paramsTable.table,
					strDelta	= strDelta,
					bForceAbs	= paramsTable.bForceAbs,
				}

				table.insert( deltaInfos, deltaInfo )

			end

		end

	end

	return deltaInfos

end


--
function UI:HasShipEquipment( shipItem )

	for slotId, ammo in pairs( shipItem.equipAmmo ) do
		if ammo.def ~= "" and ammo.amount > 0 then
			return true
		end
	end

	for slotId, iid in pairs( shipItem.equipModules ) do
		if iid ~= UI.INVALID_U64_ID then
			return true
		end
	end

	return false

end


--
function UI:ShowDefNames( bShow )

	if type( bShow ) ~= "boolean" then
		sys.log( "UI:ShowDefNames()[ERROR]: invalid type of the 1-st parameter (bShow); \"boolean\" expected, got \"%s\"", type( bShow ) )
		return
	end

	if bShow == UI.showDefNames then
		return
	end

	UI.showDefNames = bShow

	for idx, shipItem in pairs( self.serverData.allShips ) do
		shipItem.localizedName			= UI:GetEntityLocalizedNameByDef( shipItem.defName )
		shipItem.localizedName_lower	= _G.Utf8CaseFold_Transform( shipItem.localizedName )
	end

	UI:ReloadResources()

end


--
function UI:GetPrestige()

	return UI:Round( _G.MasterServer_GetPrestigeBonus() * 100 )

end


--
function UI:GetPrestigeIco( prestige )

	local hTex = UI:GetTex( "NoData" )

	if type( prestige ) ~= "number" then
		sys.log( "UI:GetPrestigeIco()[ERROR]: invalid type of the 1-st parameter (\"prestige\"); \"number\" expected, got \"%s\"", type( prestige ) )
		return hTex
	end

	if prestige < 0 then
		sys.log( "UI:GetPrestigeIco()[ERROR]: negative value" )
		prestige = 0
	end

	local STEP_SIZE	= 20
	local MAX_STEPS	= 10

	local step = math.floor( prestige / STEP_SIZE ) + 1
	if step > MAX_STEPS then
		step = MAX_STEPS
	end

	local strId = string.format( "prestige_%d", step )

	hTex = UI:GetTex( strId )
	return hTex

end


--
function UI:IsShipPremium( defName )

	local bPremium = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsShipPremium()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bPremium
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsShipPremium()[ERROR]: cannot find \"_G.Def[%s]\"", defName )
		return bPremium
	end

	if def.isPremium ~= nil then
		if type( def.isPremium ) == "boolean" then
			bPremium = def.isPremium
		else
			sys.log( "UI:IsShipPremium()[ERROR]: invalid type of '_G.Def[%s].isPremium'; 'boolean' or 'nil' expected, got '%s'", type( def.isPremium ) )
		end
	end

	return bPremium

end


