--
function UI:PreviewShipCustomizations( vid, shipEntId )

	if type( vid ) ~= "userdata" then
		sys.log( "UI:PreviewShipCustomizations()[ERROR]: invalid type of the 1-st param (\"vid\"); \"userdata\" expected, got \"%s\"", type( vid ) )
		return
	end

	if type( shipEntId ) ~= "number" then
		sys.log( "UI:PreviewShipCustomizations()[ERROR]: invalid type of the 2-nd param (\"shipEntId\"); \"number\" expected, got \"%s\"", type( shipEntId ) )
		return
	end

	local shipEnt = _G.Entities[ shipEntId ]
	if not shipEnt then
		sys.log( "UI:PreviewShipCustomizations()[ERROR]: cannot find entity with id %d", shipEntId )
		return
	end

	local presetName = UI:GetShipCustomization( vid, ai.VesselCustomSlot.MPRESET_0 )

	for slotName, customSlotId in pairs( ai.VesselCustomSlot ) do

		local bNeedPreview = true

		if customSlotId == ai.VesselCustomSlot.MPRESET_0 then
			bNeedPreview = presetName ~= ""

		else
			if presetName ~= "" and UI:IsShipCustomSlotInPreset( presetName, customSlotId ) then
				bNeedPreview = false
			end
		end

		if bNeedPreview then

			local customName = UI:GetShipCustomization( vid, customSlotId )
    		shipEnt:SetVesselCustomElement( customName, customSlotId )

		end

	end

end


--
function UI:GetJunkPriceInfo( defName )

	local priceInfo = { type = self.junkPriceTypes.NONE }

	if type( defName ) ~= "string" then
		sys.log( "UI:GetJunkPriceInfo()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return priceInfo
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetJunkPriceInfo()[ERROR]: cannot find _G.Def[%s]", defName )
		return priceInfo
	end

	if not UI:IsDefJunk( defName ) then
		sys.log( "UI:GetJunkPriceInfo()[ERROR]: item \"%s\" is not junk", defName )
		return priceInfo
	end

	if type( def.tokens ) == "number" and def.tokens ~= 0 then

		priceInfo.type		= self.junkPriceTypes.TOKENS
		priceInfo.tokens	= def.tokens

		return priceInfo

	end

	if type( def.price ) == "number" and def.price ~= 0 then

		priceInfo.type		= self.junkPriceTypes.CREDITS
		priceInfo.credits	= def.price

		return priceInfo

	end

	-- #0038482 - может быть лут без цены
--	sys.log( "UI:GetJunkPriceInfo()[ERROR]: cannot detect price type for junk \"%s\"", defName )
	return priceInfo

end


--
function UI:SubstituteHudMsgParams( strId, params )

	local str = ""

	if type( strId ) ~= "string" then
		sys.log( "UI:SubstituteHudMsgParams()[ERROR]: invalid type of the 1-st parameter (\"string\"); \"number\" expected, got \"%s\"", type( strId ) )
		return str
	end

	str = UI:GetStringByName( strId )

	if params ~= nil then
		if type( params ) ~= "table" then
			sys.log( "UI:SubstituteHudMsgParams()[ERROR]: invalid type of the 2-nd parameter (\"params\"); \"table\" or \"nil\" expected, got \"%s\"", type( params ) )
			params = nil
		end
	end

	if not params then
		return str
	end

	local bValid = true
	for key, val in pairs( params ) do
		if type( key ) ~= "number" or type( val ) ~= "table" then
			sys.log( "UI:SubstituteHudMsgParams()[ERROR]: invalid 'params' table format; <number>=<table> expected, got <%s>=<%s>", type( key ), type( val ) )
			bValid = false
			break
		end
	end

	if not bValid then
		return str
	end

	for paramIdx, param in pairs( params ) do
		str = UI:InsertMsgParam( str, param, paramIdx, strId )
	end

	return str

end


--
function UI:InsertMsgParam( str, param, paramIdx, strId )

	if not strId then
		strId = "unspecified"
	end

	if type( param ) ~= "table" then
		sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of param %d in msg \"%s\"; \"table\" expected, got \"%s\"", paramIdx, strId, type( param ) )
		return str
	end

	-- плэйсхолдер

	if type( param.name ) ~= "string" then
		sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"name\" in param %d(type %s) in msg \"%s\"; \"string\" expected, got \"%s\"", paramIdx, UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
		return str
	end

	if param.name == "" then
		sys.log( "UI:InsertMsgParam()[ERROR]: empty field \"name\" in param %d(type %s) in msg \"%s\"", paramIdx, UI:Val2Key( ai.GameMsgParamType, param.type ), strId )
		return str
	end

	local strPlaceholder = "%$"..param.name.."%$"


	-- перевод значения в строку

	local strParam = string.format( "error_param_%d", paramIdx )

	if type( param.type ) == "number" then

		if param.type == ai.GameMsgParamType.INT then

			if type( param.value ) == "number" then
				strParam = UI:Num2StrSeparatedBy3( param.value )
			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"number\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end


		elseif param.type == ai.GameMsgParamType.FLOAT then

			if type( param.value ) == "number" then
				strParam = UI:FNum2StrSeparatedBy3( param.value )
			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"number\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end


		elseif param.type == ai.GameMsgParamType.STR_ID then

			if type( param.value ) == "string" then
				strParam = UI:GetStringByName( param.value )
			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"string\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end


		elseif param.type == ai.GameMsgParamType.BIND then

			if type( param.value ) == "string" then
				strParam = UI:GetBindKeysStr( param.value, true )
			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"string\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end


		elseif param.type == ai.GameMsgParamType.ENTITY_ID then

			if type( param.value ) == "number" then

				local ent = _G.Entities[ param.value ]
				if ent then
					strParam = UI:GetEntityLocalizedName( ent, false, false )
				else
					sys.log( "UI:InsertMsgParam()[ERROR]: cannot find entity with id %d for param %d(name %s, type %s) in msg \"%s\"", param.value, paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId )
				end

			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"number\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end


		elseif param.type == ai.GameMsgParamType.DEF_NAME then

			if type( param.value ) == "string" then

				strParam = UI:GetEntityLocalizedNameByDef( param.value, false, false, false )

				if param.amount ~= nil then
					if type( param.amount ) == "number" then

						if param.amount > 1 then
							strParam = string.format( "%s [%d]", strParam, param.amount )
						end

					else
						sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"amount\" in param %d(name %s, type %s) in msg \"%s\"; \"number\" or \"nil\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.amount ) )
					end
				end


			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"string\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end


		elseif param.type == ai.GameMsgParamType.TIME then

			local strPlaceholderEx = "%$"..param.name.."%_(.-)%$"
			local postfix = string.match( str, strPlaceholderEx ) or ""

			if type( param.value ) == "number" then
				strParam = UI:Time2Str421( param.value, postfix )
			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"number\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end

			if postfix ~= "" then
				strPlaceholder = strPlaceholderEx
			end


		elseif param.type == ai.GameMsgParamType.QUEST_NAME then

			if type( param.value ) == "number" then

				local questId = param.value
				strParam = UI:Quest2Str( questId )

			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"number\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end


		elseif param.type == ai.GameMsgParamType.QUEST_TASK then

			if type( param.value ) == "number" then

				local questId	= param.value
				local baseColor = UI.HudGameMsg:GetTextColor()
				local selColor	= baseColor

				strParam = UI:GetQuestTaskDesc2( questId, baseColor, selColor, nil )

			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"number\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end

		elseif param.type == ai.GameMsgParamType.PLAYER_NAME then

			if type( param.value ) == "number" then

				local playerId	= param.value
				strParam = UI:MakePlayerNameById( playerId, true, false )

			else
				sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"value\" in param %d(name %s, type %s) in msg \"%s\"; \"number\" expected, got \"%s\"", paramIdx, tostring( param.name ), UI:Val2Key( ai.GameMsgParamType, param.type ), strId, type( param.value ) )
			end

		else
			sys.log( "UI:InsertMsgParam()[ERROR]: unhandled param type: %d", param.type )
		end

	else
		sys.log( "UI:InsertMsgParam()[ERROR]: invalid type of field \"type\" in param %d(name %s) in msg \"%s\"; \"number\" expected, got \"%s\"", paramIdx, tostring( param.name ), strId, type( param.type ) )
	end


	-- подстановка

	local numReplacements = 0
	str, numReplacements = string.gsub( str, strPlaceholder, strParam )

	if numReplacements == 0 then
		sys.log( "UI:InsertMsgParam()[ERROR]: cannot find placeholder \"%s\" in msg \"%s\" for param %d(type %s)", param.name, strId, paramIdx, UI:Val2Key( ai.GameMsgParamType, param.type ) )
	end

	return str

end


--
function UI:Region2Str( region )

	local str = "unknown"

	if type( region ) ~= "number" then
		sys.log( "UI:Region2Str()[ERROR]: invalid type of the 1-st parameter (\"region\"); \"number\" expected, got \"%s\"", type( region ) )
		return str
	end

	local strRegion = UI:Val2Key( _G.MasterServer.AuthRegion, region )
	if strRegion == "" then
		sys.log( "UI:Region2Str()[ERROR]: invalid region: %d", region )
		return str
	end

	local strId = string.format( "region_%s", strRegion )
	str = UI:GetStringByName( strId )
	return str

end


--
function UI:UpdateServerData_OnCraftResources( result, requestId, param1, param2 )

	if result == 0 then
		self.serverData.resources = _G.MasterServer_GetCraftResources()
		self.serverData.bInvItemsDirty = true
	end

	requestId = UI.RESOURCES_REQUEST_ID
	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= 0 then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


