--
function UI:GetResourceCraftResult( defName )

	local craftResultDefName = ""
	local count = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetResourceCraftResult()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return craftResultDefName, count
	end

	if not( UI:IsDefResource( defName ) or UI:IsDefBlueprint( defName ) ) then
		sys.log( "UI:GetResourceCraftResult()[ERROR]: \"%s\" is neither resource nor blueprint", defName )
		return craftResultDefName, count
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetResourceCraftResult()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return craftResultDefName, count
	end

	if def.craft_result ~= nil then

		if type( def.craft_result ) == "string" then
			craftResultDefName = def.craft_result
		else
			sys.log( "UI:GetResourceCraftResult()[ERROR]: invalid type of \"_G.Def[\"%s\"].craft_result\"; \"string\" or \"nil\" expected, got \"%s\"", defName, type( def.craft_result ) )
		end

	end

	if craftResultDefName ~= "" then

    	if def.craft_result_count ~= nil then

    		if type( def.craft_result_count ) == "number" then
    			count = def.craft_result_count
    		else
    			sys.log( "UI:GetResourceCraftResult()[ERROR]: invalid type of \"_G.Def[\"%s\"].craft_result_count\"; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.craft_result_count ) )
    		end

		else
			count = 1
    	end

	end

	return craftResultDefName, count

end


--
function UI:GetResourceCraftIngredients( defName )

	local craftIngredients = {}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetResourceCraftIngredients()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return craftIngredients
	end

	if not( UI:IsDefResource( defName ) or UI:IsDefBlueprint( defName ) ) then
		sys.log( "UI:GetResourceCraftIngredients()[ERROR]: \"%s\" is neither resource nor blueprint", defName )
		return craftIngredients
	end

	if not UI:CanResourceBeUsed( defName ) then
		sys.log( "UI:GetResourceCraftIngredients()[ERROR]: resource \"%s\" cannot be used directly for craft", defName )
		return craftIngredients
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetResourceCraftIngredients()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return craftIngredients
	end

	local ingredientsData = nil

	if def.craft_ingredients ~= nil then

		if type( def.craft_ingredients ) == "table" then
			ingredientsData = def.craft_ingredients
		else
			sys.log( "UI:GetResourceCraftIngredients()[ERROR]: invalid type of \"_G.Def[\"%s\"].craft_ingredients\"; \"table\" or \"nil\" expected, got \"%s\"", defName, type( def.craft_ingredients ) )
		end

	end

	if ingredientsData then

		local bHasModuleIngredient = false

		for ingredientIdx = 1, #ingredientsData do

			local ingredientData = ingredientsData[ ingredientIdx ]
			if type( ingredientData ) == "table" then

				if type( ingredientData.def ) == "string" then

					local ingredientDefName = ingredientData.def
					if ingredientDefName ~= "" then

						local ingredientType = -1

						-- чертежи не могут быть ингредиентами - #0042610, комм.(0158091)
						if UI:IsDefResource( ingredientDefName ) then
							ingredientType = UI.resourceIngredientTypes.RESOURCE

						elseif UI:IsDefModule( ingredientDefName ) then
							ingredientType = UI.resourceIngredientTypes.MODULE
						end

						if ingredientType ~= -1 then

    						if ingredientType == UI.resourceIngredientTypes.MODULE then

    							if bHasModuleIngredient then
    								sys.log( "UI:GetResourceCraftIngredients()[ERROR]: several module ingredients for blueprint \"%s\"", defName )
    							end

    							bHasModuleIngredient = true

    						end

    						local count = 1

    						if type( ingredientData.count ) == "number" then
    							count = ingredientData.count
    						else
    							sys.log( "UI:GetResourceCraftIngredients()[ERROR]: invalid type of \"_G.Def[\"%s\"].craft_ingredients[%d].count\"; \"number\" expected, got \"%s\"", defName, ingredientIdx, type( ingredientData.count ) )
    						end

							if ingredientType == UI.resourceIngredientTypes.MODULE and count > 1 then
								sys.log( "UI:GetResourceCraftIngredients()[ERROR]: count more than 1 for module ingredient of blueprint \"%s\"", defName )
							end

    						local ingredient =
    						{
								type	= ingredientType,
    							defName	= ingredientDefName,
    							count	= count,
    						}

    						table.insert( craftIngredients, ingredient )

						else
							sys.log( "UI:GetResourceCraftIngredients()[ERROR]: cannot detect ingredient type for %s in resource %s", ingredientDefName, defName )
						end

					else
						sys.log( "UI:GetResourceCraftIngredients()[ERROR]: empty string of \"_G.Def[\"%s\"].craft_ingredients[%d].def\"", defName, ingredientIdx )
					end

				elseif type( ingredientData.currency ) == "number" then

					local ingredientType = -1

					if ingredientData.currency == _G.GameStore.CreditsType.CT_CREDITS then
						ingredientType = UI.resourceIngredientTypes.CREDITS

					elseif ingredientData.currency == _G.GameStore.CreditsType.CT_GOLD then
						ingredientType = UI.resourceIngredientTypes.GOLD

					elseif ingredientData.currency == _G.GameStore.CreditsType.CT_TOKENS then
						ingredientType = UI.resourceIngredientTypes.TOKENS
					end

					if ingredientType ~= -1 then

						local count = 1

						if type( ingredientData.count ) == "number" then
							count = ingredientData.count
						else
							sys.log( "UI:GetResourceCraftIngredients()[ERROR]: invalid type of \"_G.Def[\"%s\"].craft_ingredients[%d].count\"; \"number\" expected, got \"%s\"", defName, ingredientIdx, type( ingredientData.count ) )
						end

						local ingredient =
						{
							type	= ingredientType,
							count	= count,
						}

    					table.insert( craftIngredients, ingredient )

					else
						sys.log( "UI:GetResourceCraftIngredients()[ERROR]: cannot detect ingredient type for currency %d in resource %s", ingredientData.currency, defName )
					end

				else
					sys.log( "UI:GetResourceCraftIngredients()[ERROR]: invalid type of \"_G.Def[\"%s\"].craft_ingredients[%d].def\"; \"string\" expected, got \"%s\"", defName, ingredientIdx, type( ingredientData.def ) )
				end

			else
				sys.log( "UI:GetResourceCraftIngredients()[ERROR]: invalid type of \"_G.Def[\"%s\"].craft_ingredients[%d]\"; \"table\" expected, got \"%s\"", defName, ingredientIdx, type( ingredientData ) )
			end

		end

	end

	return craftIngredients

end


-- TODO: удалить, использовать UI:GetItemCount()
-- сколько такого ингредиента есть у игрока, раздельно для позолоченных и непозолоченных
function UI:GetItemCraftIngredientInventoryCount( defName )

	local countNonEnchanted	= 0
	local countEnchanted	= 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemCraftIngredientInventoryCount()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return countNonEnchanted, countEnchanted
	end

	if UI:IsDefModule( defName ) then

		local inventoryItems = UI:GetInventoryItemsByDef( defName )
		for invItemIdx, invItem in pairs( inventoryItems ) do

			local equipShipItem = UI:GetEquippedShipItem( invItem.iid )
			if not equipShipItem then

				if UI:IsInventoryItemEnchanted( invItem ) then
					countEnchanted = countEnchanted + invItem.amount
				else
					countNonEnchanted = countNonEnchanted + invItem.amount
				end

			end

		end

	elseif UI:IsDefAmmo( defName ) then

		local inventoryItems = UI:GetInventoryItemsByDef( defName )
		for invItemIdx, invItem in pairs( inventoryItems ) do
			countNonEnchanted = countNonEnchanted + invItem.amount
		end

	elseif UI:IsDefResource( defName ) then
		countNonEnchanted = UI:GetPlayerResourceCount( defName )

	else
		sys.log( "UI:GetItemCraftIngredientInventoryCount()[ERROR]: unhandled ingredient type \"%s\"", defName )
	end

	return countNonEnchanted, countEnchanted

end


--
function UI:GetItemCount( defName, bIncludeAdverted )

	local countTotal = 0

	local storageData =
	{
		inventory_enchanted		= 0,
		inventory_nonEnchanted	= 0,
		inventory_total			= 0,
		inventory_max			= -1,
		equipped_enchanted		= 0,
		equipped_nonEnchanted	= 0,
		equipped_total			= 0,
	}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemCount()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return countTotal, storageData
	end

	if bIncludeAdverted ~= nil then
		if type( bIncludeAdverted ) ~= "boolean" then
			sys.log( "UI:GetItemCount()[ERROR]: invalid type of the 2-nd parameter (\"bIncludeAdverted\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIncludeAdverted ) )
			bIncludeAdverted = nil
		end
	end

	if bIncludeAdverted == nil then
		bIncludeAdverted = false
	end

	if UI:IsDefModule( defName ) then

		local inventoryItems = UI:GetInventoryItemsByDef( defName, bIncludeAdverted )
		for invItemIdx, invItem in pairs( inventoryItems ) do

			local bEnchanted = UI:IsInventoryItemEnchanted( invItem )

			if UI:GetEquippedShipItem( invItem.iid ) then
				if bEnchanted then
					storageData.equipped_enchanted = storageData.equipped_enchanted + invItem.amount
				else
					storageData.equipped_nonEnchanted = storageData.equipped_nonEnchanted + invItem.amount
				end
			else
				if bEnchanted then
					storageData.inventory_enchanted = storageData.inventory_enchanted + invItem.amount
				else
					storageData.inventory_nonEnchanted = storageData.inventory_nonEnchanted + invItem.amount
				end
			end

		end

	elseif UI:IsDefAmmo( defName ) then

		local inventoryItems = UI:GetInventoryItemsByDef( defName, bIncludeAdverted )
		for invItemIdx, invItem in pairs( inventoryItems ) do
			storageData.inventory_nonEnchanted = storageData.inventory_nonEnchanted + invItem.amount
		end

    	for shipItemIdx, shipItem in pairs( UI.serverData.ships ) do
    		for ammoSlotId, ammoInfo in pairs( shipItem.equipAmmo ) do
        		if ammoInfo.def == defName and ammoInfo.amount > 0 then
					storageData.equipped_nonEnchanted = storageData.equipped_nonEnchanted + ammoInfo.amount
        		end
    		end
    	end

	elseif UI:IsDefResource( defName ) or UI:IsDefBlueprint( defName ) then

		storageData.inventory_nonEnchanted	= UI:GetPlayerResourceCount( defName )
		storageData.inventory_max			= UI:GetPlayerResourceMaxCount( defName )

	else
		sys.log( "UI:GetItemCraftIngredientInventoryCount()[ERROR]: unhandled def type (def \"%s\")", defName )
	end

	storageData.inventory_total	= storageData.inventory_enchanted + storageData.inventory_nonEnchanted
	storageData.equipped_total	= storageData.equipped_enchanted + storageData.equipped_nonEnchanted

	countTotal = storageData.inventory_total + storageData.equipped_total

	return countTotal, storageData

end


-- сюда передается, сколько штук требуется создать из чертежа;
-- возвращает, сколько в результате получится позолоченных, а сколько непозолоченных

function UI:GetItemCraftResultCountByEnchantType( blueprintDefName, craftCountTotal )

	local craftCountEnchanted		= 0
	local craftCountNonEnchanted	= 0

	if type( blueprintDefName ) ~= "string" then
		sys.log( "UI:GetItemCraftResultCountByEnchantType()[ERROR]: invalid type of the 1-st parameter (\"blueprintDefName\"); \"string\" expected, got \"%s\"", type( blueprintDefName ) )
		return craftCountNonEnchanted, craftCountEnchanted
	end

	if type( craftCountTotal ) ~= "number" then
		sys.log( "UI:GetItemCraftResultCountByEnchantType()[ERROR]: invalid type of the 2-nd parameter (\"craftCountTotal\"); \"number\" expected, got \"%s\"", type( craftCountTotal ) )
		return craftCountNonEnchanted, craftCountEnchanted
	end

	local moduleIngredient = nil

	local ingredients = UI:GetResourceCraftIngredients( blueprintDefName )
	for ingredientIdx, ingredient in pairs( ingredients ) do

		if ingredient.type == UI.resourceIngredientTypes.MODULE then
			moduleIngredient = ingredient
			break
		end

	end

	if moduleIngredient then

		local needIngredientCount = moduleIngredient.count * craftCountTotal
    	local isIngredientCountNonEnchanted, isIngredientCountEnchanted	= UI:GetItemCraftIngredientInventoryCount( moduleIngredient.defName )

		craftCountEnchanted = math.floor( math.min( needIngredientCount, isIngredientCountEnchanted ) / moduleIngredient.count )

	end

	craftCountNonEnchanted = craftCountTotal - craftCountEnchanted

	return craftCountNonEnchanted, craftCountEnchanted

end


--
function UI:GetResourceCraftPrice( defName, count )

	local priceInfos = {}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetResourceCraftPrice()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return priceInfos
	end

	if count ~= nil then
		if type( count ) ~= "number" then
			sys.log( "UI:GetResourceCraftPrice()[ERROR]: invalid type of the 2-nd parameter (\"count\"); \"number\" expected, got \"%s\"", type( count ) )
			count = nil
		end
	end

	if count == nil then
		count = 1
	end

	local ingredients = UI:GetResourceCraftIngredients( defName )
	for ingredientIdx, ingredient in ipairs( ingredients ) do

		if ingredient.type == UI.resourceIngredientTypes.CREDITS then

			local creditsPriceInfo = {}

			creditsPriceInfo.priceType		= _G.GameStore.CreditsType.CT_CREDITS
			creditsPriceInfo.val			= ingredient.count * count
			creditsPriceInfo.bIsBuyPrice	= true
			creditsPriceInfo.basePrice		= ingredient.count * count

			table.insert( priceInfos, creditsPriceInfo )

		elseif ingredient.type == UI.resourceIngredientTypes.TOKENS then

			local tokensPriceInfo = {}

			tokensPriceInfo.priceType	= _G.GameStore.CreditsType.CT_TOKENS
			tokensPriceInfo.val			= ingredient.count * count
			tokensPriceInfo.bIsBuyPrice	= true
			tokensPriceInfo.basePrice	= ingredient.count * count

			table.insert( priceInfos, tokensPriceInfo )

		elseif ingredient.type == UI.resourceIngredientTypes.GOLD then

			local goldPriceInfo = {}

			goldPriceInfo.priceType		= _G.GameStore.CreditsType.CT_GOLD
			goldPriceInfo.val			= ingredient.count * count
			goldPriceInfo.bIsBuyPrice	= true
			goldPriceInfo.basePrice		= ingredient.count * count

			table.insert( priceInfos, goldPriceInfo )

        end

	end

	return priceInfos

end


-- можно ли на ресурсе вызывать функцию крафта
function UI:CanResourceBeUsed( defName )

	return UI:GetResourceCraftResult( defName ) ~= ""

end


--
function UI:GetPlayerResourceCount( defName, bIncludeAdverted )

	local count = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetPlayerResourceCount()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return count
	end

	if bIncludeAdverted ~= nil then
		if type( bIncludeAdverted ) ~= "boolean" then
			sys.log( "UI:GetPlayerResourceCount()[ERROR]: invalid type of the 2-nd parameter (\"bIncludeAdverted\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIncludeAdverted ) )
			bIncludeAdverted = nil
		end
	end

	if bIncludeAdverted == nil then
		bIncludeAdverted = false
	end

	count = UI.serverData.resources[ defName ] or 0

	if not bIncludeAdverted then
		if count > 0 then

			local advertedCount = UI:GetResourceAdvertedCount( defName )
			count = math.max( count - advertedCount, 0 )

		end
	end

	return count

end


--
function UI:GetPlayerResourceMaxCount( defName )

	local maxCount = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetPlayerResourceMaxCount()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return maxCount
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetPlayerResourceMaxCount()[ERROR]: cannot find Def[\"%s\"]", defName )
		return maxCount
	end

	if def.player_stock_limit ~= nil then
		if type( def.player_stock_limit ) == "number" then
			maxCount = def.player_stock_limit
		else
			sys.log( "UI:GetPlayerResourceMaxCount()[ERROR]: invalid type of Def[\"%s\"].player_stock_limit; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.player_stock_limit ) )
		end
	end

	return maxCount

end


--
function UI:IsEnoughIngredientsForCraftFromResource( defName, count, bIgnoreRefillable, targetIid )

	local bEnough = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsEnoughIngredientsForCraftFromResource()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bEnough
	end

	if not( UI:IsDefResource( defName ) or UI:IsDefBlueprint( defName ) ) then
		sys.log( "UI:IsEnoughIngredientsForCraftFromResource()[ERROR]: \"%s\" is neither resource nor blueprint", defName )
		return bEnough
	end

	if not UI:CanResourceBeUsed( defName ) then
		sys.log( "UI:IsEnoughIngredientsForCraftFromResource()[ERROR]: resource \"%s\" cannot be used directly for craft", defName )
		return bEnough
	end

	if count ~= nil then
		if type( count ) ~= "number" then
			sys.log( "UI:IsEnoughIngredientsForCraftFromResource()[ERROR]: invalid type of the 2-nd parameter (\"count\"); \"number\" \"nil\" expected, got \"%s\"", type( count ) )
			count = nil
		end
	end

	if count == nil then
		count = 1
	end

	if bIgnoreRefillable ~= nil then
		if type( bIgnoreRefillable ) ~= "boolean" then
			sys.log( "UI:IsEnoughIngredientsForCraftFromResource()[ERROR]: invalid type of the 3-rd parameter (\"bIgnoreRefillable\"); \"boolean\" \"nil\" expected, got \"%s\"", type( bIgnoreRefillable ) )
			bIgnoreRefillable = nil
		end
	end

	if bIgnoreRefillable == nil then
		bIgnoreRefillable = false
	end

	if targetIid ~= nil then
    	if type( targetIid ) ~= "userdata" then
    		sys.log( "UI:IsEnoughIngredientsForCraftFromResource()[ERROR]: invalid type of the 4-th parameter (\"targetIid\"); \"userdata\" or \"nil\" expected, got \"%s\"", type( targetIid ) )
    		return bEnough
    	end
	end

	if targetIid == nil then
		targetIid = UI.INVALID_U64_ID
	end

	local targetInventroryItem = nil
	if targetIid ~= UI.INVALID_U64_ID then
		targetInventroryItem = UI:GetInventoryItem( targetIid )
		if not targetInventroryItem then
			sys.log( "UI:IsEnoughIngredientsForCraftFromResource()[ERROR]: cannot find target item" )
		end
	end


	bEnough = true

	local ingredients = UI:GetResourceCraftIngredients( defName )
	for idx, ingredientInfo in pairs( ingredients ) do

		local bCheck = true

		if bIgnoreRefillable then
			if ingredientInfo.type == UI.resourceIngredientTypes.CREDITS or ingredientInfo.type == UI.resourceIngredientTypes.GOLD then
				bCheck = false
			end
		end

		if bCheck then

			if not( ingredientInfo.type == UI.resourceIngredientTypes.MODULE and targetInventroryItem and ingredientInfo.defName == targetInventroryItem.defName ) then
        		if not UI:IsEnoughIngredient( ingredientInfo, count ) then
        			bEnough = false
        			break
        		end
			end

		end

	end

	return bEnough

end


--
function UI:IsEnoughIngredient( ingredientInfo, craftCount )

	if type( ingredientInfo ) ~= "table" then
		sys.log( "UI:IsEnoughIngredient()[ERROR]: invalid type of the 1-st parameter (\"ingredientInfo\" ); \"table\" expected, got \"%s\"", type( ingredientInfo ) )
		return false
	end

	if craftCount ~= nil then
		if type( craftCount ) ~= "number" then
			sys.log( "UI:IsEnoughIngredient()[ERROR]: invalid type of the 2-nd parameter (\"craftCount\"); \"number\" \"nil\" expected, got \"%s\"", type( craftCount ) )
			craftCount = nil
		end
	end

	if craftCount == nil then
		craftCount = 1
	end

	local playerCount = 0


	if ingredientInfo.type == UI.resourceIngredientTypes.RESOURCE then
		playerCount = UI:GetPlayerResourceCount( ingredientInfo.defName )

	elseif ingredientInfo.type == UI.resourceIngredientTypes.MODULE then

		local inventoryItems = UI:GetInventoryItemsByDef( ingredientInfo.defName )
		for idx, inventoryItem in pairs( inventoryItems ) do

			if UI:GetEquippedShipItem( inventoryItem.iid ) == nil then
				playerCount = playerCount + 1
			end

		end

	elseif ingredientInfo.type == UI.resourceIngredientTypes.CREDITS then
		playerCount = UI:GetPlayerMoney( false )

	elseif ingredientInfo.type == UI.resourceIngredientTypes.GOLD then
		playerCount = UI:GetPlayerMoney( true )

	elseif ingredientInfo.type == UI.resourceIngredientTypes.TOKENS then
		playerCount = UI:GetPlayerTokens()

	else
		sys.log( "UI:IsEnoughIngredient()[ERROR]: unhandled ingrediwnt type: %s", tostring( ingredientInfo.type ) )
	end

	return ingredientInfo.count * craftCount <= playerCount

end


--
function UI:IsResourceRare( defName )

	local bRare = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsResourceRare()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bRare
	end

	if not UI:IsDefResource( defName ) then
		sys.log( "UI:IsResourceRare()[ERROR]: \"%s\" is not resource", defName )
		return bRare
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsResourceRare()[ERROR]: cannot find \"%s\"", defName )
		return bRare
	end

	if def.is_rare == nil then
		return bRare
	end

	if type( def.is_rare ) == "boolean" then
		bRare = def.is_rare
	else
		sys.log( "UI:IsResourceRare()[ERROR]: invalid type of _G.Def[\"%s\"].is_rare; \"boolean\" or \"nil\" expected, got \"%s\"", defName, type( def.is_rare ) )
	end

	return bRare

end


--
function UI:CheckShowNextSpecialNotify()

	if not next( UI.specialNotifiesQueue ) then
		return
	end

	if not UI.HangarWnd:IsOnScreen() then
		return
	end

	local specialNotify = table.remove( UI.specialNotifiesQueue, 1 )

	local fnName = string.format( "SpecialNotifyShow_%s", specialNotify.type )
	local fn = UI[ fnName ]

	if fn then
		fn( self, specialNotify )
	else
		UI:SpecialNotifyShow_default( specialNotify )
	end

end


--
function UI:SpecialNotifyShow_default( specialNotify )

	local caption	= UI:GetStringByName( string.format( "specNotify_%s_caption", specialNotify.type ) )
	local msg		= UI:GetStringByName( string.format( "specNotify_%s_msg", specialNotify.type ) )

	self.specialNotifyMsg.hMsg			= UI:MessageBox( caption, msg, UI.MBS_OK )
	self.specialNotifyMsg.specialNotify	= specialNotify

end


--
function UI:SpecialNotifyOnMsg_default( specialNotify, retCode )
end


--
function UI:SpecialNotifyShow_NewAutoRefillOptions( specialNotify )

	local caption	= UI:GetStringByName( string.format( "specNotify_%s_caption", specialNotify.type ) )
	local msg		= UI:GetStringByName( string.format( "specNotify_%s_msg", specialNotify.type ) )

	self.specialNotifyMsg.hMsg			= UI:MessageBox( caption, msg, UI.MBS_YES_NO )
	self.specialNotifyMsg.specialNotify	= specialNotify

end


--
function UI:SpecialNotifyOnMsg_NewAutoRefillOptions( specialNotify, retCode )

	local bYes = retCode == UI.MBRET_YES

	UI.serverData.userData.autoRefill	= bYes
	UI.serverData.userData.autoRepair	= bYes

	UI:SaveServerUserData()

end


--
function UI:GetBundleItemInfo( defName, itemIdx, bFixed )

	local itemInfo = nil

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBundleItemInfo()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return itemInfo
	end

	if type( itemIdx ) ~= "number" then
		sys.log( "UI:GetBundleItemInfo()[ERROR]: invalid type of the 2-nd parameter (\"itemIdx\"); \"number\" expected, got \"%s\"", type( itemIdx ) )
		return itemInfo
	end

	if type( bFixed ) ~= "boolean" then
		sys.log( "UI:GetBundleItemInfo()[ERROR]: invalid type of the 3-rd parameter (\"bFixed\"); \"boolean\" expected, got \"%s\"", type( bFixed ) )
		return itemInfo
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetBundleItemInfo()[ERROR]: cannot find _G.Def[%s]", defName )
		return itemInfo
	end

	if not UI:IsDefBundle( defName ) then
		sys.log( "UI:GetBundleItemInfo()[ERROR]: %s is not bundle", defName )
		return itemInfo
	end

	if bFixed then

    	local items = def.fixed_contents
    	if type( items ) ~= "table" then
    		sys.log( "UI:GetBundleItemInfo()[ERROR]: invalid type of _G.Def[%s].fixed_contents; \"table\" expected, got \"%s\"", defName, type( items ) )
    		return itemInfo
    	end

    	if type( items[ itemIdx ] ) == "table" then
			itemInfo = items[ itemIdx ]
		else
    		sys.log( "UI:GetBundleItemInfo()[ERROR]: invalid type of _G.Def[%s].fixed_contents[%d]; \"table\" expected, got \"%s\"", defName, itemIdx, type( items[ itemIdx ] ) )
    		return itemInfo
    	end

	else

		-- #0045488, комм.(0172316) - сквозная нумерация плейсхолдеров через все таблицы

    	local itemSets = def.random_contents
    	if type( itemSets ) ~= "table" then
    		sys.log( "UI:GetBundleItemInfo()[ERROR]: invalid type of _G.Def[%s].random_contents; \"table\" expected, got \"%s\"", defName, type( itemSets ) )
    		return itemInfo
    	end

		local items = {}

		for itemsSetIdx = 1, #itemSets do

			local itemSet = itemSets[ itemsSetIdx ]
			if type( itemSet ) ~= "table" then

	    		sys.log( "UI:GetBundleItemInfo()[ERROR]: invalid type of _G.Def[%s].random_contents[%d]; \"table\" expected, got \"%s\"", defName, itemsSetIdx, type( itemSets ) )
	    		return itemInfo

			end

			for itemIdxInSet = 1, #itemSet do

				local itemIsNset = itemSet[ itemIdxInSet ]
				if type( itemIsNset ) ~= "table" then

		    		sys.log( "UI:GetBundleItemInfo()[ERROR]: invalid type of _G.Def[%s].random_contents[%d][%d]; \"table\" expected, got \"%s\"", defName, itemsSetIdx, itemIdxInSet, type( itemSets ) )
		    		return itemInfo

				end

				table.insert( items, itemIsNset )

			end

			itemInfo = items[ itemIdx ]

			if not itemInfo then
				sys.log( "UI:GetBundleItemInfo()[ERROR]: cannot find random item %d in \"%s\"", itemIdx, defName  )
			end

		end

	end

	return itemInfo

end


--
function UI:BundleItem2Str( item, bAllowLinks, baseColor )

	local str = "invalid bundle item"

	if type( item ) ~= "table" then
		sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of tghe 1-st parameter (\"item\"); \"table\" expected, got \"%s\"", type( item ) )
		return str
	end

	if bAllowLinks ~= nil then
    	if type( bAllowLinks ) ~= "boolean" then
    		sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of tghe 2-nd parameter (\"bAllowLinks\"); \"boolean\" expected, got \"%s\"", type( bAllowLinks ) )
    		bAllowLinks = nil
    	end
	end

	if bAllowLinks == nil then
		bAllowLinks = false
	end

	if baseColor ~= nil then
    	if type( baseColor ) ~= "number" then
    		sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of tghe 3-rd parameter (\"baseColor\"); \"boolean\" expected, got \"%s\"", type( baseColor ) )
    		baseColor = nil
    	end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	local selColor = UI.TEXT_SEL_COLOR

	local strBaseColor	= UI:Color2Str( baseColor )
	local strSelColor	= UI:Color2Str( selColor )

	local itemType = item.type
	if type( itemType ) ~= "number" then
		sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of the field \"type\"; \"number\" expected, got \"%s\"", type( itemType ) )
		return str
	end

	if UI:Val2Key( ai.BundleContent, itemType ) == "" then
		sys.log( "UI:BundleItem2Str()[ERROR]: invalid item type %d", itemType )
		return str
	end


	if itemType == ai.BundleContent.ITEM then

		str = "invalid ITEM"
		local defName = item.defName

		if type( defName ) ~= "string" then
			sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of the field \"defName\" in item of type ITEM; \"string\" expected, got \"%s\"", type( defName ) )
			defName = ""
		end

		if defName ~= "" then

    		local strName = ""

    		if bAllowLinks then
    			strName = string.format( "$link [type ITEM][params {defName=\"%s\", bEnchanted=%s}]$", defName, tostring( item.bEnchanted ) )
    		else
    			strName = UI:GetEntityLocalizedNameByDef( defName, true )
    			strName = string.format( "%s%s", strName, strBaseColor )
    		end

			local count = item.count

			if type( count ) ~= "number" then

				if UI:IsDefAmmo( defName ) or count ~= nil then
					sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of the field \"count\" in item of type ITEM; \"number\" expected, got \"%s\"", type( count ) )
				end

				count = nil

			end

			if count == nil then
				count = 1
			end

        	if count > 1 then
        		strName = string.format( "%s[%d]", strName, count )
        	end

        	local strId = UI:IsDefAmmo( defName ) and "bundleContent_ITEM_ammo" or "bundleContent_ITEM_module"
    		str = UI:GetStringByName( strId )

			local numSubst = 0
    		str, numSubst = string.gsub( str, "%$item%$", strName )

			if numSubst == 0 then
		  		sys.log( "UI:BundleItem2Str()[ERROR]: cannot find placeholder \"$item$\" in string \"%s\"", strId )
  				str = string.format( "%s %s", str, strName )
			end

		else
			sys.log( "UI:BundleItem2Str()[ERROR]: invalid field \"defName\" in item of type ITEM" )
		end


	elseif itemType == ai.BundleContent.VESSEL then

		local strName = "unknown"
