		if numSubst == 0 then
			sys.log( "UI:BundleItem2Str()[ERROR]: cannot find placeholder \"$name$\" in string \"bundleContent_AVATAR\"" )
  			str = str.." ".. strName
		end


	elseif itemType == ai.BundleContent.MOTTO then

		local strName = "unknown"
		local defName = item.defName

		if type( defName ) ~= "string" then
			sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of the field \"defName\" in item of type MOTTO; \"string\" expected, got \"%s\"", type( defName ) )
			defName = ""
		end

		if defName ~= "" then
			strName = UI:GetMottoString( defName )
		else
			sys.log( "UI:BundleItem2Str()[ERROR]: invalid field \"defName\" in item of type MOTTO" )
		end

    	strName = string.format( "%s%s%s", strSelColor, strName, strBaseColor )

		str = UI:GetStringByName( "bundleContent_MOTTO" )

		local numSubst = 0
		str, numSubst = string.gsub( str, "%$name%$", strName )

		if numSubst == 0 then
			sys.log( "UI:BundleItem2Str()[ERROR]: cannot find placeholder \"$name$\" in string \"bundleContent_MOTTO\"" )
  			str = str.." ".. strName
		end

	elseif itemType == ai.BundleContent.AUTOGEN then

		if item.rollData then

			str = UI:Autogen2StrByRollData( item.rollData, 0, true )
			str = string.format( "%s%s", str, strBaseColor )

		else

			local autogenClassId = -1
			local rank = -1

			if type( item.autogenClassId ) == "number" then
				autogenClassId = item.autogenClassId
			else
				sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of the field \"autogenClassId\" in item of type AUTOGEN; \"number\" expected, got \"%s\"", type( autogenClassId ) )
			end

			if type( item.rank ) == "number" then
				rank = item.rank
			else
				sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of the field \"rank\" in item of type AUTOGEN; \"number\" expected, got \"%s\"", type( rank ) )
			end

			str = UI:Autogen2StrNotRolled( autogenClassId, rank )

			local count = 1

			if type( item.count ) == "number" then
				count = item.count
			else
				sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of the field \"count\" in item of type AUTOGEN; \"number\" expected, got \"%s\"", type( count ) )
			end

			if count > 1 then
				str = string.format( "%s [%d]", str, count )
			end

		end

	elseif itemType == ai.BundleContent.PREMIUM then

		local val = item.val

		if type( val ) ~= "number" then
			sys.log( "UI:BundleItem2Str()[ERROR]: invalid type of the field \"val\" in item of type PREMIUM; \"number\" expected, got \"%s\"", type( val ) )
			val = 0
		end

		str = UI:PremiumTime2Str( val, baseColor, selColor )

	else

		sys.log( "UI:BundleItem2Str()[ERROR]: unhandled item type %d", itemType )

		local itemTypeName = UI:Val2Key( ai.BundleContent, itemType )
		if itemTypeName ~= "" then
			str = itemTypeName
		end

	end

	return str

end


--
function UI:GetBundleItemsPrice( defName )

	local itemsPrice = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBundleItemsPrice()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return itemsPrice
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetBundleItemsPrice()[ERROR]: cannot find _G.Def[%s]", defName )
		return itemsPrice
	end

	local bundlePrice, bBundlePriceGold = UI:GetShopBuyPriceByDef( defName, false, false )

	local itemsPriceFieldName = bBundlePriceGold and "premiumPriceTotal" or "priceTotal"
	itemsPrice = def[ itemsPriceFieldName ]

	if type( itemsPrice ) ~= "number" then
		sys.log( "UI:GetBundleItemsPrice()[ERROR]: invalid type of_G.Def[%s].%s; \"number\" expected, got \"%s\"", defName, itemsPriceFieldName, type( itemsPrice ) )
		itemsPrice = 0
	end

	return itemsPrice

end


--
function UI:GetBundleDesc( defName, bAllowLinks, baseColor )

	local str = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBundleDesc()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return str
	end

	if bAllowLinks ~= nil then
    	if type( bAllowLinks ) ~= "boolean" then
    		sys.log( "UI:GetBundleDesc()[ERROR]: invalid type of the 2-nd parameter (\"bAllowLinks\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bAllowLinks ) )
    		bAllowLinks = nil
    	end
	end

	if bAllowLinks == nil then
		bAllowLinks = false
	end

	if baseColor ~= nil then
    	if type( baseColor ) ~= "number" then
    		sys.log( "UI:GetBundleDesc()[ERROR]: invalid type of the 3-rd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
    		baseColor = nil
    	end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end


	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetBundleDesc()[ERROR]: cannot find _G.Def[%s]", defName )
		return str
	end

	if type( def.uiDesc ) ~= "string" then
		sys.log( "UI:GetBundleDesc()[ERROR]: invalid type of _G.Def[%s].uiDesc; \"string\" expected, got \"%s\"", defName, type( def.uiDesc ) )
		return str
	end


	local function fnSubst( capture )

		local strFixedItemIdx = string.match( capture, "^item(%d+)$" )
		if strFixedItemIdx then

			local fixedItemIdx = tonumber( strFixedItemIdx )

			local item = UI:GetBundleItem( defName, fixedItemIdx, true )
			if item then
				return UI:BundleItem2Str( item, bAllowLinks, baseColor )
			else
				sys.log( "UI:GetBundleDesc()[ERROR]: cannot find item info for fixed item %d in bundle %s", fixedItemIdx, defName )
			end

		else

			local strRandomItemIdx = string.match( capture, "^random(%d+)$" )
			if strRandomItemIdx then

    			local randomItemIdx = tonumber( strRandomItemIdx )

    			local item = UI:GetBundleItem( defName, randomItemIdx, false )
    			if item then
    				return UI:BundleItem2Str( item, bAllowLinks, baseColor )
    			else
    				sys.log( "UI:GetBundleDesc()[ERROR]: cannot find item info for random item %d in bundle %s", randomItemIdx, defName )
    			end

			else
				sys.log( "UI:GetBundleDesc()[ERROR]: unhandled placeholder: %s", capture )
			end

		end

		return nil

	end

	str = UI:GetStringByName( def.uiDesc )

	if str ~= "" then
		str = string.gsub( str, "%$(.-)%$", fnSubst )
		str = string.format( "%s%s", UI:Color2Str( baseColor ), str )
	end

	return str

end


--
function UI:GetBundleItemsFromNotification( ntfParams, bOnlyVisible )

	local items = {}

	if type( ntfParams ) ~= "table" then
		sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: invalid type of the 1-st param ('ntfParams'); \"table\" expected, got \"%s\"", type( ntfParams ) )
		return items
	end

	if ntfParams.bundleContents == nil then
		return items
	end

	if type( ntfParams.bundleContents ) ~= "table" then
		sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: invalid type of \"bundleContents\"; \"table\" expected, got \"%s\"", type( ntfParams.bundleContents ) )
		return items
	end

	if bOnlyVisible ~= nil then
		if type( bOnlyVisible ) ~= "boolean" then
			sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: invalid type of the 2-nd param ('bOnlyVisible'); \"boolean\" or \"nil\" expected, got \"%s\"", type( bOnlyVisible ) )
			bOnlyVisible = nil
		end
	end

	if bOnlyVisible == nil then
		bOnlyVisible = false
	end

	local function fnParseField( itemIdx, fieldName, fieldType, defaultVal, bAllowNil )

		if bAllowNil == nil then
			bAllowNil = false
		end

		local itemData = ntfParams.bundleContents[ itemIdx ]
		local fieldVal = itemData[ fieldName ]

		if type( fieldVal ) == fieldType then
			return fieldVal

		else
			if not( fieldVal == nil and bAllowNil ) then
				sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: invalid type of \"bundleContents[%d].%s\" for item of type ai.BundleContent.%s; \"%s\" expected, got \"%s\"", itemIdx, fieldName, UI:Val2Key( ai.BundleContent, itemData.type ), fieldType, type( fieldVal ) )
			end

			return defaultVal
		end

	end

	for itemIdx, itemData in ipairs( ntfParams.bundleContents ) do

		if type( itemData ) == "table" then

			if type( itemData.type ) == "number" then

        		local item = { type = itemData.type }

        		if itemData.type == ai.BundleContent.ITEM then
					item.defName	= fnParseField( itemIdx, "defName", "string", "" )
					item.count		= fnParseField( itemIdx, "amount", "number", 1, not UI:IsDefAmmo( item.defName ) )
					item.bEnchanted	= fnParseField( itemIdx, "enchantments", "number", 0, true ) ~= 0

        		elseif itemData.type == ai.BundleContent.VESSEL then
					item.defName	= fnParseField( itemIdx, "defName", "string", "" )

        		elseif itemData.type == ai.BundleContent.EXP then
					item.val		= fnParseField( itemIdx, "amount", "number", 0 )

        		elseif itemData.type == ai.BundleContent.CUSTOM_ELEMENT then
					item.defName	= fnParseField( itemIdx, "customElement", "string", "" )

        		elseif itemData.type == ai.BundleContent.TITLE then
					item.id			= fnParseField( itemIdx, "tid", "number", -1 )

        		elseif itemData.type == ai.BundleContent.ACCOUNT_AURA then
					item.defName	= fnParseField( itemIdx, "aura", "string", "" )

        		elseif itemData.type == ai.BundleContent.INVENTORY_EXT then
					item.level		= fnParseField( itemIdx, "invExtLevel", "number", -1 )

        		elseif itemData.type == ai.BundleContent.CRAFT_RESOURCE then
					item.defName	= fnParseField( itemIdx, "defName", "string", "" )
					item.count		= fnParseField( itemIdx, "amount", "number", 1 )

        		elseif itemData.type == ai.BundleContent.BLUEPRINT then
					item.defName	= fnParseField( itemIdx, "defName", "string", "" )
					item.count		= fnParseField( itemIdx, "amount", "number", 1, true )

        		elseif itemData.type == ai.BundleContent.VESSEL_BUDGET then

					local vid = fnParseField( itemIdx, "vid", "userdata", UI.INVALID_U64_ID )

					local shipItem = nil
					if vid ~= UI.INVALID_U64_ID then
    					shipItem = self:GetShipItem( vid, true )
    					if not shipItem then
    						sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: cannot find ship item for vid %s for bundle content of type VESSEL_BUDGET", _G.U64ToStr( vid ) )
    					end
					end

					item.shipDefName	= shipItem and shipItem.defName or ""
					item.count			= fnParseField( itemIdx, "amount", "number", 0 )

        		elseif itemData.type == ai.BundleContent.EVENT_CREDITS then
					item.val		= fnParseField( itemIdx, "amount", "number", 0 )

				elseif itemData.type == ai.BundleContent.AVATAR then
					item.defName	= fnParseField( itemIdx, "avatar", "string", "" )

				elseif itemData.type == ai.BundleContent.MOTTO then
					item.defName	= fnParseField( itemIdx, "motto", "string", "" )

				elseif itemData.type == ai.BundleContent.AUTOGEN then

					item.rollData		= fnParseField( itemIdx, "rollData", "table", nil, true )

					item.autogenClassId	= -1
					item.rank			= -1
					item.count			= 0

					if item.rollData then

						local decomposition = _G.DecompositeAutogenRollData( item.rollData )

						if type( decomposition ) == "table" then

							item.autogenClassId	= decomposition.autogenClass or -1
							item.rank			= decomposition.rank or -1
							item.count			= 1

						else
							sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: invalid type of return value from _G.DecompositeAutogenRollData(); 'table' expected, got '%s'", type( decomposition ) )
						end

					else
						sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: no roll data for ai.BundleContent.AUTOGEN " )
					end

				elseif itemData.type == ai.BundleContent.PREMIUM then
					item.val = fnParseField( itemIdx, "premiumTime", "number", 0 )

        		else
        			sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: unhandled bundle content type: %d(\"%s\")", itemData.type, UI:Val2Key( ai.BundleContent, itemData.type ) )
        		end

				-- SC-100557 - в нотификациях показываются только ауры с флагом show_as_voucher
				local bVisible = true
				if item.type == ai.BundleContent.ACCOUNT_AURA then
					if bOnlyVisible and not UI:IsAccountAuraVoucher( item.defName ) then
						bVisible = false
					end
				end

				if bVisible then
					table.insert( items, item )
				end

			else
				sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: invalid type of \"bundleContents[%d].type\"; \"number\" expected, got \"%s\"", itemIdx, type( itemData.type ) )
			end

		else
			sys.log( "UI:GetBundleItemsFromNotification()[ERROR]: invalid type of \"bundleContents[%d]\"; \"table\" expected, got \"%s\"", itemIdx, type( itemData ) )
		end

	end

	return items

end


--
function UI:GetBundleItem( bundleDefName, itemIdx, bFixed, srcTable, bForShow )

	local item = nil

	if type( bundleDefName ) ~= "string" then
		sys.log( "UI:GetBundleItem()[ERROR]: invalid type of the 1-st parameter (\"bundleDefName\"); \"string\" expected, got \"%s\"", type( bundleDefName ) )
		return item
	end

	if type( itemIdx ) ~= "number" then
		sys.log( "UI:GetBundleItem()[ERROR]: invalid type of the 2-nd parameter (\"itemIdx\"); \"number\" expected, got \"%s\"", type( itemIdx ) )
		return item
	end

	if srcTable ~= nil then
    	if type( srcTable ) ~= "table" then
    		sys.log( "UI:GetBundleItem()[ERROR]: invalid type of the 4-th parameter (\"srcTable\"); \"table\" or \"nil\" expected, got \"%s\"", type( srcTable ) )
    		return item
    	end
	end

	if not srcTable then
    	if type( bFixed ) ~= "boolean" then
    		sys.log( "UI:GetBundleItem()[ERROR]: invalid type of the 3-rd parameter (\"bFixed\"); \"boolean\" expected, got \"%s\"", type( bFixed ) )
    		return item
    	end
	end

	if bForShow ~= nil then
		if type( bForShow ) ~= "boolean" then
			sys.log( "UI:GetBundleItem()[ERROR]: invalid type of the 5-th parameter (\"bForShow\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bForShow ) )
			bForShow = nil
		end
	end

	if bForShow == nil then
		bForShow = true
	end

	local itemData = nil

	if srcTable then

		itemData = srcTable[ itemIdx ]

		if itemData then
			if type( itemData ) ~= "table" then
				sys.log( "UI:GetBundleItem()[ERROR]: invalid type of item with idx %d from custom table for bundle %s; \"table\" expected, got \"%s\"", itemIdx, bundleDefName, type( itemData ) )
				itemData = nil
			end
		end

	else
		itemData = UI:GetBundleItemInfo( bundleDefName, itemIdx, bFixed )
	end

	if itemData == nil then
		sys.log( "UI:GetBundleItem()[ERROR]: cannot find item %d (fixed=%s) from bundle \"%s\"", itemIdx, tostring( bFixed ), bundleDefName )
		return item
	end


	local function fnParseField( fieldName, fieldType, defaultVal, bAllowNil )

		if bAllowNil == nil then
			bAllowNil = false
		end

		local fieldVal = itemData[ fieldName ]

		if type( fieldVal ) == fieldType then
			return fieldVal

		else
			if not( fieldVal == nil and bAllowNil ) then
				sys.log( "UI:GetBundleItem()[ERROR]: invalid type of field \"%s\" in bundle item %d (fixed=%s) from bundle \"%s\"; \"%s\" expected, got \"%s\"", fieldName, itemIdx, tostring( bFixed ), bundleDefName, fieldType, type( fieldVal ) )
			end

			return defaultVal
		end

	end


	if type( itemData.type ) == "number" then

		item = { type = itemData.type }

		item.bElite = fnParseField( "is_elite", "boolean", false, true )

		if itemData.type == ai.BundleContent.ITEM then
			item.defName	= fnParseField( "str_param", "string", "" )
			item.count		= fnParseField( "amount", "number", 1, not UI:IsDefAmmo( item.defName ) )
			item.bEnchanted	= fnParseField( "int_param", "number", 0, true ) ~= 0

		elseif itemData.type == ai.BundleContent.VESSEL then
			item.defName	= fnParseField( "str_param", "string", "" )

		elseif itemData.type == ai.BundleContent.EXP then
			item.val		= fnParseField( "amount", "number", 0 )

		elseif itemData.type == ai.BundleContent.CUSTOM_ELEMENT then
			item.defName	= fnParseField( "str_param", "string", "" )

		elseif itemData.type == ai.BundleContent.TITLE then
			item.id			= fnParseField( "int_param", "number", -1 )

		elseif itemData.type == ai.BundleContent.ACCOUNT_AURA then
			item.defName	= fnParseField( "str_param", "string", "" )

		elseif itemData.type == ai.BundleContent.INVENTORY_EXT then
			item.level		= fnParseField( "int_param", "number", -1 )

		elseif itemData.type == ai.BundleContent.CRAFT_RESOURCE then
			item.defName	= fnParseField( "str_param", "string", "" )
			item.count		= fnParseField( "amount", "number", 1 )

		elseif itemData.type == ai.BundleContent.BLUEPRINT then
			item.defName	= fnParseField( "str_param", "string", "" )
			item.count		= fnParseField( "amount", "number", 1, true )

		elseif itemData.type == ai.BundleContent.VESSEL_BUDGET then

			local shipItem = nil

			local vid = UI:GetShipForCollectingSpecModuleParts()
			if vid ~= UI.INVALID_U64_ID then
				shipItem = UI:GetShipItem( vid )
			else
				-- #0098091 - ругается в лог только если предмет надо отобразить;
				-- иногда это не нужно, например, когда составляется список item2Bundles при загрузке магазина, то сюда заходит
				if bForShow then
					sys.log( "UI:GetBundleItem()[ERROR]: no active budgete ship now, cannot show correctly bundle item of type VESSEL_BUDGET" )
				end
			end

			item.shipDefName	= shipItem and shipItem.defName or ""
			item.count			= fnParseField( "amount", "number", 0 )

		elseif itemData.type == ai.BundleContent.EVENT_CREDITS then
			item.val		= fnParseField( "amount", "number", 0 )

		elseif itemData.type == ai.BundleContent.AVATAR then
			item.defName	= fnParseField( "str_param", "string", "" )

		elseif itemData.type == ai.BundleContent.MOTTO then
			item.defName	= fnParseField( "str_param", "string", "" )

		elseif itemData.type == ai.BundleContent.AUTOGEN then

			local autogenClassName = fnParseField( "str_param", "string", "" )
			item.autogenClassId = _G.AutogenClass and _G.AutogenClass[ autogenClassName ] or -1
			if item.autogenClassId == -1 then
				sys.log( "UI:GetBundleItem()[ERROR]: invalid autogen class \"%s\" in bundle item %d (fixed=%s) from bundle \"%s\"", autogenClassName, itemIdx, tostring( bFixed ), bundleDefName)
			end

			item.rank	= fnParseField( "int_param", "number", -1 )
			item.count	= fnParseField( "amount", "number", 1 )

		elseif itemData.type == ai.BundleContent.PREMIUM then
			item.val = fnParseField( "premiumTime", "number", 0 )

		else
			sys.log( "UI:GetBundleItem()[ERROR]: unhandled bundle content type: %d(\"%s\")", itemData.type, UI:Val2Key( ai.BundleContent, itemData.type ) )
		end

	else
		sys.log( "UI:GetBundleItem()[ERROR]: invalid type of field \"type\" in bundle item %d (fixed=%s) from bundle \"%s\"; \"number\" expected, got \"%s\"", itemIdx, tostring( bFixed ), bundleDefName, type( itemData.type ) )
	end

	return item

end


--
function UI:GetBundleUiContent( defName, bForShow )

	local content = {}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBundleUiContent()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return content
	end

	if not UI:IsDefBundle( defName ) then
		sys.log( "UI:GetBundleUiContent()[ERROR]: %s is not a bundle", defName )
		return content
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetBundleUiContent()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return content
	end

	if def.ui_content == nil then
		return content
	end

	if type( def.ui_content ) ~= "table" then
		sys.log( "UI:GetBundleUiContent()[ERROR]: invalid type of _G.Def[\"%s\"].ui_content; \"table\" or \"nil\" expected, got \"%s\"", defName, type( def.ui_content ) )
		return content
	end

	for blockIdx, blockInfo in ipairs( def.ui_content ) do

		local blockItems = nil

		if type( blockInfo ) == "table" then

			for itemIdx, itemInfo in ipairs( blockInfo ) do

				local item = UI:GetBundleItem( defName, itemIdx, nil, blockInfo, bForShow )
				if item then

    				if not blockItems then
    					blockItems = {}
    				end

    				table.insert( blockItems, item )

				end

			end

		else
			sys.log( "UI:GetBundleUiContent()[ERROR]: invalid type of _G.Def[\"%s\"].ui_content[%d]; \"table\" expected, got \"%s\"", defName, blockIdx, type( blockInfo ) )
		end

		if blockItems then
			table.insert( content, blockItems )
		end

	end

	return content

end


-- возвращает бандл, в котором лежит данный предмет
function UI:GetBundleForItem( itemDefName, mustBeVisibleInBundlesWnd )

	local bundleDefName = ""

	if type( itemDefName ) ~= "string" then
		sys.log( "UI:GetBundleForItem()[ERROR]: invalid type of the 1-st parameter (\"itemDefName\"); \"string\" expected, got \"%s\"", type( itemDefName ) )
		return bundleDefName
	end

	if type( mustBeVisibleInBundlesWnd ) ~= "boolean" then
		sys.log( "UI:GetBundleForItem()[ERROR]: invalid type of the 2-nd parameter (\"mustBeVisibleInBundlesWnd\"); \"boolean\" expected, got \"%s\"", type( mustBeVisibleInBundlesWnd ) )
		mustBeVisibleInBundlesWnd = true
	end

	local possibleBundles = self.serverData.item2Bundles[ itemDefName ]
	if possibleBundles then

		for idx, _bundleDefName in ipairs( possibleBundles ) do

			if UI:IsItemVisibleInBundlesWndByDef( _bundleDefName ) then
				bundleDefName = _bundleDefName
				break
			end

			if not mustBeVisibleInBundlesWnd and bundleDefName == "" then
				if not UI:CantItemBeBoughtByDef( _bundleDefName ) then
					bundleDefName = _bundleDefName
					-- цикл не прерывается, т.к. попытка найти все-таки видимый бандл, даже если это необязательно
				end
			end

		end

	end

	return bundleDefName

end


--
function UI:GetBundleIco( defName )

	local hTex = UI:GetTex( "NoData" )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBundleIco()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return hTex
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetBundleIco()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return hTex
	end

	if type( def.uiPromo ) ~= "string" then
		sys.log( "UI:GetBundleIco()[ERROR]: invalid type of _G.Def[\"%s\"].uiPromo; \"string\" expected, got \"%s\"", defName, type( def.uiPromo ) )
		return hTex
	end

	return UI:GetTex( def.uiPromo )

end


--
function UI:GetBundleIcoBig( defName )

	local hTex = UI:GetTex( "NoData" )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBundleIcoBig()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return hTex
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetBundleIcoBig()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return hTex
	end

	if type( def.uiPromo ) ~= "string" then
		sys.log( "UI:GetBundleIcoBig()[ERROR]: invalid type of _G.Def[\"%s\"].uiPromo; \"string\" expected, got \"%s\"", defName, type( def.uiPromo ) )
		return hTex
	end

	local texName = string.format( "%s_large", def.uiPromo )

	return UI:GetTex( texName )

end


--
function UI:IsJunkSelledImmediate( defName )

	local bImmediate = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsJunkSelledImmediate()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bImmediate
	end

	if not UI:IsDefJunk( defName ) then
		sys.log( "UI:IsJunkSelledImmediate()[ERROR]: %s is not junk", defName )
		return bImmediate
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsJunkSelledImmediate()[ERROR]: cannot find _G.Def[%s]", defName )
		return bImmediate
	end

	if def.direct_reward == nil then
		return bImmediate
	end

	if type( def.direct_reward ) ~= "boolean" then
		sys.log( "UI:IsJunkSelledImmediate()[ERROR]: invalid type of _G.Def[%s].direct_reward; \"boolean\" or \"nil\" expected, got \"%s\"", defName, type( def.direct_reward ) )
		return bImmediate
	end

	bImmediate = def.direct_reward

	return bImmediate

end


-- цена за вычетом стоимости предметов, которые уже имеются у игрока
function UI:GetBundleRealBuyPrice( shopItem, bWithAuraSale )

	local shopPrice = 0

	local tokenPrice		= UI:GetShopTokenPrice( shopItem )
	local eventCreditsPrice	= UI:GetShopEventCreditsPrice( shopItem )

	if tokenPrice then
		shopPrice = tokenPrice

	elseif eventCreditsPrice then
		shopPrice = eventCreditsPrice

	else
		shopPrice = UI:GetShopBuyPrice( shopItem, false, nil, false )
	end

	return UI:GetBundleRealBuyPriceInternal( shopItem, shopPrice, bWithAuraSale )

end


-- базовая цена за вычетом стоимости предметов, которые уже имеются у игрока
function UI:GetBundleRealBaseBuyPrice( shopItem )

	local shopBasePrice = 0

	local baseTokenPrice		= UI:GetShopBaseTokenPrice( shopItem )
	local baseEventCreditsPrice	= UI:GetShopBaseEventCreditsPrice( shopItem )

	if baseTokenPrice then
		shopBasePrice = baseTokenPrice

	elseif baseEventCreditsPrice then
		shopBasePrice = baseEventCreditsPrice

	else
		shopBasePrice = UI:GetShopBaseBuyPrice( shopItem, false, true )
	end

	return UI:GetBundleRealBuyPriceInternal( shopItem, shopBasePrice, false )

end


-- цена за вычетом стоимости предметов, которые уже имеются у игрока
function UI:GetBundleRealBuyPriceByDef( defName, bWithAuraSale )

	local price				= 0
	local priceType			= -1
	local bFullyCollected	= false

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBundleRealBuyPriceByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return price, priceType, bFullyCollected
	end

	local shopItem = UI:GetShopItemByDef( defName )
	if not shopItem then
		sys.log( "UI:GetBundleRealBuyPriceByDef()[ERROR]:cannot find shop item for \"%s\"", defName )
		return price, priceType, bFullyCollected
	end

	price, priceType, bFullyCollected = UI:GetBundleRealBuyPrice( shopItem, bWithAuraSale )
	return price, priceType, bFullyCollected

end


-- базовая цена за вычетом стоимости предметов, которые уже имеются у игрока
function UI:GetBundleRealBaseBuyPriceByDef( defName )

	local price				= 0
	local priceType			= -1
	local bFullyCollected	= false

	if type( defName ) ~= "string" then
		sys.log( "UI:GetBundleRealBaseBuyPriceByDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return price, priceType, bFullyCollected
	end

	local shopItem = UI:GetShopItemByDef( defName )
	if not shopItem then
		sys.log( "UI:GetBundleRealBaseBuyPriceByDef()[ERROR]:cannot find shop item for \"%s\"", defName )
		return price, priceType, bFullyCollected
	end

	price, priceType, bFullyCollected = UI:GetBundleRealBaseBuyPrice( shopItem )
	return price, priceType, bFullyCollected

end



--
function UI:GetBundleRealBuyPriceInternal( shopItem, shopPrice, bWithAuraSale )

	local price				= 0
	local priceType			= -1
	local bFullyCollected	= false

	if type( shopItem ) ~= "table" then
		sys.log( "UI:GetBundleRealBuyPriceInternal()[ERROR]: invalid type of the 1-st parameter (\"shopItem\"); \"table\" expected, got \"%s\"", type( shopItem ) )
		return price, priceType, bFullyCollected
	end

	if type( shopItem.id ) ~= "number" then
		sys.log( "UI:GetBundleRealBuyPriceInternal()[ERROR]: invalid format of the shop item" )
		return price, priceType, bFullyCollected
	end

	if type( shopPrice ) ~= "number" then
		sys.log( "UI:GetBundleRealBuyPriceInternal()[ERROR]: invalid type of the 2-nd parameter (\"shopPrice\"); \"number\" expected, got \"%s\"", type( shopPrice ) )
		return price, priceType, bFullyCollected
	end

	if bWithAuraSale ~= nil then
    	if type( bWithAuraSale ) ~= "boolean" then
    		sys.log( "UI:GetBundleRealBuyPriceInternal()[ERROR]: invalid type of the 3-rd parameter (\"bWithAuraSale\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bWithAuraSale ) )
    		bWithAuraSale = nil
    	end
	end

	if bWithAuraSale == nil then
		bWithAuraSale = true
	end

	if UI:GetShopBaseTokenPrice( shopItem ) then
		priceType = _G.GameStore.CreditsType.CT_TOKENS

	elseif UI:GetShopBaseEventCreditsPrice( shopItem ) then
		priceType = _G.GameStore.CreditsType.CT_EVENT

	else
		local price, bGold = UI:GetShopBaseBuyPrice( shopItem, false )
		priceType = bGold and _G.GameStore.CreditsType.CT_GOLD or _G.GameStore.CreditsType.CT_CREDITS
	end

	local realPrice = _G.GameStore_GetBundlePrice( shopItem.id, shopPrice, priceType, bWithAuraSale )

	if type( realPrice ) ~= "number" then
		sys.log( "UI:GetBundleRealBuyPriceInternal()[ERROR]: invalid type of return value from GameStore_GetBundlePrice() for item \"%s\"; \"number\" expected, got \"%s\"", shopItem.defName, type( realPrice ) )
		realPrice = 0
	end

	if realPrice == -1 then
		bFullyCollected = true
		realPrice = 0
	end

	return realPrice, priceType, bFullyCollected

end


--
function UI:IsBundleContentFullyCollected( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:IsBundleContentFullyCollected()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	local realPrcie, priceType, bFullyCollected = UI:GetBundleRealBuyPriceByDef( defName, false )
	return bFullyCollected

end


--
function UI:IsBundleContentCollected( defName )

	local priceType = -1

	if UI:GetShopBaseTokenPriceByDef( defName ) then
		priceType = _G.GameStore.CreditsType.CT_TOKENS

	elseif UI:GetShopBaseEventCreditsPriceByDef( defName ) then
		priceType = _G.GameStore.CreditsType.CT_EVENT

	else
		local price, bGold = UI:GetShopBaseBuyPriceByDef( defName, false )
		priceType = bGold and _G.GameStore.CreditsType.CT_GOLD or _G.GameStore.CreditsType.CT_CREDITS
	end

	local originalPrice = 0

	if priceType == _G.GameStore.CreditsType.CT_TOKENS then
		originalPrice = UI:GetShopTokenPriceByDef( defName )

	elseif priceType == _G.GameStore.CreditsType.CT_EVENT then
		originalPrice = UI:GetShopEventCreditsPriceByDef( defName )

	else
		originalPrice = UI:GetShopBuyPriceByDef( defName, false, true, false )
	end

	local realPrcie = UI:GetBundleRealBuyPriceByDef( defName, false )

	return realPrcie < originalPrice

end


--
function UI:IsShipCraftable( shipDefName )

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:IsShipCraftable()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return false
	end

	local shipDef = UI:GetDef( shipDefName )
	if not shipDef then
		sys.log( "UI:IsShipCraftable()[ERROR]: cannot find _G.Def[%s]", shipDefName )
		return false
	end

	if shipDef.craftable == nil then
		return false
	end

	if type( shipDef.craftable ) ~= "boolean" then
		sys.log( "UI:IsShipCraftable()[ERROR]: invalid type of _G.Def[%s].craftable; \"boolean\" or \"nil\" expected, got \"%s\"", shipDefName, type( shipDef.craftable ) )
		return false
	end

	return shipDef.craftable

end

