--
function UI:GetShipCraftMoneyPrice( shipDefName )

	local price = 0
	local bGold = false

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipCraftMoneyPrice()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return price, bGold
	end

	-- цена первого крафта
	local shipItem = UI:GetShipItemByDef( shipDefName, false )
	if not shipItem then

		price, bGold = UI:GetShopBuyPriceByDef( shipDefName, false, false, false )

	-- цена рекрафта
	else

		local shipDef = UI:GetDef( shipDefName )
		if not shipDef then
			sys.log( "UI:GetShipCraftMoneyPrice()[ERROR]; cannot find _G.Def[\"%s\"]", shipDefName )
			return price, bGold
		end

		local priceCredits	= 0
		local priceGold		= 0

		if shipDef.recraft_credits ~= nil then
			if type( shipDef.recraft_credits ) == "number" then
				priceCredits = shipDef.recraft_credits
			else
				sys.log( "UI:GetShipCraftMoneyPrice()[ERROR]: invalid type of _G.Def[\"%s\"].recraft_credits; \"number\" or \"nil\" expected, got \"%s\"", type( shipDef.recraft_credits ) )
			end
		end

		if shipDef.recraft_gold ~= nil then
			if type( shipDef.recraft_gold ) == "number" then
				priceGold = shipDef.recraft_gold
			else
				sys.log( "UI:GetShipCraftMoneyPrice()[ERROR]: invalid type of _G.Def[\"%s\"].recraft_gold; \"number\" or \"nil\" expected, got \"%s\"", type( shipDef.recraft_gold ) )
			end
		end

		price, bGold = UI:UnifyPrice( priceCredits, priceGold, false )

	end

	return price, bGold

end


--
function UI:GetShipCraftResourcePrice( shipDefName )

	local resources = {}

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipCraftResourcePrice()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return resources
	end

	if not UI:IsShipCraftable( shipDefName ) then
		sys.log( "UI:GetShipCraftResourcePrice()[ERROR]: ship %s is not craftable", shipDefName )
		return resources
	end

	local shipDef = UI:GetDef( shipDefName )

	if type( shipDef.craftable_reagents ) ~= "table" then
		sys.log( "UI:GetShipCraftResourcePrice()[ERROR]: invalid type of _G.Def[%s].craftable_reagents; \"table\" expected, got \"%s\"", shipDefName, type( shipDef.craftable_reagents ) )
		return resources
	end

	for idx, resourceInfo in pairs( shipDef.craftable_reagents ) do

		if type( resourceInfo ) == "table" then

			if type( resourceInfo.resource ) == "string" then

				local resourceName	= resourceInfo.resource
				local count			= 0

				if type( resourceInfo.amount ) == "number" then
					count = resourceInfo.amount
				else
					sys.log( "UI:GetShipCraftResourcePrice()[ERROR]: invalid type of _G.Def[%s].craftable_reagents[%s].amount; \"number\" expected, got \"%s\"", shipDefName, tostring( idx ), type( resourceInfo.amount ) )
				end

				if not resources[ resourceName ] then
					resources[ resourceName ] = 0
				end

				resources[ resourceName ] = resources[ resourceName ] + count

			else
				sys.log( "UI:GetShipCraftResourcePrice()[ERROR]: invalid type of _G.Def[%s].craftable_reagents[%s].resource; \"string\" expected, got \"%s\"", shipDefName, tostring( idx ), type( resourceInfo.resource ) )
			end

		else
			sys.log( "UI:GetShipCraftResourcePrice()[ERROR]: invalid type of _G.Def[%s].craftable_reagents[%s]; \"table\" expected, got \"%s\"", shipDefName, tostring( idx ), type( resourceInfo ) )
		end

	end

	return resources

end


-- idx - это индекс визуального расположения иконок на экране
function UI:GetShipCraftResourcePriceByIdx( shipDefName, idx )

	local resourceDefName	= ""
	local resourceCount		= 0

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipCraftResourcePriceByIdx()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return resourceDefName, resourceCount
	end

	if type( idx ) ~= "number" then
		sys.log( "UI:GetShipCraftResourcePriceByIdx()[ERROR]: invalid type of the 2-nd parameter (\"idx\"); \"number\" expected, got \"%s\"", type( idx ) )
		return resourceDefName, resourceCount
	end

	if not UI:IsShipCraftable( shipDefName ) then
		sys.log( "UI:GetShipCraftResourcePriceByIdx()[ERROR]: ship %s is not craftable", shipDefName )
		return resourceDefName, resourceCount
	end

	local shipDef = UI:GetDef( shipDefName )

	if type( shipDef.craftable_reagents ) ~= "table" then
		sys.log( "UI:GetShipCraftResourcePriceByIdx()[ERROR]: invalid type of _G.Def[%s].craftable_reagents; \"table\" expected, got \"%s\"", shipDefName, type( shipDef.craftable_reagents ) )
		return resourceDefName, resourceCount
	end

	local resourceInfo = shipDef.craftable_reagents[ idx ]

	if type( resourceInfo ) ~= "table" then
		sys.log( "UI:GetShipCraftResourcePriceByIdx()[ERROR]: invalid type of _G.Def[%s].craftable_reagents[%d]; \"table\" expected, got \"%s\"", shipDefName, idx, type( resourceInfo ) )
		return resourceDefName, resourceCount
	end

	if type( resourceInfo.resource ) ~= "string" then
		sys.log( "UI:GetShipCraftResourcePriceByIdx()[ERROR]: invalid type of _G.Def[%s].craftable_reagents[%d].resource; \"string\" expected, got \"%s\"", shipDefName, idx, type( resourceInfo.resource ) )
		return resourceDefName, resourceCount
	end

	resourceDefName	= resourceInfo.resource

	if type( resourceInfo.amount ) == "number" then
		resourceCount = resourceInfo.amount
	else
		sys.log( "UI:GetShipCraftResourcePriceByIdx()[ERROR]: invalid type of _G.Def[%s].craftable_reagents[%d].amount; \"number\" expected, got \"%s\"", shipDefName, idx, type( resourceInfo.amount ) )
	end

	return resourceDefName, resourceCount

end


--
function UI:GetCraftableShipSpecModules( shipDefName )

	local specModules = {}

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetCraftableShipSpecModules()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return specModules
	end

	if not UI:IsShipCraftable( shipDefName ) then
		sys.log( "UI:GetCraftableShipSpecModules()[ERROR]: ship %s is not craftable", shipDefName )
		return specModules
	end

	local shipDef = UI:GetDef( shipDefName )

	if type( shipDef.SpecialModulesVariants ) ~= "table" then
		sys.log( "UI:GetCraftableShipSpecModules()[ERROR]: invalid type of _G.Def[%s].SpecialModulesVariants; \"table\" expected, got \"%s\"", shipDefName, type( shipDef.SpecialModulesVariants ) )
		return specModules
	end

	for moduleIdx = 1, #shipDef.SpecialModulesVariants do

		local moduleDefName = shipDef.SpecialModulesVariants[ moduleIdx ]
		if type( moduleDefName ) == "string" then
			table.insert( specModules, moduleDefName )
		else
			sys.log( "UI:GetCraftableShipSpecModules()[ERROR]: invalid type of _G.Def[%s].SpecialModulesVariants[%d]; \"string\" expected, got \"%s\"", shipDefName, type( moduleDefName ) )
		end

	end

	return specModules

end


