--
function UI:GetShipCraftedBonus( shipItem, shipLevel )

	local bonusName = ""

	if type( shipItem ) ~= "table" then
		sys.log( "UI:GetShipCraftedBonus()[ERROR]: invalid type of the 1-st parameter (\"shipItem\"); \"table\" expected, got \"%s\"", type( shipItem ) )
		return bonusName
	end

	if type( shipLevel ) ~= "number" then
		sys.log( "UI:GetShipCraftedBonus()[ERROR]: invalid type of the 2-nd parameter (\"shipLevel\"); \"number\" expected, got \"%s\"", type( shipLevel ) )
		return bonusName
	end

	if not UI:IsShipCraftable( shipItem.defName ) then
		sys.log( "UI:GetShipCraftedBonus()[ERROR]: ship \"%s\" is not craftable", shipItem.defName )
		return bonusName
	end

	if shipLevel < 1 or shipLevel > UI:GetShipMaxLevel( shipItem.defName ) then
		sys.log( "UI:GetShipCraftedBonus()[ERROR]: invalid level %d for ship \"%s\"", shipLevel, shipItem.defName )
		return bonusName
	end

	bonusName = _G.GameStore_GetVesselCraftedSpecialGrade( shipItem.vid, shipLevel - 1 )

	if type( bonusName ) ~= "string" then
		sys.log( "UI:GetShipCraftedBonus()[ERROR]: invalid type of return value from _G.GameStore_GetVesselCraftedSpecialGrade(); \"string\" expected, got \"%s\"", type( bonusName ) )
		bonusName = ""
	end

	return bonusName

end


--
function UI:GetShipCraftedBonusByVid( vid, shipLevel )

	local bonusName = ""

	if type( vid ) ~= "userdata" then
		sys.log( "UI:GetShipCraftedBonusByVid()[ERROR]: invalid type of the 1-st parameter (\"vid\"); \"userdata\" expected, got \"%s\"", type( vid ) )
		return bonusName
	end

	local shipItem = UI:GetShipItem( vid, false )
	if not shipItem then
		sys.log( "UI:GetShipCraftedBonusByVid()[ERROR]: cannot find ship item" )
		return bonusName
	end

	return UI:GetShipCraftedBonus( shipItem, shipLevel )

end


--
function UI:UpdateServerData_OnBlueprints( result, requestId, param1, param2 )

	if result ~= 0 then
		return
	end

	UI.serverData.learnedBlueprints = _G.MasterServer_GetBlueprints()

end


--
function UI:UpdateServerData_OnLearnBlueprints( result, requestId, defName )

	if result == _G.GameStore.StoreBuyResult.SBR_OK then

		self.serverData.resources = _G.MasterServer_GetCraftResources()
		self.serverData.bInvItemsDirty = true

		self.serverData.learnedBlueprints = _G.MasterServer_GetBlueprints()

	end

	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:IsBluePrintLearned( defName )

	local bLearned = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsBluePrintLearned()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bLearned
	end

	if not UI:IsDefBlueprint( defName ) then
		sys.log( "UI:IsBluePrintLearned()[ERROR]: \"%s\" is not blueprint", defName )
		return bLearned
	end

	bLearned = UI:IsTrueEx( UI.serverData.learnedBlueprints[ defName ] )

	return bLearned

end


--
function UI:CanLearnBluePrint( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:CanLearnBluePrint()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	if not UI:IsDefBlueprint( defName ) then
		sys.log( "UI:CanLearnBluePrint()[ERROR]: \"%s\" is not blueprint", defName )
		return false
	end

	-- нельзя купить и нет на складе?

	if UI:CantItemBeBoughtByDef( defName ) and UI:GetPlayerResourceCount( defName ) <= 0 then
		return false
	end

	return true

end


--
function UI:IsBlueprintEnchanted( defName )

--	return _G.GameStore_GetCraftEnchantments( defName ) ~= 0

	local bEnchanted = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsBlueprintEnchanted()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bEnchanted
	end

	local ingredients = UI:GetResourceCraftIngredients( defName )
	for ingredientIdx, ingredient in pairs( ingredients ) do

		if ingredient.type == UI.resourceIngredientTypes.MODULE then

			local inventoryItems = UI:GetInventoryItemsByDef( ingredient.defName )
			for invItemIdx, invItem in pairs( inventoryItems ) do

				if UI:IsInventoryItemEnchanted( invItem ) and not self:GetEquippedShipItem( invItem.iid ) then
					bEnchanted = true
					break
				end

			end

		end

		if bEnchanted then
			break
		end

	end

	return bEnchanted

end


-- поле rank, назначение может быть разным
-- предположительно, не используется сейчас нигде, кроме кораблей
-- для экипировки модулей и аммуниции надо использовать UI:GetItemEquipMinRank()/UI:GetItemEquipMaxRank(), для покупки предметов - UI:GetItemRequiredAccountRank()

function UI:GetItemRank( defName )

	local rank = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemRank()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return rank
	end

	if UI:IsDefBlueprint( defName ) then

		local craftResultDefName = UI:GetResourceCraftResult( defName )

		if craftResultDefName == "" then
			sys.log( "UI:GetItemRank()[ERROR]: cannot find craft result for blueprint \"%s\"", defName )
			return rank
		end

		return UI:GetItemRank( craftResultDefName )

	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemRank()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return rank
	end

	if def.rank == nil then
		return rank
	end

	if type( def.rank ) ~= "number" then	-- #0056479,комм.(0225160)
		sys.log( "UI:GetItemRank()[ERROR]: invalid type of _G.Def[\"%s\"].rank; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.rank ) )
		return rank
	end

	rank = def.rank

	return rank

end


-- на корабль какого ранга можно экипировать, используется в паре с UI:GetItemEquipMaxRank()
function UI:GetItemEquipMinRank( defName, def )

	local rank = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemEquipMinRank()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return rank
	end

	if UI:IsDefModule( defName ) or UI:IsDefAmmo( defName ) then

		if not def then
			def = UI:GetDef( defName )
		end

    	if def then

        	if def.rank_min ~= nil then
            	if type( def.rank_min ) == "number" then
    				rank = def.rank_min
    			else
            		sys.log( "UI:GetItemEquipMinRank()[ERROR]: invalid type of _G.Def[\"%s\"].rank_min; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.rank_min ) )
            	end
    		end

		else
    		sys.log( "UI:GetItemEquipMinRank()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		end

	elseif UI:IsDefBlueprint( defName ) then

		local craftResultDefName = UI:GetResourceCraftResult( defName )

		if craftResultDefName ~= "" then
			rank = UI:GetItemEquipMinRank( craftResultDefName )
		else
			sys.log( "UI:GetItemEquipMinRank()[ERROR]: cannot find craft result for blueprint \"%s\"", defName )
		end

	-- #0082990,комм.(0377588) - rank_min/rank_max были введены только для модулей и аммуниции, для остальных используется rank
	else
		rank = UI:GetItemRank( defName )
	end

	return rank

end


-- на корабль какого ранга можно экипировать, используется в паре с UI:GetItemEquipMinRank()
function UI:GetItemEquipMaxRank( defName )

	local rank = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemEquipMaxRank()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return rank
	end

	if UI:IsDefModule( defName ) or UI:IsDefAmmo( defName ) then

    	local def = UI:GetDef( defName )
    	if def then

        	if def.rank_max ~= nil then
            	if type( def.rank_max ) == "number" then
    				rank = def.rank_max
    			else
            		sys.log( "UI:GetItemEquipMaxRank()[ERROR]: invalid type of _G.Def[\"%s\"].rank_max; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.rank_max ) )
            	end
    		end

		else
    		sys.log( "UI:GetItemEquipMaxRank()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		end

	elseif UI:IsDefBlueprint( defName ) then

		local craftResultDefName = UI:GetResourceCraftResult( defName )

		if craftResultDefName ~= "" then
			rank = UI:GetItemEquipMaxRank( craftResultDefName )
		else
			sys.log( "UI:GetItemEquipMaxRank()[ERROR]: cannot find craft result for blueprint \"%s\"", defName )
		end

	-- #0082990,комм.(0377588) - rank_min/rank_max были введены только для модулей и аммуниции, для остальных используется rank
	else
		rank = UI:GetItemRank( defName )
	end

	return rank

end


-- чертежей может быть несколько, здесь возвращается только один (выбирается по некоторым принципам - см. в теле функции)
function UI:GetBlueprintForItemCraft( iteDefName, onlyShownInCraft )

	local blueprintDefName = ""

	if type( iteDefName ) ~= "string" then
		sys.log( "UI:GetBlueprintForItemCraft()[ERROR]: invalid type of the 1-st parameter (\"iteDefName\"); \"string\" expected, got \"%s\"", type( iteDefName ) )
		return blueprintDefName
	end

	if onlyShownInCraft ~= nil then
		if type( onlyShownInCraft ) ~= "boolean" then
			sys.log( "UI:GetBlueprintForItemCraft()[ERROR]: invalid type of the 2-nd parameter (\"onlyShownInCraft\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( onlyShownInCraft ) )
			onlyShownInCraft = nil
		end
	end

	if onlyShownInCraft == nil then
		onlyShownInCraft = false
	end

	local allBlueprints = UI:GetAllBlueprintsForItemCraft( iteDefName )
	if not next( allBlueprints ) then
		return blueprintDefName
	end

	-- выбирается главный, если главных несколько или ни один не главный, то выбирается первый попавшийся #0111179(0521078)
	local function fnSort( info1, info2 )

		if onlyShownInCraft then
			if info1.bShownInCraft ~= info2.bShownInCraft then
				return info1.bShownInCraft
			end
		end

		if info1.bMain ~= info2.bMain then
			return info1.bMain
		end

		return info1.defName < info2.defName

	end

	local blueprintsInfo = {}
	for blueprintIdx, blueprintDefName in pairs( allBlueprints ) do

		local info =
		{
			defName			= blueprintDefName,
			bMain			= UI:IsBlueprintMain( blueprintDefName ),
			bShownInCraft	= UI:CanBlueprintBeShownInCraft( blueprintDefName ),
		}
		table.insert( blueprintsInfo, info )

	end

	table.sort( blueprintsInfo, fnSort )

	if blueprintsInfo[ 1 ].bShownInCraft or not onlyShownInCraft then
		blueprintDefName = blueprintsInfo[ 1 ].defName
	end

	return blueprintDefName

end


--
function UI:GetAllBlueprintsForItemCraft( iteDefName )

	local allBlueprints = {}

	if type( iteDefName ) ~= "string" then
		sys.log( "UI:GetAllBlueprintsForItemCraft()[ERROR]: invalid type of the 1-st parameter (\"iteDefName\"); \"string\" expected, got \"%s\"", type( iteDefName ) )
		return allBlueprints
	end

	allBlueprints = UI.serverData.craftResult2Blueprints[ iteDefName ] or {}
	return allBlueprints

end


-- флаг в чертеже, который используется, если предмет может быть скрафчен несколкими чертежами, и надо выбрать один
function UI:IsBlueprintMain( defName )

	local bMain = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsBlueprintMain()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bMain
	end

	local def = _G.Def[ defName ]
	if not def then
		sys.log( "UI:IsBlueprintMain()[ERROR]: cannot find _G.Def['%s']", defName )
		return bMain
	end

	if def.isMain ~= nil then
		if type( def.isMain ) == "boolean" then
			bMain = def.isMain
		else
			sys.log( "UI:IsBlueprintMain()[ERROR]: invalid type of _G.Def['%s'].isMain; 'boolean' or 'nil' expected, got '%s'", defName, type( def.isMain ) )
		end
	end

	return bMain

end


--
function UI:CanBlueprintBeShownInCraft( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:CanBlueprintBeShownInCraft()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	if not UI:IsDefBlueprint( defName ) then
		sys.log( "UI:CanBlueprintBeShownInCraft()[ERROR]: \"%s\" is not blueprint", defName )
		return false
	end

	if not UI:IsBluePrintLearned( defName ) and UI:GetPlayerResourceCount( defName ) == 0 then

		local bHide = false

		local def = UI:GetDef( defName )

		if def.hide_from_player ~= nil then
			if type( def.hide_from_player ) == "boolean" then
				bHide = def.hide_from_player
			else
				sys.log( "UI:CanBlueprintBeShownInCraft()[ERROR]: invalid type od \"Def.%s.hide_from_player\"; \"boolean\" or \"nil\" expected, got \"%s\"", type( def.hide_from_player ) )
			end
		end

		if bHide then
			return false
		end

	end

	local mainCategory, subCategory = UI:GetItemShopCategory( defName )
	if mainCategory == "" then
		return false
	end

	return true

end


--
function UI:GetItemShopCategory( defName )

	local mainCategory	= ""
	local subCategory	= ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemShopCategory()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return mainCategory, subCategory
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemShopCategory()[ERROR]: cannot find \"_G.Def.%s\"", defName )
		return mainCategory, subCategory
	end

	if def.shopCategory == nil then
		return mainCategory, subCategory
	end

	if type( def.shopCategory ) ~= "string" then
		sys.log( "UI:GetItemShopCategory()[ERROR]: invalid type of \"_G.Def.%s.shopCategory\"; \"string\" or \"nil\" expected, got \"%s\"", defName, type( def.shopCategory ) )
		return mainCategory, subCategory
	end

	if def.shopCategory == "" then
		return mainCategory, subCategory
	end

	mainCategory = def.shopCategory

	if def.shopSubCategory ~= nil then

    	if type( def.shopSubCategory ) == "string" then
			subCategory = def.shopSubCategory
		else
    		sys.log( "UI:GetItemShopCategory()[ERROR]: invalid type of \"_G.Def.%s.shopSubCategory\"; \"string\" or \"nil\" expected, got \"%s\"", defName, type( def.shopSubCategory ) )
    	end

	end

	return mainCategory, subCategory

end


--
function UI:GetGameObjColorScheme( entId, playerId )

	local colorScheme = -1

	local ent = _G.Entities[ entId ]
	if not ent then
		return colorScheme
	end

	local gameplay = _G.GetCurrentGameMode()

	local localPlayerId = UI.HudWnd.localPlayerId

	local friendTeam = _G.CL_GetPlayerTeam( localPlayerId )
	if friendTeam == 0 then
		if gameplay == ai.Gameplay.THREE_TEAMS_DM then
			friendTeam = ai.ThreeTeamsDMTeam1
		else
			friendTeam = 1
		end
	end	

	local myRelationshipGroup	= friendTeam
    local relationshipGroup		= ent:GetRelationshipGroup()
	local relationship			= ai.Relationship:GetRelationship( relationshipGroup, myRelationshipGroup )

	local bSecondEnemy			= false

	local bMySquad		= false
	local bAggressor	= false
	local bCriminal		= false
	local bCivilian		= false

	if playerId ~= -1 then

		local mySqid		= _G.CL_GetPlayerSquad( localPlayerId )
		local playerSqid	= _G.CL_GetPlayerSquad( playerId )

		bMySquad = mySqid ~= UI.INVALID_U64_ID and playerSqid == mySqid

		if gameplay == ai.Gameplay.FREE_SPACE then
			bAggressor, bCriminal, bCivilian = _G.CL_GetFreeSpacePlayerFlags( playerId )
		end

		if gamepadType == ai.Gameplay.THREE_TEAMS_DM and relationship == ai.RelatioshipType.ENEMY then
			bSecondEnemy = UI:IsThreeTeamsDMSecondEnemy( friendTeam, relationshipGroup )
		end

	end

	colorScheme = UI:GetGameObjColorSchemeInternal( relationship, relationshipGroup, bSecondEnemy, gameplay, bMySquad, bAggressor, bCriminal, bCivilian, playerId )
	return colorScheme

end


--
function UI:IsThreeTeamsDMSecondEnemy( friendTeam, enemyTeam )
	local team1 = ai.ThreeTeamsDMTeam1
	local team2 = ai.ThreeTeamsDMTeam2

	local firstEnemy = team2
	if friendTeam == 0 then -- обсервер
		firstEnemy = team2
	else
		firstEnemy = ( friendTeam == team1 ) and team2 or team1
	end

	return enemyTeam ~= firstEnemy
end


