--
function UI:GetGameObjColorSchemeInternal( relationship, relationshipGroup, secondEnemy, gameplay, bMySquad, bAggressor, bCriminal, bCivilian, playerId )

	local colorScheme = -1

    local localPlayerId = _G.Game_LocalClientNum()

	if gameplay == ai.Gameplay.THREE_TEAMS_DM then

		colorScheme = ( colorScheme == -1 and playerId ~= -1 and playerId == localPlayerId ) and UI.gameObjColorSchemes.ME or colorScheme
		colorScheme = ( colorScheme == -1 and bMySquad ) and UI.gameObjColorSchemes.SQUAD or colorScheme
		colorScheme = ( colorScheme == -1 and relationship == ai.RelatioshipType.ENEMY and secondEnemy ) and UI.gameObjColorSchemes.ALIEN or colorScheme
		colorScheme = colorScheme == -1 and l_colorShemesByRelationship[ relationship ] or colorScheme

		--colorScheme =  UI.gameObjColorSchemes.ALIEN
	elseif gameplay ~= ai.Gameplay.FREE_SPACE then

		colorScheme = ( colorScheme == -1 and playerId ~= -1 and playerId == localPlayerId ) and UI.gameObjColorSchemes.ME or colorScheme
		colorScheme = ( colorScheme == -1 and bMySquad ) and UI.gameObjColorSchemes.SQUAD or colorScheme
		colorScheme = ( colorScheme == -1 and relationshipGroup == ai.RelationshipGroups.Alien ) and UI.gameObjColorSchemes.ALIEN or colorScheme
		colorScheme = colorScheme == -1 and l_colorShemesByRelationship[ relationship ] or colorScheme

	else

		colorScheme = ( colorScheme == -1 and playerId ~= -1 and playerId == localPlayerId ) and UI.gameObjColorSchemes.ME or colorScheme
		colorScheme = ( colorScheme == -1 and relationshipGroup == ai.RelationshipGroups.Alien ) and UI.gameObjColorSchemes.ALIEN or colorScheme
		colorScheme = ( colorScheme == -1 and ( relationshipGroup == ai.RelationshipGroups.Cyber2 and relationship == ai.RelatioshipType.ENEMY ) ) and UI.gameObjColorSchemes.ALIEN or colorScheme
		colorScheme = ( colorScheme == -1 and ( relationshipGroup == ai.RelationshipGroups.Default and relationship ~= ai.RelatioshipType.ENEMY ) ) and UI.gameObjColorSchemes.FRIEND or colorScheme
		colorScheme = ( colorScheme == -1 and bMySquad ) and UI.gameObjColorSchemes.SQUAD or colorScheme
		colorScheme = ( colorScheme == -1 and bCivilian ) and UI.gameObjColorSchemes.FRIEND or colorScheme
		colorScheme = ( colorScheme == -1 and ( bCriminal or relationship == ai.RelatioshipType.ENEMY ) ) and UI.gameObjColorSchemes.ENEMY or colorScheme
		colorScheme = ( colorScheme == -1 and bAggressor ) and UI.gameObjColorSchemes.AGGRESSIVE or colorScheme
		colorScheme = colorScheme == -1 and l_colorShemesByRelationship[ relationship ] or colorScheme

	end

	return colorScheme

end


--
function UI:GameObjColorScheme2Color( colorScheme )

	return UI.gameObjColors[ colorScheme ] or UI.WHITE_COLOR

end


--
function UI:GetGameObjColor( entId, playerId )

	local colorScheme = UI:GetGameObjColorScheme( entId, playerId )
	return UI:GameObjColorScheme2Color( colorScheme )

end


--
function UI:GetGameObjColorInternal( relationship, relationshipGroup, secondEnemy, gameplay, bMySquad, bAggressor, bCriminal, bCivilian, playerId )

	local colorScheme = UI:GetGameObjColorSchemeInternal( relationship, relationshipGroup, secondEnemy, gameplay, bMySquad, bAggressor, bCriminal, bCivilian, playerId )
	return UI:GameObjColorScheme2Color( colorScheme )

end


--
function UI:ShowMsgOnFacebookError( eventId, errorCode )

	-- #0056640,комм.(0228651) - не показывается во время игры, если "игрок управляет прицелом"
	if _G.GetCurrentGameMode() ~= ai.Gameplay.NONE and not UI:NeedInput() then
		return
	end

	local eventName = UI:Val2Key( _G.FBEventType, eventId )
	local strEvent = UI:GetStringByName( eventName )

	local tSubst =
	{
		event	= strEvent,
		error	= tostring( errorCode ),
	}

	local msg = UI:GetStringByName( "facebookError" )
	msg = string.gsub( msg, "%$(.-)%$", tSubst )

	UI:MessageBox( UI:GetStringByName( "msgCapt_error" ), msg, UI.MBS_OK )

end


