--
function UI:IsPvpGameplay( gameplay )

	if type( gameplay ) ~= "number" then
		sys.log( "UI:IsPvpGameplay()[ERROR]: invalid type of the 1-st parameter (\"gameplay\"); \"number\" expected, got \"%s\"", type( gameplay ) )
		return false
	end

	if type( ai.GameplayGroups ) ~= "table" then
		sys.log( "UI:IsPvpGameplay()[ERROR]: invalid type of \"ai.GameplayGroups\"; \"table\" expected, got \"%s\"", type( ai.GameplayGroups ) )
		return false
	end

	if type( ai.GameplayGroups.pvp ) ~= "table" then
		sys.log( "UI:IsPvpGameplay()[ERROR]: invalid type of \"ai.GameplayGroups.pvp\"; \"table\" expected, got \"%s\"", type( ai.GameplayGroups.pvp ) )
		return false
	end

	for idx, gmpl in pairs( ai.GameplayGroups.pvp ) do
		if gmpl == gameplay then
			return true
		end
	end

	return false

end


