function UI:IsShipInBattle( shipItem )

	local bInBattle = false

	if type( shipItem ) ~= "table" then
		sys.log( "UI:IsShipInBattle()[ERROR]: invalid type of the 1-st parameter (\"shipItem\"); \"table\" expected, got \"%s\"", type( shipItem ) )
		return bInBattle
	end

	if type( shipItem.lockedInGame ) ~= "userdata" then
		sys.log( "UI:IsShipInBattle()[ERROR]: invalid type of field \"lockedInGame\" for ship %s", _G.U64ToStr( vid ) )
		return bInBattle
	end

	bInBattle = shipItem.lockedInGame ~= UI.INVALID_U64_ID

	return bInBattle

