--
function UI:IsShipQuestTaken( questId )

	local bTaken = false

	if type( questId ) ~= "number" then
		sys.log( "UI:IsShipQuestTaken()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bTaken
	end

	local questData = UI.serverData.shipQuestsById[ questId ]
	if not questData then
		return bTaken
	end

	if type( questData.started ) == "boolean" then
		bTaken = questData.started
	else
		sys.log( "UI:IsShipQuestTaken()[ERROR]: invalid type of field \"started\" for quest %d; \"boolean\" expected, got \"%s\"", questId, type( questData.started ) )
	end

	return bTaken

end


--
function UI:IsShipQuestCompleted( questId )

	local bCompleted = false

	if type( questId ) ~= "number" then
		sys.log( "UI:IsShipQuestCompleted()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return bCompleted
	end

	if UI:IsShipQuestTaken( questId ) then

		local timeLeft = UI:GetShipQuestTimeLeft( questId  )
		if timeLeft <= 0 then
			bCompleted = true
		end

	end

	return bCompleted

end


--
function UI:GetShipQuestTimeLeft( questId )

	local timeLeft = 0

	if type( questId ) ~= "number" then
		sys.log( "UI:GetShipQuestTimeLeft()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return timeLeft
	end

	if not UI:IsShipQuestTaken( questId ) then
		sys.log( "UI:GetShipQuestTimeLeft()[ERROR]: quest %d is not taken", questId )
		return timeLeft
	end

	timeLeft = _G.MasterServer_GetShipQuestTimeLeft( questId )

	if type( timeLeft ) ~= "number" then
		sys.log( "UI:GetShipQuestTimeLeft()[ERROR]: invalid return type from _G.MasterServer_GetShipQuestTimeLeft(); \"number\" expected, got \"%s\"", type( timeLeft ) )
		timeLeft = 0
	end

	return timeLeft

end


