function UI:GetShipQuestMaxTime( questId )

	local maxTime = 0

	if type( questId ) ~= "number" then
		sys.log( "UI:GetShipQuestMaxTime()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return maxTime
	end

	local def = _G.ShipQuests and _G.ShipQuests[ questId ]
