		sys.log( "UI:GetShipQuestMaxTime()[ERROR]: invalid type of \"_G.ShipQuests[%d]\"; \"table\" expected, got \"%s\"", questId, type( def ) )
		return maxTime
	end

	if type( def.duration ) == "number" then
		maxTime = def.duration * 60 * 60 	-- время в duration прописано в часах
	else
		sys.log( "UI:GetShipQuestMaxTime()[ERROR]: invalid type of \"_G.ShipQuests[%d].duration\"; \"number\" expected, got \"%s\"", questId, type( def.duration ) )
	end

	return maxTime

end


