--
function UI:GetShipQuestRecommendedRoles( questId )

	local roles = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetShipQuestRecommendedRoles()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return roles
	end

	local roleMask = UI:GetShipQuestRoleMask( questId )

	for roleName, role in pairs( ai.ShipRoles ) do

		if role ~= ai.ShipRoles.NONE then
			if UI:BitTst( roleMask, role ) then
				table.insert( roles, role )
			end
		end

	end

	table.sort( roles )

	return roles

end


