--
function UI:GetShipQuestRewardCoef( questId, vids, bRound )

	local coef = 0

	if type( questId ) ~= "number" then
		sys.log( "UI:GetShipQuestRewardCoef()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return coef
	end

	if type( vids ) ~= "table" then
		sys.log( "UI:GetShipQuestRewardCoef()[ERROR]: invalid type of the 2-nd parameter (\"vids\"); \"table\" expected, got \"%s\"", type( vids ) )
		return coef
	end

	if bRound ~= nil then
    	if type( bRound ) ~= "boolean" then
    		sys.log( "UI:GetShipQuestRewardCoef()[ERROR]: invalid type of the 3-rt parameter (\"bRound\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bRound ) )
    		bRound = nil
    	end
	end

	if bRound == nil then
		bRound = false
	end

	local roleMask = UI:GetShipQuestRoleMask( questId )

	-- #0059236, комм.(0239140) - округляется в минимальную сторону; сумма - это сумма округленных значений
	if bRound then

		for shipIdx, vid in pairs( vids ) do

			local shipCoef = _G.MasterServer_GetShipQuestRewardCoef( questId, roleMask, { vids[ shipIdx ] } )

        	if type( shipCoef ) ~= "number" then
        		sys.log( "UI:GetShipQuestRewardCoef()[ERROR]: invalid return type from _G.MasterServer_GetShipQuestRewardCoef(); \"number\" expected, got \"%s\"", type( shipCoef ) )
        		shipCoef = 0
        	end

			-- здесь не проценты, а от 0 до 1, поэтому округление до второго знака после запятой
			shipCoef = math.floor( shipCoef * 100 ) / 100

			coef = coef + shipCoef

		end

	else

    	coef = _G.MasterServer_GetShipQuestRewardCoef( questId, roleMask, vids )

    	if type( coef ) ~= "number" then
    		sys.log( "UI:GetShipQuestRewardCoef()[ERROR]: invalid return type from _G.MasterServer_GetShipQuestRewardCoef(); \"number\" expected, got \"%s\"", type( coef ) )
    		coef = 0
    	end

	end

	return coef

end


