--
function UI:GetShipQuestRewards( questId )

	local rewards = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetShipQuestRewards()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return rewards
	end

	local questDef = _G.ShipQuests and _G.ShipQuests[ questId ]
	if type( questDef ) ~= "table" then
		sys.log( "UI:GetShipQuestRewards()[ERROR]: invalid type of \"_G.ShipQuests[%d]\"; \"table\" expected, got \"%s\"", questId, type( questDef ) )
		return rewards
	end


	local credits, bIsItems = _G.MasterServer_GetShipQuestRewards( questId )

	if type( credits ) ~= "number" then
		sys.log( "UI:GetShipQuestRewards()[ERROR]: invalid type of the #1 returned value (credits) from _G.MasterServer_GetShipQuestRewards(); \"number\" expected, got \"%s\"", type( credits ) )
		credits = 0
	end

	if type( bIsItems ) ~= "boolean" then
		sys.log( "UI:GetShipQuestRewards()[ERROR]: invalid type of the #2 returned value (bonus) from _G.MasterServer_GetShipQuestRewards(); \"boolean\" expected, got \"%s\"", type( bIsItems ) )
		bIsItems = false
	end


	-- 1. кредиты

	if credits > 0 then

		local creditsReward =
		{
			rewardType	= UI.questRewardTypes.CREDITS,
			val			= credits,
		}
		table.insert( rewards, creditsReward )

	end

--[[ #0098771,комм.(0455278) - убрана поддержка бандлов
	-- 2. бандл

	if bIsItems then

		if type( questDef.reward_bundle ) == "string" then

    		local bundleReward =
    		{
    			rewardType	= UI.questRewardTypes.ITEM,
                defName		= questDef.reward_bundle,
    			count		= 1,
    		}
    		table.insert( rewards, bundleReward )

		else
			sys.log( "UI:GetShipQuestRewards()[ERROR]: invalid type of \"_G.ShipQuests[%d].reward_bundle\"; \"string\" expectged, got \"%s\"", questId, type( questDef.reward_bundle ) )
		end

	end
]]
	return rewards

end


-- вырожденный случай UI:GetShipQuestRewards() - возвращается только одна награда (которая указана поле ui_reward)
function UI:GetShipQuestSingleReward( questId )

	local singleReward = nil

	if type( questId ) ~= "number" then
		sys.log( "UI:GetShipQuestSingleReward()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return singleReward
	end

	local questDef = _G.ShipQuests and _G.ShipQuests[ questId ]
	if type( questDef ) ~= "table" then
		sys.log( "UI:GetShipQuestSingleReward()[ERROR]: invalid type of \"_G.ShipQuests[%d]\"; \"table\" expected, got \"%s\"", questId, type( questDef ) )
		return singleReward
	end

	if type( questDef.ui_reward ) ~= "string" then
		sys.log( "UI:GetShipQuestSingleReward()[ERROR]: invalid type of _G.ShipQuests[%d].ui_reward; \"string\" expected, got \"%s\"", questId, type( questDef.ui_reward ) )
		return singleReward
	end

    local fieldName2RewardType =
    {
		base_reward_credits	= UI.questRewardTypes.CREDITS,
		reward_bundle		= UI.questRewardTypes.ITEM,
    }

	local singleRewardType = fieldName2RewardType[ questDef.ui_reward ]
	if singleRewardType == nil then
		sys.log( "UI:GetShipQuestSingleReward()[ERROR]: unhandled reward \"%s\" for ship quest %d", questDef.ui_reward, questId )
		return singleReward
	end

	local allRewards = UI:GetShipQuestRewards( questId )

	for rewardIdx, reward in ipairs( allRewards ) do
		if reward.rewardType == singleRewardType then
			singleReward = reward
			break
		end
	end

	if singleReward == nil then
		sys.log( "UI:GetShipQuestSingleReward()[ERROR]: cannot find single reward for ship quest %d", questId )
	end

	return singleReward

end


