--
function UI:UpdateServerData_OnShipQuests( result, requestId, param1, param2 )

	if result ~= 0 then
		return
	end

	UI:UpdateShipQuests()

end


--
function UI:UpdateServerData_OnStartShipQuest( result, requestId, param1, param2 )

	if result ~= _G.MasterServer.ShipQuestOpResult.SQOR_OK then
		return
	end

	UI:UpdateShipQuests()

end


--
function UI:UpdateServerData_OnEndShipQuest( result, requestId, param1, param2 )

	if result ~= _G.MasterServer.ShipQuestOpResult.SQOR_OK then
		return
	end

	UI:UpdateShipQuests()

end


--
function UI:UpdateShipQuests()

	UI.serverData.shipQuests = _G.MasterServer_GetShipQuests()

	UI.serverData.shipQuestsById = {}

	for idx, questData in pairs( UI.serverData.shipQuests ) do
		UI.serverData.shipQuestsById[ questData.id ] = questData
	end

end


--
function UI:GetClanShipData( shipName )

	local data = nil

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipData()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return data
	end

	-- эта проверка - единственное, ради чего эта функция существует, т.к. при передаче пустого имени в _G.MasterServer_ClanShipGet игра падает
	if shipName == "" then
		sys.log( "UI:GetClanShipData()[ERROR]: empty ship name" )
		return data
	end

	data = _G.MasterServer_ClanShipGet( shipName )

	return data

end


--
function UI:ClanShipBasePartIdx2Name( shipName, partIdx )

	local partName = ""

	if type( shipName ) ~= "string" then
		sys.log( "UI:ClanShipBasePartIdx2Name()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return partName
	end

	if type( partIdx ) ~= "number" then
		sys.log( "UI:ClanShipBasePartIdx2Name()[ERROR]: invalid type of the 2-nd parameter (\"partIdx\"); \"number\" expected, got \"%s\"", type( partIdx ) )
		return partName
	end

	if type( _G.ClanShipDefs ) ~= "table" then
		sys.log( "UI:ClanShipBasePartIdx2Name()[ERROR]: invalid type of \"_G.ClanShipDefs\"; \"table\" expected, got \"%s\"", type( _G.ClanShipDefs ) )
		return partName
	end

	local shipDef = _G.ClanShipDefs[ shipName ]
	if type( shipDef ) ~= "table" then
		sys.log( "UI:ClanShipBasePartIdx2Name()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"]\"; \"table\" expected, got \"%s\"", shipName, type( shipDef ) )
		return partName
	end

	local buildOrder = shipDef.ship_build_order
	if type( buildOrder ) ~= "table" then
		sys.log( "UI:ClanShipBasePartIdx2Name()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].ship_build_order\"; \"table\" expected, got \"%s\"", shipName, type( buildOrder ) )
		return partName
	end

	partName = buildOrder[ partIdx ]

	if type( partName ) ~= "string" then
		sys.log( "UI:ClanShipBasePartIdx2Name()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].ship_build_order[%d]\"; \"string\" expected, got \"%s\"", shipName, partIdx, type( partName ) )
		partName = ""
	end

	return partName

end


--
function UI:ClanShipBasePartName2Idx( shipName, partName )

	local partIdx = -1

	if type( shipName ) ~= "string" then
		sys.log( "UI:ClanShipBasePartName2Idx()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return partIdx
	end

	if type( partName ) ~= "string" then
		sys.log( "UI:ClanShipBasePartName2Idx()[ERROR]: invalid type of the 2-nd parameter (\"partName\"); \"string\" expected, got \"%s\"", type( partName ) )
		return partIdx
	end

	if type( _G.ClanShipDefs ) ~= "table" then
		sys.log( "UI:ClanShipBasePartName2Idx()[ERROR]: invalid type of \"_G.ClanShipDefs\"; \"table\" expected, got \"%s\"", type( _G.ClanShipDefs ) )
		return partIdx
	end

	local shipDef = _G.ClanShipDefs[ shipName ]
	if type( shipDef ) ~= "table" then
		sys.log( "UI:ClanShipBasePartName2Idx()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"]\"; \"table\" expected, got \"%s\"", shipName, type( shipDef ) )
		return partIdx
	end

	local buildOrder = shipDef.ship_build_order
	if type( buildOrder ) ~= "table" then
		sys.log( "UI:ClanShipBasePartName2Idx()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].ship_build_order\"; \"table\" expected, got \"%s\"", shipName, type( buildOrder ) )
		return partIdx
	end

	for idx, name in pairs( buildOrder ) do

		if type( idx ) ~= "number" then
			sys.log( "UI:ClanShipBasePartName2Idx()[ERROR]: invalid type of key in \"_G.ClanShipDefs[\"%s\"].ship_build_order\"; \"number\" expected, got \"%s\"", shipName, type( idx ) )
			return partIdx
		end

		if type( name ) ~= "string" then
			sys.log( "UI:ClanShipBasePartName2Idx()[ERROR]: invalid type of in \"_G.ClanShipDefs[\"%s\"].ship_build_order[%d]\"; \"string\" expected, got \"%s\"", shipName, idx, type( name ) )
			return partIdx
		end

		if name == partName then
			partIdx = idx
			break
		end

	end

	if partIdx == -1 then
		sys.log( "UI:ClanShipBasePartName2Idx()[ERROR]: cannot find part \"%s\" in ship \"%s\"", partName, shipName )
	end

	return partIdx

end


