--
function UI:GetClanShipBuildingPartName( shipName )

	local partName	= ""
	local bBase		= false

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipBuildingPartName()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return partName, bBase
	end

	local timeLeft	= 0
	local slotName	= ""

	timeLeft, partName, slotName = _G.MasterServer_ClanShipGetProductionProgress( shipName )

	if partName ~= nil then
    	if type( partName ) ~= "string" then
    		sys.log( "UI:GetClanShipBuildingPartName()[ERROR]: invalid type of #2 return value (partName)  from _G.MasterServer_ClanShipGetProductionProgress(); \"string\" or \"nil\" expected, got \"%s\"", type( partName ) )
			partName = nil
    	end
	end

	if partName == nil then
		partName = ""
	end

	if partName ~= "" then

		if type( slotName ) == "string" then
			bBase = slotName == ""
		else
    		sys.log( "UI:GetClanShipBuildingPartName()[ERROR]: invalid type of #3 return value (slotName)  from _G.MasterServer_ClanShipGetProductionProgress(); \"string\" expected, got \"%s\"", type( slotName) )
		end

	end

	return partName, bBase

end


