--
function UI:GetClanShipMaxBaseParts( shipName )

	local maxParts = 0

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipMaxBaseParts()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return maxParts
	end

	if type( _G.ClanShipDefs ) ~= "table" then
		sys.log( "UI:GetClanShipMaxBaseParts()[ERROR]: invalid type of \"_G.ClanShipDefs\"; \"table\" expected, got \"%s\"", type( _G.ClanShipDefs ) )
		return maxParts
	end

	local shipDef = _G.ClanShipDefs[ shipName ]
	if type( shipDef ) ~= "table" then
		sys.log( "UI:GetClanShipMaxBaseParts()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"]\"; \"table\" expected, got \"%s\"", shipName, type( shipDef ) )
		return maxParts
	end

	local buildOrder = shipDef.ship_build_order
	if type( buildOrder ) ~= "table" then
		sys.log( "UI:GetClanShipMaxBaseParts()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].ship_build_order\"; \"table\" expected, got \"%s\"", shipName, type( buildOrder ) )
		return maxParts
	end

	maxParts = #buildOrder

	return maxParts

end


--
function UI:GetClanShipNumBuiltBaseParts( shipName )

	local numBuiltParts = 0

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipNumBuiltBaseParts()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return numBuiltParts
	end

	local buildInfo = UI:GetClanShipData( shipName )

	if type( buildInfo ) ~= "table" then
		sys.log( "UI:GetClanShipNumBuiltBaseParts()[ERROR]: invalid return type from UI:GetClanShipData(); \"table\" expected, got \"%s\"", type( buildInfo ) )
		return numBuiltParts
	end

	if type( buildInfo.mainParts ) ~= "table" then
		sys.log( "UI:GetClanShipNumBuiltBaseParts()[ERROR]: invalid type of field \"mainParts\"; \"table\" expected, got \"%s\"", type( buildInfo.mainParts ) )
		return numBuiltParts
	end

	if type( buildInfo.partBeingBuilt ) ~= "string" then
		sys.log( "UI:GetClanShipNumBuiltBaseParts()[ERROR]: invalid type of field \"partBeingBuilt\"; \"string\" expected, got \"%s\"", type( buildInfo.partBeingBuilt ) )
		return numBuiltParts
	end

	if type( buildInfo.slotBeingBuilt ) ~= "string" then
		sys.log( "UI:GetClanShipNumBuiltBaseParts()[ERROR]: invalid type of field \"slotBeingBuilt\"; \"string\" expected, got \"%s\"", type( buildInfo.slotBeingBuilt ) )
		return numBuiltParts
	end

	local gatheringPartName	= UI:GetClanShipGatheringMoneyPartName( shipName )
	local buildingPartName	= UI:GetClanShipBuildingPartName( shipName )

	for idx, partName in pairs( buildInfo.mainParts ) do

		if type( partName ) == "string" then

			if partName ~= gatheringPartName and partName ~= buildingPartName then
				numBuiltParts = numBuiltParts + 1
			end

		else
			sys.log( "UI:GetClanShipNumBuiltBaseParts()[ERROR]: invalid type of field \"mainParts[%s]\"; \"string\" expected, got \"%s\"", tostring( idx ), type( partName ) )
			numBuiltParts = 0
			break
		end

	end

	return numBuiltParts

end


