		sys.log( "UI:GetClanShipPartPrice()[ERROR]: invalid type of \"_G.ClanShipParts\"; \"table\" expected, got \"%s\"", type( _G.ClanShipParts ) )
		return price
	end

	local partDef = _G.ClanShipParts[ partName ]
	if type( partDef ) ~= "table" then
		sys.log( "UI:GetClanShipPartPrice()[ERROR]: invalid type of \"_G.ClanShipParts[\"%s\"]\"; \"table\" expected, got \"%s\"", partName, type( partDef ) )
		return price
	end

	if type( partDef.price ) == "number" then
		price = partDef.price
	else
		sys.log( "UI:GetClanShipPartPrice()[ERROR]: invalid type of \"_G.ClanShipParts[\"%s\"].price\"; \"number\" expected, got \"%s\"", partName, type( partDef.price ) )
	end

	return price

end


-- начал строиться или уже построен
function UI:IsClanShipBuildStarted( shipName )

	local bStarted = false

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipEquippedFitPartInSlot()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return bStarted
	end

	-- это по сути хак; нет прямого параметра в корабле - "была начата постройка"
	bStarted = UI:GetClanShipNumBuiltBaseParts( shipName ) > 0 or UI:GetClanShipBuildingPartName( shipName ) ~= "" or UI:GetClanShipGatheringMoneyPartName( shipName ) ~= ""
	return bStarted

end


-- корабль, который в коде помечен как "текущий"
function UI:GetCurrentClanShipName()

	local shipName = ""

	if not UI.Clan:IsInClan() then
		sys.log( "UI:GetCurrentClanShipName()[ERROR]: not in clan" )
		return shipName
	end

	local clanDesc = _G.MasterServer_ClanGetDesc()
	if type( clanDesc ) ~= "table" then
		sys.log( "UI:GetCurrentClanShipName()[ERROR]: invalid type of return value from MasterServer_ClanGetDesc(); \"table\" expected, got \"%s\"", type( clanDesc ) )
		return shipName
	end

	if clanDesc.currentClanShip ~= nil then
		if type( clanDesc.currentClanShip ) == "string" then
			shipName = clanDesc.currentClanShip
		else
			sys.log( "UI:GetCurrentClanShipName()[ERROR]: invalid type of \"currentClanShip\"; \"string\" or \"nil\" expected, got \"%s\"", type( clanDesc.currentClanShip ) )
		end
	end

	return shipName

end


-- все корабли, которые могут быть построены
function UI:GetAllClanShipNames()

	local shipNames = {}

	if type( _G.ClanShipDefs ) ~= "table" then
		sys.log( "UI:GetAllClanShipNames()[ERROR]: invalid type of \"_G.ClanShipDefs\"; \"table\" expected, got \"%s\"", type( _G.ClanShipDefs ) )
		return shipNames
	end

	for shipName, def in pairs( _G.ClanShipDefs ) do

		if type( shipName ) == "string" then
			table.insert( shipNames, shipName )
		else
			sys.log( "UI:GetAllClanShipNames()[ERROR]: invalid type of key in table \"_G.ClanShipDefs\"; \"string\" expected, got \"%s\"", type( shipName ) )
		end

	end

	table.sort( shipNames )

	return shipNames

end


--
function UI:GetClanShipEquippedFitPartInSlot( shipName, slotName )

	local partName = ""

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipEquippedFitPartInSlot()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return partName
	end

	if type( slotName ) ~= "string" then
		sys.log( "UI:GetClanShipEquippedFitPartInSlot()[ERROR]: invalid type of the 2-nd parameter (\"slotName\"); \"string\" expected, got \"%s\"", type( slotName ) )
		return partName
	end

	local buildInfo = UI:GetClanShipData( shipName )

	if type( buildInfo ) ~= "table" then
		sys.log( "UI:GetClanShipEquippedFitPartInSlot()[ERROR]: invalid return type from UI:GetClanShipData(); \"table\" expected, got \"%s\"", type( buildInfo ) )
		return partName
	end

	if type( buildInfo.moduleSlots ) ~= "table" then
		sys.log( "UI:GetClanShipEquippedFitPartInSlot()[ERROR]: invalid type of field \"mainParts\"; \"table\" expected, got \"%s\"", type( buildInfo.moduleSlots ) )
		return partName
	end

	for slot, slotData in pairs( buildInfo.moduleSlots ) do

		if slot == slotName then

    		if type( slotData ) == "table" then

				if slotData.fit ~= nil then

					if type( slotData.fit ) == "string" then
						partName = slotData.fit
					else
    					sys.log( "UI:GetClanShipEquippedFitPartInSlot()[ERROR]: invalid type of field \"moduleSlots[\"%s\"].fit\"; \"string\" or \"nil\" expected, got \"%s\"", slot, type( slotData.fit ) )
					end

				end

    		else
    			sys.log( "UI:GetClanShipEquippedFitPartInSlot()[ERROR]: invalid type of field \"moduleSlots[\"%s\"]\"; \"table\" expected, got \"%s\"", slot, type( slotData ) )
    		end

			break

		end

	end

	return partName

end


