	local partName = ""

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipBuildingFitPartInSlot()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
