	if type( slotName ) ~= "string" then
		sys.log( "UI:GetClanShipBuildingFitPartInSlot()[ERROR]: invalid type of the 2-nd parameter (\"slotName\"); \"string\" expected, got \"%s\"", type( slotName ) )
		return partName
	end

	local timeLeft, buildingPartName, buildingSlotName = _G.MasterServer_ClanShipGetProductionProgress( shipName )

