--
function UI:GetClanShipFitSlots( shipName, bVisibleOnly )

	local slotNames = {}

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipFitSlots()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return partName
	end

	if bVisibleOnly ~= nil then
    	if type( bVisibleOnly ) ~= "boolean" then
    		sys.log( "UI:GetClanShipFitSlots()[ERROR]: invalid type of the 2-nd parameter (\"bVisibleOnly\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bVisibleOnly ) )
			bVisibleOnly = false
    	end
	end

	if bVisibleOnly == nil then
		bVisibleOnly = false
	end

	if type( _G.ClanShipDefs ) ~= "table" then
		sys.log( "UI:GetClanShipFitSlots()[ERROR]: invalid type of \"_G.ClanShipDefs\"; \"table\" expected, got \"%s\"", type( _G.ClanShipDefs ) )
		return slotNames
	end

	local shipDef = _G.ClanShipDefs[ shipName ]

	if type( shipDef ) ~= "table" then
		sys.log( "UI:GetClanShipFitSlots()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"]\"; \"table\" expected, got \"%s\"", shipName, type( shipDef ) )
		return slotNames
	end

	if shipDef.slots == nil then
		return slotNames
	end

	if type( shipDef.slots ) ~= "table" then
		sys.log( "UI:GetClanShipFitSlots()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].slots\"; \"table\" expected, got \"%s\"", shipName, type( shipDef ) )
		return slotNames
	end

	for slotName, slotInfo in pairs( shipDef.slots ) do

		if type( slotName ) == "string" then

			if bVisibleOnly then

				local bVisible = true

				if slotInfo.visible ~= nil then
					if type( slotInfo.visible ) == "boolean" then
						bVisible = slotInfo.visible
					else
						sys.log( "UI:GetClanShipFitSlots()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].slots[\"%s\"].visible\"; \"boolean\" or \"nil\" expected, got \"%s\"", shipName, slotName, type( slotInfo.visible ) )
					end
				end

				if bVisible then
					table.insert( slotNames, slotName )
				end

			end

		else
			sys.log( "UI:GetClanShipFitSlots()[ERROR]: invalid key type in \"_G.ClanShipDefs[\"%s\"].slots\"; \"string\" expected, got \"%s\"", shipName, type( slotName ) )
		end

	end

	return slotNames

end


