--
function UI:ClanShipPart2Str( partName, bWithColor, bSelColor )

	local str = "unknown"

	if type( partName ) ~= "string" then
		sys.log( "UI:ClanShipPart2Str()[ERROR]: invalid type of the 1-st parameter (\"partName\"); \"string\" expected, got \"%s\"", type( partName ) )
		return str
	end

	if bWithColor ~= nil then
		if type( bWithColor ) ~= "boolean" then
			sys.log( "UI:ClanShipPart2Str()[ERROR]: invalid type of the 2-nd parameter (\"bWithColor\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bWithColor ) )
			bWithColor = nil
		end
	end

	if bWithColor == nil then
		bWithColor = false
	end

	if bWithColor then

    	if bSelColor ~= nil then
    		if type( bSelColor ) ~= "boolean" then
    			sys.log( "UI:ClanShipPart2Str()[ERROR]: invalid type of the 3-rd parameter (\"bSelColor\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bSelColor ) )
    			bSelColor = nil
    		end
    	end

		if bSelColor == nil then
			bSelColor = false
		end

	end

	local strId = string.format( "clanship_part_name_%s", partName )
	str = UI:GetStringByName( strId )

	if bWithColor then

		local color = UI:GetClanShipPartColor( partName, bSelColor )
		str = string.format( "%s%s", UI:Color2Str( color ), str )

	end

	return str

end


--
function UI:GetClanShipPartColor( partName, bSel )

	local color = UI.WHITE_COLOR

	if type( partName ) ~= "string" then
		sys.log( "UI:GetClanShipPartColor()[ERROR]: invalid type of the 1-st parameter (\"partName\"); \"string\" expected, got \"%s\"", type( partName ) )
		return color
	end

	if bSel ~= nil then
		if type( bSel ) ~= "boolean" then
			sys.log( "UI:ClanShipPart2Str()[ERROR]: invalid type of the 2-nd parameter (\"bSel\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bSel ) )
			bSel = nil
		end
	end

	if bSel == nil then
		bSel = false
	end

	local itemColors = UI.itemsColors[ UI.CLAN_SHIP_PART_COLOR_ID ]
	if itemColors then
		color = bSel and itemColors.sel or itemColors.base
	else
		sys.log( "UI:GetClanShipPartColor()[ERROR]: cannot find color for clan ship part" )
	end

	return color or UI.WHITE_COLOR

end


