--
function UI:IsClanShipInDock( shipName )

    local bInDock = false

	if type( shipName ) ~= "string" then
		sys.log( "UI:IsClanShipInDock()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return bInDock
	end

	if not UI:IsClanShipBuildStarted( shipName ) then
		return bInDock
	end

	local zoneId = UI:GetClanShipZone( shipName )

	if zoneId ~= -1 then

		local shipStationRace	= UI:GetClanShipStationRace( shipName )
		local zoneStationRace	= UI:GetZoneClanShipStationRace( zoneId )

		if zoneStationRace ~= -1 and zoneStationRace == shipStationRace then
			bInDock = true
		end

	end

	return bInDock

end


--
function UI:GetClanShipZone( shipName )

	local zoneId = -1

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipZone()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return zoneId
	end

	if not UI:IsClanShipBuildStarted( shipName ) then
		return zoneId
	end

	local shipData = UI:GetClanShipData( shipName )
	if type( shipData ) ~= "table" then
		sys.log( "UI:GetClanShipZone()[ERROR]: invalid type of return value from MasterServer_ClanShipGet(); \"table\" expected, got \"%s\"", type( shipData ) )
		return zoneId
	end

	if shipData.curZone ~= nil then
    	if type( shipData.curZone ) == "number" then
			zoneId = shipData.curZone
		else
    		sys.log( "UI:GetClanShipZone()[ERROR]: invalid type of field \"curZone\"; \"number\" expected, got \"%s\"", type( shipData.curZone ) )
    	end
	end

	if zoneId == 0 then
		zoneId = -1
	end

	if zoneId == -1 then
		sys.log( "UI:GetClanShipZone()[ERROR]: cannot find zone for clan ship \"%s\"", shipName )
	end

	return zoneId

end


--
function UI:CanClanBuildClanShip()

	if not UI.Clan:IsInClan() then
		sys.log( "UI:CanClanBuildClanShip()[ERROR]: not in clan" )
		return false
	end

	local clanDesc = _G.MasterServer_ClanGetDesc()

	if type( clanDesc ) ~= "table" then
		sys.log( "UI:CanClanBuildClanShip()[ERROR]: invalid type of return value from _G.MasterServer_ClanGetDesc(); \"table\" expectged, got \"%s\"", type( clanDesc ) )
		return false
	end

	if type( clanDesc.canBuildShip ) ~= "boolean" then
		sys.log( "UI:CanClanBuildClanShip()[ERROR]: invalid type of \"canBuildShip\"; \"boolean\" expectged, got \"%s\"", type( clanDesc.canBuildShip ) )
		return false
	end

	return clanDesc.canBuildShip

end


--
function UI:IsClanShipFitSlotAutofit( shipName, slotName )

	local bAutofit = false

	if type( shipName ) ~= "string" then
		sys.log( "UI:IsClanShipFitSlotAutofit()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return bAutofit
	end

	if type( slotName ) ~= "string" then
		sys.log( "UI:IsClanShipFitSlotAutofit()[ERROR]: invalid type of the 2-nd parameter (\"slotName\"); \"string\" expected, got \"%s\"", type( slotName ) )
		return bAutofit
	end

	local shipDef = _G.ClanShipDefs[ shipName ]

	if type( shipDef ) ~= "table" then
		sys.log( "UI:IsClanShipFitSlotAutofit()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"]\"; \"table\" expected, got \"%s\"", shipName, type( shipDef ) )
		return bAutofit
	end

	if type( shipDef.slots ) ~= "table" then
		sys.log( "UI:IsClanShipFitSlotAutofit()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].slots\"; \"table\" expected, got \"%s\"", shipName, type( shipDef ) )
		return bAutofit
	end

	local slotInfo = nil

	for name, info in pairs( shipDef.slots ) do

		if name == slotName then
			slotInfo = info
			break
		end

	end

	if not slotInfo then
		sys.log( "UI:IsClanShipFitSlotAutofit()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].slots[\"%s\"]\"; \"table\" expected, got \"%s\"", shipName, slotName, type( slotInfo ) )
		return bAutofit
	end

	if slotInfo.autofit_line ~= nil then

		if type( slotInfo.autofit_line ) == "number" then
			bAutofit = slotInfo.autofit_line ~= 0
		else
			sys.log( "UI:IsClanShipFitSlotAutofit()[ERROR]: invalid type of \"_G.ClanShipDefs[\"%s\"].slots[\"%s\"].autofit_line\"; \"number\" or \"nil\" expected, got \"%s\"", shipName, slotName, type( slotInfo.autofit_line ) )
		end

	end

	return bAutofit

end


--
function UI:GetIridium()

	local money = 0

	if UI.Clan:IsInClan() then

		local money_u64 = UI.Clan:GetResources( _G.MasterServer.ClanResource.CRES_IRIDIUM )

		if money_u64.h > 0 then
			money = tonumber( _G.U64ToStr( money_u64 ) )
		else
			money = money_u64.l
		end

	else
		sys.log( "UI:GetIridium()[ERROR]: not in clan" )
	end

	return money

end


