--
function UI:GetClanShipBuildingBoostTimeDelta( shipName, money, bClanMoney )

	local timeDelta = 0

	if type( shipName ) ~= "string" then
		sys.log( "UI:GetClanShipBuildingBoostTimeDelta()[ERROR]: invalid type of the 1-st parameter (\"shipName\"); \"string\" expected, got \"%s\"", type( shipName ) )
		return timeDelta
	end

	if type( money ) ~= "number" then
		sys.log( "UI:GetClanShipBuildingBoostTimeDelta()[ERROR]: invalid type of the 2-nd parameter (\"money\"); \"number\" expected, got \"%s\"", type( money ) )
		return timeDelta
	end

	if type( bClanMoney ) ~= "boolean" then
		sys.log( "UI:GetClanShipBuildingBoostTimeDelta()[ERROR]: invalid type of the 3-rd parameter (\"bClanMoney\"); \"boolean\" expected, got \"%s\"", type( bClanMoney ) )
		return timeDelta
	end

	local timeDelta = _G.MasterServer_ClanShipGetBoostedBuildingTime( shipName, money, bClanMoney )
	if type( timeDelta ) ~= "number" then
		sys.log( "UI:GetClanShipBuildingBoostTimeDelta()[ERROR]: invalid type of return val from \"_G.MasterServer_ClanShipGetBoostedBuildingTime()\"; \"number\" expected, got \"%s\"", type( timeDelta ) )
		timeDelta = 0
	end

	if timeDelta > 0 then
		sys.log( "UI:GetClanShipBuildingBoostTimeDelta()[ERROR]: positive time delta; negative or 0 expected" )
		timeDelta = 0
	end

	timeDelta = math.abs( timeDelta )

	return timeDelta

end


