--
function UI:IsEnqueued()

	local bEnqueued = false

	local queueInfo = _G.MasterServer_GetQueueInfo()
	if type( queueInfo ) ~= "table" then
		sys.log( "UI:IsEnqueued()[ERROR]: invalid type of return value #1 from _G.MasterServer_GetQueueInfo(); \"table\" expected, got \"%s\"", type( queueInfo ) )
		return bEnqueued
	end

	if type( queueInfo.inQueue ) == "boolean" then
		bEnqueued = queueInfo.inQueue
	else
		sys.log( "UI:IsEnqueued()[ERROR]: invalid type of field \"inQueue\"; \"boolean\" expected, got \"%s\"", type( queueInfo.inQueue ) )
	end

	return bEnqueued

end


--
function UI:IsPvpEnqueued()

	local bPvp = false

	local queueInfo = _G.MasterServer_GetQueueInfo()
	if type( queueInfo ) ~= "table" then
		sys.log( "UI:IsPvpEnqueued()[ERROR]: invalid type of return value #1 from _G.MasterServer_GetQueueInfo(); \"table\" expected, got \"%s\"", type( queueInfo ) )
		return bPvp
	end

	if type( queueInfo.inQueue ) ~= "boolean" then
		sys.log( "UI:IsPvpEnqueued()[ERROR]: invalid type of field \"inQueue\"; \"boolean\" expected, got \"%s\"", type( queueInfo.inQueue ) )
		return bPvp
	end

	if not queueInfo.inQueue then
		return bPvp
	end

	if queueInfo.enqueuementParams == nil then
		return bPvp
	end

	if type( queueInfo.enqueuementParams ) ~= "table" then
		sys.log( "UI:IsPvpEnqueued()[ERROR]: invalid type of field \"inQueue\"; \"table\" or \"nil\" expected, got \"%s\"", type( queueInfo.enqueuementParams ) )
		return bPvp
	end

	bPvp = UI:IsTrueEx( queueInfo.enqueuementParams.arcade )

	return bPvp

end


