--
function UI:GetUniverseZoneOwner( zoneId )

	local ownerCid = UI.INVALID_U64_ID

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetUniverseZoneOwner()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return ownerCid
	end

	local cid = UI.Universe:GetSectorOwner( zoneId )

	if cid == nil then
		return ownerCid
	end

	if type( cid ) ~= "userdata" then
		sys.log( "UI:GetUniverseZoneOwner()[ERROR]: invalid type of zone owner data; \"userdata\" or \"nil\" expected, got \"%s\"", type( cid ) )
		return ownerCid
	end

	ownerCid = cid

	return ownerCid

end


--
function UI:GetUniverseZoneHealth( zoneId )

	local health = 0

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetUniverseZoneHealth()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return health
	end

	local zoneData = UI.Universe:GetSectorById( zoneId )
	if type( zoneData ) ~= "table" then
		sys.log( "UI:GetUniverseZoneHealth()[ERROR]: invalid type of zone data for zone %d; \"table\" expected, got \"%s\"", zoneId, type( zoneData ) )
		return health
	end

	if type( zoneData.health ) ~= "number" then
		sys.log( "UI:GetUniverseZoneHealth()[ERROR]: invalid type of zone health for zone %d; \"number\" expected, got \"%s\"", zoneId, type( zoneData.health ) )
		return health
	end

	health = zoneData.health

	return health

end


--
function UI:GetUniverseZoneTmid( zoneId )

	local tmid = UI.INVALID_U64_ID

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetUniverseZoneTmid()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return tmid
	end

	local zoneData = UI.Universe:GetSectorById( zoneId )
	if type( zoneData ) ~= "table" then
		sys.log( "UI:GetUniverseZoneTmid()[ERROR]: invalid type of zone data for zone %d; \"table\" expected, got \"%s\"", zoneId, type( zoneData ) )
		return tmid
	end

	if zoneData.tmid ~= nil then
    	if type( zoneData.tmid ) == "userdata" then
			tmid = zoneData.tmid
		else
    		sys.log( "UI:GetUniverseZoneTmid()[ERROR]: invalid type of zone tmid for zone %d; \"userdata\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneData.tmid ) )
    	end
	end

	return tmid

end


