--
function UI:GetTournamentRanks( idx )
	local minRank = 1
	local maxRank = UI:GetMaxRank()
	local tournament = UI:GetTournament( idx )
	if tournament then
		if tournament.minRank and tournament.maxRank then
			minRank = tournament.minRank
			maxRank = tournament.maxRank
		else
			sys.log( "UI.GameplayMapCallToArms_SlotWnd:Setup()[ERROR]: Tournaments.conditions[ %d ].maxRank or Tournaments.conditions[ %d ].minRank is nil", tournamentId, tournamentId )
		end
	end
	return minRank, maxRank
end


