--
function UI:GetTourRoundTimeInfo()

	local round		= -1
	local bCurRound	= false
	local timeLeft	= 0

	local timeInfo = _G.MasterServer_GetTournamentNextRoundTime()

	if type( timeInfo ) ~= "table" then
		sys.log( "UI.TourWnd:GetTourRoundTimeInfo()[ERROR]: invalid type of return value from MasterServer_GetTournamentNextRoundTime(); \"table\" expected, got \"%s\"", type( timeInfo ) )
		return round, bCurRound, timeLeft
	end

	local curRound	= -1
	local nextRound	= -1

	if timeInfo.curRound ~= nil then
		if type( timeInfo.curRound ) == "number" then
			curRound = timeInfo.curRound
		else
			sys.log( "UI.TourWnd:GetTourRoundTimeInfo()[ERROR]: invalid type of field \"curRound\"; \"number\" or \"nil\" expected, got \"%s\"", type( timeInfo.curRound ) )
		end
	end

	if timeInfo.nextRound ~= nil then
		if type( timeInfo.nextRound ) == "number" then
			nextRound = timeInfo.nextRound
		else
			sys.log( "UI.TourWnd:GetTourRoundTimeInfo()[ERROR]: invalid type of field \"nextRound\"; \"number\" or \"nil\" expected, got \"%s\"", type( timeInfo.nextRound ) )
		end
	end

	if curRound == 0 then
		curRound = -1
	end

	if nextRound == 0 then
		nextRound = -1
	end

	if curRound ~= -1 and nextRound ~= -1 then
		sys.log( "UI.TourWnd:GetTourRoundTimeInfo()[ERROR]: both \"curRound\" and \"nextRound\" are valid" )
		curRound	= -1
		nextRound	= -1
	end

	if curRound ~= -1 then
		bCurRound = true
	end

	if curRound ~= -1 then
		round = curRound
	elseif nextRound ~= -1 then
		round = nextRound
	end

	if round ~= -1 then

		if type( timeInfo.dt ) == "number" then
			timeLeft = timeInfo.dt
		else
			sys.log( "UI.TourWnd:GetTourRoundTimeInfo()[ERROR]: invalid type of field \"dt\"; \"number\" expected, got \"%s\"", type( timeInfo.dt ) )
		end

	end

	return round, bCurRound, timeLeft

end


