--
function UI:GetClanshipVpIcoName( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetClanshipVpIcoName()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return ""
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetClanshipVpIcoName()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return ""
	end

	if type( def.hud_ico ) ~= "string" then
		sys.log( "UI:GetClanshipVpIcoName()[ERROR]: invalid type of _G.Def[\"%s\"].hud_ico; \"string\" expected, got \"%s\"", defName, type( def.hud_ico ) )
		return ""
	end

	return def.hud_ico

end


--
function UI:GetClanshipVpIcoSmall( defName )

	local hTex = UI:GetTex( "NoData" )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetClanshipVpIcoSmall()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return hTex
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetClanshipVpIcoSmall()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return hTex
	end

	if type( def.hud_ico ) ~= "string" then
		sys.log( "UI:GetClanshipVpIcoSmall()[ERROR]: invalid type of _G.Def[\"%s\"].hud_ico; \"string\" expected, got \"%s\"", defName, type( def.hud_ico ) )
		return hTex
	end

	local texName = string.format( "%s_minimap", def.hud_ico )
	hTex = UI:GetTex( texName )

	return hTex

end


