--
function UI:ShowLoadingScreen( param )

	self:HideAllWindows()

	local levelName = self:GetCurLevelName()

	if param == 2 then
		UI.LoadingScreen_sys:Show( false )

	elseif levelName == "" or levelName == "mainmenu" or levelName == "mp_lobby" then
		UI.LoadingScreen_sys:Show( false )

	elseif UI:IsValidMainMenuLevelName( levelName ) then
		UI.LoadingScreen_hangar:Show( false )

	else
		UI.LoadingScreen_game:Show( false )
	end

end


