	UI.LoadingScreen_sys:Hide( false, false )

end


--
function UI.Root:F_OnEventStartLevel( hSender, iParam0, iParam1, fParam0, fParam1 )

	local gameplay = _G.GetCurrentGameMode()

	if gameplay ~= ai.Gameplay.NONE then
		UI.debriefingData					= nil
		UI.lootItems						= nil
		UI.lastNotificationIdOnLevelStart	= UI.Notifications:GetLastNotificationIdTotal()
	end

	UI:InitDamageTypes()

	if not UI.bMapLaunched and not ( network.isMultiplayer and network.isClient ) then
		UI:ResetLaunchParams( UI.launchParams )
	end
	UI.bMapLaunched = false

	if gameplay == ai.Gameplay.FREE_SPACE then

		UI.bShowZoneEnterMsg = true
    	UI.universeRequestId = _G.MasterServer_UniverseRequest()

		if UI.universeRequestId == 0 then
    		sys.log( "UI.Root:F_OnEventStartLevel()[ERROR]: cannot request universe" )
			UI.bShowZoneEnterMsg = false
		end

	end

	if UI.bNeedSetTestDriveNextStart then
		UI.bIsTestDrive = true
		UI.bNeedSetTestDriveNextStart = false
	end

	local levelName = UI:GetCurLevelName()

	if UI:IsValidMainMenuLevelName( levelName ) then
		UI:ShowUIForMainMenuLevel()
	end

	UI.Chat:UpdateTradingTabVisibility()

	UI.scriptedDialogs_nextId = 1

	UI.scriptedQuests = {}
	UI.scriptedQuests_nextId = 1

end


--
function UI.Root:F_OnEventEndLevel( hSender, iParam0, iParam1, fParam0, fParam1 )

	UI.bShowZoneEnterMsg		= false
	UI.universeRequestId		= 0
	UI.zoneOwnerNameRequestId	= 0
	UI.bIsTestDrive				= false
	UI.hudMarkTimers			= {}
	UI.tempAutogenItems			= {}

	for srcZoneId, dstZones in pairs( UI.gatesCache ) do

		for dstZoneId, linkInfo in pairs( dstZones ) do

			if linkInfo.bTemp then

				dstZones[ dstZoneId ] = nil

				if not next( dstZones ) then
					UI.gatesCache[ srcZoneId ] = nil
				end
			end

		end

	end

	self.autoHelpTimer = -1
	UI:HideAllWindows()

end


--
function UI.Root:F_OnEventPlayerDisconnected( hSender, iParam0, iParam1, fParam0, fParam1 )

	sys.out("^5F_OnEventPlayerDisconnected %d", iParam1 )

	if UI:HasReactinWindowsOnEvent( UI.EV_PLAYER_DISCONNECTED ) then
		return
	end

	local reason = iParam1

	-- при дисконнекте от мастер-сервера сначала придет этот евент, а потом евент о дисконнекте от мастер-сервера;
	-- поэтому, во избежание показа двойного месседжбокса и прочих накладок, текущий евент игрорирую, а обрабатываю только дисконнект от мастер-сервера

	if reason == network.DisconnectReason.MASTER_SERVER_CONNECTION_FAILED then
		return
	end

	if reason == network.DisconnectReason.CLIENT_QUIT then
		return
	end

	-- "переход" с одного сервера на другой. игнорируем
	if network.DisconnectReason.CLIENT_SERVER_TRANSFER ~= nil and reason == network.DisconnectReason.CLIENT_SERVER_TRANSFER then
		return
	end

	-- при DR_CLIENT_DOCK_SPACE_STATION и CLIENT_RETURN_SPACE_STATION не нужно показывать MsgBox об ошибке, но нужно загружать mainmenu
	if 	reason == network.DisconnectReason.CLIENT_DOCK_SPACE_STATION or
		reason == network.DisconnectReason.CLIENT_RETURN_SPACE_STATION or
		reason == network.DisconnectReason.CLIENT_FREE_SPACE_SAVE
	then
		reason = -1
	end

	UI.playerDisconnectReason = reason
	UI:LoadMainMenuLevel()

end


--
function UI:IsReconnectEnable( disconnectReason )

	local bReconnectEnable = false

	if disconnectReason ~= _G.network.MasterServerDisconnectReason.DR_CLIENT_QUIT then

        if disconnectReason == _G.network.MasterServerDisconnectReason.DR_NETWORK_FAIL or disconnectReason == _G.network.MasterServerDisconnectReason.DR_NO_REASON or disconnectReason == _G.network.MasterServerDisconnectReason.DR_NETWORK_FAIL_OS then
			local bInBattle = not _G.IsValidMainMenuLevel( UI:GetCurLevelName() )

        	if bInBattle then
        		bReconnectEnable = true
        	end
        end

	end

	return bReconnectEnable

end


