function UI:ChatWisperByUid( uid )

	if type( uid ) ~= "userdata" then
		sys.log( "UI:ChatWisperByUid()[ERROR]: invalid type of the 1-st parameter (\"uid\"); \"userdata\" expected, got \"%s\"", type( uid ) )
		return
	end

	if uid == UI.INVALID_U64_ID then
		sys.log( "UI:ChatWisperByUid()[ERROR]: invalid uid" )
		return
	end

	if UI.ChatWnd and UI.ChatWnd:IsOnScreen() then
		if UI:CanChatInput( true ) then
			local nickName, bCached, requestId = _G.MasterServer_GetNickName( uid )
			if bCached then
				UI.ChatWnd:SetTextAndEdit( string.format( "/w %s ", nickName ) )
			else
				UI.ChatWnd:SetTextAndEdit( string.format( "/w #%s ", _G.U64ToStr( uid ) ) )
			end
		end
	end

end


--
function UI:FillContextMenuForClan( menuType, cid, data )

	if not UI.Clan:IsInClan() then
		if bit.band( menuType, UI.ContextMenuType.CLAN ) == UI.ContextMenuType.CLAN then
			local requested = false
			if data and UI:IsTrueEx( data.joinReqSent ) then
				requested = true
			end
			if requested then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REJECT_REQUEST_TO_CLAN, cid = cid } )
			else
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REQUEST_TO_CLAN, cid = cid } )
			end
		end
	end

end


--
function UI:IsPlayerCanBeTeacher()

	return UI:Reputation2Rank( UI:GetPlayerMaxReputationForRace() ) >= TeacherMinRank and UI.Profile:HasEnoughtFightToBeATeacher()

end


--
function UI:IsPlayerCanBeStudent()

	return UI:Reputation2Rank( UI:GetPlayerMaxReputationForRace() ) < StudentMaxRank

end


--
function UI:FillContextMenuForPlayer( menuType, uid, data, isBot )

	if isBot == nil then
		isBot = false
	end

	local isLocalInClan			= UI.Clan:IsInClan()
	local isLocalInLobby		= UI.Lobby:IsInLobby()
	local isLocalInArrena		= UI.Arena:IsInTeam()
	local localUserId			= _G.MasterServer_GetLocalUserId()

	local isUidFriend			= not isBot and UI.Social:IsFriend( uid )
	local isUidWatch			= not isBot and UI.Social:IsWatch( uid )
	local isUidIgnore			= not isBot and UI.Social:IsIgnore( uid )
	local isUidNew				= not isBot and UI.Social:IsNew( uid )
	local isUidFriendRequest	= not isBot and UI.Social:IsFrendRequest( uid )
	local isUidInSquad			= not isBot and UI.Squad:InSquad( uid )
	local isUidTeacher			= not isBot and UI.Social:IsTeacher( uid )
	local isUidStudent			= not isBot and UI.Social:IsStudent( uid )
	local isUidInClan			= not isBot and UI.Clan:IsClanMember( uid )
	local isUidInLobby			= not isBot and UI.Lobby:IsPlayerInLobby( uid )
	local isUidInArena			= not isBot and isLocalInArrena and UI.Arena:IsPlayerMember( uid )
	local isUidArenaInvited		= not isBot and isLocalInArrena and UI.Arena:IsPlayerInvited( uid )

	if bit.band( menuType, UI.ContextMenuType.PLAYER_USER_NOTE ) == UI.ContextMenuType.PLAYER_USER_NOTE then
		if uid ~= localUserId then
			if isUidFriend or isUidWatch or isUidIgnore or isUidFriendRequest or isUidTeacher or isUidStudent then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.USER_NOTE_ADD, uid = uid, isBot = isBot } )
			end
		end
	end

	if bit.band( menuType, UI.ContextMenuType.PLAYER_COMMON ) == UI.ContextMenuType.PLAYER_COMMON then
		if uid ~= localUserId then
			UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.WHISPER, uid = uid, isBot = isBot } )
		end

		if uid ~= UI.INVALID_U64_ID and uid ~= localUserId and UI.HangarWnd:IsOnScreen() then
			UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.SEND_MAIL, uid = uid, isBot = isBot } )
		end


		if not isUidFriend and not isUidWatch and not isUidIgnore and not isUidFriendRequest and not isUidNew and uid ~= localUserId  then
			UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REQUEST_TO_FRIENDSHIP, uid = uid, isBot = isBot } )
			UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ADD_TO_WATCH, uid = uid, isBot = isBot } )
			UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ADD_TO_IGNORE, uid = uid, isBot = isBot } )
		else
			if isUidFriend then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ADD_TO_IGNORE, uid = uid, isBot = isBot } )
				if isUidTeacher then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.STOP_BE_STUDENT, uid = uid, isBot = isBot } )
				elseif isUidStudent then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.STOP_BE_TEACHER, uid = uid, isBot = isBot } )
				else
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REMOVE_FROM_FRIEND, uid = uid, isBot = isBot } )
				 end
			elseif isUidWatch then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REMOVE_FROM_WATCH, uid = uid, isBot = isBot } )
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REQUEST_TO_FRIENDSHIP, uid = uid, isBot = isBot } )
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ADD_TO_IGNORE, uid = uid, isBot = isBot } )
			elseif isUidIgnore then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REMOVE_FROM_IGNORE, uid = uid, isBot = isBot } )
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ADD_TO_WATCH, uid = uid, isBot = isBot } )
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REQUEST_TO_FRIENDSHIP, uid = uid, isBot = isBot } )
			elseif isUidFriendRequest then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REMOVE_FROM_FRIEND_REQUEST, uid = uid, isBot = isBot } )
			end
		end


		if UI.HangarWnd:IsOnScreen() or ( UI.HudWnd and UI.HudWnd:IsOnScreen() and _G.GetCurrentGameMode() == ai.Gameplay.FREE_SPACE ) then
			if ( UI.Squad:GetLeaderUid() == localUserId and not isUidInSquad ) or not UI.Squad:IsInSquad() and uid ~= localUserId and not isLocalInLobby then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ADD_TO_SQUAD, uid = uid, isBot = isBot } )
			end
		end

		if uid ~= localUserId then
			if UI:IsPlayerCanBeStudent() then
				if not isUidTeacher then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REQUEST_TO_TEACHER, uid = uid, isBot = isBot } )
				end
			end
			if UI:IsPlayerCanBeTeacher() then
				if not isUidStudent then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.REQUEST_TO_STUDENT, uid = uid, isBot = isBot } )
				end
			end
		end

		if UI.HangarWnd:IsOnScreen() then
			if isLocalInClan and localUserId ~= uid then
				if not isUidInClan then
					local actions = _G.MasterServer_ClanGetActionPrivileges( localUserId )
					for i = 1, #actions do
						if actions[ i ] == MasterServer.ClanActionPrivileges.CAP_INVITE then
							UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.INVITE_TO_CLAN, uid = uid, isBot = isBot } )
						end
					end
				end
			end

			if uid ~= localUserId and isLocalInLobby and UI.Lobby:IsLobbyLeader() then
				if not isUidInLobby then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.INVITE_TO_LOBBY, uid = uid, isBot = isBot } )
				end
			end

			--[[ SC-112055
			if UI.Arena:IsInTeam() and UI.Arena:IsLeader() and uid ~= localUserId and not isUidInArena and not isUidArenaInvited then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ARENA_INVITE_PLAYER, uid = uid, isBot = isBot } )
			end]]

		end

	end

	if UI.HangarWnd:IsOnScreen() or ( UI.HudWnd and UI.HudWnd:IsOnScreen() and _G.GetCurrentGameMode() == ai.Gameplay.FREE_SPACE ) then
		if bit.band( menuType, UI.ContextMenuType.PLAYER_SQUAD ) == UI.ContextMenuType.PLAYER_SQUAD then
			if UI.Squad:GetLeaderUid() == localUserId and isUidInSquad and uid ~= localUserId then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.EXCLUDE_FROM_SQUAD, uid = uid, isBot = isBot } )
			end

			if isUidInSquad and uid == localUserId then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.LEAVE_SQUAD, uid = uid } )
			end
		end
	end

	if UI.HangarWnd:IsOnScreen() then
		if bit.band( menuType, UI.ContextMenuType.LOBBY ) == UI.ContextMenuType.LOBBY then
			if UI.Lobby:IsInLobby() and UI.Lobby:IsLobbyLeader() and UI.Lobby:CanChangeTeam() and uid ~= localUserId then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.EXCLUDE_FROM_LOBBY, uid = uid, isBot = isBot } )
			end

			if UI.Lobby:IsInLobby() and uid == localUserId then
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.LEAVE_LOBBY, uid = uid } )
			end
		end
	end

	if UI.HangarWnd:IsOnScreen() then
		if bit.band( menuType, UI.ContextMenuType.PLAYER_CLAN ) == UI.ContextMenuType.PLAYER_CLAN then
			if isLocalInClan then
				local actions = _G.MasterServer_ClanGetActionPrivileges( localUserId )
				if localUserId ~= uid and isUidInClan then
					local subordinateRoles = _G.MasterServer_ClanGetSubordinateRoles( localUserId )
					local playerRole = UI.Clan:GetClanMemberRole( uid )
					for i = 1, #actions do
						if actions[ i ] == MasterServer.ClanActionPrivileges.CAP_SET_ROLE and isUidInClan then
							local include = false
							for j = 1, #subordinateRoles do
								if subordinateRoles[ j ] == playerRole then
									include = true
									break
								end
							end
							if include then
								for j = 1, #subordinateRoles do
									if subordinateRoles[ j ] ~= playerRole then
										UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.CHANGE_PRIVILEGES, uid = uid, param = UI:Val2Key( MasterServer.ClanRole, subordinateRoles[ j ] ), isBot = isBot } )
									end
								end
							end
						end
						--[[if actions[ i ] == MasterServer.ClanActionPrivileges.CAP_INVITE and not isUidInClan then
							UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.INVITE_TO_CLAN, uid = uid } )
						end]]
						if actions[ i ] == MasterServer.ClanActionPrivileges.CAP_KICK and isUidInClan then
							for j = 1, #subordinateRoles do
								if subordinateRoles[ j ] == playerRole then
									UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.KICK_FROM_CLAN, uid = uid, isBot = isBot } )
									break
								end
							end
						end
					end
				end

				if uid == localUserId then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.LEAVE_CLAN, uid = uid } )
				end

				--[[if uid == _G.MasterServer_GetLocalUserId() then
					if not UI.Clan:IsLeader( _G.MasterServer_GetLocalUserId() ) then
						UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.LEAVE_CLAN, uid = uid } )
					else
						if UI.Clan:GetMembersCount() == 1 then
							UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.LEAVE_CLAN, uid = uid } )
						end
					end
				end]]
			end
		end
	end

	if UI.HangarWnd:IsOnScreen() or ( UI.DebriefingWnd and UI.DebriefingWnd:IsOnScreen() ) then
		if bit.band( menuType, UI.ContextMenuType.PLAYER_COMMON ) == UI.ContextMenuType.PLAYER_COMMON then
			UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.SHOW_PROFILE, uid = uid } )
		end

		if not UI.DebriefingWnd or not UI.DebriefingWnd:IsOnScreen() then
			if bit.band( menuType, UI.ContextMenuType.PLAYER_RENAME) == UI.ContextMenuType.PLAYER_RENAME then
				if uid == _G.MasterServer_GetLocalUserId() then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.PLAYER_RENAME, uid = uid } )
				end
			end
		end
	end

	--if UI.HangarWnd:IsOnScreen() then
	if bit.band( menuType, UI.ContextMenuType.COMPLAINT_CHAT ) == UI.ContextMenuType.COMPLAINT_CHAT then
		if uid ~= _G.MasterServer_GetLocalUserId() then
			if not data then
				sys.log( "UI:FillContextMenuForPlayer()[ERROR]: menuType & UI.ContextMenuType.PLAYER_RENAME is true, but data is nil" )
				return
			end
			if not data.fromName or not data.toName or not data.tabId then
				sys.log( "UI:FillContextMenuForPlayer()[ERROR]: menuType & UI.ContextMenuType.PLAYER_RENAME is true, but some of data is nil" )
				return
			end
			if	_G.MasterServer_CheckAccessPrivilege( MasterServer.Privilege.PRIV_MUTE )
				or _G.MasterServer_CheckAccessPrivilege( MasterServer.Privilege.PRIV_BAN )
				or _G.MasterServer_CheckAccessPrivilege( MasterServer.Privilege.PRIV_MUTE_PERMANENT )
				or _G.MasterServer_CheckAccessPrivilege( MasterServer.Privilege.PRIV_BAN_PERMANENT ) then
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.COMPLAINT_CHAT, uid = uid, additionalData = data, isBot = isBot } )
					UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.PUNISHMENT_CHAT, uid = uid, additionalData = data, isBot = isBot } )
			else
				UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.COMPLAINT_CHAT, uid = uid, additionalData = data, isBot = isBot } )
			end
		end
	end
	--end


	if UI.HangarWnd:IsOnScreen() then

		if bit.band( menuType, UI.ContextMenuType.PLAYER_ARENA ) == UI.ContextMenuType.PLAYER_ARENA then

			if UI.Arena:IsInTeam() then

				-- TODO: можно ли, когда корабли в бою?
				if UI.Arena:IsLeader() then

					if uid == localUserId then
						UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ARENA_DISBAND_TEAM } )

					elseif isUidInArena then
						UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ARENA_KICK_PLAYER, uid = uid, isBot = isBot } )
					end

				else

					if uid == localUserId then
						UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.ARENA_LEAVE } )
					end

				end

			end

		end

	end

	if bit.band( menuType, UI.ContextMenuType.PLAYER_TRADING ) == UI.ContextMenuType.PLAYER_TRADING then

		if uid ~= UI:GetLocalPlayerUid() and UI.HangarWnd:IsOnScreen() then
			UI.ContextMenu:AddRecord( { action = UI.ContextMenu_SlotWnd.actions.TRADING, uid = uid, isBot = isBot } )
		end

	end

end


--
function UI:SortPlayersListByNickname( records, up )

	local function CompareByNicknameUp( info1, info2 )
		return string.upper( info1.nickname ) < string.upper( info2.nickname )
	end

	local function CompareByNicknameDown( info1, info2 )
		return string.upper( info1.nickname ) > string.upper( info2.nickname )
	end

	if up then
		table.sort( records, CompareByNicknameUp )
		return
	else
		table.sort( records, CompareByNicknameDown )
		return
	end

end


--
function UI:SortPlayersListByStatus( records, up )

	local function GetSortPos( record )
		local text = UI:Val2Key( MasterServer.UserState, record.state )

		if not text then
			sys.log( "UI:SortPlayersListByStatus()[ERROR]: Can't find status by index: %d", record.state )
		end
		for i = 1, #PlayerStatusSortOrder do
			if type( PlayerStatusSortOrder[ i ] ) == "table" then
				if record.state >= MasterServer.UserState[ PlayerStatusSortOrder[ i ][ 1 ] ] and record.state < MasterServer.UserState[ PlayerStatusSortOrder[ i ][ 2 ] ] then
					return i
				end
			else
				if text == PlayerStatusSortOrder[ i ] then
					return i
				end
			end
		end
		sys.log( "UI:SortPlayersListByStatus()[ERROR]: can't find status %d in sort order", record.state )
		return #PlayerStatusSortOrder + 1
	end

	local function CompareByStateUp( info1, info2 )
		if info1.recruit or info2.recruit then
			if info1.recruit and info2.recruit then
				return string.upper( info1.nickname ) < string.upper( info2.nickname )
			else
				return info1.recruit and info1.recruit or false
			end
		end
		local sortPos1 = GetSortPos( info1 )
		local sortPos2 = GetSortPos( info2 )
		if sortPos1 == sortPos2 then
			if info1.state == MasterServer.UserState.USER_STATE_OFFLINE then
				if info1.stateLastChange == nil then return true end
				if info2.stateLastChange == nil then return false end
				return UI:DateTime2Time( info1.stateLastChange ) > UI:DateTime2Time( info2.stateLastChange )
			end
			return string.upper( info1.nickname ) < string.upper( info2.nickname )
		else
			return sortPos1 < sortPos2
		end
	end

	local function CompareByStateDown( info1, info2 )
		if info1.recruit or info2.recruit then
			if info1.recruit and info2.recruit then
				return string.upper( info1.nickname ) < string.upper( info2.nickname )
			else
				return info2.recruit and info2.recruit or false
			end
		end
		local sortPos1 = GetSortPos( info1 )
		local sortPos2 = GetSortPos( info2 )
		if sortPos1 == sortPos2 then
			if info1.state == MasterServer.UserState.USER_STATE_OFFLINE then
				if info1.stateLastChange == nil then return false end
				if info2.stateLastChange == nil then return true end
				return UI:DateTime2Time( info1.stateLastChange ) < UI:DateTime2Time( info2.stateLastChange )
			end
		else
			return sortPos1 > sortPos2
		end
	end

	if up then
		table.sort( records, CompareByStateUp )
		return
	else
		table.sort( records, CompareByStateDown )
		return
	end

end


--
function UI:SortPlayersListByMilitaryRank( records, up )

	local function CompareByMilitaryRankUp( info1, info2 )

		if info1.militaryRank ~= info2.militaryRank then
			return info1.militaryRank < info2.militaryRank
		end

		-- во вторую очередь - по имени в прямом алфавитном порядке
		return string.upper( info1.nickname ) < string.upper( info2.nickname )

	end

	local function CompareByMilitaryRankDown( info1, info2 )

		if info1.militaryRank ~= info2.militaryRank then
			return info1.militaryRank > info2.militaryRank
		end

		-- во вторую очередь - по имени в прямом алфавитном порядке
		return string.upper( info1.nickname ) < string.upper( info2.nickname )

	end

	if up then
		table.sort( records, CompareByMilitaryRankUp )
		return
	else
		table.sort( records, CompareByMilitaryRankDown )
		return
	end

end


--
function UI:GetPlayerStatusFullStr( record, bOffTime )

	if bOffTime == nil then
		bOffTime = true
	end

	for k, v in pairs( MasterServer.UserState ) do
		if v == record.state then
			if MasterServer.UserState.USER_STATE_OFFLINE == v and record.stateLastChange and bOffTime then
				local time = _G.GetU64Time()
				local dif = ( ( time.l - record.stateLastChange.l ) + ( time.h - record.stateLastChange.h ) * ( 2 ^ 32 ) ) / 1000
				if dif < 60 then
					return UI:GetStringByName( "friends_status_les_1_min" )
				else
					if dif > 60 * 60 * 24 then
						dif = dif / 60 / 60
						dif = math.floor( dif )
						dif = dif * 60 * 60
					else
						dif = dif / 60
						dif = math.floor( dif )
						dif = dif * 60
					end
					return string.format( UI:GetStringByName( "friends_status_wide_offline" ), UI:Time2Str44( dif ) )
				end
			else
				return UI:GetStringByName( k )
			end
		end
	end
end


--
function UI:FormatMottoText( playerName, mottoText )

	return playerName..":|"..mottoText

end


--
function UI:GetMottoTextByUid( uid, mottoText )

	local playerName = self:MakePlayerNameByUid( uid, true, false, false )
	return UI:FormatMottoText( playerName, mottoText )

end


--
function UI:IsMottoCustom( motto )

	local isCustom = false

	if not motto then

		sys.log( "UI:IsMottoCustom()[ERROR]: motto is nil" )

	else

		if motto == "" then

		else

			local def = UI:GetDef( motto )
			if def ~= nil then
				if UI:IsDefMotto( motto ) then
					isCustom = def.stringPrefix ~= nil
				else
					sys.log( "UI:IsMottoCustom()[ERROR]: def '%s' is not motto", motto )
				end
			else
				sys.log( "UI:IsMottoCustom()[ERROR]: can't find motto with def '%s'", motto )
			end

		end

	end

	return isCustom

end


--
function UI:GetMottoStringName( motto )

	local stringName = nil

	if not motto then

		sys.log( "UI:GetMottoStringName()[ERROR]: motto is nil" )

	else

		if motto == "" then

		else

			local def = UI:GetDef( motto )
			if def ~= nil then
				if UI:IsDefMotto( motto ) then
					if def.stringId then
						stringName = def.stringId
					elseif def.stringPrefix then
						if def.depends_on_uid then
							stringName = def.stringPrefix.._G.U64ToStr( _G.MasterServer_GetLocalUserId() )
						else
							sys.log( "UI:GetMottoStringName()[ERROR]: unknown depend param for motto '%s'", motto )
						end
					else
						sys.log( "UI:GetMottoStringName()[ERROR]: can't resolve motto '%s' to the string name", motto )
					end
				else
					sys.log( "UI:GetMottoStringName()[ERROR]: def '%s' is not motto", motto )
				end
			else
				sys.log( "UI:GetMottoStringName()[ERROR]: can't find motto with def '%s'", motto )
			end

		end

	end

	return stringName

end


--
function UI:IsCustomMottoExist( motto )

	if not UI:IsMottoCustom( motto ) then
		sys.log( "UI:IsCustomMottoExist()[ERROR]: def '%s' is not custom motto", motto )
	else
		local stringName = self:GetMottoStringName( motto )
--[[ #0031105 cosmosim
		local hTex = UI:GetResourceHandleByName( stringName, UI.RES_STRING, true )
		if hTex ~= UI.INVALID_RESOURCE_HANDLE then
			return true
		end
]]
		-- #0031105 cosmosim
		do
			return UI:GetStringByName( stringName, false ) ~= nil
		end
	end

	return false

end


--
function UI:GetMottoString( motto )

	local stringId = self:GetMottoStringName( motto )
	if stringId then
		return UI:GetStringByName( stringId )
	else
		sys.log( "UI:GetMottoString()[ERROR]: self:GetMottoStringName( '%s' ) return nil", tostring( motto ) )
		return ""
	end

end


