--
function UI:GetAvatarDesc( avatar )

	local desc = ""

	if not avatar then

		sys.log( "UI:GetAvatarDesc()[ERROR]: avatar is nil" )

	else

		if avatar == "" then

			desc = UI:GetStringByName( "avatar_Default_desc" )

		else

			local def = UI:GetDef( avatar )
			if def ~= nil then
				if UI:IsDefAvatar( avatar ) then
					desc = UI:GetStringByName( "avatar_"..avatar.."_desc" )
				else
					sys.log( "UI:GetAvatarDesc()[ERROR]: def '%s' is not avatar", avatar )
				end
			else
				sys.log( "UI:GetAvatarDesc()[ERROR]: can't find avatar with def '%s'", avatar )
			end

		end

	end

	return desc

end


