--
function UI:GetAvatarTextureName( avatar )

	local textureName = "avatar_default"

	if not avatar then

		sys.log( "UI:GetAvatarTextureName()[ERROR]: avatar is nil" )

	else

		if avatar == "" then

		else

			local def = UI:GetDef( avatar )
			if def ~= nil then
				if UI:IsDefAvatar( avatar ) then
					if def.textureId then
						textureName = def.textureId
					elseif def.texturePrefix then
						if def.depends_on_uid then
							textureName = def.texturePrefix.._G.U64ToStr( _G.MasterServer_GetLocalUserId() )
						else
							sys.log( "UI:GetAvatarTextureName()[ERROR]: unknown depend param for avatar '%s'", avatar )
						end
					else
						sys.log( "UI:GetAvatarTextureName()[ERROR]: can't resolve avatar '%s' to the texture name", avatar )
					end
				else
					sys.log( "UI:GetAvatarTextureName()[ERROR]: def '%s' is not avatar", avatar )
				end
			else
				sys.log( "UI:GetAvatarTextureName()[ERROR]: can't find avatar with def '%s'", avatar )
			end

		end

	end

	return textureName

end


--
function UI:IsCustomAvatarExist( avatar )

	if not UI:IsAvatarCustom( avatar ) then
		sys.log( "UI:IsCustomAvatarExist()[ERROR]: def '%s' is not custom avatar", avatar )
	else
		local textureName = self:GetAvatarTextureName( avatar )
		local hTex = UI:GetResourceHandleByName( textureName, UI.RES_TEXTURE, true )
		if hTex ~= UI.INVALID_RESOURCE_HANDLE then
			return true
		end
	end

	return false

end


