function UI:GetAvatarTexture( avatar )

	return UI:GetTex( self:GetAvatarTextureName( avatar ) )

end



--
function UI:LocalizeSquadNotification( type, uid, errorCode, forChat, formatForMyself, params )

	if forChat == nil then
		forChat = false
	end

	local text = ""

	local stingIdPostfix = ""

	if formatForMyself then
		stingIdPostfix = "_my"
	end

	if type == MasterServer.SquadNotification.SQN_MM_JOIN_FAILURE_SQUAD_MEMBER_HAS_ISSUES then

		text = UI:GetStringByName( "SQN_MM_JOIN_FAILURE_SQUAD_MEMBER_HAS_ISSUES"..stingIdPostfix )

		local colorStr = UI:Color2Str( UI.ChatWnd:GetColorByColorType( UI.Chat.colorIds.SYSTEM ) )
		if not forChat then
			text = string.gsub( text, "%$name%$", colorStr..UI:MakePlayerNameByUid( uid, false, false ).."@ffffffff" )
		else
			text = string.gsub( text, "%$name%$", UI:MakePlayerNameByUid( uid, false, false ) )
		end

		local errorString = ""
		local errorStringId = "mmError_"..UI:Val2Key( MasterServer.MMJoinResult, errorCode )

		-- #0108919
		if forChat then
			errorStringId = string.format( "%s_chat", errorStringId )
			errorString = UI:GetStringByName( errorStringId, false ) or ""
		end

		if errorString == "" then
			errorString = UI:GetStringByName( errorStringId, true )
		end

		text = string.gsub( text, "%$reason%$", errorString )

		if errorCode == MasterServer.MMJoinResult.MMJR_VESSEL_RANK_ALL or errorCode == MasterServer.MMJoinResult.MMJR_VESSEL_RANK_ANY then
			text = string.gsub( text, "%$min_rank%$", params.minRank )
			text = string.gsub( text, "%$max_rank%$", params.maxRank )

		elseif errorCode == MasterServer.MMJoinResult.MMJR_SQUAD_RANK_DIFF then
			text = string.gsub( text, "%$min_rank%$", params.minHighestSquadRank )
			text = string.gsub( text, "%$max_rank%$", params.maxHighestSquadRank )

		elseif errorCode == MasterServer.MMJoinResult.MMJR_INVALID_ACCOUNT_RANK then
			text = string.gsub( text, "%$rank%$", params.accountRank )

		elseif errorCode == MasterServer.MMJoinResult.MMJR_LEAGUE_FORBIDDEN_EQUIPMENT then

			local badEquipment = UI:CopyTable2( params.badLeagueEquipment or {} )
			text = UI:FormatLeagueForbiddenEquipmetnMsg( text, badEquipment, forChat )

		elseif errorCode == MasterServer.MMJoinResult.MMJR_BANNED_FOR_LEAVE then

			local curTime = _G.MasterServer_GetServerTime()
			local timeLeft = 0
			if params.leaverBanTill > curTime then
				timeLeft = ( ( params.leaverBanTill - curTime ) * 0.001 ).l
			end

			local strTime = UI:Time2Str45( timeLeft )
			local baseColor = UI.TEXT_BASE_COLOR
			local YELLOW_COLOR	= 0xffffff00
			strTime = string.format( "%s%s%s", UI:Color2Str( YELLOW_COLOR ), strTime, UI:Color2Str( baseColor ) )
			text = string.gsub( text, "%$time_left%$", strTime )

		end

	elseif type == MasterServer.SquadNotification.SQN_MM_JOIN_FAILURE_PREMIUM_REQUIRED then

		text = UI:GetStringByName( "SQN_MM_JOIN_FAILURE_PREMIUM_REQUIRED"..stingIdPostfix )

	else

		text = UI:GetStringByName( UI:Val2Key( MasterServer.SquadNotification, type )..stingIdPostfix )
		local colorStr = UI:Color2Str( UI.ChatWnd:GetColorByColorType( UI.Chat.colorIds.SYSTEM ) )
		if not forChat then
			text = string.gsub( text, "%$name%$", colorStr..UI:MakePlayerNameByUid( uid, false, false ).."@ffffffff" )
		else
			text = string.gsub( text, "%$name%$", UI:MakePlayerNameByUid( uid, false, false ) )
		end

	end

	return text

end


