--
function UI:DamageFlags2DamageType( damageFlags )

	local damageType	= -1
	local bCrit			= false

	for idx, val in ipairs( self.damageTypes ) do

		if bit.band( damageFlags, val ) ~= 0 then

			if val ~= ai.DamageType.CRITICAL then

    			if damageType == -1 then
    				damageType = val
    			else
    				damageType = ai.DamageType.GENERIC	-- если установлено сразу несколько типов дамеджа, то считается, что generic
    			end

			else
				bCrit = true
			end

		end

	end

	if damageType == -1 then
		damageType = ai.DamageType.GENERIC
	end

	return damageType, bCrit

end


--
function UI:InitDamageTypes()

	if self.damageTypes[ 1 ] then
		return
	end

	for damageTypeName, damageType in pairs( ai.DamageType ) do
		table.insert( self.damageTypes, damageType )
	end

end


--
function UI:CheckShowZoneEnterMsg()

	if not self.bShowZoneEnterMsg then
		return
	end

	if _G.GetCurrentGameMode() ~= ai.Gameplay.FREE_SPACE then

		sys.log( "UI:CheckShowZoneEnterMsg()[ERROR]: wrong game mode" )
		self.bShowZoneEnterMsg = false

		return

	end

	if UI.universeRequestId ~= 0 then
		return
	end

	if not UI.ChatWnd:IsOnScreen() then
		return
	end

	local zoneId = _G.CL_GetCurrentSpaceZoneId()
	local ownerCid = UI:GetUniverseZoneOwner( zoneId )

	if ownerCid ~= UI.INVALID_U64_ID then

		local clanName, bCached, requestId, clanTag, emblem = _G.MasterServer_GetClanName( ownerCid )
		if not bCached then

			self.zoneOwnerNameRequestId = requestId

			if self.zoneOwnerNameRequestId == 0 then

				sys.log( "UI:CheckShowZoneEnterMsg()[ERROR]: fail to request clan name" )
				self.bShowZoneEnterMsg = false

			end

			return

		end

	end

	UI:ShowZoneEnterMsg()
	self.bShowZoneEnterMsg = false

end


--
function UI:ShowZoneEnterMsg()

	local currentZoneId = _G.CL_GetCurrentSpaceZoneId()
	local levelName = UI:GetLevelLocalizedName( SpaceZoneById[ currentZoneId ].level_name )

	local ownerCid = UI:GetUniverseZoneOwner( currentZoneId )
	local str = ownerCid == UI.INVALID_U64_ID and UI:GetStringByName( "freespace_entrance_to_location" ) or UI:GetStringByName( "freespace_entrance_to_location_hasOwner" )
	str = string.gsub( str, "%$level_name%$", levelName )

	local zoneName = UI:ZoneId2Name( currentZoneId )
	local difficulty = UI:GetZoneDifficulty( zoneName )
	local strDifficultyVal = UI:ZoneDifficulty2Str( difficulty )

	-- в локализованную строку зашит цвет, а в чате внутритекстовый цвет не умеет отображаться
	strDifficultyVal = string.gsub( strDifficultyVal, "@%x%x%x%x%x%x%x%x", "" )

	local numSubst = 0
	str, numSubst = string.gsub( str, "%$difficulty%$", strDifficultyVal )

	if numSubst == 0 then
		sys.log( "UI:ShowZoneEnterMsg()[ERROR]: cannont find placeholder \"$difficulty$\" in string \"freespace_entrance_to_location\"" )
		local strDifficulty = string.format( "[INVALID STRING] Zone difficulty: %s", strDifficultyVal )
		str = string.format( "%s %s", str, strDifficulty )
	end

	if ownerCid ~= UI.INVALID_U64_ID then
		local clanName, bCached, requestId, clanTag, emblem = _G.MasterServer_GetClanName( ownerCid )
		str = string.gsub( str, "%$owner%$", clanName )
	end

	UI.Chat:AddSystemMessage( str )

end


--
function UI:GetNearestGateToZone( srcZoneId, dstZoneId )

	if type( srcZoneId ) ~= "number" then
		sys.log( "UI:GetNearestGateToZone()[ERROR]: invalid type of the 1-st param (\"srcZoneId\" ); \"number\" expected, got \"%s\"", type( srcZoneId ) )
		return -1, 0
	end

	if type( dstZoneId ) ~= "number" then
		sys.log( "UI:GetNearestGateToZone()[ERROR]: invalid type of the 2-nd param (\"dstZoneId\" ); \"number\" expected, got \"%s\"", type( dstZoneId ) )
		return -1, 0
	end

	if srcZoneId == -1 or dstZoneId == -1 then
		sys.log( "UI:GetNearestGateToZone()[ERROR]: invalid zone id(s)" )
		return -1, 0
	end

	if srcZoneId == dstZoneId then
		sys.log( "UI:GetNearestGateToZone()[ERROR]: the same zone" )
		return -1, 0
	end


	local chachedGateInfo = self.gatesCache[ srcZoneId ] and self.gatesCache[ srcZoneId ][ dstZoneId ]
	if chachedGateInfo then
		return chachedGateInfo.gateId, chachedGateInfo.pathLength
	end


	local visitedZones		= {}
	local curZoneId			= _G.GetCurrentGameMode() ~= 0 and UI:GetCurZone() or -1
	local curZoneTempLinks	= nil

	local fnRecurse = nil	-- есть необходимость в предварительном объявлении, иначе вызов внутри функции не находит ее
	fnRecurse = function( curSrcZoneId, curPathLength )

		curPathLength = curPathLength + 1

		if not visitedZones[ curSrcZoneId ] or visitedZones[ curSrcZoneId ] > curPathLength then
			visitedZones[ curSrcZoneId ] = curPathLength
		else
			return -1, -1
		end

		if curSrcZoneId == dstZoneId then
			return curPathLength, -1
		end

		local linkedZones = nil

		local zoneInfo = _G.SpaceZoneById[ curSrcZoneId ]
		if type( zoneInfo ) == "table" then

			if zoneInfo.link_zones ~= nil then
				if type( zoneInfo.link_zones ) == "table" then
					linkedZones = zoneInfo.link_zones
				else
					sys.log( "UI:GetNearestGateToZone()[ERROR]: invalid type of \"_G.SpaceZoneById[%d].link_zones\", \"table\" or \"nil\" expected, got \"%s\"", curSrcZoneId, type( _G.SpaceZoneById[ curSrcZoneId ].link_zones ) )
				end
			end

		else
			sys.log( "UI:GetNearestGateToZone()[ERROR]: invalid type of \"_G.SpaceZoneById[%d]\", \"table\" expected, got \"%s\"", curSrcZoneId, type( _G.SpaceZoneById[ curSrcZoneId ] ) )
		end


		-- есть зоны, для которых связи не прописаны в дефе (локации чужих);
		-- когда игрок находится в такой зоне, должны заспауниться врата в ту зону, из которой он прилетел

		if ( not linkedZones or not next( linkedZones ) ) and curSrcZoneId == curZoneId then

			if not curZoneTempLinks then

				local gateEnts = _G.GetEntitiesByClass( "JumpDockLocation" )
    			for gateEntIdx, gateEntId in pairs( gateEnts ) do

    				local gateEnt = _G.Entities[ gateEntId ]
    				if gateEnt and not gateEnt:IsDockLocation() then

                 		local linkedZoneId = gateEnt:GetTargetZoneReal()

    					if not curZoneTempLinks then
    						curZoneTempLinks = {}
    					end

    					table.insert( curZoneTempLinks, linkedZoneId )

    				end

    			end

			end

			if curZoneTempLinks then
				linkedZones = curZoneTempLinks
			end

		end

		if linkedZones then

			local minPathLength = math.huge
			local minZoneId = -1

			for idx, linkedZoneId in ipairs( linkedZones ) do

				local pathLength, gateId = fnRecurse( linkedZoneId, curPathLength )

				if pathLength ~= -1 then

					if gateId == -1 then
						return pathLength, linkedZoneId
					else
						if pathLength < minPathLength then
							minPathLength = pathLength
							minZoneId = linkedZoneId
						end
					end

				end

			end

			if minZoneId ~= -1 then
				return minPathLength, minZoneId
			end

		end

		return -1, -1

	end

	local pathLength, gateId = fnRecurse( srcZoneId, 0 )

	if not self.gatesCache[ srcZoneId ] then
		self.gatesCache[ srcZoneId ] = {}
	end
	self.gatesCache[ srcZoneId ][ dstZoneId ] = { gateId = gateId, pathLength = pathLength, bTemp = curZoneTempLinks ~= nil }

	return gateId, pathLength

end


