--
function UI:GetZoneMinShipRank( zoneId )

	local rank = -1

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetZoneMinShipRank()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return rank
	end

	local zoneDesc = _G.SpaceZoneById and _G.SpaceZoneById[ zoneId ]

	if zoneDesc ~= nil then
		if type( zoneDesc ) ~= "table" then
			sys.log( "UI:GetZoneMinShipRank()[ERROR]: invalid type of the _G.SpaceZoneById[%d]; \"table\" expected, got \"%s\"", zoneId, type( zoneDesc ) )
			zoneDesc = nil
		end
	else
		sys.log( "UI:GetZoneMinShipRank()[ERROR]: cannot find _G.SpaceZoneById[%d]", zoneId )
	end

	if not zoneDesc then
		return rank
	end

	if type( zoneDesc.min_ship_rank ) == "number" then
		rank = zoneDesc.min_ship_rank
	else
		sys.log( "UI:GetZoneMinShipRank()[ERROR]: invalid type of \"_G.SpaceZoneById[%d].min_ship_rank\"; \"number\" expected, got \"%s\"", type( zoneDesc.min_ship_rank ) )
	end

	return rank

end


