--
function UI:IsPveMissionDisabled( missionName )

	local bDisabled = false

	if type( missionName ) ~= "string" then
		sys.log( "UI:IsPveMissionDisabled()[ERROR]: invalid type of the 1-st parameter (\"missionName\"); \"string\" expected, got \"%s\"", type( missionName ) )
		return false
	end

	local missionDef = _G.PvE_Missions[ missionName ]
	if type( missionDef ) ~= "table" then
		sys.log( "UI:IsPveMissionDisabled()[ERROR]: invalid type of \"_G.PvE_Missions.%s\"; \"table\" expected, got \"%s\"", missionName, type( missionDef ) )
		return false
	end

	if missionDef.disabled ~= nil then

		if type( missionDef.disabled ) == "boolean" then
			bDisabled = missionDef.disabled

		elseif type( missionDef.disabled ) == "number" then
			bDisabled = missionDef.disabled ~= 0

		else
			sys.log( "UI:IsPveMissionDisabled()[ERROR]: invalid type of \"_G.PvE_Missions.%s.disabled\"; \"boolean\" or \"number\" or \"nil\" expected, got \"%s\"", missionName, type( missionDef.disabled ) )
		end

	-- если disabled не прописан, то умолчанию для pve он true (#0055280, комм.(0220551)),
	-- а для рейда "старая логика" (#0055280, комм.(0220643)) ... видимо false, но ui всегда вообще игнорировал этот параметр для рейда

	else

		if UI:IsPveMissionRaid( missionName ) then
			bDisabled = false
		else
			bDisabled = true
		end

	end

	return bDisabled

end


--
function UI:GetPveMissionDifficulty( missionName )

	local difficulty = ""

	if type( missionName ) ~= "string" then
		sys.log( "UI:GetPveMissionDifficulty()[ERROR]: invalid type of the 1-st parameter (\"missionName\"); \"string\" expected, got \"%s\"", type( missionName ) )
