		return difficulty
	end

	if missionDef.difficulty ~= nil then
		if type( missionDef.difficulty ) == "string" then
			difficulty = missionDef.difficulty
		else
			sys.log( "UI:IsPveMissionDisabled()[ERROR]: invalid type of \"_G.PvE_Missions.%s.difficulty\"; \"string\" or \"nil\" expected, got \"%s\"", missionName, type( missionDef.difficulty ) )
		end
	end

	return difficulty

end


