--
function UI:IsPveMissionRaid( missionName )

	local bRaid = false

	if type( missionName ) ~= "string" then
		sys.log( "UI:IsPveMissionRaid()[ERROR]: invalid type of the 1-st parameter (\"missionName\"); \"string\" expected, got \"%s\"", type( missionName ) )
		return bRaid
	end

	if type( _G.PvE_Missions ) ~= "table" then
		sys.log( "UI:IsPveMissionRaid()[ERROR]: invalid type of \"_G.PvE_Missions\"; \"table\" expected, got \"%s\"", type( _G.PvE_Missions ) )
		return bRaid
	end

	local missionDef = _G.PvE_Missions[ missionName ]
	if type( missionDef ) ~= "table" then
		sys.log( "UI:IsPveMissionRaid()[ERROR]: invalid type of \"_G.PvE_Missions.%s\"; \"table\" expected, got \"%s\"", missionName, type( missionDef ) )
		return bRaid
	end

	if missionDef.is_raid ~= nil then
    	if type( missionDef.is_raid ) == "boolean" then
    		bRaid = missionDef.is_raid
    	else
    		sys.log( "UI:IsPveMissionRaid()[ERROR]: invalid type of \"_G.PvE_Missions.%s.is_raid\"; \"boolean\" or \"nil\" expected, got \"%s\"", missionName, type( missionDef.is_raid ) )
    	end
	end

	return bRaid

end


--
function UI:GetPveRaidShipRanks( raidLevelName )

	local minRank	= -1
	local maxRank	= -1

	if type( raidLevelName ) ~= "string" then
		sys.log( "UI:GetPveRaidShipRanks()[ERROR]: invalid type of the 1-st parameter (\"raidLevelName\"); \"string\" expected, got \"%s\"", type( raidLevelName ) )
		return minRank, maxRank
	end

	local missions = self:GetPveRaidMissions( raidLevelName )

	for misionIdx, missionName in pairs( missions ) do

		local missionMinRank, missionMaxRank = UI:GetPveMissionShipRanks( missionName )

		if minRank == -1 or missionMinRank < minRank then
			minRank = missionMinRank
		end

		if maxRank == -1 or missionMaxRank > maxRank then
			maxRank = missionMaxRank
		end

	end

	return minRank, maxRank

end


--
function UI:GetPveRaidRequiredRank( raidLevelName )

	local minRank, maxRank = UI:GetPveRaidShipRanks( raidLevelName )
	return minRank

end


--
function UI:GetPveRaidMaxRank( raidLevelName )

	local minRank, maxRank = UI:GetPveRaidShipRanks( raidLevelName )
	return maxRank

end


--
function UI:GetPveMissionsForLevel( levelName, bRaid, bEnabledOnly, difficulty )

	local missions = {}

	if type( levelName ) ~= "string" then
		sys.log( "UI:GetPveMissionsForLevel()[ERROR]: invalid type of the 1-st parameter (\"levelName\"); \"string\" expected, got \"%s\"", type( levelName ) )
		return missions
	end

	if type( bRaid ) ~= "boolean" then
		sys.log( "UI:GetPveMissionsForLevel()[ERROR]: invalid type of the 2-nd parameter (\"bRaid\"); \"boolean\" expected, got \"%s\"", type( bRaid ) )
		return missions
	end

	if type( bEnabledOnly ) ~= "boolean" then
		sys.log( "UI:GetPveMissionsForLevel()[ERROR]: invalid type of the 3-rd parameter (\"bEnabledOnly\"); \"boolean\" expected, got \"%s\"", type( bEnabledOnly ) )
		return missions
	end

	if difficulty ~= nil then
		if type( difficulty ) ~= "string" then
			sys.log( "UI:GetPveMissionsForLevel()[ERROR]: invalid type of the 4-th parameter (\"difficulty\"); \"string\" or \"nil\" expected, got \"%s\"", type( difficulty ) )
			difficulty = nil
		end
	end

	if difficulty == nil then
		difficulty = ""
	end

	if type( _G.PvE_Missions ) ~= "table" then
		sys.log( "UI:GetPveMissionsForLevel()[ERROR]: invalid type of \"_G.PvE_Missions\"; \"table\" expected, got \"%s\"", type( _G.PvE_Missions ) )
		return missions
	end

	for missionName, missionDef in pairs( _G.PvE_Missions ) do

		if	UI:IsPveMissionRaid( missionName ) == bRaid
			and UI:GetPveMissionLevelName( missionName ) == levelName
			and ( not bEnabledOnly or not UI:IsPveMissionDisabled( missionName ) )
			and ( difficulty == "" or UI:GetPveMissionDifficulty( missionName ) == difficulty ) then
				table.insert( missions, missionName )
		end

	end

	return missions

end


--
function UI:GetPveRaidMissions( raidLevelName )

	return UI:GetPveMissionsForLevel( raidLevelName, true, false )

end


--
function UI:GetPveMissionMaxResurrectionAttempts( missionName )

	local maxAttempts = 0

	if type( missionName ) ~= "string" then
		sys.log( "UI:GetPveMissionMaxResurrectionAttempts()[ERROR]: invalid type of the 1-st parameter (\"missionName\"); \"string\" expected, got \"%s\"", type( missionName ) )
		return maxAttempts
	end

	if type( _G.PvE_Missions ) ~= "table" then
		sys.log( "UI:GetPveMissionMaxResurrectionAttempts()[ERROR]: invalid type of \"_G.PvE_Missions\"; \"table\" expected, got \"%s\"", type( _G.PvE_Missions ) )
		return maxAttempts
	end

	local missionDef = _G.PvE_Missions[ missionName ]
	if type( missionDef ) ~= "table" then
		sys.log( "UI:GetPveMissionMaxResurrectionAttempts()[ERROR]: invalid type of \"_G.PvE_Missions.%s\"; \"table\" expected, got \"%s\"", missionName, type( missionDef ) )
		return maxAttempts
	end

	if missionDef.resurrection_attempts ~= nil then
		if type( missionDef.resurrection_attempts ) == "number" then
			maxAttempts = missionDef.resurrection_attempts
		else
			sys.log( "UI:GetPveMissionMaxResurrectionAttempts()[ERROR]: invalid type of \"_G.PvE_Missions.%s.resurrection_attempts\"; \"number\" or \"nil\" expected, got \"%s\"", missionName, type( missionDef.resurrection_attempts ) )
		end
	end

	return maxAttempts

end


-- среди кораблей, установленных в боевых слотах
function UI:GetCurrentShipsMaxRank()

	local shipRank = -1

	for battleSlotIdx, vid in pairs( UI.serverData.battleSlots ) do

		if vid ~= UI.INVALID_U64_ID then

			local shipItem = UI:GetShipItem( vid )
			if shipItem then

				local rank = UI:GetShipRank( shipItem.defName )
				if rank ~= -1 then

					if rank >= shipRank then
						shipRank = rank
					end

				else
					sys.log( "UI:GetCurrentShipsMaxRank()()[ERROR]: invalid ship rank for ship %s", shipItem.defName )
				end

			else
				sys.log( "UI:GetCurrentShipsMaxRank()()[ERROR]: cannot find ship item" )
			end

		end

	end

	return shipRank

end


-- из всех кораблей, когда-либо покупавшихся игроком
function UI:GetShipsMaxRank()

	local rank = _G.MasterServer_GetMaxVesselRank()

	if type( rank ) == "number" then
		if rank == 0 then
			rank = -1
		end
	else
		sys.log( "UI:GetShipsMaxRank()[ERROR]: invalid type of return value from MasterServer_GetMaxVesselRank(); \"number\" expected, got \"%s\"", type( rank ) )
		rank = -1
	end

	return rank

end


--
function UI:AddChatMsgOnPveRaidStarted()

	local data = _G.MasterServer_GetRaidSchedule()

	if type( data ) ~= "table" then
		sys.log( "UI:AddChatMsgOnPveRaidStarted()[ERROR]: invalid type of return value from MasterServer_GetRaidSchedule(); \"table\" expected, got \"%s\"", type( data ) )
		return
	end

	local raidMinRank		= -1
	local raidMaxRank		= -1
	local raidLevelName		= ""

	if type( data.levelName ) == "string" then

		if data.levelName ~= "" then

			raidLevelName = data.levelName
			raidMinRank, raidMaxRank = UI:GetPveRaidShipRanks( raidLevelName )

		else
			sys.log( "UI:AddChatMsgOnPveRaidStarted()[ERROR]: empty levelName" )
		end

	else
		sys.log( "UI:AddChatMsgOnPveRaidStarted()[ERROR]: invalid format of _G.MasterServer_GetRaidSchedule().levelName; \"string\" expected, got \"%s\"", type( data.levelName ) )
	end

	if raidMinRank == -1 or raidMinRank > UI:GetPlayerRank() then
		return
	end

	local strRaidName	= UI:GetLevelLocalizedName( raidLevelName )
	local strMinRank	= tostring( raidMinRank )
	local strMaxRank	= tostring( raidMaxRank )

	local tSubst =
	{
		raid		= strRaidName,
		min_rank	= strMinRank,
		max_rank	= strMaxRank,
	}

	local msg = UI:GetStringByName( "chat_pveRaidStarted" )
	local numSubst = 0
	msg, numSubst = string.gsub( msg, "%$(.-)%$", tSubst )

	if numSubst < UI:GetTableLength( tSubst ) then
		sys.log( "UI:AddChatMsgOnPveRaidStarted()[ERROR]: invalid placeholders in string \"chat_pveRaidStarted\"; expected \"$raid$\", \"$min_rank$\", \"$max_rank$\"" )
		msg = string.format( "[INVALID_STRING] Raid %s is available. Ranks %s-%s", strRaidName, strMinRank, strMaxRank )
	end

	UI.Chat:AddSystemMessage( msg )

end


--
function UI:GetPveMissionToLaunchForLevel( levelName, bRaid, difficulty )

	local missionNameToLaunch = ""

	if type( levelName ) ~= "string" then
		sys.log( "UI:GetPveMissionToLaunchForLevel()[ERROR]: invalid type of the 1-st parameter (\"levelName\"); \"string\" expected, got \"%s\"", type( levelName ) )
		return missionNameToLaunch
	end

	if type( bRaid ) ~= "boolean" then
		sys.log( "UI:GetPveMissionToLaunchForLevel()[ERROR]: invalid type of the 2-nd parameter (\"bRaid\"); \"boolean\" expected, got \"%s\"", type( bRaid ) )
		return missionNameToLaunch
	end

	if difficulty ~= nil then
		if type( difficulty ) ~= "string" then
			sys.log( "UI:GetPveMissionToLaunchForLevel()[ERROR]: invalid type of the 3-rd parameter (\"difficulty\"); \"string\" or \"nil\" expected, got \"%s\"", type( difficulty ) )
			difficulty = nil
		end
	end

	if difficulty == nil then
		difficulty = ""
	end

	local shipRank = UI:GetCurrentShipsMaxRank()

	if shipRank == -1 then
		return missionNameToLaunch
	end


	local missionRankToLaunch = -1

	local missions = UI:GetPveMissionsForLevel( levelName, bRaid, true, difficulty )
	for idx, missionName in pairs( missions ) do

		local missionMinRank, missionMaxRank = UI:GetPveMissionShipRanks( missionName )

		if missionMinRank ~= -1 and missionMaxRank ~= -1 and shipRank >= missionMinRank and shipRank <= missionMaxRank then

			if missionMaxRank > missionRankToLaunch then
				missionRankToLaunch = missionMaxRank
				missionNameToLaunch = missionName
			end

		end

	end

	return missionNameToLaunch

end


