--
function UI:GetArenaPlaceIcoBig( place, bMajor )

	if type( place ) ~= "number" then
		sys.log( "UI:GetArenaPlaceIcoBig()[ERROR]: invalid type of the 1-st parameter (\"place\"); \"number\" expected, got \"%s\"", type( place ) )
		return UI:GetTex( "NoData" )
	end

	if bMajor ~= nil then
		if type( bMajor ) ~= "boolean" then
			sys.log( "UI:GetArenaPlaceIcoBig()[ERROR]: invalid type of the 2-nd parameter (\"bMajor\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bMajor ) )
			bMajor = nil
		end
	end

	if bMajor == nil then
		bMajor = false
	end

	local ranges = bMajor and UI.arenaMajorPlaceIcoRanges or UI.arenaPlaceIcoRanges
	local icoRangeIdx = -1

	for rangeIdx = #ranges, 1, -1 do

		local rangeStartPlace = ranges[ rangeIdx ]

		if place >= rangeStartPlace then
			icoRangeIdx = rangeIdx
			break
		end

	end

	local hTex = UI.INVALID_RESOURCE_HANDLE

	if icoRangeIdx ~= -1 then

		local rangeStartPlace = ranges[ icoRangeIdx ]
		local texName = string.format( "arena_place_%d", rangeStartPlace )

		if bMajor then
			texName = string.format( "%s_major", texName )
		end

		hTex = UI:GetTex( texName )

	else
		sys.log( "UI:GetArenaPlaceIcoBig()[ERROR]: cannot find ico range for place %d", place )
		hTex = UI:GetTex( "NoData" )
	end

	return hTex

end


