--
function UI:GetCraftShipAvailableBonuses( shipDefName, synergyLevel )

	local bonuses = {}

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetCraftShipAvailableBonuses()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return bonuses
	end

	if type( synergyLevel ) ~= "number" then
		sys.log( "UI:GetCraftShipAvailableBonuses()[ERROR]: invalid type of the 2-nd parameter (\"synergyLevel\"); \"number\" expected, got \"%s\"", type( synergyLevel ) )
		return bonuses
	end

	local shipDef = UI:GetDef( shipDefName )
	if not shipDef then
		sys.log( "UI:GetCraftShipAvailableBonuses()[ERROR]: cannot find _G.Def[\"%s\"]", shipDefName )
		return bonuses
	end

	if shipDef.special_grades == nil then
		return bonuses
	end

	if type( shipDef.special_grades ) ~= "table" then
		sys.log( "UI:GetCraftShipAvailableBonuses()[ERROR]: invalid type of _G.Def[\"%s\"].special_grades; \"table\" or \"nil\" expected, got \"%s\"", shipDefName, type( shipDef.special_grades ) )
		return bonuses
	end

	local levelBonuses = shipDef.special_grades[ synergyLevel ]

	if levelBonuses == nil then
		return bonuses
	end

	if type( levelBonuses ) ~= "table" then
		sys.log( "UI:GetCraftShipAvailableBonuses()[ERROR]: invalid type of _G.Def[\"%s\"].special_grades[%d]; \"table\" or \"nil\" expected, got \"%s\"", shipDefName, synergyLevel, type( levelBonuses ) )
		return bonuses
	end

	for bonusIdx, bonusName in ipairs( levelBonuses ) do

		if type( bonusName ) == "string" then
			table.insert( bonuses, bonusName )
		else
			sys.log( "UI:GetCraftShipAvailableBonuses()[ERROR]: invalid type of _G.Def[\"%s\"].special_grades[%d][%d]; \"string\" expected, got \"%s\"", shipDefName, synergyLevel, bonusIdx, type( levelBonuses ) )
		end

	end

	return bonuses

end


-- для "зеленых" кораблей есть два вида рекламного корабля - определение через деф и чере флаг IS_ADVERT в магазинном товаре
function UI:IsShipAdvert( defName )

	local bAdvert	= false
	local byFlag	= false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsShipAdvert()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bAdvert, byFlag
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsShipAdvert()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return bAdvert, byFlag
	end

	if def.advert ~= nil then

		if type( def.advert ) == "boolean" then
			bAdvert	= def.advert
		else
			sys.log( "UI:IsShipAdvert()[ERROR]: invalid type of _G.Def[\"%s\"].advert; \"boolean\" expected, got \"%s\"", defName, type( def.advert ) )
		end

	end

	if not bAdvert then

    	local shopItem = self:GetShopItemByDef( defName )
    	if shopItem then

			bAdvert = UI:IsItemAdvert( shopItem )

			if bAdvert then
				byFlag = true
			end

		else
    		sys.log( "UI:IsShipAdvert()[ERROR]: cannot find shop item for \"%s\"", defName )
    	end

	end

	return bAdvert, byFlag

end


--
function UI:GetShipAdvertLink( defName )

	local link = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipAdvertLink()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return link
	end

    local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetShipAdvertLink()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return link
	end

	local linkVarName = UI:GetLanguage() == "RUSSIAN" and "advert_url_ru" or "advert_url_en"
	local link = def[ linkVarName ]

	if link ~= nil then
		if type( link ) ~= "string" then
			sys.log( "UI:GetShipAdvertLink()[ERROR]: invalid type of _G.Def[\"%s\"].%s; \"string\" or \"nil\" expected, got \"%s\"", defName, linkVarName, type( link ) )
			link = nil
		end
	end

	if link == nil then
		link = ""
	end

	return link

end


