--
function UI:GetShipUpgradeCostForLevel( defName, level )

	local cost = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipUpgradeCostForLevel()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return cost
	end

	if type( level ) ~= "number" then
		sys.log( "UI:GetShipUpgradeCostForLevel()[ERROR]: invalid type of the 1-st parameter (\"level\"); \"number\" expected, got \"%s\"", type( level ) )
		return cost
	end

	if type( _G.VesselExpPerLevel ) ~= "table" then
		sys.log( "UI:GetShipUpgradeCostForLevel()[ERROR]: invalid type of _G.VesselExpPerLevel; \"table\" expected, got \"%s\"", type( _G.VesselExpPerLevel ) )
		return cost
	end

	local rank = UI:GetShipRank( defName )

	if type( _G.VesselExpPerLevel[ rank ] ) ~= "table" then
		sys.log( "UI:GetShipUpgradeCostForLevel()[ERROR]: invalid type of _G.VesselExpPerLevel[%d]; \"table\" expected, got \"%s\"", rank, type( _G.VesselExpPerLevel[ rank ] ) )
		return cost
	end

	local cost = _G.VesselExpPerLevel[ rank ][ level ]
	if type( cost ) ~= "number" then
		sys.log( "UI:GetShipUpgradeCostForLevel()[ERROR]: invalid type of _G.VesselExpPerLevel[%d][%d]; \"number\" expected, got \"%s\"", rank, level, type( cost ) )
		return cost
	end

	return cost

end


--
function UI:GetShipPartsForShip( shipDefName )

	local resourceDefName	= ""
	local count				= 0

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipPartsForShip()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return resourceDefName, count
	end

	if not UI:IsDefShip( shipDefName ) then
		sys.log( "UI:GetShipPartsForShip()[ERROR]: \"%s\" is  not ship", shipDefName )
		return resourceDefName, count
	end

	if not UI:IsShipGold( shipDefName ) or UI:IsShipCraftable( shipDefName ) then
		return resourceDefName, count
	end

	local def = UI:GetDef( shipDefName )
	if not def then
		sys.log( "UI:GetShipPartsForShip()[ERROR]: cannot dinf _G.Def[\"%s\"]", shipDefName )
		return resourceDefName, count
	end

	if def.resource_required == nil then
		return resourceDefName, count
	end

	if type( def.resource_required ) ~= "string" then
		sys.log( "UI:GetShipPartsForShip()[ERROR]: invalid type of _G.Def[\"%s\"].resource_required; \"string\" or \"nil\" expected, got \"%s\"", type( def.resource_required ) )
		return resourceDefName, count
	end

	if def.resource_required == "" then
		return resourceDefName, count
	end

	resourceDefName = def.resource_required

	if type( def.resource_count ) == "number" then
		count = def.resource_count
	else
		sys.log( "UI:GetShipPartsForShip()[ERROR]: invalid type of _G.Def[\"%s\"].resource_count; \"number\" expected, got \"%s\"", type( def.resource_count ) )
	end

	return resourceDefName, count

end


--
function UI:GetShipPartsForShipDefName( shipDefName )

	local resourceDefName, count = UI:GetShipPartsForShip( shipDefName )
	return resourceDefName

end


--
function UI:GetShipPartsForShipCount( shipDefName )

	local resourceDefName, count = UI:GetShipPartsForShip( shipDefName )
	return count

end


--
function UI:IsShipBuildableFromShipParts( defName )

	return UI:GetShipPartsForShipDefName( defName ) ~= ""

end


--
function UI:IsEnoughShipPartsForShip( shipDefName )

	local bEnough = false

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:IsEnoughShipPartsForShip()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return bEnough
	end

	local resourceDefName, needRecourceCount = UI:GetShipPartsForShip( shipDefName )
	if resourceDefName ~= "" then
		bEnough = needRecourceCount <= UI:GetPlayerResourceCount( resourceDefName )
	else
		sys.log( "UI:IsEnoughShipPartsForShip()[ERROR]; ship \"%s\" is not buildable from ship parts", shipDefName )
	end

	return bEnough

end


