--
function UI:GetShipPartsDlcForShip( shipDefName )

	local dlcName = ""

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipPartsDlcForShip()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return dlcName
	end

	local shipDef = UI:GetDef( shipDefName )
	if not shipDef then
		sys.log( "UI:GetShipPartsDlcForShip()[ERROR]: cannot find _G.Def[\"%s\"]", shipDefName )
		return dlcName
	end

	local fieldName = UI:GetLanguage() == "RUSSIAN" and "resource_dlc_ru" or "resource_dlc_en"

	if shipDef[ fieldName ] == nil then
