	end

	if type( shipDef[ fieldName ] ) == "string" then
		dlcName = shipDef[ fieldName ]
	else
		sys.log( "UI:GetShipPartsDlcForShip()[ERROR]: invalid type of the _G.Def[\"%s\"].%s; \"string\" or \"nil\" expected, got \"%s\"", shipDefName, fieldName, type( shipDef[ fieldName ] ) )
	end

	return dlcName

end


--
function UI:GetItemRequiredShips( itemDefName )

	local shipDefNames = {}

	if type( itemDefName ) ~= "string" then
		sys.log( "UI:GetItemRequiredShips()[ERROR]: invalid type of the 1-st parameter (\"itemDefName\"); \"string\" expected, got \"%s\"", type( itemDefName ) )
		return shipDefNames
	end

	local itemDef = UI:GetDef( itemDefName )
	if not itemDef then
		sys.log( "UI:GetItemRequiredShips()[ERROR]: cannot find _G.Def[\"%s\"]", itemDefName )
		return shipDefNames
	end

	if itemDef.required_ship == nil then
		return shipDefNames
	end

	if type( itemDef.required_ship ) == "string" then
		shipDefNames = { itemDef.required_ship }

	elseif type( itemDef.required_ship ) == "table" then

		local bValid = true

		for idx, defName in pairs( itemDef.required_ship ) do
			if type( idx ) ~= "number" or type( defName ) ~= "string" then
				sys.log( "UI:GetItemRequiredShips()[ERROR]: invalid format of _G.Def[\"%s\"].required_ship table; <number>=<string> expected, got <%s>=<%s>", itemDefName, type( idx ), type( defName ) )
				bValid = false
			end
		end

		if bValid then
			shipDefNames = itemDef.required_ship
		end

	else
		sys.log( "UI:GetItemRequiredShips()[ERROR]: invalid type of _G.Def[\"%s\"].required_ship; \"string\", \"table\" or \"nil\" expected, got \"%s\"", itemDefName, type( itemDef.required_ship ) )
	end

	return shipDefNames

end


