--
function UI:CanShipOfRankGainResourceReward( shipRank )

	local bCanGain = false

	if type( shipRank ) ~= "number" then
		sys.log( "UI:CanShipOfRankGainResourceReward()[ERROR]: invalid type of the 1-st parameter (\"shipRank\"); \"number\" expected, got \"%s\"", type( shipRank ) )
		return bCanGain
	end

	if type( _G.ShipLootRank ) ~= "table" then
		sys.log( "UI:CanShipOfRankGainResourceReward()[ERROR]: invalid type of _G.ShipLootRank; \"table\" expected, got \"%s\"", type( _G.ShipLootRank ) )
		return bCanGain
	end

	for idx, rank in pairs( _G.ShipLootRank ) do
		if rank == shipRank then
			bCanGain = true
			break
		end
	end

	return bCanGain

end


