	else
		sys.log( "UI:GetShipBuiltFromResource()[ERROR]: invalid type of _G.Def[\"%s\"].ship_parts; \"string\" or \"nil\" expected, got \"%s\"", resourceDefName, type( shipPartDef.ship_parts ) )
