--
function UI:HasGroupActiveQuest( groupId )

	local bHasActiveQuest = false

	if type( groupId ) ~= "number" then
		sys.log( "UI:HasGroupActiveQuest()[ERROR]: invalid type of the 1-st parameter (\"groupId\"); \"number\" expected, got \"%s\"", type( groupId ) )
		return bHasActiveQuest
	end

	if groupId == -1 then
		sys.log( "UI:HasGroupActiveQuest()[ERROR]: invalid group" )
		return bHasActiveQuest
	end

	local bCompleted = _G.MasterServer_IsQuestGroupCompleted( groupId )	-- х.з. причем тут completed в названии, она возвращает false когда есть взятый квест в группе

	if type( bCompleted ) == "boolean" then
		bHasActiveQuest = not bCompleted
	else
		sys.log( "UI:HasGroupActiveQuest()[ERROR]: invalid type of return value from _G.MasterServer_IsQuestGroupCompleted() for group %d; \"boolean\" expected, got \"%s\"", groupId, type( bCompleted ) )
	end

	return bHasActiveQuest

end


