--
function UI:GetShipCustomizableSpecModules( shipDefName )

	local specModules = {}

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipCustomizableSpecModules()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return specModules
	end

	if UI:IsShipCraftable( shipDefName ) then
		return specModules
	end

	if UI:IsShipEvolving( shipDefName ) then
		return specModules
	end

	local def = UI:GetDef( shipDefName )
	if not def then
		sys.log( "UI:GetShipCustomizableSpecModules()[ERROR]: cannot find _G.Def[\"%s\"]", shipDefName )
		return specModules
	end

	if def.SpecialModulesVariants == nil then
		return specModules
	end

	if type( def.SpecialModulesVariants ) ~= "table" then
		sys.log( "UI:GetShipCustomizableSpecModules()[ERROR]: invalid type of _G.Def[\"%s\"].SpecialModulesVariants; \"table\" or \"nil\" expected, got \"%s\"", shipDefName, type( def.SpecialModulesVariants ) )
		return specModules
	end

	for level, levelInfo in ipairs( def.SpecialModulesVariants ) do

		local bSuccess = false

		if type( levelInfo ) == "table" then

			if type( levelInfo.def ) == "string" then

				if type( levelInfo.cost ) == "number" then

					local specModuleInfo =
					{
						defName	= levelInfo.def,
						cost	= levelInfo.cost,
					}

					table.insert( specModules, specModuleInfo )
					bSuccess = true

				else
        			sys.log( "UI:GetShipCustomizableSpecModules()[ERROR]: invalid type of _G.Def[\"%s\"].SpecialModulesVariants[%d].cost; \"number\" expected, got \"%s\"", shipDefName, level, type( levelInfo.cost ) )
				end

			else
    			sys.log( "UI:GetShipCustomizableSpecModules()[ERROR]: invalid type of _G.Def[\"%s\"].SpecialModulesVariants[%d].def; \"string\" expected, got \"%s\"", shipDefName, level, type( levelInfo.def ) )
			end

		else
			sys.log( "UI:GetShipCustomizableSpecModules()[ERROR]: invalid type of _G.Def[\"%s\"].SpecialModulesVariants[%d]; \"table\" expected, got \"%s\"", shipDefName, level, type( levelInfo ) )
		end

		if not bSuccess then
			sys.log( "UI:GetShipCustomizableSpecModules()[ERROR]: fail to get spec modules - invalid format of _G.Def[\"%s\"].SpecialModulesVariants", shipDefName )
			specModules = {}
			break
		end

	end

	return specModules

end


--
function UI:GetShipMaxSpecModuleLevel( shipDefName )

	local maxLevel = -1

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipMaxSpecModuleLevel()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return maxLevel
	end

	local specModules = UI:GetShipCustomizableSpecModules( shipDefName )
	if next( specModules ) then
		maxLevel = #specModules
	end

	return maxLevel

end


