--
function UI:GetShipSpecModuleLevelCost( shipDefName, level )

	local numParts = 0

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipSpecModuleLevelCost()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return numParts
	end

	if type( level ) ~= "number" then
		sys.log( "UI:GetShipSpecModuleLevelCost()[ERROR]: invalid type of the 2-nd parameter (\"level\"); \"number\" expected, got \"%s\"", type( level ) )
		return numParts
	end

	if level == 0 then

		numParts = 0

	else

    	local specModules		= UI:GetShipCustomizableSpecModules( shipDefName )
    	local specModuleInfo	= specModules[ level ]

    	if specModuleInfo then
    		numParts = specModuleInfo.cost
    	else
    		sys.log( "UI:GetShipSpecModuleLevelCost()[ERROR]: cannot fint spec module for level %d on ship %s", level, shipDefName )
    	end

	end

	return numParts

end


--
function UI:GetShipSpecModuleForLevel( shipDefName, level )

	local specModuleDefName = ""

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return specModuleDefName
	end

	if type( level ) ~= "number" then
		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: invalid type of the 2-nd parameter (\"level\"); \"number\" expected, got \"%s\"", type( level ) )
		return specModuleDefName
	end

	if level == 0 then

		specModuleDefName = UI:GetShipDefaultSpecModule( shipDefName )

	else

    	local specModules		= UI:GetShipCustomizableSpecModules( shipDefName )
    	local specModuleInfo	= specModules[ level ]

    	if specModuleInfo then
    		specModuleDefName = specModuleInfo.defName
    	else
    		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: cannot fint spec module for level %d on ship %s", level, shipDefName )
    	end

	end

	return specModuleDefName

end


-- если данный модуль - дефолтный, то возвращается 0
-- уровень модуля специфичен для коралбя, т.к. теоретически один и тот же модуль может быть прописан на разных кораблях
function UI:GetSpecModuleLevel( specModuleDefName, shipDefName )

	local level = -1

	if type( specModuleDefName ) ~= "string" then
		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: invalid type of the 1-st parameter (\"specModuleDefName\"); \"string\" expected, got \"%s\"", type( specModuleDefName ) )
		return level
	end

	if specModuleDefName == "" then
		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: empty module name" )
		return level
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: invalid type of the 2-nd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return level
	end

	if shipDefName == "" then
		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: empty ship name" )
		return level
	end

	if UI:GetShipDefaultSpecModule( shipDefName ) == specModuleDefName then

		level = 0

	else

    	local maxShipLevel = UI:GetShipMaxSpecModuleLevel( shipDefName )
    	if maxShipLevel ~= -1 then

        	for shipLevel = 1, maxShipLevel do
        		local specModuleDefNameOnLevel = UI:GetShipSpecModuleForLevel( shipDefName, shipLevel )
        		if specModuleDefNameOnLevel == specModuleDefName then
        			level = shipLevel
        			break
        		end
        	end

		else
    		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: spec module on ship %s is not customizable" )
		end

	end

	if level == -1 then
		sys.log( "UI:GetShipSpecModuleForLevel()[ERROR]: cannot find level for specmodule %s on ship %s", specModuleDefName, shipDefName )
	end

	return level

end


