--
function UI:SpecModuleParts2Str( shipDefName )

	local str = "unknown"

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:SpecModuleParts2Str()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return str
	end

	local color = UI:GetItemQualityColor( UI.SPEC_MODULE_PARTS_COLOR_ID, false )
	local strColor = UI:Color2Str( color )

	local shipLocalizedName = UI:GetEntityLocalizedNameByDef( shipDefName, true, false, false, false )
	shipLocalizedName = string.format( "%s%s", shipLocalizedName, strColor )

	str = UI:GetStringByName( "specModulePartsTooltip_name" )

	local numSubst = 0
	str, numSubst = string.gsub( str, "%$ship_name%$", shipLocalizedName )

	if numSubst == 0 then
		sys.log( "UI:SpecModuleParts2Str()[ERROR]: cannot find placeholder \"$ship_name$\" in string \"specModulePartsTooltip_name\"" )
		str = string.format( "[INVALID STRING] Spec module parts for ship %s", shipLocalizedName )
	end

	str = string.format( "%s%s", strColor, str )

	return str

end


