--
function UI:UpdateServerData_OnVesselBudgetLevelUp( result, requestId, param1, param2, u64Param )

	if result ~= _G.GameStore.StoreBuyResult.SBR_OK then
		return
	end

	local vid = u64Param

	local shipItem = self:GetShipItem( vid, true )

	if shipItem then

		shipItem.specModuleLevel = _G.GameStore_GetBudgetLevel( vid ) or -1

		if shipItem.specModuleLevel ~= -1 then
			shipItem.specModuleLevel = shipItem.specModuleLevel + 1
		end

	else
		sys.log( "UI:UpdateServerData_OnVesselBudgetLevelUp()[ERROR]: no ship item for vid %s", _G.U64ToStr( vid ) )
	end

end


--
function UI:UpdateServerData_OnVesselBudgetChanged( vid )

	local shipItem = self:GetShipItem( vid, true )

	if shipItem then
		shipItem.specModuleParts = _G.GameStore_GetBudgetCount( vid ) or 0
	else
		sys.log( "UI:UpdateServerData_OnVesselBudgetChanged()[ERROR]: no ship item for vid %s", _G.U64ToStr( vid ) )
	end

end


-- аккаунт-аура может содержать несколько дискаунтных предметов на выбор, здесь возвращается только один, первый
function UI:GetAccountAuraDiscountedItem( accountAuraDefName )

	local itemDefName = ""
	local bIsLicense = false

	if type( accountAuraDefName ) ~= "string" then
		sys.log( "UI:GetAccountAuraDiscountedItem()[ERROR]: invalid type of the 1-st parameter (\"accountAuraDefName\"); \"string\" expected, got \"%s\"", type( accountAuraDefName ) )
		return itemDefName, bIsLicense
	end

	if type( _G.AccountAura ) ~= "table" then
		sys.log( "UI:GetAccountAuraDiscountedItem()[ERROR]: invalid type of _G.AccountAura; \"table\" expected, got \"%s\"", type( _G.AccountAura ) )
		return itemDefName, bIsLicense
	end

	local auraDef = _G.AccountAura[ accountAuraDefName ]
	if type( auraDef ) ~= "table" then
		sys.log( "UI:GetAccountAuraDiscountedItem()[ERROR]: invalid type of _G.AccountAura[\"%s\"]; \"table\" expected, got \"%s\"", accountAuraDefName, type( auraDef ) )
		return itemDefName, bIsLicense
	end

	if auraDef.discounted_def ~= nil then

		if type( auraDef.discounted_def ) == "string" then

			itemDefName = auraDef.discounted_def

			-- хаком определяется - лицензия это или нет;
			-- есть список, где прописаны цены на лицензии, это единственное место в луа, где они есть. А как еще определить, лицензия это или нет?
			-- TODO SC-112141 - это больше не используется, лицензии сейчас покупаются за реал, и ауры на них не могут давать скидку, надо убрать
			if designers and designers.defaultPremiumTimePrices and designers.defaultPremiumTimePrices[ itemDefName ] then
				bIsLicense = true
			end

		else
			sys.log( "UI:GetAccountAuraDiscountedItem()[ERROR]: invalid type of _G.AccountAura[\"%s\"].discounted_def; \"string\" or \"nil\" expected, got \"%s\"", accountAuraDefName, type( auraDef.discounted_def ) )
		end

	elseif auraDef.alt_discounted_defs ~= nil then

		if type( auraDef.alt_discounted_defs ) == "table" then

			if next( auraDef.alt_discounted_defs ) then

				if type( auraDef.alt_discounted_defs[ 1 ] ) == "string" then
					itemDefName = auraDef.alt_discounted_defs[ 1 ]
				else
					sys.log( "UI:GetAccountAuraDiscountedItem()[ERROR]: invalid type of _G.AccountAura[\"%s\"].alt_discounted_defs[1]; \"string\" expected, got \"%s\"", accountAuraDefName, type( auraDef.alt_discounted_defs[ 1 ] ) )
				end

			end

		else
			sys.log( "UI:GetAccountAuraDiscountedItem()[ERROR]: invalid type of _G.AccountAura[\"%s\"].alt_discounted_defs; \"table\" or \"nil\" expected, got \"%s\"", accountAuraDefName, type( auraDef.alt_discounted_defs ) )
		end

	end

	return itemDefName, bIsLicense

end


