-- в формате { <race> = { <defName>=true, <defName>=true, ... }, <race> = {...}, ... }
function UI:GetShipsVisibleInShipsTree()

	local ships = {}

	if type( _G.VesselTree ) ~= "table" then
		sys.log( "UI:GetShipsVisibleInShipsTree()[ERROR]: invalid type of \"_G.VesselTree\"; \"table\" expected, got \"%s\"", type( _G.VesselTree ) )
		return ships
	end

	for shipDefName, shipTreeInfo in pairs( _G.VesselTree ) do

		local race = UI:GetItemRace( shipDefName )
		if race ~= -1 then

			if UI:IsShipVisibleInShipsTree( shipDefName ) then

				if not ships[ race ] then
					ships[ race ] = {}
				end

				ships[ race ][ shipDefName ] = true

			end

		else
			sys.log( "UI:GetShipsVisibleInShipsTree()[ERROR]: cannot find race for ship %s", shipDefName )
		end

	end

	return ships

end


