-- defName - деф любого ранга в цепочке эволюции;
-- возвращает первый деф в цепочке
function UI:GetEvolvingShipBaseDef( defName )

	local baseDefName = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipBaseDef()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return baseDefName
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipBaseDef()[ERROR]: ship \"%s\" is not evolving", defName )
		return baseDefName
	end

	baseDefName = defName

	local chainDefName = self:GetEvolvingShipPrevDef( defName )
	while chainDefName ~= "" do
		baseDefName = chainDefName
		chainDefName = self:GetEvolvingShipPrevDef( chainDefName )
	end

	return baseDefName

end


-- defName - деф любого ранга в цепочке эволюции
function UI:GetEvolvingShipDefsChain( defName, bWithAltDefs )

	local defs = {}
	local altDefs = {}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipDefsChain()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return defs, altDefs
	end

	if bWithAltDefs ~= nil then
    	if type( bWithAltDefs ) ~= "boolean" then
    		sys.log( "UI:GetEvolvingShipDefsChain()[ERROR]: invalid type of the 2-nd parameter (\"bWithAltDefs\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bWithAltDefs ) )
			bWithAltDefs = nil
    	end
	end

	if bWithAltDefs == nil then
		bWithAltDefs = false
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipDefsChain()[ERROR]: ship \"%s\" is not evolving", defName )
		return defs, altDefs
	end

	local chainDefName = UI:GetEvolvingShipBaseDef( defName )
	while chainDefName ~= "" do
		table.insert( defs, chainDefName )
		chainDefName = UI:GetEvolvingShipNextDef( chainDefName )
	end

	if bWithAltDefs then

    	local nodes = UI:GetEvolvingShipNodes( defName )

    	local shipVariants = {}

    	for nodeName, node in pairs( nodes ) do

    		local nodeShipVariants = self:GetEvolvingShipNodeShipVariants( nodeName )

    		for mainDefName, altDefName in pairs( nodeShipVariants ) do

    			if not shipVariants[ mainDefName ] then
    				shipVariants[ mainDefName ] = {}
    			end

    			table.insert( shipVariants[ mainDefName ], altDefName )

    		end

    	end

    	for idx, mainDefName in ipairs( defs ) do
    		table.insert( altDefs, shipVariants[ mainDefName ] or {} )
    	end

	end

	return defs, altDefs

end


-- defName - деф любого ранга в цепочке эволюции
