end


-- defName - деф любого ранга в цепочке эволюции
function UI:GetEvolvingShipMaxRank( defName )

	local maxRank = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipMaxRank()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return maxRank
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipMaxRank()[ERROR]: ship \"%s\" is not evolving", defName )
		return maxRank
	end

	local baseDefName = UI:GetEvolvingShipBaseDef( defName )
	if baseDefName ~= "" then

		local lastChainDefName = baseDefName

		local chainDefName = UI:GetEvolvingShipNextDef( baseDefName )
		while chainDefName ~= "" do
			lastChainDefName = chainDefName
			chainDefName = UI:GetEvolvingShipNextDef( chainDefName )
		end

		maxRank = UI:GetShipRank( lastChainDefName )

	else
		sys.log( "UI:GetEvolvingShipMaxRank()[ERROR]: cannot find evolution chain base def for \"%s\"", defName )
	end

	return maxRank

end


-- defName - деф любого ранга в цепочке эволюции
function UI:GetEvolvingShipDefForRank( defName, rank )

	local rankDefName = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipDefForRank()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return rankDefName
	end

	if type( rank ) ~= "number" then
		sys.log( "UI:GetEvolvingShipDefForRank()[ERROR]: invalid type of the 2-nd parameter (\"rank\"); \"number\" expected, got \"%s\"", type( rank ) )
		return rankDefName
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipDefForRank()[ERROR]: ship \"%s\" is not evolving", defName )
		return rankDefName
	end

	local defs = UI:GetEvolvingShipDefsChain( defName )
	for idx, chainDefName in pairs( defs ) do

		local chainRank = UI:GetShipRank( chainDefName )
		if chainRank == rank then
			rankDefName = chainDefName
			break
		end

	end

	return rankDefName

end


-- defName - деф любого ранга в цепочке эволюции
function UI:GetEvolvingShipItem( defName )

	local shipItem = nil

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipItem()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return shipItem
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipItem()[ERROR]: ship \"%s\" is not evolving", defName )
		return shipItem
	end

	local defsArr, altDefsArr = UI:GetEvolvingShipDefsChain( defName, true )

	local defsMap = {}

	for idx, def in pairs( defsArr ) do
		defsMap[ def ] = true
	end

	for idx, defs in pairs( altDefsArr ) do
		for idx1, def in pairs( defs ) do
			defsMap[ def ] = true
		end
	end

	-- не вызывается GetShipItemByDef(), т.к. она тяжелая, а надо вызвать много раз;
	-- не проверяется на conserved, т.к. эти корабли нельзя продавать

	for idx, item in pairs( self.serverData.allShips ) do
		if defsMap[ item.defName ] then
			shipItem = item
			break
		end
	end

	return shipItem

end


