-- defName - деф любого ранга в цепочке эволюции
function UI:GetEvolvingShipCabin( defName )

	local cabinDefName = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipCabin()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return cabinDefName
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipCabin()[ERROR]: ship \"%s\" is not evolving", defName )
		return cabinDefName
	end

	local baseDefName = UI:GetEvolvingShipBaseDef( defName )
	if baseDefName == "" then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: cannot find evolution chain base def for \"%s\"", defName )
		return cabinDefName
	end

	local def = UI:GetDef( baseDefName )
	if not def then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: cannot find _G.[\"%s\"]", baseDefName )
		return cabinDefName
	end

	if type( def.craftable_reagents ) ~= "table" then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: invalid type of _G.Def[\"%s\"].craftable_reagents; \"table\" expected, got \"%s\"", baseDefName, type( def.craftable_reagents ) )
		return cabinDefName
	end

	-- #0063605,комм.(0261468) - кабина отличается только тем, что находится в массиве первой

	local cabinInfo = def.craftable_reagents[ 1 ]
	if type( cabinInfo ) ~= "table" then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: invalid type of _G.Def[\"%s\"].craftable_reagents[1]; \"table\" expected, got \"%s\"", baseDefName, type( cabinInfo ) )
		return cabinDefName
	end

	if type( cabinInfo.resource ) == "string" then

		cabinDefName = cabinInfo.resource

		if cabinDefName == "" then
			sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]:	empty _G.Def[\"%s\"].craftable_reagents[1].resource", baseDefName )
		end

	else
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: invalid type of _G.Def[\"%s\"].craftable_reagents[1].resource; \"string\" expected, got \"%s\"", baseDefName, type( cabinInfo.resource ) )
	end

	return cabinDefName

end


-- defName - деф любого ранга в цепочке эволюции
function UI:GetEvolvingShipResourcePrice( defName )

	local resourceDefName	= ""
	local resourceCount		= 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return resourceDefName, resourceCount
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: ship \"%s\" is not evolving", defName )
		return resourceDefName, resourceCount
	end

	local baseDefName = UI:GetEvolvingShipBaseDef( defName )
	if baseDefName == "" then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: cannot find evolution chain base def for \"%s\"", defName )
		return resourceDefName, resourceCount
	end

	local def = UI:GetDef( baseDefName )
	if not def then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: cannot find _G.[\"%s\"]", baseDefName )
		return resourceDefName, resourceCount
	end

	if type( def.craftable_reagents ) ~= "table" then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: invalid type of _G.Def[\"%s\"].craftable_reagents; \"table\" expected, got \"%s\"", baseDefName, type( def.craftable_reagents ) )
		return resourceDefName, resourceCount
	end

	-- #0063605,комм.(0261787) - этот ресурс отличается только тем, что находится в массиве вторым

	local resourceInfo = def.craftable_reagents[ 2 ]
	if type( resourceInfo ) ~= "table" then
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: invalid type of _G.Def[\"%s\"].craftable_reagents[2]; \"table\" expected, got \"%s\"", baseDefName, type( resourceInfo ) )
		return resourceDefName, resourceCount
	end

	if type( resourceInfo.resource ) == "string" then

		resourceDefName = resourceInfo.resource

		if resourceDefName == "" then
			sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]:	empty _G.Def[\"%s\"].craftable_reagents[2].resource", baseDefName )
		end

	else
		sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: invalid type of _G.Def[\"%s\"].craftable_reagents[2].resource; \"string\" expected, got \"%s\"", baseDefName, type( resourceInfo.resource ) )
	end

	if resourceDefName ~= "" then

        if type( resourceInfo.amount ) == "number" then
        	resourceCount = resourceInfo.amount
        else
        	sys.log( "UI:GetEvolvingShipResourcePrice()[ERROR]: invalid type of _G.Def[\"%s\"].craftable_reagents[2].amount; \"number\" expected, got \"%s\"", baseDefName, type( resourceInfo.amount ) )
        end

	end

	return resourceDefName, resourceCount

end


