-- defName - деф любого ранга в цепочке эволюции
function UI:GetEvolvingShipMaxEvolutionPoints( defName, unlockedNodesMask )

	local function fnGetBaseMaxEvolutionPoints()

		local evolutionPoints = 0

    	if type( defName ) ~= "string" then
    		sys.log( "UI:GetEvolvingShipMaxEvolutionPoints()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
    		return evolutionPoints
    	end

    	if not UI:IsShipEvolving( defName ) then
    		sys.log( "UI:GetEvolvingShipMaxEvolutionPoints()[ERROR]: ship \"%s\" is not evolving", defName )
    		return evolutionPoints
    	end

    	local baseDefName = UI:GetEvolvingShipBaseDef( defName )
    	if baseDefName == "" then
    		sys.log( "UI:GetEvolvingShipMaxEvolutionPoints()[ERROR]: cannot find evolution chain base def for \"%s\"", defName )
    		return evolutionPoints
    	end

    	local def = UI:GetDef( baseDefName )
    	if not def then
    		sys.log( "UI:GetEvolvingShipMaxEvolutionPoints()[ERROR]: cannot find \"_G.Def[\"%s\"]\"", baseDefName )
    		return evolutionPoints
    	end

    	if type( def.evolution_max ) == "number" then
    		evolutionPoints = def.evolution_max
    	else
    		sys.log( "UI:GetEvolvingShipMaxEvolutionPoints()[ERROR]: invalid type of _G.Def[\"%s\"].evolution_max; \"number\" expected, got \"%s\"", baseDefName, type( def.evolution_max ) )
    	end

		return evolutionPoints

	end

	local function fnGetAddMaxEvolutionPoints()

		local evolutionPoints = 0

		if unlockedNodesMask == nil then
			return evolutionPoints
		end

		if type( unlockedNodesMask ) ~= "userdata" then
    		sys.log( "UI:GetEvolvingShipMaxEvolutionPoints()[ERROR]: invalid type of the 2-nd parameter (\"unlockedNodesMask\"); \"userdata\" or \"nil\" expected, got \"%s\"", type( unlockedNodesMask ) )
			return evolutionPoints
		end

		if unlockedNodesMask == UI.INVALID_U64_ID then
			return evolutionPoints
		end

    	local nodes = UI:GetEvolvingShipNodes( defName )

    	local nodesById = {}
    	for nodeName, node in pairs( nodes ) do
    		nodesById[ UI:GetEvolvingShipNodeId( node.name ) ] = node
    	end

    	local MAX_ID = 63
    	for nodeId = 0, MAX_ID do

    		if UI:BitTstU64( unlockedNodesMask, nodeId ) then

    			local node = nodesById[ nodeId ]
    			if node then
    				evolutionPoints = evolutionPoints + UI:GetEvolvingShipNodeAddMaxEvolutionPoints( node.name )
    			else
    				sys.log( "UI:GetEvolvingShipMaxEvolutionPoints()[ERROR]: cannot find node with id %d", nodeId )
    			end

    		end

    	end

		return evolutionPoints

	end

	return fnGetBaseMaxEvolutionPoints() + fnGetAddMaxEvolutionPoints()

end


-- слоты, которые есть в данный момент (это дефолтные + слоты из активированных нодов)
function UI:GetEvolvingShipSlotsMask( shipItem )

	local mask = u64( 0 )

	if type( shipItem ) ~= "table" then
		sys.log( "UI:GetEvolvingShipSlotsMask()[ERROR]: invalid type of the 1-st parameter (\"shipItem\"); \"table\" expected, got \"%s\"", type( shipItem ) )
		return mask
	end

	if not UI:IsShipEvolving( shipItem.defName ) then
		sys.log( "UI:GetEvolvingShipSlotsMask()[ERROR]: ship \"%s\" is not evolving", tostring( shipItem.defName ) )
		return mask
	end

	local defaultMask	= self:GetEvolvingShipDefaultSlotsMask( shipItem.defName )
	local evolvedMask	= shipItem.evolvedModuleSlots or u64( 0 )

	mask = UI:BitBorU64( defaultMask, evolvedMask )

	return mask

end


-- слоты, которые есть всегда
function UI:GetEvolvingShipDefaultSlotsMask( defName )

	local mask = u64( 0 )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipDefaultSlotsMask()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return mask
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipDefaultSlotsMask()[ERROR]: ship \"%s\" is not evolving", defName )
		return mask
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetEvolvingShipDefaultSlotsMask()[ERROR]: cannot find \"_G.Def[\"%s\"]\"", defName )
		return mask
	end

	if def.default_slot_mask == nil then
		return mask
	end

	if type( def.default_slot_mask ) == "userdata" then	-- u64 SC-112068
		mask = def.default_slot_mask
	else
		sys.log( "UI:GetEvolvingShipEvolutionCost()[ERROR]: invalid type of _G.Def[\"%s\"].default_slot_mask; \"userdata\" or \"nil\" expected, got \"%s\"", defName, type( def.default_slot_mask ) )
	end

	return mask

end


-- слоты, которые по максимуму могут быть в корабле (это дефолтные + все слоты из нодов)
function UI:GetEvolvingShipAllPossibleSlotsMask( defName )

	local mask = u64( 0 )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipAllPossibleSlotsMask()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return mask
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipAllPossibleSlotsMask()[ERROR]: ship \"%s\" is not evolving", defName )
		return mask
	end

	local defaultMask	= self:GetEvolvingShipDefaultSlotsMask( defName )
	local evolvableMask	= self:GetEvolvingShipAllEvolvableSlotsMask( defName )

	mask = UI:BitBorU64( defaultMask, evolvableMask )

	return mask


end


-- все слоты, которые можно получить через ноды
function UI:GetEvolvingShipAllEvolvableSlotsMask( defName )

	local mask = u64( 0 )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipAllEvolvableSlotsMask()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return mask
	end

	if not UI:IsShipEvolving( defName ) then
		sys.log( "UI:GetEvolvingShipAllEvolvableSlotsMask()[ERROR]: ship \"%s\" is not evolving", defName )
		return mask
	end

	local nodes = UI:GetEvolvingShipNodes( defName )

	for nodeName, nodeInfo in pairs( nodes ) do

		if UI:IsEvolvingShipNodeOfTypeShipSlot( nodeName ) then

			local slotId = UI:GetEvolvingShipNodeShipSlot( nodeName )
			if slotId ~= -1 then
				mask = UI:BitSetU64( mask, slotId )
			else
				sys.log( "UI:GetEvolvingShipAllEvolvableSlotsMask()[ERROR]: cannot find ship slot id for node \"%s\"", nodeName )
			end

		end

	end

	return mask

end


