-- shipDefName может быть любой из цепочки развития
function UI:CalcEvolvingShipEvolutionPointsFromNodesMask( shipDefName, nodesMask )

	local evolutionPoints = 0

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:CalcEvolvingShipEvolutionPointsFromNodesMask()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return evolutionPoints
	end

	if type( nodesMask ) ~= "userdata" then
		sys.log( "UI:CalcEvolvingShipEvolutionPointsFromNodesMask()[ERROR]: invalid type of the 2-nd parameter (\"nodesMask\"); \"userdata\" expected, got \"%s\"", type( nodesMask ) )
		return evolutionPoints
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:CalcEvolvingShipEvolutionPointsFromNodesMask()[ERROR]: ship \"%s\" is not evolving", shipDefName )
		return evolutionPoints
	end

	if nodesMask == u64( 0 ) then
		return evolutionPoints
	end

	local nodes = UI:GetEvolvingShipNodes( shipDefName )

	local nodesById = {}

	for nodeName, node in pairs( nodes ) do
		nodesById[ UI:GetEvolvingShipNodeId( node.name ) ] = node
	end

	local MAX_ID = 63
	for nodeId = 0, MAX_ID do

		if UI:BitTstU64( nodesMask, nodeId ) then

			local node = nodesById[ nodeId ]
			if node then
				evolutionPoints = evolutionPoints + UI:GetEvolvingShipNodeEvolutionPoints( node.name )
			else
				sys.log( "UI:CalcEvolvingShipEvolutionPointsFromNodesMask()[ERROR]: cannot find node with id %d", nodeId )
			end

		end

	end

	return evolutionPoints

end


-- shipDefName может быть любой из цепочки развития
function UI:CalcEvolvingShipDefNameFromEvolutionPoints( shipDefName, evolutionPoints )

	local dstShipDefName = ""

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:CalcEvolvingShipDefNameFromEvolutionPoints()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return dstShipDefName
	end

	if type( evolutionPoints ) ~= "number" then
		sys.log( "UI:GetEvolvingShipAllEvolvableSlotsMask()[ERROR]: invalid type of the 2-nd parameter (\"evolutionPoints\"); \"number\" expected, got \"%s\"", type( evolutionPoints ) )
		return dstShipDefName
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:GetEvolvingShipAllEvolvableSlotsMask()[ERROR]: ship \"%s\" is not evolving", shipDefName )
		return dstShipDefName
	end

	local baseShipDefName = UI:GetEvolvingShipBaseDef( shipDefName )

	if baseShipDefName == "" then
		sys.log( "UI:GetEvolvingShipAllEvolvableSlotsMask()[ERROR]: cannot find base def for %s", shipDefName )
		return dstShipDefName
	end

	local defName = baseShipDefName
	while defName ~= "" do

		if UI:GetEvolvingShipEvolutionCost( defName ) > evolutionPoints then
			break
		end

		dstShipDefName = defName

		defName = UI:GetEvolvingShipNextDef( defName )

	end

	if dstShipDefName == "" then
		sys.log( "UI:CalcEvolvingShipDefNameFromEvolutionPoints()[ERROR]: cannot find dst def for ship %s and evolution points %d", shipDefName, evolutionPoints )
	end

	return dstShipDefName

end


-- shipDefName может быть любой из цепочки развития
function UI:CalcEvolvingShipDefNameFromNodesMask( shipDefName, nodesMask )

	local dstShipDefName = ""

	local evolutionPoints = 0

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:CalcEvolvingShipDefNameFromNodesMask()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return dstShipDefName
	end

	if type( nodesMask ) ~= "userdata" then
		sys.log( "UI:CalcEvolvingShipDefNameFromNodesMask()[ERROR]: invalid type of the 2-nd parameter (\"nodesMask\"); \"userdata\" expected, got \"%s\"", type( nodesMask ) )
		return dstShipDefName
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:CalcEvolvingShipDefNameFromNodesMask()[ERROR]: ship \"%s\" is not evolving", shipDefName )
		return dstShipDefName
	end

	local evolutionPoints = UI:CalcEvolvingShipEvolutionPointsFromNodesMask( shipDefName, nodesMask )
	dstShipDefName = UI:CalcEvolvingShipDefNameFromEvolutionPoints( shipDefName, evolutionPoints )

	return dstShipDefName

end


-- shipDefName может быть любой из цепочки развития
function UI:CalcEvolvingShipRankFromNodesMask( shipDefName, nodesMask )

	local rank = -1

	local dstShipDefName = UI:CalcEvolvingShipDefNameFromNodesMask( shipDefName, nodesMask )
	if dstShipDefName ~= "" then
		rank = UI:GetShipRank( dstShipDefName )
	end

	return rank

end


--
function UI:GetEvolvingShipNodeByName( nodeName )

	local nodeInfo = nil

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeByName()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return nodeInfo
	end

	if type( _G.VesselProgress ) ~= "table" then
		sys.log( "UI:GetEvolvingShipNodeByName()[ERROR]: invalid type of _G.VesselProgress; \"table\" expected, got \"%s\"", type( _G.VesselProgress ) )
		return nodeInfo
	end

	nodeInfo = _G.VesselProgress[ nodeName ]
	if type( nodeInfo ) ~= "table" then
		sys.log( "UI:GetEvolvingShipNodeByName()[ERROR]: invalid type of _G.VesselProgress[\"%s\"]; \"table\" expected, got \"%s\"", nodeName, type( nodeInfo ) )
		nodeInfo = nil
	end

	return nodeInfo

end


--
function UI:GetEvolvingShipNodeNameById( nodeId, shipDefName )

	local nodeName = ""

	if type( nodeId ) ~= "number" then
		sys.log( "UI:GetEvolvingShipNodeByName()[ERROR]: invalid type of the 1-st parameter (\"nodeId\"); \"number\" expected, got \"%s\"", type( nodeId ) )
		return nodeName
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeByName()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return nodeName
	end

	local nodes = UI:GetEvolvingShipNodes( shipDefName )

	for _nodeName, node in pairs( nodes ) do

		if UI:GetEvolvingShipNodeId( _nodeName ) == nodeId then
			nodeName = _nodeName
			break
		end

	end

	return nodeName

end


--
function UI:EvolvingShipNode2Str( nodeName, shipDefName, chosenNodesMask, baseColor )

	local str = "unknown"

	if type( nodeName ) ~= "string" then
		sys.log( "UI:EvolvingShipNode2Str()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return str
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:EvolvingShipNode2Str()[ERROR]: invalid type of the 2-nd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return str
	end

	if chosenNodesMask ~= nil then
    	if type( chosenNodesMask ) ~= "userdata" then
    		sys.log( "UI:EvolvingShipNode2Str()[ERROR]: invalid type of the 3-rd parameter (\"chosenNodesMask\"); \"userdata\" or \"nil\" expected, got \"%s\"", type( chosenNodesMask ) )
    		return str
    	end
	end

	if baseColor ~= nil then
    	if type( baseColor ) ~= "number" then
    		sys.log( "UI:EvolvingShipNode2Str()[ERROR]: invalid type of the 4-th parameter (\"baseColor\"); \"number\" expected, got \"%s\"", type( baseColor ) )
    		baseColor = nil
    	end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:EvolvingShipNode2Str()[ERROR]: cannot find node \"%s\"", nodeName )
		return str
	end

	str = nodeName

	if UI.showDefNames then
		return str
	end

	if UI:IsEvolvingShipNodeOfTypeSpecModule( nodeName ) then

		local specModuleDefName = UI:GetEvolvingShipNodeSpecModule( nodeName, shipDefName, chosenNodesMask )
		str = UI:GetEntityLocalizedNameByDef( specModuleDefName, true, false, nil, nil )

	elseif UI:IsEvolvingShipNodeOfTypeBlueprint( nodeName ) then

		local blueprintDefName = UI:GetEvolvingShipNodeBlueprint( nodeName )
		str = UI:GetEntityLocalizedNameByDef( blueprintDefName, true, false, nil, nil )

	else

		local strName = ""

    	if type( nodeInfo.ui_name ) == "string" then
    		strName = nodeInfo.ui_name
    	else
    		sys.log( "UI:EvolvingShipNode2Str()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].ui_name; \"string\" expected, got \"%s\"", nodeName, type( nodeInfo.ui_name ) )
    	end

    	if strName ~= "" then
    		str = UI:GetStringByName( strName )
    	end

	end

	return str

end


-- (bActive нужен только если bLearned=true )
function UI:GetEvolvingShipNodeIco( nodeName, bLearned, bActive )

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeIco()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return UI:GetTex( "NoData" )
	end

	if type( bLearned ) ~= "boolean" then
		sys.log( "UI:GetEvolvingShipNodeIco()[ERROR]: invalid type of the 2-nd parameter (\"bLearned\"); \"boolean\" expected, got \"%s\"", type( bLearned ) )
		return UI:GetTex( "NoData" )
	end

	if bLearned then
    	if type( bActive ) ~= "boolean" then
    		sys.log( "UI:GetEvolvingShipNodeIco()[ERROR]: invalid type of the 3-rd parameter (\"bActive\"); \"boolean\" expected, got \"%s\"", type( bActive ) )
    		return UI:GetTex( "NoData" )
    	end
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:GetEvolvingShipNodeIco()[ERROR]: cannot find node \"%s\"", nodeName )
		return UI:GetTex( "NoData" )
	end

	local hTex = UI.INVALID_RESOURCE_HANDLE

	local texName = nodeInfo.ico

	if type( texName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeIco()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].ico; \"string\" expected, got \"%s\"", nodeName, type( texName ) )
		texName = ""
	end

	if texName ~= "" then

		local postfix = ""

		if bLearned then
			postfix = bActive and "active" or "inactive"
		else
			postfix = "locked"
		end

		texName = string.format( "%s_%s", texName, postfix )

	end

	if texName ~= "" then
		hTex = UI:GetTex( texName )
	else
		hTex = UI:GetTex( "NoData" )
	end

	return hTex

end


--
function UI:GetEvolvingShipNodeDesc( nodeName, shipDefName, chosenNodesMask, substColor, baseColor, bGroupInfo, bAddMaxEvolutionInfo )

	local desc = "error"

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return desc
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of the 2-nd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return desc
	end

	if chosenNodesMask ~= nil then
    	if type( chosenNodesMask ) ~= "userdata" then
    		sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of the 3-rd parameter (\"chosenNodesMask\"); \"userdata\" or \"nil\" expected, got \"%s\"", type( chosenNodesMask ) )
    		return desc
    	end
	end

	if substColor ~= nil then
		if type( substColor ) ~= "number" then
			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of the 4-th parameter (\"substColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( substColor ) )
			substColor = nil
		end
	end

	if substColor == nil then
		substColor = UI.TEXT_SEL_COLOR
	end

	if baseColor ~= nil then
		if type( baseColor ) ~= "number" then
			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of the 5-th parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
		end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if bGroupInfo ~= nil then
		if type( bGroupInfo ) ~= "boolean" then
			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of the 6-th parameter (\"bGroupInfo\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bGroupInfo ) )
			bGroupInfo = nil
		end
	end

	if bGroupInfo == nil then
		bGroupInfo = true
	end

	if bAddMaxEvolutionInfo ~= nil then
		if type( bAddMaxEvolutionInfo ) ~= "boolean" then
			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of the 7-th parameter (\"bAddMaxEvolutionInfo\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bAddMaxEvolutionInfo ) )
			bAddMaxEvolutionInfo = nil
		end
	end

	if bAddMaxEvolutionInfo == nil then
		bAddMaxEvolutionInfo = true
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: cannot find node \"%s\"", nodeName )
		return desc
	end


	-- бонусы

	if UI:IsEvolvingShipNodeOfTypeShipBonus( nodeName ) then

		local strBonuses = ""

		local bonuses = UI:GetEvolvingShipNodeShipBonuses( nodeName )
		if next( bonuses ) then

    		local shipDescParams = UI:GetShipDescParams( shipDefName )

    		local bonusesNamesArr = {}

    		for bonusName, bonusVal in pairs( bonuses ) do

    			if type( bonusName ) == "string" then
    				table.insert( bonusesNamesArr, bonusName )
    			else
    				sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of key in \"special_grade\" table for node %s; \"string\" expected, got \"%s\"", nodeName, type( bonusName ) )
    			end

    		end

    		table.sort( bonusesNamesArr )


			local strBonusesItems = ""

    		for bonusIdx, bonusName in ipairs( bonusesNamesArr ) do

    			local shipDescParamInfo = nil

    			for paramIdx, paramInfo in pairs( shipDescParams ) do
    				if paramInfo.valField == bonusName then
    					shipDescParamInfo = paramInfo
    					break
    				end
    			end

    			if shipDescParamInfo then

        			local bonusData =
        			{
        				paramInfo		= shipDescParamInfo,
        				vals			= UI:GetParamVals( nodeName, shipDescParamInfo, UI.paramSrcTypes.SHIP_NODE, nil, false, nil, nil, true ),
        				synergyLevel	= -1,
        			}

        			local strBonusItem = UI:ShipDescParam2Str( bonusData, baseColor, substColor, shipDefName, -1, false )

    				if strBonusItem == "" then
						sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: cannot make string for bonus \"%s\" for node \"%s\"", bonusName, nodeName )
						strBonusItem = "error"
    				end

					strBonusItem = string.format( "- %s", strBonusItem )

    				strBonusesItems = string.format( "%s%s%s", strBonusesItems, strBonusesItems ~= "" and "|" or "", strBonusItem )

    			else
    				sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: cannot find ship desc param to show bonus %s for node %s", bonusName, nodeName )
    			end

    		end

			local strBonusesLabel = UI:SubstituteValLocalizedByStringId( "shipNodeTooltip_bonuses", #bonusesNamesArr, "bonuses", "" )	-- в эту строку цифра никакая не подставляется, просто меняется форма слова "бонусы" в зависимости от того, один бонус или несколько
			strBonuses = string.format( "%s:|%s", strBonusesLabel, strBonusesItems )

		else
			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: no bonuses found for node \"%s\"", nodeName )
		end


		desc = strBonuses


	-- спецмодуль

	elseif UI:IsEvolvingShipNodeOfTypeSpecModule( nodeName ) then

		local specModuleDefName = UI:GetEvolvingShipNodeSpecModule( nodeName, shipDefName, chosenNodesMask )

		local strSpecModuleLocalizedName = UI:GetEntityLocalizedNameByDef( specModuleDefName, true, false, nil, nil )
		strSpecModuleLocalizedName = string.format( "%s%s", strSpecModuleLocalizedName, UI:Color2Str( baseColor ) )

		local strSpecModule = UI:GetStringByName( "shipNodeTooltip_specModule" )

		local numSubst = 0
		strSpecModule, numSubst = string.gsub( strSpecModule, "%$module%$", strSpecModuleLocalizedName )

		if numSubst == 0 then
			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: cannot find placeholder \"$module$\" in string \"shipNodeTooltip_specModule\"" )
			strSpecModule = string.format( "[INVALID STRING] Spec module %s. Press [ALT] to show", strSpecModuleLocalizedName )
		end

		desc = strSpecModule


	-- чертеж

	elseif UI:IsEvolvingShipNodeOfTypeBlueprint( nodeName ) then

		local blueprintDefName = UI:GetEvolvingShipNodeBlueprint( nodeName )

		local strBlueprintLocalizedName = UI:GetEntityLocalizedNameByDef( blueprintDefName, true, false, nil, nil )
		strBlueprintLocalizedName = string.format( "%s%s", strBlueprintLocalizedName, UI:Color2Str( baseColor ) )

		local strBlueprint = UI:GetStringByName( "shipNodeTooltip_blueprint" )

		local numSubst = 0
		strBlueprint, numSubst = string.gsub( strBlueprint, "%$blueprint%$", strBlueprintLocalizedName )

		if numSubst == 0 then
			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: cannot find placeholder \"$blueprint$\" in string \"shipNodeTooltip_blueprint\"" )
			strBlueprint = string.format( "[INVALID STRING] Blueprint %s. Press [ALT] to show", strBlueprintLocalizedName )
		end

		desc = strBlueprint


	-- обычная нода

	else

    	local strName = ""

    	if type( nodeInfo.ui_desc ) == "string" then
    		strName = nodeInfo.ui_desc
    	else
    		sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].ui_desc; \"string\" expected, got \"%s\"", nodeName, type( nodeInfo.ui_desc ) )
    	end

    	if strName ~= "" then

        	desc = UI:GetStringByName( strName )

        	local srcInfo =
        	{
        		defName		= nodeName,
        		dataType	= UI.paramSrcTypes.SHIP_NODE,
        	}

        	local descriptionParams = UI:GetEvolvingShipNodeDescParams( nodeName )

        	desc = UI:FillDescWithParams( srcInfo, nil, desc, descriptionParams, substColor, baseColor, true )

    	else
    		sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: cannot find desc for \"%s\"", nodeName )
    	end

	end


	-- сведения о группе нодов

	if bGroupInfo then

    	local group = UI:GetEvolvingShipNodeGroup( nodeName )
    	if group ~= -1 then

    		local groupDesc = UI:GetStringByName( "shipNodeTooltip_groupDesc" )

    		local groupName = UI:EvolvingShipNodeGroup2Str( group )
    		groupName = string.format( "%s%s%s", UI:Color2Str( substColor ), groupName, UI:Color2Str( baseColor ) )

    		local numSubst = 0
    		groupDesc, numSubst = string.gsub( groupDesc, "%$name%$", groupName )

    		if numSubst == 0 then
    			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: cannot find placeholder \"$name$\" in string \"shipNodeTooltip_groupDesc\"" )
    			groupDesc = string.format( "[INVALID STRING] Only one node can be active at a time in the group %s", groupName )
    		end

    		groupDesc = string.format( "%s%s", UI:Color2Str( baseColor ), groupDesc )

    		desc = string.format( "%s%s%s", desc, desc ~= "" and "||" or "", groupDesc )

    	end

	end


	-- сведения о добавлении к максимальной эволюции (только для неизученных нодов)

	if bAddMaxEvolutionInfo then

    	local bUnlocked = false

    	local shipItem = UI:GetEvolvingShipItem( shipDefName )
    	if shipItem then

        	local unlockedNodesMask = UI:GetEvolvingShipUnlockedNodesMask( shipItem.vid )

        	local nodeId = UI:GetEvolvingShipNodeId( nodeName )
        	if nodeId ~= -1 then

        		if UI:BitTstU64( unlockedNodesMask, nodeId ) then
    				bUnlocked = true
    			end

        	else
            	sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: invalid nodeId for node \"%s\"", nodeName )
        	end

    	end

    	if not bUnlocked then

    		local addMaxEvolution = UI:GetEvolvingShipNodeAddMaxEvolutionPoints( nodeName )
    		if addMaxEvolution > 0 then

        		local strAddMaxEvolutionVal = UI:Num2StrSeparatedBy3( addMaxEvolution )

        		local strAddMaxEvolution = UI:GetStringByName( "shipNodeTooltip_addMaxEvolution" )

        		local numSubst = 0
        		strAddMaxEvolution, numSubst = string.gsub( strAddMaxEvolution, "%$val%$", strAddMaxEvolutionVal )

        		if numSubst == 0 then
        			sys.log( "UI:GetEvolvingShipNodeDesc()[ERROR]: cannot find placeholder \"$val$\" in string \"shipNodeTooltip_addMaxEvolution\"" )
        			strAddMaxEvolution = string.format( "[INVALID STRING] Max evolution add: %s", strAddMaxEvolutionVal )
        		end

            	desc = string.format( "%s%s%s", desc, desc ~= "" and "||" or "", strAddMaxEvolution )

    		end

    	end

	end


	return desc

end


--
function UI:GetEvolvingShipNodeDescParams( nodeName )

	local params = {}

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeDescParams()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return params
	end

	if type( _G.NodeTooltip ) ~= "table" then
		sys.log( "UI:GetEvolvingShipNodeDescParams()[ERROR]: invalid type of _G.NodeTooltip; \"table\" expected, got \"%s\"", type( _G.NodeTooltip ) )
		return params
	end

	params = _G.NodeTooltip

	return params

end


--
function UI:EvolvingShipNodeGroup2Str( group )

	local str = "unknown"

	if type( group ) ~= "number" then
		sys.log( "UI:EvolvingShipNodeGroup2Str()[ERROR]: invalid type of the 1-st parameter (\"group\"); \"number\" expected, got \"%s\"", type( group ) )
		return str
	end

	local strName = string.format( "node_group_%d", group )
	str = UI:GetStringByName( strName )

	return str

end


--
function UI:GetEvolvingShipNodeId( nodeName )

	local nodeId = -1

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeId()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return nodeId
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:GetEvolvingShipNodeId()[ERROR]: cannot find node \"%s\"", nodeName )
		return nodeId
	end

	if type( nodeInfo.nodeId ) == "number" then

		local MAX_ID = 63

		if nodeInfo.nodeId >= 0 and nodeInfo.nodeId <= MAX_ID then
			nodeId = nodeInfo.nodeId
		else
			sys.log( "UI:GetEvolvingShipNodeId()[ERROR]: invalid value %d of node \"%s\"; from 0 to %d expected", nodeInfo.nodeId, nodeName, MAX_ID )
		end

	else
		sys.log( "UI:GetEvolvingShipNodeId()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].nodeId; \"number\" expected, got \"%s\"", nodeName, type( nodeInfo.nodeId ) )
	end

	return nodeId

end


-- очки эволюции, которые нод при изучении добавит к эволюции корабля
function UI:GetEvolvingShipNodeEvolutionPoints( nodeName )

	local evolutionPoints = 0

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeEvolutionPoints()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return evolutionPoints
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:GetEvolvingShipNodeEvolutionPoints()[ERROR]: cannot find node \"%s\"", nodeName )
		return evolutionPoints
	end

	if nodeInfo.evolution ~= nil then
    	if type( nodeInfo.evolution ) == "number" then
    		evolutionPoints = nodeInfo.evolution
    	else
    		sys.log( "UI:GetEvolvingShipNodeEvolutionPoints()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].evolution; \"number\" or \"nil\" expected, got \"%s\"", nodeName, type( nodeInfo.evolution ) )
    	end
	end

	return evolutionPoints

end


-- очки эволюции, которые нод при изучении добавит к максимальной эволюции корабля (evolution_max в дефе корабля)
