    	else
    		sys.log( "UI:GetEvolvingShipNodeAddMaxEvolutionPoints()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].evolution_max_add; \"number\" or \"nil\" expected, got \"%s\"", nodeName, type( nodeInfo.evolution_max_add ) )
    	end
	end

	return evolutionPoints

end


--
function UI:IsEvolvingShipNodeNonActivatable( nodeName )

	local bForcedActive = false

	if type( nodeName ) ~= "string" then
		sys.log( "UI:IsEvolvingShipNodeNonActivatable()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return bForcedActive
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:IsEvolvingShipNodeNonActivatable()[ERROR]: cannot find node \"%s\"", nodeName )
		return bForcedActive
	end

	if nodeInfo.can_be_activated ~= nil then

    	if type( nodeInfo.can_be_activated ) == "boolean" then
			bForcedActive = not nodeInfo.can_be_activated
    	else
    		sys.log( "UI:IsEvolvingShipNodeNonActivatable()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].can_be_activated; \"boolean\" or \"nil\" expected, got \"%s\"", nodeName, type( nodeInfo.can_be_activated ) )
    	end

	end

	return bForcedActive

end


