--
function UI:GetEvolvingShipNodePrice( nodeName, shipDefName )

	local prices = {}

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return prices
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of the 2-nd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return prices
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: cannot find node \"%s\"", nodeName )
		return prices
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: ship \"%s\" is not evolving", shipDefName )
		return prices
	end

	local pricesTable = {}
	local pricesTablePath = ""	-- используется в возможных записях в лог об ошибках

	if UI:IsEvolvingShipNodePriceInNode( nodeName ) then

		pricesTable = nodeInfo
		pricesTablePath = string.format( "_G.VesselProgress[\"%s\"]", nodeName )

	else

		local numUnlockedNodes = 0

		local shipItem = UI:GetEvolvingShipItem( shipDefName )
		if shipItem then

        	local nodes = UI:GetEvolvingShipNodes( shipDefName )

        	local nodesById = {}

        	for nodeName, node in pairs( nodes ) do

        		local nodeId = UI:GetEvolvingShipNodeId( nodeName )
        		if nodeId ~= -1 then
        			nodesById[ nodeId ] = node
        		else
        			sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid nodeId for node \"%s\"", nodeName )
        		end

        	end

			local unlockedNodesMask = UI:GetEvolvingShipUnlockedNodesMask( shipItem.vid )

        	local MAX_ID = 63

        	for nodeId = 0, MAX_ID do

        		if UI:BitTstU64( unlockedNodesMask, nodeId ) then

        			local node = nodesById[ nodeId ]
        			if node then

						if not UI:IsEvolvingShipNodePriceInNode( node.name ) then
							numUnlockedNodes = numUnlockedNodes + 1
						end

					end

				end

			end

		end

		local baseShipDefName = UI:GetEvolvingShipBaseDef( shipDefName )
		if baseShipDefName ~= "" then

    		local shipDef = UI:GetDef( baseShipDefName )
    		if shipDef then

    			if type( shipDef.node_prices ) == "table" then

					local pricesIdx = numUnlockedNodes + 1

					if type( shipDef.node_prices[ pricesIdx ] ) == "table" then
						pricesTable = shipDef.node_prices[ pricesIdx ]
						pricesTablePath = string.format( "_G.Def[\"%s\"].node_prices[%d];", baseShipDefName, pricesIdx )
					else
						sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of _G.Def[\"%s\"].node_prices[%d]; \"table\" expected, got \"%s\"", baseShipDefName, pricesIdx, type( shipDef.node_prices[ pricesIdx ] ) )
					end

				else
					sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of _G.Def[\"%s\"].node_prices; \"table\" expected, got \"%s\"", baseShipDefName, type( shipDef.node_prices ) )
				end

    		else
    			sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: cannot find _G.Def[\"%s\"]", baseShipDefName )
    		end

		else
			sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: cannot find base def in evolving chain for ship %s", shipDefName )
		end

	end


	-- кредиты

	if pricesTable.credits ~= nil then

		if type( pricesTable.credits ) == "number" then

			if pricesTable.credits > 0 then

				local creditsPriceInfo =
				{
            		priceType	= UI.shipNodePriceTypes.CREDITS,
        			val			= pricesTable.credits,
				}

				table.insert( prices, creditsPriceInfo )

			end

		else
			sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of %s.credits; \"number\" or \"nil\" expected, got \"%s\"", pricesTablePath, type( pricesTable.credits ) )
		end

	end


	-- токены (иридиум)

	if pricesTable.tokens ~= nil then

		if type( pricesTable.tokens ) == "number" then

			if pricesTable.tokens > 0 then

				local tokensPriceInfo =
				{
            		priceType	= UI.shipNodePriceTypes.TOKENS,
        			val			= pricesTable.tokens,
				}

				table.insert( prices, tokensPriceInfo )

			end

		else
			sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of %s.tokens; \"number\" or \"nil\" expected, got \"%s\"", pricesTablePath, type( pricesTable.tokens ) )
		end

	end


	-- синергия

	if pricesTable.exp ~= nil then

		if type( pricesTable.exp ) == "number" then

			if pricesTable.exp > 0 then

				local synergyPriceInfo =
				{
            		priceType	= UI.shipNodePriceTypes.SYNERGY,
        			val			= pricesTable.exp,
				}

				table.insert( prices, synergyPriceInfo )

			end

		else
			sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of %s.exp; \"number\" or \"nil\" expected, got \"%s\"", pricesTablePath, type( pricesTable.exp ) )
		end

	end


	-- ресурсы

	if pricesTable.resources ~= nil then

		if type( pricesTable.resources ) == "table" then

			for resourceIdx, resourceInfo in ipairs( pricesTable.resources ) do

				if type( resourceInfo ) == "table" then

        			local defName	= ""
        			local count		= 0

        			if type( resourceInfo[ 1 ] ) == "string" then
        				defName = resourceInfo[ 1 ]
        			else
        				sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of %s.resources[%d][1]; \"string\" expected, got \"%s\"", pricesTablePath, resourceIdx, type( resourceInfo[ 1 ] ) )
        			end

        			if type( resourceInfo[ 2 ] ) == "number" then
        				count = resourceInfo[ 2 ]
        			else
        				sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of %s.resources[%d][2]; \"number\" expected, got \"%s\"", pricesTablePath, resourceIdx, type( resourceInfo[ 2 ] ) )
        			end

        			if defName ~= "" then

        				local itemPriceInfo =
        				{
		            		priceType	= UI.shipNodePriceTypes.ITEM,
        					defName		= defName,
        					count		= count,
        				}

        				table.insert( prices, itemPriceInfo )

        			end

				else
					sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of %s.resources[%d]; \"table\" expected, got \"%s\"", pricesTablePath, resourceIdx, type( pricesTable.resources ) )
				end

			end

		else
			sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of %s.resources; \"table\" or \"nil\" expected, got \"%s\"", pricesTablePath, type( pricesTable.resources ) )
		end

	end

	return prices

end


--
function UI:IsEvolvingShipNodePriceInNode( nodeName )

	local bPriceInNode = false

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodePrice()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return bPriceInNode
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:IsEvolvingShipNodePriceInNode()[ERROR]: cannot find node \"%s\"", nodeName )
		return bPriceInNode
	end

	if nodeInfo.static_price ~= nil then

		if type( nodeInfo.static_price ) == "boolean" then
			bPriceInNode = nodeInfo.static_price
		else
			sys.log( "UI:IsEvolvingShipNodePriceInNode()[ERROR]: invalid type of field \"static_price\" in node \"%s\", \"boolean\" expected, got \"%s\"", nodeName, type( nodeInfo.static_price ) )
		end

	end

	return bPriceInNode

end


--
function UI:GetEvolvingShipNodeRequiredQuests( nodeName )

	local quests = {}

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeRequiredQuests()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return quests
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:GetEvolvingShipNodeRequiredQuests()[ERROR]: cannot find node \"%s\"", nodeName )
		return quests
	end

	if nodeInfo.required_quests == nil then
		return quests
	end

	if type( nodeInfo.required_quests ) ~= "table" then
		sys.log( "UI:GetEvolvingShipNodeBudgets()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].required_quests; \"table\" or \"nil\" expected, got \"%s\"", nodeName, type( nodeInfo.required_quests ) )
		return quests
	end

	local bValidFormat = true

	for idx, questId in pairs( nodeInfo.required_quests ) do
		if type( idx ) ~= "number" or type( questId ) ~= "number" then
			sys.log( "UI:GetEvolvingShipNodeBudgets()[ERROR]: invalid format of table _G.VesselProgress[\"%s\"].required_quests; <number>=<number> expected, got <%s>=<%s>", nodeName, type( idx ), type( questId ) )
			bValidFormat = false
			break
		end
	end

	if bValidFormat then
		quests = UI:CopyTable2( nodeInfo.required_quests )
	end

	table.sort( quests )

	return quests

end


--
function UI:GetEvolvingShipNodeCoords( nodeName )

	local circle	= -1
	local angle		= 0

	local resourceItems = {}

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeCoords()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return circle, angle
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:GetEvolvingShipNodeCoords()[ERROR]: cannot find node \"%s\"", nodeName )
		return circle, angle
	end

	if type( nodeInfo.ui_layer ) == "number" then

		local MAX_CIRCLE = 3

		if nodeInfo.ui_layer >= 1 and nodeInfo.ui_layer <= MAX_CIRCLE then
			circle = nodeInfo.ui_layer
		else
			sys.log( "UI:GetEvolvingShipNodeCoords()[ERROR]: invalid value of _G.VesselProgress[\"%s\"].ui_layer; from 1 to %d expected, got %d", nodeName, MAX_CIRCLE, nodeInfo.ui_layer )
		end

	else
		sys.log( "UI:GetEvolvingShipNodeCoords()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].ui_layer; \"number\" expected, got \"%s\"", nodeName, type( nodeInfo.ui_layer ) )
	end

	if circle ~= -1 then

    	if type( nodeInfo.ui_angle ) == "number" then
    		angle = math.rad( -nodeInfo.ui_angle )		-- в дефе нода положительные углы считаются по часовой стрелке, а стандартное направление - против часовой, поэтому минус
    	else
    		sys.log( "UI:GetEvolvingShipNodeCoords()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].ui_angle; \"number\" expected, got \"%s\"", nodeName, type( nodeInfo.ui_angle ) )
    	end

	end

	return circle, angle

end


--
function UI:GetEvolvingShipNodeShipVariants( nodeName )

	local shipVariants = {}

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeShipVariants()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return shipVariants
	end

	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
	if not nodeInfo then
		sys.log( "UI:GetEvolvingShipNodeShipVariants()[ERROR]: cannot find node \"%s\"", nodeName )
		return shipVariants
	end

	if nodeInfo.ship_variants == nil then
		return shipVariants
	end

	if type( nodeInfo.ship_variants ) == "table" then

		for mainShipDefName, altShipDefName in pairs( nodeInfo.ship_variants ) do

			if type( mainShipDefName ) == "string" and type( altShipDefName ) == "string" then
				shipVariants[ mainShipDefName ] = altShipDefName
			else
				sys.log( "UI:GetEvolvingShipNodeShipVariants()[ERROR]: invalid format of _G.VesselProgress[\"%s\"].ship_variants; <string>=<string> expected, got <%s>=<%s>", nodeName, type( mainShipDefName ), type( altShipDefName ) )
			end

		end

	else
		sys.log( "UI:GetEvolvingShipNodeShipVariants()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].ship_variants; \"table\" or \"nil\" expected, got \"%s\"", nodeName, type( nodeInfo.ship_variants ) )
	end

	return shipVariants

end


--[[
	defName - деф любого ранга в цепочке эволюции

    возвращает таблицу из записей в формате <nodeName>=<Node>, где Node - это таблица вида:
    {
    	name		= <string>,			-- имя нода
    	nodeInfo	= <table>,			-- таблица нода из _G.VesselProgress
    	rank		= <number>,			-- ранг корабля, к которому относится нод
    	parent		= <table>/<nil>,	-- ссылка на таблицу Node нода-родителя; может быть nil, если нод происходит непосредственно от ранга корабля
    	children	= <table>,			-- список из ссылок на таблицы Node дочерних нодов
    }
]]

function UI:GetEvolvingShipNodes( shipDefName )

	local nodes = {}

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodes()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return nodes
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:GetEvolvingShipNodes()[ERROR]: ship \"%s\" is not evolving", shipDefName )
		return nodes
	end

	local baseDefName = UI:GetEvolvingShipBaseDef( shipDefName )
	if baseDefName == "" then
		sys.log( "UI:GetEvolvingShipNodes()[ERROR]: cannot find evolution chain base def for \"%s\"", shipDefName )
		return nodes
	end


    local function fnMakeEmptyNode()

    	local node =
    	{
    		name		= "",
    		nodeInfo	= nil,
    		rank		= -1,
    		parent		= nil,
    		children	= {},
    	}

    	return node

    end


	local function fnCollectChildNodes( parentNode )

		-- переменные nodes и rankDefName, которые используются в этой функции,
		-- объявлены выше по вызывающему коду, и находятся здесь в области видимости

		if parentNode.nodeInfo.children == nil then
			return
		end

		if type( parentNode.nodeInfo.children ) ~= "table" then
			sys.log( "UI:GetEvolvingShipNodes()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].children; \"table\" or \"nil\" expected, got \"%s\"", parentNode.name, type( parentNode.nodeInfo.children ) )
			return
		end

		for idx, childNodeName in pairs( parentNode.nodeInfo.children ) do

			if type( childNodeName ) == "string" then

				local childNodeInfo = UI:GetEvolvingShipNodeByName( childNodeName )
				if childNodeInfo then

					if nodes[ childNodeName ] == nil then

    					local childNode = fnMakeEmptyNode()

            			childNode.name		= childNodeName
            			childNode.nodeInfo	= childNodeInfo
            			childNode.rank		= parentNode.rank
						childNode.parent	= parentNode

						table.insert( parentNode.children, childNode )

						nodes[ childNodeName ] = childNode

						fnCollectChildNodes( childNode )

					else
						sys.log( "UI:GetEvolvingShipNodes()[ERROR]: duplicate nodes \"%s\" in ship \"%s\"", childNodeName, baseDefName )
					end

				else
					sys.log( "UI:GetEvolvingShipNodes()[ERROR]: cannot find node \"%s\" for ship %s", childNodeName, baseDefName )
				end

			else
				sys.log( "UI:GetEvolvingShipNodes()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].children[%s]; \"string\" expected, got \"%s\"", parentNode.name, tostring( idx ), type( childNodeName ) )
			end

		end

	end


	local function fnCollectRankNodes( rank )

		-- переменная nodes, которая используются в этой функции,
		-- объявлена выше по вызывающему коду, и находится здесь в области видимости

		local rankDefName = UI:GetEvolvingShipDefForRank( baseDefName, rank )
		if rankDefName == "" then
			sys.log( "UI:GetEvolvingShipNodes()[ERROR]: cannot find def for rank %d for ship %s", rank, baseDefName )
			return
		end

		local def = UI:GetDef( rankDefName )
		if not def then
			sys.log( "UI:GetEvolvingShipNodes()[ERROR]: canont find _G.Def[\"%s\"]", rankDefName )
			return
		end

		if def.progress == nil then
			return
		end

		if type( def.progress ) ~= "table" then
			sys.log( "UI:GetEvolvingShipNodes()[ERROR]: invalid type of _G.Def[\"%s\"].progress; \"table\" or \"nil\" expected, got \"%s\"", rankDefName, type( def.progress ) )
			return
		end

		for idx, nodeName in pairs( def.progress ) do

			if type( nodeName ) == "string" then

				local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )
				if nodeInfo then

					if nodes[ nodeName ] == nil then

    					local node = fnMakeEmptyNode()

            			node.name		= nodeName
            			node.nodeInfo	= nodeInfo
            			node.rank		= rank

						nodes[ nodeName ] = node

						fnCollectChildNodes( node )

					else
						sys.log( "UI:GetEvolvingShipNodes()[ERROR]: duplicate nodes \"%s\" in ship \"%s\"", nodeName, rankDefName )
					end

				else
					sys.log( "UI:GetEvolvingShipNodes()[ERROR]: cannot find node \"%s\" for ship %s", nodeName, rankDefName )
				end

			else
				sys.log( "UI:GetEvolvingShipNodes()[ERROR]: invalid type of _G.Def[\"%s\"].progress[%s]; \"string\" expected, got \"%s\"", rankDefName, tostring( idx ), type( nodeName ) )
			end

		end

	end


	for rank = UI:GetEvolvingShipMinRank( baseDefName ), UI:GetEvolvingShipMaxRank( baseDefName ) do
		fnCollectRankNodes( rank )
	end

	return nodes

end


-- defName - деф любого ранга в цепочке эволюции
function UI:GetEvolvingShipNodeParent( nodeName, shipDefName )

	local parentNodeName	= ""
	local rank				= -1

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeParent()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return parentNodeName, rank
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeParent()[ERROR]: invalid type of the 2-nd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return parentNodeName, rank
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:GetEvolvingShipNodeParent()[ERROR]: ship \"%s\" is not evolving", shipDefName )
		return parentNodeName, rank
	end

	local nodes = UI:GetEvolvingShipNodes( shipDefName )

	local node = nodes[ nodeName ]
	if not node then
		sys.log( "UI:GetEvolvingShipNodeParent()[ERROR]: node \"%s\" is not child of ship \"%s\"", nodeName, shipDefName )
		return parentNodeName, rank
	end

	parentNodeName	= node.parent and node.parent.name or ""
	rank			= node.rank

	return parentNodeName, rank

end


--
function UI:IsEvolvingShipNodeUnlocked( nodeName, vid )

	local bUnlocked = false

	if type( nodeName ) ~= "string" then
		sys.log( "UI:IsEvolvingShipNodeUnlocked()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return bUnlocked
	end

	if type( vid ) ~= "userdata" then
		sys.log( "UI:IsEvolvingShipNodeUnlocked()[ERROR]: invalid type of the 2-nd parameter (\"vid\"); \"userdata\" expected, got \"%s\"", type( vid ) )
		return bUnlocked
	end

	if vid == UI.INVALID_U64_ID then
		sys.log( "UI:IsEvolvingShipNodeUnlocked()[ERROR]: invalid vid" )
		return bUnlocked
	end

	local nodeId = UI:GetEvolvingShipNodeId( nodeName )
	if nodeId == -1 then
		sys.log( "UI:IsEvolvingShipNodeUnlocked()[ERROR]: invalid id for node \"%s\"", nodeName )
		return bUnlocked
	end

	local mask = UI:GetEvolvingShipUnlockedNodesMask( vid )
	bUnlocked = UI:BitTstU64( mask, nodeId )

	return bUnlocked

end


--
function UI:IsEvolvingShipNodeActive( nodeName, vid )

	local bActive = false

	if type( nodeName ) ~= "string" then
		sys.log( "UI:IsEvolvingShipNodeActive()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return bActive
	end

	if type( vid ) ~= "userdata" then
		sys.log( "UI:IsEvolvingShipNodeActive()[ERROR]: invalid type of the 2-nd parameter (\"vid\"); \"userdata\" expected, got \"%s\"", type( vid ) )
		return bActive
	end

	if vid == UI.INVALID_U64_ID then
		sys.log( "UI:IsEvolvingShipNodeActive()[ERROR]: invalid vid" )
		return bActive
	end

	local nodeId = UI:GetEvolvingShipNodeId( nodeName )
	if nodeId == -1 then
		sys.log( "UI:IsEvolvingShipNodeActive()[ERROR]: invalid id for node \"%s\"", nodeName )
		return bActive
	end

	local mask = UI:GetEvolvingShipActiveNodesMask( vid )
	bActive = UI:BitTstU64( mask, nodeId )

	return bActive

end


--
function UI:GetEvolvingShipUnlockedRank( shipItem )

	local unlockedRank = -1

	if type( shipItem ) ~= "table" then
		sys.log( "UI:GetEvolvingShipUnlockedRank()[ERROR]: invalid type of the 1-st parameter (\"shipItem\"); \"table\" expected, got \"%s\"", type( shipItem ) )
		return unlockedRank
	end

	if not UI:IsShipEvolving( shipItem.defName ) then
		sys.log( "UI:GetEvolvingShipUnlockedRank()[ERROR]: ship \"%s\" is not evolving", shipItem.defName )
		return unlockedRank
	end

	local baseDefName = UI:GetEvolvingShipBaseDef( shipItem.defName )
	if baseDefName == "" then
		sys.log( "UI:GetEvolvingShipUnlockedRank()[ERROR]: cannot find evolution chain base def for \"%s\"", shipItem.defName )
		return unlockedRank
	end

	local mask = UI:GetEvolvingShipUnlockedNodesMask( shipItem.vid )

	-- из маски получаются очки эволюции

	local evolutionPoints = 0

	local nodes = UI:GetEvolvingShipNodes( shipItem.defName )

	local nodesById = {}

	for nodeName, node in pairs( nodes ) do

		local nodeId = UI:GetEvolvingShipNodeId( nodeName )
		if nodeId ~= -1 then
			nodesById[ nodeId ] = node
		else
			sys.log( "UI:GetEvolvingShipUnlockedRank()[ERROR]: invalid nodeId for node \"%s\"", nodeName )
		end

	end

	local MAX_ID = 63

	for nodeId = 0, MAX_ID do

		if UI:BitTstU64( mask, nodeId ) then

			local node = nodesById[ nodeId ]
			if node then
				evolutionPoints = evolutionPoints + UI:GetEvolvingShipNodeEvolutionPoints( node.name )
			else
				sys.log( "UI:GetEvolvingShipUnlockedRank()[ERROR]: invalid unlocked node - cannot find child node with id %d for ship \"%s\"", nodeId, shipItem.defName )
			end

		end

	end


	-- из очков эволюции получается деф

	local unlockedDefName = ""

	local defName = baseDefName
	while defName ~= "" do

		if UI:GetEvolvingShipEvolutionCost( defName ) > evolutionPoints then
			break
		end

		unlockedDefName = defName

		defName = UI:GetEvolvingShipNextDef( defName )

	end


	-- из дефа получается ранг

	if unlockedDefName ~= "" then
		unlockedRank = UI:GetShipRank( unlockedDefName )
	else
		sys.log( "UI:GetEvolvingShipUnlockedRank()[ERROR]: cannot find unlocked ship def" )
	end

	return unlockedRank

end


--
function UI:GetEvolvingShipSpecModuleFromNodesMask( shipDefName, mask )

	local specModuleDefName = ""

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipSpecModuleFromNodesMask()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return specModuleDefName
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:GetEvolvingShipSpecModuleFromNodesMask()[ERROR]: ship \"%s\" is not evolving", shipDefName )
		return specModuleDefName
	end

	local nodes = UI:GetEvolvingShipNodes( shipDefName )

	local nodeId2Name = {}
	for nodeName, node in pairs( nodes ) do
		local nodeId = UI:GetEvolvingShipNodeId( nodeName )
		nodeId2Name[ nodeId ] = nodeName
	end

	for nodeId = 0, 63 do

		if UI:BitTstU64( mask, nodeId ) then

			local nodeName = nodeId2Name[ nodeId ]
			if nodeName then

				if UI:IsEvolvingShipNodeOfTypeSpecModule( nodeName ) then
					specModuleDefName = UI:GetEvolvingShipNodeSpecModule( nodeName, shipDefName, mask )
					break
				end

			else
				sys.log( "UI:GetEvolvingShipSpecModuleFromNodesMask()[ERROR]: cannot find node name for node id %d for ship %s", nodeId, shipDefName )
			end

		end

	end

	return specModuleDefName

end


--
function UI:GetEvolvingShipSlotsFromNodesMask( shipDefName, mask )

	local slotsMask = u64( 0 )

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipSlotsFromNodesMask()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return slotsMask
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:GetEvolvingShipSlotsFromNodesMask)[ERROR]: ship \"%s\" is not evolving", shipDefName )
		return slotsMask
	end

	local nodes = UI:GetEvolvingShipNodes( shipDefName )

	local nodeId2Name = {}
	for nodeName, node in pairs( nodes ) do
		local nodeId = UI:GetEvolvingShipNodeId( nodeName )
		nodeId2Name[ nodeId ] = nodeName
	end

	for nodeId = 0, 63 do

		if UI:BitTstU64( mask, nodeId ) then

			local nodeName = nodeId2Name[ nodeId ]
			if nodeName then

				if UI:IsEvolvingShipNodeOfTypeShipSlot( nodeName ) then

					local slotId = UI:GetEvolvingShipNodeShipSlot( nodeName )
					if slotId ~= -1 then
						slotsMask = UI:BitSetU64( slotsMask, slotId )
					else
						sys.log( "UI:GetEvolvingShipSlotsFromNodesMask()[ERROR]: invalid slot id for node %s", nodeName )
					end

				end

			else
				sys.log( "UI:GetEvolvingShipSlotsFromNodesMask()[ERROR]: cannot find node name for node id %d for ship %s", nodeId, shipDefName )
			end

		end

	end

	return slotsMask

end


-- возвращает нод, который открывает данный слот корабля

function UI:GetEvolvingShipNodeForShipSlot( shipDefName, slotId )

	local nodeName = ""

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeForShipSlot()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return nodeName
	end

	if type( slotId ) ~= "number" then
		sys.log( "UI:GetEvolvingShipNodeForShipSlot()[ERROR]: invalid type of the 2-nd parameter (\"slotId\"); \"number\" expected, got \"%s\"", type( slotId ) )
		return nodeName
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:GetEvolvingShipNodeForShipSlot()[ERROR]: ship %s is not craftable", shipDefName )
		return nodeName
	end

	if slotId == -1 then
		sys.log( "UI:GetEvolvingShipNodeForShipSlot()[ERROR]: invalid ship slot" )
		return nodeName
	end

	local nodes = UI:GetEvolvingShipNodes( shipDefName )

	for _nodeName, node in pairs( nodes ) do

		if UI:IsEvolvingShipNodeOfTypeShipSlot( _nodeName ) then

			local _slotId = UI:GetEvolvingShipNodeShipSlot( _nodeName )

			if _slotId == slotId then
				nodeName = _nodeName
				break
			end

		end

	end

	return nodeName

end


