--
function UI:GetEvolvingShipNodeSpecModule( nodeName, shipDefName, chosenNodesMask )

	local specModuleDefName = ""

	if type( nodeName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeSpecModule()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return specModuleDefName
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetEvolvingShipNodeSpecModule()[ERROR]: invalid type of the 2-nd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return specModuleDefName
	end

	if chosenNodesMask ~= nil then
    	if type( chosenNodesMask ) ~= "userdata" then
    		sys.log( "UI:GetEvolvingShipNodeSpecModule()[ERROR]: invalid type of the 3-rd parameter (\"chosenNodesMask\"); \"userdata\" or \"nil\" expected, got \"%s\"", type( chosenNodesMask ) )
    		return specModuleDefName
    	end
	end

	if not UI:IsShipEvolving( shipDefName ) then
		sys.log( "UI:GetEvolvingShipNodeSpecModule()[ERROR]: ship %s is not craftable", shipDefName )
		return specModuleDefName
	end

	local nodesMask = u64( 0 )

	if chosenNodesMask ~= nil then
		nodesMask = chosenNodesMask
	else
		local shipItem = UI:GetEvolvingShipItem( shipDefName )
		if shipItem then
			nodesMask = UI:GetEvolvingShipActiveNodesMask( shipItem.vid )
		end
	end

	local mainEvolvedShipDefName = UI:CalcEvolvingShipDefNameFromNodesMask( shipDefName, nodesMask )
	if mainEvolvedShipDefName ~= "" then

    	local shipVariants = UI:GetEvolvingShipNodeShipVariants( nodeName )
    	local altEvolvedShipDefName = shipVariants[ mainEvolvedShipDefName ] or ""

    	if altEvolvedShipDefName ~= "" then

			specModuleDefName = UI:GetShipDefaultSpecModule( altEvolvedShipDefName )

    	else

			local altShipWithMinRank = ""
			local minRank = -1

			for mainDefName, altDefName in pairs( shipVariants ) do
				local rank = UI:GetShipRank( mainDefName )
				if minRank == -1 or rank < minRank then
					minRank = rank
					altShipWithMinRank = altDefName
				end
			end

			if altShipWithMinRank ~= "" then
				specModuleDefName = UI:GetShipDefaultSpecModule( altShipWithMinRank )
			else
				sys.log( "UI:GetEvolvingShipNodeSpecModule()[ERROR]: cannot find ship variant for specmodule for ship %s, node %s, nodesMask %s", shipDefName, nodeName, _G.U64ToStr( nodesMask ) )
			end

    	end

	else
		sys.log( "UI:GetEvolvingShipNodeSpecModule()[ERROR]: cannot find evolved ship for ship \"%s\" and nodes mask %s", shipDefName, _G.U64ToStr( nodesMask ) )
	end

	return specModuleDefName

end


