-- скрыто из интерфейса; при этом нод может иметь любое стостояние (изучено, активно) и продолжает участвовать при определении ранга корабля
-- bHierarchycally - проверит, не скрыт ли предок
-- shipDefName - опциональный параметр, если указано bHierarchycally
-- nodes - готовый массив нод, для оптимизации - опциональный параметр, если указано bHierarchycally

function UI:IsEvolvingShipNodeHidden( nodeName, bHierarchycally, shipDefName, nodes )

	local bHidden = false

	if type( nodeName ) ~= "string" then
		sys.log( "UI:IsEvolvingShipNodeHidden()[ERROR]: invalid type of the 1-st parameter (\"nodeName\"); \"string\" expected, got \"%s\"", type( nodeName ) )
		return bHidden
	end

	if bHierarchycally ~= nil then
    	if type( bHierarchycally ) ~= "boolean" then
    		sys.log( "UI:IsEvolvingShipNodeHidden()[ERROR]: invalid type of the 2-nd parameter (\"bHierarchycally\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bHierarchycally ) )
    		return bHidden
    	end
	end
	if bHierarchycally == nil then
		bHierarchycally = false
	end

	if bHierarchycally then

    	if type( shipDefName ) ~= "string" then
    		sys.log( "UI:IsEvolvingShipNodeHidden()[ERROR]: invalid type of the 3-rd parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
    		return bHidden
    	end

		if nodes ~= nil then
        	if type( nodes ) ~= "table" then
        		sys.log( "UI:IsEvolvingShipNodeHidden()[ERROR]: invalid type of the 4-th parameter (\"nodes\"); \"table\" or \"nil\"  expected, got \"%s\"", type( nodes ) )
        		return bHidden
        	end
		end

	end


	local nodeInfo = UI:GetEvolvingShipNodeByName( nodeName )

	if not nodeInfo then
		sys.log( "UI:IsEvolvingShipNodeHidden()[ERROR]: cannot find node \"%s\"", nodeName )
		return blueprintDefName
	end

	if nodeInfo.hidden ~= nil then
    	if type( nodeInfo.hidden ) == "boolean" then
    		bHidden = nodeInfo.hidden
    	else
    		sys.log( "UI:IsEvolvingShipNodeHidden()[ERROR]: invalid type of _G.VesselProgress[\"%s\"].hidden; \"boolean\" or \"nil\" expected, got \"%s\"", nodeName, type( nodeInfo.hidden ) )
    	end
	end

	if bHidden then
		return bHidden
	end


	if bHierarchycally then

		if not nodes then
    		nodes = UI:GetEvolvingShipNodes( shipDefName )
		end

		local node = nodes[ nodeName ]
		if node then

        	local parentNode = node.parent
        	while parentNode do

        		if UI:IsEvolvingShipNodeHidden( parentNode.name, false ) then
        			bHidden = true
        			break
        		end

        		parentNode = parentNode.parent

        	end

		else
			sys.log( "UI:IsEvolvingShipNodeHidden()[ERROR]: cannot find node %s among nodes of ship %s", nodeName, shipDefName )
		end

	end

	return bHidden

end


