--
function UI:CanSellShip( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:CanSellShip()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	-- одно время можно было продавать dlc корабли, если у них цена не в золоте ( #0055600, комм.(0221497) ), но было убрано в #0065383,комм.(0268617)
	-- также можно было разобрать крафтовый корабль, но было убрано в #0060122

	return
		not UI:IsShipGold( defName )
		and not UI:IsShipCraftable( defName )
		and not UI:IsShipDlc( defName )
		and not UI:IsShipEvolving( defName )
		and not UI:CantItemBeBoughtByDef( defName )	-- #0075401,комм.(0328723)

end


--
function UI:CheckShowMsgOnUnequipPrimaryAmmo( shipItem, dstWeaponClass )

	local hMsg = UI.INVALID_UI_HANDLE

	local bHasPrimaryAmmo = false

	local primaryAmmoInfo = shipItem.equipAmmo[ ai.MunitionBayType.MBT_PRIMARY ]
	if primaryAmmoInfo and primaryAmmoInfo.def ~= "" and primaryAmmoInfo.amount > 0 then
		bHasPrimaryAmmo = true
	end

	if not bHasPrimaryAmmo then
		return hMsg
	end

	local ammoWeaponClass = UI:GetWeaponClass( primaryAmmoInfo.def )
	if ammoWeaponClass == dstWeaponClass then
		return hMsg
	end

	hMsg = UI:MessageBox( UI:GetStringByName( "msgCapt_warning" ), UI:GetStringByName( "msg_unfitModsDrop" ), UI.MBS_OK )

	return hMsg

end


