--
function UI:ShowErrorMsg( stringId, result, resultsTableName )

	local msg = ""

	if type( stringId ) ~= "string" then
		sys.log( "UI:ShowErrorMsg()[ERROR]: invalid type of the 1-st parameter (\"stringId\"); \"string\" expected, fot \"%s\"", type( stringId ) )
		stringId = ""
	end

	if stringId ~= "" then
		msg = UI:GetStringByName( stringId )
	end

	return UI:ShowErrorMsg2( msg, result, resultsTableName )

end


-- (msg - локализованный текст)
function UI:ShowErrorMsg2( msg, result, resultsTableName )

	if type( msg ) ~= "string" then
		sys.log( "UI:ShowErrorMsg2()[ERROR]: invalid type of the 1-st parameter (\"msg\"); \"string\" expected, fot \"%s\"", type( msg ) )
		msg = ""
	end

	if result ~= nil then

		local resultStr = UI:Result2Str( result, resultsTableName )

    	if msg ~= "" then

			if string.find( msg, "%%s", 1, false ) then
    			msg = string.format( msg, resultStr )
			else
				msg = string.format( "%s %s", msg, resultStr )
			end

    	else
    		msg = string.format( "[INVALID STRING] Error: %s", resultStr )
    	end

	end

	if msg == "" then
		msg = "[INVALID STRING] Error"
	end

	return UI:MessageBox( UI:GetStringByName( "msgCapt_error" ), msg, UI.MBS_OK )

end


--
function UI:Result2Str( result, resultsTableName )

	local resultStr = "unknown"

	if type( result ) ~= "number" then
		sys.log( "UI:Result2Str()[ERROR]: invalid type of the 1-st parameter (\"result\"); \"number\" expected, fot \"%s\"", type( result ) )
		return resultStr
	end

	if type( resultsTableName ) ~= "string" then
		sys.log( "UI:Result2Str()[ERROR]: invalid type of the 2-nd parameter (\"resultsTableName\"); \"string\" expected, fot \"%s\"", type( resultsTableName ) )
		return resultStr
	end

	local resultsTable = UI:GetValByName( resultsTableName )

	local resultName = UI:Val2Key( resultsTable, result )
	if resultName == "" then
		sys.log( "UI:Result2Str()[ERROR]: cannot find val %d in table %s", result, resultsTableName )
		return resultStr
	end

	if resultsTable == _G.GameStore.StoreBuyResult then
		resultStr = UI:GetStringByName( string.format( "buyError_%s", resultName ) )

	elseif resultsTable == _G.GameStore.ModuleEquipResult then
		resultStr = UI:GetStringByName( string.format( "equipError_%s", resultName ) )

	elseif resultsTable == _G.GameStore.MunitionResult then
		resultStr = UI:GetStringByName( string.format( "refillError_%s", resultName ) )

	elseif resultsTable == _G.GameStore.ChangeBSResult then
		resultStr = UI:GetStringByName( string.format( "assignBattleShipError_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.QuestResult then
		resultStr = UI:GetStringByName( string.format( "questError_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.ShipQuestOpResult then
		resultStr = UI:GetStringByName( string.format( "shipQuestError_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.ClanOpResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.LeagueTeamOperationResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.LeaderboardGetResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.RejoinResult then
		resultStr = UI:GetStringByName( string.format( "rejoinError_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.ZoneInstanceTravelResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.SquadOpResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.AccountAttachResult then
		resultStr = UI:GetStringByName( string.format( "linkAccountError_%s", resultName ) )

	elseif resultsTable == ai.SalvageOpRes then
		resultStr = UI:GetStringByName( string.format( "salvageError_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.MailOpResult then
		resultStr = UI:GetStringByName( string.format( "mailOpResult_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.ReferralsResult then
		resultStr = UI:GetStringByName( string.format( "ReferralsResult_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.GenericResponderResult then
		resultStr = UI:GetStringByName( string.format( "GenericResponderResult_%s", resultName ) )

	elseif resultsTable == _G.SkillManager.TalentResult then
		resultStr = UI:GetStringByName( string.format( "talentsError_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.RewardTutorialResult then
		resultStr = UI:GetStringByName( string.format( "RewardTutorialResult_%s", resultName ) )

	elseif resultsTable == _G.MasterServer.LobbyOpResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.AdvertResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.SetCivilianZoneResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.WarResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.UserNotesResult then
		resultStr = UI:GetStringByName( resultName )

	elseif resultsTable == _G.MasterServer.BattlePassResult then
		resultStr = UI:GetStringByName( resultName )

	else
		sys.log( "UI:Result2Str()[ERROR]: unhandled results table %s", resultsTableName )
	end

	return resultStr

end


