--
function UI:CanItemUpgradeNow( iid )

	if type( iid ) ~= "userdata" or iid == UI.INVALID_U64_ID then
		sys.log( "UI:CanItemUpgradeNow()[ERROR]: invalid iid" )
		return false
	end

	local defName = UI:Iid2DefName( iid )

	if UI:IsDefAutogen( defName ) then
		return false
	end

	if not UI:CanItemUpgradeFurther( defName ) or UI:CanUpgradeItemThroughCraftOnly( defName ) then
		return false
	end

	if UI:GetPlayerCredits() < UI:GetItemUpgradeCreditsPrice( defName ) then
		return false
	end

	return true

end


--
function UI:GetBlueprintRequiredNode( blueprintDefName )

	local nodeName		= ""
	local shipDefName	= ""

	if type( blueprintDefName ) ~= "string" then
		sys.log( "UI:GetBlueprintRequiredNode()[ERROR]: invalid type of the 1-st parameter (\"blueprintDefName\"); \"string\" expected, got \"%s\"", type( blueprintDefName ) )
		return nodeName, shipDefName
	end

	local blueprintDef = UI:GetDef( blueprintDefName )
	if not blueprintDef then
		sys.log( "UI:GetBlueprintRequiredNode()[ERROR]: cannot find _G.Def[\"%s\"]", blueprintDefName )
		return nodeName, shipDefName
	end

	if blueprintDef.required_node == nil then
		return nodeName, shipDefName
	end

	if type( blueprintDef.required_node ) == "number" then

		local nodeId = blueprintDef.required_node

    	if type( blueprintDef.required_ship ) == "string" then

	    	shipDefName = blueprintDef.required_ship

			if shipDefName ~= "" then

    			nodeName = UI:GetEvolvingShipNodeNameById( nodeId, shipDefName )

    			if nodeName == "" then
					sys.log( "UI:GetBlueprintRequiredNode()[ERROR]: cannot find node %d for ship %s", nodeId, shipDefName )
					shipDefName = ""
    			end

			else
				sys.log( "UI:GetBlueprintRequiredNode()[ERROR]: empty _G.Def[\"%s\"].required_ship", blueprintDefName )
			end

		else
    		sys.log( "UI:GetBlueprintRequiredNode()[ERROR]: invalid type of _G.Def[\"%s\"].required_ship; \"string\" expected, got \"%s\"", blueprintDefName, type( blueprintDef.required_ship ) )
    	end

	else
		sys.log( "UI:GetBlueprintRequiredNode()[ERROR]: invalid type of _G.Def[\"%s\"].required_node; \"number\" or \"nil\" expected, got \"%s\"", blueprintDefName, type( blueprintDef.required_node ) )
	end

	return nodeName, shipDefName

end


