function UI:SquadFinderActivityType2Str( activityType )

	local str = "unknown"

	if type( activityType ) ~= "number" then
		sys.log( "UI:SquadFinderActivityType2Str()[ERROR]: invalid type of the 1-st parameter (\"activityType\"); \"number\" expected, got \"%s\"", type( activityType ) )
		return str
	end

	str = string.format( "[invalid name] %d", activityType )

	if type( _G.SquadSearchAct ) ~= "table" then
		sys.log( "UI:SquadFinderActivityType2Str()[ERROR]: invalid type of _G.SquadSearchAct; \"table\" expected, got \"%s\"", type( _G.SquadSearchAct ) )
		return str
	end

	local activityName = UI:Val2Key( _G.SquadSearchAct, activityType )
	if activityName == "" then
		sys.log( "UI:SquadFinderActivityType2Str()[ERROR]: cannot find activity %d in table _G.SquadSearchAct", activityType )
		return str
	end

	local strName = string.format( "squad_search_act_%s", activityName )
	str = UI:GetStringByName( strName )

	return str

