--
function UI:GetTradingDealsLeft()

	local maxDeals = UI:GetTradingDealsMax()
	if maxDeals == 0 then	-- #0098712 0 максимального количества сделок означает отсутствие ограничение
		return -1
	end

	local numDealsAccomplished = _G.MasterServer_GetTradingDealsNum()

	if type( numDealsAccomplished ) ~= "number" then
		sys.log( "UI:GetTradingDealsLeft()[ERROR]: invalid type of return value from _G.MasterServer_GetTradingDealsNum(); \"number\" expected, got \"%s\"", type( numDealsAccomplished ) )
		numDealsAccomplished = 0
	end

	return math.max( maxDeals - numDealsAccomplished, 0 )

end


