--
function UI:GetItemSetItems( setName )

	local items = {}

	if type( setName ) ~= "string" then
		sys.log( "UI:GetItemSetItems()[ERROR]: invalid type of the 1-st parameter (\"setName\"); \"string\" expected, got \"%s\"", type( setName ) )
		return items
	end

	if type( _G.ItemSets ) ~= "table" then
		sys.log( "UI:GetItemSetItems()[ERROR]: invalid type of _G.ItemSets; \"table\" expected, got \"%s\"", type( _G.ItemSets ) )
		return items
	end

	local setDef = _G.ItemSets[ setName ]
	if type( setDef ) ~= "table" then
		sys.log( "UI:GetItemSetItems()[ERROR]: invalid type of _G.ItemSets[\"%s\"]; \"table\" expected, got \"%s\"", setName, type( setDef ) )
		return items
	end

	if type( setDef.items ) ~= "table" then
		sys.log( "UI:GetItemSetItems()[ERROR]: invalid type of _G.ItemSets[\"%s\"].items; \"table\" expected, got \"%s\"", setName, type( setDef.items ) )
		return items
	end

	for idx, defName in ipairs( setDef.items ) do

		if type( defName ) == "string" then
			table.insert( items, defName )
		else
			sys.log( "UI:GetItemSetItems()[ERROR]: invalid type of _G.ItemSets[\"%s\"].items[%d]; \"string\" expected, got \"%s\"", setName, idx, type( defName ) )
		end

	end

	if not next( items ) then
		sys.log( "UI:GetItemSetItems()[ERROR]: no items found for set \"%s\"", setName )
	end

	return items

end


--[[
возвращаемые данные - в формате:
{
	-- отсортированы по numItems
    {
    	numItems = <number>,	-- минимальное количество предметов из сета, которые должны быть экипированы для того, чтобы бонусы были активированы
    	bonuses =
    	{
			-- отсортированы по name
    		{
        		name	= <string>,
        		val		= <number>,
    		},
    		...
    	}
    },
	...
}
]]

function UI:GetItemSetBonuses( setName )

	local bonuses = {}

	if type( setName ) ~= "string" then
		sys.log( "UI:GetItemSetBonuses()[ERROR]: invalid type of the 1-st parameter (\"setName\"); \"string\" expected, got \"%s\"", type( setName ) )
		return bonuses
	end

	if type( _G.ItemSets ) ~= "table" then
		sys.log( "UI:GetItemSetBonuses()[ERROR]: invalid type of _G.ItemSets; \"table\" expected, got \"%s\"", type( _G.ItemSets ) )
		return bonuses
	end

	local setDef = _G.ItemSets[ setName ]
	if type( setDef ) ~= "table" then
		sys.log( "UI:GetItemSetBonuses()[ERROR]: invalid type of _G.ItemSets[\"%s\"]; \"table\" expected, got \"%s\"", setName, type( setDef ) )
		return bonuses
	end

	if type( setDef.bonus ) ~= "table" then
		sys.log( "UI:GetItemSetBonuses()[ERROR]: invalid type of _G.ItemSets[\"%s\"].bonus; \"table\" expected, got \"%s\"", setName, type( setDef.bonus ) )
		return bonuses
	end


	local function fnSortByName( bonusInfo1, bonusInfo2 )
		return bonusInfo1.name < bonusInfo2.name
	end

	for numItems, levelData in ipairs( setDef.bonus ) do

		if type( levelData ) == "table" then

    		if next( levelData ) then

				local levelInfo = nil

    			for bonusName, bonusVal in pairs( levelData ) do

    				if type( bonusName ) == "string" and type( bonusVal ) == "number" then

						local bonusInfo =
						{
							name	= bonusName,
							val		= bonusVal,
						}

						if not levelInfo then

							levelInfo =
							{
								numItems	= numItems,
								bonuses		= {},
							}

						end

						table.insert( levelInfo.bonuses, bonusInfo )

    				else
						sys.log( "UI:GetItemSetBonuses()[ERROR]: invalid format of _G.ItemSets[\"%s\"].bonus[%d]; <string>=<number> expected, got <%s>=<%s>", setName, numItems, type( bonusName ), type( bonusVal ) )
					end

    			end

				if levelInfo then
					table.sort( levelInfo.bonuses, fnSortByName )
					table.insert( bonuses, levelInfo )
				end

    		end

		else
			sys.log( "UI:GetItemSetBonuses()[ERROR]: invalid type of _G.ItemSets[\"%s\"].bonus[%d]; \"table\" expected, got \"%s\"", setName, numItems, type( levelData ) )
		end

	end

	return bonuses

end


