--
function UI:F_OnMouseLButtonDown( mouseX, mouseY, wndThatReceivedInput )

	if UI:CanAddLinkToChatOnClick( mouseX, mouseY ) then
		if UI:TryAddLinkToChatOnClick( mouseX, mouseY ) then
			return true
		end
	end

	return false

end


--
function UI:F_OnMouseLButtonUp( mouseX, mouseY, wndThatReceivedInput )

	return UI:CanAddLinkToChatOnClick( mouseX, mouseY )
end


--
function UI:CanAddLinkToChatOnClick( mouseX, mouseY )

	return
		not _G.IsCursorHidden()
		and _G.Input_IsKeyPressed( UI.Keys.KEY_SHIFT )
		and UI:DetectLinkToChatOnClickParams( mouseX, mouseY ) ~= -1

end


--
function UI:TryAddLinkToChatOnClick( mouseX, mouseY )

	local linkType, linkParams = UI:DetectLinkToChatOnClickParams( mouseX, mouseY )
	if linkType ~= -1 then
		UI.ChatWnd:InsertLinkAndEdit( linkType, linkParams )
		return true
	else
		return false
	end

end


--
function UI:DetectLinkToChatOnClickParams( mouseX, mouseY )

	local linkType		= -1
	local linkParams	= nil

	if not UI.ChatWnd:IsOnScreen() then
		return linkType, linkParams
	end

	local wnd = UI:FindWindowUnderMouse( UI.Root, mouseX, mouseY, true )

	if not wnd or not wnd.GetTooltipData then
		return linkType, linkParams
	end

	local tooltipData = wnd:GetTooltipData()
	if not tooltipData then
		return linkType, linkParams
	end

	if tooltipData.tooltipType == UI.tooltipTypes.MODULE or tooltipData.tooltipType == UI.tooltipTypes.SHIP or tooltipData.tooltipType == UI.tooltipTypes.RESOURCE then

    	linkType = UI:Def2LinkType( tooltipData.defName )

		if linkType ~= -1 then
			linkParams = { defName = tooltipData.defName }
		end

	end

	return linkType, linkParams

end


--
function UI:Def2LinkType( defName )

	local linkType = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:Def2LinkType()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return linkType
	end

	if UI:IsDefModule( defName ) or UI:IsDefAmmo( defName ) then
		linkType = UI.LinkWnd.linkTypes.ITEM

	elseif UI:IsDefResource( defName ) or UI:IsDefBlueprint( defName ) then
		linkType = UI.LinkWnd.linkTypes.RESOURCE

	elseif UI:IsDefShip( defName ) then
		linkType = UI.LinkWnd.linkTypes.SHIP
	end

	return linkType

end


