--
function UI:GetShipParamMaxVal( shipDefName, paramName )

	local maxVal = 0

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:GetShipParamMaxVal()[ERROR]: invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return maxVal
	end

	if type( paramName ) ~= "string" then
		sys.log( "UI:GetShipParamMaxVal()[ERROR]: invalid type of the 2-nd parameter (\"paramName\"); \"string\" expected, got \"%s\"", type( paramName ) )
		return maxVal
	end

	if type( _G.ShipProgressBarMaxValue ) ~= "table" then
		sys.log( "UI:GetShipParamMaxVal()[ERROR]: invalid type of \"_G.ShipProgressBarMaxValue\"; \"table\" expected, got \"%s\"", type( _G.ShipProgressBarMaxValue ) )
		return maxVal
	end

	local paramDada = _G.ShipProgressBarMaxValue[ paramName ]
	if type( paramDada ) ~= "table" then
		sys.log( "UI:GetShipParamMaxVal()[ERROR]: invalid type of _G.ShipProgressBarMaxValue[\"%s\"]; \"table\" expected, got \"%s\"", paramName, type( paramDada ) )
		return maxVal
	end

	local role = UI:GetItemRole( shipDefName )

	if type( paramDada[ role ] ) == "number" then
		maxVal = paramDada[ role ]
	else
		sys.log( "UI:GetShipParamMaxVal()[ERROR]: invalid type of _G.ShipProgressBarMaxValue[\"%s\"][%d]; \"table\" expected, got \"%s\"", paramName, role, type( paramDada[ role ] ) )
	end

	return maxVal

end


-- возвращаемое значение - от 0 до 1
function UI:GetGoldBonus()

	local baseBonus = _G.GameStore_GetBonusGoldPercentage()

	if type( baseBonus ) ~= "number" then
		sys.log( "UI:GetGoldBonus()[ERROR]: invalid type of return value from _G.GameStore_GetBonusGoldPercentage(); \"number\" expected, got \"%s\"", type( baseBonus ) )
		baseBonus = 0
	end

	local auraBonus = 0

	for idx, auraInfo in pairs( self.serverData.accountAuras ) do

		if UI:GetAccountAuraCategory( auraInfo.defName ) == ai.AccountAuraCategory.BUY_GOLD_BONUS then
			auraBonus = UI:GetAccountAuraGoldModifier( auraInfo.defName )
			break
		end
	end

	return baseBonus + auraBonus

end


-- парамтры countInventory, maxCountInventory, countEquipped нужны только если bStacked=true; параметр equipShipItem - если bStacked=false
function UI:MakeItemStorageString( bStacked, countInventory, maxCountInventory, countEquipped, equipShipItem, bLinksAllowed, baseColor )

	local str = "error"

	if type( bStacked ) ~= "boolean" then
		sys.log( "UI:MakeItemStorageString()[ERROR]: invalid type of the 1-st parameter (\"bStacked\"); \"boolean\" expected, got \"%s\"", type( bStacked ) )
		return str
	end

	if bStacked then

    	if type( countInventory ) ~= "number" then
    		sys.log( "UI:MakeItemStorageString()[ERROR]: invalid type of the 2-nd parameter (\"countInventory\"); \"number\" expected, got \"%s\"", type( countInventory ) )
    		return str
    	end

    	if type( maxCountInventory ) ~= "number" then
    		sys.log( "UI:MakeItemStorageString()[ERROR]: invalid type of the 3-rd parameter (\"maxCountInventory\"); \"number\" expected, got \"%s\"", type( maxCountInventory ) )
    		return str
    	end

    	if type( countEquipped ) ~= "number" then
    		sys.log( "UI:MakeItemStorageString()[ERROR]: invalid type of the 4-th parameter (\"countEquipped\"); \"number\" expected, got \"%s\"", type( countEquipped ) )
    		return str
    	end

	else

		if equipShipItem ~= nil then
        	if type( equipShipItem ) ~= "table" then
        		sys.log( "UI:MakeItemStorageString()[ERROR]: invalid type of the 5-th parameter (\"equipShipItem\"); \"table\" expected, got \"%s\"", type( equipShipItem ) )
        		return str
        	end
		end

	end

	if bLinksAllowed ~= nil then
    	if type( bLinksAllowed ) ~= "boolean" then
    		sys.log( "UI:MakeItemStorageString()[ERROR]: invalid type of the 6-th parameter (\"bLinksAllowed\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bLinksAllowed ) )
    		bLinksAllowed = nil
    	end
	end

	if bLinksAllowed == nil then
		bLinksAllowed = false
	end

	if baseColor ~= nil then
    	if type( baseColor ) ~= "number" then
    		sys.log( "UI:MakeItemStorageString()[ERROR]: invalid type of the 7-th parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
    		baseColor = nil
    	end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end


	-- много предметов
	if bStacked then

		-- в инвентаре

		local strInventory = UI:GetStringByName( "storage_inventory_multi" )

		local strInventoryVal = ""
		if maxCountInventory ~= -1 then
			strInventoryVal = string.format( "%s/%s", UI:Num2StrSeparatedBy3( countInventory ), UI:Num2StrSeparatedBy3( maxCountInventory ) )
		else
			strInventoryVal = UI:Num2StrSeparatedBy3( countInventory )
		end

		local numSubst = 0
		strInventory, numSubst = string.gsub( strInventory, "%$val%$", strInventoryVal )

		if numSubst == 0 then
			sys.log( "UI:MakeItemStorageString()[ERROR]: cannot find placeholder \"$val$\" in string \"storage_inventory_multi\"" )
			strInventory = string.format( "[INVALID STRING] Inventory: %s", strInventoryVal )
		end

		-- экипировано

		local strEquipped = ""

		if countEquipped > 0 then

			strEquipped = UI:GetStringByName( "storage_equipped_multi" )

			local strEquippedVal = UI:Num2StrSeparatedBy3( countEquipped )

			local numSubst = 0
    		strEquipped, numSubst = string.gsub( strEquipped, "%$val%$", strEquippedVal )

    		if numSubst == 0 then
    			sys.log( "UI:MakeItemStorageString()[ERROR]: cannot find placeholder \"$val$\" in string \"storage_equipped_multi\"" )
    			strEquipped = string.format( "[INVALID STRING] Equipped: %s", strEquippedVal )
    		end

		end

		-- всё вместе
		str = strEquipped ~= "" and string.format( "%s / %s", strInventory, strEquipped ) or strInventory


	-- один предмет
	else

		-- экипирован
		if equipShipItem then

			str = UI:GetStringByName( "storage_equipped_one" )

			local strShipName = ""

			if bLinksAllowed then
				strShipName = string.format( "$link [type SHIP][params {defName=\"%s\", vid=u64(%d,%d)}]$", equipShipItem.defName, equipShipItem.vid.h, equipShipItem.vid.l )
			else
				strShipName = string.foramt( "%s%s", UI:GetEntityLocalizedNameByDef( equipShipItem.defName, true ), UI:Color2Str( baseColor ) )
			end

			local numSubst = 0
    		str, numSubst = string.gsub( str, "%$ship%$", strShipName )

    		if numSubst == 0 then
    			sys.log( "UI:MakeItemStorageString()[ERROR]: cannot find placeholder \"$ship$\" in string \"storage_equipped_one\"" )
    			str = string.format( "[INVALID STRING] Equipped on ship %s", strShipName )
    		end

		-- в инвентаре
		else
			str = UI:GetStringByName( "storage_inventory_one" )
		end

	end

	return str

end


-- return bCanStart, minShipsRank, maxShipsRank
function UI:CanStartBfsInRandomZone( universeType )

	if type( universeType ) ~= "number" then
		sys.log( "UI:CanStartBfsInRandomZone()[ERROR]: invalid type of the 1-st param ('universeType'); 'number' expected, got '%s'", type( universeType ) )
		return false
	end


--[[ #0076544,комм.(0340648) , поправки в SC-111154 (ранги вместо тира) (SC-111154#focus=streamItem-4-572564.0-0)
	БЗС в рандомной локации можно начать, если:
	- если игрок не в скваде,
	- и если у игрока в боевых слотах не меньше трех кораблей,
	- и если MasterServer_EnableUniverseByRank( universeType, shipsMinRank, shipsMaxRank) вернет true
]]

	-- не в скваде?

	if UI.Squad:IsInSquad() then
		return false
	end

	-- у игрока в боевых слотах не меньше трех кораблей

	local vids			= {}
	local MIN_NUM_SHIPS	= 3

	for battleSlotIdx, vid in pairs( UI.serverData.battleSlots ) do
		if vid ~= UI.INVALID_U64_ID then
			table.insert( vids, vid )
		end
	end

	if #vids < MIN_NUM_SHIPS then
		return false
	end

	-- есть доступная зона для таких рангов?

	local shipsMinRank = -1
	local shipsMaxRank = -1

	for shipIdx, vid in pairs( vids ) do

		local shipItem = self:GetShipItem( vid )
		if shipItem then

			local rank = UI:GetShipRank( shipItem.defName )
			if rank ~= -1 then

				if shipsMinRank == -1 or rank < shipsMinRank then
					shipsMinRank = rank
				end

				if shipsMaxRank == -1 or rank > shipsMaxRank then
					shipsMaxRank = rank
				end

			end

		end

	end

	if shipsMinRank == -1 or shipsMaxRank == -1 then
		sys.log( "UI:CanStartBfsInRandomZone()[ERROR]: invalid ship ranks" )
		return false
	end

	local bZoneEnabled = _G.MasterServer_EnableUniverseByRank( universeType, shipsMinRank, shipsMaxRank )

	if type( bZoneEnabled ) ~= "boolean" then
		sys.log( "UI:CanStartBfsInRandomZone()[ERROR]: invalid type of return value from _G.MasterServer_EnableUniverseByRank(); \"boolean\" expected, got \"%s\"", type( bZoneEnabled ) )
		bZoneEnabled = false
	end

	if not bZoneEnabled then
		return false
	end

	return true, shipsMinRank, shipsMaxRank

end


--
function UI:GetTransferToZonePrice( zoneId )

	local priceInfo =
	{
		priceType 	= _G.GameStore.CreditsType.CT_CREDITS,
		val			= 0,	-- в случае 0 отобразится слово "Бесплатно" голубым цветом, без иконки валюты
		basePrice	= 0,
		bIsBuyPrice	= true,
	}

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetTransferToZonePrice()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return priceInfo
	end

	-- вылет в зону, где есть станция, бесплатен
	if UI:IsZoneSpaceStation( zoneId ) then
		return priceInfo
	end

	-- вылет в зону, которой владеет корпорация игрока, бесплатен (#0092868)
	local zoneUniversrData = UI.Universe:GetSectorById( zoneId, false )	-- если зона не участвует в бзс, то ее нет в данных universe; сначало это проверяется, чтобы в GetSectorOwner не ругалось
	if UI.Clan:IsInClan() and zoneUniversrData and UI.Universe:GetSectorOwner( zoneId ) == UI.Clan:GetCid() then
		return priceInfo
	end

	-- #0104332 вылет в зону, которая прописана в accessibleZoneIds взятого квеста, бесплатен
	for questIdx, questInfo in pairs( UI.serverData.activeQuests ) do

		local questId = questInfo.id

		local stage = UI:GetQuestStage( questId )
		local questZones = UI:GetQuestAccessibleZonesForStage( questId, stage )

		for questZoneIdx, questZoneId in pairs( questZones ) do
			if questZoneId == zoneId then
				return priceInfo
			end
		end

	end


	local price		= 0
	local priceType	= -1

	local gameplayInfo = nil

	if type( _G.GameplayDef ) == "table" and type( _G.GameplayDef[ ai.Gameplay.FREE_SPACE ] ) == "table" then
		gameplayInfo = _G.GameplayDef[ ai.Gameplay.FREE_SPACE ]
	end

	if gameplayInfo then

		if type( gameplayInfo.jump_to_zone_price_type ) == "number" then

			priceType = gameplayInfo.jump_to_zone_price_type

			if type( gameplayInfo.jump_to_zone_price_value ) == "number" then
				price = gameplayInfo.jump_to_zone_price_value
			else
				sys.log( "UI:GetTransferToZonePrice()[ERROR]: invalid type of _G.GameplayDef[ ai.Gameplay.FREE_SPACE ].jump_to_zone_price_value; \"number\" expected, got \"%s\"", type( gameplayInfo.jump_to_zone_price_value ) )
				priceType = -1
			end

		else
			sys.log( "UI:GetTransferToZonePrice()[ERROR]: invalid type of _G.GameplayDef[ ai.Gameplay.FREE_SPACE ].jump_to_zone_price_type; \"number\" expected, got \"%s\"", type( gameplayInfo.jump_to_zone_price_type ) )
		end

	else
		sys.log( "UI:GetTransferToZonePrice()[ERROR]: cannot find table _G.GameplayDef[ ai.Gameplay.FREE_SPACE ]" )
	end

	if priceType == _G.GameStore.CreditsType.CT_INVALID then	-- CT_INVALID - валидное значение, оно означает, что перелет бесплатен
		price		= 0
		priceType	= _G.GameStore.CreditsType.CT_CREDITS
	end

	if priceType ~= -1 then
		priceInfo.priceType	= priceType
		priceInfo.val		= price
		priceInfo.basePrice	= price
	end

	return priceInfo

end


--
function UI:IsZoneAllowedForTransfer( zoneId )

	local bAllowed = true

	if type( zoneId ) ~= "number" then
		sys.log( "UI:IsZoneAllowedForTransfer()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return bAllowed
	end

	local zoneDef = _G.SpaceZoneById and _G.SpaceZoneById[ zoneId ]
	if not zoneDef then
		sys.log( "UI:IsZoneAllowedForTransfer()[ERROR]: cannot find def for zone %d", zoneId )
		return bAllowed
	end

	if zoneDef.allowed_jump ~= nil then

		if type( zoneDef.allowed_jump ) == "boolean" then
			bAllowed = zoneDef.allowed_jump
		else
			sys.log( "UI:IsZoneAllowedForTransfer()[ERROR]: invalid type of \"allowed_jump\" for zone %d; \"boolean\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneDef.allowed_jump ) )
		end

	end

	return bAllowed

end


--
function UI:GetAuraDefFieldValue( spellName, auraIdx, fieldName, defaultValue )

	local fieldValue = nil

	if type( spellName ) ~= "string" then
		sys.log( "UI:GetAuraDefFieldValue()[ERROR]: invalid type of the 1-st parameter (\"spellName\"); \"string\" expected, got \"%s\"", type( spellName ) )
		return fieldValue
	end

	if auraIdx ~= nil then
    	if type( auraIdx ) ~= "number" then
    		sys.log( "UI:GetAuraDefFieldValue()[ERROR]: invalid type of the 2-nd parameter (\"auraIdx\"); \"number\" or \"nil\" expected, got \"%s\"", type( auraIdx ) )
    		return fieldValue
    	end
	end

	if type( fieldName ) ~= "string" then
		sys.log( "UI:GetAuraDefFieldValue()[ERROR]: invalid type of the 3-st parameter (\"fieldName\"); \"string\" expected, got \"%s\"", type( fieldName ) )
		return fieldValue
	end

	if type( defaultValue ) == nil then
		sys.log( "UI:GetAuraDefFieldValue()[ERROR]: no the 4-st parameter (\"defaultValue\")" )
		return fieldValue
	end

	fieldValue = defaultValue

	if auraIdx == nil then
		auraIdx = 0
	end

	local spellDef = UI:GetSpellDef( spellName )
	if not spellDef then
		sys.log( "UI:GetAuraDefFieldValue()[ERROR]: cannot find _G.Spell[%s]", tostring( spellName ) )
		return fieldValue
	end

	if auraIdx == 0 then

		if spellDef[ fieldName ] ~= nil then
			if type( spellDef[ fieldName ] ) == type( defaultValue ) then
				fieldValue = spellDef[ fieldName ]
			else
				sys.log( "UI:GetAuraDefFieldValue()[ERROR]: invalid type of _G.Spell[\"%s\"].%s; \"%s\" or \"nil\" expected, got \"%s\"", spellName, fieldName, type( defaultValue ), type( spellDef.hud_visible ) )
			end
		end

	else

		if type( spellDef.additional_auras ) == "table" then

			local additionAuraInfo = spellDef.additional_auras[ auraIdx ]
			if type( additionAuraInfo ) == "table" then

				if additionAuraInfo[ fieldName ] ~= nil then
					if type( additionAuraInfo[ fieldName ] ) == type( defaultValue ) then
						fieldValue = additionAuraInfo[ fieldName ]
					else
						sys.log( "UI:GetAuraDefFieldValue()[ERROR]: invalid type of _G.Spell[\"%s\"].additional_auras[%d].%s; \"%s\" or \"nil\" expected, got \"%s\"", spellName, auraIdx, fieldName, type( defaultValue ), type( additionAuraInfo[ fieldName ] ) )
					end
				end

			else
				sys.log( "UI:GetAuraDefFieldValue()[ERROR]: invalid type of _G.Spell[\"%s\"].additional_auras[%d]; \"table\" expected, got \"%s\"", spellName, auraIdx, type( additionAuraInfo ) )
			end

		else
			sys.log( "UI:GetAuraDefFieldValue()[ERROR]: invalid type of _G.Spell[\"%s\"].additional_auras; \"table\" expected, got \"%s\"", spellName, type( spellDef.additional_auras ) )
		end

	end

	return fieldValue
end


