--
function UI:IsWndOfSquadFinder( handle )

	if type( handle ) ~= "number" then
		sys.log( "UI:IsWndOfSquadFinder()[ERROR]: invalid type of the 1-st parameter (\"handle\"); \"number\" expected, got \"%s\"", type( handle ) )
		return false
	end

	local wnd = UI:GetUiObjByHandleT( handle )
	if not wnd then
		sys.log( "UI:IsWndOfSquadFinder()[ERROR]: cannot find window with handle %d", handle )
		return false
	end

	return
		wnd == UI.SquadFinder_CreateMyGroupWnd
		or wnd == UI.SquadFinder_GroupsWnd
		or wnd == UI.SquadFinder_MyGroupWnd

end


--
function UI:GetGameRegion()

	if not _G.MasterServer_IsConnected() then
		sys.log( "Profile:GetGameRegion()[ERROR]: not connected to server" )
		return _G.MasterServer.AuthRegion.AR_UNKNOWN
	end

	local region = UI.serverData.userData.region

	if region ~= nil and region ~= _G.MasterServer.AuthRegion.AR_NUM then
		return region
	end

	region = _G.MasterServer_GetAuthRegion()
	self:SetGameRegion( region )

	if region == _G.MasterServer.AuthRegion.AR_NUM then
		return _G.MasterServer.AuthRegion.AR_UNKNOWN
	else
		return region
	end

end


--
function UI:SetGameRegion( region )

	if type( region ) ~= "number" then
		sys.log( "UI:SetGameRegion()[ERROR]: invalid type od the 1-st parameter (\"region\"); \"number\" expected, got \"%s\"", type( region ) )
		return
	end

	if not _G.MasterServer_IsConnected() then
		sys.log( "Profile:SetGameRegion()[ERROR]: not connected to server" )
		return
	end

	UI.serverData.userData.region = region
	UI:SaveServerUserData()

end


--
function UI:IsEMMReady()

	local bReady = false

	if _G.MasterServer_EMMGetReady ~= nil then	-- ui ¬®¦Ґв § Їа®бЁвм нв® ЇаЁ бў®Ґ¬  Ї¤Ґ©вҐ ­  а ­­Ґ© бв ¤ЁЁ, Є®Ј¤  нв  дг­ЄжЁп ҐйҐ ­Ґ ®ЇаҐ¤Ґ«Ґ­ 

    	bReady = _G.MasterServer_EMMGetReady()

    	if type( bReady ) ~= "boolean" then
    		sys.log( "UI:IsEMMReady()[ERROR]: invalid type of return value from _G.MasterServer_EMMGetReady(); \"boolean\" expected, got \"%s\"", type( bReady ) )
    		bReady = false
    	end

	end

	return bReady

end


--
function UI:IsEMMOpponent()

	local bIsOpponent		= false
	local bIsReadyOponent	= false

	if _G.MasterServer_EMMGetExistOpponent ~= nil then	-- ui ¬®¦Ґв § Їа®бЁвм нв® ЇаЁ бў®Ґ¬  Ї¤Ґ©вҐ ­  а ­­Ґ© бв ¤ЁЁ, Є®Ј¤  нв  дг­ЄжЁп ҐйҐ ­Ґ ®ЇаҐ¤Ґ«Ґ­ 

    	local opponentState = _G.MasterServer_EMMGetExistOpponent()
    	if type( opponentState ) == "number" then

    		if opponentState == _G.MasterServer.ExistOpponent.EO_NO_OPPONENT then

    		elseif opponentState == _G.MasterServer.ExistOpponent.EO_HAS_OPPONENT then
    			bIsOpponent		= true

    		elseif opponentState == _G.MasterServer.ExistOpponent.EO_HAS_READY_OPPONENT then
    			bIsOpponent		= true
    			bIsReadyOponent	= true

    		else
    			sys.log( "UI:IsEMMReady()[ERROR]: unhandled opponent state %d(%s)", opponentState, UI:Val2Key( _G.MasterServer.ExistOpponent, opponentState ) )
    		end

    	else
    		sys.log( "UI:IsEMMReady()[ERROR]: invalid type of return value from _G.MasterServer_EMMGetExistOpponent(); \"number\" expected, got \"%s\"", type( opponentState ) )
    	end

	end

	return bIsOpponent, bIsReadyOponent

end

--
function UI:ShowProfile( uid, modeName, bSound, restoreData, launchData )

	if type( uid ) ~= "userdata" then
		sys.log( "UI:ShowProfile()[ERROR]: invalid type of the 1-st parameter (\"uid\"); \"userdata\" expected, got \"%s\"", type( uid ) )
		return
	end

	if uid == UI.INVALID_U64_ID then
		sys.log( "UI:ShowProfile()[ERROR]: invalid uid" )
		return
	end

	if modeName ~= nil then
		if type( modeName ) ~= "string" then
			sys.log( "UI:ShowProfile()[ERROR]: invalid type of the 2-nd parameter (\"modeName\"); \"string\" or \"nil\" expected, got \"%s\"", type( modeName ) )
			modeName = nil
		end
	end

	if bSound ~= nil then
		if type( bSound ) ~= "boolean" then
			sys.log( "UI:ShowProfile()[ERROR]: invalid type of the 3-rd parameter (\"bSound\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bSound ) )
			bSound = nil
		end
	end

	if bSound == nil then
		bSound = false
	end

	if UI.HangarWnd:IsOnScreen() and not UI.DebriefingWnd:IsOnScreen() and not UI.DebriefingOWWnd:IsOnScreen() then

		UI.HangarWnd:ShowProfile( uid, modeName, bSound, restoreData, launchData )

	else

		if modeName == "ATLAS" then

			UI.Profile_Wnd:UnlinkFromParent()
			UI.LeaderboardWnd:UnlinkFromParent()

			local mode = UI.ProfileWnd_new.modes[ modeName ]
			UI.ProfileWnd_new:Setup( uid, mode, launchData )
			UI.ProfileWnd_new:UnlinkFromParent()
			UI.ProfileWnd_new:Show()

			if restoreData then
				UI.ProfileWnd_new:RestoreState( restoreData )
			end

		elseif modeName == "ACHIEVEMENTS" or modeName == "MEDALS" or modeName == "LEADERBOARDS" then

			UI.Profile_Wnd:UnlinkFromParent()
			UI.ProfileWnd_new:UnlinkFromParent()

			UI.LeaderboardWnd:UnlinkFromParent()
			UI.LeaderboardWnd:Show()
			UI.LeaderboardWnd:Setup( uid, launchData )

			if modeName ~= nil then
				UI.Leaderboard_TabsWnd:SelectTab( modeName )
			end

		else

			UI.ProfileWnd_new:UnlinkFromParent()
			UI.LeaderboardWnd:UnlinkFromParent()

			UI.Profile_Wnd:UnlinkFromParent()
			UI.Profile_Wnd:Show()
			UI.Profile_Wnd:Setup( uid )
			UI.Profile_Wnd:UpdateMode()

			if modeName ~= nil then
				UI.Profile_TabsWnd:SelectTab( modeName )
			end

		end

		if bSound then
			UI:PlayGlobalSound( UI.HangarWnd.sounds.menuTabSelect )
		end

	end

end


--
function UI:GetPlayerAccountRank()

	local accountRank = _G.MasterServer_GetAccountRank()

	if type( accountRank ) ~= "number" then
		sys.log( "UI:GetPlayerAccountRank()[ERROR]: invalid type of return value from MasterServer_GetAccountRank(); \"number\" expected, got \"%s\"", type( accountRank ) )
		accountRank = 1
	end

	return accountRank

end


--
function UI:GetMaxAccountRank()

	local maxRank = 1

	if type( _G.AccountExpPerRank ) == "table" then
		maxRank = #_G.AccountExpPerRank + 1	-- #0081865,комм.(0364595)
	else
		sys.log( "UI:GetMaxAccountRank()[ERROR]: invalid type of _G.AccountExpPerRank; \"table\" expected, got \"%s\"", type( _G.AccountExpPerRank ) )
	end

	return maxRank

end


--
function UI:GetPlayerAccountRankExpCost( rank )

	local exp = 0

	if type( rank ) ~= "number" then
		sys.log( "UI:GetPlayerAccountRankExpCost()[ERROR]: invalid type of the 1-st parameter (\"rank\"); \"number\" expected, got \"%s\"", type( rank ) )
		return exp
	end

	if type( _G.AccountExpPerRank ) == "table" then

		exp = _G.AccountExpPerRank[ rank - 1 ]

		if type( exp ) ~= "number" then
			sys.log( "UI:GetPlayerAccountRankExpCost()[ERROR]: invalid type of _G.AccountExpPerRank[%d]; \"number\" expected, got \"%s\"", rank - 1, type( exp ) )
			exp = 0
		end

	else
		sys.log( "UI:GetPlayerAccountRankExpCost()[ERROR]: invalid type of _G.AccountExpPerRank; \"table\" expected, got \"%s\"", type( _G.AccountExpPerRank ) )
	end

	return exp

end


--
function UI:GetPlayerAccountExp()

	local exp = _G.MasterServer_GetAccountExpPool()

	if type( exp ) ~= "number" then
		sys.log( "UI:GetPlayerAccountExp()[ERROR]: invalid type of return value from MasterServer_GetAccountExpPool(); \"number\" expected, got \"%s\"", type( exp ) )
		exp = 0
	end

	return exp

end


--
function UI:GetItemAtlasId( defName )

	local atlasId = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemAtlasId()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return atlasId
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemAtlasId()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return atlasId
	end

	if def.atlasId ~= nil then
		if type( def.atlasId ) == "number" then
			atlasId = def.atlasId
		else
			sys.log( "UI:GetItemAtlasId()[ERROR]: invalid type of _G.Def[\"%s\"].atlasId; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.atlasId ) )
		end
	end

	return atlasId

end


--
function UI:IsItemVisibleInAtlas( defName )

	local bVisible = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsItemVisibleInAtlas()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bVisible
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:IsItemVisibleInAtlas()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return bVisible
	end

	if def.is_atlas_entity ~= nil then
		if type( def.is_atlas_entity ) == "boolean" then
			bVisible = def.is_atlas_entity
		else
			sys.log( "UI:IsItemVisibleInAtlas()[ERROR]: invalid type of _G.Def[\"%s\"].is_atlas_entity; \"boolean\" or \"nil\" expected, got \"%s\"", defName, type( def.is_atlas_entity ) )
		end
	end

	return bVisible

end


--
function UI:OnInput()

	if UI.HangarWnd and UI.HangarWnd:IsOnScreen() then
		UI.hangarLastInputTime = _G.TimerGetRealTime()
	end

end


-- #0083817 - хак - надо убрать это из UI
function UI:CheckLogoutOnInactivity()

	if UI.hangarLastInputTime ~= nil then

		if _G.TimerGetRealTime() - UI.hangarLastInputTime > UI.INACTIVITY_LOGOUT_TIME then

    		UI.hangarLastInputTime = nil

			if UI.HangarWnd and UI.HangarWnd:IsOnScreen() then
				if cvars.cl_versionType == "live" then		-- #0083817,комм.(0368996) - только на лайве
					UI.bNeedShowMsgOnInactivity = true
					_G.MasterServer_ClientDisconnect()
				end
			else
				sys.log( "UI:CheckLogoutOnInactivity()[ERROR]: hangar is not on screen" )
			end

		end

	end

end


--
function UI:UpdateBlur()

	local bNeedBlur =
		UI.ProfileWnd_new and UI.ProfileWnd_new.w and UI.ProfileWnd_new:IsOnScreen()
		or UI.BattlePassWnd and UI.BattlePassWnd.w and UI.BattlePassWnd:IsOnScreen()

	cvars.pe_kawaseBlur = bNeedBlur and 1 or 0

end


--
function UI:UpdateDrawStaticAndDynamic()

	local bNeedDraw = not( UI.GameplayPveMapWnd and UI.GameplayPveMapWnd.w and UI.GameplayPveMapWnd:IsOnScreen() )

	cvars.g_drawStatic	= bNeedDraw and 1 or 0
	cvars.g_drawDynamic	= bNeedDraw and 1 or 0

end


--
function UI:GetZoneUnlockRank( zoneId )

	local rank = 1

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetZoneUnlockRank()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return rank
	end

	local zoneDef = _G.SpaceZoneById and _G.SpaceZoneById[ zoneId ]
	if not zoneDef then
		sys.log( "UI:GetZoneUnlockRank()[ERROR]: cannot find def for zone %d", zoneId )
		return rank
	end

	if zoneDef.min_account_rank ~= nil then

		if type( zoneDef.min_account_rank ) == "number" then
			rank = zoneDef.min_account_rank
		else
			sys.log( "UI:GetZoneUnlockRank()[ERROR]: invalid type of \"min_account_rank\" for zone %d; \"number\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneDef.min_account_rank ) )
		end

	end

	return rank

end


