end


--
function UI:GetItemSourceDesc( itemDefName, baseColor, selColor, bLinksAllowed )

	local strDesc = "unknown source"

	if type( itemDefName ) ~= "string" then
		sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of the 1-st parameter (\"itemDefName\"); \"string\" expected, got \"%s\"", type( itemDefName ) )
		return strDesc
	end

	if baseColor ~= nil then
		if type( baseColor ) ~= "number" then
			sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of the 2-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
		end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if selColor ~= nil then
		if type( selColor ) ~= "number" then
			sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of the 3-rd parameter (\"selColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( selColor ) )
			selColor = nil
		end
	end

	if selColor == nil then
		selColor = UI.TEXT_SEL_COLOR
	end

	if bLinksAllowed ~= nil then
		if type( bLinksAllowed ) ~= "boolean" then
			sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of the 4-th parameter (\"bLinksAllowed\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bLinksAllowed ) )
			bLinksAllowed = nil
		end
	end

	if bLinksAllowed == nil then
		bLinksAllowed = false
	end

	-- #0098154 - если это предмет не первый в цепочке апгрейда, то пишем описание для первого предмета в цепочке
	local baseDefName = itemDefName
	if UI:IsDefModule( itemDefName ) then
		baseDefName = UI:GetItemUpgradeBaseDef( itemDefName )
	end

	local def = UI:GetDef( baseDefName )
	if not def then
		sys.log( "UI:GetItemSourceDesc()[ERROR]: cannot find _G.Def[\"%s\"]", baseDefName )
		return strDesc
	end

	if def.source_desc ~= nil then
		if type( def.source_desc ) ~= "string" then
			sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of _G.Def[\"%s\"].source_desc; \"string\" expected, got \"%s\"", baseDefName, type( def.source_desc ) )
			return strDesc
		end
	end

	local bundleDefName = nil

	if def.source_desc then

		local sourceDescStrId = string.format( "sourceDesc_%s", def.source_desc )
		strDesc = UI:GetStringByName( sourceDescStrId )

		local function fnSubst( capture )

			local strSubst = nil

			-- бандл, в котором лежит предмет
			if capture == "bundle" then

				strSubst = "unknown"

				if bundleDefName == nil then -- мог быть уже найден при обработке плэйсхолдера $bundle_source$
					bundleDefName = UI:GetBundleForItem( baseDefName, false )
					if bundleDefName == "" then
						sys.log( "UI:GetItemSourceDesc()[ERROR]: cannot find bundle for \"%s\"", baseDefName )
					end
				end

				if bundleDefName ~= "" then

					if bLinksAllowed then
						strSubst = string.format( "$link [type ITEM] [params {defName=\"%s\"}]$", bundleDefName )
					else
						strSubst = UI:GetEntityLocalizedNameByDef( bundleDefName, true, false )
						strSubst = string.format( "%s%s", strSubst, UI:Color2Str( baseColor ) )
					end

				end

			-- источник для бандла, в котором лежит предмет
			elseif capture == "bundle_source" then

				if bundleDefName == nil then	-- мог быть уже найден при обработке плэйсхолдера $bundle$
					bundleDefName = UI:GetBundleForItem( baseDefName, false )
					if bundleDefName == "" then
						sys.log( "UI:GetItemSourceDesc()[ERROR]: cannot find bundle for \"%s\"", baseDefName )
					end
				end

				local bundleSourceFound = false

				if bundleDefName ~= "" then

					-- для анлока бандла требуется аура?
					local bundleRequiredAura = UI:GetAccountAuraToUnlockItem( bundleDefName )
					if bundleRequiredAura ~= "" then

						-- ищем ауру в квестах

						if type( _G.Quests ) == "table" then
							for questId, questInfo in pairs( _G.Quests ) do
								if type( questId ) == "number" and type( questInfo ) == "table" then
									if not UI:IsQuestDisabled( questId ) then
										if type( questInfo.reward_account_aura ) == "string" then

											if questInfo.reward_account_aura == bundleRequiredAura then

												strSubst = UI:GetStringByName( "sourceBundleDesc_quest" )

												-- подставляем ссылку на категорию квеста
												local strQuestCategory = "unknown"

												local questCategory = UI:GetQuestCategory( questId )
												if questCategory ~= -1 then

													if bLinksAllowed then
														strQuestCategory = string.format( "$link [type QUEST_CATEGORY] [params {category=%d}]$", questCategory )
													else
														strQuestCategory = UI:QuestCategory2Str( questCategory )
														strQuestCategory = string.format( "%s%s%s", UI:Color2Str( selColor ), strQuestCategory, UI:Color2Str( baseColor ) )
													end

												else
													sys.log( "UI:GetItemSourceDesc()[ERROR]: cannot find category for quest %d", questId )
												end

												local numSubst = 0
												strSubst, numSubst = string.gsub( strSubst, "%$quest%$", strQuestCategory )
												if numSubst == 0 then
													sys.log( "UI:GetItemSourceDesc()[ERROR]: cannot find placeholder \"$quest$\" in string \"sourceBundleDesc_quest\"" )
													strSubst = string.format( "[ERROR STRING]Available in a quest of category %s", strQuestCategory )
												end

												bundleSourceFound = true
												break

											end

										elseif questInfo.reward_account_aura ~= nil then
											sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of _G.Quests[%d].reward_account_aura; \"string\" or nil expected, got \"%s\"", questId, type( questInfo.reward_account_aura ) )
										end
									end
								else
									sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid format of _G.Quests; <number>=<table> expected, got <%s>=<%s>", type( questId ), type( questInfo ) )
								end
							end
						else
							sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of _G.Quests; \"table\" expected, got \"%s\"", type( _G.Quests ) )
						end

						-- ищем ауру в луте

						if not bundleSourceFound then

							if type( _G.LootTable ) == "table" then
								for lootBlockName, lootBlockInfo in pairs( _G.LootTable ) do

									if type( lootBlockName ) == "string" and type( lootBlockInfo ) == "table" then
										for lootItemIdx, lootItemInfo in pairs( lootBlockInfo ) do
											if type( lootItemIdx ) == "number" and type( lootItemInfo ) == "table" then
												if type( lootItemInfo.aura ) == "string" then

													if lootItemInfo.aura == bundleRequiredAura then
														strSubst = UI:GetStringByName( "sourceBundleDesc_loot" )
														bundleSourceFound = true
														break
													end

												elseif lootItemInfo.aura ~= nil then
													sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of _G.LootTable[%s][%d].aura; \"string\" or nil expected, got \"%s\"", lootBlockName, lootItemIdx, type( lootItemInfo.aura ) )
												end
											else
												sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid format of _G.LootTable.%s; <number>=<table> expected, got <%s>=<%s>", lootBlockName, type( lootItemIdx ), type( lootItemInfo ) )
											end
										end
									else
										sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid format of _G.LootTable; <string>=<table> expected, got <%s>=<%s>", type( lootBlockName ), type( lootBlockInfo ) )
									end

									if bundleSourceFound then
										break
									end

								end
							else
								sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of _G.LootTable; \"table\" expected, got \"%s\"", type( _G.LootTable ) )
							end

						end

					end

				end

				-- источник для бандла не найден
				if not bundleSourceFound then
					strSubst = UI:GetStringByName( "sourceBundleDesc_unknown" )
				end

			-- подстановка имени зоны, где можно добыть предмет, которая прописана в дефе предмета
			elseif capture == "source_zone" then

				if type( def.source_zone ) == "string" then

					if _G.SpaceZone[ def.source_zone ] then

						strSubst = UI:Zone2Str( def.source_zone )
						strSubst = string.format( "%s%s%s", UI:Color2Str( selColor ), strSubst, UI:Color2Str( baseColor ) )

					else
						sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid zone name ('%s') in Def['%s'].source_zone, no zone found with this name", def.source_zone, baseDefName )
					end

				else
					sys.log( "UI:GetItemSourceDesc()[ERROR]: invalid type of Def['%s'].source_zone; \"string\" expected, got \"%s\"", type( def.source_zone ) )
				end

			-- подстановка имени произвольного дефа
			elseif UI:GetDef( capture, false ) then

				strSubst = UI:GetEntityLocalizedNameByDef( capture, true, false, nil, nil, false )
				strSubst = string.format( "%s%s", strSubst, UI:Color2Str( baseColor ) )

			-- подстановка имени произвольной зоны
			elseif _G.SpaceZone[ capture ] then

				strSubst = UI:Zone2Str( capture )
				strSubst = string.format( "%s%s%s", UI:Color2Str( selColor ), strSubst, UI:Color2Str( baseColor ) )

			end

			return strSubst

		end

		strDesc = string.gsub( strDesc, "%$([%w_]+)%$", fnSubst )
		strDesc = string.format( "%s%s", UI:Color2Str( baseColor ), strDesc )

	else

		if UI:IsDefBlueprint( baseDefName ) then
			strDesc = UI:IsItemTrading( baseDefName ) and UI:GetStringByName( "itemCraft_cantBeBought_trading" ) or UI:GetStringByName( "itemCraft_cantBeBought" )
			strDesc = string.format( "%s%s", UI:Color2Str( baseColor ), strDesc )
		else
			strDesc = ""	-- #0091128, комм.(0415423) - если источник не прописан, то ничего не пишется
		end

	end

	-- #0098154 - если это предмет не первый в цепочке апгрейда, то к описанию, которое взято от первого предмета, добавляется строка, что надо апгрейдить
	if strDesc ~= "" and baseDefName ~= itemDefName then
		local strNeedUpgrade = UI:GetStringByName( "source_upgrade" )
		strDesc = string.format( "%s|%s", strDesc, strNeedUpgrade )
	end

	return strDesc

end


--
function UI:GetItemSourceZone( defName )

	local zoneId = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemSourceZone()[ERROR]: invalid type of the 1-st param ('defName'); 'string' expected, got '%s'", type( defName ) )
		return zoneId
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetItemSourceZone()[ERROR]: cannot find def for '%s'", defName )
		return zoneId
	end

	if def.source_zone ~= nil then

		if type( def.source_zone ) == "string" then

			zoneId = UI:ZoneName2Id( def.source_zone )
			if zoneId == -1 then
				sys.log( "UI:GetItemSourceZone()[ERROR]: cannot find zoneId for '%s'", def.source_zone )
			end

		else
			sys.log( "UI:GetItemSourceZone()[ERROR]: invalid type of _G.Def['%s'].source_zone; 'string' or 'nil' expected, got '%s'", defName, type( def.source_zone ) )
		end

	end

	return zoneId

end


--
function UI:IsUniverseZone( zoneId )

	local bUniverse = false

	if type( zoneId ) ~= "number" then
		sys.log( "UI:IsUniverseZone()[ERROR]: invalid type of the 1-st parameter (\"zoneId\"); \"number\" expected, got \"%s\"", type( zoneId ) )
		return bUniverse
	end

	if type( _G.SpaceZoneById ) ~= "table" then
		sys.log( "UI:IsUniverseZone()[ERROR]: invalid type of _G.SpaceZoneById; \"table\" expected, got \"%s\"", type( _G.SpaceZoneById ) )
		return bUniverse
	end

	local zoneDef = _G.SpaceZoneById[ zoneId ]
	if type( zoneDef ) ~= "table" then
		sys.log( "UI:IsUniverseZone()[ERROR]: invalid type of the _G.SpaceZoneById[%d]; \"table\" expected, got \"%s\"", zoneId, type( zoneDef ) )
		return bUniverse
	end

	if zoneDef.universe_zone ~= nil then
		if type( zoneDef.universe_zone ) == "boolean" then
			bUniverse = zoneDef.universe_zone
		else
			sys.log( "UI:IsUniverseZone()[ERROR]: invalid type of the _G.SpaceZoneById[%d].universe_zone; \"boolean\" or \"nil\" expected, got \"%s\"", zoneId, type( zoneDef.universe_zone ) )
		end
	end

	return bUniverse

end


--
function UI:GetItemInfluenceColor( defName )

	local color = nil

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemInfluenceColor()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return color
	end

	local def = UI:GetDef( defName )

	if not def then
		sys.log( "UI:GetItemInfluenceColor()[ERROR]: cannot find _G.Def[\"%s\"]", defName )
		return color
	end

	if def.influence_type_color ~= nil then
		if type( def.influence_type_color ) == "number" then
			color = def.influence_type_color
		else
			sys.log( "UI:GetItemInfluenceColor()[ERROR]: invalid type of _G.Def[\"%s\"].influence_type_color; \"number\" or \"nil\" expected, got \"%s\"", defName, type( def.influence_type_color ) )
		end
	end

	return color

end


--
function UI:GetAuraInfluenceColor( auraId, isBuff )

	local color = nil

	if type( auraId ) ~= "number" then
		sys.log( "UI:GetAuraInfluenceColor()[ERROR]: invalid type of the 1-st parameter (\"auraId\"); \"number\" expected, got \"%s\"", type( auraId ) )
		return color
	end

	if type( isBuff ) ~= "boolean" then
		sys.log( "UI:GetAuraInfluenceColor()[ERROR]: invalid type of the 2-nd parameter (\"isBuff\"); \"boolean\" expected, got \"%s\"", type( isBuff ) )
		return color
	end

	if type( _G.AuraTypeColor ) ~= "table" then
		sys.log( "UI:GetAuraInfluenceColor()[ERROR]: invalid type of _G.AuraTypeColor; \"table\" expected, got \"%s\"", type( _G.AuraTypeColor ) )
		return color
	end

	for infoIdx, info in pairs( _G.AuraTypeColor ) do

		if type( info ) == "table" then

			if type( info.aura ) == "number" and type( info.isBuff ) == "boolean" and type( info.color ) == "number" then

				if info.aura == auraId and info.isBuff == isBuff then
					color = info.color
					break
				end

			else
				sys.log( "UI:GetAuraInfluenceColor()[ERROR]: invalid format of _G.AuraTypeColor[%s]; { aura=<number>, isBuff=<boolean>, color=<number> } expected", tostring( infoIdx ) )
			end

		else
			sys.log( "UI:GetAuraInfluenceColor()[ERROR]: invalid type of _G.AuraTypeColor[%s]; \"table\" expected, got \"%s\"", tostring( infoIdx ) )
		end

	end

	return color

end


--
function UI:GetAccountRankTooltipData( rank, exp )

	local tooltipData = nil

	if rank ~= nil then
		if type( rank ) ~= "number" then
			sys.log( "UI:GetAccountRankTooltipData()[ERROR]: invalid type of the 1-st parameter (\"rank\"); \"number\" expected, got \"%s\"", type( rank ) )
			return tooltipData
		end
	end

	if exp ~= nil then
		if type( exp ) ~= "number" then
			sys.log( "UI:GetAccountRankTooltipData()[ERROR]: invalid type of the 2-nd parameter (\"exp\"); \"number\" expected, got \"%s\"", type( exp ) )
			return tooltipData
		end
	end

	if rank == nil then
		rank = UI:GetPlayerAccountRank()
	end

	if exp == nil then
		exp = UI:GetPlayerAccountExp()
	end


	local text = UI:GetStringByName( "hangar_exp_tooltipText" )

	local maxRank = UI:GetMaxAccountRank()
	if rank < maxRank then

		-- значение опыта

		local nextRankCost = UI:GetPlayerAccountRankExpCost( rank + 1 )
		local expClamped = math.min( exp, nextRankCost )

		local strExpOvercap = ""

		if expClamped < exp then

			local expOvercap = exp - expClamped
			local strExpOvercapVal = UI:Num2StrSeparatedBy3( expOvercap )

			strExpOvercap = UI:GetStringByName( "profile_rank_overcap" )

			local numSubst = 0
			strExpOvercap, numSubst = string.gsub( strExpOvercap, "%$val%$", strExpOvercapVal )

			if numSubst == 0 then
				sys.log( "UI:GetAccountRankTooltipData()[ERROR]: cannot find placeholder \"$val$\" in string \"profile_rank_overcap\"" )
				strExpOvercap = string.format( "[INVALID STRING] overcap %s", strExpOvercapVal )
			end

			strExpOvercap = string.format( " (%s)", strExpOvercap )

		end

    	local strExp = string.format( "%s: %s/%s%s", UI:GetStringByName( "hangar_exp_tooltipText_expLabel" ), UI:Num2StrSeparatedBy3( expClamped ), UI:Num2StrSeparatedBy3( nextRankCost ), strExpOvercap )
		text = string.format( "%s||%s", text, strExp )

		-- информация, как получить новый ранг

		if exp >= nextRankCost then

			local strGetRankInfo = UI:GetStringByName( "hangar_exp_tooltipText_getRankInfo" )
			strGetRankInfo = string.format( "%s%s%s", UI:Color2Str( UI.GOLD_COLOR ), strGetRankInfo, UI:Color2Str( UI.TooltipWnd_shared:GetTextColor() ) )

			text = string.format( "%s||%s", text, strGetRankInfo )

		end

	end

	tooltipData =
	{
		tooltipType	= UI.tooltipTypes.TEXT_LARGE,
		caption		= UI:GetStringByName( "hangar_exp_tooltipCaption"),
		text		= text,
	}

	return tooltipData

end


