--
function UI:LaunchTestDrive( shipDefName )

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:LaunchTestDrive()[ERROR]: fail to run test-drive - invalid type of the 1-st parameter (\"shipDefName\"); \"string\" expected, got \"%s\"", type( shipDefName ) )
		return
	end

	local spawnData = UI:GetShipTestDriveSpawnData( shipDefName )
	if not next( spawnData ) then
		sys.log( "UI:LaunchTestDrive()[ERROR]: fail to run test-drive - cannot make ship spawn data" )
		return
	end

	UI.bNeedSetTestDriveNextStart = true
	UI:LaunchSinglePractice( false, UI.testDriveParams.mapName, ai.Gameplay[ UI.testDriveParams.gameplay ], UI.testDriveParams.numBots, spawnData )

end


--
function UI:LaunchFirstFight()

	UI.serverData.userData.firstFightDone = true
	UI:SaveServerUserData()

	UI:LaunchSinglePractice( true, UI.firstFightParams.mapName, ai.Gameplay[ UI.firstFightParams.gameplay ], UI.firstFightParams.numBots, nil )

end


--
function UI:LaunchSinglePractice( bShowDebriefing, mapName, gameplay, numBots, shipSpawnData --[[опциональный]] )

	if type( bShowDebriefing ) ~= "boolean" then
		sys.log( "UI:LaunchSinglePractice()[ERROR]: invalid type of the 1-st parameter (\"bShowDebriefing\"); \"boolean\" expected, got \"%s\"", type( bShowDebriefing ) )
		bShowDebriefing = false
	end

	UI.bShowDebriefingAfterPractice = bShowDebriefing

	if shipSpawnData then
		_G.MasterServer_LaunchSinglePlayerPractice( mapName, gameplay, numBots, 0--[[раса - не используется]], shipSpawnData )
	else
		_G.MasterServer_LaunchSinglePlayerPractice( mapName, gameplay, numBots, 0--[[раса - не используется]] ) -- если shipSpawnData=nil, то ее нельзя передать, т.к. заругается на тип
	end

end


--
function UI:NeedFirstFight()

	--#0099737(0500865) - убран "первый бой"
	if true then
		return false
	end

	if not _G.MasterServer_IsConnected() then
		return false
	end

	if UI:IsTrueEx( UI.serverData.userData.firstFightDone ) then
		return false
	end

	-- игрок уже играл в настоящую битву (pvp)? эта проверка актуальна для старых игроков, у которых в принципе не может быть поля userdata.firstFightDone
	local stats = _G.MasterServer_UserProfileGet( UI:GetLocalPlayerUid() ).generalStats
	local battlesFought = stats and stats[ MasterServer.UserProfileGeneralStat.UPGS_NUM_VICTORIES ] or u64( 0 )

	if battlesFought > u64( 0 )	 then
		return false
	end

	return true

end


