--
function UI:UpdateMyAdverts()

	UI.serverData.myAdverts = {}

	local myAdverts = _G.MasterServer_MyAdvertGet()

	if UI:IsMyAdvertsDataValid( myAdverts ) then
		UI.serverData.myAdverts = myAdverts
	end

	self.serverData.bInvItemsDirty = true
	self:UpdateInvItems()

end


--
function UI:IsMyAdvertsDataValid( adverts )

	if type( adverts ) ~= "table" then
		sys.log( "UI:IsMyAdvertsDataValid()[ERROR]: invalid type of return value from MasterServer_MyAdvertGet(); \"table\" expected, got \"%s\"", type( adverts ) )
		return false
	end

	for idx, advert in pairs( adverts ) do

		if type( advert ) ~= "table" then
			sys.log( "UI:IsMyAdvertsDataValid()[ERROR]: invalid type of advert data; \"table\" expected, got \"%s\"", type( advert ) )
			return false
		end

		if type( advert.advertId ) ~= "userdata" then
			sys.log( "UI:IsMyAdvertsDataValid()[ERROR]: invalid type of field \"advertId\"; \"userdata\" expected, got \"%s\"", type( advert.advertId ) )
			return false
		end

		if type( advert.def ) ~= "string" then
			sys.log( "UI:IsMyAdvertsDataValid()[ERROR]: invalid type of field \"def\"; \"string\" expected, got \"%s\"", type( advert.def ) )
			return false
		end

		if type( advert.goldPrice ) ~= "number" then
			sys.log( "UI:IsMyAdvertsDataValid()[ERROR]: invalid type of field \"goldPrice\"; \"number\" expected, got \"%s\"", type( advert.goldPrice ) )
			return false
		end

		if type( advert.expTime ) ~= "userdata" then
			sys.log( "UI:IsMyAdvertsDataValid()[ERROR]: invalid type of field \"expTime\"; \"userdata\" expected, got \"%s\"", type( advert.expTime ) )
			return false
		end

		if type( advert.iid ) ~= "userdata" then
			sys.log( "UI:IsMyAdvertsDataValid()[ERROR]: invalid type of field \"iid\"; \"userdata\" expected, got \"%s\"", type( advert.iid ) )
			return false
		end

		if type( advert.amount ) ~= "number" then
			sys.log( "UI:IsMyAdvertsDataValid()[ERROR]: invalid type of field \"amount\"; \"number\" expected, got \"%s\"", type( advert.amount ) )
			return false
		end

	end

	return true

end


--
function UI:IsItemAdverted( iid )

	local bAdverted = false

	if type( iid ) ~= "userdata" then
		sys.log( "UI:IsItemAdverted()[ERROR]: invalid 1-st param ('iid'); 'userdata' expected, got '%s'", type( iid ) )
		return bAdverted
	end

	if iid == UI.INVALID_U64_ID then
		sys.log( "UI:IsItemAdverted()[ERROR]: invalid iid" )
		return bAdverted
	end

	for advertIdx, advert in pairs( UI.serverData.myAdverts ) do
		if advert.iid == iid then
			bAdverted = true
			break
		end
	end

	return bAdverted

end


--
function UI:GetResourceAdvertedCount( defName )

	local advertedCount = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetResourceAdvertedCount()[ERROR]: invalid 1-st param ('defName'); 'string' expected, got '%s'", type( defName ) )
		return advertedCount
	end

	if defName == "" then
		sys.log( "UI:GetResourceAdvertedCount()[ERROR]: invalid defName" )
		return advertedCount
	end

	for advertIdx, advert in pairs( UI.serverData.myAdverts ) do
		if advert.def == defName then
			advertedCount = advertedCount + advert.amount
		end
	end

	return advertedCount

end


--
function UI:GetMyAdvertsByDef( defName )

	local myAdvertsByDef = {}

	if type( defName ) ~= "string" then
		sys.log( "UI:GetMyAdvertsByDef()[ERROR]: invalid 1-st param ('defName'); 'string' expected, got '%s'", type( defName ) )
		return myAdvertsByDef
	end

	for advertIdx, advert in pairs( UI.serverData.myAdverts ) do
		if advert.def == defName then
			table.insert( myAdvertsByDef, advert )
		end
	end

	return myAdvertsByDef

end


-- награда за бой с учетом тех денег, которые были получены за автопродажу джанка и продажу предметов из лута
function UI:CalcFullGameRewardWithLoot( debriefingData, lootItems )

	local credits = 0

	if type( debriefingData ) ~= "table" then
		sys.log( "UI:CalcFullGameRewardWithLoot()[ERROR]: invalid type of the 1-st parameter (\"debriefingData\"); \"table\" expected, got \"%s\"", type( debriefingData ) )
		return credits
	end

	if lootItems ~= nil then
		if type( lootItems ) ~= "table" then
			sys.log( "UI:CalcFullGameRewardWithLoot()[ERROR]: invalid type of the 2-nd parameter (\"lootItems\"); \"table\" or \"nil\" expected, got \"%s\"", type( lootItems ) )
			lootItems = nil
		end
	end

	if lootItems == nil then
		lootItems = {}
	end

	local uid = UI:GetLocalPlayerUid()

	local palyerData = nil

	if type( debriefingData.players ) == "table" then
		for playerIdx, _playerData in pairs( debriefingData.players ) do
			if type( playerIdx ) == "number" and type( _playerData ) == "table" then
				if _playerData.uid ~= nil then
					if type( _playerData.uid ) == "userdata" then

						if _playerData.uid == uid then
							palyerData = _playerData
							break
						end

					else
						sys.log( "UI:CalcFullGameRewardWithLoot()[ERROR]: invalid type of field players[%d].uid; \"userdata\" or \"nil\" expected, got \"%s\"", playerIdx, type( _playerData.uid ) )
					end
				end
			else
				sys.log( "UI:CalcFullGameRewardWithLoot()[ERROR]: invalid format of field \"players\"; <number>=<table> expected, got <%s>=<%s>", type( playerIdx ), type( _playerData ) == "table" )
			end
		end
	else
		sys.log( "UI:CalcFullGameRewardWithLoot()[ERROR]: invalid type of field \"players\"; \"table\" expected, got \"%s\"", type( debriefingData.players ) )
	end

	if not palyerData then
		sys.log( "UI:CalcFullGameRewardWithLoot()[ERROR]: cannot find data for local player" )
		return credits
	end

	-- награда за бой
	if type( palyerData.credits ) == "number" then
		credits = palyerData.credits
	else
		sys.log( "UI:CalcFullGameRewardWithLoot()[ERROR]: invalid type of field \"credits\" in debriefingData for local player; \"number\" expected, got \"%s\"", type( palyerData.credits ) )
	end

	-- лут
	for itemIdx, item in pairs( lootItems ) do
		if type( itemIdx ) == "number" and type( item ) == "table" then
			if item.creditsEarned ~= nil then

				if type( item.creditsEarned ) == "number" then
					credits = credits + item.creditsEarned
				else
					sys.log( "UI:CalcLootRefund()[ERROR]: invalid type of field \"creditsEarned\" in lootItems[%d]; \"number\" or \"nil\" expected, got \"%s\"", itemIdx, type( item.creditsEarned ) )
				end

			end
		else
			sys.log( "UI:CalcLootRefund()[ERROR]: invalid format of lootItems; <number>=<table> expected, got <%s>=<%s>", type( itemIdx ), type( item ) )
		end
	end

	return credits

end


--
function UI:OnLootCompleted( lootItems )

	UI.lootItems = lootItems
	UI:CheckModidyGameRewardNotification()

	UI.HangarWnd:OnLootCompleted( lootItems )

end


-- #0098688 - хак: в награду включается лут
function UI:CheckModidyGameRewardNotification()

	if not UI.debriefingData or not UI.lootItems then
		return
	end

	for ntfId = UI.Notifications:GetLastNotificationIdTotal(), UI.Notifications:GetFirstNotificationId(), -1 do

		if UI.lastNotificationIdOnLevelStart ~= -1 and ntfId <= UI.lastNotificationIdOnLevelStart then
			break
		end

		local ntf = UI.Notifications:GetNotificationTotal( ntfId )

		if ntf.type == UI.Notifications.types.SN_GAME_REWARDED then
			ntf.params.credits = UI:CalcFullGameRewardWithLoot( UI.debriefingData, UI.lootItems )
			break
		end

	end

end


