--
function UI:UpdateServerData_OnUserProfileUpdate( result, requestId, uid, field )

	if result == 0 then

		if uid == UI:GetLocalPlayerUid() then

			if field == _G.MasterServer.UserProfileField.UPF_ATLAS then

				sys.log( "UI:UpdateServerData_OnUserProfileUpdate: atlas update" )

				self.serverData.atlas = nil

				local profile = _G.MasterServer_UserProfileGet( UI:GetLocalPlayerUid() )
				if profile then

					if profile.atlas ~= nil then
						if type( profile.atlas ) == "table" then
							self.serverData.atlas = profile.atlas
						else
							sys.log( "UI:UpdateServerData_OnUserProfileUpdate()[ERROR]: invalid type of \"atlas\"; \"table\" or \"nil\" expected, got \"%s\"", type( profile.atlas ) )
						end
					end

				end

			end

		end

	end

end


--
function UI:GetItemAtlasLevel( defName )

	local level = -1

	if type( defName ) ~= "string" then
		sys.log( "UI:GetItemAtlasLevel()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return level
	end

	local atlasId = UI:GetItemAtlasId( defName )
	if atlasId == -1 then
		sys.log( "UI:GetItemAtlasLevel()[ERROR]: \"%s\" has no atlas id", defName )
		return level
	end

	local atlas = self.serverData.atlas
	if atlas then

		local atlasModules = nil

		if type( atlas.modules ) == "table" then

			if type( atlas.modules.lvls ) == "table" then
				atlasModules = atlas.modules.lvls
			else
				sys.log( "UI:GetItemAtlasLevel()[ERROR]: invalid typpe of atlas.modules.lvls; \"table\" expected, got \"%s\"", type( atlas.modules.lvls ) )
			end

		else
			sys.log( "UI:GetItemAtlasLevel()[ERROR]: invalid typpe of atlas.modules; \"table\" expected, got \"%s\"", type( atlas.modules ) )
		end

		if atlasModules then
			if atlasModules[ atlasId ] ~= nil then
				if type( atlasModules[ atlasId ] ) == "number" then
					level = atlasModules[ atlasId ]
				else
					sys.log( "UI:GetItemAtlasLevel()[ERROR]: invalid format of atlas.modules.lvls[%d]; \"number\" or \"nil\" expected, got \"%s\"", atlasId, type( atlasModules[ atlasId ] ) )
				end
			end
		end

	end

	return level

end


