function UI:GetUnlimPveBuffResourcePrice( buffId )

	local defName	= ""
	local count		= 0

	local priceTable = _G.MasterServer_UnlimPveGetPlayerLevelUpgradeCost( buffId )

	if type( priceTable ) ~= "table" then
		sys.log( "UI:GetUnlimPveBuffResourcePrice()[ERROR]: invalid type of return value from MasterServer_UnlimPveGetPlayerLevelUpgradeCost(); 'table' expected, got '%s'", type( priceTable ) )
		return defName, count
	end

	if type( priceTable.resource ) ~= "table" then
		sys.log( "UI.Pve_UpgradeBuffsWnd:UpdateResourceIco()[ERROR]: invalid type of 'resource'; 'table' expected, got '%s'", priceTable.resource )
		return defName, count
	end

	if type( priceTable.resource.defName ) ~= "string" then
		sys.log( "UI.Pve_UpgradeBuffsWnd:UpdateResourceIco()[ERROR]: invalid type of 'resource.defName'; 'string' expected, got '%s'", priceTable.resource.defName )
		return defName, count
	end

	if type( priceTable.resource.amount ) ~= "number" then
		sys.log( "UI.Pve_UpgradeBuffsWnd:UpdateResourceIco()[ERROR]: invalid type of 'resource.amount'; 'number' expected, got '%s'", priceTable.resource.amount )
		return defName, count
	end

	defName	= priceTable.resource.defName
	count	= priceTable.resource.amount

	return defName, count

end


