-- подставляются парамтеры дельты за уровень
function UI:GetUnlimPveBuffUpgradeDesc( buffId, baseColor )

	local str = "error"

	if type( buffId ) ~= "number" then
		sys.log( "UI:GetUnlimPveBuffUpgradeDesc()[ERROR]: invalid type of the 1-st parameter (\"buffId\"); \"number\" expected, got \"%s\"", type( buffId ) )
		return str
	end

	if baseColor ~= nil then
		if type( baseColor ) ~= "number" then
			sys.log( "UI:GetUnlimPveBuffUpgradeDesc()[ERROR]: invalid type of the 2-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
		end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	local selColor = UI.TEXT_SEL_COLOR


	local function fnSubst( capture )

		local modifier = 0

		local spellName = string.match( capture, "^spell_([%w_]+)$" )
		if spellName then
			modifier = UI:GetUnlimPveBuffModifierPerLevel( buffId, spellName, true )
		else
			modifier = UI:GetUnlimPveBuffModifierPerLevel( buffId, capture, false )
		end

		local valPercent = math.abs( modifier ) * 100
		valPercent = UI:Round( valPercent )
		return string.format( "%s%d%%%s", UI:Color2Str( selColor ), valPercent, UI:Color2Str( baseColor ) )

	end

	local strName = string.format( "unlimPveBuff_%d_desc", buffId )
	str = UI:GetStringByName( strName )
	str = string.gsub( str, "%$([%w_]+)%$", fnSubst )

	return str

end


-- подставляются актуальные параметры баффа
function UI:GetUnlimPveBuffDesc( buffId, baseColor )

	local str = "error"

	if type( buffId ) ~= "number" then
		sys.log( "UI:GetUnlimPveBuffDesc()[ERROR]: invalid type of the 1-st parameter (\"buffId\"); \"number\" expected, got \"%s\"", type( buffId ) )
		return str
	end

	if baseColor ~= nil then
		if type( baseColor ) ~= "number" then
			sys.log( "UI:GetUnlimPveBuffDesc()[ERROR]: invalid type of the 2-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
			baseColor = nil
		end
	end

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	local selColor = UI.TEXT_SEL_COLOR


	local function fnSubst( capture )

		local val = 0

		local spellName = string.match( capture, "^spell_([%w_]+)$" )
		if spellName then
			val = UI:GetUnlimPveBuffModifier( buffId, spellName, true )
		else
			val = UI:GetUnlimPveBuffModifier( buffId, capture, false )
		end

		val = math.abs( val ) * 100

		--#0105400 чтобы число одинаково форматировалось в окне пве в ангаре и в аурах в худе
		val = UI:FixParamVal( {}, val, false )
		local strVal = UI:ParamVal2Str( {}, val )

		return string.format( "%s%s%%%s", UI:Color2Str( selColor ), strVal, UI:Color2Str( baseColor ) )

	end

	local strName = string.format( "unlimPveBuff_%d_desc_actual", buffId )
	str = UI:GetStringByName( strName )
	str = string.gsub( str, "%$([%w_]+)%$", fnSubst )

	return str

end


--
function UI:GetUnlimPveBuffDef( buffId )

	local buffDef = nil

	if type( buffId ) ~= "number" then
		sys.log( "UI:GetUnlimPveBuffDef()[ERROR]: invalid type of the 1-st parameter (\"buffId\"); \"number\" expected, got \"%s\"", type( buffId ) )
		return buffDef
	end

	if type( _G.UnlimitedPvE ) ~= "table" then
		sys.log( "UI:GetUnlimPveBuffDef()[ERROR]: invalid type of '_G.UnlimitedPvE'; 'table' expected, got '%s'", type( _G.UnlimitedPvE ) )
		return buffDef
	end

	local buffTableName = ""
	if buffId == 1 then
		buffTableName = "player_buff_per_level_1"
	elseif buffId == 2 then
		buffTableName = "player_buff_per_level_2"
	else
		sys.log( "UI:GetUnlimPveBuffDef()[ERROR]: unhandled buffId (%d)", buffId )
	end

	if buffTableName ~= "" then
		if type( _G.UnlimitedPvE[ buffTableName ] ) == "table" then
			buffDef = _G.UnlimitedPvE[ buffTableName ]
		else
			sys.log( "UI:GetUnlimPveBuffDef()[ERROR]: invalid type of _G.UnlimitedPvE['%s']; 'table' expected, got '%s'", buffTableName, type( _G.UnlimitedPvE[ buffTableName ] ) )
		end
	end

	return buffDef

end


--
function UI:GetUnlimPveBuffModifierPerLevel( buffId, modifierName, bSpell )

	local modifierPerLevel = 0

	if type( buffId ) ~= "number" then
		sys.log( "UI:GetUnlimPveBuffModifierPerLevel()[ERROR]: invalid type of the 1-st parameter (\"buffId\"); \"number\" expected, got \"%s\"", type( buffId ) )
		return modifierPerLevel
	end

	if type( modifierName ) ~= "string" then
		sys.log( "UI:GetUnlimPveBuffModifierPerLevel()[ERROR]: invalid type of the 2-nd parameter (\"modifierName\"); \"string\" expected, got \"%s\"", type( modifierName ) )
		return modifierPerLevel
	end

	if bSpell ~= nil then
		if type( bSpell ) ~= "boolean" then
			sys.log( "UI:GetUnlimPveBuffModifierPerLevel()[ERROR]: invalid type of the 3-rd parameter (\"bSpell\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bSpell ) )
			return modifierPerLevel
		end
	else
		bSpell = false
	end

	local buffDef = UI:GetUnlimPveBuffDef( buffId )
	if not buffDef then
		sys.log( "UI:GetUnlimPveBuffModifierPerLevel()[ERROR]: cannot find def for buff %d", buffId )
		return modifierPerLevel
	end

	if bSpell then

		if type( buffDef.spells ) == "table" then

			modifierPerLevel = buffDef.spells[ modifierName ]

			if type( modifierPerLevel ) ~= "number" then
				sys.log( "UI:GetUnlimPveBuffModifierPerLevel()[ERROR]: invalid type of spells['%s'] for buff %d; 'number' expected, got '%s'", modifierName, buffId, type( modifierPerLevel ) )
				modifierPerLevel = nil
			end

		else
			sys.log( "UI:GetUnlimPveBuffModifierPerLevel()[ERROR]: invalid type of 'spells' for buff %d; 'table' expected, got '%s'", buffId, type(  buffDef.spells ) )
		end

	else

		modifierPerLevel = buffDef[ modifierName ]

		if type( modifierPerLevel ) ~= "number" then
			sys.log( "UI:GetUnlimPveBuffModifierPerLevel()[ERROR]: invalid type of '%s' for buff %d; 'number' expected, got '%s'", modifierName, buffId, type( modifierPerLevel ) )
			modifierPerLevel = nil
		end

	end

	return modifierPerLevel

end


--
function UI:GetUnlimPveBuffModifier( buffId, modifierName, bSpell )

	local modifier = 0

	if type( buffId ) ~= "number" then
		sys.log( "UI:GetUnlimPveBuffModifier()[ERROR]: invalid type of the 1-st parameter (\"buffId\"); \"number\" expected, got \"%s\"", type( buffId ) )
		return modifier
	end

	if type( modifierName ) ~= "string" then
		sys.log( "UI:GetUnlimPveBuffModifier()[ERROR]: invalid type of the 2-nd parameter (\"modifierName\"); \"string\" expected, got \"%s\"", type( modifierName ) )
		return modifier
	end

	if bSpell ~= nil then
		if type( bSpell ) ~= "boolean" then
			sys.log( "UI:GetUnlimPveBuffModifier()[ERROR]: invalid type of the 3-rd parameter (\"bSpell\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bSpell ) )
			return modifier
		end
	else
		bSpell = false
	end

	local modifierPerLevel = UI:GetUnlimPveBuffModifierPerLevel( buffId, modifierName, bSpell )
	local level = UI:GetUnlimPveBuffLevel( buffId )

	modifier = UI:UnlimPveModifierPerLevel2Modifier( modifierPerLevel, level )
	return modifier

end


-- в формате: 1.1 - увеличение на 10%, 0.9 - уменьшение на 10%
function UI:UnlimPveModifierPerLevel2Coef( modifierPerLevel, level )

	local coef = 1

	if type( modifierPerLevel ) ~= "number" then
		sys.log( "UI:UnlimPveModifierPerLevel2Coef()[ERROR]: invalid type of the 1-st parameter (\"buffId\"); \"number\" expected, got \"%s\"", type( modifierPerLevel ) )
		return coef
	end

	if type( level ) ~= "number" then
		sys.log( "UI:UnlimPveModifierPerLevel2Coef()[ERROR]: invalid type of the 2-nd parameter (\"level\"); \"number\" expected, got \"%s\"", type( level ) )
		return coef
	end

	if level <= 1 then
		return coef
	end

	if modifierPerLevel < 0 then
		coef = 1 / ( 1 - modifierPerLevel )
	elseif modifierPerLevel > 0 then
		coef = 1 + modifierPerLevel
	end

	coef = math.pow( coef, level - 1 )	 --#0101604(0472356) - коэффициенты за уровень перемножаются

	return coef

end


-- в формате: +0.1 - увеличение на 10%, -0.1 - уменьшение на 10%(примерно)
function UI:UnlimPveModifierPerLevel2Modifier( modifierPerLevel, level )

	local modifier = 0

	if type( modifierPerLevel ) ~= "number" then
		sys.log( "UI:UnlimPveModifierPerLevel2Modifier()[ERROR]: invalid type of the 1-st parameter (\"modifierPerLevel\"); \"number\" expected, got \"%s\"", type( modifierPerLevel ) )
		return modifier
	end

	if type( level ) ~= "number" then
		sys.log( "UI:UnlimPveModifierPerLevel2Modifier()[ERROR]: invalid type of the 2-nd parameter (\"level\"); \"number\" expected, got \"%s\"", type( level ) )
		return modifier
	end

	if level <= 1 then
		return modifier
	end

	local coef = UI:UnlimPveModifierPerLevel2Coef( modifierPerLevel, level )

	if modifierPerLevel > 0 then
		modifier = coef - 1
	else
		modifier = 1 - 1 / coef
	end

	return modifier

end


--
function UI:GetUnlimPveBuffLevel( buffId )

	local level = 1

	if type( buffId ) ~= "number" then
		sys.log( "UI:GetUnlimPveBuffLevel()[ERROR]: invalid type of the 1-st parameter (\"buffId\"); \"number\" expected, got \"%s\"", type( buffId ) )
		return level
	end

	if buffId == 1 then
		level = _G.MasterServer_UnlimPveGetPlayerLevel1()
	elseif buffId == 2 then
		level = _G.MasterServer_UnlimPveGetPlayerLevel2()
	else
		sys.log( "UI:GetUnlimPveBuffLevel()[ERROR]: unhandled buffId (%d)", buffId )
	end

	return level

end


--
function UI:GetUnlimPveCreditsRewardBonus( missionLevel, bIsWavePve )

	local bonus = 0

	if type( missionLevel ) ~= "number" then
		sys.log( "UI:GetUnlimPveCreditsRewardBonus()[ERROR]: invalid type of the 1-st parameter (\"missionLevel\"); \"number\" expected, got \"%s\"", type( missionLevel ) )
		return bonus
	end

	if missionLevel < 1 then
		sys.log( "UI:GetUnlimPveCreditsRewardBonus()[ERROR]: invalid missionLevel (%d)", missionLevel )
		return bonus
	end

	if bIsWavePve ~= nil then
		if type( bIsWavePve ) ~= "boolean" then
			sys.log( "UI:GetUnlimPveCreditsRewardBonus()[ERROR]: invalid type of the 1-st parameter (\"bIsWavePve\"); \"boolean\" or \"nil\" expected, got \"%s\"", type( bIsWavePve ) )
			return bonus
		end
	end

	if bIsWavePve == nil then
		bIsWavePve = false
	end

	if type( _G.UnlimitedPvE ) ~= "table" then
		sys.log( "UI:GetUnlimPveCreditsRewardBonus()[ERROR]: invalid type of '_G.UnlimitedPvE'; 'table' expected, got '%s'", type( _G.UnlimitedPvE ) )
		return bonus
	end

	if bIsWavePve then
		if type( _G.UnlimitedPvE.wave ) ~= "table" then
			sys.log( "UI:GetUnlimPveCreditsRewardBonus()[ERROR]: invalid type of '_G.UnlimitedPvE.wave'; 'table' expected, got '%s'", type( _G.UnlimitedPvE.wave ) )
			return bonus
		end
	end

	local desc = bIsWavePve and _G.UnlimitedPvE.wave or _G.UnlimitedPvE
	local descTableName = bIsWavePve and "_G.UnlimitedPvE.wave" or "_G.UnlimitedPvE"

	-- #0104407 по формуле Y = tanh( A * ( X - 1 ) )

	local coef = 1

	local A = 1
	if type( desc.credits_coef ) == "number" then
		A = desc.credits_coef
	else
		sys.log( "UI:GetUnlimPveCreditsRewardBonus()[ERROR]: cannot find field '%s.credits_coef'", descTableName );
	end

	local minCoef = 1
	if type( desc.credits_min_mod ) == "number" then
		minCoef = desc.credits_min_mod
	else
		sys.log( "UI:GetUnlimPveCreditsRewardBonus()[ERROR]: cannot find field '%s.credits_min_mod'", descTableName );
	end

	local maxCoef = 1
	if type( desc.credits_max_mod ) == "number" then
		maxCoef = desc.credits_max_mod
	else
		sys.log( "UI:GetUnlimPveCreditsRewardBonus()[ERROR]: cannot find field '%s.credits_max_mod'", descTableName );
	end

	coef = math.tanh( A * ( missionLevel - 1 ) )
	coef = UI:Lerp( minCoef, maxCoef, coef )

	bonus = coef - minCoef

	return bonus

end


--
function UI:ValidateScriptedQuestProgress( progress )

	local fixedProgress =
	{
		cur		= 0,
		max		= 0,
		success	= false,	-- завершен успешно		(success и fail не могут быть одновременно true)
		fail	= false,	-- завершен провалом
	}

	if type( progress ) == "table" then

		local bValid = true

		if type( progress.cur ) == "number" then
			fixedProgress.cur = progress.cur
		else
			sys.log( "UI:ValidateScriptedQuestProgress()[ERROR]: invalid type of 'progress.cur'; 'number' expected, got '%s'", type( progress.cur ) )
		end

		if type( progress.max ) == "number" then
			fixedProgress.max = progress.max
		else
			sys.log( "UI:ValidateScriptedQuestProgress()[ERROR]: invalid type of 'progress.max'; 'number' expected, got '%s'", type( progress.max ) )
		end

		if progress.success ~= nil then
			if type( progress.success ) == "boolean" then
				fixedProgress.success = progress.success
			else
				sys.log( "UI:ValidateScriptedQuestProgress()[ERROR]: invalid type of 'progress.success'; 'boolean' or 'nil' expected, got '%s'", type( progress.success ) )
			end
		end

		if progress.fail ~= nil then
			if type( progress.fail ) == "boolean" then
				fixedProgress.fail = progress.fail
			else
				sys.log( "UI:ValidateScriptedQuestProgress()[ERROR]: invalid type of 'progress.fail'; 'boolean' or 'nil' expected, got '%s'", type( progress.fail ) )
			end
		end

		if fixedProgress.success and fixedProgress.fail then
			sys.log( "UI:ValidateScriptedQuestProgress()[ERROR]: both 'success' and 'fail' are specified" )
			fixedProgress.fail = false
		end

	else
		sys.log( "UI:ValidateScriptedQuestProgress()[ERROR]: invalid type of 'progress'; \"table\" expected, got \"%s\"", type( progress ) )
	end

	return fixedProgress

end


--
function UI:GetScriptedQuestData( questId )

	local questData = nil

	if type( questId ) ~= "number" then
		sys.log( "UI:GetScriptedQuestData()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return questData
	end

	for idx, _questData in pairs( UI.scriptedQuests ) do
		if _questData.questId == questId then
			questData = _questData
			break
		end
	end

	return questData

end


