--
function UI:UpdateItemIconsOnLeagueForbiddenEquipmentChanged()

	-- апдейт всех иконок
	local function l_fnRecurse( wnd )

		if UI:IsWndKindOf( wnd, "ItemIcoWnd" ) then
			wnd:OnLeagueForbiddenEquipmentChanged()
		end

		local child = wnd:GetFirstChild()
		while child do

			l_fnRecurse( child )

			child = child:GetNextSibling()

		end

	end

	l_fnRecurse( UI.Root )

end


--
function UI:IsItemForbiddenInLeague( defName )

	local bForbidden = false

	if type( defName ) ~= "string" then
		sys.log( "UI:IsItemForbiddenInLeague()[ERROR]: invalid type of the 1-st parameter ('defName'); 'string' expected, got '%s'", type( defName ) )
		return bForbidden
	end

	if UI:IsDefAutogen( defName ) then

		local subType = UI:GetItemSubType( defName )
		if subType ~= -1 then
			bForbidden = _G.MasterServer_IsLeagueForbiddenSubtype( subType )
		end

	else
		bForbidden = _G.MasterServer_IsLeagueForbiddenEquipment( defName )	-- в зеленые корабли и проапгрейженные модул в базовй деф переводить не нужно, это делается в cpp
	end

	return bForbidden

end


-- "киберспортивное" оборудование - другое название для разрешенного в лигах (арене)
function UI:IsItemCyberSport( defName )

	return not UI:IsItemForbiddenInLeague( defName )

end


-- во время стояния в очередь в арену, а также в лобби при включенной опции "киберспорт" есть ограничения на установку оборудования
function UI:IsCyberSportRestrictionsNow()

	if UI:IsArenaEnqueued() or UI:IsPseudoArenaEnqueued() then
		return true
	end

	if UI.Lobby:IsInLobby() and UI.Lobby:GetMyLobby().cyberSport then
		return true
	end

	return false

end


-- показ мессджбокса с ошибкой о том, что производится попытка установки некиберспортивного оборудования в момент, когда можно устанавливать только его
function UI:ShowErrorOnSetLeagueForbiddenEquipment()

	UI:ShowErrorMsg( "msg_trySetForbiddenEquipment" )

end


-- вызывает _G.GameStore_ChangeEquipment() если можно поставить модуль;
-- если игрок стоит в очереди в лиги или в лобби, то действуют ограничения на то, какое оборудоваине можно ставить;
-- если нельзя поставить, то показывается сообщение с ошибкой
function UI:SafeChangeEquipment( vid, slotId, iid )

	local requestId = 0
	local bForbidden = false

	if type( vid ) ~= "userdata" then
		sys.log( "UI:SafeChangeEquipment()[ERROR]: invalid type of the 1-st parameter ('vid'); 'userdata' expected, got '%s'", type( vid ) )
		return requestId, bForbidden
	end

	if type( slotId ) ~= "number" then
		sys.log( "UI:SafeChangeEquipment()[ERROR]: invalid type of the 2-nd parameter ('slotId'); 'number' expected, got '%s'", type( slotId ) )
		return requestId, bForbidden
	end

	if type( iid ) ~= "userdata" then
		sys.log( "UI:SafeChangeEquipment()[ERROR]: invalid type of the 3-rd parameter ('iid'); 'userdata' expected, got '%s'", type( iid ) )
		return requestId, bForbidden
	end

	if UI:IsCyberSportRestrictionsNow() then

		if UI:GetShipBattleSlotByVid( vid ) ~= -1 then

			if iid ~= UI.INVALID_U64_ID then
				local defName = UI:Iid2DefName( iid )
				bForbidden = UI:IsItemForbiddenInLeague( defName )
			end

		end

	end

	if not bForbidden then
		requestId = _G.GameStore_ChangeEquipment( vid, slotId, iid )
	else
		UI:ShowErrorOnSetLeagueForbiddenEquipment()
	end

	return requestId, bForbidden

end


-- вызывает _G.GameStore_ChangeEquipmentMulti() если можно поставить все модули;
-- если игрок стоит в очереди в лиги или в лобби, то действуют ограничения на то, какое оборудоваине можно ставить;
-- если нельзя поставить, то показывается сообщение с ошибкой
function UI:SafeChangeEquipmentMulti( vid, equipment )

	local requestId = 0
	local bForbidden = false

	if type( vid ) ~= "userdata" then
		sys.log( "UI:SafeChangeEquipmentMulti()[ERROR]: invalid type of the 1-st parameter ('vid'); 'userdata' expected, got '%s'", type( vid ) )
		return requestId, bForbidden
	end

	if UI:IsCyberSportRestrictionsNow() then

		if UI:GetShipBattleSlotByVid( vid ) ~= -1 then

			if equipment.modules then

				for slotId, iid in pairs( equipment.modules ) do
					local defName = UI:Iid2DefName( iid )
					if UI:IsItemForbiddenInLeague( defName ) then
						bForbidden = true
						break
					end
				end

			end

			if not bForbidden then

				if equipment.ammo then

					for slotId, defName in pairs( equipment.ammo ) do
						if UI:IsItemForbiddenInLeague( defName ) then
							bForbidden = true
							break
						end
					end

				end

			end

		end

	end

	if not bForbidden then
		requestId = _G.GameStore_ChangeEquipmentMulti( vid, equipment )
	else
		UI:ShowErrorOnSetLeagueForbiddenEquipment()
	end

	return requestId, bForbidden

end


-- вызывает _G.GameStore_TransferEquipment() если можно поставить модуль;
-- если игрок стоит в очереди в лиги или в лобби, то действуют ограничения на то, какое оборудоваине можно ставить;
-- если нельзя поставить, то показывается сообщение с ошибкой
function UI:SafeTransferEquipment( vidFrom, vidTo, slotFrom, slotTo )

	local requestId = 0
	local bForbidden = false

	if type( vidFrom ) ~= "userdata" then
		sys.log( "UI:SafeTransferEquipment()[ERROR]: invalid type of the 1-st parameter ('vidFrom'); 'userdata' expected, got '%s'", type( vidFrom ) )
		return requestId, bForbidden
	end

	if type( vidTo ) ~= "userdata" then
		sys.log( "UI:SafeTransferEquipment()[ERROR]: invalid type of the 2-nd parameter ('vidTo'); 'userdata' expected, got '%s'", type( vidTo ) )
		return requestId, bForbidden
	end

	if type( slotFrom ) ~= "number" then
		sys.log( "UI:SafeTransferEquipment()[ERROR]: invalid type of the 3-rd parameter ('slotFrom'); 'number' expected, got '%s'", type( slotFrom ) )
		return requestId, bForbidden
	end

	if type( slotTo ) ~= "number" then
		sys.log( "UI:SafeTransferEquipment()[ERROR]: invalid type of the 4-th parameter ('slotTo'); 'number' expected, got '%s'", type( slotTo ) )
		return requestId, bForbidden
	end

	if UI:IsCyberSportRestrictionsNow() then

		if UI:GetShipBattleSlotByVid( vidTo ) ~= -1 then

			local shipItemFrom = UI:GetShipItem( vidFrom, false )
			if not shipItemFrom then
				sys.log( "UI:SafeTransferEquipment()[ERROR]: cannot find ship item for vid %s", _G.U64ToStr( vidFrom ) )
				return requestId, bForbidden
			end

			local iid = shipItemFrom.equipModules[ slotFrom ]
			if iid == nil or iid == UI.INVALID_U64_ID then
				sys.log( "UI:SafeTransferEquipment()[ERROR]: no module in slot %d vid %s", slotFrom, _G.U64ToStr( iid ) )
				return requestId, bForbidden
			end

			local moduleDefName = UI:Iid2DefName( iid )
			bForbidden = UI:IsItemForbiddenInLeague( moduleDefName )

		end

	end

	if not bForbidden then
		requestId = _G.GameStore_TransferEquipment( vidFrom, vidTo, slotFrom, slotTo )
	else
		UI:ShowErrorOnSetLeagueForbiddenEquipment()
	end

	return requestId, bForbidden

end


-- вызывает _G.GameStore_ChangeMunition() если можно поставить модуль;
-- если игрок стоит в очереди в лиги или в лобби, то действуют ограничения на то, какое оборудоваине можно ставить;
-- если нельзя поставить, то показывается сообщение с ошибкой
function UI:SafeChangeMunition( vid, slotId, creditsType, defName )

	local requestId = 0
	local bForbidden = false

	if type( vid ) ~= "userdata" then
		sys.log( "UI:SafeChangeMunition()[ERROR]: invalid type of the 1-st parameter ('vid'); 'userdata' expected, got '%s'", type( vid ) )
		return requestId, bForbidden
	end

	if type( slotId ) ~= "number" then
		sys.log( "UI:SafeChangeMunition()[ERROR]: invalid type of the 2-nd parameter ('slotId'); 'number' expected, got '%s'", type( slotId ) )
		return requestId, bForbidden
	end

	if type( creditsType ) ~= "number" then
		sys.log( "UI:SafeChangeMunition()[ERROR]: invalid type of the 3-rd parameter ('creditsType'); 'number' expected, got '%s'", type( creditsType ) )
		return requestId, bForbidden
	end

	if type( defName ) ~= "string" then
		sys.log( "UI:SafeChangeMunition()[ERROR]: invalid type of the 4-th parameter ('defName'); 'string' expected, got '%s'", type( defName ) )
		return requestId, bForbidden
	end

	if UI:IsCyberSportRestrictionsNow() then

		if UI:GetShipBattleSlotByVid( vid ) ~= -1 then

			if defName ~= "" then
				bForbidden = UI:IsItemForbiddenInLeague( defName )
			end

		end

	end

	if not bForbidden then
		requestId = _G.GameStore_ChangeMunition( vid, slotId, creditsType, defName )
	else
		UI:ShowErrorOnSetLeagueForbiddenEquipment()
	end

	return requestId, bForbidden

end


-- вызывает _G.GameStore_TransferMunition() если можно поставить модуль;
-- если игрок стоит в очереди в лиги или в лобби, то действуют ограничения на то, какое оборудоваине можно ставить;
-- если нельзя поставить, то показывается сообщение с ошибкой
function UI:SafeTransferMunition( vidFrom, vidTo, slotFrom, slotTo )

	local requestId = 0
	local bForbidden = false

	if type( vidFrom ) ~= "userdata" then
		sys.log( "UI:SafeTransferMunition()[ERROR]: invalid type of the 1-st parameter ('vidFrom'); 'userdata' expected, got '%s'", type( vidFrom ) )
		return requestId, bForbidden
	end

	if type( vidTo ) ~= "userdata" then
		sys.log( "UI:SafeTransferMunition()[ERROR]: invalid type of the 2-nd parameter ('vidTo'); 'userdata' expected, got '%s'", type( vidTo ) )
		return requestId, bForbidden
	end

	if type( slotFrom ) ~= "number" then
		sys.log( "UI:SafeTransferMunition()[ERROR]: invalid type of the 3-rd parameter ('slotFrom'); 'number' expected, got '%s'", type( slotFrom ) )
		return requestId, bForbidden
	end

	if type( slotTo ) ~= "number" then
		sys.log( "UI:SafeTransferMunition()[ERROR]: invalid type of the 4-th parameter ('slotTo'); 'number' expected, got '%s'", type( slotTo ) )
		return requestId, bForbidden
	end

	if UI:IsCyberSportRestrictionsNow() then

		if UI:GetShipBattleSlotByVid( vidTo ) ~= -1 then

			local shipItemFrom = UI:GetShipItem( vidFrom, false )
			if not shipItemFrom then
				sys.log( "UI:SafeTransferMunition()[ERROR]: cannot find ship item for vid %s", _G.U64ToStr( vidFrom ) )
				return requestId, bForbidden
			end

			local ammoDefName = shipItemFrom.equipAmmo[ slotFrom ] and shipItemFrom.equipAmmo[ slotFrom ].def or ""
			bForbidden = UI:IsItemForbiddenInLeague( ammoDefName )

		end

	end

	if not bForbidden then
		requestId = _G.GameStore_TransferMunition( vidFrom, vidTo, slotFrom, slotTo )
	else
		UI:ShowErrorOnSetLeagueForbiddenEquipment()
	end

	return requestId, bForbidden

end


-- установка оборудования, сохраненного в пресете, на корабль
function UI:ShipPreset_ApplyPresetToCurrent( vid, presetId )

	local requestId = 0

	if UI:IsWaitingRequests() then
		sys.log( "UI:ShipPreset_ApplyPresetToCurrent()[ERROR]: waiting for anothe requests" )
		return requestId
	end

	if type( vid ) ~= "userdata" then
		sys.log( "UI:ShipPreset_ApplyPresetToCurrent()[ERROR]: invalid type of the 1-st parameter ('vid'); 'userdata' expected, got '%s'", type( vid ) )
		return requestId
	end

	if type( presetId ) ~= "number" then
		sys.log( "UI:ShipPreset_ApplyPresetToCurrent()[ERROR]: invalid type of the 2-nd parameter ('presetId'); 'number' expected, got '%s'", type( presetId ) )
		return requestId
	end

	local shipItem = self:GetShipItem( vid, false )
	if not shipItem then
		sys.log( "UI:ShipPreset_ApplyPresetToCurrent()[ERROR]: cannot find ship item for vid %s", _G.U64ToStr( vid ) )
		return requestId
	end

	local shipDefName = shipItem.defName
	if UI:IsShipEvolving( shipDefName ) then
		shipDefName = UI:GetEvolvingShipBaseDef( shipDefName )
	end

	local shipPresetsData = UI.shipPresets[ shipDefName ]
	if not shipPresetsData or not shipPresetsData.presets then
		sys.log( "UI:ShipPreset_ApplyPresetToCurrent()[ERROR]: cannot find presets data for ship %s", shipDefName )
		fnShowErrorMsg()
		return requestId
	end

	local preset = nil
	for presetIdx, _preset in pairs( shipPresetsData.presets ) do
		if _preset.id == presetId then
			preset = _preset
			break
		end
	end

	if not preset then
		sys.log( "UI:ShipPreset_ApplyPresetToCurrent()[ERROR]: cannot find preset %d for ship %s", presetId, shipDefName )
		return requestId
	end

	-- новая раскладка
	local newEquipment = {}

	-- вспомогательная функция, собирает все подходящие модули для данного слота
	local function fnCollectFitItemsForDef( defName, moduleSlotId, fitItems )

		if defName == "" then
			return
		end

		local baseDefName = UI:GetItemUpgradeBaseDef( defName )

		-- не подходит, если:
		-- установлен на другой корабль
		-- установлен на этот корабль в другой слот, и в пресете он тут есть

		local invItems = UI:GetInventoryItemsByDef( defName )
		for itemIdx, invItem in pairs( invItems ) do

			local bFit = true

			local equipShipItem, equipSlotId = UI:GetEquippedShipItemAndSlot( invItem.iid )
			if equipShipItem then

				if equipShipItem == shipItem then

					if equipSlotId ~= moduleSlotId then
						local otherSlotPresetDefName = preset.modules[ equipSlotId ] and preset.modules[ equipSlotId ].defName or ""
						if otherSlotPresetDefName ~= "" and UI:GetItemUpgradeBaseDef( otherSlotPresetDefName ) == baseDefName then
							bFit = false
						end
					end

				else
					bFit = false
				end

			end

			-- проверка, что уже не занят в новой раскладке
			if bFit then
				if newEquipment.modules then
					for newSlotId, newIid in pairs( newEquipment.modules ) do
						if newIid == invItem.iid then
							bFit = false
							break
						end
					end
				end
			end

			if bFit then
				table.insert( fitItems, invItem )
			end

		end

	end


	-- вспомогательная функция, сортировка подходящих модулей, в начале самые лучшие
	local function fnSortFitItems( item1, item2 )

		-- по уровню апгрейда
		local level1 = UI:GetItemUpgradeLevel( item1.defName )
		local level2 = UI:GetItemUpgradeLevel( item2.defName )

		if level1 ~= level2 then
			return level1 > level2
		end

		-- по enchanted
		local bEnchanted1 = UI:IsInventoryItemEnchanted( item1 )
		local bEnchanted2 = UI:IsInventoryItemEnchanted( item2 )

		if bEnchanted1 ~= bEnchanted2 then
			return bEnchanted1
		end

		return item1.iid < item2.iid

	end


	-- добавление модулей в новую раскладку

	-- Все автогены должны остаться на своих местах,
	-- т.к. их нельзя просто так снять, только за плату, через специальный интерфейс
	for moduleSlotId, equipIid in pairs( shipItem.equipModules ) do

		local bAutogen = equipIid ~= UI.INVALID_U64_ID and UI:GetAutogenInventoryItem( equipIid ) ~= nil
		if bAutogen then

			if not newEquipment.modules then
				newEquipment.modules = {}
			end
			newEquipment.modules[ moduleSlotId ] = equipIid

		end

	end

	if preset.modules then

		for moduleSlotId, moduleData in pairs( preset.modules ) do

			if UI:HasShipModuleSlot( shipItem, moduleSlotId ) then

				local presetDefName = moduleData.defName or ""
				local bIsSet = newEquipment.modules ~= nil and newEquipment.modules[ moduleSlotId ] ~= nil and newEquipment.modules[ moduleSlotId ] ~= UI.INVALID_U64_ID	-- там уже может стоять автоген, его не заменяем ничем

				if presetDefName ~= "" and not bIsSet then

					if UI:IsItemFitForShip( presetDefName, shipItem ) then

						local fitItems = {}

						local baseDefName = UI:GetItemUpgradeBaseDef( presetDefName )
						local maxLevel = UI:GetItemUpgradeMaxLevel( baseDefName )

						-- если у модуля есть уровни апгрейда, то выбираем самый лучший модуль из имеющихся
						if maxLevel ~= -1 then
							for level = 1, maxLevel do
								local defNameForLevel = UI:GetItemUpgradeDefForLevel( baseDefName, level )
								fnCollectFitItemsForDef( defNameForLevel, moduleSlotId, fitItems )
							end
						-- модуль не имеет уровней апгрейда
						else
							fnCollectFitItemsForDef( presetDefName, moduleSlotId, fitItems )
						end

						if next( fitItems ) then

							table.sort( fitItems, fnSortFitItems )

							if not newEquipment.modules then
								newEquipment.modules = {}
							end

							local iid = fitItems[ 1 ].iid
							newEquipment.modules[ moduleSlotId ] = iid

						end

					end

				end

			end

		end

	end

	-- добавление аммуниции в новую раскладку
	if preset.ammo then

		for ammoSlotId, ammoDefName in pairs( preset.ammo ) do

			if UI:IsItemFitForShip( ammoDefName, shipItem ) then

				local bFit = true

				-- боеприпасы должны подходить к оружию
				if ammoSlotId == ai.MunitionBayType.MBT_PRIMARY then

					bFit = false

					local weaponIid = newEquipment.modules and newEquipment.modules[ ai.SpaceShipModuleSlot.PRIMARY_WEAPON_01 ] or UI.INVALID_U64_ID
					if weaponIid ~= UI.INVALID_U64_ID then

						local weaponDefName = UI:Iid2DefName( weaponIid )
						if UI:GetWeaponClass( weaponDefName ) == UI:GetWeaponClass( ammoDefName ) then
							bFit = true
						end

					end

				end

				-- аммуниции может реально не быть ни в инвентаре, ни на корабле,
				-- но деф аммуниции можно установить в слот даже при нулевом количестве (аммуницию можно пополнять потом)

				if bFit then

					if not newEquipment.ammo then
						newEquipment.ammo = {}
					end

					newEquipment.ammo[ ammoSlotId ] = ammoDefName

				end

			end

		end

	end

	-- ок, вызов функции cpp, которая установит
	requestId = UI:SafeChangeEquipmentMulti( vid, newEquipment )

	return requestId

end


-- сохранение текущей раскладки на корабле в пресет
function UI:ShipPreset_SaveCurrentToPreset( vid, presetId )

	local function fnShowErrorMsg()
		UI:ShowErrorMsg( "shipPresets_errorMsg_failSavePreset" )
	end

	if type( vid ) ~= "userdata" then
		sys.log( "UI:ShipPreset_SaveCurrentToPreset()[ERROR]: invalid type of the 1-st parameter ('vid'); 'userdata' expected, got '%s'", type( vid ) )
		fnShowErrorMsg()
		return false
	end

	if type( presetId ) ~= "number" then
		sys.log( "UI:ShipPreset_SaveCurrentToPreset()[ERROR]: invalid type of the 2-nd parameter ('presetId'); 'number' expected, got '%s'", type( presetId ) )
		fnShowErrorMsg()
		return false
	end

	local shipItem = self:GetShipItem( vid, false )
	if not shipItem then
		sys.log( "UI:ShipPreset_SaveCurrentToPreset()[ERROR]: cannot find ship item for vid %s", _G.U64ToStr( vid ) )
		fnShowErrorMsg()
		return false
	end

	local shipDefName = shipItem.defName
	if UI:IsShipEvolving( shipDefName ) then
		shipDefName = UI:GetEvolvingShipBaseDef( shipDefName )
	end

	local shipPresetsData = UI.shipPresets[ shipDefName ]
	if not shipPresetsData or not shipPresetsData.presets then
		sys.log( "UI:ShipPreset_SaveCurrentToPreset()[ERROR]: cannot find presets data for ship %s", shipDefName )
		fnShowErrorMsg()
		return false
	end

	local preset = nil
	for presetIdx, _preset in pairs( shipPresetsData.presets ) do
		if _preset.id == presetId then
			preset = _preset
			break
		end
	end

	if not preset then
		sys.log( "UI:ShipPreset_SaveCurrentToPreset()[ERROR]: cannot find preset %d for ship %s", presetId, shipDefName )
		fnShowErrorMsg()
		return false
	end

	UI:ShipPreset_SaveCurrentToPresetInternal( shipItem, preset )

	UI.shipPresetsChanged = true
	UI:ShipPreset_WriteToFile()

	UI.HangarWnd:ShipPreset_OnSaveCurrentToPreset( vid, presetId )

	return true

end


--
function UI:ShipPreset_SaveCurrentToPresetInternal( shipItem, preset )

	preset.modules = nil
	preset.ammo = nil

	-- модули
	for moduleSlotId, iid in pairs( shipItem.equipModules ) do

		if iid ~= UI.INVALID_U64_ID then

			local item = UI:GetInventoryItem( iid )	-- эта функция возвращает только обычные модули, не автоген; автоген не может быть в пресете
			if item and item.defName and item.defName ~= "" then

				if not preset.modules then
					preset.modules = {}
				end

				local moduleData = {}
				moduleData.defName = item.defName

				if UI:IsInventoryItemEnchanted( item ) then
					moduleData.enchanted = true
				end

				preset.modules[ moduleSlotId ] = moduleData

			end

		end

	end

	-- аммуниция
	for ammoSlotId, ammo in pairs( shipItem.equipAmmo ) do

		if ammo.def and ammo.def ~= "" then

			if not preset.ammo then
				preset.ammo = {}
			end

			preset.ammo[ ammoSlotId ] = ammo.def

		end

	end

end


-- Добавление нового пресета, сохранение в него текущей раскладки и установка выделения на него
function UI:ShipPreset_AddPreset( vid, presetName )

	local function fnShowErrorMsg()
		UI:ShowErrorMsg( "shipPresets_errorMsg_failAddPreset" )
	end

	if type( vid ) ~= "userdata" then
		sys.log( "UI:ShipPreset_AddPreset()[ERROR]: invalid type of the 1-st parameter ('vid'); 'userdata' expected, got '%s'", type( vid ) )
		fnShowErrorMsg()
		return false
	end

	if type( presetName ) ~= "string" then
		sys.log( "UI:ShipPreset_AddPreset()[ERROR]: invalid type of the 2-nd parameter ('presetName'); 'string' expected, got '%s'", type( presetName ) )
		fnShowErrorMsg()
		return false
	end

	local shipItem = self:GetShipItem( vid, false )
	if not shipItem then
		sys.log( "UI:ShipPreset_AddPreset()[ERROR]: cannot find ship item for vid %s", _G.U64ToStr( vid ) )
		fnShowErrorMsg()
		return false
	end

	local shipDefName = shipItem.defName
	if UI:IsShipEvolving( shipDefName ) then
		shipDefName = UI:GetEvolvingShipBaseDef( shipDefName )
	end

	if shipDefName == "" then
		sys.log( "UI:ShipPreset_AddPreset()[ERROR]: empty shipDefName" )
		fnShowErrorMsg()
		return false
	end

	if presetName == "" then
		sys.log( "UI:ShipPreset_AddPreset()[ERROR]: empty presetName" )
		fnShowErrorMsg()
		return false
	end

	if _G.Utf8StrLen( presetName ) > UI.SHIP_PRESET_MAX_NAME_LENGTH then
		sys.log( "UI:ShipPreset_AddPreset()[ERROR]: too long preset name" )
		fnShowErrorMsg()
		return false
	end

	local shipPresetsData = UI.shipPresets[ shipDefName ]

	if shipPresetsData and shipPresetsData.presets then
		if UI:GetTableLength( shipPresetsData.presets ) >= UI.SHIP_PRESET_MAX_PRESETS_PER_SHIP then
			sys.log( "UI:ShipPreset_AddPreset()[ERROR]: presets limit achieved for ship %s", shipDefName )
			fnShowErrorMsg()
			return false
		end
	end

	local freePresetId = -1

	if shipPresetsData and shipPresetsData.presets then

		for presetId = 1, UI.SHIP_PRESET_MAX_PRESETS_PER_SHIP do

			local bFound = false

			for presetIdx, _preset in pairs( shipPresetsData.presets ) do
				if _preset.id == presetId then
					bFound = true
					break
				end
			end

			if not bFound then
				freePresetId = presetId
				break
			end

		end

	else
		freePresetId = 1
	end

	if freePresetId == -1 then
		sys.log( "UI:ShipPreset_AddPreset()[ERROR]: cannot find new preset id for ship %s", shipDefName )
		fnShowErrorMsg()
		return false
	end

	-- ок, добавление
	if not shipPresetsData then
		shipPresetsData = {}
		UI.shipPresets[ shipDefName ] = shipPresetsData
	end

	if not shipPresetsData.presets then
		shipPresetsData.presets = {}
	end

	local preset = {}
	table.insert( shipPresetsData.presets, preset )

	preset.id = freePresetId
	preset.name = presetName

	-- сохранение текущей раскладки в новый пресет
	UI:ShipPreset_SaveCurrentToPresetInternal( shipItem, preset )

	-- ставим выделение на новый пресет
	shipPresetsData.selPresetId = preset.id

	UI.shipPresetsChanged = true
	UI:ShipPreset_WriteToFile()

	UI.HangarWnd:ShipPreset_OnAddPreset( vid, preset.id )

	return true

end


--
function UI:ShipPreset_RemovePreset( shipDefName, presetId )

	local function fnShowErrorMsg()
		UI:ShowErrorMsg( "shipPresets_errorMsg_failRemovePreset" )
	end

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:ShipPreset_RemovePreset()[ERROR]: invalid type of the 1-st parameter ('shipDefName'); 'string' expected, got '%s'", type( shipDefName ) )
		fnShowErrorMsg()
		return false
	end

	if type( presetId ) ~= "number" then
		sys.log( "UI:ShipPreset_RemovePreset()[ERROR]: invalid type of the 2-nd parameter ('presetId'); 'number' expected, got '%s'", type( presetId ) )
		fnShowErrorMsg()
		return false
	end

	if UI:IsShipEvolving( shipDefName ) then
		shipDefName = UI:GetEvolvingShipBaseDef( shipDefName )
	end

	local shipPresetsData = UI.shipPresets[ shipDefName ]
	if not shipPresetsData or not shipPresetsData.presets then
		sys.log( "UI:ShipPreset_RemovePreset()[ERROR]: cannot find presets data for ship %s", shipDefName )
		fnShowErrorMsg()
		return false
	end

	local presetIdx = nil
	for _presetIdx, preset in pairs( shipPresetsData.presets ) do
		if preset.id == presetId then
			presetIdx = _presetIdx
			break
		end
	end

	if not presetIdx then
		sys.log( "UI:ShipPreset_RemovePreset()[WARNING]: cannot find preset %d for ship %s", presetId, shipDefName )
		return true
	end

	table.remove( shipPresetsData.presets, presetIdx )

	if not next( shipPresetsData.presets ) then

		UI.shipPresets[ shipDefName ] = nil

	else

		-- при удалении выделенного пресета ставим выделение на другой пресет (такой же по порядку с конца, т.к. правое выравнивание слотов)
		if shipPresetsData.selPresetId == presetId then

			local numPresetsNew = #shipPresetsData.presets
			local numPresetsOld = numPresetsNew + 1

			local idxFromEnd = numPresetsOld - presetIdx + 1
			local newSelPresetIdx = numPresetsNew - idxFromEnd + 1

			newSelPresetIdx = math.max( newSelPresetIdx, 1 )
			newSelPresetIdx = math.fmod( newSelPresetIdx - 1, #shipPresetsData.presets ) + 1

			local newSelPreset = shipPresetsData.presets[ newSelPresetIdx ]
			if newSelPreset then
				newSelPresetId = newSelPreset.id
			else
				sys.log( "UI:ShipPreset_RemovePreset()[ERROR]: cannot be here, irregular array" )
			end

			shipPresetsData.selPresetId = newSelPresetId

		end

	end

	UI.shipPresetsChanged = true
	UI:ShipPreset_WriteToFile()

	UI.HangarWnd:ShipPreset_OnRemovePreset( shipDefName, presetId )

	return true

end


-- установка выбранного пресета для корабля; нужно только для отображения кнопочки в интерфейсе
function UI:ShipPreset_SetSelPreset( shipDefName, presetId )

	if type( shipDefName ) ~= "string" then
		sys.log( "UI:ShipPreset_SetSelPreset()[ERROR]: invalid type of the 1-st parameter ('shipDefName'); 'string' expected, got '%s'", type( shipDefName ) )
		return false
	end

	if type( presetId ) ~= "number" then
		sys.log( "UI:ShipPreset_SetSelPreset()[ERROR]: invalid type of the 2-nd parameter ('presetId'); 'number' expected, got '%s'", type( presetId ) )
		return false
	end

	if UI:IsShipEvolving( shipDefName ) then
		shipDefName = UI:GetEvolvingShipBaseDef( shipDefName )
	end

	local shipPresetsData = UI.shipPresets[ shipDefName ]
	if not shipPresetsData or not shipPresetsData.presets then
		sys.log( "UI:ShipPreset_SetSelPreset()[ERROR]: cannot find presets data for ship %s", shipDefName )
		return false
	end

	local preset = nil
	for presetIdx, _preset in pairs( shipPresetsData.presets ) do
		if _preset.id == presetId then
			preset = _preset
			break
		end
	end

	if not preset then
		sys.log( "UI:ShipPreset_SetSelPreset()[ERROR]: cannot find preset %d for ship %s", presetId, shipDefName )
		return false
	end

	if presetId ~= shipPresetsData.selPresetId then

		shipPresetsData.selPresetId = presetId

		UI.shipPresetsChanged = true
		UI.HangarWnd:ShipPreset_OnSetSelPreset( shipDefName, presetId )

	end

	return true

end


-- чтение таблицы пресетов из файла
function UI:ShipPreset_ReadFromFile()

	local uid = UI:GetLocalPlayerUid()
	if uid == UI.INVALID_U64_ID then
		sys.log( "UI:ShipPreset_ReadFromFile()[ERROR]: invalid uid" )
		return
	end

	local t = nil

	UI.shipPresets, t = _G.ShipPresetsRead( uid ) or {}
	UI.shipPresetsChanged = false
	UI.shipPresetsUid = uid

end


-- сохранине таблицы пресетов в файл
function UI:ShipPreset_WriteToFile()

	if UI.shipPresetsUid == UI.INVALID_U64_ID then
		sys.log( "UI:ShipPreset_WriteToFile()[ERROR]: invalid uid" )
		return
	end

	if UI.shipPresetsChanged then
		_G.ShipPresetsWrite( UI.shipPresets, UI.shipPresetsUid )
		UI.shipPresetsChanged = false
	end

end


--
function UI:UpdateServerData_OnVesselChangeEquipMulti( result, requestId, param1, param2, u64Param )

	if result == _G.GameStore.ModuleEquipResult.MER_OK then

    	local shipId = u64( param1, param2 )

    	for idx, shipItem in pairs( self.serverData.allShips ) do
    		if shipItem.vid == shipId then

    			shipItem.equipModules	= _G.GameStore_GetEquipmentIids( shipItem.vid )
	    		shipItem.equipAmmo		= _G.GameStore_GetMunition( shipItem.vid )

    			self:UpdateIid2Ship( shipItem )

    			break

    		end
    	end

    	self.serverData.bInvItemsDirty = true

	end


	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.ModuleEquipResult.MER_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:NeedShowNotificationForBundle( defName )

	local bNeedShow = true

	if type( defName ) ~= "string" then
		sys.log( "UI:NeedShowNotificationForBundle()[ERROR]: invalid type of the 1-st param ('defName'); 'string' expected, got '%s'", type( defName ) )
		return bNeedShow
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:NeedShowNotificationForBundle()[ERROR]: cannot find def '%s'", defName )
		return bNeedShow
	end

	if def.hiddenNotification ~= nil then

		if type( def.hiddenNotification ) == "boolean" then
			bNeedShow = not def.hiddenNotification
		else
			sys.log( "UI:NeedShowNotificationForBundle()[ERROR]: invalid type of _G.Def['%s'].hiddenNotification; 'boolean' or 'nil' expected, got '%s'", type( def.hiddenNotification ) )
		end

	end

	return bNeedShow

end


