--
function UI:Reward2Str( rewardInfo, baseColor )

	local str = "unknown"

	if type( rewardInfo ) ~= "table" then
		sys.log( "UI:Reward2Str()[ERROR]: invalid type of the 1-st paramenter ('rewardInfo'); 'table' expected, got '%s'", type( rewardInfo ) )
		return str
	end

	-- tODO проверки типов

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if rewardInfo.type == _G.MasterServer.RewardType.RT_CREDITS then
		str = string.format( "%s$credits_big$", UI:Num2StrSeparatedBy3( rewardInfo.value ) )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_GOLD_CREDITS then
		str = string.format( "%s$gold_big$", UI:Num2StrSeparatedBy3( rewardInfo.value ) )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_TOKEN_CREDITS then
		str = string.format( "%s$tokens_big$", UI:Num2StrSeparatedBy3( rewardInfo.value ) )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_EVENT_CREDITS then
		str = string.format( "%s$event_credits$", UI:Num2StrSeparatedBy3( rewardInfo.value ) )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_VESSEL_EXP_POOL then
		str = string.format( "%s$synergy_free$", UI:Num2StrSeparatedBy3( rewardInfo.value ) )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_ITEM then

		str = UI:GetEntityLocalizedNameByDef( rewardInfo.def, true )

		local amount = rewardInfo.value or 1
		if amount > 1 then
			str = string.format( "%s%s[%s]", str, UI:Color2Str( baseColor ), UI:Num2StrSeparatedBy3( amount ) )
		end

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_ACCOUNT_AURA then
		str = UI:AccountAura2Str( rewardInfo.def )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_PREMIUM then
		-- tODO
		str = string.format( "premium %f", rewardInfo.value )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_TITLE then
		str = UI:Title2Str( rewardInfo.value )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_AVATAR then
		str = UI:MailAttachmentAvatar2Str( rewardInfo.def )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_MOTTO then
		str = UI:MailAttachmentMotto2Str( rewardInfo.def )

	elseif rewardInfo.type == _G.MasterServer.RewardType.RT_CUSTOM_ELEMENT then
		str = UI:MailAttachmentCustomElement2Str( rewardInfo.def )

	else
		sys.log( "UI:Reward2Str()[ERROR]: unhandled reward type %d", rewardInfo.type )
	end

	return str

end


