--
function UI:GetDef( defName, bSwear, autogenUpgradeLevel )

	local def = nil

	if type( defName ) ~= "string" then
		sys.log( "UI:GetDef()[ERROR]: invalid type of the 1-st paramenter ('defName'); 'string' expected, got '%s'", type( defName ) )
		return def
	end

	if bSwear ~= nil then
		if type( bSwear ) ~= "boolean" then
			sys.log( "UI:GetDef()[ERROR]: invalid type of the 2-nd paramenter ('bSwear'); 'boolean' or 'nil' expected, got '%s'", type( bSwear ) )
			bSwear = nil
		end
	end

	if bSwear == nil then
		bSwear = true
	end

	if autogenUpgradeLevel ~= nil then
		if type( autogenUpgradeLevel ) ~= "number" then
			sys.log( "UI:GetDef()[ERROR]: invalid type of the 3-rd paramenter ('autogenUpgradeLevel'); 'number' or 'nil' expected, got '%s'", type( autogenUpgradeLevel ) )
			autogenUpgradeLevel = nil
		end
	end

	if autogenUpgradeLevel == nil then
		autogenUpgradeLevel = -1
	end

	-- обычный деф?
	if _G.Def[ defName ] then

		def = _G.Def[ defName ]

	-- автоген?
	else

		local autogenItem = nil

		-- если есть в инвентаре (там прямо сама таблица дефа уже хранится), то берем оттуда
		-- (во время геймплея не работает)
		if _G.GetCurrentGameMode() == ai.Gameplay.NONE then
			autogenItem = UI:GetAutogenInventoryItemByDef( defName )
			if autogenItem and ( autogenUpgradeLevel == -1 or autogenItem.upgradeLevel == autogenUpgradeLevel ) then
				def = autogenItem.def
			end
		end

		-- пробуем взять из cpp,
		-- так можно получить дефы установленных на игроках автогенов во время геймплея
		if not def and not autogenItem then
			autogenItem = _G.GetAutogenItem( defName, false--[[не ругаться если не найдено]] )
			if autogenItem and ( autogenUpgradeLevel == -1 or autogenItem.upgradeLevel == autogenUpgradeLevel ) then
				def = _G.GetAutogenDef( defName, false--[[не ругаться если не автоген]] )
			end
		end

		-- пробуем найти в пуле временных дефов в ui
		-- (эти дефы создаются для отображения атогенов в дебрифинге, почте, чате,
		-- т.е. когда такого дефа нет в cpp)
		if not def and not autogenItem then
			autogenItem = UI:GetTempAutogenItem( defName )
			if autogenItem and ( autogenUpgradeLevel == -1 or autogenItem.upgradeLevel == autogenUpgradeLevel ) then
				def = autogenItem.def
			end
		end

		-- если мы нашли autogenItem, но сам сгенеренный деф не подошел по причине не совпадения уровеня апгрейда,
		-- то берем rollData из autogenItem и генерим на лету новый деф с правильным уровнем апгрейда
		if not def and autogenItem then

			local def = _G.GenerateAutogenDef( autogenItem.rollData, autogenUpgradeLevel )
			if not def then
				sys.log( "UI:GetDef()[ERROR]: cannot generate autogen def" )
			end

		end

	end

	if not def and bSwear then
		sys.log( "UI:GetDef()[ERROR]: cannot find def for '%s'", defName )
	end

	return def

end


--
function UI:GetSpellDef( defName )

	local def = nil

	if type( defName ) ~= "string" then
		sys.log( "UI:GetSpellDef()[ERROR]: invalid type of the 1-st paramenter ('defName'); 'string' expected, got '%s'", type( defName ) )
		return def
	end

	if _G.Spell[ defName ] then
		def = _G.Spell[ defName ]
	else
		def = _G.GetAutogenSpellDef( defName, true--[[не ругаться если не автоген]] )
	end

	if not def then
		sys.log( "UI:GetSpellDef()[ERROR]: cannot find def for '%s'", defName )
	end

	return def

end


