--
function UI:AutogenAffix2Str( affixId, level, bPostfix )

	local str = "unknown affix"

	if type( affixId ) ~= "number" then
		sys.log( "UI:AutogenAffix2Str()[ERROR]: invalid type of the 1-st paramenter ('affixId'); 'number' expected, got '%s'", type( affixId ) )
		return str
	end

	str = string.format( "affix %d", affixId )

	if type( level ) ~= "number" then
		sys.log( "UI:AutogenAffix2Str()[ERROR]: invalid type of the 2-nd paramenter ('level'); 'number' expected, got '%s'", type( level ) )
		return str
	end

	str = string.format( "affix %d level %d", affixId, level )

	if type( bPostfix ) ~= "boolean" then
		sys.log( "UI:AutogenAffix2Str()[ERROR]: invalid type of the 3-rd paramenter ('bPostfix'); 'boolean' expected, got '%s'", type( bPostfix ) )
		return str
	end

	local affixName, affixGroupId = UI:GetAutogenAffixNameAndGroup( affixId )
	if affixName == "" or affixGroupId == -1 then
		sys.log( "UI:AutogenAffix2Str()[ERROR]: cannot find affixName or groupId for affixId=%d", affixId )
		return str
	end

	local affixGroupName = UI:Val2Key( _G.AutogenAffixGroup, affixGroupId )
	if affixGroupName == "" then
		sys.log( "UI:AutogenAffix2Str()[ERROR]: cannot find affix group %d in _G.AutogenAffixGroup (for affixId=%d affixName=%s)", affixGroupId, affixId, affixName )
		return str
	end

	local strId = string.format( "autogen_%s_%s_%d_%s", affixGroupName, affixName, level, bPostfix and "postfix" or "prefix" )
	str = UI:GetStringByName( strId )

	return str

end


--
function UI:GetAutogenAffixDefInternal( affixId )

	local affixDef		= nil
	local affixName		= ""
	local affixGroupId	= -1

	if type( affixId ) ~= "number" then
		sys.log( "UI:GetAutogenAffixDefInternal()[ERROR]: invalid type of the 1-st paramenter ('affixId'); 'number' expected, got '%s'", type( affixId ) )
		return affixDef, affixName, affixGroupId
	end

	if type( _G.Affixes ) ~= "table" then
		sys.log( "UI:GetAutogenAffixDefInternal()[ERROR]: invalid type of '_G.Affixes'; 'table' expected, got '%s'", type( _G.Affixes ) )
		return affixDef, affixName, affixGroupId
	end

	for _affixGroupId, affixGroupDef in pairs( _G.Affixes ) do

		if type( _affixGroupId ) == "number" and type( affixGroupDef ) == "table" then

			local bStopSearch = false

			for _affixName, _affixDef in pairs( affixGroupDef ) do

				if type( _affixName ) == "string" and type( _affixDef ) == "table" then

					if _affixDef.affixId == affixId then

						affixDef		= _affixDef
						affixName		= _affixName
						affixGroupId	= _affixGroupId

						bStopSearch = true
						break

					end

				else
					sys.log( "UI:GetAutogenAffixDefInternal()[ERROR]: invalid format of table '_G.Affixes[%d]'; <string>=<table> expected, got <%s>=%s", _affixGroupId, type( _affixName ), type( _affixDef ) )
					bStopSearch = true
					break
				end

			end

			if bStopSearch then
				break
			end

		else
			sys.log( "UI:GetAutogenAffixDefInternal()[ERROR]: invalid format of table '_G.Affixes'; <number>=<table> expected, got <%s>=%s", type( _affixGroupId ), type( affixGroupDef ) )
			break
		end

	end

	return affixDef, affixName, affixGroupId

end


--
function UI:GetAutogenAffixDef( affixId )

