	local affixGroupId	= -1

	if type( affixId ) ~= "number" then
		sys.log( "UI:GetAutogenAffixDef()[ERROR]: invalid type of the 1-st paramenter ('affixId'); 'number' expected, got '%s'", type( affixId ) )
		return affixDef
	end

	affixDef, affixName, affixGroupId = UI:GetAutogenAffixDefInternal( affixId )
	return affixDef

end


