end


--
function UI:GetAutogenSpellBaseDefName( affixId, level, spellActionName, spellIdx )

	local spellDefName = ""

	if type( affixId ) ~= "number" then
		sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: invalid type of the 1-st paramenter ('affixId'); 'number' expected, got '%s'", type( affixId ) )
		return spellDefName
	end

	if type( level ) ~= "number" then
		sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: invalid type of the 2-nd paramenter ('level'); 'number' expected, got '%s'", type( level ) )
		return spellDefName
	end

	if type( spellActionName ) ~= "string" then
		sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: invalid type of the 3-rd paramenter ('spellActionName'); 'string' expected, got '%s'", type( spellActionName ) )
		return spellDefName
	end

	if type( spellIdx ) ~= "number" then
		sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: invalid type of the 4-th paramenter ('spellIdx'); 'number' expected, got '%s'", type( spellIdx ) )
		return spellDefName
	end

	local affixDef = UI:GetAutogenAffixDef( affixId )
	if not affixDef then
		sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: cannot find def for affix %d", affixId )
		return spellDefName
	end

	local levelDef = type( affixDef.levels ) == "table" and affixDef.levels[ level + 1 ]
	if type( levelDef ) ~= "table" then
		sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: cannot find levelDef for affix %d level %d", affixId, level )
		return spellDefName
	end

	if type( levelDef.spells ) ~= "table" then
		sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: invalid type of 'spells' for affix %d level %d; 'table' expected, got '%s'", affixId, level, type( levelDef.spells ) )
		return spellDefName
	end

	for actionIdx, actionInfo in pairs( levelDef.spells ) do

		local _spellActionName, spellsInfo = next( actionInfo )
		if type( _spellActionName ) == "string" and type( spellsInfo ) == "table" then

			if _spellActionName == spellActionName then

				local spellDef = spellsInfo[ spellIdx ]
				if spellDef then

					if type( spellDef.defName ) == "string" then
						spellDefName = spellDef.defName
					else
						sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: invalid type of 'defName' for affix %d level %d spellActionName %s spellIdx %d; 'string' expected, got '%s'", affixId, level, spellActionName, spellIdx, type( spellDef.defName ) )
					end

				else
					sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: cannot find spellDef for affix %d level %d spellActionName %s spellIdx %d", affixId, level, spellActionName, spellIdx )
				end

				break

			end

		else
			sys.log( "UI:GetAutogenSpellBaseDefName()[ERROR]: invalid format of spellAction for affix %d level %d spellActionName %s", affixId, level, _spellActionName )
		end

	end

	return spellDefName

end


--
function UI:GetAutogenItemBaseDefName( decomposition )

	local baseDefName = "Module_Autogen_Default"

	if type( decomposition ) ~= "table" then
		sys.log( "UI:GetAutogenItemBaseDefName()[ERROR]: invalid type of the 1-st paramenter ('decomposition'); 'table' expected, got '%s'", type( decomposition ) )
		return baseDefName
	end

	if type( decomposition.affixes ) ~= "table" then
		sys.log( "UI:GetAutogenItemBaseDefName()[ERROR]: invalid type of 'decomposition.affixes'; 'table' expected, got '%s'", type( decomposition.affixes ) )
		return baseDefName
	end

	-- деф берется из аффиксов;
	-- прописанный деф может быть только у одного из аффиксов модуля
	-- если нигде не прописано, то дефолтный
	for affixIdx, affixData in pairs( decomposition.affixes ) do

		local affixDef = UI:GetAutogenAffixDef( affixData.affixId )
		if affixDef then

			if affixDef.moduleBaseDefName and affixDef.moduleBaseDefName ~= "" then
				baseDefName = affixDef.moduleBaseDefName
				break
			end

		else
			sys.log( "UI:GetAutogenItemBaseDefName()[ERROR]: cannot find def for affix %d", affixData.affixId )
		end

	end

	return baseDefName

end


-- значения для подстановки в текстовое описание аффикса
function UI:GetAutogenAffixDescParams( affixId )

	local params = {}

	if type( affixId ) ~= "number" then
		sys.log( "UI:GetAutogenAffixDescParams()[ERROR]: invalid type of the 1-st parameter ('affixId'); 'number' expected, got 'type( affixId )'" )
		return params
	end

	local affixName, affixGroupId = UI:GetAutogenAffixNameAndGroup( affixId )
	if affixName == "" or affixGroupId == -1 then
		sys.log( "UI:GetAutogenAffixDescParams()[ERROR]: fail to get name or group for affix %d", affixId )
		return params
	end

	local affixGroupName = UI:Val2Key( _G.AutogenAffixGroup, affixGroupId )
	if affixGroupName == "" then
		sys.log( "UI:GetAutogenAffixDescParams()[ERROR]: fail to get group name for group %d", affixGroupId )
		return params
	end

	if type( _G.AffixTooltips ) ~= "table" then
		sys.log( "UI:GetAutogenAffixDescParams()[ERROR]: cannot find table '_G.AffixTooltips'" )
		return params
	end

	if type( _G.AffixTooltips[ affixGroupName ] ) == "table" and type( _G.AffixTooltips[ affixGroupName ][ affixName ] ) == "table" then
		params = _G.AffixTooltips[ affixGroupName ][ affixName ]
	else
		sys.log( "UI:GetAutogenAffixDescParams()[ERROR]: cannot find table _G.AffixTooltips['%s']['%s']", affixGroupName, affixName )
	end

	return params

end


-- автоген еще не сроллен, есть только начальные параметры для ролла
function UI:Autogen2StrNotRolled( autogenClassId, rank )

	local str = "unknown"

	if type( autogenClassId ) ~= "number" then
		sys.log( "UI:Autogen2StrNotRolled()[ERROR]: invalid type of the 1-st parameter ('autogenClassId'); 'number' expected, got 'type( autogenClassId )'" )
		return str
	end

	if type( rank ) ~= "number" then
		sys.log( "UI:Autogen2StrNotRolled()[ERROR]: invalid type of the 2-nd parameter ('rank'); 'number' expected, got 'type( rank )'" )
		return str
	end

	local strAutogenClass = UI:AutogenClass2Str( autogenClassId )
	local strRank = tostring( rank )

	local tSubst =
	{
		class	= strAutogenClass,
		rank	= strRank,
	}

	str = UI:GetStringByName( "bundleContent_AUTOGEN" )

	local numSubst = 0
	str, numSubst = string.gsub( str, "%$(.-)%$", tSubst )

	if numSubst ~= 2 then
		sys.log( "UI:BundleItem2Str()[ERROR]: invalid placeholders in string 'bundleContent_AUTOGEN'; '$class$' and '$rank$' expected" )
		local strFix = string.format( "[INVALID STRING]class %s rank %s", strAutogenClass, strRank )
		str = str.." ".. strFix
	end

	return str

end


-- нет сохраненного дефа, есть только роллдата
function UI:Autogen2StrByRollData( rollData, upgradeLevel, bWithColor, bSelColor, bShowRank, bShowObsolete, bAltColor )

	local str = UI.autogenDefaultDefName

	if type( rollData ) ~= "table" then
		sys.log( "UI:Autogen2StrByRollData()[ERROR]: invalid type of the 1-st parameter ('rollData'); 'table' expected, got '%s'", type( rollData ) )
		return str
	end

	if type( upgradeLevel ) ~= "number" then
		sys.log( "UI:Autogen2StrByRollData()[ERROR]: invalid type of the 2-nd parameter ('upgradeLevel'); 'number' expected, got '%s'", type( upgradeLevel ) )
		return str
	end

	if bWithColor ~= nil then
		if type( bWithColor ) ~= "boolean" then
			sys.log( "UI:Autogen2StrByRollData()[ERROR]: invalid type of the 3-rd parameter ('bWithColor'); 'boolean' or 'nil' expected, got '%s'", type( bWithColor ) )
			bWithColor = nil
		end
	end

	if bWithColor == nil then
		bWithColor = true
	end

	if bShowRank ~= nil then
		if type( bShowRank ) ~= "boolean" then
			sys.log( "UI:Autogen2StrByRollData()[ERROR]: invalid type of the 5-th parameter ('bShowRank'); 'boolean' or 'nil' expected, got '%s'", type( bShowRank ) )
			bShowRank = nil
		end
	end

	if bShowRank == nil then
		bShowRank = true
	end

	if bShowObsolete ~= nil then
		if type( bShowObsolete ) ~= "boolean" then
			sys.log( "UI:Autogen2StrByRollData()[ERROR]: invalid type of the 6-th parameter ('bShowObsolete'); 'boolean' or 'nil' expected, got '%s'", type( bShowObsolete ) )
			bShowObsolete = nil
		end
	end

	if bShowObsolete == nil then
		bShowObsolete = true
	end

	local def = _G.GenerateAutogenDef( rollData, upgradeLevel )
	if not def then
		sys.log( "UI:Autogen2StrByRollData()[ERROR]: fail to generate autogen def" )
		return str
	end

	local defName = def.baseDefName

	str = UI:Autogen2StrInternal( defName, def, rollData )

	if bShowRank then
		str = UI:AddRankToItemName( str, defName, def )
	end

	if bShowObsolete then
		str = UI:AddObsoleteToItemName( str, defName, def )
	end

	if bWithColor then

		local quality = def.mark or -1
		local colorId = quality ~= -1 and quality or UI.MK1_QUALITY	-- #0022915 - если марк в дефинишене не прописан, то считается, то mk1
		local color = UI:GetItemQualityColor( colorId, bSelColor, bAltColor )

		local strColor = UI:Color2Str( color )
		str = string.format( "%s%s", strColor, str )

	end

	return str

end


-- есть сохраненный деф
function UI:Autogen2StrByDef( defName, bWithColor, bSelColor, bShowRank, bShowObsolete, bAltColor )

	return UI:GetEntityLocalizedNameByDef( defName, bWithColor, bSelColor, bShowRank, bShowObsolete, bAltColor )

end


--
function UI:Autogen2StrInternal( defName, def, rollData )

	local str = "unknown"

	if type( defName ) ~= "string" then
		sys.log( "UI:Autogen2StrInternal()[ERROR]: invalid type of the 1-st parameter ('defName'); 'string' expected, got '%s'", type( defName ) )
		return str
	end

	str = defName

	if type( def ) ~= "table" then
		sys.log( "UI:Autogen2StrInternal()[ERROR]: invalid type of the 2-nd parameter ('def'); 'table' expected, got '%s'", type( def ) )
		return str
	end

	if type( rollData ) ~= "table" then
		sys.log( "UI:Autogen2StrInternal()[ERROR]: invalid type of the 3-rd parameter ('rollData'); 'table' expected, got '%s'", type( rollData ) )
		return str
	end

	-- базовая часть имени - по общим правилам модулей
	str = UI:Module2StrInternal( defName, def )

	-- Сролленные аффиксы отображаются в виде префиксов и постфиксов к названию.
	-- SC-112190 Правила:
	-- для префикса выбираем самый мощный аффикс из сгенеренных;
	-- для постфикса выбираем второй по мощи аффикс из сгенеренных;
	-- мощность выбирается сортировкой вначале по рангу аффикса, а при равном ранге аффиксов по среднему роллу внутри аффикса.

	local bestAffixes = UI:GetAutogenBestAffixes( rollData )

	local affixPrefix = bestAffixes[ 1 ]
	if affixPrefix then
		local strPrefix = UI:AutogenAffix2Str( affixPrefix.affixId, affixPrefix.level, false )
		str = string.format( "%s %s", strPrefix, str )
	end

	local affixPostfix = bestAffixes[ 2 ]
	if affixPostfix then
		local strPostfix = UI:AutogenAffix2Str( affixPostfix.affixId, affixPostfix.level, true )
		str = string.format( "%s %s", str, strPostfix )
	end

	return str

end


-- возвращает два лучших аффикса, используется для генерации имени и иконки
function UI:GetAutogenBestAffixes( rollData )

	--SC-112478
	--выбирать из всех сролленых аффиксы у которых самый большой cost_coef
	--при одинаковом cost_coef выбирать те, у которых выше индекс уровня аффикса
	--при одинаковых индексах аффикса выбирать те, у которых выше ролл

	local bestAffixes = {}

	if type( rollData ) ~= "table" then
		sys.log( "UI:GetAutogenBestAffixes()[ERROR]: invalid type of the 1-st patam ('rollData'); 'table' expected, got '%s'", type( rollData ) )
		return bestAffixes
	end

	local decomposition = _G.DecompositeAutogenRollData( rollData )

	if not decomposition or not decomposition.affixes then
		return bestAffixes
	end

	local allAffixes = decomposition.affixes

	for affixIdx, affixData in pairs( allAffixes ) do

		affixData.averageVal = 0

		if affixData.rolledVals and next( affixData.rolledVals ) then

			local valsSum = 0
			for valIdx, val in pairs( affixData.rolledVals ) do
				valsSum = valsSum + val
			end

			affixData.averageVal = valsSum / #affixData.rolledVals

		end

		affixData.costCoef = 1

		local affixDef = UI:GetAutogenAffixDef( affixData.affixId )
		if affixDef then
			if type( affixDef.cost_coef ) == "number" then
				affixData.costCoef = affixDef.cost_coef
			end
		end

	end

	local function fnSort( affixData1, affixData2 )

		-- по cost_coef
		if affixData1.costCoef ~= affixData2.costCoef then
			return affixData1.costCoef > affixData2.costCoef
		end

		-- по уровню
		if affixData1.level ~= affixData2.level then
			return affixData1.level > affixData2.level
		end

		-- по роллу
		if affixData1.averageVal ~= affixData2.averageVal then
			return affixData1.averageVal > affixData2.averageVal
		end

		-- по id
		return affixData1.affixId < affixData2.affixId

	end

	table.sort( allAffixes, fnSort )

	for affixIdx = 1, math.min( 2, #allAffixes ) do
		table.insert( bestAffixes, allAffixes[ affixIdx ] )
	end

	return bestAffixes

end


--
function UI:Module2StrInternal( defName, def )

	local str = "unknown"

	if type( defName ) ~= "string" then
		sys.log( "UI:Module2StrInternal()[ERROR]: invalid type of the 1-st parameter ('defName'); 'string' expected, got '%s'", type( defName ) )
		return str
	end

	str = defName

	if type( def ) ~= "table" then
		sys.log( "UI:Module2StrInternal()[ERROR]: invalid type of the 2-nd parameter ('def'); 'table' expected, got '%s'", type( def ) )
		return str
	end

	if not UI:IsStrEmpty( def.uiName ) then
		str = UI:GetStringByName( def.uiName )
	else
		local subType = UI:GetItemSubType( defName, def )
		if subType ~= -1 then
			str = UI:ItemSubType2Str2( subType )
		else
			sys.log( "UI:Module2StrInternal()[ERROR]: cannot find item sub type for \"%s\"", defName )
		end
	end

	return str

end


--
function UI:AddRankToItemName( str, defName, def )

	local minRank = UI:GetItemEquipMinRank( defName, def )
	local maxRank = UI:GetItemEquipMaxRank( defName, def )

	-- SC-112483 для автогенов всегда пишется минимальный ранг
	if UI:IsDefAutogen( defName ) or UI:IsDefAutogenBase( defName ) then
		str = string.format( "%s %d", str, minRank )
	else
		if minRank ~= -1 and maxRank ~= -1 then
			if not( minRank == 1 and maxRank == UI:GetMaxRank() ) then	-- #0087847,комм.(0394809) - цифра ранга подставляется в название только если диапазон рангов предмета не от первого до максимального.
				str = string.format( "%s %d", str, maxRank )			-- #0059898,комм.(0242554) - всегда максимальный ранг, от опции itemRankMode не зависит
			end
		end
	end

	return str

end


--
function UI:AddObsoleteToItemName( str, defName, def )

	if def.outdated == true then
		local strObsolete = string.format( "%s(%s)", UI:Color2Str( UI.PARAM_DELTA_MINUS_COLOR ), UI:GetStringByName( "obsoleteItem" ) )
		str = string.format( "%s %s", str, strObsolete )
	end

	return str

end


