--
function UI:GetZoneNextConflictTime( zoneId )

	local nextTime = UI.INVALID_U64_ID

	if not _G.MasterServer_IsConnected() then
		sys.log( "UI:GetZoneNextConflictTime()[ERROR]: not connected" )	-- коннект нужен для получения времени
		return nextTime
	end

	if type( zoneId ) ~= "number" then
		sys.log( "UI:GetZoneNextConflictTime()[ERROR]: invalid type of the 1-st param ('zoneId'); 'number' expected, got '%s'", type( zoneId ) )
		return nextTime
	end

	local zoneDesc = _G.SpaceZoneById and _G.SpaceZoneById[ zoneId ]
	if type( zoneDesc ) ~= "table" then
		sys.log( "UI:GetZoneNextConflictTime()[ERROR]: invalid type of the _G.SpaceZoneById[%d]; \"table\" expected, got \"%s\"", zoneId, type( zoneDesc ) )
		return nextTime
	end

	if zoneDesc.conflictIntervalStart == nil and zoneDesc.conflictIntervalLong == nil then
		return nextTime
	end

	if type( zoneDesc.conflictIntervalStart ) ~= "string" then
		sys.log( "UI:GetZoneNextConflictTime()[ERROR]: invalid type of SpaceZoneById[%d].conflictIntervalStart; 'string' expected, got '%s'", zoneId, type( zoneDesc.conflictIntervalStart ) )
		return nextTime
	end

	if type( zoneDesc.conflictIntervalLong ) ~= "number" then
		sys.log( "UI:GetZoneNextConflictTime()[ERROR]: invalid type of SpaceZoneById[%d].conflictIntervalLong; 'number' expected, got '%s'", zoneId, type( zoneDesc.conflictIntervalLong ) )
		return nextTime
	end

	local curTime = _G.MasterServer_GetServerTime()

	local conflictStartTime = _G.MasterServer_StrToTime( zoneDesc.conflictIntervalStart )
	if conflictStartTime == nil then
		sys.log( "UI:GetZoneNextConflictTime()[ERROR]: invalid time format '%s' in SpaceZoneById[%d].conflictIntervalStart", zoneDesc.conflictIntervalStart, zoneId )
		return nextTime
	end

	if conflictStartTime > curTime then
		nextTime = conflictStartTime
	else
		local timeFromStartSec = ( ( curTime - conflictStartTime ) * 0.001 ).l
		local curIntervalIdx = math.floor( timeFromStartSec / zoneDesc.conflictIntervalLong )
		nextTime = conflictStartTime + ( curIntervalIdx + 1 ) * zoneDesc.conflictIntervalLong * 1000
	end

	return nextTime

end


--
function UI:GetTooltipForItem( defName )

	local tooltipData = nil

	if type( defName ) ~= "string" then
		sys.log( "UI:GetTooltipForItem()[ERROR]: invalid type of the 1-st param ('defName'); 'string' expected, got '%s'", type( defName ) )
		return tooltipData
	end

	tooltipData = {}

	if UI:IsDefTokenItem( defName ) then

		tooltipData.tooltipType	= UI.tooltipTypes.TOKEN_ITEM
		tooltipData.defName		= defName

	elseif UI:IsDefModule( defName ) or UI:IsDefAmmo( defName ) then

		tooltipData.tooltipType		= UI.tooltipTypes.MODULE
		tooltipData.defName			= defName

		if UI:IsDefAutogen( defName ) then
			tooltipData.autogenItem = UI:GetAutogenItem( defName )
		end

	elseif UI:IsDefResource( defName ) or UI:IsDefBlueprint( defName ) then

		tooltipData.tooltipType	= UI.tooltipTypes.RESOURCE
		tooltipData.defName		= defName

	elseif UI:IsDefBundle( defName ) then

		tooltipData.tooltipType	= UI.tooltipTypes.TEXT_LARGE
		tooltipData.caption		= UI:GetEntityLocalizedNameByDef( defName, true, false, false, false )
		tooltipData.text		= UI:GetBundleDesc( defName, false, UI.TooltipWnd_shared:GetTextColor() )

	elseif UI:IsDefShip( defName ) then

		tooltipData.tooltipType	= UI.tooltipTypes.SHIP
		tooltipData.defName		= defName

	elseif UI:IsDefJunk( defName ) then

		tooltipData.tooltipType	= UI.tooltipTypes.JUNK
		tooltipData.defName		= defName

	else

		tooltipData.tooltipType	= UI.tooltipTypes.TEXT_LARGE
		tooltipData.caption		= UI:GetEntityLocalizedNameByDef( defName, true, false, true )
		tooltipData.text		= UI:GetEntityDescByDef( defName )

	end

	return tooltipData

end


--
function UI:GetBattlePassStageInfo( stage )

	local stageInfo = nil

	if type( stage ) ~= "number" then
		sys.log( "UI:GetBattlePassStageInfo()[ERROR]: invalid type of the 1-st param ('stage'); 'number' expected, got '%s'", type( stage ) )
		return stageInfo
	end

	if type( _G.battle_pass ) ~= "table" then
		sys.log( "UI:GetBattlePassStageInfo()[ERROR]: invalid type of _G.battle_pass; 'table' expected, got '%s'", type( _G.battle_pass ) )
		return stageInfo
	end

	if type( _G.battle_pass.stages ) ~= "table" then
		sys.log( "UI:GetBattlePassStageInfo()[ERROR]: invalid type of _G.battle_pass.stages; 'table' expected, got '%s'", type( _G.battle_pass.stages ) )
		return stageInfo
	end

	stageInfo = _G.battle_pass.stages[ stage ]
	if type( stageInfo ) ~= "table" then
		sys.log( "UI:GetBattlePassStageInfo()[ERROR]: invalid type of _G.battle_pass.stages[%d]; 'table' expected, got '%s'", stage, type( stageInfo ) )
		stageInfo = nil
	end

	return stageInfo

end


--
function UI:GetBattlePassLevelInfo( stage, level )

