	if type( levelInfo ) ~= "table" then
		sys.log( "UI:GetBattlePassLevelInfo()[ERROR]: invalid type of _G.battle_pass.stages[%d].reward[%d]; 'table' expected, got '%s'", stage, level, type( levelInfo ) )
