-- в ивентовых кредитах (_G.GameStore.CreditsType.CT_EVENT)
function UI:GetBattlePassLevelUnlockPrice( stage, level )

	local price = 0

	if type( stage ) ~= "number" then
		sys.log( "UI:GetBattlePassLevelUnlockPrice()[ERROR]: invalid type of the 1-st param ('stage'); 'number' expected, got '%s'", type( stage ) )
		return price
	end

	if type( level ) ~= "number" then
		sys.log( "UI:GetBattlePassLevelUnlockPrice()[ERROR]: invalid type of the 2-nd param ('level'); 'number' expected, got '%s'", type( level ) )
		return price
	end

	local levelInfo = UI:GetBattlePassLevelInfo( stage, level )
	if not levelInfo then
		sys.log( "UI:GetBattlePassLevelUnlockPrice()[ERROR]: cannot fin level info for stage %d level %d", stage, level )
		return price
	end

	if type( levelInfo.cost ) == "number" then
		price = levelInfo.cost
	else
		sys.log( "UI:GetBattlePassLevelUnlockPrice()[ERROR]: invalid type of _G.battle_pass[%d].reward[%d].cost; 'number' expected, got '%s'", stage, level, type( levelInfo.cost ) )
	end

	return price

end


--
function UI:GetBattlePassUiShips()

	local shipDefNames = {}

	if type( _G.battle_pass ) ~= "table" then
		sys.log( "UI:GetBattlePassUiShips()[ERROR]: invalid type of _G.battle_pass; 'table' expected, got '%s'", type( _G.battle_pass ) )
		return shipDefNames
	end

	if _G.battle_pass.ui_ship ~= nil then
		if type( _G.battle_pass.ui_ship ) == "string" then
			if _G.battle_pass.ui_ship ~= "" then
				table.insert( shipDefNames, _G.battle_pass.ui_ship )
			end
		else
			sys.log( "UI:GetBattlePassUiShips()[ERROR]: invalid type of _G.battle_pass.ui_ship; 'string' or 'nil' expected, got '%s'", stage, level, type( _G.battle_pass.ui_ship ) )
		end
	end

	if _G.battle_pass.ui_ship_2 ~= nil then
		if type( _G.battle_pass.ui_ship_2 ) == "string" then
			if _G.battle_pass.ui_ship_2 ~= "" then
				table.insert( shipDefNames, _G.battle_pass.ui_ship_2 )
			end
		else
			sys.log( "UI:GetBattlePassUiShips()[ERROR]: invalid type of _G.battle_pass.ui_ship_2; 'string' or 'nil' expected, got '%s'", stage, level, type( _G.battle_pass.ui_ship_2 ) )
		end
	end
	
	return shipDefNames

end


--
function UI:GetBattlePassUnlockedLevel( stage )

	local unlockedLevel = -1

	if type( stage ) ~= "number" then
		sys.log( "UI:GetBattlePassUnlockedLevel()[ERROR]: invalid type of the 1-st param ('stage'); 'number' expected, got '%s'", type( stage ) )
		return unlockedLevel
	end

	if UI.serverData.battlePassPlayerProgress.progress and UI.serverData.battlePassPlayerProgress.progress[ stage ] then
		unlockedLevel = UI.serverData.battlePassPlayerProgress.progress[ stage ].unlockedLevel
	end

	return unlockedLevel

end


--
function UI:IsBattlePassPremiumUnlocked( stage )

	local bPremiumUnlocked = false

	if type( stage ) ~= "number" then
		sys.log( "UI:IsBattlePassPremiumUnlocked()[ERROR]: invalid type of the 1-st param ('stage'); 'number' expected, got '%s'", type( stage ) )
		return bPremiumUnlocked
	end

	local startTime = UI:GetBattlePassStartTime()
	if startTime ~= UI.INVALID_U64_ID then

		for premIdx, premInfo in pairs( UI.serverData.battlePassPlayerPremium ) do

			if premInfo.startTime == startTime then

				if premInfo.stages then

					for stageIdx, _stage in pairs( premInfo.stages ) do
						if _stage == stage then
							bPremiumUnlocked = true
							break
						end
					end

				end

				if bPremiumUnlocked then
					break
				end

			end

		end

	end

	return bPremiumUnlocked

end


--
function UI:IsBattlePassRewardAcquired( stage, level )

	if type( stage ) ~= "number" then
		sys.log( "UI:IsBattlePassRewardAcquired()[ERROR]: invalid type of the 1-st param ('stage'); 'number' expected, got '%s'", type( stage ) )
		return false
	end

	if type( level ) ~= "number" then
		sys.log( "UI:IsBattlePassRewardAcquired()[ERROR]: invalid type of the 2-nd param ('level'); 'number' expected, got '%s'", type( level ) )
		return false
	end

	local bundleDefName = UI:GetBattlePassRewardBundle( stage, level )
	if bundleDefName == "" then
		return false
	end

	local bAcquired = false

	if UI.serverData.battlePassPlayerProgress.acquiredItems then
		for itemIdx, defName in pairs( UI.serverData.battlePassPlayerProgress.acquiredItems ) do
			if defName == bundleDefName then
				bAcquired = true
				break
			end
		end
	end

	return bAcquired

end


--
function UI:GetBattlePassStartTime()

	return UI.serverData.battlePassActivation.startTime or UI.INVALID_U64_ID

end


--
function UI:GetBattlePassEndTime()

	local endTime = UI.INVALID_U64_ID

	if UI.serverData.battlePassActivation.activeStages then
		for stageIdx, stageInfo in pairs( UI.serverData.battlePassActivation.activeStages ) do
			if stageInfo.endTime > endTime then
				endTime = stageInfo.endTime
			end
		end
	end

	return endTime

end


--
function UI:GetBattlePassActiveStages()

	local activStages = {}

	if _G.MasterServer_IsConnected() then

		local curTime = _G.MasterServer_GetServerTime()
		if UI.serverData.battlePassActivation.startTime and UI.serverData.battlePassActivation.startTime ~= UI.INVALID_U64_ID and curTime >= UI.serverData.battlePassActivation.startTime then

			for stageIdx, stageInfo in pairs( UI.serverData.battlePassActivation.activeStages ) do
				if stageInfo.endTime == UI.INVALID_U64_ID or curTime < stageInfo.endTime then
					table.insert( activStages, stageInfo.stage )
				end
			end

		end

	end

	return activStages

end


--
function UI:GetBattlePassStageEndTime( stage )

	local stageEndTime = UI.INVALID_U64_ID

	if type( stage ) ~= "number" then
		sys.log( "UI:GetBattlePassStageEndTime()[ERROR]: invalid type of the 1-st param ('stage'); 'number' expected, got '%s'", type( stage ) )
		return stageEndTime
	end

	if UI.serverData.battlePassActivation.activeStages then

		for stageIdx, stageInfo in pairs( UI.serverData.battlePassActivation.activeStages ) do
			if stageInfo.stage == stage then
				stageEndTime = stageInfo.endTime
				break
			end
		end

	end

	return stageEndTime

end


