--
function UI:PremiumTime2Str( time, baseColor, selColor )

	if baseColor == nil then
		baseColor = UI.TEXT_BASE_COLOR
	end

	if selColor == nil then
		selColor = UI.TEXT_SEL_COLOR
	end

	local str = ""

	local strBaseColor	= UI:Color2Str( baseColor )
	local strSelColor	= UI:Color2Str( selColor )

	local strTime = string.format( "%s%s%s", strSelColor, UI:Time2Str421( time ), strBaseColor )

	str = UI:GetStringByName( "mail_attachmentTooltip_premium" )
	str = string.gsub( str, "%$time%$", strTime )
	str = string.format( "%s%s", strBaseColor, str )

	return str

end


--
function UI:GetZoneEventVisualMap( eventId )

	if type( eventId ) ~= "number" then
		sys.log( "UI:GetZoneEventVisualMap()[ERROR]: invalid type of the 1-st param ('eventId'); 'number' expected, got '%s'", type( eventId ) )
		return nil
	end

	if type( _G.Events ) ~= "table" then
		sys.log( "UI:GetZoneEventVisualMap()[ERROR]: invalid type of _G.Events; 'table' expected, got '%s'", type( _G.Events ) )
		return nil
	end

	if type( _G.Events[ eventId ] ) ~= "table" then
		sys.log( "UI:GetZoneEventVisualMap()[ERROR]: invalid type of _G.Events[%d]; 'table' expected, got '%s'", eventId, type( _G.Events[ eventId ] ) )
		return nil
	end

	if _G.Events[ eventId ].visualMap == nil then
		return nil
	end

	if type( _G.Events[ eventId ].visualMap ) ~= "table" then
		sys.log( "UI:GetZoneEventVisualMap()[ERROR]: invalid type of _G.Events[%d].visualMap; 'table' or 'nil' expected, got '%s'", eventId, type( _G.Events[ eventId ].visualMap ) )
		return nil
	end

	return _G.Events[ eventId ].visualMap

end


--
function UI:GetPlayerNameFromKillInfo( params, bKiller, baseColor )

	local nickName = "unknown"

	if type( params ) ~= "table" then
		sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of the 1-st parameter (\"params\"); \"table\" expected, got \"%s\"", type( params ) )
		return nickName
	end

	if type( bKiller ) ~= "boolean" then
		sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of the 1-st parameter (\"bKiller\"); \"boolean\" expected, got \"%s\"", type( bKiller ) )
		return nickName
	end

	local playerParamsName = bKiller and "killer" or "victim"
	local playerParams = params[ playerParamsName ]

	if type( playerParams ) ~= "table" then
		sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of (\"params.%s\"); \"table\" expected, got \"%s\"", playerParamsName, type( playerParams ) )
		return nickName
	end

	if type( playerParams.playerId ) ~= "number" then
		sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of (\"params.%s.playerId\"); \"number\" expected, got \"%s\"", playerParamsName, type( playerParams.playerId ) )
		return nickName
	end

	local bIsShip = false

	if type( playerParams.isShip ) == "boolean" then
		bIsShip = playerParams.isShip
	else
		sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of (\"params.%s.isShip\"); \"boolean\" expected, got \"%s\"", playerParamsName, type( playerParams.isShip ) )
		return nickName
	end

	if playerParams.playerId ~= -1 and ( bIsShip or bKiller ) then -- для жертвы выводим ник игрока только если убит корабль игрока

		nickName = UI:MakePlayerNameById( playerParams.playerId, true, false )

	else

		local defName = ""

		if type( playerParams.name ) == "string" then

			if type( playerParams.isDef ) == "boolean" then
				defName = playerParams.name
			else
				sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of (\"params.%s.isDef\"); \"boolean\" expected, got \"%s\"", playerParamsName, type( playerParams.isDef ) )
			end

		else
			sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of (\"params.%s.name\"); \"string\" expected, got \"%s\"", playerParamsName, type( playerParams.name ) )
		end

		if defName ~= "" then

			if bIsShip then
				nickName = UI:GetBotNameByDef( defName )
			else
				nickName = UI:GetEntityLocalizedNameByDef( defName, false, false, false, nil )
			end

		end

	end


	-- определение цвета

	local team = -1

	if type( playerParams.team ) == "number" then
		team = playerParams.team
	else
		sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of (\"params.%s.team\"); \"number\" expected, got \"%s\"", playerParamsName, type( playerParams.team ) )
	end

	local objColor = UI:GetKillMsgPlayerColor( playerParams.playerId, team )
	nickName = string.format( "%s%s%s", UI:Color2Str( objColor ), nickName, UI:Color2Str( baseColor ) )

	return nickName

end


--
function UI:GetKillMsgPlayerColor( playerId, team )

	local localPlayerId = UI.HudWnd.localPlayerId

	local gameplay		= _G.GetCurrentGameMode()

	local myTeam = _G.CL_GetPlayerTeam( localPlayerId )
	if myTeam == 0 then
		if gameplay == ai.Gameplay.THREE_TEAMS_DM then
			myTeam = ai.ThreeTeamsDMTeam1
		else
			myTeam = 1
		end
	end

	local relationship	= ai.Relationship:GetRelationship( team, myTeam )
	local bSecondEnemy	= false

	local bMySquad		= false
	local bAggressor	= false
	local bCriminal		= false
	local bCivilian		= false

	if playerId ~= -1 then

		local mySqid		= _G.CL_GetPlayerSquad( localPlayerId )
		local playerSqid	= _G.CL_GetPlayerSquad( playerId )

		bMySquad = mySqid ~= UI.INVALID_U64_ID and playerSqid == mySqid

		if gameplay == ai.Gameplay.FREE_SPACE then
			bAggressor,	bCriminal, bCivilian = _G.CL_GetFreeSpacePlayerFlags( playerId )
		end

	end

	if gameplay == ai.Gameplay.THREE_TEAMS_DM and relationship == ai.RelatioshipType.ENEMY then
		bSecondEnemy = UI:IsThreeTeamsDMSecondEnemy( myTeam, team )
	end

	return UI:GetGameObjColorInternal( relationship, team, bSecondEnemy, gameplay, bMySquad, bAggressor, bCriminal, bCivilian, playerId )

end


--
function UI:CanItemBeAcivatedInBattleRoyal( defName )

	local bCanbeActivated = false

	if type( defName ) ~= "string" then
		sys.log( "UI:CanItemBeAcivatedInBattleRoyal()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return bCanbeActivated
	end

	local def = _G.Def[ defName ]
	if not def then
		sys.log( "UI.CanItemBeAcivatedInBattleRoyal()[ERROR]: cannot find def for '%s'", defName )
		return bCanbeActivated
	end

	if def.can_be_activated == nil then
		return bCanbeActivated
	end

	if type( def.can_be_activated ) == "boolean" then
		bCanbeActivated = def.can_be_activated
	else
		sys.log( "UI.CanItemBeAcivatedInBattleRoyal()[ERROR]: invalid type of _G.Def['%s'].can_be_activated; 'boolean' or 'nil' expected, got '%s'", type( def.can_be_activated ) )
	end

	return bCanbeActivated

end


