--
function UI:RequestYupPurchasesPrices( bIgnoreDelayTimer )

	if bIgnoreDelayTimer ~= nil then
		if type( bIgnoreDelayTimer ) ~= "boolean" then
			sys.log( "UI:RequestYupPurchasesPrices()[ERROR]: invalid type of the 1-st param ('bIgnoreDelayTimer'); 'boolean' expected, got '%s'", type( bIgnoreDelayTimer ) )
			bIgnoreDelayTimer = nil
		end
	end

	if bIgnoreDelayTimer == nil then
		bIgnoreDelayTimer = false
	end

	if type( _G.PremiumLicenses ) ~= "table" then
		sys.log( "UI:RequestYupPurchasesPrices()[ERROR]: invalid type of _G.PremiumLicenses; 'table' expected, got '%s'", type( _G.PremiumLicenses ) )
		return
	end

	local guids = {}

	for licenseIdx, license in pairs( _G.PremiumLicenses ) do

		local guid = UI:GetDlcYupGuid( license.dlcName )
		if guid ~= "" then
			table.insert( guids, guid )
		end

	end

	if next( guids ) then
		_G.MasterServer_RequestYupPurchasesPrices( guids, bIgnoreDelayTimer )
	end

end


-- SC-111975 некоторые корабли доступны только в определенные дни года;
-- здесь запоминаются временные точки, в которые надо запустить ивент на апдейт задисэйбленного состояния кораблей;
-- вызывается при инициализации данных из серверного магазина
function UI:UpdateShipsNextDisableTimes()

	UI.shipsNextDisableTimes = {}
	UI.numShipsNextDisableTimes = 0

	if not _G.MasterServer_IsConnected() then
		return
	end

	local curTime = _G.MasterServer_GetServerTime()

	for itemIdx, item in pairs( self.serverData.shop ) do

		if item.type == _G.GameStore.ItemType.IT_VESSEL then

			local defName = item.defName
			if UI:IsShipEvolving( defName ) then
				defName = UI:GetEvolvingShipBaseDef( defName )
			end

			local enableTimeFrom, enableTimeTill = _G.GameStore_GetVesselAvailableTime( defName )

			if enableTimeFrom ~= UI.INVALID_U64_ID and enableTimeTill ~= UI.INVALID_U64_ID then

				-- время сохраняется только то, которое в будущем, время в прошлом интереса не представляет
				if enableTimeFrom >= curTime then
					table.insert( UI.shipsNextDisableTimes, { defName = defName, time = enableTimeFrom } )
				end

				if enableTimeTill >= curTime then
					table.insert( UI.shipsNextDisableTimes, { defName = defName, time = enableTimeTill } )
				end

			end

		end

	end

	-- все временные точки, в которые надо будет произвести апдейт, складываются в сортированный массив,
	-- билажайшие к текущему времени точки - в конце списка
	if next( UI.shipsNextDisableTimes ) then

		local function fnSort( info1, info2 )
			return info1.time > info2.time
		end

		table.sort( UI.shipsNextDisableTimes, fnSort )

		UI.numShipsNextDisableTimes = #UI.shipsNextDisableTimes

	end

end


-- SC-111975 некоторые корабли доступны только в определенные дни года;
-- здесь проверяется, не надо ли запустить ивент на апдейт задисэйбленного состояния кораблей, и если надо, то ивент запускается;
-- вызывается каждый кадр
function UI:CheckUpdateShipsDisabledByTime()

	if not _G.MasterServer_IsConnected() then
		return
	end

	if not next( UI.shipsNextDisableTimes ) then
		return
	end

	-- проверяется ближайшая временная точка адпейта
	local nextTimeInfo = UI.shipsNextDisableTimes[ UI.numShipsNextDisableTimes ]
	local curTime = _G.MasterServer_GetServerTime()

	if curTime >= nextTimeInfo.time then

		UI.HangarWnd:OnShipDisabledByTimeChanged( nextTimeInfo.defName )

		-- адпдейт прошел, стработавшая временная точка удаляется из списка
		UI.shipsNextDisableTimes[ UI.numShipsNextDisableTimes ] = nil
		UI.numShipsNextDisableTimes = UI.numShipsNextDisableTimes - 1

	end

end


-- SC-111975 некоторые корабли доступны только в определенные дни года;
-- здесть проверяется, доступен ли корабль в данный момент
function UI:IsShipDisabledByTime( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetPlayerNameFromKillInfo()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return false
	end

	if not _G.MasterServer_IsConnected() then
		return false
	end

	if UI:IsShipEvolving( defName ) then
		defName = UI:GetEvolvingShipBaseDef( defName )
	end

	local enableTimeFrom, enableTimeTill = _G.GameStore_GetVesselAvailableTime( defName )
	if enableTimeFrom == UI.INVALID_U64_ID or enableTimeTill == UI.INVALID_U64_ID then
		return false
	end

	local curTime = _G.MasterServer_GetServerTime()
	return curTime < enableTimeFrom or curTime >= enableTimeTill

end


-- SC-111975 некоторые корабли доступны только в определенные дни года;
-- здесь формируется строка вида 'Доступен с $time_from$ до $time_till$'
function UI:GetShipDisabledByTimeString( defName )

	local str = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipDisabledByTimeString()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return str
	end

	if UI:IsShipEvolving( defName ) then
		defName = UI:GetEvolvingShipBaseDef( defName )
	end

	if not UI:IsShipDisabledByTime( defName ) then
		sys.log( "UI:GetShipDisabledByTimeString()[ERROR]: ship '%s' is not disabled at this time", defName )
		return str
	end

	local timeFrom, timeTill = _G.GameStore_GetVesselAvailableTime( defName )

	local dateTimeFrom = _G.PlatformTimeToTable( timeFrom )
	local dateTimeTill = _G.PlatformTimeToTable( timeTill )

	-- строки вида '$day$ апреля' ('april $day$' в англ. версии)
	local strTimeFormatFrom = UI:GetStringByName( string.format( "time_ddDigit_mmStr_%d", dateTimeFrom.month ) )
	local strTimeFormatTill = UI:GetStringByName( string.format( "time_ddDigit_mmStr_%d", dateTimeTill.month ) )

	local numSubst = 0
	local strFrom, numSubst = string.gsub( strTimeFormatFrom, "%$day%$", tostring( dateTimeFrom.day ) )
	if numSubst == 0 then
		sys.log( "UI:GetShipDisabledByTimeString()[ERROR]: cannot find placeholder '$day$' in string '%s'", string.format( "time_ddDigit_mmStr_%d", dateTimeFrom.month ) )
		strFrom = string.format( "[INVALID STRING]%d.%d", dateTimeFrom.day, dateTimeFrom.month )
	end

	numSubst = 0
	local strTill, numSubst = string.gsub( strTimeFormatTill, "%$day%$", tostring( dateTimeTill.day ) )
	if numSubst == 0 then
		sys.log( "UI:GetShipDisabledByTimeString()[ERROR]: cannot find placeholder '$day$' in string '%s'", string.format( "time_ddDigit_mmStr_%d", dateTimeTill.month ) )
		strTill = string.format( "[INVALID STRING]%d.%d", dateTimeTill.day, dateTimeTill.month )
	end

	-- строка вида 'Доступен с $time_from$ до $time_till$'
	str = UI:GetStringByName( "shipTooltip_lockedByTime" )

	local tSubst =
	{
		time_from	= strFrom,
		time_till	= strTill,
	}

	numSubst = 0
	str, numSubst = string.gsub( str, "%$(.-)%$", tSubst )
	if numSubst ~= 2 then
		sys.log( "UI:GetShipDisabledByTimeString()[ERROR]: invalid placeholders in string 'shipTooltip_lockedByTime'; '$time_from$' and '$time_till$' expected" )
		str = string.format( "[INVALID STRING]Available from %s till %s", strFrom, strTill )
	end

	return str

end


--
function UI:UpdateServerData_OnAutogenDestroy( result, requestId, params )

	if result == _G.GameStore.ModuleEquipResult.MER_OK then

		self:OnAutogenInventoryChanged()

		local vid = params.vid

		for idx, shipItem in pairs( self.serverData.allShips ) do

			if shipItem.vid == vid then

				shipItem.equipModules = _G.GameStore_GetEquipmentIids( shipItem.vid )
				self:UpdateIid2Ship( shipItem )

				break

			end

		end

		self.serverData.bInvItemsDirty = true

	end


	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.ModuleEquipResult.MER_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:UpdateServerData_OnAutogenDismantle( result, requestId, params )

	if result == _G.GameStore.ModuleEquipResult.MER_OK then

		local vid = params.vid

		for idx, shipItem in pairs( self.serverData.allShips ) do

			if shipItem.vid == vid then

				shipItem.equipModules = _G.GameStore_GetEquipmentIids( shipItem.vid )
				self:UpdateIid2Ship( shipItem )

				break

			end

		end

		self.serverData.bInvItemsDirty = true

	end


	if self:IsWaitingRequest( requestId ) then

		self:RemoveWaitingRequest( requestId )

		if result ~= _G.GameStore.ModuleEquipResult.MER_OK then
			self:StopWaitingRequests()
		end

	else
		self:UpdateInvItems()
	end

end


--
function UI:GetResourceAutogenDonorExp( defName )

	local exp = 0

	if type( defName ) ~= "string" then
		sys.log( "UI:GetResourceAutogenDonorExp()[ERROR]: invalid type of the 1-st param ('defName'); 'string' expected, got '%s'", type( defName ) )
		return exp
	end

	local def = _G.Def[ defName ]
	if not def then
		sys.log( "UI:GetResourceAutogenDonorExp()[ERROR]: cannot find def for '%s'", defName )
		return exp
	end

	if def.donate_exp == nil then
		return exp
	end

	if type( def.donate_exp ) == "number" then
		exp = def.donate_exp
	else
		sys.log( "UI:GetResourceAutogenDonorExp()[ERROR]: invalid type of _G.Def['%s'].donate_exp; 'number' or 'nil' expected, got '%s'", type( def.donate_exp ) )
	end

	return exp

end


--
function UI:GetAutogenDismantlePrice( iid )

	local price = 0
	local bGold = false

	if type( iid ) ~= "userdata" then
		sys.log( "UI:GetAutogenDismantlePrice()[ERROR]: invalid type of the 1-st param ('iid'); 'userdata' expected, got '%s'", type( iid ) )
		return price, bGold
	end

	if iid == UI.INVALID_U64_ID then
		sys.log( "UI:GetAutogenDismantlePrice()[ERROR]: invalid iid" )
		return price, bGold
	end

	local priceData = _G.GameStore_GetAutogenItemDismantlePrice( iid )
	price = priceData.price
	bGold = priceData.isGold

	return price, bGold

end


--
function UI:GetAutogenAffixIco( affixId )

	if type( affixId ) ~= "number" then
		sys.log( "UI:GetAutogenAffixIco()[ERROR]: invalid type of the 1-st param ('affixId'); 'number' expected, got '%s'", type( affixId ) )
		return UI:GetTex( "NoData" )
	end

	local affixName, affixGroupId = UI:GetAutogenAffixNameAndGroup( affixId )
	if affixName == "" then
		sys.log( "UI:GetAutogenAffixIco()[ERROR]: cannot find name for affix %d", affixId )
		return UI:GetTex( "NoData" )
	end

	local affixGroupName = UI:Val2Key( _G.AutogenAffixGroup, affixGroupId )

	local texName = string.format( "autogen_%s_%s", affixGroupName, affixName )
	return UI:GetTex( texName )

end


-- affixLevel c 0
function UI:GetAutogenAffixColor( affixId, affixLevel )

	local color = UI.WHITE_COLOR

	if type( affixId ) ~= "number" then
		sys.log( "UI:GetAutogenAffixColor()[ERROR]: invalid type of the 1-st param ('affixId'); 'number' expected, got '%s'", type( affixId ) )
		return color
	end

	if type( UI.autogenAffixColors ) ~= "table" then
		sys.log( "UI:GetAutogenAffixColor()[ERROR]: invalid type of UI.autogenAffixColors; 'table' expected, got '%s'", type( UI.autogenAffixColors ) )
		return color
	end

	if type( UI.autogenAffixColors[ affixLevel + 1 ] ) ~= "number" then	-- индексы в autogenAffixColors с 1
		sys.log( "UI:GetAutogenAffixColor()[ERROR]: invalid type of UI.autogenAffixColors[%d]  'table' expected, got '%s'", affixRank, type( UI.autogenAffixColors ) )
		return color
	end

	color = UI.autogenAffixColors[ affixLevel + 1 ]

	return color

end


-- affixLevel c 0
function UI:GetAutogenAffixRankForLevel( affixId, affixLevel )

	local affixRank = -1

	if type( affixId ) ~= "number" then
		sys.log( "UI:GetAutogenAffixRankForLevel()[ERROR]: invalid type of the 1-st param ('affixId'); 'number' expected, got '%s'", type( affixId ) )
		return affixRank
	end

	if type( affixLevel ) ~= "number" then
		sys.log( "UI:GetAutogenAffixRankForLevel()[ERROR]: invalid type of the 2-nd param ('affixLevel'); 'number' expected, got '%s'", type( affixLevel ) )
		return affixRank
	end

	if affixLevel == -1 then
		sys.log( "UI:GetAutogenAffixRankForLevel()[ERROR]: invalid level %d", affixLevel )
		return affixRank
	end

	local affixDef = UI:GetAutogenAffixDef( affixId )
	if not affixDef then
		sys.log( "UI:GetAutogenAffixRankForLevel()[ERROR]: cannot find def for affix %d", affixId )
		return affixRank
	end

	if type( affixDef.levels ) ~= "table" then
		sys.log( "UI:GetAutogenAffixRankForLevel()[ERROR]: invalid type of 'levels' in def for affix %d", affixId )
		return affixRank
	end

	local levelDef = affixDef.levels[ affixLevel + 1 ]	-- affixLevel c 0

	if type( levelDef ) ~= "table" then
		sys.log( "UI:GetAutogenAffixRankForLevel()[ERROR]: invalid type of levels[%d] in def for affix %d; 'table' expected, got '%s'", affixLevel + 1, affixId, type( levelDef ) )
		return affixRank
	end

	if type( levelDef.rank ) ~= "number" then
		sys.log( "UI:GetAutogenAffixRankForLevel()[ERROR]: invalid type of levels[%d].rank in def for affix %d; 'number' expected, got '%s'", affixLevel + 1, affixId, type( levelDef.rank ) )
		return affixRank
	end

	affixRank = levelDef.rank

	return affixRank

end


