--
function UI:UpdateServerData_OnZonesLuaActiveEventsUpdate( result, requestId, param1, param2 )

	if result ~= _G.MasterServer.VariableSyncResult.NEED_UPDATE then
		return
	end

	UI:UpdateZoneEvents()

end


--
function UI:UpdateZoneEvents()

	self.serverData.zoneEvents = _G.MasterServer_ZonesLuaActiveEventsGet()

	if type( self.serverData.zoneEvents ) ~= "table" then
		sys.log( "UI:UpdateZoneEvents()[ERROR]: invalid type of return value from MasterServer_ZonesLuaActiveEventsGet(); 'table' expected, got '%s'", type( self.serverData.zoneEvents ) )
		self.serverData.zoneEvents = {}
	end

	-- если параметр ивента - вермя, то оно передается в виде оставшегося времени в секудах,
	-- вместо этого находим и запоминаем время окончания для удобства апдейта
	for zoneId, events in pairs( self.serverData.zoneEvents ) do

		for eventId, eventVal in pairs( events ) do

			-- если eventVal <= DISABLE_EVENT, то это технический ивент, не для ui
			if eventVal > ai.ScriptsServer.DISABLE_EVENT then

				local visualMap = UI:GetZoneEventVisualMap( eventId )
				if visualMap and visualMap.showTimer == true and eventVal > 0 then

					local curTime = _G.MasterServer_GetServerTime() or u64( 0 )
					local endTime = curTime + eventVal * 1000
					self.serverData.zoneEvents[ zoneId ][ eventId ] = endTime

				end

			end

		end

	end

end


--
function UI:GetModulesForUpgrade( shipItem )

	local itemsForUpgrade	= {}
	local totalPrice		= 0
	local bGivingExp		= false

	local allAvailableModulesInfo = {}

	for slotId, iid in pairs( shipItem.equipModules ) do

		if iid ~= UI.INVALID_U64_ID and UI:CanItemUpgradeNow( iid ) then

			local info = {}
			info.iid		= iid
			info.defName	= ""
			info.bGivingExp	= false

			local defName = UI:Iid2DefName( iid )
			info.defName = defName

			local baseDefName = UI:GetItemUpgradeBaseDef( defName )

			local atlasId = UI:GetItemAtlasId( baseDefName )
			if atlasId ~= -1 then

				local atlasLevel = UI:GetItemAtlasLevel( baseDefName )
				local nextItemLevel = UI:GetItemUpgradeLevel( UI:GetItemUpgradeNextDef( defName ) )

				if atlasLevel == -1 or atlasLevel < nextItemLevel then
					info.bGivingExp	= true
				end

				if info.bGivingExp then
					bGivingExp = true
				end

			end

			table.insert( allAvailableModulesInfo, info )

		end

	end

	local function fnSort( info1, info2 )

		-- 1. сначчала те, которые дают экспу при апгрейде
		if info1.bGivingExp ~= info2.bGivingExp then
			return info1.bGivingExp
		end

		-- 2. по iid
		return info1.iid < info2.iid

	end

	table.sort( allAvailableModulesInfo, fnSort )

	local playerCredits = UI:GetPlayerCredits()

	for itemIdx, info in ipairs( allAvailableModulesInfo ) do

		-- #№0100139(0470449)
		-- модули, дающие экспу, и моудли не дающие, апгрейдятся отдельно;
		-- т.е. если есть дающие экспу, то апгрейдим тлько их; чтобы апгрейдить недающие, надо кликнуть еще раз
		if bGivingExp and not info.bGivingExp then
			break
		end

		local curLevel = UI:GetItemUpgradeLevel( info.defName )
		local maxLevel = UI:GetItemUpgradeMaxLevel( info.defName )

		local storedInfo = nil

		for level = curLevel, maxLevel - 1 do

			local defNameOnLevel = UI:GetItemUpgradeDefForLevel( info.defName, level )

			if not UI:CanUpgradeItemThroughCraftOnly( defNameOnLevel ) then

				local price = UI:GetItemUpgradeCreditsPrice( defNameOnLevel )
				if totalPrice + price <= playerCredits then

					if not storedInfo then
						storedInfo =
						{
							iid			= info.iid,
							numLevels	= 0,
						}
						table.insert( itemsForUpgrade, storedInfo )
					end

					storedInfo.numLevels = storedInfo.numLevels + 1

					totalPrice = totalPrice + price

				end

			end

		end

		-- не прерываем цикл, если на данный модуль не хватает денег, смотрим следующий - возможно, на него хватит

	end

	return itemsForUpgrade, totalPrice, bGivingExp

end


-- является ли игрок боссом в "one against all",
-- ВНИМАНИЕ! "тяжелая" функция, не вызывать каждый кадр
function UI:IsLocalPlayerOAABoss()

	local localPlayerIdx = _G.Game_LocalClientNum()
	if localPlayerIdx ~= -1 then
		local playerInfo = _G.GetPlayerInfo( localPlayerIdx )
		if playerInfo.team == 1 then
			return true
		end
	end

	return false

end


-- возвращает босса в геймплее "one against all"
-- есть CL_GetBossPlayerIdx(), но она не надежная - в самом начале когда худу надо апдейтиться, а она возвращает -1
-- ВНИМАНИЕ! "тяжелая" функция, не вызывать каждый кадр
function UI:GetOAABossPlayerIdx()

	local bossPlayerIdx = -1

	local allPlayersInfo = _G.GetAllPlayersInfo()
	for idx, playerInfo in pairs( allPlayersInfo ) do
		if playerInfo.team == 1 then
			bossPlayerIdx = playerInfo.playerId
			break
		end
	end

	return bossPlayerIdx

end


-- Запоминает autogenItem в пул. Генерит на его основе деф (так же хранится в этом пуле) и возвращает имя дефа.
-- Нужно для показа информации об автоген-модулях в дебрифинге, почте, чате (т.е. там, где дефов для этих модулей в cpp нет).
-- Окна и функции, которым самим был не известен изначальный autogenItem, а у них есть только имя дефа,
-- будут использовать этот пул, чтобы получить деф по имени и работать с автогеном как с обычным модулем.
-- Это не совсем полноценный деф, т.к. он не будет содержать ссылки на сгенеренные спеллы.
-- Для того, чтобы получить полноценный деф со спеллами, надо вызывать _G.AddAutogenDef(), но она не работает во время геймплея, поэтому не используется.
-- Пул имеет ограниченный размер. Если он заполнен, то выкидывается самый старый autogenItem.
-- Т.к. не гарантируется, что autogenItem сохранен в данный момент, перед использованием функций, которые будут работать с ним,
-- нужно вызывать эту функцию повторно (ее можно вызывать сколько угодно раз; если деф сохранен, то она просто вернет существующий).
-- Следует иметь в виду, что единожды запомненный autogenItem и сгенеренный деф не меняются (пока не будут выкинуты из пула).
-- Т.е. уровень апгрейда модуля не будет обновлен. Поэтому, если надо показывать информацию, зависимую от уровня апгрейда,
-- это надо учитывать на вызывающей стороне - генерить новый деф для этого уровня апгрейда, а отсюда брать только rollData.
-- ( UI:GetDef() умеет генерить новый деф при необходимости, если задан параметр autogenUpgradeLevel.)
function UI:AddTempAutogenDef( autogenItem )

	if type( autogenItem ) ~= "table" then
		sys.log( "UI:AddTempAutogenDef()[ERROR]: invalid type of the 1-st parameter ('autogenItem'); \"table\" expected, got \"%s\"", type( autogenItem ) )
		return ""
	end

	-- в autogenItem не всегда записано имя дефа. Но оно всегда формируется по одним правилам.
	local defName = autogenItem.defName
	if defName == nil or defName == "" then
		defName = string.format( "Module_Autogen_%s", _G.U64ToStr( autogenItem.iid ) )
	end

	-- уже есть?
	if UI:GetDef( defName, false ) then
		return defName
	end

	-- генерим деф
	local def = _G.GenerateAutogenDef( autogenItem.rollData, autogenItem.upgradeLevel )
	if not def then
		sys.log( "UI:AddTempAutogenDef()[ERROR]: cannot generate autogen def" )
		return ""
	end

	-- если буфер переполнен то выкидываем самый первый (самый старый) деф
	if #UI.tempAutogenItems >= UI.MAX_TEMP_AUTOGEN_ITEMS then
		table.remove( UI.tempAutogenItems, 1 )
	end

	autogenItem.defName = defName
	autogenItem.def = def	-- запоминаем деф прямо сюда

	table.insert( UI.tempAutogenItems, autogenItem )

	return defName

end


--
function UI:GetTempAutogenDef( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetTempAutogenDef()[defName]: invalid type of the 1-st parameter ('defName'); \"string\" expected, got \"%s\"", type( defName ) )
		return nil
	end

	for idx, autogenItem in pairs( UI.tempAutogenItems ) do
		if autogenItem.defName == defName then
			return autogenItem.def
		end
	end

	return nil

end


--
function UI:GetTempAutogenItem( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetTempAutogenItem()[defName]: invalid type of the 1-st parameter ('defName'); \"string\" expected, got \"%s\"", type( defName ) )
		return nil
	end

	for idx, autogenItem in pairs( UI.tempAutogenItems ) do
		if autogenItem.defName == defName then
			return autogenItem
		end
	end

	return nil

end


--
function UI:GetAutogenItem( defName )

	if type( defName ) ~= "string" then
		sys.log( "UI:GetAutogenItem()[defName]: invalid type of the 1-st parameter ('defName'); \"string\" expected, got \"%s\"", type( defName ) )
		return nil
	end

	local autogenItem = _G.GetAutogenItem( defName, false--[[не ругаться если не найдено]] )

	if not autogenItem then
		autogenItem = UI:GetTempAutogenItem( defName )
	end

	return autogenItem

end


--
function UI:GetShipAdditionalDesc( defName )

	local strAdditionalDesc = ""

	if type( defName ) ~= "string" then
		sys.log( "UI:GetShipAdditionalDesc()[ERROR]: invalid type of the 1-st parameter (\"defName\"); \"string\" expected, got \"%s\"", type( defName ) )
		return strAdditionalDesc
	end

	local def = UI:GetDef( defName )
	if not def then
		sys.log( "UI:GetShipAdditionalDesc()[ERROR]: cannot find \"_G.Def[%s]\"", defName )
		return strAdditionalDesc
	end

	if def.additional_desc ~= nil then
		if type( def.additional_desc ) == "string" then
			strAdditionalDesc = UI:GetStringByName( def.additional_desc, true )
		else
			sys.log( "UI:GetShipAdditionalDesc()[ERROR]: invalid type of '_G.Def[%s].additional_desc'; 'string' or 'nil' expected, got '%s'", type( def.additional_desc ) )
		end
	end

	return strAdditionalDesc

end


-- tradeMoney это u64
function UI:GetTax( tradeMoney )

	local tax = 0
	
	if type( _G.TradingTax ) ~= "table" then
		sys.log( "UI:GetTax()[ERROR]: invalid type of '_G.TradingTax'; 'table' expected, got '%s'", type( _G.TradingTax ) )
		return tax
	end
	
	local success = true
	
	for idx, taxInfo in ipairs( _G.TradingTax ) do
	
		if type( taxInfo ) == "table" then
		
			if type( taxInfo.tax ) == "number" and type( taxInfo.moneyMax ) == "number" then
			
				if tradeMoney <= u64( taxInfo.moneyMax ) or taxInfo.moneyMax == 0 then	-- moneyMax=0 означает до бесконечности
					tax = taxInfo.tax
					break
				end
			
			else
				sys.log( "UI:GetTax()[ERROR]: invalid format of '_G.TradingTax'" )
				success = false
				break
			end
			
		else
			sys.log( "UI:GetTax()[ERROR]: invalid format of '_G.TradingTax'" )
			success = false
			break
		end
	
	end
	
	if not success then
		tax = 0
	end
	
	return tax

end


-- tradeMoney это u64
-- правила расчёта SC-112234/Progressivnaya-shkala-nalogooblazheniya
function UI:GetTaxForPrice( tradeMoney, price )
	
	local priceCount = 0
	local tax = 0
	
	if type( _G.TradingTax ) ~= "table" then
		sys.log( "UI:GetTaxForPrice()[ERROR]: invalid type of '_G.TradingTax'; 'table' expected, got '%s'", type( _G.TradingTax ) )
		return tax
	end
	
	local success = true
	
	for idx, taxInfo in ipairs( _G.TradingTax ) do
	
		if type( taxInfo ) == "table" then
		
			if type( taxInfo.tax ) == "number" and type( taxInfo.moneyMax ) == "number" then
				
				if taxInfo.moneyMax == 0 or u64(taxInfo.moneyMax) > tradeMoney then
				
					local taxStep = price - priceCount
				
					if taxStep <= 0 then
						break
					end
				
					if taxInfo.moneyMax > 0 then
						local u64MoneyMax = u64(taxInfo.moneyMax) - tradeMoney
						
						if u64(price) > u64MoneyMax then
							u64TaxStep = u64MoneyMax - priceCount
							taxStep = u64TaxStep.l
						end
					end
					
					tax = tax + taxStep * taxInfo.tax
					priceCount = priceCount + taxStep
					
				end
			
			else
				sys.log( "UI:GetTaxForPrice()[ERROR]: invalid format of '_G.TradingTax'" )
				success = false
				break
			end
			
		else
			sys.log( "UI:GetTaxForPrice()[ERROR]: invalid format of '_G.TradingTax'" )
			success = false
			break
		end
	
	end
	
	if not success then
		tax = 0
	end
	
	return math.ceil(tax)

end


--
function UI:GetQuestZones( questId )

	local zones = {}

	if type( questId ) ~= "number" then
		sys.log( "UI:GetQuestZones()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( questId ) )
		return zones
	end

	local stage = UI:GetQuestStage( questId )

	local stageInfo = UI:GetQuestStageInfo( questId, stage )
	if not stageInfo then
		sys.log( "UI:GetQuestZones()[ERROR]: cannot find stage info for quest %d stage %d", questId, stage )
		return zones
	end

	if stageInfo.restrictions == nil then
		return zones
	end

	if type( stageInfo.restrictions ) ~= "table" then
		sys.log( "UI:GetQuestZones()[ERROR]: invalid type of the \"_G.Quests[%d].stages[%d].restrictions\"; \"table\" or \"nil\" expected, got \"%s\"", questId, stage, type( stageInfo.restrictions ) )
		return zones
	end

	for restrictionIdx, restriction in pairs( stageInfo.restrictions ) do

		if restriction.param == ai.GameEventParam.ZONE_ID then

			if type( restriction.num_value ) == "number" then
				zones = { restriction.num_value }
			elseif type( restriction.num_value ) == "table" then
				zones = restriction.num_value
			else
				sys.log( "UI:GetQuestZones()[ERROR]: invalid type of \"_G.Quests[%d].restrictions[%d].num_value\"; \"number\" or \"table\" expected, got \"%s\"", questId, restrictionIdx, type( restriction.num_value ) )
			end

			break

		end

	end

	return zones

end


--
function UI:IsQuestLockedByZone( questId )

	local bLocked = false

	local zones = UI:GetQuestZones( questId )

	if next( zones ) then
		local bIsAnyZoneAccessible = false
		zonesWithDisableQuests = _G.MasterServer_ZonesWithDisabledQuestsGet()

		for _, zoneId in ipairs( zones ) do
			if not ( zonesWithDisableQuests[ zoneId ] ) then
				bIsAnyZoneAccessible = true
				break
			end
		end

		if not bIsAnyZoneAccessible then
			bLocked = true
		end
	end

	return bLocked

end


-- как такового имени у сквада нет, возвращается превращенный в строку номер 1,2,... (для каждой команды нумерация своя);
-- работает только во время геймплея

function UI:MakePlayerSquadName( playerId )

	local squadName = ""

	local squadIdx = UI:GetPlayerSquadConsequentIdx( playerId )
	if squadIdx ~= -1 then
		squadName = tostring( squadIdx )
	end

	return squadName

end


-- возвращается порядковый номер типа 1,2,... (для каждой команды нумерация своя);
-- присвоение такого номера скваду можно считать произвольным; его использовать нельзя нигде, кроме создания фэйковогоо якобы имени;
-- работает только во время геймплея

function UI:GetPlayerSquadConsequentIdx( playerId )

	local playerSquadIdx = -1

	if type( playerId ) ~= "number" then
		sys.log( "UI:GetPlayerSquadConsequentIdx()[ERROR]: invalid type of the 1-st parameter (\"playerId\"); \"number\" expected, got \"%s\"", type( playerId ) )
		return playerSquadIdx
	end

	local playerSqid = _G.CL_GetPlayerSquad( playerId )
	if playerSqid == UI.INVALID_U64_ID then
		return playerSquadIdx
	end

	local playerTeam = _G.CL_GetPlayerTeam( playerId )
	local playersInfo = _G.GetAllPlayersInfo()

	local teamSqids = {}

	for playerInfoIdx, playerInfo in pairs( playersInfo ) do

		if playerInfo.team == playerTeam and playerInfo.sqid ~= nil and playerInfo.sqid ~= UI.INVALID_U64_ID then

			local bFound = false
			for squadIdx, sqid in pairs( teamSqids ) do
				if sqid == playerInfo.sqid then
					bFound = true
					break
				end
			end

			if not bFound then
				table.insert( teamSqids, playerInfo.sqid )
			end

		end

	end

	table.sort( teamSqids )

	for squadIdx, sqid in pairs( teamSqids ) do
		if sqid == playerSqid then
			playerSquadIdx = squadIdx
			break
		end
	end

	return playerSquadIdx

end


--
function UI:Adventure2Str( adventureAtid, command, stage )

	local name = ""

	if type( adventureAtid ) ~= "number" then
		sys.log( "UI:Adventure2Str()[ERROR]: invalid type (\"adventureAtid\"); \"number\" expected, got \"%s\"", type( adventureAtid ) )
		return name
	end

	if type( command ) ~= "string" then
		sys.log( "UI:Adventure2Str()[ERROR]: invalid type (\"command\"); \"string\" expected, got \"%s\"", type( command ) )
		return name
	end

	local adventureName = UI:Val2Key( ai.Adventures, adventureAtid )
	if adventureName == "" then
		sys.log( "UI:Adventure2Str()[ERROR]: invalid adventureAtid: %d", adventureAtid )
		return name
	end

	if command == "" then
		sys.log( "UI:Adventure2Str()[ERROR]: invalid command: %s", command )
		return name
	end

	if stage ~= nil and type( stage ) ~= "number" then
		sys.log( "UI:Adventure2Str()[ERROR]: invalid type (\"stage\"); \"string\" expected, got \"%s\"", type( stage ) )
		return name
	end

	if UI.showDefNames then
		return adventureName
	end

	local strId = ""
	if stage == nil then
		strId = string.format( "adventure_%s_%s", adventureName, command )
	else
		strId = string.format( "adventure_%s_stage%d_%s", adventureName, stage, command )
	end

	name = UI:GetStringByName( strId, false ) or ""

	return name

end


