function UI:GetAdventureStageInfo( adventureAtid, stage )

	local stageInfo = nil

	if type( adventureAtid ) ~= "number" then
		sys.log( "UI:GetAdventureStageInfo()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( adventureAtid ) )
		return stageInfo
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetAdventureStageInfo()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return stageInfo
	end

	local adventureInfo = UI:GetAdventureInfo( adventureAtid )
	if not adventureInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestStageInfo()[ERROR]:cannot find quest info for quest %d", questId )
		return stageInfo
	end

	if type( adventureInfo.stages ) ~= "table" then
		sys.log( "UI:GetAdventureStageInfo()[ERROR]: invalid type of _G.Adventures[%d].stages; \"table\" expected, got \"%s\"", adventureAtid, type( adventureInfo.stages ) )
		return stageInfo
	end

	stageInfo = adventureInfo.stages[ stage ]

	if type( stageInfo ) ~= "table" then
		sys.log( "UI:GetAdventureStageInfo()[ERROR]: invalid type of _G.Adventures[%d].stages[%d]; \"table\" expected, got \"%s\"", adventureAtid, stage, type( stageInfo ) )
		stageInfo = nil
	end

	return stageInfo

end


--
function UI:GetAdventureTaskMaxVal( aiid, stage )

	local val = nil

	if type( aiid ) ~= "userdata" then
		sys.log( "UI:GetAdventureTaskMaxVal()[ERROR]: invalid type of the 1-st parameter (\"aiid\"); \"number\" expected, got \"%s\"", type( aiid ) )
		return val
	end

	local activeAdventure = nil
	if UI.serverData.activeAdventuresByAiid[ aiid.h ] ~= nil then
		activeAdventure = UI.serverData.activeAdventuresByAiid[ aiid.h ][ aiid.l ]
	end

	if activeAdventure == nil then
		sys.log( "UI:GetAdventureTaskMaxVal()[ERROR]: cannot find active adventure by aiid( %d, %d )", aiid.h, aiid.l )
		return val
	end

	local atid = UI:GetAdventureAtid( aiid )

	if stage ~= nil then
		if type( stage ) ~= "number" then
			sys.log( "UI:GetAdventureTaskMaxVal()[ERROR]: invalid type of the 2-th parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
			return val
		end
	else
		stage = -1
	end

	if stage == -1 then
		stage = UI:GetAdventureStage( aiid )
	end

	local stageInfo = UI:GetAdventureStageInfo( atid, stage )
	if not stageInfo then
		sys.log( "UI:GetAdventureTaskMaxVal()[ERROR]: cannot find stage info for adventure %d stage %d", atid, stage )
		return val
	end

	if stageInfo.required_progress == nil then
		sys.log( "UI:GetAdventureTaskMaxVal()[ERROR]: cannot find \"_G.Adventures[%d].stages[%d].required_progress\"", atid, stage )
		return val
	end

	if type( stageInfo.required_progress ) == "number" then

		val = stageInfo.required_progress

	elseif type( stageInfo.required_progress ) == "table" then

		local placeholderIdx = UI:GetAdventureParamPlaceholderIdx( stageInfo.required_progress )

		if placeholderIdx ~= 0 and activeAdventure.params then
			val = activeAdventure.params[ placeholderIdx ]
		end

	else
		sys.log( "UI:GetAdventureTaskMaxVal()[ERROR]: invalid type of the \"_G.Adventures[%d].stages[%d].required_progress\"; \"number\" expected, gpt \"%s\"", adventureAtid, stage, type( stageInfo.required_progress ) )
		return val
	end

	return val

end


