--
function UI:GetAdventureRewards( atid, stageFinal, completionData )

	local rewards = {}

	if type( atid ) ~= "number" then
		sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of the 1-st parameter (\"atid\"); \"number\" expected, got \"%s\"", type( atid ) )
		return rewards
	end

	if completionData ~= nil then
		if type( completionData ) ~= "table" then
			sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of the 3-rd parameter (\"completionData\"); \"table\" or \"nil\" expected, got \"%s\"", type( completionData ) )
			completionData = nil
		end
	end

	local rewardInfo = UI:GetAdventureRewardInfo( atid, stageFinal )
	if not rewardInfo then
		return rewards
	end

	-- пока что нет модификаций награды

	if completionData then
		-- пока что нет инфы
	else
		-- пока что нет инфы
	end


	-- 1. золото

	if rewardInfo.gold ~= nil then

		if type( rewardInfo.gold ) == "number" then

			local goldReward =
			{
				rewardType	= UI.questRewardTypes.GOLD,
				val			= rewardInfo.gold,
			}
			table.insert( rewards, goldReward )

		else
			sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of _G.Adventure[%d].rewards[%d].gold; \"number\" expected, got \"%s\"", atid, stageFInal, type( rewardInfo.gold ) )
		end

	end


	-- 2. кредиты

	if rewardInfo.credits ~= nil then

		if type( rewardInfo.credits ) == "number" then

			local creditsReward =
			{
				rewardType		= UI.questRewardTypes.CREDITS,
				val				= rewardInfo.credits,
			}
			table.insert( rewards, creditsReward )

		else
			sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of _G.Adventure[%d].rewards[%d].credits; \"number\" expected, got \"%s\"", atid, stageFinal, type( rewardInfo.credits ) )
		end

	end


	-- 3. ивентовые кредиты

	if rewardInfo.eventCredits ~= nil then

		if type( rewardInfo.eventCredits ) == "number" then

			local eventCreditsReward =
			{
				rewardType	= UI.questRewardTypes.EVENT_CREDITS,
				val			= rewardInfo.eventCredits,
			}
			table.insert( rewards, eventCreditsReward )

		else
			sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of _G.Adventure[%d].rewards[%d].eventCredits; \"number\" or \"nil\" expected, got \"%s\"", atid, stageFinal, type( rewardInfo.eventCredits ) )
		end

	end


	-- 4. предметы; среди предметов - сортировка по имени дефинишена

	if rewardInfo.items ~= nil then

		if type( rewardInfo.items ) == "table" then

			local itemsRewards = {}

			for itemIdx, itemInfo in ipairs( rewardInfo.items ) do

				if type( itemInfo ) == "table" then

					local itemDefName = itemInfo[ 1 ]
					if type( itemDefName ) == "string" then

						local countBase = itemInfo[ 2 ]
						if countBase == nil then
							countBase = 1
						else
							if type( countBase ) ~= "number" then
								sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of _G.Adventure[%d].rewards[%d].items[%d][2]; \"number\" or \"nil\" expected, got \"%s\"", atid, stageFinal, itemIdx, type( countBase ) )
								countBase = 1
							end
						end

						local countModified = countBase

						if UI:IsDefResource( itemDefName ) or UI:IsDefBlueprint( itemDefName ) then
							countModified = UI:Round( countBase )
						end

						local itemReward =
						{
							rewardType		= UI.questRewardTypes.ITEM,
							defName			= itemDefName,
							count			= countModified,
						}
						table.insert( itemsRewards, itemReward )


					else
						sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of _G.Adventure[%d].rewards[%d].items[%d][1]; \"string\" expected, got \"%s\"", atid, stageFinal, itemIdx, type( itemDefName ) )
					end

				else
					sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of _G.Adventure[%d].rewards[%d].items[%d]; \"table\" expected, got \"%s\"", atid, stageFinal, itemIdx, type( itemInfo ) )
				end

			end

			for itemIdx, itemReward in ipairs( itemsRewards ) do
				table.insert( rewards, itemReward )
			end

		else
			sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of _G.Adventure[%d].rewards[%d].items; \"table\" expected, got \"%s\"", atid, stageFinal, type( rewardInfo.items ) )
		end

	end


	-- 4. токены (иридиум для игрока)
	if rewardInfo.tokens ~= nil then

		if type( rewardInfo.tokens ) == "number" then

			local tokensReward =
			{
				rewardType	= UI.questRewardTypes.TOKENS,
				val			= rewardInfo.tokens,
			}
			table.insert( rewards, tokensReward )

		else
			sys.log( "UI:GetAdventureRewards()[ERROR]: invalid type of _G.Adventure[%d].rewards[%d].tokens; \"number\" expected, got \"%s\"", atid, stageFinal, type( rewardInfo.tokens ) )
		end

	end


	return rewards

end


--
function UI:GetAdventureRewardInfo( atid, stageFinal )

	local rewardInfo = nil

	if type( atid ) ~= "number" then
		sys.log( "UI:GetAdventureRewardInfo()[ERROR]: invalid type of the 1-st parameter (\"questId\"); \"number\" expected, got \"%s\"", type( atid ) )
		return rewardInfo
	end

	if type( stageFinal ) ~= "number" then
		sys.log( "UI:GetAdventureRewardInfo()[ERROR]: invalid type of the 2-nd parameter (\"stageFinal\"); \"number\" expected, got \"%s\"", type( stageFinal ) )
		return rewardInfo
	end

	local adventureInfo = UI:GetAdventureInfo( atid )
	if not adventureInfo then
		-- #0100434 - сейчас это считается "нормальным", что нет таблицы для квеста
		-- sys.log( "UI:GetQuestStageInfo()[ERROR]:cannot find quest info for quest %d", questId )
		return rewardInfo
	end

	if type( adventureInfo.rewards ) ~= "table" then
		sys.log( "UI:GetAdventureRewardInfo()[ERROR]: invalid type of _G.Adventures[%d].stages; \"table\" expected, got \"%s\"", atid, type( adventureInfo.rewards ) )
		return rewardInfo
	end

	rewardInfo = adventureInfo.rewards[ stageFinal ]

	if type( rewardInfo ) ~= "table" then
		sys.log( "UI:GetAdventureRewardInfo()[ERROR]: invalid type of _G.Adventures[%d].stages[%d]; \"table\" expected, got \"%s\"", atid, stageFinal, type( rewardInfo ) )
		rewardInfo = nil
	end

	return rewardInfo

end


--
function UI:GetAdventureZonesForStageT( aiid )

	local zones = {}

	if type( aiid ) ~= "userdata" then
		sys.log( "UI:GetAdventureZonesForStageT()[ERROR]: invalid type of the 1-st parameter (\"aiid\"); \"number\" expected, got \"%s\"", type( aiid ) )
		return zones
	end

	local activeAdventure = nil
	if UI.serverData.activeAdventuresByAiid[ aiid.h ] ~= nil then
		activeAdventure = UI.serverData.activeAdventuresByAiid[ aiid.h ][ aiid.l ]
	end

	if activeAdventure == nil then
		sys.log( "UI:GetAdventureZonesForStageT()[ERROR]: cannot find active adventure by aiid( %d, %d )", aiid.h, aiid.l )
		return zones
	end

	local atid = UI:GetAdventureAtid( aiid )
	local stage = UI:GetAdventureStage( aiid )

	if type( atid ) ~= "number" then
		sys.log( "UI:GetAdventureZonesForStageT()[ERROR]: invalid type parameter (\"atid\"); \"number\" expected, got \"%s\"", type( atid ) )
		return zones
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetAdventureZonesForStageT()[ERROR]: invalid type parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return zones
	end

	local stageInfo = UI:GetAdventureStageInfo( atid, stage )
	if not stageInfo then
		sys.log( "UI:GetAdventureZonesForStageT()[ERROR]: cannot find stage info for Adventure[%d].stages[%d]", atid, stage )
		return zones
	end

	if stageInfo.marked_zones == nil then
		return zones
	end

	if type( stageInfo.marked_zones ) ~= "table" then
		sys.log( "UI:GetAdventureZonesForStageT()[ERROR]: invalid type of _G.Adventures[%d].stages[%d].marked_zones; \"table\" expected, got \"%s\"", atid, stage, type( stageInfo.marked_zones ) )
		return zones
	end

	for zoneIdx, zoneInfo in pairs( stageInfo.marked_zones ) do

		if type( zoneInfo ) == "number" then

			if zoneInfo ~= 0 then
				table.insert( zones, zoneInfo )
			end
	
		elseif type( zoneInfo ) == "table" then
	
			-- Если таблица, то Placeholder
			for placeholderIdx, placeholderInfo in pairs( ai.Placeholders ) do
				if zoneInfo == placeholderInfo then
					local zoneId = activeAdventure.params[ placeholderIdx ]
					if zoneId ~= 0 then
						table.insert( zones, zoneId )
					end
				end
			end
	
		else
			sys.log( "UI:GetAdventureZonesForStageT()[ERROR]: invalid type of \"marked_zone_id\" for Adventure[%d].stages[%d]; \"number\", \"table\" or \"nil\" expected, got \"%s\"", atid, stage, type( stageInfo.marked_zone_id ) )
		end

	end

	return zones

end


--
function UI:GetAdventureParamPlaceholderIdx( param )

	for idx, placeholderInfo in pairs( ai.Placeholders ) do
		if param == placeholderInfo then
			return idx
		end
	end

	return 0

end


--
function UI:GetAdventureMarkDefsForStage( aiid )

	local markDefs = {}

	if type( aiid ) ~= "userdata" then
		sys.log( "UI:GetAdventureMarkDefsForStage()[ERROR]: invalid type of the 1-st parameter (\"aiid\"); \"number\" expected, got \"%s\"", type( aiid ) )
		return markDefs
	end

	local activeAdventure = nil
	if UI.serverData.activeAdventuresByAiid[ aiid.h ] ~= nil then
		activeAdventure = UI.serverData.activeAdventuresByAiid[ aiid.h ][ aiid.l ]
	end

	if activeAdventure == nil then
		sys.log( "UI:GetAdventureMarkDefsForStage()[ERROR]: cannot find active adventure by aiid( %d, %d )", aiid.h, aiid.l )
		return markDefs
	end

	local atid = UI:GetAdventureAtid( aiid )
	local stage = UI:GetAdventureStage( aiid )

	local stageInfo = UI:GetAdventureStageInfo( atid, stage )
	if not stageInfo then
		sys.log( "UI:GetAdventureMarkDefsForStage()[ERROR]: cannot find stage info for Adventure[%d].stages[%d]", atid, stage )
		return markDefs
	end

	if stageInfo.hud_marker_defs == nil then
		return markDefs
	end

	if type( stageInfo.hud_marker_defs ) ~= "table" then
		sys.log( "UI:GetAdventureMarkDefsForStage()[ERROR]: invalid type of the Adventure[%d].stages[%d].hud_marker_defs; \"table\" or \"nil\" expected, got \"%s\"", atid, stage, type( stageInfo.hud_marker_defs ) )
		return markDefs
	end

	for idx, defName in pairs( stageInfo.hud_marker_defs ) do
		if type( defName ) == "string" then
			markDefs[ defName ] = true
		else
			sys.log( "UI:GetAdventureMarkDefsForStage()[ERROR]: invalid type of the Adventure[%d].stages[%d].hud_marker_defs[%d]; \"string\" or \"nil\" expected, got \"%s\"", aiid, stage, idx, type( defName ) )
		end
	end

	return markDefs

end


--
function UI:IsAdventureTaken( aiid )

	if type( aiid ) ~= "userdata" then
		sys.log( "UI:IsAdventureTaken()[ERROR]: invalid type of the 1-st parameter (\"aiid\"); \"userdata\" expected, got \"%s\"", type( aiid ) )
		return false
	end

	if UI.serverData.activeAdventuresByAiid[ aiid.h ] == nil then
		return false
	end

	return UI.serverData.activeAdventuresByAiid[ aiid.h ][ aiid.l ] ~= nil

end


--
function UI:GetAdventureTaskDesc2( aiid, baseColor, selColor, stage, bAllowLinks )

	local desc = ""

	if type( aiid ) ~= "userdata" then
		sys.log( "UI:GetAdventureTaskDesc2()[ERROR]: invalid type of the 1-st parameter (\"aiid\"); \"userdata\" expected, got \"%s\"", type( aiid ) )
		return desc
	end

	local activeAdventure = nil
	if UI.serverData.activeAdventuresByAiid[ aiid.h ] ~= nil then
		activeAdventure = UI.serverData.activeAdventuresByAiid[ aiid.h ][ aiid.l ]
	end

	if activeAdventure == nil then
		sys.log( "UI:GetAdventureTaskDesc2()[ERROR]: cannot find active adventure by aiid( %d, %d )", aiid.h, aiid.l )
		return desc
	end

	local atid = UI:GetAdventureAtid( aiid )

	if stage ~= nil then
    	if type( stage ) ~= "number" then
    		sys.log( "UI:GetAdventureTaskDesc2()[ERROR]: invalid type of the 4-th parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
    		return desc
    	end
	else
		stage = -1
	end

	if stage == -1 then
		stage = UI:GetAdventureStage( aiid )
	end

	local adventureName = UI:Val2Key( ai.Adventures, atid )
	if adventureName == "" then
		sys.log( "UI:GetAdventureTaskDesc2()[ERROR]: invalid atid name: %d", atid )
		return desc
	end

	if type( baseColor ) ~= "number" then

		if baseColor ~= nil then
			sys.log( "UI:GetAdventureTaskDesc2()[ERROR]: invalid type of the 2-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
		end

		baseColor = UI.TEXT_BASE_COLOR

	end

	if type( selColor ) ~= "number" then

		if selColor ~= nil then
			sys.log( "UI:GetAdventureTaskDesc2()[ERROR]: invalid type of the 3-rd parameter (\"selColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( selColor ) )
		end

		selColor = UI.TEXT_SEL_COLOR

	end

	local strBaseColor	= UI:Color2Str( baseColor )
	local strSelColor	= UI:Color2Str( selColor )

	local strId = string.format( "adventure_%s_stage%d_task_short", adventureName, stage )
	desc = UI:GetStringByName( strId )

	local curVal = 0
	local maxVal = UI:GetAdventureTaskMaxVal( aiid, stage )
	if stage ~= UI:GetAdventureStage( aiid ) then
		curVal = maxVal
	else
		curVal = UI:GetAdventureTaskCurVal( aiid )
	end

	local strCurVal = string.format( "%s%s%s", strSelColor, UI:Num2StrSeparatedBy3( curVal ), strBaseColor )
	local strMaxVal = string.format( "%s%s%s", strSelColor, UI:Num2StrSeparatedBy3( maxVal ), strBaseColor )

	local tSubst =
	{
		current	= strCurVal,
		target	= strMaxVal,
	}

	desc = string.gsub( desc, "%$(.-)%$", tSubst )
	--desc = UI:FillQuestDescWithParams( questId, stage, desc, bAllowLinks, baseColor )
	desc = string.format( "%s%s", strBaseColor, desc )

	return desc

end


--
-- Этот метод необходим для HudQuestTrackerWnd,
-- так как мы не храним информацию о завершённых адвенчерах ( UI.serverData.completeAdventures ),
-- а информацию о прогрессе необходимо показать
function UI:GetAdventureTaskDesc2ByAtid( atid, params, baseColor, selColor, stage, bAllowLinks )

	local desc = ""

	if type( atid ) ~= "number" then
		sys.log( "UI:GetAdventureTaskDesc2ByAtid()[ERROR]: invalid type of the 1-st parameter (\"atid\"); \"number\" expected, got \"%s\"", type( atid ) )
		return desc
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetAdventureTaskDesc2ByAtid()[ERROR]: invalid type of the 5-th parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return val
	end

	if type( params ) ~= "table" then
		sys.log( "UI:GetAdventureTaskDesc2ByAtid()[ERROR]: invalid type of the 2-th parameter (\"params\"); \"table\" expected, got \"%s\"", type( params ) )
		return val
	end

	local adventureName = UI:Val2Key( ai.Adventures, atid )
	if adventureName == "" then
		sys.log( "UI:GetAdventureTaskDesc2ByAtid()[ERROR]: invalid atid name: %d", atid )
		return desc
	end

	if type( baseColor ) ~= "number" then

		if baseColor ~= nil then
			sys.log( "UI:GetAdventureTaskDesc2ByAtid()[ERROR]: invalid type of the 3-nd parameter (\"baseColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( baseColor ) )
		end

		baseColor = UI.TEXT_BASE_COLOR

	end

	if type( selColor ) ~= "number" then

		if selColor ~= nil then
			sys.log( "UI:GetAdventureTaskDesc2ByAtid()[ERROR]: invalid type of the 4-rd parameter (\"selColor\"); \"number\" or \"nil\" expected, got \"%s\"", type( selColor ) )
		end

		selColor = UI.TEXT_SEL_COLOR

	end

	local strBaseColor	= UI:Color2Str( baseColor )
	local strSelColor	= UI:Color2Str( selColor )

	local strId = string.format( "adventure_%s_stage%d_task_short", adventureName, stage )
	desc = UI:GetStringByName( strId )

	local maxVal = UI:GetAdventureTaskMaxValByAtid( atid, stage, params )
	local curVal = maxVal

	local strCurVal = string.format( "%s%s%s", strSelColor, UI:Num2StrSeparatedBy3( curVal ), strBaseColor )
	local strMaxVal = string.format( "%s%s%s", strSelColor, UI:Num2StrSeparatedBy3( maxVal ), strBaseColor )

	local tSubst =
	{
		current	= strCurVal,
		target	= strMaxVal,
	}

	desc = string.gsub( desc, "%$(.-)%$", tSubst )
	--desc = UI:FillQuestDescWithParams( questId, stage, desc, bAllowLinks, baseColor )
	desc = string.format( "%s%s", strBaseColor, desc )

	return desc

end


--
function UI:IsAdventureFinalOnCancel( atid, stageFinal )

	if type( atid ) ~= "number" then
		sys.log( "UI:IsAdventureFinalOnCancel()[ERROR]: invalid type of the 1-st parameter (\"atid\"); \"number\" expected, got \"%s\"", type( atid ) )
		return false
	end

	if type( stageFinal ) ~= "number" then
		sys.log( "UI:IsAdventureFinalOnCancel()[ERROR]: invalid type of the 2-th parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stageFinal ) )
		return false
	end

	local adventureInfo = UI:GetAdventureInfo( atid )
	if not adventureInfo then
		return false
	end

	if type( adventureInfo.final_on_cancel ) ~= "number" then
		-- значение поумолчанию ai.AdventureStage.LOSS
		return stageFinal == ai.AdventureStage.LOSS
	end

	return stageFinal == adventureInfo.final_on_cancel

end


--
function UI:IsAdventureStageFinal( stageFinal )

	if type( stageFinal ) ~= "number" then
		sys.log( "UI:IsAdventureFinalOnCancel()[ERROR]: invalid type of the 1-th parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stageFinal ) )
		return false
	end

	return stageFinal >= ai.AdventureStage.WIN and stageFinal <= ai.AdventureStage.ROUTE_LAST

end


--
function UI:IsAdventureRewardFinal( atid, stageFinal )

	return UI:GetAdventureRewardInfo( atid, stageFinal ) ~= nil

end


--
function UI:CanAdventureCanceled( atid )

	if type( atid ) ~= "number" then
		sys.log( "UI:CanAdventureCanceled()[ERROR]: invalid type of the 1-st parameter (\"atid\"); \"number\" expected, got \"%s\"", type( atid ) )
		return true
	end

	local adventureInfo = UI:GetAdventureInfo( atid )
	if not adventureInfo then
		return true
	end

	if adventureInfo.no_cancel ~= nil then

		if type( adventureInfo.no_cancel ) == "boolean" then
			return not adventureInfo.no_cancel
		else
			sys.log( "UI:CanAdventureCanceled()[ERROR]: invalid type of _G.Adventure[%d].no_cancel; \"boolean\" or \"nil\" expected, got \"%s\"", atid, type( adventureInfo.no_cancel ) )
			return true
		end

	end

	return true

end


--
function UI:GetAdventureDialogsForEvent( atid, stage, eventIdx )

	local dialogs = {}

	if type( atid ) ~= "number" then
		sys.log( "UI:GetAdventureDialogsForEvent()[ERROR]: invalid type of the 1-st parameter (\"atid\"); \"number\" expected, got \"%s\"", type( atid ) )
		return dialogs
	end

	if type( stage ) ~= "number" then
		sys.log( "UI:GetAdventureDialogsForEvent()[ERROR]: invalid type of the 2-nd parameter (\"stage\"); \"number\" expected, got \"%s\"", type( stage ) )
		return dialogs
	end

	if type( eventIdx ) ~= "number" then
		sys.log( "UI:GetAdventureDialogsForEvent()[ERROR]: invalid type of the 3-rd parameter (\"eventIdx\"); \"number\" expected, got \"%s\"", type( eventIdx ) )
		return dialogs
	end

	local adventureInfo = UI:GetAdventureInfo( atid )
	if not adventureInfo then
		return dialogs
	end

	if type( adventureInfo.stages ) ~= "table" then
		sys.log( "UI:GetAdventureDialogsForEvent()[ERROR]: invalid type of _G.Adventures[%d].stages; \"table\" expected, got \"%s\"", atid, type( adventureInfo.stages ) )
		return dialogs
	end

	local stageInfo = adventureInfo.stages[ stage ]
	if type( stageInfo ) ~= "table" then
		sys.log( "UI:GetAdventureDialogsForEvent()[ERROR]: invalid type of _G.Adventures[%d].stages[%d]; \"table\" expected, got \"%s\"", atid, stage, type( stageInfo ) )
		return dialogs
	end

	if type( stageInfo.info_events ) ~= "table" then
		sys.log( "UI:GetAdventureDialogsForEvent()[ERROR]: invalid type of _G.Adventures[%d].stages[%d].info_events; \"table\" expected, got \"%s\"", atid, stage, type( stageInfo.info_events ) )
		return dialogs
	end

	local eventInfo = stageInfo.info_events[ eventIdx ]
	if type( eventInfo ) ~= "table" then
		sys.log( "UI:GetAdventureDialogsForEvent()[ERROR]: invalid type of _G.Adventures[%d].stages[%d].info_events[%d]; \"table\" expected, got \"%s\"", atid, stage, eventIdx, type( eventInfo ) )
		return dialogs
	end

	if type( eventInfo.dialogs ) ~= "table" then
		sys.log( "UI:GetAdventureDialogsForEvent()[ERROR]: invalid type of _G.Adventures[%d].stages[%d].info_events[%d].dialogs; \"table\" expected, got \"%s\"", atid, stage, eventIdx, type( eventInfo.dialogs ) )
		return dialogs
	end

	dialogs = eventInfo.dialogs
	return dialogs

end


--
function UI:GetAdventureNumDialogsForEvent( atid, stage, eventIdx )

	local dialogs = UI:GetAdventureDialogsForEvent( atid, stage, eventIdx )
	return #dialogs

end


--
function UI:GetAdventureDialogInfo( atid, stage, eventIdx, dialogIdx )

	local dialogInfo = nil

	if type( dialogIdx ) ~= "number" then
		sys.log( "UI:GetAdventureDialogInfo()[ERROR]: invalid type of the 3-rd parameter (\"dialogIdx\"); \"number\" expected, got \"%s\"", type( dialogIdx ) )
		return dialogInfo
	end

	local dialogs = UI:GetAdventureDialogsForEvent( atid, stage, eventIdx )

	local dlgInfo = dialogs[ dialogIdx ]
	if type( dlgInfo ) ~= "table" then
		sys.log( "UI:GetAdventureDialogInfo()[ERROR]: invalid type of _G.Adventures[%d].stages[%d].info_events[%d].dialogs[%d]; \"table\" expected, got \"%s\"", atid, stage, eventIdx, dialogIdx, type( dlgInfo ) )
		return dialogInfo
	end

	dialogInfo = dlgInfo
	return dialogInfo

end